GameEvents = {
    handlers = {},
}

function GameEvents.On(eventName, handler)
    if GameEvents.handlers[eventName] == nil then
        GameEvents.handlers[eventName] = {}
    end
    table.insert(GameEvents.handlers[eventName], handler)
end

function GameEvents.Emit(eventName, data)
    local handlers = GameEvents.handlers[eventName]
    if handlers == nil then return end
    for _, handler in ipairs(handlers) do
        handler(data)
    end
end

