function NormalizeSelectedClassId(classId)
    if type(classId) == "string" and CLASS_DEFS[classId] ~= nil then
        return classId
    end
    return "warrior"
end

function GetSelectedClassId()
    local runState = playerData.roguelikeRunState
    local runClassId = runState and runState.classId
    if type(runClassId) == "string" and CLASS_DEFS[runClassId] ~= nil then
        return runClassId
    end

    playerData.settings = playerData.settings or {}
    return NormalizeSelectedClassId(playerData.settings.selectedClassId)
end

function GetSelectedClassDef()
    return CLASS_DEFS[GetSelectedClassId()]
end

function SetSelectedClassId(classId)
    if SelectCurrentRunClass == nil then return false end
    return SelectCurrentRunClass(classId)
end

function ApplySelectedClassBonuses(stats)
    local classId = GetSelectedClassId()
    local classDef = CLASS_DEFS[classId]
    stats.selectedClassId = classId
    stats.selectedClassName = classDef.name
    for stat, value in pairs(classDef.bonuses or {}) do
        stats[stat] = (stats[stat] or 0) + value
    end
end

