        name = "集火协议",
        summary = "三个分身集中攻击同一高威胁目标，伤害96%",
    },
}

function NormalizeCloneProtocolsData(value)
    local selectedId = nil
    if type(value) == "string" then
        selectedId = value
    elseif type(value) == "table" then
        local selected = value.selected
        if type(selected) == "table" then
            for index = 1, 3 do
                local candidate = selected[index]
                if CLONE_PROTOCOL_DEFS[candidate] ~= nil then
                    selectedId = candidate
                    break
                end
            end
        end
        if selectedId == nil and CLONE_PROTOCOL_DEFS[value.selectedId] ~= nil then
            selectedId = value.selectedId
        end
    end
    if CLONE_PROTOCOL_DEFS[selectedId] == nil then
        selectedId = "balanced"
    end
    return {
        version = 1,
        independentEnabled = false,
        selected = { selectedId, selectedId, selectedId },
    }
end

function GetCloneProtocolsSaveSignature(value)
    local normalized = NormalizeCloneProtocolsData(value)
    return table.concat({
        tostring(normalized.version or 1),
        normalized.independentEnabled == true and "1" or "0",
        tostring(normalized.selected[1] or "balanced"),
        tostring(normalized.selected[2] or "balanced"),
        tostring(normalized.selected[3] or "balanced"),
    }, ":")
end

function NormalizeCloneProtocols()
    local before = GetCloneProtocolsSaveSignature(playerData.cloneProtocols)
    local normalized = NormalizeCloneProtocolsData(playerData.cloneProtocols)
    playerData.cloneProtocols = normalized
    if before ~= GetCloneProtocolsSaveSignature(normalized) then
        saveDirty = true
    end
    return normalized
end

function GetCloneProtocolId(index)
    local protocols = NormalizeCloneProtocols()
    index = math.max(1, math.min(3, math.floor(index or 1)))
    return protocols.selected[index] or "balanced"
end

function GetCloneProtocolDef(index)
    return CLONE_PROTOCOL_DEFS[GetCloneProtocolId(index)]
        or CLONE_PROTOCOL_DEFS.balanced
end

function SetUnifiedCloneProtocol(protocolId)
    if CLONE_PROTOCOL_DEFS[protocolId] == nil then
        return false
    end
    local protocols = NormalizeCloneProtocols()
    local changed = false
    for index = 1, 3 do
        if protocols.selected[index] ~= protocolId then
            protocols.selected[index] = protocolId
            changed = true
        end
    end
    protocols.independentEnabled = false
    if changed then
        saveDirty = true
    end
    return true
end

function NormalizeSkillSynergyData(value)
    local selected = { [1] = "", [2] = "" }
    local raw = type(value) == "table" and (value.selectedByLoadout or value.selected) or nil
    for index = 1, 2 do
        local candidate = type(raw) == "table" and (raw[index] or raw[tostring(index)]) or ""
        if SKILL_SYNERGY_DEFS and SKILL_SYNERGY_DEFS[candidate] ~= nil then
            selected[index] = candidate
        end
    end
    return { version = 1, selectedByLoadout = selected }
end

function MergeSkillSynergyData(currentValue, incomingValue)
    if type(incomingValue) == "table" then return NormalizeSkillSynergyData(incomingValue) end
    return NormalizeSkillSynergyData(currentValue)
end

playerData.cloneProtocols = NormalizeCloneProtocolsData(playerData.cloneProtocols)
playerData.skillSynergy = NormalizeSkillSynergyData(playerData.skillSynergy)

function GetSkillSynergySaveSignature(value)
    local normalized = NormalizeSkillSynergyData(value)
    return table.concat({
        tostring(normalized.version or 1),
        tostring(normalized.selectedByLoadout[1] or ""),
        tostring(normalized.selectedByLoadout[2] or ""),
    }, ":")
end

function AddGold(amount)
    amount = math.max(0, math.floor(amount or 0))
    if amount <= 0 then return 0 end
    playerData.gold = math.max(0, math.floor(playerData.gold or 0)) + amount
    playerData.totalGoldEarned = math.max(0, math.floor(playerData.totalGoldEarned or 0)) + amount
    return amount
end

function CreateOfflineClimbState()
    return {
        version = OFFLINE_CLIMB_VERSION,
        active = false,
        runId = "",
        startedAt = 0,
        startFloor = 1,
        simulatedFloor = 1,
        targetFloor = 1,
        carriedSeconds = 0,
        updatedAt = 0,
        status = "idle",
        rewardClaimed = false,
        settlementVersion = 0,
        failedReason = nil,
        pendingReward = nil,
    }
end

function NormalizeOfflineClimbState(value)
    local state = type(value) == "table" and value or CreateOfflineClimbState()
    local loadedVersion = math.max(
        0,
        math.floor(tonumber(state.version) or 0)
    )
    state.active = state.active == true
    state.runId = tostring(state.runId or "")
    state.startedAt = math.max(0, math.floor(tonumber(state.startedAt) or 0))
    state.startFloor = math.max(1, math.floor(tonumber(state.startFloor) or 1))
    state.simulatedFloor = math.max(0, math.floor(tonumber(state.simulatedFloor) or 0))
    if loadedVersion < 2 and state.simulatedFloor < state.startFloor then
        state.simulatedFloor = state.startFloor
    end
    state.simulatedFloor = math.max(state.startFloor, state.simulatedFloor)
    state.targetFloor = math.max(state.startFloor, math.floor(tonumber(state.targetFloor) or state.startFloor))
    state.carriedSeconds = math.max(
        0,
        math.min(
            OFFLINE_CLIMB_INTERVAL_SECONDS - 1,
            math.floor(tonumber(state.carriedSeconds) or 0)
        )
    )
    state.updatedAt = math.max(
        0,
        math.floor(tonumber(state.updatedAt) or 0)
    )
    state.status = tostring(state.status or "idle")
    if state.status ~= "idle" and state.status ~= "running"
        and state.status ~= "completed" and state.status ~= "failed" then
        state.status = state.active and "running" or "idle"
    end
    state.rewardClaimed = state.rewardClaimed == true
    state.settlementVersion = math.max(0, math.floor(tonumber(state.settlementVersion) or 0))
    state.failedReason = state.failedReason ~= nil and tostring(state.failedReason) or nil
    local reward = tonumber(state.pendingReward)
    state.pendingReward = reward ~= nil and math.max(0, math.floor(reward)) or nil
    if not state.active and state.status == "running" then
        state.status = "idle"
    end
    state.version = OFFLINE_CLIMB_VERSION
    return state
end

playerData.offlineClimbState = NormalizeOfflineClimbState(playerData.offlineClimbState)

function NormalizeCloneUpgradeLevels()
    local levels = playerData.cloneUpgradeLevels
    local shouldMigrateLegacy = type(levels) ~= "table"
    if shouldMigrateLegacy then
        levels = { math.max(0, math.floor(playerData.cloneUpgradeLevel or 0)), 0, 0 }
    end
    playerData.cloneUpgradeLevels = levels
    local maxLevel = CONFIG.CloneMaxUpgradeLevel or 100
    local changed = shouldMigrateLegacy
    for index = 1, 3 do
        local level = math.max(0, math.min(maxLevel, math.floor(levels[index] or 0)))
        if levels[index] ~= level then
            levels[index] = level
            changed = true
        end
    end
    for index = #levels, 4, -1 do
        levels[index] = nil
        changed = true
    end
    playerData.cloneUpgradeLevel = levels[1] or 0
    if changed then
        saveDirty = true
    end
end

function GetCloneUpgradeLevel(index)
    NormalizeCloneUpgradeLevels()
    index = math.max(1, math.min(3, math.floor(index or 1)))
    return playerData.cloneUpgradeLevels[index] or 0
end

function SetCloneUpgradeLevel(index, level)
    NormalizeCloneUpgradeLevels()
    index = math.max(1, math.min(3, math.floor(index or 1)))
    level = math.max(0, math.min(CONFIG.CloneMaxUpgradeLevel or 100, math.floor(level or 0)))
    playerData.cloneUpgradeLevels[index] = level
    playerData.cloneUpgradeLevel = playerData.cloneUpgradeLevels[1] or 0
    saveDirty = true
end

function GetCloneAttackCountInheritPercent(index)
    local level = GetCloneUpgradeLevel(index or 1)
    local steps = math.floor(level / 10)
    return math.min(100, steps * 10)
end

function GetCloneInheritedAttackCount(index)
    local inheritPercent = GetCloneAttackCountInheritPercent(index or 1)
    if inheritPercent <= 0 then
        return 1
    end
    return math.max(1, math.floor(GetHeroBaseAttackCount() * inheritPercent / 100))
end

function GetRebirthUpgradeTierValue(level)
    level = math.max(1, math.floor(level or 1))
    local tierSize = math.max(1, CONFIG.RebirthUpgradeTierSize or 10)
    local tierIndex = math.floor((level - 1) / tierSize) + 1
    local tiers = CONFIG.RebirthUpgradeTiers or {}
    return tiers[math.min(tierIndex, #tiers)] or {
        attack = CONFIG.RebirthAttackPerUpgrade or 5,
        hp = CONFIG.RebirthBaseHpPerUpgrade or 20,
    }
end

function GetRebirthUpgradeBonus(count)
    count = math.max(0, math.floor(count or 0))
    local attack = 0
    local hp = 0
    for level = 1, count do
        local tier = GetRebirthUpgradeTierValue(level)
        attack = attack + (tier.attack or 0)
        hp = hp + (tier.hp or 0)
    end
    return attack, hp
end

function GetNextRebirthUpgradeBonus()
    return GetRebirthUpgradeTierValue((playerData.rebirthUpgradeCount or 0) + 1)
end

function ApplyRebirthBonuses()
    local upgradeCount = math.max(0, math.floor(tonumber(playerData.rebirthUpgradeCount) or 0))
    local attackBonus, hpBonus = GetRebirthUpgradeBonus(upgradeCount)
    CONFIG.AttackDamage = BASE_ATTACK_DAMAGE + attackBonus
    CONFIG.BaseMaxHP = BASE_MAX_HP + hpBonus
    print(
        "[RebirthUpgrade] 永久属性重算",
        "次数:", upgradeCount,
        "攻击:", BASE_ATTACK_DAMAGE, "+", attackBonus, "=", CONFIG.AttackDamage,
        "血量:", BASE_MAX_HP, "+", hpBonus, "=", CONFIG.BaseMaxHP
    )
end

function NormalizeRebirthStoneSystem()
    playerData.rebirthStone = math.max(0, math.floor(playerData.rebirthStone or 0))
    playerData.rebirthStoneBestClaimFloor = math.max(0, math.floor(playerData.rebirthStoneBestClaimFloor or 0))
    playerData.skipLevelUpgradeLevel = math.max(0, math.min(CONFIG.SkipLevelMaxUpgradeLevel or 10, math.floor(playerData.skipLevelUpgradeLevel or 0)))
    if playerData.skipLevelEnabled == nil then playerData.skipLevelEnabled = true end
    playerData.skipLevelEnabled = playerData.skipLevelEnabled == true
    playerData.skillDamageUpgradeLevel = math.max(0, math.min(CONFIG.SkillDamageMaxUpgradeLevel or 10, math.floor(playerData.skillDamageUpgradeLevel or 0)))
    playerData.cloneCritUpgradeLevel = math.max(0, math.min(CONFIG.CloneCritMaxUpgradeLevel or 20, math.floor(playerData.cloneCritUpgradeLevel or 0)))
    playerData.rebirthRunStartFloor = math.max(1, math.floor(playerData.rebirthRunStartFloor or playerData.currentFloor or 1))
    playerData.rebirthRunCompletedFloors = math.max(0, math.floor(playerData.rebirthRunCompletedFloors or 0))
    playerData.rebirthRunSkippedFloors = math.max(0, math.floor(playerData.rebirthRunSkippedFloors or 0))
    local completedFloors = math.max(0, math.floor((playerData.bestFloor or 1) - 1))
    local claimFloor = math.min(playerData.rebirthStoneBestClaimFloor or 0, completedFloors)
    local backfillReward = 0
    if completedFloors > claimFloor then
        for floor = claimFloor + 1, completedFloors do
            backfillReward = backfillReward + GetRebirthStoneRewardForFloor(floor)
        end
        backfillReward = math.floor(backfillReward * math.max(0, CONFIG.RebirthStoneFirstClearRewardRate or 1.0))
        playerData.rebirthStone = math.max(0, math.floor(playerData.rebirthStone or 0)) + backfillReward
        playerData.rebirthStoneBestClaimFloor = completedFloors
        print("[RebirthStone] 历史首通转生石补发:", backfillReward, "补发楼层:", claimFloor + 1, "-", completedFloors, "当前:", playerData.rebirthStone)
    end
end

-- 指定强化等级（已强化次数）对应的单次价格；重置返还按同一公式逐级累加，保证与买入消耗一致
function GetRebirthStoneUpgradeCostForLevel(level)
    level = math.max(0, math.floor(tonumber(level) or 0))
    local tiers = CONFIG.RebirthStoneCostTiers or {}
    local matchedTier = nil
    for _, tier in ipairs(tiers) do
        if level >= math.max(0, math.floor(tier.minLevel or 0)) then
            matchedTier = tier
        end
    end
    if matchedTier ~= nil then
        local minLevel = math.max(0, math.floor(matchedTier.minLevel or 0))
        local baseCost = math.max(0, math.floor(matchedTier.baseCost or 0))
        local growth = math.max(0, math.floor(matchedTier.growth or 0))
        return baseCost + (level - minLevel) * growth
    end
    return (CONFIG.RebirthStoneCostBase or 5) + level * (CONFIG.RebirthStoneCostGrowth or 2)
end

function GetRebirthStoneUpgradeCost()
    return GetRebirthStoneUpgradeCostForLevel(playerData.rebirthUpgradeCount or 0)
end

function GetSkipLevelUpgradeLevel()
    NormalizeRebirthStoneSystem()
    return math.max(0, math.min(CONFIG.SkipLevelMaxUpgradeLevel or 10, math.floor(playerData.skipLevelUpgradeLevel or 0)))
end

function IsSkipLevelEnabled()
    NormalizeRebirthStoneSystem()
    return playerData.skipLevelEnabled == true
end

function SetSkipLevelEnabled(enabled)
    NormalizeRebirthStoneSystem()
    playerData.skipLevelEnabled = enabled == true
end

function GetSkipLevelUpgradeCost()
    local level = GetSkipLevelUpgradeLevel()
    local costs = CONFIG.SkipLevelUpgradeCosts or {}
    if level >= (CONFIG.SkipLevelMaxUpgradeLevel or 10) then
        return nil
    end
    return costs[level + 1]
end

function GetSkipLevelChance(level)
    level = math.max(0, math.min(CONFIG.SkipLevelMaxUpgradeLevel or 10, math.floor(level or GetSkipLevelUpgradeLevel())))
    return level * (CONFIG.SkipLevelChancePerLevel or 0.02)
end

function GetSkipTwoLevelChance(level)
    level = math.max(0, math.min(CONFIG.SkipLevelMaxUpgradeLevel or 10, math.floor(level or GetSkipLevelUpgradeLevel())))
    return level * (CONFIG.SkipTwoLevelChancePerLevel or 0.01)
end

function GetSkipLevelChancePercent(level)
    return math.floor(GetSkipLevelChance(level) * 100 + 0.5)
end

function GetSkipTwoLevelChancePercent(level)
    return math.floor(GetSkipTwoLevelChance(level) * 100 + 0.5)
end

function RollSkipFloorsOnFloorClear()
    if not IsSkipLevelEnabled() then return 0 end
    local skipOneChance = GetSkipLevelChance()
    local skipTwoChance = GetSkipTwoLevelChance()
    local totalChance = skipOneChance + skipTwoChance
    if totalChance <= 0 then return 0 end
    local roll = math.random()
    if roll < skipTwoChance then
        return 2
    end
    if roll < totalChance then
        return 1
    end
    return 0
end

function RollSkipLevelOnFloorClear()
    return RollSkipFloorsOnFloorClear() > 0
end

function GetSkillDamageUpgradeLevel()
    NormalizeRebirthStoneSystem()
    return math.max(0, math.min(CONFIG.SkillDamageMaxUpgradeLevel or 10, math.floor(playerData.skillDamageUpgradeLevel or 0)))
end

function GetSkillDamageUpgradeCost()
    local level = GetSkillDamageUpgradeLevel()
    local costs = CONFIG.SkillDamageUpgradeCosts or {}
    if level >= (CONFIG.SkillDamageMaxUpgradeLevel or 10) then
        return nil
    end
    return costs[level + 1]
end

function GetSkillDamagePermanentBonus()
    local level = GetSkillDamageUpgradeLevel()
    return level * (CONFIG.SkillDamagePercentPerLevel or 5)
end

function GetSkillDamagePercent(level)
    level = math.max(0, math.min(CONFIG.SkillDamageMaxUpgradeLevel or 10, math.floor(level or GetSkillDamageUpgradeLevel())))
    return level * (CONFIG.SkillDamagePercentPerLevel or 5)
end

function GetCloneCritUpgradeLevel()
    NormalizeRebirthStoneSystem()
    return math.max(0, math.min(CONFIG.CloneCritMaxUpgradeLevel or 20, math.floor(playerData.cloneCritUpgradeLevel or 0)))
end

function GetCloneCritUpgradeCost()
    local level = GetCloneCritUpgradeLevel()
    local costs = CONFIG.CloneCritUpgradeCosts or {}
    if level >= (CONFIG.CloneCritMaxUpgradeLevel or 20) then
        return nil
    end
    return costs[level + 1]
end

function GetCloneCritInheritPercent(level)
    level = math.max(0, math.min(CONFIG.CloneCritMaxUpgradeLevel or 20, math.floor(level or GetCloneCritUpgradeLevel())))
    return level * (CONFIG.CloneCritInheritPercentPerLevel or 1)
end

function GetCloneEffectiveCritStats(floor)
    local inheritPercent = GetCloneCritInheritPercent() / 100
    local stats = GetBattleEquipmentStats()
    local heroCritRate = GetEffectiveCritRate(stats)
    local targetFloor = floor or runFloor or playerData.currentFloor or 1
    local heroCritDamage = GetEffectiveCritDamageAgainstMonster(stats, { floor = targetFloor })
    return heroCritRate * inheritPercent, heroCritDamage * inheritPercent
end

-- ============================================================================
-- 永久强化重置（看广告返还全部转生石，重新加点）
-- ============================================================================

-- 成本表按等级顺序排列（索引 1 = 0→1 级），累计到 level 级的总消耗
local function SumRebirthUpgradeCosts(costs, level)
    level = math.max(0, math.floor(tonumber(level) or 0))
    local total = 0
    for i = 1, level do
        total = total + math.max(0, math.floor(tonumber(costs[i]) or 0))
    end
    return total
end

function HasRebirthUpgradesToReset()
    NormalizeRebirthStoneSystem()
    if math.max(0, math.floor(tonumber(playerData.rebirthUpgradeCount) or 0)) > 0 then return true end
    if GetSkipLevelUpgradeLevel() > 0 then return true end
    if GetSkillDamageUpgradeLevel() > 0 then return true end
    if GetCloneCritUpgradeLevel() > 0 then return true end
    return false
end

-- 汇总当前四条永久强化线已投入的转生石，重置时等额返还
function GetRebirthUpgradeResetRefund()
    NormalizeRebirthStoneSystem()
    local attackHpLevel = math.max(0, math.floor(tonumber(playerData.rebirthUpgradeCount) or 0))
    local attackHpRefund = 0
    for level = 0, attackHpLevel - 1 do
        attackHpRefund = attackHpRefund + GetRebirthStoneUpgradeCostForLevel(level)
    end
    local skipLevel = GetSkipLevelUpgradeLevel()
    local skillDamageLevel = GetSkillDamageUpgradeLevel()
    local cloneCritLevel = GetCloneCritUpgradeLevel()
    local refund = {
        attackHp = attackHpRefund,
        attackHpLevel = attackHpLevel,
        skip = SumRebirthUpgradeCosts(CONFIG.SkipLevelUpgradeCosts or {}, skipLevel),
        skipLevel = skipLevel,
        skillDamage = SumRebirthUpgradeCosts(CONFIG.SkillDamageUpgradeCosts or {}, skillDamageLevel),
        skillDamageLevel = skillDamageLevel,
        cloneCrit = SumRebirthUpgradeCosts(CONFIG.CloneCritUpgradeCosts or {}, cloneCritLevel),
        cloneCritLevel = cloneCritLevel,
        total = 0,
    }
    refund.total = refund.attackHp + refund.skip + refund.skillDamage + refund.cloneCrit
    return refund
end

-- 执行重置：等级归零 + 返还转生石 + 重置世代号 +1（供云存档仲裁识别“合法降级”）
function PerformRebirthUpgradeReset()
    if not HasRebirthUpgradesToReset() then
        print("[RebirthReset] 没有可重置的强化，忽略本次重置")
        return 0
    end
    local refund = GetRebirthUpgradeResetRefund()
    local stoneBefore = math.max(0, math.floor(playerData.rebirthStone or 0))
    playerData.rebirthUpgradeCount = 0
    playerData.skipLevelUpgradeLevel = 0
    playerData.skillDamageUpgradeLevel = 0
    playerData.cloneCritUpgradeLevel = 0
    playerData.rebirthStone = stoneBefore + refund.total
    playerData.rebirthUpgradeResetId = math.max(0, math.floor(tonumber(playerData.rebirthUpgradeResetId) or 0)) + 1
    ApplyRebirthBonuses()
    saveDirty = true
    SaveCloudData(true)
    print(
        "[RebirthReset] 永久强化已重置",
        "返还:", refund.total,
        "(攻血", refund.attackHp, "跳层", refund.skip, "技能", refund.skillDamage, "分身", refund.cloneCrit, ")",
        "转生石:", stoneBefore, "->", playerData.rebirthStone,
        "重置世代:", playerData.rebirthUpgradeResetId
    )
    return refund.total
end

function GetRebirthStoneRewardForFloor(floor)
    floor = math.max(1, math.floor(floor or 1))
    local step = math.max(1, CONFIG.RebirthStoneFloorStep or 10)
    return math.max(1, math.floor((floor - 1) / step) + 1)
end

function CalculateRebirthStoneReward(reachedFloor)
    NormalizeRebirthStoneSystem()
    reachedFloor = math.max(1, math.floor(reachedFloor or 1))
    local claimedFloor = math.max(0, math.floor(playerData.rebirthStoneBestClaimFloor or 0))
    if reachedFloor <= claimedFloor then
        return 0, claimedFloor, claimedFloor
    end
    local rawReward = 0
    for floor = claimedFloor + 1, reachedFloor do
        rawReward = rawReward + GetRebirthStoneRewardForFloor(floor)
    end
    local rate = math.max(0, CONFIG.RebirthStoneFirstClearRewardRate or 1.0)
    return math.floor(rawReward * rate), claimedFloor, reachedFloor
end

function GetRepeatRebirthStoneMaxReward(reachedFloor)
    reachedFloor = math.max(1, math.floor(reachedFloor or 1))
    local baseMax = math.max(0, CONFIG.RebirthStoneRepeatMaxReward or 10)
    local growthStep = math.max(1, CONFIG.RebirthStoneRepeatMaxRewardGrowthFloorStep or 100)
    local growth = math.max(0, CONFIG.RebirthStoneRepeatMaxRewardGrowth or 5)
    local cap = math.max(baseMax, CONFIG.RebirthStoneRepeatMaxRewardCap or 30)
    local dynamicMax = baseMax + math.floor(reachedFloor / growthStep) * growth
    return math.min(cap, dynamicMax)
end

function GetRepeatRebirthStoneSegmentReward(segmentIndex, tierOffset)
    segmentIndex = math.max(1, math.floor(segmentIndex or 1))
    tierOffset = math.max(0, math.floor(tierOffset or 0))
    local tier = math.floor((segmentIndex - 1) / 3) + tierOffset
    local maxSegmentReward = math.max(1, CONFIG.RebirthStoneRepeatSegmentMaxReward or 64)
    return math.min(maxSegmentReward, 2 * (2 ^ tier))
end

function GetRebirthStoneTierOffset(startFloor)
    startFloor = math.max(1, math.floor(startFloor or 1))
    return math.floor((startFloor - 1) / 50)
end

function CalculateChallengeRebirthStoneReward(reachedFloor, startFloor, skippedFloors, minimumSegments)
    reachedFloor = math.max(1, math.floor(reachedFloor or 1))
    startFloor = math.max(1, math.floor(startFloor or playerData.rebirthRunStartFloor or reachedFloor))
    skippedFloors = math.max(0, math.floor(skippedFloors or playerData.rebirthRunSkippedFloors or 0))
    minimumSegments = math.max(0, math.floor(tonumber(minimumSegments) or 0))
    local brushedFloors = math.max(0, reachedFloor - startFloor + 1 - skippedFloors)
    local repeatFloorStep = math.max(
        1,
        math.floor(CONFIG.RebirthStoneRepeatFloorStep or 10)
    )
    -- 保底段：无尽挑战死亡等场景，刷层不足 8 层（如 601~607 层死亡）也至少按一段结算，避免转生石到账为 0
    local fullSegments = math.max(minimumSegments, math.floor(brushedFloors / repeatFloorStep))
    local tierOffset = GetRebirthStoneTierOffset(startFloor)
    local reward = 0
    for segmentIndex = 1, fullSegments do
        reward = reward + GetRepeatRebirthStoneSegmentReward(segmentIndex, tierOffset)
    end
    return reward, brushedFloors, fullSegments, tierOffset
end

function CalculateRepeatRebirthStoneReward(startFloor, reachedFloor)
    return CalculateChallengeRebirthStoneReward(reachedFloor, startFloor)
end

function AwardRebirthStoneOnDeath(reachedFloor, startFloor, minimumSegments)
    reachedFloor = math.max(1, math.floor(reachedFloor or 1))
    startFloor = math.max(1, math.floor(startFloor or playerData.rebirthRunStartFloor or reachedFloor))
    local skippedFloors = math.max(0, math.floor(playerData.rebirthRunSkippedFloors or 0))
    minimumSegments = math.max(0, math.floor(tonumber(minimumSegments) or 0))
    local firstClearReward, oldClaimFloor, newClaimFloor = CalculateRebirthStoneReward(reachedFloor)
    local rawChallengeReward, countedFloors, rewardSegments, tierOffset = CalculateChallengeRebirthStoneReward(reachedFloor, startFloor, skippedFloors, minimumSegments)
    local challengeRewardCap = math.max(0, CONFIG.RebirthStoneChallengeRunMaxReward or 5000)
    local challengeReward = math.min(rawChallengeReward, challengeRewardCap)
    local requestedReward = firstClearReward + challengeReward
    local awardDaily = _G.AwardDailyRebirthStone
    local reward = type(awardDaily) == "function"
        and awardDaily(requestedReward, "死亡结算")
        or 0
    if newClaimFloor > oldClaimFloor then
        playerData.rebirthStoneBestClaimFloor = newClaimFloor
    end
    playerData.rebirthRunStartFloor = 1
    playerData.rebirthRunCompletedFloors = 0
    playerData.rebirthRunSkippedFloors = 0
    local perSegmentFirst = GetRepeatRebirthStoneSegmentReward(1, tierOffset)
    if newClaimFloor > oldClaimFloor then
        print("[RebirthStone] 死亡重生结算首通转生石:", firstClearReward, "领取楼层:", oldClaimFloor + 1, "-", newClaimFloor, "反复刷奖励:", challengeReward, "申请合计:", requestedReward, "实际到账:", reward, "今日已获:", playerData.dailyRebirthStoneEarned, "/", GetDailyRebirthStoneLimit(), "反复刷原始奖励:", rawChallengeReward, "单局上限:", challengeRewardCap, "起始层:", startFloor, "档位偏移:", tierOffset, "每段首:", perSegmentFirst, "刷层:", countedFloors, "跳过层:", skippedFloors, "完整奖励段:", rewardSegments, "当前:", playerData.rebirthStone)
    else
        print("[RebirthStone] 死亡重生结算反复刷转生石:", challengeReward, "申请合计:", requestedReward, "实际到账:", reward, "今日已获:", playerData.dailyRebirthStoneEarned, "/", GetDailyRebirthStoneLimit(), "反复刷原始奖励:", rawChallengeReward, "单局上限:", challengeRewardCap, "起始层:", startFloor, "档位偏移:", tierOffset, "每段首:", perSegmentFirst, "死亡层:", reachedFloor, "刷层:", countedFloors, "跳过层:", skippedFloors, "完整奖励段:", rewardSegments, "已领取最高楼层:", oldClaimFloor, "当前:", playerData.rebirthStone)
    end
    return reward
end

