function NormalizeProgressionData()
    local legacyCleared = math.max(0, math.floor(tonumber(playerData.bestFloor) or 0) - 1)
    playerData.normalHighestClearedFloor = math.max(
        0,
        math.min(600, math.max(
            math.floor(tonumber(playerData.normalHighestClearedFloor) or 0),
            legacyCleared
        ))
    )
    playerData.rebirthUnlocked = playerData.rebirthUnlocked == true
        or playerData.normalHighestClearedFloor >= 600
    playerData.rebirthRunActive = playerData.rebirthRunActive == true
    playerData.endlessBestFloor = math.max(0, math.floor(tonumber(playerData.endlessBestFloor) or 0))
    local state = type(playerData.endlessRunState) == "table" and playerData.endlessRunState or {}
    playerData.endlessRunState = {
        version = 1,
        active = state.active == true,
        runId = math.max(0, math.floor(tonumber(state.runId) or 0)),
        currentFloor = math.max(601, math.floor(tonumber(state.currentFloor) or 601)),
        penaltyState = state.penaltyState == "pending" and "pending"
            or (state.penaltyState == "processing" and "processing" or "resolved"),
        pausePending = state.pausePending == true,
    }
    return playerData.normalHighestClearedFloor
end

function GetNormalHighestClearedFloor()
    return NormalizeProgressionData()
end

function IsEndlessUnlocked()
    return GetNormalHighestClearedFloor() >= 600
end

function GetLeaderboardProgressScore()
    NormalizeProgressionData()
    if playerData.endlessBestFloor >= 600 then
        return 1000000 + playerData.endlessBestFloor
    end
    return playerData.normalHighestClearedFloor
end

function NormalizeDailyEquipmentUpgradeAdQuota()
    local today = GetCurrentCstDayKey and GetCurrentCstDayKey() or os.date("%Y-%m-%d")
    if tostring(playerData.dailyEquipmentUpgradeAdClaimDayKey or "") ~= today then
        playerData.dailyEquipmentUpgradeAdClaimDayKey = today
        playerData.dailyEquipmentUpgradeAdClaimCount = 0
        saveDirty = true
        print("[EquipmentUpgradeAd] 北京时间新的一天，强化保护次数已重置")
    end
    playerData.dailyEquipmentUpgradeAdClaimCount = math.max(0, math.min(
        DAILY_EQUIPMENT_UPGRADE_AD_MAX_CLAIMS,
        math.floor(tonumber(playerData.dailyEquipmentUpgradeAdClaimCount) or 0)))
end

function GetDailyEquipmentUpgradeAdRemaining()
    NormalizeDailyEquipmentUpgradeAdQuota()
    return math.max(0, DAILY_EQUIPMENT_UPGRADE_AD_MAX_CLAIMS
        - playerData.dailyEquipmentUpgradeAdClaimCount)
end

function ConsumeDailyEquipmentUpgradeAdClaim()
    NormalizeDailyEquipmentUpgradeAdQuota()
    if GetDailyEquipmentUpgradeAdRemaining() <= 0 then return false end
    if ConsumeDailyRewardAdClaim == nil or not ConsumeDailyRewardAdClaim() then return false end
    playerData.dailyEquipmentUpgradeAdClaimCount =
        playerData.dailyEquipmentUpgradeAdClaimCount + 1
    saveDirty = true
    print("[EquipmentUpgradeAd] 保护次数已消耗:",
        playerData.dailyEquipmentUpgradeAdClaimCount, "/",
        DAILY_EQUIPMENT_UPGRADE_AD_MAX_CLAIMS)
    return true
end

function GetDailySocketPuncherAdClaimCount()
    NormalizeDailySocketPuncherAdQuota()
    return math.max(0, math.min(
        DAILY_SOCKET_PUNCHER_AD_MAX_CLAIMS,
        math.floor(tonumber(playerData.dailySocketPuncherAdClaimCount) or 0)))
end

function GetDailySocketPuncherAdRemaining()
    return math.max(0, DAILY_SOCKET_PUNCHER_AD_MAX_CLAIMS
        - GetDailySocketPuncherAdClaimCount())
end

function NormalizeDailySocketPuncherAdQuota()
    local today, clockBlocked = UpdateDailySpeedClockState()
    local dayKey = tostring(playerData.dailySocketPuncherAdClaimDayKey or "")
    if not clockBlocked and dayKey ~= today then
        playerData.dailySocketPuncherAdClaimDayKey = today
        playerData.dailySocketPuncherAdClaimCount = 0
        saveDirty = true
        print("[SocketPuncherAd] 北京时间新的一天，打孔器广告次数已重置")
    elseif clockBlocked then
        print("[SocketPuncherAd] 时间异常期间保留当前广告次数，日期:", dayKey, "当前系统日期:", today)
    end
    playerData.dailySocketPuncherAdClaimCount = math.max(0, math.min(
        DAILY_SOCKET_PUNCHER_AD_MAX_CLAIMS,
        math.floor(tonumber(playerData.dailySocketPuncherAdClaimCount) or 0)))
end

function CanClaimDailySocketPuncherAd()
    return GetDailySocketPuncherAdRemaining() > 0
end

function ConsumeDailySocketPuncherAdClaim()
    NormalizeDailySocketPuncherAdQuota()
    if not CanClaimDailySocketPuncherAd() then return false end
    if not CanClaimDailyRewardAd() then return false end

    playerData.dailySocketPuncherAdClaimDayKey = GetCurrentCstDayKey()
    playerData.dailySocketPuncherAdClaimCount =
        playerData.dailySocketPuncherAdClaimCount + 1
    if not ConsumeDailyRewardAdClaim() then
        playerData.dailySocketPuncherAdClaimCount =
            math.max(0, playerData.dailySocketPuncherAdClaimCount - 1)
        return false
    end
    saveDirty = true
    print("[SocketPuncherAd] 打孔器广告次数已消耗:",
        playerData.dailySocketPuncherAdClaimCount, "/",
        DAILY_SOCKET_PUNCHER_AD_MAX_CLAIMS)
    return true
end

function ApplyDailySocketPuncherAdClaimValues(claimCount, dayKey, source)
    local incomingDay = tostring(dayKey or "")
    local incomingCount = math.max(0, math.min(
        DAILY_SOCKET_PUNCHER_AD_MAX_CLAIMS,
        math.floor(tonumber(claimCount) or 0)))
    NormalizeDailySocketPuncherAdQuota()
    local activeDay = tostring(playerData.dailySocketPuncherAdClaimDayKey or "")
    if incomingDay ~= "" and incomingDay == activeDay then
        playerData.dailySocketPuncherAdClaimCount = math.max(
            playerData.dailySocketPuncherAdClaimCount or 0,
            incomingCount)
    end
    print("[SocketPuncherAd] 应用", source or "广告次数数据", "日期:",
        playerData.dailySocketPuncherAdClaimDayKey, "广告次数:",
        playerData.dailySocketPuncherAdClaimCount, "/",
        DAILY_SOCKET_PUNCHER_AD_MAX_CLAIMS)
end

function MergeDailySocketPuncherAdClaimsFromCloud(values, iscores)
    values = values or {}
    iscores = iscores or {}
    NormalizeDailySocketPuncherAdQuota()
    local activeDay = tostring(playerData.dailySocketPuncherAdClaimDayKey or "")
    local bestCount = nil
    local function consider(count, dayKey)
        if count == nil or tostring(dayKey or "") ~= activeDay then return end
        local normalized = math.max(0, math.min(
            DAILY_SOCKET_PUNCHER_AD_MAX_CLAIMS,
            math.floor(tonumber(count) or 0)))
        bestCount = math.max(bestCount or 0, normalized)
    end
    consider(iscores.daily_socket_puncher_ad_claim_count,
        values.daily_socket_puncher_ad_claim_day)
    consider(values.daily_socket_puncher_ad_claim_count,
        values.daily_socket_puncher_ad_claim_day)
    local blob = values.save_blob
    if type(blob) == "table" then
        consider(blob.dailySocketPuncherAdClaimCount,
            blob.dailySocketPuncherAdClaimDayKey)
    end
    if bestCount ~= nil then
        ApplyDailySocketPuncherAdClaimValues(bestCount, activeDay, "云端合并")
    end
end

function GetRewardAdFailureMessage(msg)
    local text = tostring(msg or "")
    if text == "embed manual close" then
        return "需要完整观看广告后才能获得奖励"
    end
    if text == "广告请求未受理" then
        return "广告冷却中或正在加载，本次未扣次数，请稍后再试"
    end
    if text == "广告响应超时" then
        return "广告响应超时，本次未扣次数，请重新点击"
    end
    return "广告暂不可用，本次未扣次数，请稍后重试"
end

-- 广告结果投递缓存：SDK 回调发生在 native 回调栈内（JNI→Lua），此时引擎可能
-- 尚处于回前台的恢复期；在回调栈内同步销毁弹窗并重建整页 UI（如强化保护弹窗
-- 结算后重建装备详情页）在真机上会闪退。缓存起来，下一帧 HandleUpdate 主循环
-- 中再执行，并用 pcall 防护，避免异常打穿 SDK 回调栈。
pendingRewardAdDeliver = nil

function FinishRewardAd(result)
    local success = result ~= nil and result.success == true
    local msg = result and result.msg or "广告暂不可用"

    -- 迟到补发：本流程此前已以“失败”结束（如 30/120 秒响应超时），
    -- 但 SDK 稍后才返回 success，说明玩家确实完整看完了广告。
    -- 此时补投递一次 success，由原回调在发奖前再次做前置校验，
    -- 已发过奖的正常成功流程不会进入这里，因此不会二次发奖。
    if rewardAdFlowEnded then
        if success and rewardAdOnComplete ~= nil then
            print("[RewardAd] 迟到成功回调，补发奖励")
            pendingRewardAdDeliver = {
                onComplete = rewardAdOnComplete,
                success = true,
                msg = msg,
            }
            rewardAdOnComplete = nil
            rewardAdFlowEnded = false
        end
        return
    end

    if rewardAdCompleted then return end
    rewardAdCompleted = true
    rewardAdInFlight = false
    rewardAdDeadline = 0
    rewardAdFlowEnded = false
    local onComplete = rewardAdOnComplete
    rewardAdOnComplete = nil
    if onComplete ~= nil then
        pendingRewardAdDeliver = {
            onComplete = onComplete,
            success = success,
            msg = msg,
        }
    end
end

function DeliverPendingRewardAdResult()
    local deliver = pendingRewardAdDeliver
    if deliver == nil then return end
    pendingRewardAdDeliver = nil
    local ok, err = pcall(deliver.onComplete, deliver.success == true, deliver.msg)
    if not ok then
        print("[RewardAd] 广告回调执行异常:", tostring(err))
    end
end

function ShowRewardAd(onComplete)
    -- 防御：上次请求超时未复位（如 HandleUpdate 未运行）时先复位，避免入口永久卡死
    if rewardAdInFlight and rewardAdDeadline > 0 and os.clock() >= rewardAdDeadline then
        rewardAdFlowEnded = true
        FinishRewardAd({ success = false, msg = "广告响应超时" })
    end
    if rewardAdInFlight then
        if onComplete ~= nil then onComplete(false, "广告正在播放，请稍候") end
        return false
    end
    rewardAdInFlight = true
    rewardAdCompleted = false
    rewardAdFlowEnded = false
    rewardAdOnComplete = onComplete
    rewardAdDeadline = os.clock() + 120
    local callbackFired = false
    local sdkApi = _G.sdk
    if sdkApi == nil or sdkApi.ShowRewardVideoAd == nil then
        FinishRewardAd({ success = false, msg = "广告接口不可用" })
        return false
    end
    print("[RewardAd] 请求播放激励广告")
    local ok, accepted = pcall(function()
        return sdkApi:ShowRewardVideoAd(function(result)
            callbackFired = true
            FinishRewardAd(result)
        end)
    end)
    if not ok then
        -- SDK 调用抛异常时立即复位并结束流程，避免按钮/入口永久卡死
        print("[RewardAd] 广告调用异常:", tostring(accepted))
        FinishRewardAd({ success = false, msg = "广告调用异常" })
        return false
    end
    if accepted == false and not callbackFired then
        FinishRewardAd({ success = false, msg = "广告请求未受理" })
    end
    return accepted ~= false
end

