function GetWeaponFlameTier(level)
    local lv = math.max(0, math.floor(level or 0))
    if lv >= 20 then return 20 end
    if lv >= 15 then return 15 end
    if lv >= 10 then return 10 end
    if lv >= 5 then return 5 end
    return nil
end

function GetWeaponFlamePose(tier)
    return WEAPON_FLAME_POSES[tier] or WEAPON_FLAME_POSES[5]
end

