function GetWeaponVisualIdByName(name)
    if type(name) ~= "string" then return "default" end
    return WEAPON_VISUAL_BY_NAME[name] or "default"
end

function GetWeaponVisualId(item)
    if item == nil then return "default" end
    if type(item.name) == "string" and WEAPON_VISUAL_BY_NAME[item.name] ~= nil then
        return WEAPON_VISUAL_BY_NAME[item.name]
    end
    if type(item.visualId) == "string" and weaponImagePaths[item.visualId] ~= nil then
        return item.visualId
    end
    if type(item.quality) == "string" and weaponImagePaths[item.quality] ~= nil then
        return item.quality
    end
    return "default"
end

function NormalizeWeaponVisual(item)
    if item == nil or item.type ~= "equipment" or item.slot ~= "weapon" then return false end
    local visualId = GetWeaponVisualId(item)
    if item.visualId ~= visualId then
        item.visualId = visualId
        return true
    end
    return false
end

