function GetRandomSkillCooldownSlot()
    local count = 10
    if GetUnlockedSkillSlotCount ~= nil then
        count = math.min(count, GetUnlockedSkillSlotCount())
    end
    count = math.max(1, math.min(10, count))
    return math.random(1, count)
end

function RollEquipmentAffixValue(def, floor)
    local value = 0
    if def.min and def.max then
        value = math.random(def.min, def.max)
    else
        local growth = def.growth or 0
        local growthStep = math.max(1, math.floor(def.growthStep or 10))
        local step = math.floor((math.max(1, floor or 1) - 1) / growthStep)
        value = def.base + step * growth + math.random(-def.variance, def.variance)
    end
    if def.minValue ~= nil then
        value = math.max(def.minValue, value)
    end
    return math.floor(value)
end

function GetEquipmentAffixValueRange(def, floor)
    if def == nil then return nil, nil end
    if def.min ~= nil and def.max ~= nil then
        return math.floor(def.min), math.floor(def.max)
    end
    local growth = def.growth or 0
    local growthStep = math.max(1, math.floor(def.growthStep or 10))
    local step = math.floor((math.max(1, floor or 1) - 1) / growthStep)
    local center = (def.base or 0) + step * growth
    local minValue = center - (def.variance or 0)
    local maxValue = center + (def.variance or 0)
    if def.minValue ~= nil then
        minValue = math.max(def.minValue, minValue)
        maxValue = math.max(def.minValue, maxValue)
    end
    return math.floor(minValue), math.floor(maxValue)
end

function MakeEquipmentRefineRangeDisplay(item, affix)
    if affix == nil or affix.fixed == true then return nil end
    local def = nil
    for _, candidate in ipairs(EQUIPMENT_AFFIX_DEFS or {}) do
        if candidate.id == affix.id then
            def = candidate
            break
        end
    end
    if def == nil then return nil end
    local floor = math.max(1, math.floor(item and item.floor or 1))
    local minValue, maxValue = GetEquipmentAffixValueRange(def, floor)
    if minValue == nil or maxValue == nil then return nil end
    return "装备第" .. tostring(floor) .. "层可洗：" .. tostring(minValue) .. "～"
        .. tostring(maxValue) .. (def.suffix or "")
end

function GetMaxEquipmentAffixValue(def, floor)
    local value = 0
    if def.min ~= nil and def.max ~= nil then
        value = def.max
    else
        local growth = def.growth or 0
        local growthStep = math.max(1, math.floor(def.growthStep or 10))
        local step = math.floor((math.max(1, floor or 1) - 1) / growthStep)
        value = (def.base or 0) + step * growth + (def.variance or 0)
    end
    if def.minValue ~= nil then
        value = math.max(def.minValue, value)
    end
    return math.floor(value)
end

function IsAncientEquipment(item)
    return item ~= nil
        and item.type == "equipment"
        and item.ancient == true
        and (
            item.quality == "blue"
            or item.quality == "purple"
            or item.quality == "orange"
            or item.quality == "red"
        )
end

function NormalizeAncientEquipment(item)
    if item == nil or item.type ~= "equipment" then return false end
    if item.ancient == nil or item.ancient == false then return false end
    if item.quality ~= "blue"
        and item.quality ~= "purple"
        and item.quality ~= "orange"
        and item.quality ~= "red" then
        item.ancient = nil
        return true
    end
    local changed = false
    if item.ancient ~= true then
        item.ancient = true
        changed = true
    end
    return changed
end

function GetEquipmentDisplayName(item)
    local name = item and item.name or "未知装备"
    local ancientName = IsAncientEquipment(item)
        and ("太古·" .. name)
        or name
    local setId = item and item.resonanceSetId or nil
    local setDef = (EQUIPMENT_RESONANCE_DEFS or {})[setId]
    if setDef == nil then return ancientName end
    local shortName = setDef.shortName or setDef.name or setId
    return "[" .. shortName .. "] " .. ancientName
end

function GetEquipmentQualityLabel(item)
    local qualityDef = GetEquipmentQualityDef(item and item.quality)
    local label = qualityDef and qualityDef.label or "未知"
    return IsAncientEquipment(item) and ("太古" .. label) or label
end

function GetEquipmentDisplayColor(item)
    if IsAncientEquipment(item) then
        return { 255, 220, 105, 255 }
    end
    local qualityDef = GetEquipmentQualityDef(item and item.quality)
    return qualityDef and qualityDef.color or { 180, 180, 180, 255 }
end

function GetEquipmentCardBackground(item)
    if IsAncientEquipment(item) then
        return { 55, 38, 20, 248 }
    end
    return { 20, 20, 38, 240 }
end

function MakeAffixDisplay(affix)
    local def = EQUIPMENT_AFFIX_BY_ID[affix.id]
    if def == nil then return "未知词条" end
    local prefix = affix.fixed and "彩色 " or ""
    if affix.id == "skill_cooldown" then
        local slot = affix.slot or 1
        return string.format("%s%d号槽冷却-%d%s", prefix, slot, affix.value or 0, def.suffix or "")
    end
    if affix.id == "easter_egg" then
        return prefix .. def.label
    end
    return string.format("%s%s+%d%s", prefix, def.label, affix.value or 0, def.suffix or "")
end

