    return item ~= nil and item.type == "material" and item.id == REFINE_STONE_ITEM_ID
end

function IsPinkRefineStoneItem(item)
    return item ~= nil and item.type == "material" and item.id == PINK_REFINE_STONE_ITEM_ID
end

function IsSocketPuncherItem(item)
    return item ~= nil and item.type == "material" and item.id == SOCKET_PUNCHER_ITEM_ID
