function NormalizeEquipmentName(item)
    if item == nil or item.type ~= "equipment" then return false end
    local name = item.name
    if type(name) ~= "string" or name == "" then
        local slotDef = EQUIPMENT_SLOT_BY_ID[item.slot]
        item.name = slotDef and slotDef.name or "未知装备"
        return true
    end
    for _, quality in ipairs(EQUIPMENT_QUALITY_ORDER or {}) do
        local qualityDef = EQUIPMENT_QUALITY_DEFS[quality]
        local label = qualityDef and qualityDef.label
        if label ~= nil and string.sub(name, 1, #label) == label then
            local stripped = string.sub(name, #label + 1):gsub("^%s+", "")
            if stripped ~= "" then
                item.name = stripped
                return true
            end
        end
    end
    return false
end

function NormalizeRefineStoneItem(item)
    if not IsRefineStoneItem(item) then return false end
    local changed = false
    if item.name ~= REFINE_STONE_NAME then
        item.name = REFINE_STONE_NAME
        changed = true
    end
    local count = math.max(1, math.floor(item.count or 1))
    if item.count ~= count then
        item.count = count
        changed = true
    end
    return changed
end

