function NormalizeRefineStoneStacks()
    playerData.inventory = playerData.inventory or {}
    local total = 0
    local firstIndex = nil
    local changed = false
    for i = #playerData.inventory, 1, -1 do
        local item = playerData.inventory[i]
        if IsRefineStoneItem(item) then
            item.name = REFINE_STONE_NAME
            local count = math.max(1, math.floor(item.count or 1))
            total = total + count
            if firstIndex == nil then
                firstIndex = i
                item.count = count
            else
                table.remove(playerData.inventory, i)
                changed = true
            end
        end
    end
    if firstIndex ~= nil then
        for _, item in ipairs(playerData.inventory) do
            if IsRefineStoneItem(item) then
                if item.count ~= total then
                    item.count = total
                    changed = true
                end
                break
            end
        end
    end
    return changed
end

