    local floor = math.max(1, math.floor(item and item.floor or 1))
    return math.floor((floor - 1) / 100) + 1
end

function AddRefineStone(count, deferSave)
    count = math.max(1, math.floor(count or 1))
    playerData.inventory = playerData.inventory or {}
    for _, item in ipairs(playerData.inventory) do
        if IsRefineStoneItem(item) then
            item.name = REFINE_STONE_NAME
            item.count = math.max(0, item.count or 0) + count
            saveDirty = true
            print("[Drop] 获得" .. REFINE_STONE_NAME .. " x" .. count .. "，当前:" .. item.count)
            if deferSave ~= true then SaveCloudData(true) end
            return item.count
        end
    end
    table.insert(playerData.inventory, {
        type = "material",
        id = REFINE_STONE_ITEM_ID,
        name = REFINE_STONE_NAME,
        count = count,
    })
    saveDirty = true
    print("[Drop] 获得" .. REFINE_STONE_NAME .. " x" .. count .. "，当前:" .. count)
    if deferSave ~= true then SaveCloudData(true) end
    return count
end

function AddPinkRefineStone(count, deferSave)
    count = math.max(1, math.floor(count or 1))
    playerData.inventory = playerData.inventory or {}
    local total = count
    local merged = false
    for _, item in ipairs(playerData.inventory) do
        if IsPinkRefineStoneItem(item) then
            item.name = PINK_REFINE_STONE_NAME
            item.count = math.max(0, item.count or 0) + count
            total = item.count
            merged = true
            break
        end
    end
    if not merged then
        table.insert(playerData.inventory, {
            type = "material",
            id = PINK_REFINE_STONE_ITEM_ID,
            name = PINK_REFINE_STONE_NAME,
            count = count,
        })
    end
    saveDirty = true
    print("[Drop] 获得" .. PINK_REFINE_STONE_NAME .. " x" .. count .. "，当前:" .. total)
    if deferSave ~= true then
        SaveCloudData(true)
    end
    return total
end

function AddSocketPuncher(count, deferSave)
    count = math.max(1, math.floor(count or 1))
    playerData.inventory = playerData.inventory or {}
    local total = count
    for _, item in ipairs(playerData.inventory) do
        if IsSocketPuncherItem(item) then
            item.name = SOCKET_PUNCHER_NAME
            item.count = math.max(0, item.count or 0) + count
            total = item.count
            saveDirty = true
            print("[Drop] 获得" .. SOCKET_PUNCHER_NAME .. " x" .. count .. "，当前:" .. total)
            if deferSave ~= true then SaveCloudData(true) end
            return total
        end
    end
    table.insert(playerData.inventory, {
        type = "material",
        id = SOCKET_PUNCHER_ITEM_ID,
        name = SOCKET_PUNCHER_NAME,
        count = count,
    })
    saveDirty = true
    print("[Drop] 获得" .. SOCKET_PUNCHER_NAME .. " x" .. count .. "，当前:" .. total)
    if deferSave ~= true then SaveCloudData(true) end
    return total
end

function GrantRebirthStoneToCurrentPlayer(amount, deferSave)
    amount = math.max(1, math.floor(tonumber(amount) or 0))
    playerData.rebirthStone = math.max(0, math.floor(playerData.rebirthStone or 0)) + amount
    saveDirty = true
    print("[RebirthStoneGrant] 获得" .. REBIRTH_STONE_NAME .. " x" .. amount .. "，当前:" .. playerData.rebirthStone)
    if deferSave ~= true then SaveCloudData(true) end
    return playerData.rebirthStone
end

function GrantMaterialToCurrentPlayer(materialId, amount, deferSave)
    local count = math.max(1, math.floor(tonumber(amount) or 0))
    if materialId == REFINE_STONE_ITEM_ID then
        return AddRefineStone(count, deferSave)
    end
    if materialId == PINK_REFINE_STONE_ITEM_ID then
        return AddPinkRefineStone(count, deferSave)
    end
    if materialId == SOCKET_PUNCHER_ITEM_ID then
        return AddSocketPuncher(count, deferSave)
    end
    return nil
end
pendingLoot = {
    equip = {},
    skills = {},
    gold = 0,
    refineStone = 0,
    destroyedColorfulCount = 0,
    rejectedEquipmentCount = 0,
    rejectedSkillCount = 0,
}

function ResetPendingLoot()
    pendingLoot = {
        equip = {},
        skills = {},
        gold = 0,
        refineStone = 0,
        destroyedColorfulCount = 0,
        rejectedEquipmentCount = 0,
        rejectedSkillCount = 0,
    }
end

function HasPendingLoot()
    return #pendingLoot.equip > 0
        or #pendingLoot.skills > 0
        or (pendingLoot.gold or 0) > 0
        or (pendingLoot.refineStone or 0) > 0
end

function PendingAddGold(amount)
    amount = math.max(0, math.floor(amount or 0))
    if amount <= 0 then return 0 end
    pendingLoot.gold = (pendingLoot.gold or 0) + amount
    return amount
end

function PendingAddRefineStone(count)
    count = math.max(0, math.floor(count or 0))
    if count <= 0 then return 0 end
    pendingLoot.refineStone = (pendingLoot.refineStone or 0) + count
    return count
end

function PendingAddMilestoneRedWeapon(floor)
    local item = GenerateEquipment("weapon", "red", floor)
    item.milestoneReward = true
    local status = PendingAddEquipment(item)
    if status == "kept" then
        print("[MilestoneReward] 第" .. tostring(floor) .. "层获得红色武器:", item.name)
        return item
    end
    print("[MilestoneReward] 第" .. tostring(floor) .. "层红色武器未获取:", status or "unknown")
    return nil
end

function ClaimMilestoneRedWeapons(startFloor, endFloor)
    local claims = playerData.milestoneRedWeaponClaims or {}
    playerData.milestoneRedWeaponClaims = claims
    local claimed = 0
    for _, floor in ipairs({ 5, 10, 20 }) do
        if floor >= startFloor and floor <= endFloor and claims[tostring(floor)] ~= true then
            PendingAddMilestoneRedWeapon(floor)
            claims[tostring(floor)] = true
            claimed = claimed + 1
        end
    end
    if claimed > 0 then
        saveDirty = true
    end
    return claimed
end

local function CountEquipmentInList(list)
    local n = 0
    for _, item in ipairs(list or {}) do
        if type(item) == "table" and item.type == "equipment" then
            n = n + 1
        end
    end
    return n
end

function CountInventoryEquipment()
    return CountEquipmentInList(playerData.inventory)
end

function GetEquipmentCapacityUsage()
    local inventoryCount = CountInventoryEquipment()
    local pendingCount = CountEquipmentInList(pendingLoot and pendingLoot.equip or nil)
    return inventoryCount + pendingCount, inventoryCount, pendingCount
end

function GetSkillCapacityUsage()
    local inventoryCount = CountUnequippedSkillCards()
    local pendingCount = #((pendingLoot and pendingLoot.skills) or {})
    return inventoryCount + pendingCount, inventoryCount, pendingCount
end

function AddRecoveredEquipmentToInventory(item, source)
    if type(item) ~= "table" or item.type ~= "equipment" then
        print("[EquipmentRecovery] 忽略无效装备:", source or "unknown")
        return false
    end
    local equipmentCap = CONFIG.MaxEquipmentInventory or 500
    local equipmentCount = CountInventoryEquipment()
    if equipmentCount >= equipmentCap then
        print("[EquipmentRecovery] 背包已满，恢复装备未写入:",
            item.name or item.slot or "装备", source or "unknown", equipmentCount, "/", equipmentCap)
        return false
    end
    table.insert(playerData.inventory, item)
    saveDirty = true
    print("[EquipmentRecovery] 装备已恢复到背包:",
        item.name or item.slot or "装备", source or "unknown", equipmentCount + 1, "/", equipmentCap)
    return true
end

local function ShowInventoryCapacityMessage(text)
    print("[InventoryCapacity]", text)
    if AddEffect ~= nil and screenW ~= nil and screenH ~= nil then
        AddEffect({
            type = "drop",
            x = screenW * 0.5,
            y = screenH * 0.36,
            text = text,
            life = 1.8,
            maxLife = 1.8,
        })
    end
end

local function CountColorfulInList(list)
    local n = 0
    for _, it in ipairs(list or {}) do
        if it and it.type == "equipment" and it.quality == "colorful" then
            n = n + 1
        end
    end
    return n
end

local function IsEasterEggEquipment(item)
    for _, affix in ipairs(item and item.affixes or {}) do
        if affix and affix.id == "easter_egg" then
            return true
        end
    end
    return false
end

local function RemoveNonEasterEggColorful(list)
    for i = #(list or {}), 1, -1 do
        local item = list[i]
        if item and item.type == "equipment"
            and item.quality == "colorful"
            and not IsEasterEggEquipment(item) then
            return table.remove(list, i)
        end
    end
    return nil
end

local function MakeRoomForEasterEggColorful()
    local removed = RemoveNonEasterEggColorful(playerData.inventory)
    if removed == nil then
        removed = RemoveNonEasterEggColorful(pendingLoot.equip)
    end
    return removed
end

local function CountInventoryColorful()
    return CountColorfulInList(playerData.inventory)
end

function PendingAddEquipment(item)
    if item == nil then return nil end
    if RecordEquipmentDiscovery ~= nil then RecordEquipmentDiscovery(item) end
    local replacedColorful = false

    if item.quality == "colorful" then
        local maxColorful = CONFIG.MaxColorfulInventory or 5
        local curColorful = CountInventoryColorful() + CountColorfulInList(pendingLoot.equip)
        if curColorful >= maxColorful then
            local replaced = nil
            if IsEasterEggEquipment(item) then
                replaced = MakeRoomForEasterEggColorful()
            end
            if replaced == nil then
                pendingLoot.destroyedColorfulCount = (pendingLoot.destroyedColorfulCount or 0) + 1
                print("[ColorfulCap] 销毁(暂存):", item.name,
                    "背包", CountInventoryColorful(), "暂存", CountColorfulInList(pendingLoot.equip),
                    "上限", maxColorful)
                return "destroyed"
            end
            replacedColorful = true
            item._capacityReplacement = true
            print("[ColorfulCap] 小趴菜替换彩色装备:", replaced.name, "→", item.name)
        end
    end

    NormalizeEquipmentSettings()
    if not replacedColorful and ShouldAutoSellEquipment(item) then
        local gold, refineStone = GetEquipmentSellRewards(item)
        if gold > 0 then PendingAddGold(gold) end
        if refineStone > 0 then PendingAddRefineStone(refineStone) end
        local rewardText = FormatEquipmentSellRewardValues(gold, refineStone)
        print("[PendingLoot] 自动出售(暂存):", item.name, rewardText)
        return "autoSold"
    end

    local equipmentCap = CONFIG.MaxEquipmentInventory or 500
    local equipmentCount = GetEquipmentCapacityUsage()
    if equipmentCount >= equipmentCap and not replacedColorful then
        pendingLoot.rejectedEquipmentCount = (pendingLoot.rejectedEquipmentCount or 0) + 1
        ShowInventoryCapacityMessage(
            "装备背包已满（" .. tostring(equipmentCount) .. "/" .. tostring(equipmentCap)
                .. "），未获取 " .. tostring(item.name or "装备")
        )
        return "inventoryFull"
    end

    table.insert(pendingLoot.equip, item)
    print("[PendingLoot] 装备入暂存:", item.name, "层数:", item.floor or 1)
    return "kept"
end

function PendingAddSkill(skill)
    if skill == nil then return nil end
    local skillCap = CONFIG.MaxUnequippedSkillCards or 300
    local skillCount = GetSkillCapacityUsage()
    local autoMergeEnabled = playerData.settings and playerData.settings.autoSkillMergeEnabled == true
    if skillCount >= skillCap and not autoMergeEnabled then
        pendingLoot.rejectedSkillCount = (pendingLoot.rejectedSkillCount or 0) + 1
        ShowInventoryCapacityMessage(
            "技能背包已满（" .. tostring(skillCount) .. "/" .. tostring(skillCap)
                .. "），未获取 " .. tostring(skill.name or "技能卡")
        )
        return "inventoryFull"
    end
    if RecordSkillDiscovery ~= nil and not autoMergeEnabled then RecordSkillDiscovery(skill) end
    table.insert(pendingLoot.skills, skill)
    if skillCount >= skillCap then
        print("[InventoryCapacity] 技能暂存超过当前容量，等待结算自动合成:",
            skill.name or "技能卡", skillCount + 1, "/", skillCap)
    end
    return "kept"
end

function CommitPendingLoot(reason, preserveSkillRuntime)
    if not HasPendingLoot() then
        ResetPendingLoot()
        if not preserveSkillRuntime then
            InitSkillRuntime()
        end
        return false
    end

    NormalizeEquipment()
    NormalizeSkills()

    local equipmentCap = CONFIG.MaxEquipmentInventory or 500
    local equipmentCount = CountInventoryEquipment()
    local committedEquipmentCount = 0
    for _, item in ipairs(pendingLoot.equip) do
        if equipmentCount < equipmentCap or item._capacityReplacement == true then
            item._capacityReplacement = nil
            table.insert(playerData.inventory, item)
            equipmentCount = equipmentCount + 1
            committedEquipmentCount = committedEquipmentCount + 1
        else
            pendingLoot.rejectedEquipmentCount = (pendingLoot.rejectedEquipmentCount or 0) + 1
            print("[InventoryCapacity] 提交时装备背包已满，未获取:", item.name or "装备")
        end
    end

    NormalizeEquipmentSettings()
    local skillCap = CONFIG.MaxUnequippedSkillCards or 300
    local autoMergeEnabled = playerData.settings.autoSkillMergeEnabled == true
    local autoMergeTargetStar = playerData.settings.autoSkillMergeTargetStar or 3
    local autoMergeAttempts = 0
    local autoMergeSuccessCount = 0
    local autoMergeFailCount = 0
    local function MergeSkillsForCapacity()
        local attempts, successCount, failCount = AutoMergeSkillsToTarget(autoMergeTargetStar)
        autoMergeAttempts = autoMergeAttempts + attempts
        autoMergeSuccessCount = autoMergeSuccessCount + successCount
        autoMergeFailCount = autoMergeFailCount + failCount
    end
    if autoMergeEnabled then
        MergeSkillsForCapacity()
    end
    local unequippedSkillCount = CountUnequippedSkillCards()
    local committedSkillCount = 0
    local pendingSkills = pendingLoot.skills or {}
    local pendingSkillCount = #pendingSkills

    -- 原逐张语义：插入→合并→容量不足则回滚该张
    -- （仅在未开启自动合成，或容量不足的边界回滚时使用）
    local function CommitPendingSkillsOneByOne()
        local count = 0
        local unequipped = CountUnequippedSkillCards()
        for _, skill in ipairs(pendingSkills) do
            local accepted = false
            if autoMergeEnabled then
                table.insert(playerData.skills, skill)
                MergeSkillsForCapacity()
                unequipped = CountUnequippedSkillCards()
                accepted = unequipped <= skillCap
                if not accepted then
                    for index = #playerData.skills, 1, -1 do
                        if playerData.skills[index].uid == skill.uid then
                            table.remove(playerData.skills, index)
                            break
                        end
                    end
                    NormalizeSkills()
                end
            elseif unequipped < skillCap then
                table.insert(playerData.skills, skill)
                accepted = true
            end

            if accepted then
                if RecordSkillDiscovery ~= nil and autoMergeEnabled then RecordSkillDiscovery(skill) end
                if autoMergeEnabled then
                    -- 开合成：合成会改变未装备卡数，必须重算。
                    unequipped = CountUnequippedSkillCards()
                else
                    -- 未开合成：插入一张，未装备计数直接 +1，避免每张全表重扫。
                    unequipped = unequipped + 1
                end
                count = count + 1
            else
                pendingLoot.rejectedSkillCount = (pendingLoot.rejectedSkillCount or 0) + 1
                print("[InventoryCapacity] 自动合成后技能背包仍满，未获取:", skill.name or "技能卡")
            end
        end
        return count
    end

    if autoMergeEnabled and pendingSkillCount > 0 then
        -- 快路径：整批入包后只触发一次自动合成。
        -- 连打结算一次性提交几十上百张技能卡，原先逐卡触发全量合成是弹结算界面卡顿的主因。
        local insertedUids = {}
        for _, skill in ipairs(pendingSkills) do
            insertedUids[skill.uid] = true
            table.insert(playerData.skills, skill)
        end
        MergeSkillsForCapacity()
        unequippedSkillCount = CountUnequippedSkillCards()
        if unequippedSkillCount <= skillCap then
            for _, skill in ipairs(pendingSkills) do
                if RecordSkillDiscovery ~= nil then RecordSkillDiscovery(skill) end
            end
            committedSkillCount = pendingSkillCount
        else
            -- 容量不足边界：回滚本次批量插入，重放原逐张语义，保证取舍规则与旧版一致
            for index = #playerData.skills, 1, -1 do
                if insertedUids[playerData.skills[index].uid] == true then
                    table.remove(playerData.skills, index)
                end
            end
            NormalizeSkills()
            committedSkillCount = CommitPendingSkillsOneByOne()
        end
    else
        committedSkillCount = CommitPendingSkillsOneByOne()
    end

    local gold = pendingLoot.gold or 0
    if gold > 0 then
        playerData.gold = math.max(0, math.floor(playerData.gold or 0)) + gold
        playerData.totalGoldEarned = math.max(0, math.floor(playerData.totalGoldEarned or 0)) + gold
    end

    local refine = pendingLoot.refineStone or 0
    if refine > 0 then
        playerData.inventory = playerData.inventory or {}
        local merged = false
        for _, item in ipairs(playerData.inventory) do
            if IsRefineStoneItem(item) then
                item.name = REFINE_STONE_NAME
                item.count = math.max(0, item.count or 0) + refine
                merged = true
                break
            end
        end
        if not merged then
            table.insert(playerData.inventory, {
                type = "material",
                id = REFINE_STONE_ITEM_ID,
                name = REFINE_STONE_NAME,
                count = refine,
            })
        end
    end

    local equipCount = committedEquipmentCount
    local skillCount = committedSkillCount
    local destroyed = pendingLoot.destroyedColorfulCount or 0
    local rejectedEquipment = pendingLoot.rejectedEquipmentCount or 0
    local rejectedSkills = pendingLoot.rejectedSkillCount or 0
    print("[PendingLoot] 提交(", reason or "unknown",
        "): 装备", equipCount, "技能", skillCount,
        "金币", gold, "洗练石", refine,
        "销毁彩色", destroyed,
        "装备满未获取", rejectedEquipment,
        "技能满未获取", rejectedSkills)
    if rejectedEquipment > 0 or rejectedSkills > 0 then
        local parts = {}
        if rejectedEquipment > 0 then
            table.insert(parts, "装备" .. tostring(rejectedEquipment) .. "件")
        end
        if rejectedSkills > 0 then
            table.insert(parts, "技能卡" .. tostring(rejectedSkills) .. "张")
        end
        ShowInventoryCapacityMessage("背包空间不足，未获取" .. table.concat(parts, "、"))
    end

    ResetPendingLoot()

    NormalizeSkills()
    if autoMergeEnabled and autoMergeAttempts > 0 then
        SaveCloudData(true)
        print("[SkillAutoMerge] 触发: commit_pending", "目标:", autoMergeTargetStar,
            "次数:", autoMergeAttempts, "成功:", autoMergeSuccessCount, "失败:", autoMergeFailCount)
    end
    if preserveSkillRuntime then
        print("[Skill] 保留当前技能CD, 原因:", reason or "unknown")
    else
        InitSkillRuntime()
    end
    NormalizeEquipment()

    saveDirty = true
    return true
end

function ConsumeRefineStone(count)
    count = math.max(1, math.floor(count or 1))
    if GetRefineStoneCount() < count then return false end
    local remaining = count
    for i = #playerData.inventory, 1, -1 do
        local item = playerData.inventory[i]
        if IsRefineStoneItem(item) then
            local take = math.min(remaining, item.count or 0)
            item.count = (item.count or 0) - take
            remaining = remaining - take
            if item.count <= 0 then
                table.remove(playerData.inventory, i)
            end
            if remaining <= 0 then break end
        end
    end
    saveDirty = true
    return true
end

function ConsumePinkRefineStone(count)
    count = math.max(1, math.floor(count or 1))
    if GetPinkRefineStoneCount() < count then return false end
    local remaining = count
    for i = #playerData.inventory, 1, -1 do
        local item = playerData.inventory[i]
        if IsPinkRefineStoneItem(item) then
            local take = math.min(remaining, item.count or 0)
            item.count = (item.count or 0) - take
            remaining = remaining - take
            if item.count <= 0 then
                table.remove(playerData.inventory, i)
            end
            if remaining <= 0 then break end
        end
    end
    saveDirty = true
    return true
end

function IsEquipmentRefinable(item)
    return item ~= nil
        and item.type == "equipment"
        and item.quality ~= "colorful"
        and item.affixes ~= nil
        and #item.affixes > 0
end

function IsColorfulEquipmentRefinable(item)
    if item == nil or item.type ~= "equipment" or item.quality ~= "colorful" then
        return false
    end
    for _, affix in ipairs(item.affixes or {}) do
        if affix.fixed ~= true then
            return true
        end
    end
    return false
end

function IsAnyEquipmentRefinable(item)
    return IsEquipmentRefinable(item) or IsColorfulEquipmentRefinable(item)
end

function NormalizeEquipmentRefineState(item)
    if item == nil or item.type ~= "equipment" then return false end
    local changed = false
    if item.refineAffixIndex ~= nil then
        local index = math.floor(item.refineAffixIndex or 0)
        if item.affixes == nil or index < 1 or index > #item.affixes or (item.affixes[index] and item.affixes[index].fixed == true) then
            item.refineAffixIndex = nil
            changed = true
        else
            if item.refineAffixIndex ~= index then
                item.refineAffixIndex = index
                changed = true
            end
        end
    end
    if item.refineCount ~= nil then
        local count = math.max(0, math.floor(item.refineCount or 0))
        if item.refineCount ~= count then
            item.refineCount = count
            changed = true
        end
    end
    return changed
end

function GetRefineCandidateAffixDefs(item, affixIndex)
    local blocked = {}
    for index, affix in ipairs(item.affixes or {}) do
        if index ~= affixIndex and affix.id ~= nil then
            blocked[affix.id] = true
        end
    end
    local candidates = {}
    for _, def in ipairs(EQUIPMENT_AFFIX_DEFS) do
        if not blocked[def.id] then
            table.insert(candidates, def)
        end
    end
    return candidates
end

function RollRefinedAffix(item, affixIndex)
    local candidates = GetRefineCandidateAffixDefs(item, affixIndex)
    if #candidates == 0 then return nil end
    local def = candidates[math.random(1, #candidates)]
    return {
        id = def.id,
        value = RollEquipmentAffixValue(def, item.floor),
    }
end

function GetPinkRefineCandidateAffixDefs(item, affixIndex)
    local blocked = {}
    local currentAffix = item.affixes and item.affixes[affixIndex] or nil
    if currentAffix ~= nil and currentAffix.id ~= nil then
        blocked[currentAffix.id] = true
    end
    for index, affix in ipairs(item.affixes or {}) do
        if index ~= affixIndex and affix.id ~= nil then
            blocked[affix.id] = true
        end
    end
    local candidates = {}
    for _, def in ipairs(EQUIPMENT_AFFIX_DEFS or {}) do
        if not blocked[def.id] then
            table.insert(candidates, def)
        end
    end
    return candidates
end

function RollPinkRefinedAffix(item, affixIndex)
    local candidates = GetPinkRefineCandidateAffixDefs(item, affixIndex)
    if #candidates == 0 then return nil end
    local def = candidates[math.random(1, #candidates)]
    return {
        id = def.id,
        value = RollEquipmentAffixValue(def, item.floor),
    }
end

function TryRefineEquipment(item, affixIndex, inventoryIndex)
    if not IsEquipmentRefinable(item) then
        return false, item and item.quality == "colorful" and "彩色装备不能洗炼" or "该装备没有可洗炼词条"
    end
    NormalizeEquipmentRefineState(item)
    affixIndex = math.floor(affixIndex or 0)
    if affixIndex < 1 or affixIndex > #(item.affixes or {}) then
        return false, "请选择一条可洗炼词条"
    end
    if item.affixes[affixIndex].fixed == true then
        return false, "固定词条不能洗炼"
    end
    if item.refineAffixIndex ~= nil and item.refineAffixIndex ~= affixIndex then
        return false, "已锁定其他词条，只能继续洗炼已选词条"
    end
    local stoneCost = GetEquipmentRefineStoneCost(item)
    if GetRefineStoneCount() < stoneCost then
        return false, REFINE_STONE_NAME .. "不足，本次需要" .. stoneCost .. "个"
    end
    local newAffix = RollRefinedAffix(item, affixIndex)
    if newAffix == nil then
        return false, "没有可用词条池"
    end
    if not ConsumeRefineStone(stoneCost) then
        return false, REFINE_STONE_NAME .. "不足，本次需要" .. stoneCost .. "个"
    end
    item.refineAffixIndex = affixIndex
    item.refineCount = math.max(0, item.refineCount or 0) + 1
    if RecordAdventureRefine ~= nil then RecordAdventureRefine() end
    item.affixes[affixIndex] = newAffix
    if inventoryIndex ~= nil and not IsAncientEquipment(item) then
        item.locked = true
    end
    saveDirty = true
    local message = "洗炼成功：第" .. affixIndex .. "条变为 " .. MakeAffixDisplay(newAffix)
    refineMessage = message
    SaveCloudData(true)
    print("[Refine]", item.name or "装备", message, "剩余" .. REFINE_STONE_NAME .. ":", GetRefineStoneCount())
    return true, message
end

function TryPinkRefineEquipment(item, affixIndex, inventoryIndex)
    if not IsColorfulEquipmentRefinable(item) then
        return false, item and item.quality ~= "colorful"
            and "粉色洗练石只能用于彩色装备"
            or "该彩色装备没有可洗炼普通词条"
    end
    NormalizeEquipmentRefineState(item)
    affixIndex = math.floor(affixIndex or 0)
    if affixIndex < 1 or affixIndex > #(item.affixes or {}) then
        return false, "请选择一条可洗炼普通词条"
    end
    if item.affixes[affixIndex].fixed == true then
        return false, "彩色固定词条不能洗炼"
    end
    if item.refineAffixIndex ~= nil and item.refineAffixIndex ~= affixIndex then
        return false, "已锁定其他词条，只能继续洗炼已选词条"
    end
    local stoneCost = GetEquipmentRefineStoneCost(item)
    if GetPinkRefineStoneCount() < stoneCost then
        return false, PINK_REFINE_STONE_NAME .. "不足，本次需要" .. stoneCost .. "个"
    end
    local newAffix = RollPinkRefinedAffix(item, affixIndex)
    if newAffix == nil then
        return false, "没有符合规则的普通词条"
    end
    if not ConsumePinkRefineStone(stoneCost) then
        return false, PINK_REFINE_STONE_NAME .. "不足，本次需要" .. stoneCost .. "个"
    end
    item.refineAffixIndex = affixIndex
    item.refineCount = math.max(0, item.refineCount or 0) + 1
    if RecordAdventureRefine ~= nil then RecordAdventureRefine() end
    item.affixes[affixIndex] = newAffix
    if inventoryIndex ~= nil and not IsAncientEquipment(item) then
        item.locked = true
    end
    saveDirty = true
    local message = "粉色洗炼成功：第" .. affixIndex .. "条变为 " .. MakeAffixDisplay(newAffix)
    refineMessage = message
    SaveCloudData(true)
    print("[PinkRefine]", item.name or "装备", message,
        "剩余" .. PINK_REFINE_STONE_NAME .. ":", GetPinkRefineStoneCount())
    return true, message
end

function GetBaseAffixRange(item)
    if item == nil or item.baseAffix == nil then return nil, nil end
    local slotDef = EQUIPMENT_SLOT_BY_ID[item.slot]
    if slotDef == nil then return nil, nil end
    local floor = math.max(1, math.floor(item.floor or 1))
    local growthStep = math.max(1, math.floor(slotDef.growthStep or 5))
    local step = math.floor((floor - 1) / growthStep)
    local baseValue = slotDef.baseValue + step * slotDef.growth
    local minMultiplier = (item.quality == "orange" or item.quality == "red" or item.quality == "colorful") and 0.8 or 1.0
    local minValue = math.max(0, math.floor(baseValue * minMultiplier + 0.5))
    local maxValue = math.max(0, math.floor(baseValue * 1.2 + 0.5))
    return minValue, maxValue
end

function MakeBaseAffixDisplay(item)
    if item == nil or item.baseAffix == nil then return "" end
    local text = MakeAffixDisplay(item.baseAffix)
    local minValue, maxValue = GetBaseAffixRange(item)
    if minValue == nil or maxValue == nil then return text end
    local def = EQUIPMENT_AFFIX_BY_ID[item.baseAffix.id]
    local suffix = def and def.suffix or ""
    return text .. string.format("（%d～%d%s）", minValue, maxValue, suffix)
end

function GetEquipmentRefineStatusText(item)
    if item == nil then return "" end
    if item.quality == "colorful" then return "彩色装备不可洗炼" end
    if not IsEquipmentRefinable(item) then return "没有可洗炼词条" end
    NormalizeEquipmentRefineState(item)
    if item.refineAffixIndex ~= nil then
        return "已锁定第" .. item.refineAffixIndex .. "条，可无限洗炼该词条"
    end
    return "首次洗炼需手动选择一条词条"
end

function RollBaseAffixValue(slotDef, floor, quality, maximum)
    floor = math.max(1, floor)
    local growthStep = math.max(1, math.floor(slotDef.growthStep or 5))
    local step = math.floor((floor - 1) / growthStep)
    local baseValue = slotDef.baseValue + step * slotDef.growth
    if maximum then
        return math.max(0, math.floor(baseValue * 1.2 + 0.5))
    end
    local minMultiplier = (quality == "orange" or quality == "red" or quality == "colorful") and 0.8 or 1.0
    local floatingValue = baseValue * (minMultiplier + math.random() * (1.2 - minMultiplier))
    return math.max(0, math.floor(floatingValue + 0.5))
end

function RollEquipmentQuality(floor)
    local roll = math.random(1, 10000)
    local colorfulChance = 7
    local acc = 0
    for _, item in ipairs(EQUIPMENT_QUALITY_ROLLS) do
        local chance = item.chance
        if item.quality == "colorful" then
            chance = colorfulChance
        elseif item.quality == "blue" and colorfulChance > 10 then
            chance = math.max(0, chance - (colorfulChance - 10))
        end
        acc = acc + chance
        if roll <= acc then return item.quality end
    end
    return "blue"
end

local TARGETED_EASTER_EGG_UID = "1089365352"
local TARGETED_EASTER_EGG_CHANCE = 0.30

local function IsTargetedEasterEggPlayer()
    return clientCloud ~= nil
        and tostring(clientCloud.userId or "") == TARGETED_EASTER_EGG_UID
end

function CreateColorfulFixedAffix(useTargetedChance, maximum)
    if COLORFUL_FIXED_AFFIX_DEFS == nil or #COLORFUL_FIXED_AFFIX_DEFS == 0 then return nil end
    local fixedDef = nil
    if useTargetedChance == true
        and IsTargetedEasterEggPlayer()
        and math.random() < TARGETED_EASTER_EGG_CHANCE then
        fixedDef = EQUIPMENT_AFFIX_BY_ID.easter_egg
    else
        local candidates = COLORFUL_FIXED_AFFIX_DEFS
        if useTargetedChance == true and IsTargetedEasterEggPlayer() then
            candidates = {}
            for _, def in ipairs(COLORFUL_FIXED_AFFIX_DEFS) do
                if def.id ~= "easter_egg" then
                    table.insert(candidates, def)
                end
            end
        end
        fixedDef = candidates[math.random(1, #candidates)]
    end
    local affix = {
        id = fixedDef.id,
        value = RollEquipmentAffixValue(fixedDef),
        fixed = true,
    }
    if affix.id == "skill_cooldown" then
        affix.slot = GetRandomSkillCooldownSlot()
    end
    return affix
end

function EnsureColorfulFixedAffix(item)
    if item == nil or item.type ~= "equipment" or item.quality ~= "colorful" then return false end
    item.affixes = item.affixes or {}
    local changed = false
    local hasFixed = false
    for _, affix in ipairs(item.affixes) do
        if affix.id == "skill_cooldown" and affix.slot == nil then
            affix.slot = GetRandomSkillCooldownSlot()
            changed = true
        end
        if affix.fixed == true then
            hasFixed = true
        end
    end
    if hasFixed then
        item.fixedAffix = nil
        return changed
    end
    if item.fixedAffix ~= nil then
        item.fixedAffix.fixed = true
        if item.fixedAffix.id == "skill_cooldown" and item.fixedAffix.slot == nil then
            item.fixedAffix.slot = GetRandomSkillCooldownSlot()
        end
        table.insert(item.affixes, item.fixedAffix)
        item.fixedAffix = nil
        return true
    end
    local fixedAffix = CreateColorfulFixedAffix()
    if fixedAffix ~= nil then
        table.insert(item.affixes, fixedAffix)
        return true
    end
    return changed
end

function RollEquipmentResonanceSetId()
    local order = EQUIPMENT_RESONANCE_ORDER or {}
    if #order <= 0 then return nil end
    return order[math.random(1, #order)]
end

function GenerateEquipment(slot, quality, floor, ancientOverride, grantResonanceSet)
    local slotDef = EQUIPMENT_SLOT_BY_ID[slot] or EQUIPMENT_SLOT_BY_ID.weapon
    floor = math.max(1, math.floor(floor or 1))
    quality = quality or RollEquipmentQuality(floor)
    local ancient = false
    if quality == "blue"
        or quality == "purple"
        or quality == "orange"
        or quality == "red" then
        if ancientOverride == nil then
            local ancientChance = quality == "blue"
                and (CONFIG.AncientBlueEquipmentChance or 0.20)
                or quality == "purple"
                and (CONFIG.AncientPurpleEquipmentChance or 0.10)
                or quality == "orange"
                and (CONFIG.AncientOrangeEquipmentChance or 0.06)
                or (CONFIG.AncientRedEquipmentChance or 0.03)
            ancient = math.random() < ancientChance
        else
            ancient = ancientOverride == true
        end
    end
    local qualityDef = EQUIPMENT_QUALITY_DEFS[quality] or EQUIPMENT_QUALITY_DEFS.blue
    local qualityRank = EQUIPMENT_QUALITY_RANK[quality] or 0
    -- 彩色（粉色）装备默认满属性（等同太古的满值词条），但不标记为太古
    local fullValue = ancient or quality == "colorful"
    local resonanceSetId = grantResonanceSet == true
        and qualityRank >= (EQUIPMENT_QUALITY_RANK.blue or 1)
        and RollEquipmentResonanceSetId()
        or nil
    local count = math.random(qualityDef.minAffixes, qualityDef.maxAffixes)
    local available = {}
    for i = 1, #EQUIPMENT_AFFIX_DEFS do
        available[i] = EQUIPMENT_AFFIX_DEFS[i]
    end

    local affixes = {}
    for _ = 1, count do
        local index = math.random(1, #available)
        local def = table.remove(available, index)
        local value = fullValue
            and GetMaxEquipmentAffixValue(def, floor)
            or RollEquipmentAffixValue(def, floor)
        table.insert(affixes, {
            id = def.id,
            value = value,
        })
    end

    local baseAffix = {
        id = slotDef.baseAffixId,
        value = RollBaseAffixValue(slotDef, floor, quality, fullValue),
    }
    if quality == "colorful" then
        local fixedAffix = CreateColorfulFixedAffix(true)
        if fixedAffix ~= nil then
            table.insert(affixes, fixedAffix)
        end
    end
    local baseNames = slotDef.names or { slotDef.name }
    local baseName = baseNames[math.random(1, #baseNames)] or slotDef.name
    local name = baseName

    local visualId = slot == "weapon" and GetWeaponVisualIdByName(name) or nil
    local equipmentUid = math.max(1, math.floor(tonumber(playerData.nextEquipmentUid) or 1))
    playerData.nextEquipmentUid = equipmentUid + 1
    return {
        type = "equipment",
        uid = equipmentUid,
        name = name,
        slot = slot,
        quality = quality,
        ancient = ancient or nil,
        viewed = false,
        floor = floor,
        visualId = visualId,
        resonanceSetId = resonanceSetId,
        weaponUpgradeLevel = slot == "weapon" and 0 or nil,
        armorUpgradeLevel = slot == "armor" and 0 or nil,
        bootsUpgradeLevel = slot == "boots" and 0 or nil,
        glovesUpgradeLevel = slot == "gloves" and 0 or nil,
        ringUpgradeLevel = slot == "ring" and 0 or nil,
        baseAffix = baseAffix,
        affixes = affixes,
    }
end

EQUIPMENT_SYNTHESIS_RESULT_QUALITY = {
    blue = "purple",
    purple = "orange",
    orange = "red",
    red = "red",
}

EQUIPMENT_SYNTHESIS_ANCIENT_CHANCE = {
    blue = 0,
    purple = 1,
    orange = 1,
    red = 5,
}

EQUIPMENT_SYNTHESIS_GOLD_COST = {
    blue = 0,
    purple = 0,
    orange = 1000000,
    red = 1000000,
}

function GetEquipmentUpgradeLevel(item)
    if item == nil or item.type ~= "equipment" then return 0 end
    return math.max(
        0,
        math.floor(
            item.weaponUpgradeLevel
                or item.armorUpgradeLevel
                or item.bootsUpgradeLevel
                or item.glovesUpgradeLevel
                or item.ringUpgradeLevel
                or 0
        )
    )
end

function GetEquipmentSynthesisBlockReason(item)
    if item == nil or item.type ~= "equipment" then
        return "只能选择装备"
    end
    if EQUIPMENT_SYNTHESIS_RESULT_QUALITY[item.quality] == nil then
        return item.quality == "colorful" and "彩色装备不能合成" or "该品质不能合成"
    end
    if IsAncientEquipment(item) then
        return "太古装备不能合成"
    end
    if item.locked == true then
        return "锁定装备不能合成"
    end
    if HasSocketedGems(item) then
        return "已镶嵌宝石的装备不能合成"
    end
    if GetEquipmentUpgradeLevel(item) > 0 then
        return "已强化装备不能合成"
    end
    if item.synthesized == true then
        return "合成产物不能再次合成"
    end
    return nil
end

function CanUseEquipmentAsSynthesisMaterial(item)
    return GetEquipmentSynthesisBlockReason(item) == nil
end

function GetEquipmentSynthesisPreview(materials)
    if type(materials) ~= "table" or #materials == 0 then
        return nil, "请先选择装备"
    end

    local sourceQuality = nil
    local floorTotal = 0
    local seen = {}
    for _, item in ipairs(materials) do
        local blockReason = GetEquipmentSynthesisBlockReason(item)
        if blockReason ~= nil then
            return nil, blockReason
        end
        if seen[item] then
            return nil, "不能重复选择同一件装备"
        end
        seen[item] = true
        if sourceQuality == nil then
            sourceQuality = item.quality
        elseif item.quality ~= sourceQuality then
            return nil, "五件材料必须为相同品质"
        end
        floorTotal = floorTotal + math.max(1, math.floor(item.floor or 1))
    end

    local resultQuality = EQUIPMENT_SYNTHESIS_RESULT_QUALITY[sourceQuality]
    if resultQuality == nil then
        return nil, "该品质不能合成"
    end

    local averageFloor = math.floor(floorTotal / #materials)
    local resultFloor = averageFloor + (sourceQuality == "red" and 10 or 0)
    return {
        sourceQuality = sourceQuality,
        resultQuality = resultQuality,
        averageFloor = averageFloor,
        resultFloor = resultFloor,
        ancientChance = EQUIPMENT_SYNTHESIS_ANCIENT_CHANCE[sourceQuality] or 0,
        cost = EQUIPMENT_SYNTHESIS_GOLD_COST[sourceQuality] or 0,
        materialCount = #materials,
    }, nil
end

function SynthesizeEquipment(materials)
    if type(materials) ~= "table" or #materials ~= 5 then
        return nil, "必须选择恰好5件装备"
    end

    local preview, previewError = GetEquipmentSynthesisPreview(materials)
    if preview == nil then
        return nil, previewError
    end
    if (playerData.gold or 0) < (preview.cost or 0) then
        return nil, "金币不足，需要 " .. tostring(preview.cost or 0) .. " 金币"
    end

    local inventory = playerData.inventory or {}
    local indices = {}
    local usedIndices = {}
    for _, material in ipairs(materials) do
        local foundIndex = nil
        for index, inventoryItem in ipairs(inventory) do
            if inventoryItem == material and not usedIndices[index] then
                foundIndex = index
                break
            end
        end
        if foundIndex == nil then
            return nil, "材料已不在背包，请重新选择"
        end
        local blockReason = GetEquipmentSynthesisBlockReason(inventory[foundIndex])
        if blockReason ~= nil then
            return nil, blockReason
        end
        usedIndices[foundIndex] = true
        table.insert(indices, foundIndex)
    end

    local slotDef = EQUIPMENT_SLOT_DEFS[math.random(1, #EQUIPMENT_SLOT_DEFS)]
    local ancientRoll = math.random(1, 100)
    local ancient = ancientRoll <= preview.ancientChance
    local result = GenerateEquipment(
        slotDef.id,
        preview.resultQuality,
        preview.resultFloor,
        ancient,
        true
    )
    result.synthesized = true

    playerData.gold = math.max(0, (playerData.gold or 0) - (preview.cost or 0))
    table.sort(indices, function(a, b) return a > b end)
    for _, index in ipairs(indices) do
        table.remove(inventory, index)
    end
    table.insert(inventory, result)

    saveDirty = true
    SaveCloudData(true)
    print(
        "[EquipmentSynthesis] 合成成功:",
        preview.sourceQuality,
        "->",
        preview.resultQuality,
        "层数:",
        preview.resultFloor,
        "部位:",
        slotDef.id,
        "太古:",
        ancient,
        "概率点数:",
        ancientRoll
    )
    return result, nil
end

function CreateEmptyEquipmentSet()
    local set = {}
    for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS) do
        set[slotDef.id] = nil
    end
    return set
end

EQUIPMENT_SET_NAMES = { "主套", "备用1", "备用2" }
EQUIPMENT_SET_COUNT = 3

function NormalizeEquipmentSet(set)
    if type(set) ~= "table" then
        set = CreateEmptyEquipmentSet()
    end
    for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS) do
        local item = set[slotDef.id]
        if item and (item.quality == nil or item.baseAffix == nil or item.slot == nil) then
            local repairedItem = GenerateEquipment(slotDef.id, "blue", 1)
            repairedItem.viewed = true
            AddRecoveredEquipmentToInventory(repairedItem, "损坏装备修复")
            set[slotDef.id] = nil
        elseif item then
            item.slot = slotDef.id
            if item.slot == "weapon" then
                item.weaponUpgradeLevel = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, item.weaponUpgradeLevel or 0))
            elseif item.slot == "armor" then
                item.armorUpgradeLevel = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, item.armorUpgradeLevel or 0))
            elseif item.slot == "boots" then
                item.bootsUpgradeLevel = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, item.bootsUpgradeLevel or 0))
            elseif item.slot == "gloves" then
                item.glovesUpgradeLevel = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, item.glovesUpgradeLevel or 0))
            elseif item.slot == "ring" then
                item.ringUpgradeLevel = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, item.ringUpgradeLevel or 0))
            end
            NormalizeEquipmentName(item)
            if NormalizeAncientEquipment(item) then
                saveDirty = true
            end
            NormalizeWeaponVisual(item)
            EnsureColorfulFixedAffix(item)
            NormalizeEquipmentRefineState(item)
        end
    end
    return set
end

function IsEquipmentLikeItem(item, fallbackSlot)
    if type(item) ~= "table" then return false end
    local slot = item.slot or fallbackSlot
    if type(slot) ~= "string" or EQUIPMENT_SLOT_BY_ID[slot] == nil then return false end
    return item.type == "equipment" or item.quality ~= nil or item.baseAffix ~= nil or item.affixes ~= nil or item.name ~= nil
end

function GetEquipmentItemSlot(item, fallbackSlot)
    local slot = type(item) == "table" and (item.slot or fallbackSlot) or nil
    if type(slot) == "string" and EQUIPMENT_SLOT_BY_ID[slot] ~= nil then
        return slot
    end
    return nil
end

function ExtractEquipmentSet(source)
    local result = CreateEmptyEquipmentSet()
    local count = 0
    local function addItem(item, fallbackSlot)
        if not IsEquipmentLikeItem(item, fallbackSlot) then return end
        local slot = GetEquipmentItemSlot(item, fallbackSlot)
        if slot == nil or result[slot] ~= nil then return end
        item.type = "equipment"
        item.slot = slot
        result[slot] = item
        count = count + 1
    end
    local function scan(container)
        if type(container) ~= "table" then return end
        for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS) do
            addItem(container[slotDef.id], slotDef.id)
            addItem(container[tostring(slotDef.id)], slotDef.id)
        end
        for _, value in pairs(container) do
            addItem(value, nil)
        end
    end
    if type(source) == "table" then
        scan(source)
        scan(source.equipment)
        scan(source.slots)
        scan(source.items)
        scan(source.data)
        if type(source.equipment) == "table" then
            scan(source.equipment.equipment)
            scan(source.equipment.slots)
        end
    end
    return result, count
end

function IsEquipmentSetEmpty(set)
    return CountEquipmentItems(set) <= 0
end

function CountEquipmentItems(set)
    local _, count = ExtractEquipmentSet(set)
    return count
end

function CountEquipmentSetsItems(sets)
    local count = 0
    if type(sets) ~= "table" then return 0 end
    count = count + CountEquipmentItems(sets)
    local wrapped = sets.equipmentSets or sets.equipment_sets or sets.sets
    if type(wrapped) == "table" then
        sets = wrapped
    end
    for index = 1, EQUIPMENT_SET_COUNT do
        count = count + CountEquipmentItems(sets[index]) + CountEquipmentItems(sets[tostring(index)])
    end
    return count
end

function MaybeSetLegacyEquipment(equipment, source)
    if type(equipment) ~= "table" then return false end
    local normalized, newCount = ExtractEquipmentSet(equipment)
    local oldCount = CountEquipmentItems(playerData.legacyEquipment)
    if newCount > oldCount then
        playerData.legacyEquipment = normalized
        print("[EquipmentSet] 记录旧装备恢复源:", source or "unknown", "数量:", newCount)
        return true
    end
    return false
end

function GetLegacyEquipmentForMigration()
    local best = nil
    local bestCount = 0
    if type(playerData.legacyEquipment) == "table" then
        best = playerData.legacyEquipment
        bestCount = CountEquipmentItems(best)
    end
    if type(playerData.equipment) == "table" then
        local isActiveSetRef = false
        if type(playerData.equipmentSets) == "table" then
            for index = 1, EQUIPMENT_SET_COUNT do
                if playerData.equipment == playerData.equipmentSets[index] or playerData.equipment == playerData.equipmentSets[tostring(index)] then
                    isActiveSetRef = true
                    break
                end
            end
        end
        if not isActiveSetRef then
            local equipmentCount = CountEquipmentItems(playerData.equipment)
            if equipmentCount > bestCount then
                best = playerData.equipment
                bestCount = equipmentCount
            end
        end
    end
    if bestCount <= 0 then return nil end
    return best
end

function RestoreBestInventoryEquipmentToMainSet()
    if type(playerData.inventory) ~= "table" or type(playerData.equipmentSets) ~= "table" then return 0 end
    local mainSet = playerData.equipmentSets[1]
    if type(mainSet) ~= "table" or not IsEquipmentSetEmpty(mainSet) then return 0 end
    local bestBySlot = {}
    local bestIndexBySlot = {}
    for index, item in ipairs(playerData.inventory) do
        if IsEquipmentLikeItem(item, item and item.slot or nil) then
            item.type = "equipment"
            local slot = GetEquipmentItemSlot(item, item.slot)
            local old = bestBySlot[slot]
            if slot ~= nil and (old == nil or GetEquipmentScore(item) > GetEquipmentScore(old)) then
                bestBySlot[slot] = item
                bestIndexBySlot[slot] = index
            end
        end
    end
    local indices = {}
    for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS) do
        local item = bestBySlot[slotDef.id]
        if item ~= nil then
            mainSet[slotDef.id] = item
            table.insert(indices, bestIndexBySlot[slotDef.id])
        end
    end
    table.sort(indices, function(a, b) return a > b end)
    for _, index in ipairs(indices) do
        table.remove(playerData.inventory, index)
    end
    if #indices > 0 then
        print("[EquipmentSet] 主套为空，已从背包恢复最佳装备，数量:", #indices)
        saveDirty = true
    end
    return #indices
end

function NormalizeEquipmentSets()
    playerData.inventory = playerData.inventory or {}
    local oldEquipment = GetLegacyEquipmentForMigration()
    if oldEquipment ~= nil then
        MaybeSetLegacyEquipment(oldEquipment, "playerData.equipment")
    end
    if type(playerData.equipmentSets) ~= "table" then
        playerData.equipmentSets = {}
    else
        local wrappedSets = playerData.equipmentSets.equipmentSets or playerData.equipmentSets.equipment_sets or playerData.equipmentSets.sets
        if type(wrappedSets) == "table" then
            playerData.equipmentSets = wrappedSets
        end
    end
    for index = 1, EQUIPMENT_SET_COUNT do
        if type(playerData.equipmentSets[index]) ~= "table" and type(playerData.equipmentSets[tostring(index)]) == "table" then
            playerData.equipmentSets[index] = playerData.equipmentSets[tostring(index)]
            playerData.equipmentSets[tostring(index)] = nil
        end
        if type(playerData.equipmentSets[index]) ~= "table" then
            playerData.equipmentSets[index] = CreateEmptyEquipmentSet()
        end
    end
    if oldEquipment ~= nil then
        local mainSet = playerData.equipmentSets[1]
        local extractedOld = ExtractEquipmentSet(oldEquipment)
        local recovered = 0
        for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS) do
            if mainSet[slotDef.id] == nil and extractedOld[slotDef.id] ~= nil then
                mainSet[slotDef.id] = extractedOld[slotDef.id]
                recovered = recovered + 1
            end
        end
        if recovered > 0 then
            print("[EquipmentSet] 已从旧装备字段恢复到主套，数量:", recovered)
            saveDirty = true
        end
    end
    for index = 1, EQUIPMENT_SET_COUNT do
        playerData.equipmentSets[index] = ExtractEquipmentSet(playerData.equipmentSets[index])
        playerData.equipmentSets[index] = NormalizeEquipmentSet(playerData.equipmentSets[index])
    end
    playerData.legacyEquipment = nil
    RestoreBestInventoryEquipmentToMainSet()

    local extraSetKeys = {}
    for key, value in pairs(playerData.equipmentSets) do
        local numericIndex = tonumber(key)
        local isIntegerIndex = numericIndex ~= nil and numericIndex == math.floor(numericIndex)
        local isSupportedNumericKey = type(key) == "number"
            and numericIndex >= 1 and numericIndex <= EQUIPMENT_SET_COUNT
        if type(value) == "table" and isIntegerIndex and not isSupportedNumericKey then
            table.insert(extraSetKeys, key)
        end
    end
    table.sort(extraSetKeys, function(a, b)
        local numberA = tonumber(a) or 0
        local numberB = tonumber(b) or 0
        if numberA ~= numberB then return numberA < numberB end
        return tostring(a) < tostring(b)
    end)
    for _, key in ipairs(extraSetKeys) do
        local extractedSet, extractedCount = ExtractEquipmentSet(playerData.equipmentSets[key])
        for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS) do
            local item = extractedSet[slotDef.id]
            if item ~= nil then
                AddRecoveredEquipmentToInventory(item, "多余装备方案" .. tostring(key))
            end
        end
        playerData.equipmentSets[key] = nil
        saveDirty = true
        print("[EquipmentRecovery] 已处理多余装备方案:", tostring(key), "有效装备:", extractedCount)
    end
    playerData.activeEquipmentSetIndex = math.max(1, math.min(EQUIPMENT_SET_COUNT, math.floor(playerData.activeEquipmentSetIndex or 1)))
    playerData.equipment = playerData.equipmentSets[playerData.activeEquipmentSetIndex]
end

function GetActiveEquipmentSetIndex()
    NormalizeEquipmentSets()
    return playerData.activeEquipmentSetIndex or 1
end

function GetActiveEquipmentSetName()
    return EQUIPMENT_SET_NAMES[GetActiveEquipmentSetIndex()] or "装备套"
end

function GetActiveEquipment()
    NormalizeEquipmentSets()
    return playerData.equipment
end

function GetEquipmentResonanceDef(setId)
    if type(setId) ~= "string" then return nil end
    return (EQUIPMENT_RESONANCE_DEFS or {})[setId]
end

function GetEquipmentResonanceSetId(item)
    if item == nil or item.type ~= "equipment" then return nil end
    local setId = item.resonanceSetId
    if GetEquipmentResonanceDef(setId) == nil then return nil end
    return setId
end

function CountEquipmentResonanceSets(
    equipment,
    replacementItem,
    replacementSlot
)
    local counts = {}
    for _, setId in ipairs(EQUIPMENT_RESONANCE_ORDER or {}) do
        counts[setId] = 0
    end
    for slotId, equippedItem in pairs(equipment or {}) do
        local item = equippedItem
        if replacementSlot ~= nil and slotId == replacementSlot then
            item = replacementItem
        end
        local setId = GetEquipmentResonanceSetId(item)
        if setId ~= nil then
            counts[setId] = (counts[setId] or 0) + 1
        end
    end
    if replacementSlot ~= nil
        and (equipment or {})[replacementSlot] == nil
    then
        local setId = GetEquipmentResonanceSetId(replacementItem)
        if setId ~= nil then
            counts[setId] = (counts[setId] or 0) + 1
        end
    end
    return counts
end

function GetActiveEquipmentResonanceCounts()
    return CountEquipmentResonanceSets(GetActiveEquipment())
end

function GetEquipmentResonanceCount(setId)
    local counts = GetActiveEquipmentResonanceCounts()
    return counts[setId] or 0
end

function GetMixedEquipmentResonance(counts)
    counts = counts or {}
    local activeSetIds = {}
    for _, setId in ipairs(EQUIPMENT_RESONANCE_ORDER or {}) do
        if (counts[setId] or 0) >= 2 then
            table.insert(activeSetIds, setId)
        end
    end
    if #activeSetIds ~= 2 then return nil, nil end
    for mixedId, def in pairs(MIXED_EQUIPMENT_RESONANCE_DEFS or {}) do
        local setIds = def.setIds or {}
        if setIds[1] == activeSetIds[1]
            and setIds[2] == activeSetIds[2]
        then
            return mixedId, def
        end
    end
    return nil, nil
end

function ApplyMixedEquipmentResonanceBonus(stats, counts)
    local mixedId, mixedDef = GetMixedEquipmentResonance(counts)
    stats.mixedResonanceId = mixedId
    stats.mixedResonanceName = mixedDef and mixedDef.name or nil
    stats.mixedResonanceEffect = mixedDef and mixedDef.effect or nil
    if mixedDef == nil then return end
    for stat, value in pairs(mixedDef.bonuses or {}) do
        stats[stat] = (stats[stat] or 0) + value
    end
end

function ApplyEquipmentResonanceBonuses(stats, counts)
    counts = counts or {}
    stats.resonanceCounts = counts

    local berserkerCount = counts.berserker or 0
    if berserkerCount >= 2 then
        stats.attackPercent = (stats.attackPercent or 0) + 6
    end
