        stats.hpPercent = (stats.hpPercent or 0) + 9
    end
    if bulwarkCount >= 3 then
        stats.damageReductionPercent =
            (stats.damageReductionPercent or 0) + 5
    end
    if bulwarkCount >= 4 then
        stats.hpPercent = (stats.hpPercent or 0) + 13
        stats.damageReductionPercent =
            (stats.damageReductionPercent or 0) + 4
    end
    if bulwarkCount >= 5 then
        stats.damageReductionPercent =
            (stats.damageReductionPercent or 0) + 5
        stats.bulwarkEmergencyRecovery = true
    end

    local swiftCount = counts.swift or 0
    if swiftCount >= 2 then
        stats.attackSpeedPercent =
            (stats.attackSpeedPercent or 0) + 6
    end
    if swiftCount >= 3 then
        stats.attackRangePercent =
            (stats.attackRangePercent or 0) + 8
    end
    if swiftCount >= 4 then
        stats.attackSpeedPercent =
            (stats.attackSpeedPercent or 0) + 11
        stats.attackRangePercent =
            (stats.attackRangePercent or 0) + 11
    end
    if swiftCount >= 5 then
        stats.attackCount = (stats.attackCount or 0) + 3
        stats.attackRangePercent =
            (stats.attackRangePercent or 0) + 11
    end

    local arcaneCount = counts.arcane or 0
    if arcaneCount >= 2 then
        stats.skillDamagePercent =
            (stats.skillDamagePercent or 0) + 9
    end
    if arcaneCount >= 3 then
        stats.skillCooldownPercent =
            (stats.skillCooldownPercent or 0) + 6
    end
    if arcaneCount >= 4 then
        stats.skillDamagePercent =
            (stats.skillDamagePercent or 0) + 15
        stats.skillCooldownPercent =
            (stats.skillCooldownPercent or 0) + 5
    end
    if arcaneCount >= 5 then
        stats.skillDamagePercent =
            (stats.skillDamagePercent or 0) + 15
    end

    local spiritCount = counts.spirit or 0
    if spiritCount >= 2 then
        stats.cloneDamagePercent =
            (stats.cloneDamagePercent or 0) + 7
    end
    if spiritCount >= 3 then
        stats.cloneAttackSpeedPercent =
