function SetActiveEquipmentSetIndex(index)
    index = math.max(1, math.min(EQUIPMENT_SET_COUNT, math.floor(index or 1)))
    NormalizeEquipmentSets()
    if playerData.activeEquipmentSetIndex == index then
        PrintActiveEquipmentSetStatsLog("重复点击当前套")
        return true
    end
    if currentScreen == "playing" then
        AddEffect({ type = "drop", x = screenW * 0.5, y = screenH * 0.35, text = "战斗中不能切换装备套", life = 1.1, maxLife = 1.1 })
        return false
    end
    playerData.activeEquipmentSetIndex = index
    playerData.equipment = playerData.equipmentSets[index]
    PrintActiveEquipmentSetStatsLog("切换后")
    MarkSaveDirty()
    SaveCloudData(true)
    print("[EquipmentSet] 切换到", GetActiveEquipmentSetName())
    return true
end

function NormalizeEquipmentViewedState(item)
    if item == nil or item.type ~= "equipment" or item.viewed ~= nil then
        return false
    end
    item.viewed = true
    return true
end

function MarkEquipmentViewed(item)
    if item == nil or item.type ~= "equipment" or item.viewed ~= false then
        return false
    end
    item.viewed = true
    MarkSaveDirty()
    print("[Equipment] 已查看:", GetEquipmentDisplayName(item))
    return true
end

NormalizeEquipment = function()
    NormalizeEquipmentSets()
    local migrated = false
    local nextUid = math.max(1, math.floor(tonumber(playerData.nextEquipmentUid) or 1))
    local seenUids = {}
    local function NormalizeEquipmentUid(item)
        if item == nil or item.type ~= "equipment" then return false end
        local uid = math.floor(tonumber(item.uid) or 0)
        if uid <= 0 or seenUids[uid] then
            while seenUids[nextUid] do nextUid = nextUid + 1 end
            item.uid = nextUid
            seenUids[nextUid] = true
            nextUid = nextUid + 1
            return true
        end
        seenUids[uid] = true
        nextUid = math.max(nextUid, uid + 1)
        return false
    end
    for _, set in ipairs(playerData.equipmentSets or {}) do
        for _, item in pairs(set) do
            if item and item.type == "equipment" then
                migrated = NormalizeEquipmentUid(item) or migrated
                migrated = NormalizeEquipmentName(item) or migrated
                migrated = NormalizeAncientEquipment(item) or migrated
                migrated = NormalizeWeaponVisual(item) or migrated
                migrated = EnsureColorfulFixedAffix(item) or migrated
                migrated = NormalizeEquipmentRefineState(item) or migrated
                migrated = NormalizeEquipmentViewedState(item) or migrated
            end
        end
    end
    for _, item in ipairs(playerData.inventory) do
        if item.type == "equipment" then
            migrated = NormalizeEquipmentUid(item) or migrated
            migrated = NormalizeEquipmentName(item) or migrated
            migrated = NormalizeAncientEquipment(item) or migrated
            migrated = NormalizeWeaponVisual(item) or migrated
            migrated = EnsureColorfulFixedAffix(item) or migrated
            migrated = NormalizeEquipmentRefineState(item) or migrated
            migrated = NormalizeEquipmentViewedState(item) or migrated
        else
            migrated = NormalizeRefineStoneItem(item) or migrated
            migrated = NormalizePinkRefineStoneItem(item) or migrated
            migrated = NormalizeSocketPuncherItem(item) or migrated
        end
    end
    playerData.nextEquipmentUid = nextUid
    migrated = NormalizeRefineStoneStacks() or migrated
    migrated = NormalizePinkRefineStoneStacks() or migrated
    migrated = NormalizeSocketPuncherStacks() or migrated
    if migrated then
        saveDirty = true
    end
end

ADMIN_HIDDEN_SUCCESS_RATE_BONUS = 0.10

function GetHiddenAdminSuccessRateBonus()
    if IS_CLOUD_ADMIN ~= true
        or CLOUD_BANLIST_LOADED ~= true
        or clientCloud == nil
        or CLOUD_ADMIN_UID == nil then
        return 0
    end
    local myUid = tostring(clientCloud.userId or "")
    if myUid == "" or tostring(CLOUD_ADMIN_UID) ~= myUid then
        return 0
    end
    return ADMIN_HIDDEN_SUCCESS_RATE_BONUS
end

function GetEffectiveHiddenAdminSuccessRate(baseRate)
    return math.min(1, math.max(0, baseRate or 0) + GetHiddenAdminSuccessRateBonus())
end

function GetWeaponUpgradeAttackPercent(level)
    level = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, level or 0))
    return level * 7
end

function GetWeaponUpgradeRangePercent(level)
    level = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, level or 0))
    return level * CONFIG.WeaponRangePercentPerLevel
end

function GetWeaponUpgradeSuccessRate(level)
    level = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, level or 0))
    return math.max(0, 95 - level * CONFIG.WeaponUpgradeSuccessDropPerLevel)
end

function GetEquipmentUpgradeFloorMultiplier(floor)
    if type(floor) == "table" then
        floor = floor.floor
    end
    floor = math.max(1, math.floor(floor or 1))
    local step = CONFIG.FloorUpgradeTierStep or 100
    local mult = CONFIG.FloorUpgradeTierMult or 1.5
    local tier = math.floor((floor - 1) / step)
    return mult ^ tier
end

function GetWeaponUpgradeCost(level, floor)
    level = math.max(0, level or 0)
    local base = CONFIG.WeaponUpgradeCostBase * (level + 1) * (level + 1)
    local highLevelStart = CONFIG.EquipmentUpgradeHighLevelStart or 15
    local highLevelMult = CONFIG.EquipmentUpgradeHighLevelMult or 1.3
    local highLevelTier = math.max(0, level - highLevelStart + 1)
    return math.floor(base * GetEquipmentUpgradeFloorMultiplier(floor) * highLevelMult ^ highLevelTier)
end

local EQUIPMENT_UPGRADE_META = {
    weapon = { field = "weaponUpgradeLevel", name = "武器" },
    armor = { field = "armorUpgradeLevel", name = "盔甲" },
    boots = { field = "bootsUpgradeLevel", name = "鞋子" },
    gloves = { field = "glovesUpgradeLevel", name = "护手" },
    ring = { field = "ringUpgradeLevel", name = "戒指" },
}

function MergeEquipmentUpgradeProtectionState(
    dayKey,
    claimCount,
    pending,
    resolvedId,
    nextEquipmentUid
)
    local incomingDay = tostring(dayKey or "")
    local localDay = tostring(playerData.dailyEquipmentUpgradeAdClaimDayKey or "")
    local incomingCount = math.max(0, math.floor(tonumber(claimCount) or 0))
    if incomingDay ~= "" then
        if incomingDay > localDay then
            playerData.dailyEquipmentUpgradeAdClaimDayKey = incomingDay
            playerData.dailyEquipmentUpgradeAdClaimCount = incomingCount
        elseif incomingDay == localDay then
            playerData.dailyEquipmentUpgradeAdClaimCount = math.max(
                playerData.dailyEquipmentUpgradeAdClaimCount or 0,
                incomingCount
            )
        end
    end

    local mergedResolvedId = math.max(
        math.floor(tonumber(playerData.equipmentUpgradePenaltyResolvedId) or 0),
        math.floor(tonumber(resolvedId) or 0)
    )
    playerData.equipmentUpgradePenaltyResolvedId = mergedResolvedId

    local localPending = type(playerData.pendingEquipmentUpgradePenalty) == "table"
        and playerData.pendingEquipmentUpgradePenalty or nil
    local incomingPending = type(pending) == "table" and pending or nil
    local localPendingId = math.floor(tonumber(localPending and localPending.id) or 0)
    local incomingPendingId = math.floor(tonumber(incomingPending and incomingPending.id) or 0)
    local selectedPending = localPendingId >= incomingPendingId
        and localPending or incomingPending
    local selectedPendingId = math.max(localPendingId, incomingPendingId)
    playerData.pendingEquipmentUpgradePenalty = selectedPendingId > mergedResolvedId
        and selectedPending or nil

    playerData.nextEquipmentUid = math.max(
        1,
        math.floor(tonumber(playerData.nextEquipmentUid) or 1),
        math.floor(tonumber(nextEquipmentUid) or 1)
    )
    NormalizeDailyEquipmentUpgradeAdQuota()
end

function FindEquipmentByUid(uid)
    uid = math.floor(tonumber(uid) or 0)
    if uid <= 0 then return nil, nil end
    for _, set in ipairs(playerData.equipmentSets or {}) do
        for slotId, item in pairs(set) do
            if item and item.type == "equipment" and item.uid == uid then
                return item, slotId
            end
        end
    end
    for index, item in ipairs(playerData.inventory or {}) do
        if item and item.type == "equipment" and item.uid == uid then
            return item, index
        end
    end
    return nil, nil
end

function ResolvePendingEquipmentUpgradePenalty(keepLevel, reason)
    local pending = playerData.pendingEquipmentUpgradePenalty
    if type(pending) ~= "table" then return false end
    local penaltyId = math.max(0, math.floor(tonumber(pending.id) or 0))
    if penaltyId <= math.max(0, math.floor(tonumber(playerData.equipmentUpgradePenaltyResolvedId) or 0)) then
        playerData.pendingEquipmentUpgradePenalty = nil
        return false
    end
    local item = FindEquipmentByUid(pending.equipmentUid)
    local restoreLevel = math.floor(tonumber(pending.restoreLevel) or 0)
    if restoreLevel > 0 then
        -- 新格式：失败时已立即降级，这里只需处理广告恢复
        if keepLevel == true and item ~= nil then
            local field = tostring(pending.field or "")
            if field ~= "" then
                -- 只升不降：不覆盖玩家在降级后继续强化得到的更高等级
                item[field] = math.max(item[field] or 0, restoreLevel)
            end
        end
        playerData.equipmentUpgradePenaltyResolvedId = penaltyId
        playerData.pendingEquipmentUpgradePenalty = nil
        weaponUpgradeMessage = keepLevel == true
            and "广告观看完成，强化等级已恢复"
            or "强化已降级"
        saveDirty = true
        SaveCloudData(true)
        print("[EquipmentUpgradeAd] 强化惩罚已结算, id=", penaltyId,
            "恢复=", keepLevel == true, "原因=", tostring(reason))
        return true
    end
    -- 旧格式（仅 level）：延迟降级，兼容老存档
    if item ~= nil and keepLevel ~= true then
        local field = tostring(pending.field or "")
        if field ~= "" then
            local expectedLevel = math.max(0, math.floor(tonumber(pending.level) or 0))
            item[field] = math.max(0, expectedLevel - 1)
        end
    elseif item == nil then
        -- 找不到装备时保留罚单，避免静默丢失
        print("[EquipmentUpgradeAd] 旧格式罚单未找到装备 uid=", tostring(pending.equipmentUid), "，保留罚单待后续结算")
        return false
    end
    playerData.equipmentUpgradePenaltyResolvedId = penaltyId
    playerData.pendingEquipmentUpgradePenalty = nil
    weaponUpgradeMessage = keepLevel == true
        and "广告观看完成，强化等级保持不变"
        or "强化失败，等级下降1级"
    saveDirty = true
    SaveCloudData(true)
    print("[EquipmentUpgradeAd] 待处理强化已结算, id=", penaltyId,
        "保级=", keepLevel == true, "原因=", tostring(reason))
    return true
end

function ResolvePendingEquipmentUpgradePenaltyOnLoad()
    if type(playerData.pendingEquipmentUpgradePenalty) ~= "table" then return false end
    -- 强化失败保护弹窗正在展示时，不自动兜底结算：
    -- 若此时结算会吃掉罚单，玩家看完广告也无法恢复等级（表现为"广告点不了/没用"）。
    -- 恢复机会留给弹窗内的广告流程，或玩家主动关闭弹窗时再确认降级。
    if equipmentUpgradeProtectionModal ~= nil then
        print("[EquipmentUpgradeAd] 强化失败弹窗正在展示，跳过云同步兜底结算")
        return false
    end
    print("[EquipmentUpgradeAd] 检测到未完成的强化恢复罚单，进行兜底结算")
    return ResolvePendingEquipmentUpgradePenalty(false, "restart")
end

function ShowEquipmentUpgradeProtectionModal(item, inventoryIndex)
    local pending = playerData.pendingEquipmentUpgradePenalty
    if type(pending) ~= "table" or equipmentUpgradeProtectionModal ~= nil then return end
    local settled = false
    local modal
    local function Settle(keepLevel, reason)
        if settled then return end
        settled = true
        ResolvePendingEquipmentUpgradePenalty(keepLevel, reason)
        if modal ~= nil then modal:Close() end
        equipmentUpgradeProtectionModal = nil
        if item ~= nil and ShowEquippedItemDetail ~= nil then
            ShowEquippedItemDetail(item, item.slot, inventoryIndex)
        end
    end
    -- 广告按钮下方的提示文案（失败/加载中/超时时展示，固定高度避免布局跳动）
    local hintLabel = UI.Label {
        text = "",
        fontSize = 10,
        height = 14,
        fontColor = PX and PX.textGold or { 245, 200, 92, 255 },
        textAlign = "center",
        whiteSpace = "normal",
    }
    modal = UI.Modal {
        title = "强化失败",
        size = "sm",
        isOpen = false,
        closeOnOverlay = false,
        closeOnEscape = true,
        showCloseButton = true,
        contentPadding = 14,
        contentGap = 10,
        onClose = function(self)
            if not settled then
                settled = true
                ResolvePendingEquipmentUpgradePenalty(false, "close")
                if item ~= nil and ShowEquippedItemDetail ~= nil then
                    ShowEquippedItemDetail(item, item.slot, inventoryIndex)
                end
            end
            equipmentUpgradeProtectionModal = nil
            self:Destroy()
        end,
        children = {
            UI.Label {
                text = "强化失败等级已下降1级；看广告可恢复原等级，关闭或未完整观看将保持降级。",
                fontSize = 12,
                fontColor = PX and PX.textGray or { 210, 210, 220, 255 },
                textAlign = "center",
                whiteSpace = "normal",
            },
            UI.Label {
                text = "今日强化保护剩余 " .. tostring(GetDailyEquipmentUpgradeAdRemaining())
                    .. "/" .. tostring(DAILY_EQUIPMENT_UPGRADE_AD_MAX_CLAIMS),
                fontSize = 11,
                fontColor = PX and PX.textGold or { 245, 200, 92, 255 },
                textAlign = "center",
            },
            UI.Button {
                width = "100%",
                text = "看广告恢复等级",
                variant = "primary",
                onClick = function(self)
                    if settled then return end
                    if rewardAdInFlight then
                        -- 上次请求已超时未复位 → 先复位，随后直接重新发起
                        if rewardAdDeadline > 0 and os.clock() >= rewardAdDeadline then
                            rewardAdFlowEnded = true
                            FinishRewardAd({ success = false, msg = "广告响应超时" })
                        else
                            hintLabel:SetText("广告正在加载，请稍候…")
                            return
                        end
                    end
                    self:SetDisabled(true)
                    hintLabel:SetText("")
                    ShowRewardAd(function(success, msg)
                        if settled then return end
                        if success and ConsumeDailyEquipmentUpgradeAdClaim() then
                            Settle(true, "ad_success")
                        else
                            -- 广告失败：恢复按钮并提示，保留弹窗供玩家重试或关闭确认降级
                            self:SetDisabled(false)
                            hintLabel:SetText(GetRewardAdFailureMessage(msg))
                        end
                    end)
                end,
            },
            hintLabel,
        },
    }
    equipmentUpgradeProtectionModal = modal
    print("[EquipmentUpgradeAd] 显示强化失败保护弹窗, 等级:", pending.level)
    modal:Open()
end

function TryUpgradeEquipment(item, inventoryIndex, protected)
    if item == nil or item.type ~= "equipment" then return end
    local meta = EQUIPMENT_UPGRADE_META[item.slot]
    if meta == nil then return end
    local level = math.max(
        0,
        math.min(CONFIG.WeaponUpgradeMaxLevel, item[meta.field] or 0)
    )
    item[meta.field] = level
    if level >= CONFIG.WeaponUpgradeMaxLevel then
        weaponUpgradeMessage = meta.name .. "强化已满级"
        ShowEquippedItemDetail(item, item.slot, inventoryIndex)
        return
    end

    if protected == true
        and level > (CONFIG.EquipmentProtectedUpgradeMaxLevel or 16) then
        weaponUpgradeMessage = "保底强化仅可在+0至+"
            .. tostring(CONFIG.EquipmentProtectedUpgradeMaxLevel or 16)
            .. "使用"
        ShowEquippedItemDetail(item, item.slot, inventoryIndex)
        return
    end

    local baseCost = GetWeaponUpgradeCost(level, item)
    local cost = protected == true and baseCost * 3 or baseCost
    if playerData.gold < cost then
        weaponUpgradeMessage = "金币不足，需要" .. tostring(cost)
        ShowEquippedItemDetail(item, item.slot, inventoryIndex)
        return
    end

    playerData.gold = playerData.gold - cost
    local baseSuccessRate = GetWeaponUpgradeSuccessRate(level) / 100
    local successRate = GetEffectiveHiddenAdminSuccessRate(baseSuccessRate)
    local succeeded = math.random() < successRate
    if succeeded then
        item[meta.field] = level + 1
        weaponUpgradeMessage = "强化成功！" .. meta.name .. "强化等级+1"
    elseif protected == true then
        weaponUpgradeMessage = "保底强化失败，等级保持不变"
    elseif level >= EQUIPMENT_UPGRADE_AD_MIN_LEVEL
        and GetDailyEquipmentUpgradeAdRemaining() > 0
        and (CanClaimDailyRewardAd == nil or CanClaimDailyRewardAd()) then
        NormalizeEquipment()
        local penaltyId = math.max(
            os.time(),
            math.floor(tonumber(playerData.equipmentUpgradePenaltyResolvedId) or 0) + 1
        )
        -- 方案A：失败当场降级，罚单仅记录可恢复等级（看广告恢复）
        item[meta.field] = math.max(0, level - 1)
        if inventoryIndex ~= nil and not IsAncientEquipment(item) then item.locked = true end
        playerData.pendingEquipmentUpgradePenalty = {
            id = penaltyId,
            equipmentUid = item.uid,
            field = meta.field,
            restoreLevel = level,
            level = level,
            createdAt = os.time(),
        }
        weaponUpgradeMessage = "强化失败降级，可看广告恢复等级"
        saveDirty = true
        SaveCloudData(true)
        print("[EquipmentUpgradeAd] 强化失败已降级待恢复, id=", penaltyId,
            "uid=", item.uid, "降级=", level, "->", item[meta.field],
            "可恢复至=", level)
        ShowEquipmentUpgradeProtectionModal(item, inventoryIndex)
        return
    else
        item[meta.field] = math.max(0, level - 1)
        weaponUpgradeMessage = "强化失败，等级下降1级"
    end
    if inventoryIndex ~= nil and not IsAncientEquipment(item) then item.locked = true end
    saveDirty = true
    SaveCloudData(true)
    print(
        "[EquipmentUpgrade]", meta.name,
        protected == true and "保底强化" or "普通强化",
        succeeded and "成功" or "失败",
        "等级:", level, "->", item[meta.field],
        "消耗:", cost
    )
    ShowEquippedItemDetail(item, item.slot, inventoryIndex)
end

