local WING_BONUSES = {
    [0] = { tier = 0, label = "无", moveSpeed = 0, attackSpeed = 0 },
    [1] = { tier = 1, label = "小翅膀", moveSpeed = 10, attackSpeed = 10 },
    [2] = { tier = 2, label = "大翅膀", moveSpeed = 20, attackSpeed = 20 },
}

function GetWingBonus()
    if GetActiveEquipment == nil then return WING_BONUSES[0] end
    local equipment = GetActiveEquipment()
    if equipment == nil then return WING_BONUSES[0] end
    local weapon = equipment.weapon
    local armor = equipment.armor
    local boots = equipment.boots
    local gloves = equipment.gloves
    local ring = equipment.ring
    if weapon == nil or armor == nil or boots == nil or gloves == nil or ring == nil then
        return WING_BONUSES[0]
    end
    local weaponLevel = math.max(0, math.floor(weapon.weaponUpgradeLevel or 0))
    local armorLevel = math.max(0, math.floor(armor.armorUpgradeLevel or 0))
    local bootsLevel = math.max(0, math.floor(boots.bootsUpgradeLevel or 0))
    local glovesLevel = math.max(0, math.floor(gloves.glovesUpgradeLevel or 0))
    local ringLevel = math.max(0, math.floor(ring.ringUpgradeLevel or 0))
    if weaponLevel >= WING_BIG_THRESHOLD
        and armorLevel >= WING_BIG_THRESHOLD
        and bootsLevel >= WING_BIG_THRESHOLD
        and glovesLevel >= WING_BIG_THRESHOLD
        and ringLevel >= WING_BIG_THRESHOLD then
        return WING_BONUSES[2]
    end
    if weaponLevel >= WING_SMALL_THRESHOLD
        and armorLevel >= WING_SMALL_THRESHOLD
        and bootsLevel >= WING_SMALL_THRESHOLD
        and glovesLevel >= WING_SMALL_THRESHOLD
        and ringLevel >= WING_SMALL_THRESHOLD then
        return WING_BONUSES[1]
    end
    return WING_BONUSES[0]
end

function GetEquipmentStats()
    local stats = {
        attackFlat = 0,
        attackPercent = 0,
        critRate = 0,
        critDamage = 0,
        hpFlat = 0,
        luckPercent = 0,
        moveSpeedPercent = 0,
        attackSpeedPercent = 0,
        attackCount = 0,
        goldPercent = 0,
        bossDamagePercent = 0,
        awakeningDuration = 0,
        skillCooldownReduction = 0,
        skillCooldownPercent = 0,
        skillDamagePercent = 0,
        mageSkillMultiplierPercent = 0,
        attackRangePercent = 0,
        hpPercent = 0,
        doubleAttackChance = 0,
        easterEgg = 0,
        primaryAttackDamagePercent = 0,
        skillAreaPercent = 0,
        damageReductionPercent = 0,
        cloneDamagePercent = 0,
        cloneAttackSpeedPercent = 0,
        executeThresholdPercent = 0,
        resonanceCounts = {},
        bulwarkEmergencyRecovery = false,
    }

    for _, item in pairs(GetActiveEquipment() or {}) do
        if item then
            if item.atk then stats.attackFlat = stats.attackFlat + item.atk end
            if item.baseAffix then
                local def = EQUIPMENT_AFFIX_BY_ID[item.baseAffix.id]
                if def and stats[def.stat] ~= nil then
                    local value = item.baseAffix.value or 0
                    if item.slot == "weapon" and item.baseAffix.id == "attack_flat" then
                        value = math.floor(value * (1 + GetWeaponUpgradeAttackPercent(item.weaponUpgradeLevel or 0) / 100) + 0.5)
                    elseif item.slot == "armor" and item.baseAffix.id == "hp_flat" then
                        value = math.floor(value * (1 + GetArmorUpgradeHpPercent(item.armorUpgradeLevel or 0) / 100) + 0.5)
                    elseif item.slot == "boots" and item.baseAffix.id == "crit_damage" then
                        value = math.floor(value * (1 + GetBootsUpgradeCritDamagePercent(item.bootsUpgradeLevel or 0) / 100) + 0.5)
                    elseif item.slot == "gloves" and item.baseAffix.id == "crit_rate" then
                        value = value + GetGlovesUpgradeCritRatePercent(item.glovesUpgradeLevel or 0)
                    elseif item.slot == "ring" and item.baseAffix.id == "luck" then
                        value = value + GetRingUpgradeLuckPercent(item.ringUpgradeLevel or 0)
                    end
                    stats[def.stat] = stats[def.stat] + value
                end
            end
            for _, affix in ipairs(item.affixes or {}) do
                AddEquipmentAffixStats(stats, affix)
            end
        end
    end

    local wing = GetWingBonus()
    stats.wingTier = wing.tier
    stats.wingLabel = wing.label
    stats.wingMoveSpeed = wing.moveSpeed
    stats.wingAttackSpeed = wing.attackSpeed
    stats.moveSpeedPercent = (stats.moveSpeedPercent or 0) + wing.moveSpeed
    stats.attackSpeedPercent = (stats.attackSpeedPercent or 0) + wing.attackSpeed

    stats.skillDamagePercent = (stats.skillDamagePercent or 0) + GetSkillDamagePermanentBonus()
    stats.doubleAttackChance = math.min(20, stats.doubleAttackChance or 0)
    stats.primaryAttackDamagePercent = math.min(30, stats.primaryAttackDamagePercent or 0)
    stats.skillAreaPercent = math.min(15, stats.skillAreaPercent or 0)
    stats.damageReductionPercent = math.min(15, stats.damageReductionPercent or 0)
    stats.cloneDamagePercent = math.min(60, stats.cloneDamagePercent or 0)
    stats.executeThresholdPercent = math.min(10, stats.executeThresholdPercent or 0)

    local resonanceCounts = CountEquipmentResonanceSets(
        GetActiveEquipment()
    )
    ApplyEquipmentResonanceBonuses(stats, resonanceCounts)
    ApplyMixedEquipmentResonanceBonus(stats, resonanceCounts)
    ApplySelectedClassBonuses(stats)

    return stats
end

GEM_MAX_LEVEL = 5
GEM_MERGE_COST = 3
EQUIPMENT_SOCKET_VERSION = 1
EQUIPMENT_SOCKET_ROLLS = {
    { socketCount = 0, chance = 50 },
    { socketCount = 1, chance = 35 },
    { socketCount = 2, chance = 15 },
}
GEM_ORDER = { "red", "yellow", "green", "blue", "purple" }
GEM_DEFS = {
    red = {
        name = "红宝石",
        shortName = "红",
        color = { 235, 74, 78, 255 },
        stat = "gemPrimaryDamagePercent",
        label = "普攻最终伤害",
        values = { 1, 2, 4, 7, 10 },
    },
    yellow = {
        name = "黄宝石",
        shortName = "黄",
        color = { 242, 194, 62, 255 },
        stat = "gemSkillDamagePercent",
        label = "技能最终伤害",
        values = { 2, 4, 7, 11, 16 },
    },
    green = {
        name = "绿宝石",
        shortName = "绿",
        color = { 64, 190, 112, 255 },
        stat = "gemEliteBossDamagePercent",
        label = "精英/Boss最终伤害",
        values = { 3, 6, 12, 18, 25 },
    },
    blue = {
        name = "蓝宝石",
        shortName = "蓝",
        color = { 70, 135, 238, 255 },
        stat = "gemMaxHpPercent",
        label = "最终最大生命",
        values = { 1.5, 3, 5, 8, 12 },
    },
    purple = {
        name = "紫宝石",
        shortName = "紫",
        color = { 174, 94, 226, 255 },
        stat = "gemIncomingDamageReductionPercent",
        label = "最终减伤",
        values = { 1, 1.5, 2, 3, 5 },
    },
}

local GenerateEquipmentWithoutGemSockets = GenerateEquipment
local NormalizeEquipmentWithoutGems = NormalizeEquipment

function GetGemDef(gemType)
    return GEM_DEFS[gemType]
end

function GetGemValue(gemType, level)
    local def = GetGemDef(gemType)
    level = math.max(1, math.min(GEM_MAX_LEVEL, math.floor(level or 1)))
    return def and (def.values[level] or 0) or 0
end

function GetGemDisplayName(gemType, level)
    local def = GetGemDef(gemType)
    if def == nil then return "未知宝石" end
    return tostring(math.max(1, math.min(GEM_MAX_LEVEL, math.floor(level or 1))))
        .. "级" .. def.name
end

function GetGemEffectText(gemType, level)
    local def = GetGemDef(gemType)
    if def == nil then return "未知效果" end
    return def.label .. "+" .. tostring(GetGemValue(gemType, level)) .. "%"
end

function GetGemItemId(gemType, level)
    return "gem_" .. tostring(gemType) .. "_" .. tostring(level)
end

function IsGemItem(item)
    return item ~= nil
        and item.type == "material"
        and GEM_DEFS[item.gemType] ~= nil
        and item.gemLevel ~= nil
end

function NormalizeGemItem(item)
    if not IsGemItem(item) then return false end
    local changed = false
    local level = math.max(1, math.min(GEM_MAX_LEVEL, math.floor(item.gemLevel or 1)))
    local count = math.max(1, math.floor(item.count or 1))
    local id = GetGemItemId(item.gemType, level)
    local name = GetGemDisplayName(item.gemType, level)
    if item.gemLevel ~= level then item.gemLevel = level changed = true end
    if item.count ~= count then item.count = count changed = true end
    if item.id ~= id then item.id = id changed = true end
    if item.name ~= name then item.name = name changed = true end
    return changed
end

function NormalizeGemStacks()
    playerData.inventory = playerData.inventory or {}
    local firstByKey = {}
    local changed = false
    for i = #playerData.inventory, 1, -1 do
        local item = playerData.inventory[i]
        if IsGemItem(item) then
            changed = NormalizeGemItem(item) or changed
            local key = tostring(item.gemType) .. ":" .. tostring(item.gemLevel)
            local first = firstByKey[key]
            if first == nil then
                firstByKey[key] = item
            else
                first.count = math.max(1, math.floor(first.count or 1))
                    + math.max(1, math.floor(item.count or 1))
                table.remove(playerData.inventory, i)
                changed = true
            end
        end
    end
    return changed
end

function FindGemItem(gemType, level)
    level = math.max(1, math.min(GEM_MAX_LEVEL, math.floor(level or 1)))
    for index, item in ipairs(playerData.inventory or {}) do
        if IsGemItem(item) and item.gemType == gemType and item.gemLevel == level then
            return item, index
        end
    end
    return nil, nil
end

function GetGemCount(gemType, level)
    local item = FindGemItem(gemType, level)
    return item and math.max(0, math.floor(item.count or 0)) or 0
end

function AddGem(gemType, level, count, saveNow)
    if GEM_DEFS[gemType] == nil then return 0 end
    level = math.max(1, math.min(GEM_MAX_LEVEL, math.floor(level or 1)))
    count = math.max(0, math.floor(count or 0))
    if count <= 0 then return GetGemCount(gemType, level) end
    playerData.inventory = playerData.inventory or {}
    local item = FindGemItem(gemType, level)
    if item then
        item.count = math.max(0, math.floor(item.count or 0)) + count
    else
        item = {
            type = "material",
            id = GetGemItemId(gemType, level),
            name = GetGemDisplayName(gemType, level),
            gemType = gemType,
            gemLevel = level,
            count = count,
        }
        table.insert(playerData.inventory, item)
    end
    saveDirty = true
    print("[Gem] 获得", GetGemDisplayName(gemType, level), "x" .. tostring(count), "当前:", item.count)
    if saveNow == true then SaveCloudData(true) end
    return item.count
end

function GrantSettingsGemAdReward()
    local gemOrder = GEM_ORDER or { "red", "yellow", "green", "blue", "purple" }
    local count = math.max(1, math.floor(tonumber(GEM_AD_REWARD_COUNT) or 10))
    local totals = {}
    for i = 1, count do
        local gemType = gemOrder[math.random(1, #gemOrder)]
        AddGem(gemType, 1, 1, false)
        totals[gemType] = (totals[gemType] or 0) + 1
    end
    local parts = {}
    for _, gemType in ipairs(gemOrder) do
        local amount = totals[gemType] or 0
        if amount > 0 then
            table.insert(parts, GetGemDisplayName(gemType, 1) .. "×" .. tostring(amount))
        end
    end
    print("[RewardAd] 宝石广告发放:", table.concat(parts, "，"))
    return parts
end

function ConsumeGem(gemType, level, count)
    count = math.max(1, math.floor(count or 1))
    local item, index = FindGemItem(gemType, level)
    if item == nil or (item.count or 0) < count then return false end
    item.count = math.floor(item.count or 0) - count
    if item.count <= 0 then table.remove(playerData.inventory, index) end
    saveDirty = true
    return true
end

function MergeGemOnce(gemType, level)
    level = math.floor(level or 1)
    if GEM_DEFS[gemType] == nil then return false, "未知宝石" end
    if level < 1 or level >= GEM_MAX_LEVEL then return false, "该等级不能继续合成" end
    if GetGemCount(gemType, level) < GEM_MERGE_COST then
        return false, "需要" .. GEM_MERGE_COST .. "颗同类型、同等级宝石"
    end
    if not ConsumeGem(gemType, level, GEM_MERGE_COST) then
        return false, "宝石数量不足"
    end
    AddGem(gemType, level + 1, 1, false)
    SaveCloudData(true)
    print("[GemMerge] 合成成功:", GetGemDisplayName(gemType, level + 1))
    return true, GetGemDisplayName(gemType, level + 1)
end

function MergeAllGems(gemType)
    if GEM_DEFS[gemType] == nil then return 0, "未知宝石" end
    local merged = 0
    for level = 1, GEM_MAX_LEVEL - 1 do
        local batches = math.floor(GetGemCount(gemType, level) / GEM_MERGE_COST)
        if batches > 0 then
            ConsumeGem(gemType, level, batches * GEM_MERGE_COST)
            AddGem(gemType, level + 1, batches, false)
            merged = merged + batches
        end
    end
    if merged <= 0 then return 0, "没有可合成的宝石" end
    saveDirty = true
    SaveCloudData(true)
    print("[GemMerge] 全部合成:", GEM_DEFS[gemType].name, "次数:", merged)
    return merged, "完成" .. tostring(merged) .. "次合成"
end

function RollEquipmentSocketCount()
    local roll = math.random(1, 100)
    local cumulative = 0
    for _, entry in ipairs(EQUIPMENT_SOCKET_ROLLS) do
        cumulative = cumulative + entry.chance
        if roll <= cumulative then return entry.socketCount end
    end
    return 0
end

GenerateEquipment = function(slot, quality, floor, ancientOverride, grantResonanceSet)
    local item = GenerateEquipmentWithoutGemSockets(slot, quality, floor, ancientOverride, grantResonanceSet)
    item.socketVersion = EQUIPMENT_SOCKET_VERSION
    item.socketCount = RollEquipmentSocketCount()
    item.gems = {}
    print("[GemSocket] 新装备孔数:", item.name or slot, item.socketCount)
    return item
end

function NormalizeEquipmentGemState(item)
    if item == nil or item.type ~= "equipment" then return false end
    local changed = false
    if item.socketVersion ~= EQUIPMENT_SOCKET_VERSION then
        local existingGemCount = 0
        local seenGemTypes = {}
        for _, gem in ipairs(type(item.gems) == "table" and item.gems or {}) do
            local gemType = type(gem) == "table" and gem.gemType or nil
            local level = type(gem) == "table"
                and math.floor(gem.level or gem.gemLevel or 0)
                or 0
            if GEM_DEFS[gemType] ~= nil
                and level >= 1 and level <= GEM_MAX_LEVEL
                and not seenGemTypes[gemType]
                and existingGemCount < 2 then
                seenGemTypes[gemType] = true
                existingGemCount = existingGemCount + 1
            end
        end
        item.socketVersion = EQUIPMENT_SOCKET_VERSION
        item.socketCount = math.max(
            existingGemCount,
            math.max(0, math.min(2, math.floor(item.socketCount or 0)))
        )
        if type(item.gems) ~= "table" then item.gems = {} end
        changed = true
    end
    local socketCount = math.max(0, math.min(2, math.floor(item.socketCount or 0)))
    if item.socketCount ~= socketCount then item.socketCount = socketCount changed = true end
    if type(item.gems) ~= "table" then item.gems = {} changed = true end
    local normalized = {}
    local seenTypes = {}
    for _, gem in ipairs(item.gems) do
        local gemType = type(gem) == "table" and gem.gemType or nil
        local level = type(gem) == "table" and math.floor(gem.level or gem.gemLevel or 0) or 0
        if GEM_DEFS[gemType] ~= nil
            and level >= 1 and level <= GEM_MAX_LEVEL
            and not seenTypes[gemType]
            and #normalized < socketCount then
            table.insert(normalized, { gemType = gemType, level = level })
            seenTypes[gemType] = true
        else
            changed = true
        end
    end
    if #normalized ~= #item.gems then changed = true end
    item.gems = normalized
    return changed
end

function GetEquipmentSocketCount(item)
    if item == nil or item.type ~= "equipment" then return 0 end
    return math.max(0, math.min(2, math.floor(item.socketCount or 0)))
end

function GetEquipmentSocketedGemCount(item)
    return item and type(item.gems) == "table" and #item.gems or 0
end

function HasSocketedGems(item)
    return GetEquipmentSocketedGemCount(item) > 0
end

function HasEquipmentGemType(item, gemType)
    for _, gem in ipairs(item and item.gems or {}) do
        if gem.gemType == gemType then return true end
    end
    return false
end

function GetEquipmentSocketText(item)
    local socketCount = GetEquipmentSocketCount(item)
    if socketCount <= 0 then return "无宝石孔" end
    local parts = {}
    for index = 1, socketCount do
        local gem = item.gems and item.gems[index] or nil
        table.insert(parts, gem and GetGemDisplayName(gem.gemType, gem.level) or "空孔")
    end
    return "宝石孔：" .. table.concat(parts, " / ")
end

function ConsumeSocketPuncher(count)
    count = math.max(1, math.floor(count or 1))
    if GetSocketPuncherCount() < count then return false end
    for index = #playerData.inventory, 1, -1 do
        local item = playerData.inventory[index]
        if IsSocketPuncherItem(item) then
            local available = math.max(0, math.floor(item.count or 0))
            local used = math.min(available, count)
            item.count = available - used
            count = count - used
            if item.count <= 0 then
                table.remove(playerData.inventory, index)
            end
            if count <= 0 then return true end
        end
    end
    return false
end

function UseSocketPuncherOnEquipment(item)
    if currentScreen == "playing" then return false, "战斗中不能使用打孔器" end
    if item == nil or item.type ~= "equipment" then return false, "目标不是装备" end
    NormalizeEquipmentGemState(item)
    if GetEquipmentSocketCount(item) >= 2 then
        return false, "该装备已达到两孔上限"
    end
    if not ConsumeSocketPuncher(1) then
        return false, "背包中没有打孔器"
    end
    item.socketCount = GetEquipmentSocketCount(item) + 1
    item.socketVersion = EQUIPMENT_SOCKET_VERSION
    saveDirty = true
    SaveCloudData(true)
    print("[SocketPuncher] 打孔成功:", GetEquipmentDisplayName(item), "孔数:", item.socketCount)
    return true, "打孔成功，新增一个空宝石孔"
end

function SocketGemIntoEquipment(item, gemType, level)
    if currentScreen == "playing" then return false, "战斗中不能镶嵌宝石" end
    if item == nil or item.type ~= "equipment" then return false, "目标不是装备" end
    NormalizeEquipmentGemState(item)
    if GetEquipmentSocketedGemCount(item) >= GetEquipmentSocketCount(item) then
        return false, "该装备没有空宝石孔"
    end
    if HasEquipmentGemType(item, gemType) then
        return false, "同一装备不能镶嵌两颗同类宝石"
    end
    level = math.floor(level or 1)
    if GEM_DEFS[gemType] == nil or level < 1 or level > GEM_MAX_LEVEL then
        return false, "宝石无效"
    end
    if not ConsumeGem(gemType, level, 1) then return false, "背包中没有该宝石" end
    table.insert(item.gems, { gemType = gemType, level = level })
    saveDirty = true
    SaveCloudData(true)
    print("[GemSocket] 永久镶嵌:", GetEquipmentDisplayName(item), GetGemDisplayName(gemType, level))
    return true, "镶嵌成功"
end

function AddEquipmentGemStats(stats, item)
    for _, gem in ipairs(item and item.gems or {}) do
        local def = GetGemDef(gem.gemType)
        if def and stats[def.stat] ~= nil then
            stats[def.stat] = stats[def.stat] + GetGemValue(gem.gemType, gem.level)
        end
    end
end

function GetEquippedGemStats()
    local stats = {
        gemPrimaryDamagePercent = 0,
        gemSkillDamagePercent = 0,
        gemEliteBossDamagePercent = 0,
        gemMaxHpPercent = 0,
        gemIncomingDamageReductionPercent = 0,
    }
    for _, item in pairs(GetActiveEquipment() or {}) do
        AddEquipmentGemStats(stats, item)
    end
    return stats
end

NormalizeEquipment = function()
    NormalizeEquipmentWithoutGems()
    local migrated = false
    for _, set in ipairs(playerData.equipmentSets or {}) do
        for _, item in pairs(set) do
            if item and item.type == "equipment" then
                migrated = NormalizeEquipmentGemState(item) or migrated
            end
        end
    end
    for _, item in ipairs(playerData.inventory or {}) do
        if item.type == "equipment" then
            migrated = NormalizeEquipmentGemState(item) or migrated
        elseif IsGemItem(item) then
            migrated = NormalizeGemItem(item) or migrated
        end
    end
    migrated = NormalizeGemStacks() or migrated
    if migrated then
        saveDirty = true
        print("[GemMigration] 宝石与装备孔位数据已标准化")
    end
end

local GetEquipmentStatsWithoutGems = GetEquipmentStats
GetEquipmentStats = function()
    local stats = GetEquipmentStatsWithoutGems()
    local gemStats = GetEquippedGemStats()
    for key, value in pairs(gemStats) do stats[key] = value end
    return stats
end

function PrintActiveEquipmentSetStatsLog(reason)
    NormalizeEquipmentSets()
    local stats = GetEquipmentStats()
    local setCounts = {}
    for setIndex = 1, EQUIPMENT_SET_COUNT do
        setCounts[setIndex] = CountEquipmentItems(playerData.equipmentSets[setIndex])
    end
    print(string.format("[EquipmentSet] 验证%s: activeEquipmentSetIndex=%d, activeSetName=%s, equipmentCounts=%d/%d/%d, GetEquipmentStats={attackFlat=%d, attackPercent=%d, critRate=%d, critDamage=%d, hpFlat=%d, luckPercent=%d, moveSpeedPercent=%d, attackSpeedPercent=%d, attackCount=%d, goldPercent=%d, bossDamagePercent=%d, awakeningDuration=%d, skillCooldownReduction=%d, skillDamagePercent=%d, attackRangePercent=%d}",
        reason or "",
        playerData.activeEquipmentSetIndex or 1,
        GetActiveEquipmentSetName(),
        setCounts[1] or 0,
        setCounts[2] or 0,
        setCounts[3] or 0,
        stats.attackFlat or 0,
        stats.attackPercent or 0,
        stats.critRate or 0,
        stats.critDamage or 0,
        stats.hpFlat or 0,
        stats.luckPercent or 0,
        stats.moveSpeedPercent or 0,
        stats.attackSpeedPercent or 0,
        stats.attackCount or 0,
        stats.goldPercent or 0,
        stats.bossDamagePercent or 0,
        stats.awakeningDuration or 0,
        stats.skillCooldownReduction or 0,
        stats.skillDamagePercent or 0,
        stats.attackRangePercent or 0))
end

function GetEquipmentQualityDef(quality)
    return EQUIPMENT_QUALITY_DEFS[quality] or EQUIPMENT_QUALITY_DEFS.blue
end

function FormatAutoSellFloorText(value)
    value = math.max(0, math.floor(value or 0))
    if value <= 0 then return "不限层数" end
    return tostring(value) .. "层以下"
end

function AdjustAutoSellMaxFloor(value, delta)
    value = math.max(0, math.floor(value or 0))
    delta = math.floor(delta or 0)
    return math.max(0, value + delta)
end

function GetEquipmentAffixCount(item)
    if item == nil or type(item.affixes) ~= "table" then return 0 end
    local count = 0
    for _, affix in ipairs(item.affixes) do
        if affix and affix.fixed ~= true then
            count = count + 1
        end
    end
    return count
end

function NormalizeAutoSellSlotSettings()
    local source = playerData.settings.autoSellSlots
    local normalized = {}
    if type(source) == "table" then
        for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS) do
            if source[slotDef.id] == true then
                normalized[slotDef.id] = true
            end
        end
        for _, value in pairs(source) do
            if type(value) == "string" and EQUIPMENT_SLOT_BY_ID[value] ~= nil then
                normalized[value] = true
            end
        end
    end
    playerData.settings.autoSellSlots = normalized
end

function NormalizeAutoSellAffixCountSettings()
    local source = playerData.settings.autoSellAffixCounts
    local normalized = {}
    if type(source) == "table" then
        for key, value in pairs(source) do
            local count = nil
            if value == true then
                count = tonumber(key)
            elseif type(value) == "number" then
                count = value
            end
            if count ~= nil then
                count = math.floor(count)
                if count >= 1 and count <= 6 then
                    normalized[tostring(count)] = true
                end
            end
        end
    end
    playerData.settings.autoSellAffixCounts = normalized
end

function NormalizeAutoSellSetIdSettings()
    local source = playerData.settings.autoSellSetIds
    local normalized = {}
    if type(source) == "table" then
        for _, setId in ipairs(EQUIPMENT_RESONANCE_ORDER or {}) do
            if source[setId] == true then
                normalized[setId] = true
            end
        end
        for key, value in pairs(source) do
            if type(value) == "string"
                and EQUIPMENT_RESONANCE_DEFS[value] ~= nil
            then
                normalized[value] = true
            end
        end
    end
    playerData.settings.autoSellSetIds = normalized
end

function IsAutoSellSetSelected(setId)
    NormalizeEquipmentSettings()
    if EQUIPMENT_RESONANCE_DEFS[setId] == nil then return false end
    return playerData.settings.autoSellSetIds[setId] == true
end

function ToggleAutoSellSet(setId)
    NormalizeEquipmentSettings()
    if EQUIPMENT_RESONANCE_DEFS[setId] == nil then return false end
    playerData.settings.autoSellSetIds[setId] = not playerData.settings.autoSellSetIds[setId]
    return playerData.settings.autoSellSetIds[setId]
end

function IsAutoSellSlotSelected(slotId)
    NormalizeEquipmentSettings()
    return playerData.settings.autoSellSlots[slotId] == true
end

function ToggleAutoSellSlot(slotId)
    NormalizeEquipmentSettings()
    if EQUIPMENT_SLOT_BY_ID[slotId] == nil then return false end
    playerData.settings.autoSellSlots[slotId] = not playerData.settings.autoSellSlots[slotId]
    return playerData.settings.autoSellSlots[slotId]
end

function IsAutoSellAffixCountSelected(count)
    NormalizeEquipmentSettings()
    count = math.max(1, math.min(6, math.floor(count or 1)))
    return playerData.settings.autoSellAffixCounts[tostring(count)] == true
end

function ToggleAutoSellAffixCount(count)
    NormalizeEquipmentSettings()
    count = math.max(1, math.min(6, math.floor(count or 1)))
    local key = tostring(count)
    playerData.settings.autoSellAffixCounts[key] = not playerData.settings.autoSellAffixCounts[key]
    return playerData.settings.autoSellAffixCounts[key]
end

function ShouldAutoSellEquipment(item)
    NormalizeEquipmentSettings()
    if item == nil or item.type ~= "equipment" then return false end
    if item.locked == true then return false end
    if HasSocketedGems(item) then return false end
    if not playerData.settings.autoSellEnabled then return false end

    local colorMatched = playerData.settings.autoSellColorRuleEnabled
        and IsQualityAtOrBelow(item.quality, playerData.settings.autoSellThreshold)

    local maxFloor = math.max(0, math.floor(playerData.settings.autoSellMaxFloor or 0))
    local floorMatched = playerData.settings.autoSellFloorRuleEnabled
        and maxFloor > 0
        and math.max(1, math.floor(item.floor or 1)) <= maxFloor

    local slotMatched = item.slot ~= nil
        and playerData.settings.autoSellSlots[item.slot] == true

    local affixCount = GetEquipmentAffixCount(item)
    local affixCountMatched = playerData.settings.autoSellAffixCounts[tostring(affixCount)] == true

    local setMatched = playerData.settings.autoSellSetIds
        and item.resonanceSetId ~= nil
        and playerData.settings.autoSellSetIds[item.resonanceSetId] == true

    return colorMatched or floorMatched or slotMatched or affixCountMatched or setMatched
end

SPEED_AD_UNLOCK_MIGRATION_VERSION = 1

function MergeSpeedAdUnlockSettings(incomingSettings)
    local incoming = type(incomingSettings) == "table" and incomingSettings or {}
    local current = type(playerData.settings) == "table" and playerData.settings or {}
    local incomingVersion = math.max(0, math.floor(tonumber(incoming.speedAdUnlockMigrationVersion) or 0))
    local currentVersion = math.max(0, math.floor(tonumber(current.speedAdUnlockMigrationVersion) or 0))

    if incomingVersion < SPEED_AD_UNLOCK_MIGRATION_VERSION then
        incoming.tripleSpeedUnlocked = false
        incoming.fiveSpeedUnlocked = false
        incoming.fiveSpeedAdUnlockDayKey = ""
        incoming.tenBattleUnlocked = false
        incoming.tenBattleEnabled = false
        incoming.speedAdUnlockMigrationVersion = SPEED_AD_UNLOCK_MIGRATION_VERSION
        incomingVersion = SPEED_AD_UNLOCK_MIGRATION_VERSION
        print("[AdUnlock] 已回收旧版三倍速、五倍速和十连打权益")
    end

    if currentVersion >= SPEED_AD_UNLOCK_MIGRATION_VERSION then
        incoming.tripleSpeedUnlocked = incoming.tripleSpeedUnlocked == true
            or current.tripleSpeedUnlocked == true
        incoming.tenBattleUnlocked = incoming.tenBattleUnlocked == true
            or current.tenBattleUnlocked == true
        local today = GetCurrentCstDayKey ~= nil and GetCurrentCstDayKey() or ""
        if tostring(current.fiveSpeedAdUnlockDayKey or "") == today then
            incoming.fiveSpeedAdUnlockDayKey = today
        end
    end
    return incoming
end

function IsFiveSpeedUnlockedToday()
    return playerData.settings ~= nil
        and tostring(playerData.settings.fiveSpeedAdUnlockDayKey or "") == GetCurrentCstDayKey()
end

function NormalizeEquipmentSettings()
    playerData.settings = MergeSpeedAdUnlockSettings(playerData.settings)
    if playerData.settings.sellThreshold == nil then playerData.settings.sellThreshold = "blue" end
    if playerData.settings.autoSellEnabled == nil then playerData.settings.autoSellEnabled = false end
    if playerData.settings.autoSellThreshold == nil then playerData.settings.autoSellThreshold = "blue" end
    if playerData.settings.autoSellColorRuleEnabled == nil then playerData.settings.autoSellColorRuleEnabled = true end
    if playerData.settings.autoSellFloorRuleEnabled == nil then playerData.settings.autoSellFloorRuleEnabled = false end
    playerData.settings.autoSellMaxFloor = math.max(0, math.floor(playerData.settings.autoSellMaxFloor or 0))
    NormalizeAutoSellSlotSettings()
    NormalizeAutoSellAffixCountSettings()
    NormalizeAutoSellSetIdSettings()
    if playerData.settings.tripleSpeedUnlocked == nil then playerData.settings.tripleSpeedUnlocked = false end
    playerData.settings.fiveSpeedUnlocked = false
    playerData.settings.fiveSpeedAdUnlockDayKey = tostring(playerData.settings.fiveSpeedAdUnlockDayKey or "")
    playerData.settings.speedAdUnlockMigrationVersion = SPEED_AD_UNLOCK_MIGRATION_VERSION
    if playerData.settings.tenSpeedUnlocked == nil then playerData.settings.tenSpeedUnlocked = false end
    if playerData.settings.fakeTenSpeedUnlocked == nil then playerData.settings.fakeTenSpeedUnlocked = false end
    if playerData.settings.fiveBattleEnabled == nil then playerData.settings.fiveBattleEnabled = false end
    if playerData.settings.tenBattleUnlocked == nil then playerData.settings.tenBattleUnlocked = false end
    if playerData.settings.tenBattleEnabled == nil then playerData.settings.tenBattleEnabled = false end
    if playerData.settings.twentyBattleUnlocked == nil then playerData.settings.twentyBattleUnlocked = false end
    if playerData.settings.twentyBattleEnabled == nil then playerData.settings.twentyBattleEnabled = false end
    if playerData.settings.autoBattleEnabled == nil then playerData.settings.autoBattleEnabled = true end
    playerData.settings.selectedClassId = NormalizeSelectedClassId(
        playerData.settings.selectedClassId
    )
    if not playerData.settings.tenBattleUnlocked then playerData.settings.tenBattleEnabled = false end
    if not playerData.settings.twentyBattleUnlocked then playerData.settings.twentyBattleEnabled = false end
    if playerData.settings.twentyBattleEnabled then
        playerData.settings.tenBattleEnabled = false
        playerData.settings.fiveBattleEnabled = false
    elseif playerData.settings.tenBattleEnabled then
        playerData.settings.fiveBattleEnabled = false
    end
    if playerData.settings.lastGameSpeed == nil then playerData.settings.lastGameSpeed = 1 end
    if playerData.settings.autoSkillMergeEnabled == nil then playerData.settings.autoSkillMergeEnabled = false end
    local maxAutoSkillMergeStar = CONFIG.SkillMaxStar or 10
    playerData.settings.autoSkillMergeTargetStar = math.max(2, math.min(maxAutoSkillMergeStar, math.floor(playerData.settings.autoSkillMergeTargetStar or 3)))
    if playerData.settings.autoDismantleEnabled == nil then playerData.settings.autoDismantleEnabled = false end
    local maxAutoDismantleStar = math.max(1, CONFIG.SkillDismantleMaxStar or 2)
    playerData.settings.autoDismantleTargetStar = math.max(1, math.min(maxAutoDismantleStar, math.floor(playerData.settings.autoDismantleTargetStar or 3)))
    local lastSpeed = math.floor(playerData.settings.lastGameSpeed or 1)
    local speedAllowed = lastSpeed == 1
        or ((lastSpeed == 2 or lastSpeed == 3) and playerData.settings.tripleSpeedUnlocked)
        or (lastSpeed == 5
            and playerData.settings.fiveSpeedAdUnlockDayKey == GetCurrentCstDayKey())
        or (lastSpeed == 10 and playerData.settings.tenSpeedUnlocked)
    if not speedAllowed then playerData.settings.lastGameSpeed = 1 end
    local lastRiftSpeed = math.floor(playerData.settings.lastEquipmentRiftGameSpeed or 1)
    local riftSpeedAllowed = lastRiftSpeed == 1
        or ((lastRiftSpeed == 2 or lastRiftSpeed == 3) and playerData.settings.tripleSpeedUnlocked)
        or (lastRiftSpeed == 5
            and playerData.settings.fiveSpeedAdUnlockDayKey == GetCurrentCstDayKey())
        or (lastRiftSpeed == 10 and playerData.settings.tenSpeedUnlocked)
    if not riftSpeedAllowed then playerData.settings.lastEquipmentRiftGameSpeed = 1 end
end

function CycleQuality(quality)
    local rank = EQUIPMENT_QUALITY_RANK[quality] or 1
    rank = rank + 1
    if rank > #EQUIPMENT_QUALITY_ORDER then rank = 1 end
    return EQUIPMENT_QUALITY_ORDER[rank]
end

function IsQualityAtOrBelow(quality, threshold)
    return (EQUIPMENT_QUALITY_RANK[quality] or 1) <= (EQUIPMENT_QUALITY_RANK[threshold] or 1)
end

function GetEquipmentSellPrice(item)
    local floor = math.max(1, item.floor or 1)
    local mult = EQUIPMENT_QUALITY_PRICE_MULT[item.quality] or 1
    return math.max(1, math.floor((20 + floor * 5) * mult * 1.44))
end

function GetEquipmentSellRewards(item)
    if item == nil or item.type ~= "equipment" then return 0, 0 end
    local gold = GetEquipmentSellPrice(item)
    if IsAncientEquipment(item) then
        gold = gold * 10
    end
    local refineStone = item.quality == "red" and 1 or 0
    return gold, refineStone
end

function FormatEquipmentSellRewardValues(gold, refineStone)
    local parts = {}
    gold = math.max(0, math.floor(gold or 0))
    refineStone = math.max(0, math.floor(refineStone or 0))
    if gold > 0 then
        table.insert(parts, "金币+" .. gold)
    end
    if refineStone > 0 then
        table.insert(parts, REFINE_STONE_NAME .. "+" .. refineStone)
    end
    if #parts == 0 then return "无收益" end
    return table.concat(parts, " / ")
end

function GetEquipmentSellRewardText(item)
    local gold, refineStone = GetEquipmentSellRewards(item)
    return FormatEquipmentSellRewardValues(gold, refineStone)
end

function AccumulateEquipmentStats(item)
    local stats = {
        attackFlat = 0,
        attackPercent = 0,
        critRate = 0,
        critDamage = 0,
        hpFlat = 0,
        luckPercent = 0,
        moveSpeedPercent = 0,
        attackSpeedPercent = 0,
        attackCount = 0,
        goldPercent = 0,
        bossDamagePercent = 0,
        awakeningDuration = 0,
        skillCooldownReduction = 0,
        skillDamagePercent = 0,
        attackRangePercent = 0,
        hpPercent = 0,
        doubleAttackChance = 0,
        easterEgg = 0,
        primaryAttackDamagePercent = 0,
        skillAreaPercent = 0,
        damageReductionPercent = 0,
        cloneDamagePercent = 0,
        executeThresholdPercent = 0,
    }
    if item == nil then return stats end
    if item.baseAffix then
        local def = EQUIPMENT_AFFIX_BY_ID[item.baseAffix.id]
        if def and stats[def.stat] ~= nil then
            local value = item.baseAffix.value or 0
            if item.slot == "weapon" and item.baseAffix.id == "attack_flat" then
                value = math.floor(value * (1 + GetWeaponUpgradeAttackPercent(item.weaponUpgradeLevel or 0) / 100) + 0.5)
            elseif item.slot == "armor" and item.baseAffix.id == "hp_flat" then
                value = math.floor(value * (1 + GetArmorUpgradeHpPercent(item.armorUpgradeLevel or 0) / 100) + 0.5)
            elseif item.slot == "boots" and item.baseAffix.id == "crit_damage" then
                value = math.floor(value * (1 + GetBootsUpgradeCritDamagePercent(item.bootsUpgradeLevel or 0) / 100) + 0.5)
            elseif item.slot == "gloves" and item.baseAffix.id == "crit_rate" then
                value = value + GetGlovesUpgradeCritRatePercent(item.glovesUpgradeLevel or 0)
            elseif item.slot == "ring" and item.baseAffix.id == "luck" then
                value = value + GetRingUpgradeLuckPercent(item.ringUpgradeLevel or 0)
            end
            stats[def.stat] = stats[def.stat] + value
        end
    end
    for _, affix in ipairs(item.affixes or {}) do
        AddEquipmentAffixStats(stats, affix)
    end
    return stats
end

function GetEquipmentScore(item)
    local stats = AccumulateEquipmentStats(item)
    local scoreValue = 0
    for stat, value in pairs(stats) do
        scoreValue = scoreValue + value * (EQUIPMENT_SCORE_WEIGHTS[stat] or 0)
    end
    return math.floor(scoreValue)
end

function SortInventoryEquipment()
    playerData.inventory = playerData.inventory or {}
    local entries = {}
    for index, item in ipairs(playerData.inventory) do
        if item and item.type == "equipment" then
            table.insert(entries, {
                item = item,
                order = index,
                qualityRank = EQUIPMENT_QUALITY_RANK[item.quality] or 1,
                ancientRank = IsAncientEquipment(item) and 1 or 0,
                score = GetEquipmentScore(item),
                floor = math.floor(item.floor or 1),
            })
        end
    end
    table.sort(entries, function(a, b)
        if a.qualityRank ~= b.qualityRank then
            return a.qualityRank > b.qualityRank
        end
        if a.ancientRank ~= b.ancientRank then
            return a.ancientRank > b.ancientRank
        end
        if a.floor ~= b.floor then
            return a.floor > b.floor
        end
        if a.score ~= b.score then
            return a.score > b.score
        end
        return a.order < b.order
    end)

    local entryIndex = 0
    for index, item in ipairs(playerData.inventory) do
        if item and item.type == "equipment" then
            entryIndex = entryIndex + 1
            playerData.inventory[index] = entries[entryIndex].item
        end
    end
    if #entries > 1 then
        saveDirty = true
        SaveCloudData(true)
    end
    print("[Equipment] 一键排序完成，装备数量:", #entries)
    return #entries
end

COMPARE_STAT_ORDER = {
    { stat = "attackFlat", label = "攻击", suffix = "" },
    { stat = "attackPercent", label = "攻击力", suffix = "%" },
    { stat = "critRate", label = "暴击率", suffix = "%" },
    { stat = "critDamage", label = "暴击伤害", suffix = "%" },
    { stat = "hpFlat", label = "血量", suffix = "" },
    { stat = "hpPercent", label = "血量", suffix = "%" },
    { stat = "luckPercent", label = "幸运", suffix = "%" },
    { stat = "moveSpeedPercent", label = "移速", suffix = "%" },
    { stat = "attackSpeedPercent", label = "攻速", suffix = "%" },
    { stat = "attackCount", label = "攻击数量", suffix = "" },
    { stat = "goldPercent", label = "金币", suffix = "%" },
    { stat = "skillCooldownReduction", label = "技能冷却", suffix = "秒", invert = true },
    { stat = "skillDamagePercent", label = "技能伤害", suffix = "%" },
    { stat = "attackRangePercent", label = "攻击范围", suffix = "%" },
    { stat = "doubleAttackChance", label = "双重攻击概率", suffix = "%" },
    { stat = "bossDamagePercent", label = "boss增伤", suffix = "%" },
    { stat = "awakeningDuration", label = "觉醒时长", suffix = "秒" },
    { stat = "primaryAttackDamagePercent", label = "破军", suffix = "%" },
    { stat = "skillAreaPercent", label = "法域扩张", suffix = "%" },
    { stat = "damageReductionPercent", label = "坚韧", suffix = "%" },
    { stat = "cloneDamagePercent", label = "分身共鸣", suffix = "%" },
    { stat = "executeThresholdPercent", label = "斩杀", suffix = "%" },
}

function MakeEquipmentCompareText(item)
    if item == nil or item.type ~= "equipment" then return "" end
    local current = GetActiveEquipment()[item.slot]
    local newScore = GetEquipmentScore(item)
    local oldScore = GetEquipmentScore(current)
    local scoreDiff = newScore - oldScore
    local newStats = AccumulateEquipmentStats(item)
    local oldStats = AccumulateEquipmentStats(current)
    local parts = {}
    for _, def in ipairs(COMPARE_STAT_ORDER) do
        local diff = (newStats[def.stat] or 0) - (oldStats[def.stat] or 0)
        if diff ~= 0 then
            local sign = diff > 0 and "+" or ""
            if def.invert then sign = diff > 0 and "-" or "+" end
            table.insert(parts, def.label .. sign .. math.abs(diff) .. def.suffix)
            if #parts >= 3 then break end
        end
    end
    local diffSign = scoreDiff >= 0 and "+" or ""
    local detail = #parts > 0 and table.concat(parts, " / ") or "属性持平"
    return "评分" .. newScore .. "（当前" .. oldScore .. "，" .. diffSign .. scoreDiff .. "）｜" .. detail
end

function ToggleInventoryEquipmentLocked(index)
    local item = playerData.inventory[index]
    if item == nil or item.type ~= "equipment" then return false end
    item.locked = not item.locked
    saveDirty = true
    SaveCloudData(true)
    print("[Equipment]", item.locked and "锁定" or "解锁", item.name or "装备")
    return item.locked
end

function SellEquipmentAtIndex(index, allowGemmed)
    local item = playerData.inventory[index]
    if item == nil or item.type ~= "equipment" or item.locked then return 0, 0 end
    if HasSocketedGems(item) and allowGemmed ~= true then return 0, 0 end
    local gold, refineStone = GetEquipmentSellRewards(item)
    table.remove(playerData.inventory, index)
    if gold > 0 then
        AddGold(gold)
    end
    if refineStone > 0 then
        AddRefineStone(refineStone)
    end
    return gold, refineStone
end

function SellInventoryEquipment(index, allowGemmed)
    local gold, refineStone = SellEquipmentAtIndex(index, allowGemmed)
    if gold > 0 or refineStone > 0 then
        saveDirty = true
        SaveCloudData(true)
        print("[Equipment] 出售装备, " .. FormatEquipmentSellRewardValues(gold, refineStone))
    end
    return gold, refineStone
end

function SellEquipmentByThreshold(threshold)
    local totalGold = 0
    local totalRefineStone = 0
    local count = 0
    for i = #playerData.inventory, 1, -1 do
        local item = playerData.inventory[i]
        if item and item.type == "equipment"
            and not item.locked
            and not HasSocketedGems(item)
            and IsQualityAtOrBelow(item.quality, threshold) then
            local gold, refineStone = SellEquipmentAtIndex(i)
            totalGold = totalGold + gold
            totalRefineStone = totalRefineStone + refineStone
            count = count + 1
        end
    end
    if count > 0 then
        saveDirty = true
        SaveCloudData(true)
    end
    return count, totalGold, totalRefineStone
end

HandleDroppedEquipment = function(item)
    NormalizeEquipmentSettings()

    if item.quality == "colorful" then
        local maxColorful = CONFIG.MaxColorfulInventory or 5
        if CountInventoryColorful() >= maxColorful then
            local replaced = nil
            if IsEasterEggEquipment(item) then
                replaced = MakeRoomForEasterEggColorful()
            end
            if replaced == nil then
                print("[ColorfulCap] 销毁(局外):", item.name,
                    "背包", CountInventoryColorful(), "上限", maxColorful)
                AddEffect({
                    type = "drop",
                    x = screenW * 0.5,
                    y = screenH * 0.36,
                    text = "彩色已满·销毁 " .. item.name,
                    life = 1.6,
                    maxLife = 1.6,
                })
                return
            end
            item._capacityReplacement = true
            print("[ColorfulCap] 小趴菜替换彩色装备(局外):", replaced.name, "→", item.name)
        end
    end

    if ShouldAutoSellEquipment(item) then
        local gold, refineStone = GetEquipmentSellRewards(item)
        if gold > 0 then
            AddGold(gold)
        end
        if refineStone > 0 then
            AddRefineStone(refineStone)
        end
        saveDirty = true
        SaveCloudData(true)
        local rewardText = FormatEquipmentSellRewardValues(gold, refineStone)
        AddEffect({ type = "drop", x = screenW * 0.5, y = screenH * 0.36, text = "自动出售 " .. item.name .. " " .. rewardText, life = 1.4, maxLife = 1.4 })
        print("[Equipment] 自动出售:", item.name, rewardText)
    else
        AddEquipmentToInventory(item)
    end
end


AddEquipmentToInventory = function(item)
    if item == nil or item.type ~= "equipment" then return false end
    local equipmentCap = CONFIG.MaxEquipmentInventory or 500
    local equipmentCount = CountInventoryEquipment()
    if equipmentCount >= equipmentCap and item._capacityReplacement ~= true then
        ShowInventoryCapacityMessage(
            "装备背包已满（" .. tostring(equipmentCount) .. "/" .. tostring(equipmentCap)
                .. "），未获取 " .. tostring(item.name or "装备")
        )
        return false
    end
    item._capacityReplacement = nil
    table.insert(playerData.inventory, item)
    saveDirty = true
    print("[Equipment] 装备进入背包:", item.name, "层数:", item.floor or 1,
        "装备数量:", equipmentCount + 1, "/", equipmentCap)
    SaveCloudData(true)
    return true
end

function EquipInventoryItem(index)
    local item = playerData.inventory[index]
    if item == nil or item.type ~= "equipment" or item.slot == nil then return end
    local equipment = GetActiveEquipment()
    local oldItem = equipment[item.slot]
    table.remove(playerData.inventory, index)
    equipment[item.slot] = item
    if oldItem then
        table.insert(playerData.inventory, oldItem)
    end
    saveDirty = true
    SaveCloudData(true)
    GameEvents.Emit("scene:bag")
    print("[Equipment] 已穿戴:", item.name)
end

screenMetricsPhysW = screenMetricsPhysW or -1
screenMetricsPhysH = screenMetricsPhysH or -1
screenMetricsDpr = screenMetricsDpr or -1

function UpdateScreenMetrics(force)
    local physW = graphics:GetWidth()
    local physH = graphics:GetHeight()
    local dpr = graphics:GetDPR()
    if dpr == nil or dpr <= 0 then
        dpr = 1.0
    end
    if not force
        and physW == screenMetricsPhysW
        and physH == screenMetricsPhysH
        and dpr == screenMetricsDpr then
        return false
    end
    screenMetricsPhysW = physW
    screenMetricsPhysH = physH
    screenMetricsDpr = dpr
    screenDpr = dpr
    screenW = physW / screenDpr
    screenH = physH / screenDpr

    local inset = { left = 0, top = 0, right = 0, bottom = 0 }
    local ok, rect = pcall(GetSafeAreaInsets, false)
    if ok and rect then
        inset.left   = (rect.min and rect.min.x or 0) / screenDpr
        inset.top    = (rect.min and rect.min.y or 0) / screenDpr
        inset.right  = (rect.max and rect.max.x or 0) / screenDpr
        inset.bottom = (rect.max and rect.max.y or 0) / screenDpr
    end

    local sdk = _G.sdk
    if sdk and sdk.GetNativeExitMenuRect then
        local menuRect = sdk:GetNativeExitMenuRect()
        if menuRect then
            local menuBottom = menuRect.bottom * screenH
            if menuBottom > inset.top then
                inset.top = menuBottom
            end
        end
    end
    safeInset = inset
    if inset.left > 0 or inset.top > 0 or inset.right > 0 or inset.bottom > 0 then
        print("[SafeArea] insets(base px):", inset.left, inset.top, inset.right, inset.bottom)
    end

    uiLabelSize = screenW < 340 and 13 or 12
    uiValueSize = screenW < 340 and 14 or 13
    settingsLabelSize = uiLabelSize
    settingsValueSize = uiValueSize
    return true
end

GetMaxSelectableStartFloor = function()
    local completedFloors = math.max(0, (playerData.bestFloor or 1) - 1)
    if completedFloors < 100 then
        return math.max(0, math.floor(completedFloors * CONFIG.RebirthStartFloorRate))
    end
    return math.max(0, completedFloors - 50)
end

NormalizeUsedStartFloors = function()
    local source = playerData.usedStartFloors or {}
    local normalized = {}
    for key, value in pairs(source) do
        local floor = tonumber(key)
        if floor == nil and type(value) == "number" then
            floor = value
        end
        if floor and floor >= 1 then
            normalized[tostring(math.floor(floor))] = true
        end
    end
    playerData.usedStartFloors = normalized
end

IsStartFloorUsed = function(floor)
    -- 死亡选层改为无限次数：不再限制已选过的楼层，恒返回 false。
    return false
end

MarkStartFloorUsed = function(floor)
    -- 死亡选层改为无限次数：不再写入已选楼层记录。
    return true
end

FindSelectableStartFloor = function(preferred)
    NormalizeUsedStartFloors()
    local maxFloor = GetMaxSelectableStartFloor()
    preferred = math.max(0, math.min(math.floor(preferred or 0), maxFloor))
    if preferred > 0 and not IsStartFloorUsed(preferred) then
        return preferred
    end
    for floor = maxFloor, 1, -1 do
        if not IsStartFloorUsed(floor) then
            return floor
        end
    end
    return 0
end

ClampSelectedStartFloor = function(floor)
    return FindSelectableStartFloor(floor)
end


