local function BuildIdSet(defs)
    local result = {}
    for _, def in ipairs(defs or {}) do result[def.id] = true end
    return result
end

local ADVENTURE_MONSTER_IDS = BuildIdSet(ADVENTURE_MONSTER_DEFS)
local ADVENTURE_SKILL_IDS = BuildIdSet((function()
    local defs = {}
    for _, id in ipairs(SKILL_ORDER or {}) do table.insert(defs, { id = id }) end
    return defs
end)())
local ADVENTURE_ACHIEVEMENT_IDS = BuildIdSet(ADVENTURE_ACHIEVEMENT_DEFS)
local ADVENTURE_TITLE_IDS = {}
local ADVENTURE_BADGE_IDS = {}
for id in pairs(ADVENTURE_TITLE_DEFS) do ADVENTURE_TITLE_IDS[id] = true end
for id in pairs(ADVENTURE_BADGE_DEFS) do ADVENTURE_BADGE_IDS[id] = true end

local function CreateAdventureCodexData()
    return {
        version = 1,
        equipmentDiscovered = {},
        skillDiscovered = {},
        skillHighestStar = {},
        monsterDiscovered = {},
        achievementClaims = {},
        unlockedTitles = { novice = true },
        selectedTitleId = "novice",
        selectedTitleStyleId = "royal_gold",
        selectedTitleInnerBgId = "aurora_core",
        unlockedBadges = {},
        selectedBadgeId = "",
        totalRefineCount = 0,
    }
end

local function CreateSkillResearchData()
    return { version = 1, totalExchanges = 0 }
end

local function CountMapEntries(source, whitelist)
    local count = 0
    for key, value in pairs(type(source) == "table" and source or {}) do
        if value == true and (whitelist == nil or whitelist[key]) then count = count + 1 end
    end
    return count
end

local function SanitizeBoolMap(source, whitelist)
    local result = {}
    for key, value in pairs(type(source) == "table" and source or {}) do
        if value == true and whitelist[key] then result[key] = true end
    end
    return result
end

local function GetEquipmentDiscoveryWhitelist()
    local whitelist = {}
    for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS or {}) do
        for _, quality in ipairs(EQUIPMENT_QUALITY_ORDER or {}) do
            whitelist[slotDef.id .. ":" .. quality] = true
        end
    end
    return whitelist
end

function NormalizeAdventureData()
    if type(playerData.adventureCodex) ~= "table" then
        playerData.adventureCodex = CreateAdventureCodexData()
        saveDirty = true
    end
    if type(playerData.skillResearch) ~= "table" then
        playerData.skillResearch = CreateSkillResearchData()
        saveDirty = true
    end
    local codex = playerData.adventureCodex
    local equipmentWhitelist = GetEquipmentDiscoveryWhitelist()
    codex.version = 1
    codex.equipmentDiscovered = SanitizeBoolMap(codex.equipmentDiscovered, equipmentWhitelist)
    codex.skillDiscovered = SanitizeBoolMap(codex.skillDiscovered, ADVENTURE_SKILL_IDS)
    codex.monsterDiscovered = SanitizeBoolMap(codex.monsterDiscovered, ADVENTURE_MONSTER_IDS)
    codex.achievementClaims = SanitizeBoolMap(codex.achievementClaims, ADVENTURE_ACHIEVEMENT_IDS)
    codex.unlockedTitles = SanitizeBoolMap(codex.unlockedTitles, ADVENTURE_TITLE_IDS)
    codex.unlockedTitles.novice = true
    codex.unlockedBadges = SanitizeBoolMap(codex.unlockedBadges, ADVENTURE_BADGE_IDS)
    codex.totalRefineCount = math.max(0, math.floor(tonumber(codex.totalRefineCount) or 0))

    local highest = {}
    for id, value in pairs(type(codex.skillHighestStar) == "table" and codex.skillHighestStar or {}) do
        if ADVENTURE_SKILL_IDS[id] then
            highest[id] = math.max(1, math.min(CONFIG.SkillMaxStar or 10, math.floor(tonumber(value) or 1)))
        end
    end
    codex.skillHighestStar = highest

    if codex.selectedTitleId ~= "" and not codex.unlockedTitles[codex.selectedTitleId] then codex.selectedTitleId = "novice" end
    if type(codex.selectedTitleStyleId) ~= "string" or ADVENTURE_TITLE_STYLE_DEFS[codex.selectedTitleStyleId] == nil then codex.selectedTitleStyleId = "royal_gold" end
    if type(codex.selectedTitleInnerBgId) ~= "string" or ADVENTURE_TITLE_INNER_BG_DEFS[codex.selectedTitleInnerBgId] == nil then codex.selectedTitleInnerBgId = "aurora_core" end
    if codex.selectedBadgeId ~= "" and not codex.unlockedBadges[codex.selectedBadgeId] then codex.selectedBadgeId = "" end

    playerData.skillResearch.version = 1
    playerData.skillResearch.totalExchanges = math.max(0, math.floor(tonumber(playerData.skillResearch.totalExchanges) or 0))

    for _, item in ipairs(playerData.inventory or {}) do
        if item and item.type == "equipment" and equipmentWhitelist[tostring(item.slot) .. ":" .. tostring(item.quality)] then
            codex.equipmentDiscovered[item.slot .. ":" .. item.quality] = true
        end
    end
    for _, equipmentSet in ipairs(playerData.equipmentSets or {}) do
        for _, item in pairs(type(equipmentSet) == "table" and equipmentSet or {}) do
            if type(item) == "table" and item.type == "equipment" and equipmentWhitelist[tostring(item.slot) .. ":" .. tostring(item.quality)] then
                codex.equipmentDiscovered[item.slot .. ":" .. item.quality] = true
            end
        end
    end
    for _, skill in ipairs(playerData.skills or {}) do
        if skill and ADVENTURE_SKILL_IDS[skill.id] then
            codex.skillDiscovered[skill.id] = true
            codex.skillHighestStar[skill.id] = math.max(codex.skillHighestStar[skill.id] or 1, math.floor(tonumber(skill.star) or 1))
        end
    end
    return codex
end

-- 图鉴登记快路径：NormalizeAdventureData 需要全量扫描背包/套装/技能（大存档下约
-- 0.3ms/次），而掉落与技能卡是逐件、逐张登记的，连打结算时会累积成明显卡顿。
-- 已登记过的内容直接短路返回，结果与走完整归一化完全一致（归一化只会把
-- 已拥有的装备/技能标记为已发现，不会清除已登记项），仅在确需登记时才全量归一化。
function RecordEquipmentDiscovery(item)
    if type(item) ~= "table" or item.type ~= "equipment" then return false end
    local key = tostring(item.slot) .. ":" .. tostring(item.quality)
    if not GetEquipmentDiscoveryWhitelist()[key] then return false end
    local codex = playerData.adventureCodex
    if type(codex) == "table"
        and type(codex.equipmentDiscovered) == "table"
        and codex.equipmentDiscovered[key] == true then
        return false
    end
    codex = NormalizeAdventureData()
    if codex.equipmentDiscovered[key] then return false end
    codex.equipmentDiscovered[key] = true
    saveDirty = true
    print("[Codex] 新装备图鉴:", key)
    return true
end

function RecordSkillDiscovery(skill)
    if type(skill) ~= "table" or not ADVENTURE_SKILL_IDS[skill.id] then return false end
    local star = math.max(1, math.min(CONFIG.SkillMaxStar or 10, math.floor(tonumber(skill.star) or 1)))
    local codex = playerData.adventureCodex
    if type(codex) == "table"
        and type(codex.skillDiscovered) == "table"
        and type(codex.skillHighestStar) == "table"
        and codex.skillDiscovered[skill.id] == true
        and star <= (codex.skillHighestStar[skill.id] or 0) then
        return false
    end
    codex = NormalizeAdventureData()
    local changed = codex.skillDiscovered[skill.id] ~= true
    if star > (codex.skillHighestStar[skill.id] or 0) then changed = true end
    codex.skillDiscovered[skill.id] = true
    codex.skillHighestStar[skill.id] = math.max(codex.skillHighestStar[skill.id] or 1, star)
    if changed then
        saveDirty = true
        print("[Codex] 技能图鉴更新:", skill.id, star .. "星")
    end
    return changed
end

function RecordMonsterDiscovery(monsterType)
    if not ADVENTURE_MONSTER_IDS[monsterType] then return false end
    local codex = playerData.adventureCodex
    if type(codex) == "table"
        and type(codex.monsterDiscovered) == "table"
        and codex.monsterDiscovered[monsterType] == true then
        return false
    end
    codex = NormalizeAdventureData()
    if codex.monsterDiscovered[monsterType] then return false end
    codex.monsterDiscovered[monsterType] = true
    saveDirty = true
    print("[Codex] 新怪物图鉴:", monsterType)
    return true
end

function RecordAdventureRefine()
    local codex = NormalizeAdventureData()
    codex.totalRefineCount = codex.totalRefineCount + 1
    saveDirty = true
end

local function GetHighestSkillHistoryStar()
    local highest = 0
    for _, star in pairs(NormalizeAdventureData().skillHighestStar) do highest = math.max(highest, star) end
    return highest
end

function GetAdventureMetric(kind)
    local codex = NormalizeAdventureData()
    if kind == "floor" then return math.max(0, math.floor(playerData.bestFloor or 0)) end
    if kind == "kills" then return math.max(0, math.floor(playerData.totalKills or 0)) end
    if kind == "gold" then return math.max(0, math.floor(playerData.totalGoldEarned or 0)) end
    if kind == "rebirth" then return math.max(0, math.floor(playerData.rebirthCount or 0)) end
    if kind == "equipment" then return CountMapEntries(codex.equipmentDiscovered) end
    if kind == "skills" then return CountMapEntries(codex.skillDiscovered) end
    if kind == "monsters" then return CountMapEntries(codex.monsterDiscovered) end
    if kind == "skillStar" then return GetHighestSkillHistoryStar() end
    if kind == "refine" then return codex.totalRefineCount end
    if kind == "research" then return math.max(0, math.floor(playerData.skillResearch.totalExchanges or 0)) end
    return 0
end

function GetAdventureAchievementProgress(def)
    local current = GetAdventureMetric(def.kind)
    return current, def.target, current >= def.target
end

function GetAdventureAchievementDef(id)
    for _, def in ipairs(ADVENTURE_ACHIEVEMENT_DEFS) do if def.id == id then return def end end
    return nil
end

local function AddRefineStoneWithoutSave(count)
    count = math.max(0, math.floor(count or 0))
    if count <= 0 then return end
    for _, item in ipairs(playerData.inventory or {}) do
        if IsRefineStoneItem(item) then
            item.name = REFINE_STONE_NAME
            item.count = math.max(0, math.floor(item.count or 0)) + count
            return
        end
    end
    table.insert(playerData.inventory, { type = "material", id = REFINE_STONE_ITEM_ID, name = REFINE_STONE_NAME, count = count })
end

function FormatAdventureReward(reward)
    local parts = {}
    if (reward.gold or 0) > 0 then table.insert(parts, "金币+" .. reward.gold) end
    if (reward.refineStone or 0) > 0 then table.insert(parts, (REFINE_STONE_NAME or "白色洗练石") .. "+" .. reward.refineStone) end
    if (reward.rebirthStone or 0) > 0 then table.insert(parts, "转生石+" .. reward.rebirthStone) end
    if reward.title and ADVENTURE_TITLE_DEFS[reward.title] then table.insert(parts, "称号·" .. ADVENTURE_TITLE_DEFS[reward.title].name) end
    return table.concat(parts, "  ")
end

function ClaimAdventureAchievement(id)
    local def = GetAdventureAchievementDef(id)
    if def == nil then return false, "成就不存在" end
    local codex = NormalizeAdventureData()
    if codex.achievementClaims[id] then return false, "奖励已经领取" end
    local _, _, completed = GetAdventureAchievementProgress(def)
    if not completed then return false, "成就尚未完成" end

    codex.achievementClaims[id] = true
    local reward = def.reward or {}
    if (reward.gold or 0) > 0 then AddGold(reward.gold) end
    AddRefineStoneWithoutSave(reward.refineStone)
    playerData.rebirthStone = math.max(0, math.floor(playerData.rebirthStone or 0)) + math.max(0, math.floor(reward.rebirthStone or 0))
    if reward.title and ADVENTURE_TITLE_IDS[reward.title] then codex.unlockedTitles[reward.title] = true end
    saveDirty = true
    SaveCloudData(true)
    print("[Achievement] 已领取:", id, FormatAdventureReward(reward))
    return true, "领取成功：" .. FormatAdventureReward(reward)
end

function GetClaimableAdventureAchievementCount()
    local count = 0
    local codex = NormalizeAdventureData()
    for _, def in ipairs(ADVENTURE_ACHIEVEMENT_DEFS) do
        local _, _, completed = GetAdventureAchievementProgress(def)
        if completed and not codex.achievementClaims[def.id] then count = count + 1 end
    end
    return count
end

function GetAdventureCompletion()
    local codex = NormalizeAdventureData()
    local skillTotal = #(SKILL_ORDER or {})
    local milestoneDone = 0
    for _, def in ipairs(ADVENTURE_MILESTONE_DEFS) do
        if GetAdventureMetric(def.kind) >= def.target then milestoneDone = milestoneDone + 1 end
    end
    local completed = CountMapEntries(codex.skillDiscovered) + milestoneDone
    local total = skillTotal + #ADVENTURE_MILESTONE_DEFS
    local percent = total > 0 and math.floor(completed * 100 / total) or 0
    local changed = false
    for id, def in pairs(ADVENTURE_BADGE_DEFS) do
        if percent >= def.threshold and not codex.unlockedBadges[id] then
            codex.unlockedBadges[id] = true
            changed = true
            print("[Codex] 解锁完成度徽章:", def.name)
        end
    end
    if changed then saveDirty = true end
    return completed, total, percent
end

