local function MergeBoolMaps(target, incoming, whitelist)
    for key, value in pairs(type(incoming) == "table" and incoming or {}) do
        if value == true and whitelist[key] then target[key] = true end
    end
end

function ApplyAdventureSnapshot(incomingCodex, incomingResearch)
    local codex = NormalizeAdventureData()
    if type(incomingCodex) == "table" then
        MergeBoolMaps(codex.equipmentDiscovered, incomingCodex.equipmentDiscovered, GetEquipmentDiscoveryWhitelist())
        MergeBoolMaps(codex.skillDiscovered, incomingCodex.skillDiscovered, ADVENTURE_SKILL_IDS)
        MergeBoolMaps(codex.monsterDiscovered, incomingCodex.monsterDiscovered, ADVENTURE_MONSTER_IDS)
        MergeBoolMaps(codex.achievementClaims, incomingCodex.achievementClaims, ADVENTURE_ACHIEVEMENT_IDS)
        MergeBoolMaps(codex.unlockedTitles, incomingCodex.unlockedTitles, ADVENTURE_TITLE_IDS)
        MergeBoolMaps(codex.unlockedBadges, incomingCodex.unlockedBadges, ADVENTURE_BADGE_IDS)
        if type(incomingCodex.selectedTitleStyleId) == "string" and ADVENTURE_TITLE_STYLE_DEFS[incomingCodex.selectedTitleStyleId] then
            codex.selectedTitleStyleId = incomingCodex.selectedTitleStyleId
        end
        if type(incomingCodex.selectedTitleInnerBgId) == "string" and ADVENTURE_TITLE_INNER_BG_DEFS[incomingCodex.selectedTitleInnerBgId] then
            codex.selectedTitleInnerBgId = incomingCodex.selectedTitleInnerBgId
        end
        for id, star in pairs(type(incomingCodex.skillHighestStar) == "table" and incomingCodex.skillHighestStar or {}) do
            if ADVENTURE_SKILL_IDS[id] then codex.skillHighestStar[id] = math.max(codex.skillHighestStar[id] or 0, math.floor(tonumber(star) or 0)) end
        end
        codex.totalRefineCount = math.max(codex.totalRefineCount, math.floor(tonumber(incomingCodex.totalRefineCount) or 0))
        if incomingCodex.selectedTitleId and codex.unlockedTitles[incomingCodex.selectedTitleId] then codex.selectedTitleId = incomingCodex.selectedTitleId end
        if incomingCodex.selectedBadgeId == "" or codex.unlockedBadges[incomingCodex.selectedBadgeId] then codex.selectedBadgeId = incomingCodex.selectedBadgeId or codex.selectedBadgeId end
    end
    if type(incomingResearch) == "table" then
        playerData.skillResearch.totalExchanges = math.max(playerData.skillResearch.totalExchanges, math.floor(tonumber(incomingResearch.totalExchanges) or 0))
    end
    NormalizeAdventureData()
end

function SanitizeAdventureSnapshot(snapshot)
    if type(snapshot) ~= "table" then return end
    local codex = snapshot.adventureCodex
    if type(codex) == "table" then
        codex.equipmentDiscovered = SanitizeBoolMap(codex.equipmentDiscovered, GetEquipmentDiscoveryWhitelist())
        codex.skillDiscovered = SanitizeBoolMap(codex.skillDiscovered, ADVENTURE_SKILL_IDS)
        codex.monsterDiscovered = SanitizeBoolMap(codex.monsterDiscovered, ADVENTURE_MONSTER_IDS)
        codex.achievementClaims = SanitizeBoolMap(codex.achievementClaims, ADVENTURE_ACHIEVEMENT_IDS)
        codex.unlockedTitles = SanitizeBoolMap(codex.unlockedTitles, ADVENTURE_TITLE_IDS)
        codex.unlockedBadges = SanitizeBoolMap(codex.unlockedBadges, ADVENTURE_BADGE_IDS)
        codex.totalRefineCount = math.max(0, math.min(100000000, math.floor(tonumber(codex.totalRefineCount) or 0)))
    end
    if type(snapshot.skillResearch) == "table" then
        snapshot.skillResearch.totalExchanges = math.max(0, math.min(100000000, math.floor(tonumber(snapshot.skillResearch.totalExchanges) or 0)))
    end
end

local function StableMapSignature(source)
    local keys = {}
    for key, value in pairs(type(source) == "table" and source or {}) do
        if value == true or type(value) == "number" then table.insert(keys, tostring(key) .. "=" .. tostring(value)) end
    end
    table.sort(keys)
    return table.concat(keys, ",")
end

function GetAdventureSaveSignature(codex, research)
    codex = type(codex) == "table" and codex or {}
    research = type(research) == "table" and research or {}
    return table.concat({
        StableMapSignature(codex.equipmentDiscovered),
        StableMapSignature(codex.skillDiscovered),
        StableMapSignature(codex.skillHighestStar),
        StableMapSignature(codex.monsterDiscovered),
        StableMapSignature(codex.achievementClaims),
        StableMapSignature(codex.unlockedTitles),
        StableMapSignature(codex.unlockedBadges),
        tostring(codex.selectedTitleId or ""),
        tostring(codex.selectedTitleStyleId or ""),
        tostring(codex.selectedTitleInnerBgId or ""),
        tostring(codex.selectedBadgeId or ""),
        tostring(math.floor(tonumber(codex.totalRefineCount) or 0)),
        tostring(math.floor(tonumber(research.totalExchanges) or 0)),
    }, "|")
end

skillProtectionCacheSignature = nil
skillProtectionCache = nil

function RebuildSkillProtectionCache()
    NormalizeSkillLoadouts()
    local protected = {}
    for index = 1, GetUnlockedSkillSlotCount() do
        local uid = playerData.skillSlots and playerData.skillSlots[index]
        if uid ~= nil then protected[uid] = "该技能正在装备栏中使用" end
    end
    for loadoutIndex = 1, 2 do
        for _, record in pairs(
            playerData.skillLoadouts[loadoutIndex].slots or {}
        ) do
            if record.uid ~= nil and protected[record.uid] == nil then
                protected[record.uid] = "该技能被技能方案" .. loadoutIndex .. "引用"
            end
        end
    end
    skillProtectionCache = protected
    skillProtectionCacheSignature = tostring(playerData.activeSkillLoadoutIndex or 1)
        .. ":" .. tostring(playerData.unlockedSkillSlots or 0)
    return protected
end

function IsSkillProtectedFromResearch(uid)
    if uid == nil then return false end
    local signature = tostring(playerData.activeSkillLoadoutIndex or 1)
        .. ":" .. tostring(playerData.unlockedSkillSlots or 0)
    if skillProtectionCache == nil
        or skillProtectionCacheSignature ~= signature then
        RebuildSkillProtectionCache()
    end
    local reason = skillProtectionCache[uid]
    return reason ~= nil, reason
end

function NormalizeSkillFragmentsData(source)
    source = type(source) == "table" and source or {}
    local normalized = {}
    local maxCount = CONFIG.SkillFragmentMaxCount or 999999
    for star = 1, CONFIG.SkillMaxStar or 10 do
        local raw = source[star]
        if raw == nil then raw = source[tostring(star)] end
        normalized[star] = math.max(0, math.min(maxCount, math.floor(tonumber(raw) or 0)))
    end
    return normalized
end

function NormalizeSkillFragments()
    playerData.skillFragments = NormalizeSkillFragmentsData(playerData.skillFragments)
    return playerData.skillFragments
end

function CanDismantleSkill(sourceUid)
    if currentScreen == "playing" then return false, "战斗中不能分解技能" end
    NormalizeSkills()
    NormalizeSkillFragments()
    local source = FindSkillCardByUid(sourceUid)
    if source == nil then return false, "技能卡不存在" end
    local star = GetSkillStar(source)
    local maxDismantleStar = math.max(1, CONFIG.SkillDismantleMaxStar or 2)
    if star > maxDismantleStar then
        return false, (maxDismantleStar + 1) .. "星及以上的技能不能分解"
    end
    local protected, reason = IsSkillProtectedFromResearch(sourceUid)
    if protected then return false, reason end
    return true, nil, source, star, CONFIG.SkillFragmentDismantleYield or 1
end

function DismantleSkill(sourceUid)
    local allowed, reason, source, star, yield = CanDismantleSkill(sourceUid)
    if not allowed then return false, reason end
    local sourceIndex = nil
    for index, skill in ipairs(playerData.skills or {}) do
        if skill.uid == sourceUid then sourceIndex = index break end
    end
    if sourceIndex == nil then return false, "技能卡不存在" end
    table.remove(playerData.skills, sourceIndex)
    playerData.skillFragments[star] = math.min(
        CONFIG.SkillFragmentMaxCount or 999999,
        (playerData.skillFragments[star] or 0) + yield
    )
    NormalizeSkills()
    NormalizeSkillFragments()
    saveDirty = true
    SaveCloudData(true)
    print("[SkillFragment] 分解:", source.id, star .. "星", "+", yield)
    return true, "分解成功：获得" .. star .. "星碎片 ×" .. yield, star, yield
end

function GetDismantleBatchPreview(star)
    if currentScreen == "playing" then
        return {
            canExecute = false,
            blockedReason = "战斗中不能分解技能",
            star = math.floor(tonumber(star) or 0),
            candidateUids = {},
            skipReasons = {},
            eligibleCount = 0,
            skippedCount = 0,
            expectedYield = 0,
        }
    end

    NormalizeSkills()
    local fragments = NormalizeSkillFragments()
    RebuildSkillProtectionCache()

    star = math.floor(tonumber(star) or 0)
    local maxDismantleStar = math.max(1, CONFIG.SkillDismantleMaxStar or 2)
    if star < 1 or star > maxDismantleStar then
        return {
            canExecute = false,
            blockedReason = "只能选择1～" .. maxDismantleStar .. "星技能",
            star = star,
            candidateUids = {},
            skipReasons = {},
            eligibleCount = 0,
            skippedCount = 0,
            expectedYield = 0,
        }
    end

    local candidateUids = {}
    local skipReasons = {}
    local totalCount = 0
    for _, skill in ipairs(playerData.skills or {}) do
        if GetSkillStar(skill) == star then
            totalCount = totalCount + 1
            local protected, reason = IsSkillProtectedFromResearch(skill.uid)
            if protected then
                skipReasons[reason] = (skipReasons[reason] or 0) + 1
            else
                table.insert(candidateUids, skill.uid)
            end
        end
    end

    local yield = CONFIG.SkillFragmentDismantleYield or 1
    local expectedYield = #candidateUids * yield
    local maxFragments = CONFIG.SkillFragmentMaxCount or 999999
    local currentFragments = fragments[star] or 0
    local blockedReason = nil
    if #candidateUids == 0 then
        blockedReason = "当前没有可分解的" .. star .. "星技能"
    elseif currentFragments + expectedYield > maxFragments then
        blockedReason = star .. "星碎片将超过上限（当前" .. currentFragments
            .. "，预计获得" .. expectedYield .. "，上限" .. maxFragments .. "），本次不执行"
    end

    local skippedCount = 0
    for _, count in pairs(skipReasons) do skippedCount = skippedCount + count end
    return {
        canExecute = blockedReason == nil,
        blockedReason = blockedReason,
        star = star,
        totalCount = totalCount,
        candidateUids = candidateUids,
        eligibleCount = #candidateUids,
        skippedCount = skippedCount,
        skipReasons = skipReasons,
        expectedYield = expectedYield,
        yieldPerSkill = yield,
        currentFragments = currentFragments,
        maxFragments = maxFragments,
    }
end

function DismantleSkillsByStar(star)
    local preview = GetDismantleBatchPreview(star)
    if not preview.canExecute then
        return false, preview.blockedReason, preview
    end

    local removeUids = {}
    for _, uid in ipairs(preview.candidateUids) do removeUids[uid] = true end
    local removedCount = 0
    for index = #(playerData.skills or {}), 1, -1 do
        if removeUids[playerData.skills[index].uid] then
            table.remove(playerData.skills, index)
            removedCount = removedCount + 1
        end
    end
    if removedCount ~= preview.eligibleCount then
        return false, "技能数据发生变化，请刷新后重试", preview
    end

    playerData.skillFragments[preview.star] = preview.currentFragments + preview.expectedYield
    NormalizeSkills()
    NormalizeSkillFragments()
    saveDirty = true
    SaveCloudData(true)
    print("[SkillFragment] 一键分解:", preview.star .. "星", "数量:", removedCount, "碎片:", preview.expectedYield)
    return true, "已分解 " .. removedCount .. " 张" .. preview.star .. "星技能，获得"
        .. preview.star .. "星碎片 ×" .. preview.expectedYield, preview
end

-- 自动分解：目标星级为保底下限，分解所有不高于该星级的未装备/未引用技能。
-- 用于每层结算后自动清理低星技能卡，产出同星碎片。
function TryAutoDismantleSkills(reason)
    NormalizeEquipmentSettings()
    if playerData.settings.autoDismantleEnabled ~= true then
        return 0
    end
    local targetStar = math.max(1, math.min(
        CONFIG.SkillDismantleMaxStar or 2,
        math.floor(playerData.settings.autoDismantleTargetStar or 3)
    ))
    NormalizeSkills()
    NormalizeSkillFragments()
    RebuildSkillProtectionCache()

    local dismantledCount = 0
    local yieldByStar = {}
    local maxFragments = CONFIG.SkillFragmentMaxCount or 999999
    for index = #(playerData.skills or {}), 1, -1 do
        local skill = playerData.skills[index]
        if skill ~= nil then
            local star = math.max(1, math.min(CONFIG.SkillMaxStar or 10, GetSkillStar(skill)))
            if star <= targetStar then
                local protected = IsSkillProtectedFromResearch(skill.uid)
                if not protected then
                    local yield = CONFIG.SkillFragmentDismantleYield or 1
                    local newFragmentCount = (playerData.skillFragments[star] or 0) + yield
                    if newFragmentCount <= maxFragments then
                        playerData.skillFragments[star] = newFragmentCount
                        table.remove(playerData.skills, index)
                        dismantledCount = dismantledCount + 1
                        yieldByStar[star] = (yieldByStar[star] or 0) + yield
                    end
                end
            end
        end
    end

    if dismantledCount > 0 then
        NormalizeSkills()
        NormalizeSkillFragments()
        saveDirty = true
        SaveCloudData(true)
        local parts = {}
        for star, count in pairs(yieldByStar) do
            table.insert(parts, tostring(star) .. "星碎片×" .. tostring(count))
        end
        table.sort(parts)
        print("[SkillFragment] 自动分解:", reason or "floor_complete", "目标:", targetStar,
            "数量:", dismantledCount, "碎片:", table.concat(parts, "，"))
    end
    return dismantledCount
end

-- 自动分解预览：统计当前目标星级及以下的可分解技能数量（不实际分解）。
function GetAutoDismantleCount()
    NormalizeEquipmentSettings()
    if playerData.settings.autoDismantleEnabled ~= true then
        return 0
    end
    local targetStar = math.max(1, math.min(
        CONFIG.SkillDismantleMaxStar or 2,
        math.floor(playerData.settings.autoDismantleTargetStar or 3)
    ))
    NormalizeSkills()
    RebuildSkillProtectionCache()
    local count = 0
    for _, skill in ipairs(playerData.skills or {}) do
        if skill ~= nil then
            local star = math.max(1, math.min(CONFIG.SkillMaxStar or 10, GetSkillStar(skill)))
            if star <= targetStar then
                local protected = IsSkillProtectedFromResearch(skill.uid)
                if not protected then
                    count = count + 1
                end
            end
        end
    end
    return count
end

-- 自动分解预览明细：按星级返回目标星级及以下的可分解技能数量（不实际分解）。
-- 返回 { [star] = count, total = n }。
function GetAutoDismantlePreview()
    NormalizeEquipmentSettings()
    local breakdown = {}
    local total = 0
    if playerData.settings.autoDismantleEnabled ~= true then
        return { total = 0, breakdown = breakdown }
    end
    local targetStar = math.max(1, math.min(
        CONFIG.SkillDismantleMaxStar or 2,
        math.floor(playerData.settings.autoDismantleTargetStar or 3)
    ))
    NormalizeSkills()
    RebuildSkillProtectionCache()
    for _, skill in ipairs(playerData.skills or {}) do
        if skill ~= nil then
            local star = math.max(1, math.min(CONFIG.SkillMaxStar or 10, GetSkillStar(skill)))
            if star <= targetStar then
                local protected = IsSkillProtectedFromResearch(skill.uid)
                if not protected then
                    breakdown[star] = (breakdown[star] or 0) + 1
                    total = total + 1
                end
            end
        end
    end
    return { total = total, breakdown = breakdown }
end

function CanSynthesizeSkillFromFragments(star)
    if currentScreen == "playing" then return false, "战斗中不能合成技能" end
    NormalizeSkills()
    local fragments = NormalizeSkillFragments()
    star = math.floor(tonumber(star) or 0)
    local maxFragmentStar = math.max(1, CONFIG.SkillFragmentSynthesisMaxStar or 2)
    if star < 1 or star > maxFragmentStar then
        return false, "只有1～" .. maxFragmentStar .. "星碎片可以合成"
    end
    local cost = CONFIG.SkillFragmentSynthesisCost or 5
    if (fragments[star] or 0) < cost then
        return false, star .. "星碎片不足，需要" .. cost .. "个"
    end
    local usage = GetSkillCapacityUsage()
    local capacity = CONFIG.MaxUnequippedSkillCards or 250
    if usage >= capacity then
        return false, "技能背包已满（" .. usage .. "/" .. capacity .. "）"
    end
    if #(SKILL_ORDER or {}) == 0 then return false, "没有可合成的技能" end
    return true, nil, cost
end

function SynthesizeSkillFromFragments(star)
    local allowed, reason, cost = CanSynthesizeSkillFromFragments(star)
    if not allowed then return false, reason end
    star = math.floor(tonumber(star) or 1)
    local resultStar = star + 1
    local skillId = SKILL_ORDER[math.random(1, #SKILL_ORDER)]
    local def = GetSkillDef(skillId)
    if def == nil then return false, "随机技能不存在" end
    local result = {
        uid = AllocateSkillUid(),
        id = skillId,
        name = def.name,
        desc = def.desc,
        icon = def.icon,
        star = resultStar,
        cooldown = GetSkillBaseCooldown(skillId),
    }
    local fragments = NormalizeSkillFragmentsData(playerData.skillFragments)
    playerData.skillFragments = fragments
    fragments[star] = math.max(0, (tonumber(fragments[star]) or 0) - cost)
    table.insert(playerData.skills, result)
    NormalizeSkills()
    NormalizeSkillFragments()
    RecordSkillDiscovery(result)
    saveDirty = true
    SaveCloudData(true)
    print("[SkillFragment] 升星合成:", star .. "星碎片", "->", skillId, resultStar .. "星", "消耗:", cost)
    return true, "合成成功：" .. def.name .. " " .. resultStar .. "星", result
end

-- 碎片随机合成当前最多可执行的次数（受碎片数量与技能背包容量限制）。
function GetSkillFragmentSynthesisMaxCount(star)
    star = math.max(1, math.floor(tonumber(star) or 1))
    if currentScreen == "playing" then return 0, "战斗中不能合成技能" end
    local fragments = NormalizeSkillFragments()
    local fragmentCost = CONFIG.SkillFragmentSynthesisCost or 5
    local fragmentBalance = math.floor(tonumber(fragments[star]) or 0)
    if fragmentBalance < fragmentCost then
        return 0, star .. "星碎片不足，需要" .. fragmentCost .. "个"
    end
    if #(SKILL_ORDER or {}) == 0 then return 0, "没有可合成的技能" end
    local usage = GetSkillCapacityUsage()
    local capacity = CONFIG.MaxUnequippedSkillCards or 250
    local freeBag = math.max(0, capacity - usage)
    local maxCount = math.floor(fragmentBalance / fragmentCost)
    maxCount = math.min(maxCount, freeBag)
    if maxCount < 1 then
        return 0, "技能背包空间不足（" .. usage .. "/" .. capacity .. "）"
    end
    return maxCount, nil
end

-- 批量碎片随机合成：连续执行 count 次合成，每次消耗5个碎片，随机获得1张N+1星技能卡。
function BatchSynthesizeSkillFromFragments(star, count)
    count = math.floor(tonumber(count) or 0)
    star = math.max(1, math.floor(tonumber(star) or 1))
    local maxCount, reason = GetSkillFragmentSynthesisMaxCount(star)
    if maxCount < 1 then
        return false, reason or "无法批量合成"
    end
    if count < 1 then return false, "合成次数无效" end
    if count > maxCount then
        return false, "最多可合成" .. maxCount .. "次"
    end
    local resultStar = star + 1
    local fragmentCost = CONFIG.SkillFragmentSynthesisCost or 5
    local fragments = NormalizeSkillFragmentsData(playerData.skillFragments)
    playerData.skillFragments = fragments
    for _ = 1, count do
        local skillId = SKILL_ORDER[math.random(1, #SKILL_ORDER)]
        local def = GetSkillDef(skillId)
        if def == nil then
            NormalizeSkills()
            NormalizeSkillFragments()
            return false, "随机技能不存在，本次批量合成中止"
        end
        local result = {
            uid = AllocateSkillUid(),
            id = skillId,
            name = def.name,
            desc = def.desc,
            icon = def.icon,
            star = resultStar,
            cooldown = GetSkillBaseCooldown(skillId),
        }
        table.insert(playerData.skills, result)
        fragments[star] = math.max(0, (tonumber(fragments[star]) or 0) - fragmentCost)
        RecordSkillDiscovery(result)
    end
    NormalizeSkills()
    NormalizeSkillFragments()
    saveDirty = true
    SaveCloudData(true)
    print("[SkillFragment] 批量升星合成:", star .. "星碎片", "->", resultStar .. "星",
        "次数:", count, "消耗:", fragmentCost * count, "个碎片")
    return true, "批量合成成功" .. count .. "次：获得" .. count .. "张随机"
        .. resultStar .. "星技能卡（消耗" .. (fragmentCost * count) .. "个" .. star .. "星碎片）"
end


NEAREST_KINDS = {
    hero        = true,
    heroWing    = true,
    heroWingSmall = true,
    titleEmblem = true,
    titleStyle = true,
    titleInnerBg = true,
    weapon      = true,
    weaponFlame  = true,
    monster     = true,
    splitter    = true,
}

function QueueAssetLoad(kind, path, category, visualId)
    table.insert(assetLoadQueue, {
        kind = kind,
        path = path,
        category = category,
        visualId = visualId,
    })
end

function StartAssetLoading()
    monsterImages = {}
    monsterImageBags = {}
    monsterImageSizes = {}
    for _, category in ipairs(monsterImageCategories or {}) do
        monsterImages[category] = {}
        monsterImageBags[category] = {}
    end
    weaponImages = {}
    weaponFlameImages = {}
    splitterImage = 0
    bgImages = {}
    heroImage = 0
    heroWingImage = 0
    heroWingSmallImage = 0
    leaderboardFirstWingImage = 0
    titleEmblemImages = {}
    titleStyleImages = {}
    titleInnerBgImages = {}
    weaponGlowImage = 0
    baseImage = 0
    currentBgIndex = 0
    assetLoadQueue = {}
    assetLoadIndex = 1
    assetLoadDone = false

    QueueAssetLoad("hero", heroImagePath)
    QueueAssetLoad("heroWing", heroWingImagePath)
    QueueAssetLoad("heroWingSmall", heroWingSmallImagePath)
    QueueAssetLoad("leaderboardFirstWing", leaderboardFirstWingImagePath)
    for titleId, titleDef in pairs(ADVENTURE_TITLE_DEFS or {}) do
        if titleDef.iconPath then QueueAssetLoad("titleEmblem", titleDef.iconPath, nil, titleId) end
    end
    for styleId, styleDef in pairs(ADVENTURE_TITLE_STYLE_DEFS or {}) do
        QueueAssetLoad("titleStyle", styleDef.imagePath, nil, styleId)
    end
    for innerBgId, innerBgDef in pairs(ADVENTURE_TITLE_INNER_BG_DEFS or {}) do
        QueueAssetLoad("titleInnerBg", innerBgDef.imagePath, nil, innerBgId)
    end
    QueueAssetLoad("base", baseImagePath)
    QueueAssetLoad("splitter", splitterImagePath)
    for visualId, path in pairs(weaponImagePaths) do
        QueueAssetLoad("weapon", path, nil, visualId)
    end
    for tier, path in pairs(weaponFlameImagePaths or {}) do
        QueueAssetLoad("weaponFlame", path, nil, tier)
    end
    for _, path in ipairs(bgImagePaths) do
        QueueAssetLoad("background", path)
    end
    for _, category in ipairs(monsterImageCategories or {}) do
        local paths = monsterImagePaths[category] or {}
        for _, path in ipairs(paths) do
            QueueAssetLoad("monster", path, category)
        end
    end
    print("[Assets] 本地图片加入分帧加载队列:", #assetLoadQueue, "张")
end

function ProcessAssetLoadQueue(maxCount)
    if assetLoadDone or nvgContext == nil then return end

    local loadedThisFrame = 0
    while loadedThisFrame < maxCount and assetLoadIndex <= #assetLoadQueue do
        local item = assetLoadQueue[assetLoadIndex]
        local imageFlags = NEAREST_KINDS[item.kind] and 8 or 0
        local handle = nvgCreateImage(nvgContext, item.path, imageFlags)
        if handle > 0 then
            if item.kind == "monster" or item.kind == "splitter" then
                local imageW, imageH = nvgImageSize(nvgContext, handle)
                monsterImageSizes[handle] = { w = imageW, h = imageH }
            end
            if item.kind == "hero" then
                heroImage = handle
                print("[Hero] 加载主角:", item.path)
            elseif item.kind == "heroWing" then
                heroWingImage = handle
                print("[Hero] 加载大暗紫魔翼:", item.path)
            elseif item.kind == "heroWingSmall" then
                heroWingSmallImage = handle
                print("[Hero] 加载小暗紫魔翼:", item.path)
            elseif item.kind == "leaderboardFirstWing" then
                leaderboardFirstWingImage = handle
                print("[Hero] 加载榜一白金圣翼:", item.path)
            elseif item.kind == "titleEmblem" then
                titleEmblemImages[item.visualId] = handle
            elseif item.kind == "titleStyle" then
                titleStyleImages[item.visualId] = handle
            elseif item.kind == "titleInnerBg" then
                titleInnerBgImages[item.visualId] = handle
            elseif item.kind == "weaponGlow" then
                weaponGlowImage = handle
                print("[Weapon] 加载武器赤紫魔焰光效:", item.path)
            elseif item.kind == "base" then
                baseImage = handle
                print("[Base] 加载主基地:", item.path)
            elseif item.kind == "splitter" then
                splitterImage = handle
                print("[Monster] 加载分裂怪固定模型:", item.path)
            elseif item.kind == "weapon" then
                weaponImages[item.visualId] = handle
            elseif item.kind == "weaponFlame" then
                weaponFlameImages[item.visualId] = handle
                print("[Weapon] 加载强化火焰贴图 tier=" .. tostring(item.visualId) .. ":", item.path)
            elseif item.kind == "background" then
                table.insert(bgImages, handle)
                if currentBgIndex == 0 then
                    currentBgIndex = 1
                end
                print("[BG] 加载背景:", item.path)
            elseif item.kind == "monster" then
                if monsterImages[item.category] == nil then
                    monsterImages[item.category] = {}
                end
                table.insert(monsterImages[item.category], handle)
                if monsterImageBags then
                    monsterImageBags[item.category] = nil
                end
            end
        else
            print("[Assets] 加载失败:", item.path)
        end

        assetLoadIndex = assetLoadIndex + 1
        loadedThisFrame = loadedThisFrame + 1
    end

    if assetLoadIndex > #assetLoadQueue then
        assetLoadDone = true
        if #bgImages > 0 and currentBgIndex == 0 then
            currentBgIndex = math.random(1, #bgImages)
        end
        print("[Assets] 本地图片分帧加载完成")
    end
end

LOCAL_SAVE_MAGIC = "DGSV3"
LOCAL_SAVE_MAGIC_V2 = "DGSV2"
LOCAL_SAVE_VERSION = 3
LOCAL_SAVE_XOR_KEY = "JianWeyV3xK9pQ2mNz"
LOCAL_SAVE_HASH_SALT = "GuardH4shV3!Salt@2026"
LOCAL_SAVE_INLINE_SALT = "ChkSumV3Inline_9xQ"
LOCAL_SAVE_CLOUD_SALT = "CloudBlobV3!K7x@2026"

function OfficialBatchGet()
    local request = clientCloud:BatchGet()
    local proxy = {}

    function proxy:Key(key)
        request:Key(OfficialSaveKey(key))
        return self
    end

    function proxy:Fetch(events)
        request:Fetch({
            ok = function(values, iscores)
                local officialValues = {}
                local officialScores = {}
                for key, value in pairs(values or {}) do
                    local plainKey = tostring(key):match("^" .. OFFICIAL_SAVE_PREFIX .. "(.+)$")
                    if plainKey ~= nil then officialValues[plainKey] = value end
                end
                for key, value in pairs(iscores or {}) do
                    local plainKey = tostring(key):match("^" .. OFFICIAL_SAVE_PREFIX .. "(.+)$")
                    if plainKey ~= nil then officialScores[plainKey] = value end
                end
                if events and events.ok then events.ok(officialValues, officialScores) end
            end,
            error = events and events.error or nil,
            timeout = events and events.timeout or nil,
        })
    end

    return proxy
end

function OfficialBatchSet()
    local request = clientCloud:BatchSet()
    local proxy = {}

    function proxy:Set(key, value)
        request:Set(OfficialSaveKey(key), value)
        return self
    end

    function proxy:SetInt(key, value)
        request:SetInt(OfficialSaveKey(key), value)
        return self
    end

    function proxy:Add(key, value)
        request:Add(OfficialSaveKey(key), value)
        return self
    end

    function proxy:Delete(key)
        request:Delete(OfficialSaveKey(key))
        return self
    end

    function proxy:Save(description, events)
        request:Save(description, events)
    end

    return proxy
end

function CopyLegacyDisplaySettings(settings)
    local source = type(settings) == "table" and settings or {}
    local preserved = {}
    local allowed = {
        "musicVolume", "sfxVolume", "sfxEnabled",
        "graphicsQuality", "qualityLevel", "renderScale",
    }
    for _, key in ipairs(allowed) do
        if source[key] ~= nil then preserved[key] = source[key] end
    end
    return preserved
end

