function StrongSaveHash(text)
    text = tostring(text or "") .. "|" .. LOCAL_SAVE_HASH_SALT
    local len = #text
    local h1, h2, h3, h4 = 2166136261, 5381, 1315423911, 0x811c9dc5
    for i = 1, len do
        local b = string.byte(text, i)
        local pos = i
        h1 = ((h1 ~ b) * 16777619 + pos * 31) % 2147483647
        h2 = (h2 * 33 + b * (1 + (pos % 7)) + pos) % 2147483647
        local rpos = len - i + 1
        h3 = (h3 * 131 + b * rpos) % 2147483647
        h4 = ((h4 * 16777619) ~ (b + pos * 17)) % 2147483647
    end
    local final = (h1 ~ h2) + (h3 ~ h4)
    final = (final * 2654435761 + h1 + h3) % 2147483647
    final = (final ~ (final >> 16)) * 2246822519 % 2147483647
    return string.format("%08x%08x%08x", h1, h2 ~ h4, final)
end

function LocalSaveHashV2(text)
    text = tostring(text or "") .. "|DaJianGuardSaveV2"
    local h1 = 5381
    local h2 = 1315423911
    for i = 1, #text do
        local b = string.byte(text, i)
        h1 = (h1 * 33 + b + i) % 2147483647
        h2 = (h2 * 131 + b * i) % 2147483647
    end
    return string.format("%08x%08x", h1, h2)
end

-- 本地快照 hex 编码提速：逐字符 string.format("%02x") 并重复取密钥字节，
-- 在大存档落盘（连打结算提交大量战利品）时是主线程卡顿的主要来源。
-- 查表 / 预取密钥的结果与旧实现逐字节一致，不影响存档内容与兼容性。
---@type table<integer, string>
local LOCAL_SAVE_HEX_ENCODE = (function()
    local cache = {}
    for value = 0, 255 do
        cache[value] = string.format("%02x", value)
    end
    return cache
end)()

---@type table<integer, integer>
local LOCAL_SAVE_KEY_BYTES = (function()
    local bytes = {}
    for index = 1, #LOCAL_SAVE_XOR_KEY do
        bytes[index] = string.byte(LOCAL_SAVE_XOR_KEY, index)
    end
    return bytes
end)()

function LocalSaveToHex(text)
    local keyLen = #LOCAL_SAVE_KEY_BYTES
    local hexOf = LOCAL_SAVE_HEX_ENCODE
    local keyBytes = LOCAL_SAVE_KEY_BYTES
    local out = {}
    local prev = 0
    for i = 1, #text do
        local b = string.byte(text, i)
        local k1 = keyBytes[((i - 1) % keyLen) + 1]
        local k2 = keyBytes[((i * 7 - 1) % keyLen) + 1]
        local ks = (k1 + k2 * 3 + i * 31 + prev * 7) % 256
        local enc = (b ~ ks) & 0xff
        out[i] = hexOf[enc]
        prev = enc
    end
    return table.concat(out)
end

function LocalSaveFromHex(hex)
    if type(hex) ~= "string" or (#hex % 2) ~= 0 then return nil end
    local keyLen = #LOCAL_SAVE_XOR_KEY
    local out = {}
    local prev = 0
    for i = 1, #hex, 2 do
        local value = tonumber(string.sub(hex, i, i + 1), 16)
        if value == nil then return nil end
        local index = (i + 1) / 2
        local k1 = string.byte(LOCAL_SAVE_XOR_KEY, ((index - 1) % keyLen) + 1)
        local k2 = string.byte(LOCAL_SAVE_XOR_KEY, ((index * 7 - 1) % keyLen) + 1)
        local ks = (k1 + k2 * 3 + index * 31 + prev * 7) % 256
        out[index] = string.char((value ~ ks) & 0xff)
        prev = value
    end
    return table.concat(out)
end

function LocalSaveFromHexV2(hex)
    if type(hex) ~= "string" or (#hex % 2) ~= 0 then return nil end
    local v2key = "DaJianGuardSaveV2"
    local out = {}
    for i = 1, #hex, 2 do
        local value = tonumber(string.sub(hex, i, i + 1), 16)
        if value == nil then return nil end
        local index = (i + 1) / 2
        local k = string.byte(v2key, ((index - 1) % #v2key) + 1)
        out[index] = string.char((value ~ ((k + index * 17) % 256)) & 0xff)
    end
    return table.concat(out)
end

function ComputeInlineChecksum(snapshot, includeRiftPressure)
    if type(snapshot) ~= "table" then return "0" end
    local parts = {
        tostring(math.floor(tonumber(snapshot.gold) or 0)),
        tostring(math.floor(tonumber(snapshot.highScore) or 0)),
        tostring(math.floor(tonumber(snapshot.totalKills) or 0)),
        tostring(math.floor(tonumber(snapshot.playCount) or 0)),
        tostring(math.floor(tonumber(snapshot.bestFloor) or 0)),
        tostring(math.floor(tonumber(snapshot.rebirthCount) or 0)),
        tostring(math.floor(tonumber(snapshot.rebirthUpgradeCount) or 0)),
        tostring(math.floor(tonumber(snapshot.rebirthStone) or 0)),
        tostring(math.floor(tonumber(snapshot.skipLevelUpgradeLevel) or 0)),
    }
    if includeRiftPressure ~= false then
        table.insert(parts, tostring(math.floor(tonumber(snapshot.equipmentRiftPressure) or 0)))
        table.insert(parts, tostring(snapshot.equipmentRiftPressureDayKey or ""))
    end
    local raw = table.concat(parts, "|") .. "|" .. LOCAL_SAVE_INLINE_SALT
    local h = 0x12345678
    for i = 1, #raw do
        h = ((h ~ string.byte(raw, i)) * 1103515245 + 12345 + i * 7) % 2147483647
    end
    return string.format("%08x", h)
end

function ComputeCloudBlobHash(snapshot, includeClass, includeRiftPressure)
    if type(snapshot) ~= "table" then return "0" end
    local parts = {
        tostring(math.floor(tonumber(snapshot.gold) or 0)),
        tostring(math.floor(tonumber(snapshot.highScore) or 0)),
        tostring(math.floor(tonumber(snapshot.totalKills) or 0)),
        tostring(math.floor(tonumber(snapshot.playCount) or 0)),
        tostring(math.floor(tonumber(snapshot.bestFloor) or 0)),
        tostring(math.floor(tonumber(snapshot.rebirthCount) or 0)),
        tostring(math.floor(tonumber(snapshot.rebirthUpgradeCount) or 0)),
        tostring(math.floor(tonumber(snapshot.rebirthStone) or 0)),
        tostring(math.floor(tonumber(snapshot.skipLevelUpgradeLevel) or 0)),
        tostring(math.floor(tonumber(snapshot.dailyRebirthStoneEarned) or 0)),
        tostring(snapshot.dailyRebirthStoneDayKey or ""),
    }
    if includeRiftPressure ~= false then
        table.insert(parts, tostring(math.floor(tonumber(snapshot.equipmentRiftPressure) or 0)))
        table.insert(parts, tostring(snapshot.equipmentRiftPressureDayKey or ""))
    end
    table.insert(parts, tostring(type(snapshot.inventory) == "table" and #snapshot.inventory or 0))
    table.insert(parts, tostring(type(snapshot.skills) == "table" and #snapshot.skills or 0))
    table.insert(parts, tostring(type(snapshot.equipmentSets) == "table" and #snapshot.equipmentSets or 0))
    table.insert(parts, tostring(type(snapshot.redeemedCodes) == "table" and #snapshot.redeemedCodes or 0))
    table.insert(parts, GetSkillSynergySaveSignature(snapshot.skillSynergy))
    if includeClass ~= false then
        local settings = type(snapshot.settings) == "table"
            and snapshot.settings
            or {}
        table.insert(
            parts,
            NormalizeSelectedClassId(settings.selectedClassId)
        )
    end
    local raw = table.concat(parts, "|")
    if type(snapshot.cloneProtocols) == "table" then
        raw = raw .. "|" .. GetCloneProtocolsSaveSignature(snapshot.cloneProtocols)
    end
    if type(snapshot.adventureCodex) == "table" then
        raw = raw .. "|" .. GetAdventureSaveSignature(snapshot.adventureCodex, snapshot.skillResearch)
    end
    raw = raw .. "|" .. LOCAL_SAVE_CLOUD_SALT
    local h = 0xdeadbeef
    for i = 1, #raw do
        h = ((h ~ string.byte(raw, i)) * 2246822519 + i * 13) % 2147483647
    end
    return string.format("%08x", h)
end

local function ComputeLegacyCloudBlobHash(snapshot)
    if type(snapshot) ~= "table" then return "0" end
    local parts = {
        tostring(math.floor(tonumber(snapshot.gold) or 0)),
        tostring(math.floor(tonumber(snapshot.highScore) or 0)),
        tostring(math.floor(tonumber(snapshot.totalKills) or 0)),
        tostring(math.floor(tonumber(snapshot.playCount) or 0)),
        tostring(math.floor(tonumber(snapshot.bestFloor) or 0)),
        tostring(math.floor(tonumber(snapshot.rebirthCount) or 0)),
        tostring(math.floor(tonumber(snapshot.rebirthUpgradeCount) or 0)),
        tostring(math.floor(tonumber(snapshot.rebirthStone) or 0)),
        tostring(math.floor(tonumber(snapshot.skipLevelUpgradeLevel) or 0)),
        tostring(math.floor(tonumber(snapshot.skillDamageUpgradeLevel) or 0)),
        tostring(math.floor(tonumber(snapshot.cloneCritUpgradeLevel) or 0)),
        tostring(type(snapshot.inventory) == "table" and #snapshot.inventory or 0),
        tostring(type(snapshot.skills) == "table" and #snapshot.skills or 0),
        tostring(type(snapshot.equipmentSets) == "table" and #snapshot.equipmentSets or 0),
        tostring(type(snapshot.redeemedCodes) == "table" and #snapshot.redeemedCodes or 0),
    }
    local raw = table.concat(parts, "|") .. "|" .. LOCAL_SAVE_CLOUD_SALT
    local h = 0xdeadbeef
    for i = 1, #raw do
        h = ((h ~ string.byte(raw, i)) * 2246822519 + i * 13) % 2147483647
    end
    return string.format("%08x", h)
end

function ValidateCloudBlobHash(snapshot)
    if type(snapshot) ~= "table" then return false end
    local stored = snapshot._blob_hash
    if stored == nil then return true end -- 旧版本无哈希字段，放行
    if stored == ComputeCloudBlobHash(snapshot) then return true end
    if stored == ComputeCloudBlobHash(snapshot, true, false) then
        print("[Cloud] 检测到秘境压力字段上线前的 blob 哈希，已兼容接受")
        return true
    end
    if stored == ComputeCloudBlobHash(snapshot, false) then
        print("[Cloud] 检测到职业字段上线前的 blob 哈希，已兼容接受")
        return true
    end
    if stored == ComputeCloudBlobHash(snapshot, false, false) then
        print("[Cloud] 检测到职业与秘境压力字段上线前的 blob 哈希，已兼容接受")
        return true
    end
    if stored == ComputeLegacyCloudBlobHash(snapshot) then
        print("[Cloud] 检测到 BUG 版本遗留 blob 哈希，已兼容接受（下次保存将迁移为现行标准）")
        return true
    end
    return false
end

function SanitizeSnapshot(snapshot, source)
    if type(snapshot) ~= "table" then return false end
    local warnings = {}
    local function clampNum(field, minVal, maxVal)
        local val = tonumber(snapshot[field])
        if val == nil then return end
        local fixed = math.floor(val)
        if fixed ~= val then
            table.insert(warnings, field .. " 非整数 " .. tostring(val))
        end
        if fixed < minVal then
            table.insert(warnings, field .. " 过低 " .. tostring(fixed) .. " -> " .. tostring(minVal))
            fixed = minVal
        elseif maxVal ~= nil and fixed > maxVal then
            table.insert(warnings, field .. " 过高 " .. tostring(fixed) .. " -> " .. tostring(maxVal))
            fixed = maxVal
        end
        snapshot[field] = fixed
    end
    local function checkArraySize(field, maxSize)
        local arr = snapshot[field]
        if type(arr) == "table" and maxSize ~= nil and #arr > maxSize then
            table.insert(warnings, field .. " 数组过大 " .. tostring(#arr) .. " (上限" .. tostring(maxSize) .. ")")
        end
    end
    clampNum("gold", 0, LOCAL_SAVE_SANITY_MAX.gold)
    clampNum("totalGoldEarned", 0, LOCAL_SAVE_SANITY_MAX.totalGoldEarned)
    clampNum("highScore", 0, LOCAL_SAVE_SANITY_MAX.highScore)
    clampNum("totalKills", 0, LOCAL_SAVE_SANITY_MAX.totalKills)
    clampNum("playCount", 0, LOCAL_SAVE_SANITY_MAX.playCount)
    clampNum("totalPlayTime", 0, LOCAL_SAVE_SANITY_MAX.totalPlayTime)
    clampNum("bestFloor", 0, LOCAL_SAVE_SANITY_MAX.bestFloor)
    clampNum("currentFloor", 1, LOCAL_SAVE_SANITY_MAX.currentFloor)
    if snapshot.offlineClimbState ~= nil then
        local offlineState = NormalizeOfflineClimbState(
            snapshot.offlineClimbState
        )
        offlineState.startedAt = math.max(
            0,
            math.min(
                LOCAL_SAVE_SANITY_MAX.offlineClimbStartedAt,
                offlineState.startedAt
            )
        )
        offlineState.startFloor = math.min(
            LOCAL_SAVE_SANITY_MAX.offlineClimbStartFloor,
            offlineState.startFloor
        )
        offlineState.simulatedFloor = math.min(
            LOCAL_SAVE_SANITY_MAX.offlineClimbSimulatedFloor,
            offlineState.simulatedFloor
        )
        offlineState.targetFloor = math.min(
            LOCAL_SAVE_SANITY_MAX.offlineClimbTargetFloor,
            offlineState.targetFloor
        )
        offlineState.settlementVersion = math.min(
            LOCAL_SAVE_SANITY_MAX.offlineClimbSettlementVersion,
            offlineState.settlementVersion
        )
        if offlineState.pendingReward ~= nil then
            offlineState.pendingReward = math.min(
                LOCAL_SAVE_SANITY_MAX.offlineClimbReward,
                offlineState.pendingReward
            )
        end
        snapshot.offlineClimbState = offlineState
    end
    clampNum("equipmentRiftPressure", EQUIPMENT_RIFT_PRESSURE_MIN, LOCAL_SAVE_SANITY_MAX.equipmentRiftPressure)
    if snapshot.equipmentRiftPressureDayKey ~= nil then
        snapshot.equipmentRiftPressureDayKey = tostring(snapshot.equipmentRiftPressureDayKey)
    end
    clampNum("rebirthCount", 0, LOCAL_SAVE_SANITY_MAX.rebirthCount)
    clampNum("rebirthUpgradeCount", 0, LOCAL_SAVE_SANITY_MAX.rebirthUpgradeCount)
    clampNum("rebirthUpgradeResetId", 0, LOCAL_SAVE_SANITY_MAX.rebirthUpgradeResetId)
    clampNum("skipLevelUpgradeLevel", 0, LOCAL_SAVE_SANITY_MAX.skipLevelUpgradeLevel)
    if snapshot.skipLevelEnabled ~= nil then
        snapshot.skipLevelEnabled = snapshot.skipLevelEnabled == true
    end
    clampNum("skillDamageUpgradeLevel", 0, LOCAL_SAVE_SANITY_MAX.skillDamageUpgradeLevel)
    clampNum("cloneCritUpgradeLevel", 0, LOCAL_SAVE_SANITY_MAX.cloneCritUpgradeLevel)
    clampNum("rebirthStone", 0, LOCAL_SAVE_SANITY_MAX.rebirthStone)
    clampNum("rebirthStoneBestClaimFloor", 0, LOCAL_SAVE_SANITY_MAX.rebirthStoneBestClaimFloor)
    clampNum("dailyRebirthStoneEarned", 0, LOCAL_SAVE_SANITY_MAX.dailyRebirthStoneEarned)
    clampNum("rebirthRunStartFloor", 1, LOCAL_SAVE_SANITY_MAX.rebirthRunStartFloor)
    clampNum("rebirthRunCompletedFloors", 0, LOCAL_SAVE_SANITY_MAX.rebirthRunCompletedFloors)
    clampNum("rebirthRunSkippedFloors", 0, LOCAL_SAVE_SANITY_MAX.rebirthRunSkippedFloors)
    clampNum("cloneCount", 0, LOCAL_SAVE_SANITY_MAX.cloneCount)
    clampNum("cloneUpgradeLevel", 0, LOCAL_SAVE_SANITY_MAX.cloneUpgradeLevel)
    clampNum("unlockedSkillSlots", 1, LOCAL_SAVE_SANITY_MAX.unlockedSkillSlots)
    clampNum("nextSkillUid", 1, LOCAL_SAVE_SANITY_MAX.nextSkillUid)
    local gold = tonumber(snapshot.gold) or 0
    local totalEarned = tonumber(snapshot.totalGoldEarned) or 0
    if totalEarned < gold then
        snapshot.totalGoldEarned = gold
        table.insert(warnings, "totalGoldEarned < gold，已修正")
    end
    if SanitizeAdventureSnapshot ~= nil then SanitizeAdventureSnapshot(snapshot) end
    if snapshot.cloneProtocols ~= nil then
        if type(snapshot.cloneProtocols) ~= "table" then
            table.insert(warnings, "cloneProtocols 格式无效，已回退均衡协议")
        end
        snapshot.cloneProtocols = NormalizeCloneProtocolsData(snapshot.cloneProtocols)
    end
    snapshot.skillSynergy = NormalizeSkillSynergyData(snapshot.skillSynergy)
    checkArraySize("dailySpeedAdminGrants", LOCAL_SAVE_SANITY_MAX.dailySpeedAdminGrants)
    checkArraySize("adminMaterialGrantClaims", LOCAL_SAVE_SANITY_MAX.adminMaterialGrantClaims)
    checkArraySize("inventory", LOCAL_SAVE_SANITY_MAX.inventory)
    checkArraySize("skills", LOCAL_SAVE_SANITY_MAX.skills)
    checkArraySize("redeemedCodes", LOCAL_SAVE_SANITY_MAX.redeemedCodes)
    checkArraySize("equipmentSets", LOCAL_SAVE_SANITY_MAX.equipmentSets)
    if #warnings > 0 then
        print("[SaveSanity] " .. (source or "snapshot") .. " 范围校验告警:")
        for _, w in ipairs(warnings) do
            print("  - " .. w)
        end
    end
    return true
end

function EncodeLocalSaveSnapshot(encodedSnapshot)
    local envelope = {
        magic = LOCAL_SAVE_MAGIC,
        version = LOCAL_SAVE_VERSION,
        payload = LocalSaveToHex(encodedSnapshot),
        hash = StrongSaveHash(encodedSnapshot),
    }
    return cjson.encode(envelope)
end

function DecodeLocalSaveContent(content)
    local ok, decoded = pcall(cjson.decode, content)
    if not ok or decoded == nil then
        return nil, "json"
    end

    if decoded.magic ~= LOCAL_SAVE_MAGIC and decoded.magic ~= LOCAL_SAVE_MAGIC_V2 then
        return nil, "bad_magic"
    end

    local payload = nil
    local hashOk = false

    if decoded.magic == LOCAL_SAVE_MAGIC_V2 then
        payload = LocalSaveFromHexV2(decoded.payload)
        if payload ~= nil and LocalSaveHashV2(payload) == decoded.hash then
            hashOk = true
        end
    else
        payload = LocalSaveFromHex(decoded.payload)
        if payload ~= nil and StrongSaveHash(payload) == decoded.hash then
            hashOk = true
        end
    end

    if not hashOk or payload == nil then
        return nil, "tampered"
    end

    local payloadOk, snapshot = pcall(cjson.decode, payload)
    if not payloadOk or snapshot == nil then
        return nil, "payload"
    end

    if decoded.magic == LOCAL_SAVE_MAGIC then
        local expectedChecksum = ComputeInlineChecksum(snapshot)
        local legacyChecksum = ComputeInlineChecksum(snapshot, false)
        if snapshot._chk ~= nil
            and snapshot._chk ~= expectedChecksum
            and snapshot._chk ~= legacyChecksum then
            return nil, "inline_tampered"
        end
    end

    return snapshot, nil
end

function LoadLegacyDisplaySettings()
    if not fileSystem:FileExists(LEGACY_LOCAL_SAVE_PATH) then return {} end
    local file = File(LEGACY_LOCAL_SAVE_PATH, FILE_READ)
    if file == nil or not file:IsOpen() then return {} end
    local content = file:ReadString()
    file:Close()
    local snapshot = DecodeLocalSaveContent(content)
    if type(snapshot) ~= "table" then return {} end
    return CopyLegacyDisplaySettings(snapshot.settings)
end

function HasCurrentSaveGeneration(snapshot)
    return type(snapshot) == "table"
        and snapshot.officialSaveId == OFFICIAL_SAVE_ID
end

function MergeRedeemedCodes(codes)
    if type(codes) ~= "table" then return end
    redeemedCodes = redeemedCodes or {}
    local existing = {}
    for _, code in ipairs(redeemedCodes) do
        existing[tostring(code)] = true
    end
    for _, code in ipairs(codes) do
        local text = tostring(code)
        if not existing[text] then
            table.insert(redeemedCodes, code)
            existing[text] = true
        end
    end
end

function MergeRedeemedCodesFromSnapshot(snapshot)
    if type(snapshot) ~= "table" then return end
    MergeRedeemedCodes(snapshot.redeemedCodes)
end

function ApplyRedeemedCodeRewards()
    if type(redeemedCodes) ~= "table" or #redeemedCodes == 0 then return end
    if playerData == nil then playerData = {} end
    if playerData.settings == nil then playerData.settings = {} end
    local needNormalizeSkills = false
    local baseSlotCount = (CONFIG and CONFIG.SkillSlotBaseCount) or 10
    local currentSlots = tonumber(playerData.unlockedSkillSlots) or baseSlotCount
    for _, code in ipairs(redeemedCodes) do
        local entry = REDEEM_CODES and REDEEM_CODES[tostring(code)]
        if entry ~= nil then
            local reward = entry.reward or {}
            if reward.tripleSpeedUnlocked then
                playerData.settings.tripleSpeedUnlocked = true
            end
            if reward.fiveSpeedUnlocked then
                playerData.settings.fiveSpeedUnlocked = true
                playerData.settings.tripleSpeedUnlocked = true
            end
            if reward.tenSpeedUnlocked then
                playerData.settings.tenSpeedUnlocked = true
            end
            if reward.fakeTenSpeedUnlocked then
                playerData.settings.fakeTenSpeedUnlocked = true
            end
            if reward.tenBattleUnlocked then
                playerData.settings.tenBattleUnlocked = true
            end
            if reward.twentyBattleUnlocked then
                playerData.settings.twentyBattleUnlocked = true
            end
            if reward.unlockSkillSlots then
                local target = tonumber(reward.unlockSkillSlots) or 0
                if target > currentSlots then
                    currentSlots = target
                    needNormalizeSkills = true
                end
            end
        end
    end
    if needNormalizeSkills then
        playerData.unlockedSkillSlots = currentSlots
        if type(NormalizeSkills) == "function" then
            NormalizeSkills()
        end
    end
end

