function CorrectLegacyPlayTime(totalPlayTime, clockVersion, settings)
    local total = math.max(0, math.floor(totalPlayTime or 0))
    if (clockVersion or 0) >= PLAY_TIME_CLOCK_VERSION_REAL then
        return total, PLAY_TIME_CLOCK_VERSION_REAL, false
    end
    local divisor = PLAY_TIME_LEGACY_CORRECTION_DIVISOR
    if type(settings) == "table" then
        local lastSpeed = tonumber(settings.lastGameSpeed) or divisor
        if lastSpeed > divisor then
            divisor = lastSpeed
        end
    end
    divisor = math.max(1, divisor)
    local corrected = math.floor(total / divisor)
    if total > 0 and corrected < 1 then
        corrected = 1
    end
    return corrected, PLAY_TIME_CLOCK_VERSION_REAL, corrected ~= total
end

function SetPlayTimeFromLoadedValue(totalPlayTime, clockVersion, settings)
    local corrected, version, changed = CorrectLegacyPlayTime(totalPlayTime, clockVersion, settings)
    playerData.totalPlayTime = math.max(playerData.totalPlayTime or 0, corrected)
    playerData.playTimeClockVersion = math.max(playerData.playTimeClockVersion or 0, version)
    if changed then
        saveDirty = true
        playTimeMigrationDirty = true
        print("[PlayTime] 已校正历史游戏时长:", math.floor(totalPlayTime or 0), "->", corrected)
    end
end

function GetCurrentCstDayKey()
    local cstTimestamp = os.time() + 8 * 60 * 60
    return os.date("!*t", cstTimestamp).year .. "-"
        .. string.format("%02d", os.date("!*t", cstTimestamp).month) .. "-"
        .. string.format("%02d", os.date("!*t", cstTimestamp).day)
end

