-- 每日活跃打点：玩家进入游戏时上报一次（幂等 SetInt=1，按日去重）。
-- 由进入游戏流程与 SaveCloudData 共同保证：即便玩家未触发云存档也能尽早入榜。
function ReportDailyActiveOnEnter()
    if clientCloud == nil or clientCloud.userId == nil then return end
    local dayKey = GetCurrentCstDayKey()
    local scoreKey = GetDailyActiveLeaderboardScoreKey(dayKey)
    if scoreKey == nil then return end
    clientCloud:SetInt(scoreKey, 1, {
        ok = function()
            print("[DailyStats] 进入游戏上报活跃:", dayKey)
        end,
        error = function(code, reason)
            print("[DailyStats] 活跃上报失败:", dayKey, tostring(reason or code))
        end,
        timeout = function()
            print("[DailyStats] 活跃上报超时:", dayKey)
        end,
    })
end

DAILY_SPEED_QUOTA_SECONDS = 6 * 60 * 60
DAILY_SPEED_AD_BONUS_SECONDS = 2 * 60 * 60
DAILY_SPEED_AD_MAX_CLAIMS = 5
DAILY_SPEED_ADMIN_BONUS_MAX_SECONDS = 8 * 60 * 60
DAILY_SPEED_QUOTA_VERSION = 1
DAILY_SPEED_CLOCK_GUARD_VERSION = 1
DAILY_SPEED_CLOCK_JUMP_TOLERANCE = 10 * 60
DAILY_SPEED_CLOCK_STABLE_RECOVERY_SECONDS = 10 * 60
DAILY_REWARD_AD_MAX_CLAIMS = 20
DAILY_SOCKET_PUNCHER_AD_MAX_CLAIMS = 1
WHITE_REFINE_AD_REWARD = 50
PINK_REFINE_AD_REWARD = 5
GEM_AD_REWARD_COUNT = 10
-- 每日转生石常规获取基准上限；实际上限随历史最高已通关层数提升（见 GetDailyRebirthStoneLimit）
---@type integer
DAILY_REBIRTH_STONE_LIMIT = 10000
DAILY_REBIRTH_STONE_QUOTA_VERSION = 1

---@return integer
function GetDailyRebirthStoneLimit()
    local highestCleared = GetHighestClearedFloor()
    -- 普通模式历史最高已通关 500 层 → 每日上限 30000；通关 300 层 → 20000；未达到 → 基准 10000
    if highestCleared >= 500 then
        return 30000
    elseif highestCleared >= 300 then
        return 20000
    end
    return DAILY_REBIRTH_STONE_LIMIT
end
dailySpeedSessionUsageSeconds = 0
dailySpeedSessionLastUnixTime = dailySpeedSessionLastUnixTime or 0
dailySpeedClockStableSeconds = dailySpeedClockStableSeconds or 0

dailySpeedClockState = dailySpeedClockState or {
    lastObservedUnixTime = 0,
    trustedDayKey = "",
    blockedDayKey = "",
}

function ResetDailySpeedClockRuntime()
    dailySpeedSessionLastUnixTime = 0
    dailySpeedClockStableSeconds = 0
end

function GetDailySpeedClockNow()
    return math.floor(os.time())
end

function UpdateDailySpeedClockState(frameTimeStep)
    local now = GetDailySpeedClockNow()
    local state = dailySpeedClockState or {}
    local lastObserved = math.floor(tonumber(state.lastObservedUnixTime) or 0)
    local trustedDayKey = tostring(state.trustedDayKey or "")
    local blockedDayKey = tostring(state.blockedDayKey or "")
    local today = GetCurrentCstDayKey()
    local returnedToTrustedDay = blockedDayKey ~= ""
        and trustedDayKey ~= ""
        and today == trustedDayKey
    local backwardJump = not returnedToTrustedDay
        and lastObserved > 0
        and now < lastObserved
    local foregroundJump = false
    if dailySpeedSessionLastUnixTime > 0 and frameTimeStep ~= nil then
        local wallDelta = now - dailySpeedSessionLastUnixTime
        local expectedDelta = math.max(0, tonumber(frameTimeStep) or 0)
        -- 仅当"墙钟流逝显著小于帧间隔"（系统时间被往前调）才判定为前跳，
        -- 避免把切后台/挂机回前台（wallDelta 远大于 dt）误判为时间异常，
        -- 导致当天广告/额度被锁定不重置。
        foregroundJump = (wallDelta - expectedDelta) < -DAILY_SPEED_CLOCK_JUMP_TOLERANCE
    end

    if returnedToTrustedDay then
        blockedDayKey = ""
        lastObserved = now
        dailySpeedClockStableSeconds = 0
        print("[SpeedQuota] 系统时间恢复正常，解除额度日期保护")
    elseif backwardJump or foregroundJump then
        dailySpeedClockStableSeconds = 0
        if blockedDayKey ~= today then
            print("[SpeedQuota] 检测到系统时间异常，暂停自动重置额度，日期:", today)
        end
        blockedDayKey = today
    elseif blockedDayKey == today and frameTimeStep ~= nil then
        dailySpeedClockStableSeconds = (dailySpeedClockStableSeconds or 0)
            + math.max(0, tonumber(frameTimeStep) or 0)
        if dailySpeedClockStableSeconds >= DAILY_SPEED_CLOCK_STABLE_RECOVERY_SECONDS then
            playerData.dailySpeedUsageDayKey = today
            playerData.dailyRebirthStoneDayKey = today
            playerData.equipmentRiftPressureDayKey = today
            playerData.dailyRewardAdClaimDayKey = today
            playerData.dailySocketPuncherAdClaimDayKey = today
            trustedDayKey = today
            blockedDayKey = ""
            dailySpeedClockStableSeconds = 0
            saveDirty = true
            print("[DailyQuota] 系统时间已持续稳定，保留已用额度并解除日期保护")
        end
    end

    if trustedDayKey == "" then
        trustedDayKey = today
    end
    dailySpeedSessionLastUnixTime = now
    dailySpeedClockState = {
        lastObservedUnixTime = math.max(lastObserved, now),
        trustedDayKey = trustedDayKey,
        blockedDayKey = blockedDayKey,
    }
    return today, blockedDayKey == today
end

function ObserveDailySpeedClock(frameTimeStep)
    UpdateDailySpeedClockState(frameTimeStep)
end

function NormalizeDailySpeedQuota()
    local today, clockBlocked = UpdateDailySpeedClockState()
    local dayKey = tostring(playerData.dailySpeedUsageDayKey or "")
    if not clockBlocked and dayKey ~= today then
        playerData.dailySpeedUsageDayKey = today
        playerData.dailySpeedUsageSeconds = 0
        playerData.dailySpeedAdClaimDayKey = today
        playerData.dailySpeedAdClaimCount = 0
        playerData.dailySpeedQuotaVersion = DAILY_SPEED_QUOTA_VERSION
        dailySpeedSessionUsageSeconds = 0
        dailySpeedClockState.trustedDayKey = today
        saveDirty = true
    elseif dayKey == today then
        playerData.dailySpeedQuotaVersion = DAILY_SPEED_QUOTA_VERSION
        dailySpeedClockState.trustedDayKey = today
    elseif clockBlocked then
        print("[SpeedQuota] 时间异常期间保留当前额度，日期:", dayKey, "当前系统日期:", today)
    end
    local adDayKey = tostring(playerData.dailySpeedAdClaimDayKey or "")
    if not clockBlocked and adDayKey ~= today then
        playerData.dailySpeedAdClaimDayKey = today
        playerData.dailySpeedAdClaimCount = 0
        saveDirty = true
    end
    playerData.dailySpeedAdClaimCount = math.max(0, math.min(
        DAILY_SPEED_AD_MAX_CLAIMS,
        math.floor(tonumber(playerData.dailySpeedAdClaimCount) or 0)))
    playerData.dailySpeedUsageSeconds = math.max(0, math.min(
        DAILY_SPEED_QUOTA_SECONDS
            + DAILY_SPEED_AD_BONUS_SECONDS * DAILY_SPEED_AD_MAX_CLAIMS
            + DAILY_SPEED_ADMIN_BONUS_MAX_SECONDS,
        math.floor(tonumber(playerData.dailySpeedUsageSeconds) or 0)))
    NormalizeDailyRewardAdQuota()
end

function NormalizeDailyRewardAdQuota()
    local today, clockBlocked = UpdateDailySpeedClockState()
    local dayKey = tostring(playerData.dailyRewardAdClaimDayKey or "")
    if not clockBlocked and dayKey ~= today then
        playerData.dailyRewardAdClaimDayKey = today
        playerData.dailyRewardAdClaimCount = 0
        saveDirty = true
        print("[RewardAdQuota] 北京时间新的一天，广告次数已重置:", today)
    elseif dayKey == today then
        dailySpeedClockState.trustedDayKey = today
    elseif clockBlocked then
        print("[RewardAdQuota] 时间异常期间保留当前广告次数，日期:", dayKey, "当前系统日期:", today)
    end
    playerData.dailyRewardAdClaimCount = math.max(0, math.min(
        DAILY_REWARD_AD_MAX_CLAIMS,
        math.floor(tonumber(playerData.dailyRewardAdClaimCount) or 0)))
end

function NormalizeDailyRebirthStoneQuota()
    local today, clockBlocked = UpdateDailySpeedClockState()
    local dayKey = tostring(playerData.dailyRebirthStoneDayKey or "")
    if not clockBlocked and dayKey ~= today then
        playerData.dailyRebirthStoneDayKey = today
        playerData.dailyRebirthStoneEarned = 0
        playerData.dailyRebirthStoneQuotaVersion = DAILY_REBIRTH_STONE_QUOTA_VERSION
        dailySpeedClockState.trustedDayKey = today
        saveDirty = true
        print("[RebirthStoneQuota] 北京时间新的一天，常规获取额度已重置:", today)
    elseif dayKey == today then
        playerData.dailyRebirthStoneQuotaVersion = DAILY_REBIRTH_STONE_QUOTA_VERSION
        dailySpeedClockState.trustedDayKey = today
    elseif clockBlocked then
        print("[RebirthStoneQuota] 时间异常期间保留当前额度，日期:", dayKey, "当前系统日期:", today)
    end
    playerData.dailyRebirthStoneEarned = math.max(0, math.min(
        GetDailyRebirthStoneLimit(),
        math.floor(tonumber(playerData.dailyRebirthStoneEarned) or 0)))
end

function NormalizeEquipmentRiftPressure()
    local today, clockBlocked = UpdateDailySpeedClockState()
    local dayKey = tostring(playerData.equipmentRiftPressureDayKey or "")
    if not clockBlocked and dayKey ~= today then
        playerData.equipmentRiftPressureDayKey = today
        playerData.equipmentRiftPressure = 0
        dailySpeedClockState.trustedDayKey = today
        saveDirty = true
        print("[EquipmentRiftPressure] 北京时间新的一天，压力已重置:", today)
    elseif dayKey == today then
        dailySpeedClockState.trustedDayKey = today
    elseif clockBlocked then
        print("[EquipmentRiftPressure] 时间异常期间保留当前压力，日期:",
            dayKey, "当前系统日期:", today)
    end
    playerData.equipmentRiftPressure = math.max(EQUIPMENT_RIFT_PRESSURE_MIN, math.min(
        LOCAL_SAVE_SANITY_MAX.equipmentRiftPressure,
        math.floor(tonumber(playerData.equipmentRiftPressure) or 0)))
    return playerData.equipmentRiftPressure
end

function GetEquipmentRiftPressure()
    return NormalizeEquipmentRiftPressure()
end

function AdjustEquipmentRiftPressure(delta, source)
    NormalizeEquipmentRiftPressure()
    local before = math.max(
        EQUIPMENT_RIFT_PRESSURE_MIN,
        math.floor(tonumber(playerData.equipmentRiftPressure) or 0)
    )
    local after = math.max(EQUIPMENT_RIFT_PRESSURE_MIN, math.min(
        LOCAL_SAVE_SANITY_MAX.equipmentRiftPressure,
        before + math.floor(tonumber(delta) or 0)))
    playerData.equipmentRiftPressure = after
    print("[EquipmentRiftPressure]", source or "调整", "before=", before,
        "delta=", math.floor(tonumber(delta) or 0), "after=", after)
    if after ~= before then
        saveDirty = true
    end
    return after, before
end

function ApplyEquipmentRiftPressureValues(pressure, dayKey, source)
    if pressure == nil and (dayKey == nil or tostring(dayKey) == "") then
        NormalizeEquipmentRiftPressure()
        return
    end
    playerData.equipmentRiftPressure = math.max(EQUIPMENT_RIFT_PRESSURE_MIN, math.min(
        LOCAL_SAVE_SANITY_MAX.equipmentRiftPressure,
        math.floor(tonumber(pressure) or 0)))
    playerData.equipmentRiftPressureDayKey = tostring(dayKey or "")
    NormalizeEquipmentRiftPressure()
    print("[EquipmentRiftPressure] 应用", source or "数据", "日期:",
        playerData.equipmentRiftPressureDayKey, "压力:",
        playerData.equipmentRiftPressure)
end

function GetDailyRebirthStoneEarned()
    NormalizeDailyRebirthStoneQuota()
    return math.max(0, math.min(
        GetDailyRebirthStoneLimit(),
        math.floor(tonumber(playerData.dailyRebirthStoneEarned) or 0)))
end

function GetDailyRebirthStoneRemaining()
    return math.max(0, GetDailyRebirthStoneLimit() - GetDailyRebirthStoneEarned())
end

function AwardDailyRebirthStone(amount, source)
    amount = math.max(0, math.floor(tonumber(amount) or 0))
    if amount <= 0 then return 0 end
    NormalizeDailyRebirthStoneQuota()
    local granted = math.min(amount, GetDailyRebirthStoneRemaining())
    if granted > 0 then
        playerData.rebirthStone = math.max(0, math.floor(playerData.rebirthStone or 0)) + granted
        playerData.dailyRebirthStoneEarned = GetDailyRebirthStoneEarned() + granted
        saveDirty = true
    end
    if granted < amount then
        print("[RebirthStoneQuota]", source or "常规来源", "受每日上限裁剪，申请:", amount,
            "实际:", granted, "未发放:", amount - granted, "今日:",
            playerData.dailyRebirthStoneEarned, "/", GetDailyRebirthStoneLimit())
    end
    return granted
end

function ApplyDailyRebirthStoneQuotaValues(earned, dayKey, source)
    local incomingDay = tostring(dayKey or "")
    local incoming = math.max(0, math.min(
        GetDailyRebirthStoneLimit(),
        math.floor(tonumber(earned) or 0)))
    local _, clockBlocked = UpdateDailySpeedClockState()
    if clockBlocked and incomingDay ~= "" then
        local activeDay = tostring(playerData.dailyRebirthStoneDayKey or "")
        if activeDay == "" or incomingDay == activeDay then
            playerData.dailyRebirthStoneDayKey = incomingDay
            playerData.dailyRebirthStoneEarned = math.max(
                playerData.dailyRebirthStoneEarned or 0,
                incoming)
        end
        playerData.dailyRebirthStoneQuotaVersion = DAILY_REBIRTH_STONE_QUOTA_VERSION
    else
        NormalizeDailyRebirthStoneQuota()
        local activeDay = tostring(playerData.dailyRebirthStoneDayKey or "")
        if incomingDay ~= "" and incomingDay == activeDay then
            playerData.dailyRebirthStoneEarned = math.max(
                playerData.dailyRebirthStoneEarned or 0,
                incoming)
        end
    end
    print("[RebirthStoneQuota] 应用", source or "数据", "日期:",
        playerData.dailyRebirthStoneDayKey, "已获:",
        playerData.dailyRebirthStoneEarned, "/", GetDailyRebirthStoneLimit())
end

function MergeDailyRebirthStoneQuotaFromCloud(values, iscores)
    values = values or {}
    iscores = iscores or {}
    NormalizeDailyRebirthStoneQuota()
    local activeDay = tostring(playerData.dailyRebirthStoneDayKey or "")
    local bestEarned = nil
    local function consider(earned, dayKey)
        if earned == nil or tostring(dayKey or "") ~= activeDay then return end
        local normalized = math.max(0, math.min(
            GetDailyRebirthStoneLimit(),
            math.floor(tonumber(earned) or 0)))
        bestEarned = math.max(bestEarned or 0, normalized)
    end
    consider(iscores.daily_rebirth_stone_earned, values.daily_rebirth_stone_day)
    consider(values.daily_rebirth_stone_earned, values.daily_rebirth_stone_day)
    local blob = values.save_blob
    if type(blob) == "table" then
        consider(blob.dailyRebirthStoneEarned, blob.dailyRebirthStoneDayKey)
    end
    if bestEarned ~= nil then
        ApplyDailyRebirthStoneQuotaValues(bestEarned, activeDay, "云端合并")
    end
end

function GrantSettingsGoldAdReward()
    playerData.gold = math.max(0, math.floor(tonumber(playerData.gold) or 0)) + 1000000
    playerData.totalGoldEarned = math.max(
        math.floor(tonumber(playerData.totalGoldEarned) or 0),
        playerData.gold
    )
    saveDirty = true
    return 1000000
end

function GrantSettingsRiftPressureAdReward()
    local before = GetEquipmentRiftPressure()
    local after = AdjustEquipmentRiftPressure(-2, "设置页广告")
    return before - after, after
end

function CanClaimRebirthStoneAdReward()
    -- 广告获得的转生石不计入每日1万常规获取上限，故不受额度限制，仅受广告次数限制
    return true
end

function GrantRebirthStoneAdReward()
    -- 广告转生石独立于每日1万常规上限直接发放，不累计 dailyRebirthStoneEarned
    local amount = 500
    playerData.rebirthStone = math.max(0, math.floor(playerData.rebirthStone or 0)) + amount
    playerData.rebirthStoneAdLastClaimDayKey = GetCurrentCstDayKey()
    saveDirty = true
    return true, amount
end

function NormalizeAdminMaterialGrantClaims()
    local claims = playerData.adminMaterialGrantClaims
    if type(claims) ~= "table" then
        claims = {}
        playerData.adminMaterialGrantClaims = claims
    end
    local count = 0
    for grantId, claimedAt in pairs(claims) do
        local key = tostring(grantId or "")
        if key == "" or type(claimedAt) ~= "number" then
            claims[grantId] = nil
        else
            count = count + 1
        end
    end
    if count > LOCAL_SAVE_SANITY_MAX.adminMaterialGrantClaims then
        local keys = {}
        for grantId, claimedAt in pairs(claims) do
            table.insert(keys, { id = grantId, at = claimedAt })
        end
        table.sort(keys, function(a, b) return a.at > b.at end)
        for index = LOCAL_SAVE_SANITY_MAX.adminMaterialGrantClaims + 1, #keys do
            claims[keys[index].id] = nil
        end
    end
end

function MergeAdminMaterialGrantClaims(incoming)
    if type(incoming) ~= "table" then return false end
    NormalizeAdminMaterialGrantClaims()
    local changed = false
    for grantId, claimedAt in pairs(incoming) do
        local key = tostring(grantId or "")
        local timestamp = math.floor(tonumber(claimedAt) or 0)
        if key ~= "" and timestamp > 0 and playerData.adminMaterialGrantClaims[key] == nil then
            playerData.adminMaterialGrantClaims[key] = timestamp
            changed = true
        end
    end
    NormalizeAdminMaterialGrantClaims()
    if changed then saveDirty = true end
    return changed
end

function NormalizeDailySpeedAdminGrants()
    local grants = playerData.dailySpeedAdminGrants
    if type(grants) ~= "table" then
        grants = {}
        playerData.dailySpeedAdminGrants = grants
    end
    local currentDay = tostring(playerData.dailySpeedUsageDayKey or GetCurrentCstDayKey())
    for grantId, grant in pairs(grants) do
        if type(grant) ~= "table" then
            grants[grantId] = nil
        else
            grant.seconds = math.min(
                DAILY_SPEED_ADMIN_BONUS_MAX_SECONDS,
                math.max(0, math.floor(tonumber(grant.seconds) or 0)))
            grant.dayKey = tostring(grant.dayKey or currentDay)
            grant.grantId = tostring(grant.grantId or grantId)
            if grant.dayKey ~= currentDay then
                grants[grantId] = nil
            elseif grant.grantId ~= tostring(grantId) then
                grants[grant.grantId] = grant
                grants[grantId] = nil
            end
        end
    end
end

-- 管理员发放到账提示累积：洗练石/转生石/倍速补偿到账后先记录，
-- 玩家打开排行榜时统一弹窗告知"领取成功 + 具体内容"。
ADMIN_GRANT_NOTICE_PENDING = ADMIN_GRANT_NOTICE_PENDING or nil

function RecordAdminGrantNotice(delta)
    if type(delta) ~= "table" then return end
    local notice = ADMIN_GRANT_NOTICE_PENDING
    if type(notice) ~= "table" then
        notice = {}
        ADMIN_GRANT_NOTICE_PENDING = notice
    end
    if (delta.whiteRefine or 0) > 0 then
        notice.whiteRefine = (notice.whiteRefine or 0) + delta.whiteRefine
    end
    if (delta.pinkRefine or 0) > 0 then
        notice.pinkRefine = (notice.pinkRefine or 0) + delta.pinkRefine
    end
    if (delta.rebirthStone or 0) > 0 then
        notice.rebirthStone = (notice.rebirthStone or 0) + delta.rebirthStone
    end
    if (delta.speedSeconds or 0) > 0 then
        notice.speedSeconds = (notice.speedSeconds or 0) + delta.speedSeconds
    end
end

function MergeDailySpeedAdminGrants(incoming)
    if type(incoming) ~= "table" then return false end
    NormalizeDailySpeedAdminGrants()
    local currentDayKey = tostring(playerData.dailySpeedUsageDayKey or GetCurrentCstDayKey())
    local speedSecondsBefore = GetDailySpeedAdminBonusForDay(currentDayKey)
    local changed = false
    for grantId, grant in pairs(incoming) do
        if type(grant) == "table" then
            local key = tostring(grant.grantId or grantId)
            if playerData.dailySpeedAdminGrants[key] == nil then
                local seconds = math.max(0, math.floor(tonumber(grant.seconds or grant.remainingSeconds) or 0))
                if seconds > 0 then
                    playerData.dailySpeedAdminGrants[key] = {
                        grantId = key,
                        seconds = math.min(DAILY_SPEED_ADMIN_BONUS_MAX_SECONDS, seconds),
                        dayKey = tostring(grant.dayKey or GetCurrentCstDayKey()),
                        createdAt = math.floor(tonumber(grant.createdAt) or 0),
                        issuedBy = tostring(grant.issuedBy or ""),
                    }
                    changed = true
                end
            end
        end
    end
    NormalizeDailySpeedAdminGrants()
    if changed then
        saveDirty = true
        local speedSecondsAfter = GetDailySpeedAdminBonusForDay(currentDayKey)
        local addedSeconds = math.max(0, speedSecondsAfter - speedSecondsBefore)
        if addedSeconds > 0 then
            RecordAdminGrantNotice({ speedSeconds = addedSeconds })
        end
    end
    return changed
end

function GetDailySpeedAdminBonusForDay(dayKey)
    NormalizeDailySpeedAdminGrants()
    local total = 0
    for _, grant in pairs(playerData.dailySpeedAdminGrants) do
        if tostring(grant.dayKey or "") == tostring(dayKey or "") then
            total = total + math.max(0, math.floor(tonumber(grant.seconds) or 0))
        end
    end
    return math.min(DAILY_SPEED_ADMIN_BONUS_MAX_SECONDS, total)
end

function GetDailySpeedAdminBonusForSave()
    return GetDailySpeedAdminBonusForDay(playerData.dailySpeedUsageDayKey)
end

function GetDailySpeedAdClaimCount()
    NormalizeDailySpeedQuota()
    return math.max(0, math.min(
        DAILY_SPEED_AD_MAX_CLAIMS,
        math.floor(tonumber(playerData.dailySpeedAdClaimCount) or 0)))
end

