        .. tostring(GetDailyRewardAdClaimCount())
        .. "/"
        .. tostring(DAILY_REWARD_AD_MAX_CLAIMS)
end

function CanClaimDailySpeedAdBonus()
    return IsDailySpeedQuotaExhausted()
        and GetDailySpeedAdClaimCount() < DAILY_SPEED_AD_MAX_CLAIMS
        and CanClaimDailyRewardAd()
