function GrantDailySpeedAdBonus()
    if not CanClaimDailySpeedAdBonus() then return false end
    if not ConsumeDailyRewardAdClaim() then return false end
    playerData.dailySpeedAdClaimDayKey = GetCurrentCstDayKey()
    playerData.dailySpeedAdClaimCount = GetDailySpeedAdClaimCount() + 1
    saveDirty = true
    print("[SpeedQuota] 广告额度领取成功，今日次数:",
        playerData.dailySpeedAdClaimCount, "/", DAILY_SPEED_AD_MAX_CLAIMS,
        FormatDailyRewardAdProgressText())
