    return GetDailySpeedAdClaimCount() * DAILY_SPEED_AD_BONUS_SECONDS
end

function GetDailySpeedQuotaLimit()
    return DAILY_SPEED_QUOTA_SECONDS
        + GetDailySpeedAdBonusForSave()
        + GetDailySpeedAdminBonusForSave()
end

function GetDailySpeedUsageForSave()
    NormalizeDailySpeedQuota()
    local total = math.floor(playerData.dailySpeedUsageSeconds or 0)
    if currentScreen == "playing" then
