    end
    return math.max(0, math.min(GetDailySpeedQuotaLimit(), total))
end

function GetDailySpeedQuotaRemaining()
    return math.max(0, GetDailySpeedQuotaLimit() - GetDailySpeedUsageForSave())
end

function ApplyDailySpeedClockState(snapshot)
    if type(snapshot) ~= "table" or type(snapshot.dailySpeedClockState) ~= "table" then
        return
    end
    local incomingState = snapshot.dailySpeedClockState
    local currentState = dailySpeedClockState or {}
    local incomingLast = math.floor(tonumber(incomingState.lastObservedUnixTime) or 0)
    local currentLast = math.floor(tonumber(currentState.lastObservedUnixTime) or 0)
    if incomingLast >= currentLast then
        dailySpeedClockState = {
            lastObservedUnixTime = incomingLast,
            trustedDayKey = tostring(incomingState.trustedDayKey or currentState.trustedDayKey or ""),
            blockedDayKey = tostring(incomingState.blockedDayKey or currentState.blockedDayKey or ""),
        }
    end
end

function ApplyDailySpeedQuotaValues(usageSeconds, dayKey, source)
    local incomingDay = tostring(dayKey or "")
    local incoming = math.max(0, math.min(
        DAILY_SPEED_QUOTA_SECONDS
            + DAILY_SPEED_AD_BONUS_SECONDS * DAILY_SPEED_AD_MAX_CLAIMS
            + DAILY_SPEED_ADMIN_BONUS_MAX_SECONDS,
        math.floor(tonumber(usageSeconds) or 0)))
    local _, clockBlocked = UpdateDailySpeedClockState()
    if clockBlocked and incomingDay ~= "" then
        playerData.dailySpeedUsageDayKey = incomingDay
        playerData.dailySpeedUsageSeconds = math.max(
            playerData.dailySpeedUsageSeconds or 0,
            incoming)
        playerData.dailySpeedQuotaVersion = DAILY_SPEED_QUOTA_VERSION
    else
        NormalizeDailySpeedQuota()
        local activeDay = tostring(playerData.dailySpeedUsageDayKey or "")
        if incomingDay ~= "" and incomingDay == activeDay then
            playerData.dailySpeedUsageSeconds = math.max(
                playerData.dailySpeedUsageSeconds or 0,
                incoming)
        end
    end
    print("[SpeedQuota] 应用", source or "数据", "日期:", playerData.dailySpeedUsageDayKey,
        "已用:", playerData.dailySpeedUsageSeconds, "/", DAILY_SPEED_QUOTA_SECONDS)
end

function IsDailySpeedQuotaExhausted()
    return GetDailySpeedQuotaRemaining() <= 0
end

