function CommitForegroundPlayTime()
    local pending = math.floor(foregroundPlayTimeSessionSeconds or 0)
    if pending <= 0 then return end
    playerData.totalPlayTime = math.floor((playerData.totalPlayTime or 0) + pending)
    foregroundPlayTimeSessionSeconds = (foregroundPlayTimeSessionSeconds or 0) - pending
    saveDirty = true
end

function GetTotalPlayTimeForSave()
    local total = playerData.totalPlayTime or 0
    total = total + (foregroundPlayTimeSessionSeconds or 0)
    return math.floor(total)
end

function IsOfflineClimbBlocked()
    return currentScreen == "playing"
        or autoContinueActive == true
        or equipmentRiftActive == true
        or pendingRoguelikeChoice ~= nil
        or pendingRoguelikeBattleStart == true
        or pendingFloorSettlement ~= nil
end

function GetOfflineClimbBlockReason()
    if currentScreen == "playing" then
        return "正在战斗"
    end
    if autoContinueActive == true then
        return "自动继续仍在运行"
    end
    if equipmentRiftActive == true then
        return "装备裂隙仍在运行"
    end
    if pendingRoguelikeChoice ~= nil then
        return "仍有肉鸽选项未确认"
    end
    if pendingRoguelikeBattleStart == true then
        return "仍有肉鸽战斗待开始"
    end
    if pendingFloorSettlement ~= nil then
        return "仍有楼层奖励未结算"
    end
    return nil
end

function GetOfflineClimbTargetFloor()
    local highestCleared = GetHighestClearedFloor()
    if highestCleared < 50 then
        return 0
    end
    return math.max(1, highestCleared - 50)
end

function MergeOfflineClimbStates(firstValue, secondValue)
    local first = NormalizeOfflineClimbState(firstValue)
    local second = NormalizeOfflineClimbState(secondValue)

    local function GetStateTimestamp(state)
        local updatedAt = math.max(
            0,
            math.floor(tonumber(state.updatedAt) or 0)
        )
        if updatedAt > 0 then
            return updatedAt
        end
        return math.max(
            0,
            math.floor(tonumber(state.startedAt) or 0)
        )
    end

    local firstTimestamp = GetStateTimestamp(first)
    local secondTimestamp = GetStateTimestamp(second)
    if first.runId ~= ""
        and first.runId == second.runId then
        if firstTimestamp ~= secondTimestamp then
            return firstTimestamp > secondTimestamp
                and first or second
        end
        if first.settlementVersion
            ~= second.settlementVersion then
            return first.settlementVersion
                    > second.settlementVersion
                and first or second
        end
        if first.simulatedFloor ~= second.simulatedFloor then
            return first.simulatedFloor
                    > second.simulatedFloor
                and first or second
        end
        if first.active ~= second.active then
            return first.active and first or second
        end
        return first
    end

    if firstTimestamp ~= secondTimestamp then
        return firstTimestamp > secondTimestamp
            and first or second
    end
    if first.active ~= second.active then
        return first.active and first or second
    end
    if first.settlementVersion
        ~= second.settlementVersion then
        return first.settlementVersion
                > second.settlementVersion
            and first or second
    end
    return first.simulatedFloor >= second.simulatedFloor
        and first or second
end

function StartOfflineClimbIfEligible(reason)
    local state = NormalizeOfflineClimbState(playerData.offlineClimbState)
    playerData.offlineClimbState = state
    if state.active then
        print("[OfflineClimb] 已有离线任务，跳过重复启动:", reason or "background")
        return false
    end

    local blockedReason = GetOfflineClimbBlockReason()
    if blockedReason ~= nil then
        state.failedReason = blockedReason
        print("[OfflineClimb] 未启动:", blockedReason)
        return false
    end

    local targetFloor = GetOfflineClimbTargetFloor()
    if targetFloor <= 0 then
        state.failedReason = "历史最高通关不足50层"
        print("[OfflineClimb] 未启动:", state.failedReason)
        return false
    end

    local startFloor = math.max(
        1,
        math.floor(playerData.currentFloor or 1)
    )
    if startFloor >= targetFloor then
        state.status = "completed"
        state.targetFloor = targetFloor
        state.startFloor = startFloor
        state.simulatedFloor = startFloor
        state.failedReason = "当前层已达到离线上限"
        print(
            "[OfflineClimb] 未启动:",
            state.failedReason,
            "当前层:", startFloor,
            "目标层:", targetFloor
        )
        return false
    end

    local now = math.max(0, math.floor(os.time()))
    state.version = OFFLINE_CLIMB_VERSION
    state.active = true
    state.runId = tostring(now)
        .. "-"
        .. tostring(math.random(100000, 999999))
    state.startedAt = now
    state.updatedAt = now
    state.startFloor = startFloor
    state.simulatedFloor = startFloor
    state.targetFloor = targetFloor
    state.status = "running"
    state.rewardClaimed = false
    state.failedReason = nil
    state.pendingReward = nil
    MarkSaveDirty()
    print(
        "[OfflineClimb] 任务开始:",
        reason or "background",
        "起始层:", startFloor,
        "目标层:", targetFloor,
        "累计秒:", state.carriedSeconds
    )
    return true
end

function SettleOfflineClimb(reason)
    local state = NormalizeOfflineClimbState(playerData.offlineClimbState)
    playerData.offlineClimbState = state
    if not state.active or state.runId == "" then
        return 0, 0, false
    end

    local now = math.max(0, math.floor(os.time()))
    local elapsed = math.max(0, now - state.startedAt)
    local totalSeconds = math.min(
        OFFLINE_CLIMB_MAX_SECONDS,
        elapsed + state.carriedSeconds
    )
    local availableFloors = math.floor(
        totalSeconds / OFFLINE_CLIMB_INTERVAL_SECONDS
    )
    local remainingFloors = math.max(
        0,
        state.targetFloor - state.simulatedFloor
    )
    local completedFloors = math.min(
        availableFloors,
        remainingFloors
    )
    local reward = 0
    local firstClearedFloor = nil
    local lastClearedFloor = nil
    if completedFloors > 0 then
        firstClearedFloor = state.simulatedFloor
        lastClearedFloor = state.simulatedFloor
            + completedFloors - 1
        for floor = firstClearedFloor, lastClearedFloor do
            reward = reward
                + floor
                * OFFLINE_CLIMB_GOLD_PER_FLOOR_MULTIPLIER
        end
        state.simulatedFloor = state.simulatedFloor
            + completedFloors
        playerData.currentFloor = math.max(
            math.floor(playerData.currentFloor or 1),
            state.simulatedFloor
        )
    end

    local consumedSeconds = completedFloors
        * OFFLINE_CLIMB_INTERVAL_SECONDS
    if state.simulatedFloor >= state.targetFloor then
        state.status = "completed"
        state.carriedSeconds = 0
    else
        state.status = "idle"
        state.carriedSeconds = math.max(
            0,
            math.min(
                OFFLINE_CLIMB_INTERVAL_SECONDS - 1,
                totalSeconds - consumedSeconds
            )
        )
    end
    state.active = false
    state.updatedAt = now
    state.settlementVersion = state.settlementVersion + 1
    state.pendingReward = reward
    state.rewardClaimed = reward <= 0
    if reward > 0 then
        AddGold(reward)
        state.rewardClaimed = true
    end
    state.failedReason = nil
    MarkSaveDirty()
    print(
        "[OfflineClimb] 任务结算:",
        reason or "resume",
        "离线秒:", elapsed,
        "推进:", completedFloors,
        "金币:", reward,
        "当前层:", playerData.currentFloor,
        "目标层:", state.targetFloor,
        "保留秒:", state.carriedSeconds
    )
    return completedFloors,
        reward,
        true,
        firstClearedFloor,
        lastClearedFloor
end

function BuildOfflineClimbNotice(completedFloors, reward)
    if (completedFloors or 0) <= 0 and (reward or 0) <= 0 then
        return ""
    end
    return "离线爬层完成：推进 "
        .. tostring(completedFloors or 0)
        .. " 层，获得 "
        .. tostring(reward or 0)
        .. " 金币"
end

function ResumeOfflineClimbAndPersist(reason)
    local completedFloors,
        reward,
        hadTask,
        firstClearedFloor,
        lastClearedFloor = SettleOfflineClimb(reason)
    if not hadTask then
        return 0, 0, false
    end

    local notice = BuildOfflineClimbNotice(
        completedFloors,
        reward
    )
    if notice ~= "" then
        offlineClimbNotice = notice
    end

    local startedRoguelikeSettlement = false
    if completedFloors > 0
        and firstClearedFloor ~= nil
        and lastClearedFloor ~= nil
        and BeginRoguelikeSettlementForFloorRange ~= nil then
        startedRoguelikeSettlement =
            BeginRoguelikeSettlementForFloorRange(
                firstClearedFloor,
                lastClearedFloor,
                "离线爬层"
            )
    end

    SaveLocalSnapshot()
    if cloudDataReadyForSave == true then
        SaveCloudData(true)
    end
    if currentScreen == "menu"
        and notice ~= ""
        and not startedRoguelikeSettlement then
        ShowMainMenu()
    end
    return completedFloors, reward, true
end

