    NormalizeAdventureData()
    playerData.offlineClimbState = NormalizeOfflineClimbState(
        playerData.offlineClimbState
    )
    local snapshot = {
        officialSaveId = OFFICIAL_SAVE_ID,
        version = LOCAL_SAVE_VERSION,
        saved_at = math.max(os.time(), localSaveTimestamp or 0),
        gold = playerData.gold or 0,
        totalGoldEarned = math.max(playerData.totalGoldEarned or 0, playerData.gold or 0),
        highScore = playerData.highScore or 0,
        totalKills = playerData.totalKills or 0,
        playCount = playerData.playCount or 0,
        totalPlayTime = GetTotalPlayTimeForSave(),
        playTimeClockVersion = PLAY_TIME_CLOCK_VERSION_REAL,
        dailySpeedUsageSeconds = GetDailySpeedUsageForSave(),
        dailySpeedUsageDayKey = playerData.dailySpeedUsageDayKey or GetCurrentCstDayKey(),
        dailySpeedQuotaVersion = DAILY_SPEED_QUOTA_VERSION,
        dailySpeedAdClaimDayKey = playerData.dailySpeedAdClaimDayKey or GetCurrentCstDayKey(),
        dailySpeedAdClaimCount = GetDailySpeedAdClaimCount(),
        dailyRewardAdClaimDayKey = playerData.dailyRewardAdClaimDayKey or GetCurrentCstDayKey(),
        dailyRewardAdClaimCount = GetDailyRewardAdClaimCount(),
        dailySocketPuncherAdClaimDayKey = playerData.dailySocketPuncherAdClaimDayKey or GetCurrentCstDayKey(),
        dailySocketPuncherAdClaimCount = GetDailySocketPuncherAdClaimCount(),
        dailyEquipmentUpgradeAdClaimDayKey = playerData.dailyEquipmentUpgradeAdClaimDayKey or GetCurrentCstDayKey(),
        dailyEquipmentUpgradeAdClaimCount = playerData.dailyEquipmentUpgradeAdClaimCount or 0,
        pendingEquipmentUpgradePenalty = playerData.pendingEquipmentUpgradePenalty,
        equipmentUpgradePenaltyResolvedId = playerData.equipmentUpgradePenaltyResolvedId or 0,
        nextEquipmentUid = playerData.nextEquipmentUid or 1,
        dailySpeedAdminGrants = playerData.dailySpeedAdminGrants or {},
        adminMaterialGrantClaims = playerData.adminMaterialGrantClaims or {},
        adminRebirthStoneGrantClaims = playerData.adminRebirthStoneGrantClaims or {},
        dailySpeedClockGuardVersion = DAILY_SPEED_CLOCK_GUARD_VERSION,
        dailySpeedClockState = {
            lastObservedUnixTime = dailySpeedClockState.lastObservedUnixTime or 0,
            trustedDayKey = dailySpeedClockState.trustedDayKey or "",
            blockedDayKey = dailySpeedClockState.blockedDayKey or "",
        },
        bestFloor = playerData.bestFloor or 0,
        currentFloor = playerData.currentFloor or math.max(1, playerData.bestFloor or 0),
        normalHighestClearedFloor = GetNormalHighestClearedFloor(),
        rebirthUnlocked = playerData.rebirthUnlocked == true,
        rebirthRunActive = playerData.rebirthRunActive == true,
        endlessBestFloor = playerData.endlessBestFloor or 0,
        endlessRunState = playerData.endlessRunState,
        offlineClimbState = playerData.offlineClimbState,
