ApplySaveSnapshot = function(snapshot, source)
    if snapshot == nil then return false end
    if not HasCurrentSaveGeneration(snapshot) then
        print("[OfficialSave] 忽略非正式档快照:", source or "snapshot")
        return false
    end
    SanitizeSnapshot(snapshot, source or "snapshot")
    REAL_PROGRESS_REVISION = math.max(
        math.floor(tonumber(REAL_PROGRESS_REVISION) or 0),
        math.floor(tonumber(snapshot.progressRevision) or 0))
    manualSaveRevision = math.max(
        math.floor(tonumber(manualSaveRevision) or 0),
        math.floor(tonumber(snapshot.manualSaveRevision) or 0))
    manualSaveAt = math.max(
        math.floor(tonumber(manualSaveAt) or 0),
        math.floor(tonumber(snapshot.manualSaveAt) or 0))
    playerData.gold = snapshot.gold or playerData.gold or 0
    playerData.totalGoldEarned = math.max(snapshot.totalGoldEarned or snapshot.total_gold_earned or 0, playerData.totalGoldEarned or 0, playerData.gold or 0)
    playerData.highScore = snapshot.highScore or playerData.highScore or 0
    playerData.totalKills = snapshot.totalKills or playerData.totalKills or 0
    playerData.playCount = snapshot.playCount or playerData.playCount or 0
    SetPlayTimeFromLoadedValue(snapshot.totalPlayTime or snapshot.playTime or 0, snapshot.playTimeClockVersion or snapshot.play_time_clock_version or 0, snapshot.settings)
    ApplyDailySpeedClockState(snapshot)
    MergeDailySpeedAdminGrants(snapshot.dailySpeedAdminGrants)
    MergeAdminMaterialGrantClaims(snapshot.adminMaterialGrantClaims)
    MergeAdminRebirthStoneGrantClaims(snapshot.adminRebirthStoneGrantClaims)
    ApplyDailySpeedAdClaimValues(
        snapshot.dailySpeedAdClaimCount,
        snapshot.dailySpeedAdClaimDayKey,
        source or "snapshot"
    )
    ApplyDailyRewardAdClaimValues(
        snapshot.dailyRewardAdClaimCount,
        snapshot.dailyRewardAdClaimDayKey,
        source or "snapshot"
    )
    ApplyDailySocketPuncherAdClaimValues(
        snapshot.dailySocketPuncherAdClaimCount,
        snapshot.dailySocketPuncherAdClaimDayKey,
        source or "snapshot"
    )
    MergeEquipmentUpgradeProtectionState(
        snapshot.dailyEquipmentUpgradeAdClaimDayKey,
        snapshot.dailyEquipmentUpgradeAdClaimCount,
        snapshot.pendingEquipmentUpgradePenalty,
        snapshot.equipmentUpgradePenaltyResolvedId,
        snapshot.nextEquipmentUid
    )
    ApplyDailySpeedQuotaValues(snapshot.dailySpeedUsageSeconds, snapshot.dailySpeedUsageDayKey, source or "snapshot")
    playerData.bestFloor = snapshot.bestFloor or playerData.bestFloor or 0
    playerData.currentFloor = snapshot.currentFloor or snapshot.bestFloor or playerData.currentFloor or playerData.bestFloor or 0
    playerData.normalHighestClearedFloor = math.max(
        playerData.normalHighestClearedFloor or 0,
        math.floor(tonumber(snapshot.normalHighestClearedFloor) or 0))
    playerData.rebirthUnlocked = playerData.rebirthUnlocked == true
        or snapshot.rebirthUnlocked == true
    if snapshot.rebirthRunActive ~= nil then
        playerData.rebirthRunActive = snapshot.rebirthRunActive == true
    end
    playerData.endlessBestFloor = math.max(
        playerData.endlessBestFloor or 0,
        math.floor(tonumber(snapshot.endlessBestFloor) or 0))
    if type(snapshot.endlessRunState) == "table" then
        local localRun = type(playerData.endlessRunState) == "table" and playerData.endlessRunState or {}
        local incomingRun = snapshot.endlessRunState
        if math.floor(tonumber(incomingRun.runId) or 0) >= math.floor(tonumber(localRun.runId) or 0) then
            playerData.endlessRunState = incomingRun
        end
    end
    NormalizeProgressionData()
    if snapshot.offlineClimbState ~= nil then
        playerData.offlineClimbState = MergeOfflineClimbStates(
            playerData.offlineClimbState,
            snapshot.offlineClimbState
        )
    end
    ApplyEquipmentRiftPressureValues(
        snapshot.equipmentRiftPressure,
        snapshot.equipmentRiftPressureDayKey,
        source or "snapshot"
    )
    playerData.nextBaseHpRatio = snapshot.nextBaseHpRatio
    playerData.selectedStartFloor = 0
    playerData.rebirthCount = snapshot.rebirthCount or playerData.rebirthCount or 0
    -- 永久强化重置世代：同一世代内强化等级只升不降（防止旧档覆盖新进度）；
    -- 快照世代更高说明对方完成过“看广告重置”，此时按快照覆盖，允许等级合法下降。
    local incomingUpgradeResetId = math.max(0, math.floor(tonumber(snapshot.rebirthUpgradeResetId) or 0))
    local currentUpgradeResetId = math.max(0, math.floor(tonumber(playerData.rebirthUpgradeResetId) or 0))
    local upgradeResetAdvanced = incomingUpgradeResetId > currentUpgradeResetId
    if upgradeResetAdvanced then
        playerData.rebirthUpgradeResetId = incomingUpgradeResetId
        playerData.rebirthUpgradeCount = math.max(0, math.floor(tonumber(snapshot.rebirthUpgradeCount) or 0))
        playerData.skipLevelUpgradeLevel = math.max(0, math.floor(tonumber(snapshot.skipLevelUpgradeLevel) or 0))
        playerData.skillDamageUpgradeLevel = math.max(0, math.floor(tonumber(snapshot.skillDamageUpgradeLevel) or 0))
        playerData.cloneCritUpgradeLevel = math.max(0, math.floor(tonumber(snapshot.cloneCritUpgradeLevel) or 0))
        print("[RebirthReset] 快照重置世代更新，按快照覆盖永久强化等级:",
            "世代", currentUpgradeResetId, "->", incomingUpgradeResetId,
            "攻血", playerData.rebirthUpgradeCount,
            "跳层", playerData.skipLevelUpgradeLevel,
            "技能", playerData.skillDamageUpgradeLevel,
            "分身", playerData.cloneCritUpgradeLevel)
    else
        playerData.rebirthUpgradeResetId = currentUpgradeResetId
        local incomingRebirthCount = tonumber(snapshot.rebirthUpgradeCount) or 0
        local currentRebirthCount = tonumber(playerData.rebirthUpgradeCount) or 0
        if incomingRebirthCount > 0 and incomingRebirthCount >= currentRebirthCount then
            playerData.rebirthUpgradeCount = incomingRebirthCount
        end
        if snapshot.skipLevelUpgradeLevel ~= nil then
            local incoming = math.max(0, math.floor(tonumber(snapshot.skipLevelUpgradeLevel) or 0))
            local current = math.max(0, math.floor(tonumber(playerData.skipLevelUpgradeLevel) or 0))
            if incoming > current then playerData.skipLevelUpgradeLevel = incoming end
        end
        if snapshot.skillDamageUpgradeLevel ~= nil then
            local incoming = math.max(0, math.floor(tonumber(snapshot.skillDamageUpgradeLevel) or 0))
            local current = math.max(0, math.floor(tonumber(playerData.skillDamageUpgradeLevel) or 0))
            if incoming > current then playerData.skillDamageUpgradeLevel = incoming end
        end
        if snapshot.cloneCritUpgradeLevel ~= nil then
            local incoming = math.max(0, math.floor(tonumber(snapshot.cloneCritUpgradeLevel) or 0))
            local current = math.max(0, math.floor(tonumber(playerData.cloneCritUpgradeLevel) or 0))
            if incoming > current then playerData.cloneCritUpgradeLevel = incoming end
        end
    end
    if snapshot.skipLevelEnabled ~= nil then
        playerData.skipLevelEnabled = snapshot.skipLevelEnabled == true
    end
    if snapshot.rebirthStone ~= nil then playerData.rebirthStone = snapshot.rebirthStone end
    if snapshot.rebirthStoneBestClaimFloor ~= nil then playerData.rebirthStoneBestClaimFloor = snapshot.rebirthStoneBestClaimFloor end
    ApplyDailyRebirthStoneQuotaValues(
        snapshot.dailyRebirthStoneEarned,
        snapshot.dailyRebirthStoneDayKey,
        source or "snapshot"
    )
    if snapshot.rebirthRunStartFloor ~= nil then playerData.rebirthRunStartFloor = snapshot.rebirthRunStartFloor end
    if snapshot.rebirthRunCompletedFloors ~= nil then playerData.rebirthRunCompletedFloors = snapshot.rebirthRunCompletedFloors end
    if snapshot.rebirthRunSkippedFloors ~= nil then playerData.rebirthRunSkippedFloors = snapshot.rebirthRunSkippedFloors end
    if snapshot.roguelikeRunState ~= nil then
        local legacyClassId = type(snapshot.settings) == "table"
            and snapshot.settings.selectedClassId or nil
        RestoreRoguelikeRunState(snapshot.roguelikeRunState, legacyClassId)
    end
    if snapshot.milestoneRedWeaponClaims ~= nil then playerData.milestoneRedWeaponClaims = snapshot.milestoneRedWeaponClaims end
    if snapshot.activeEquipmentSetIndex ~= nil then playerData.activeEquipmentSetIndex = snapshot.activeEquipmentSetIndex end
    if snapshot.equipment ~= nil then MaybeSetLegacyEquipment(snapshot.equipment, source or "snapshot") end
    if snapshot.equipmentSets ~= nil then playerData.equipmentSets = snapshot.equipmentSets end
    if snapshot.equipment ~= nil and snapshot.equipmentSets == nil then playerData.equipment = snapshot.equipment end
    if snapshot.inventory ~= nil then playerData.inventory = snapshot.inventory end
    if snapshot.skills ~= nil then playerData.skills = snapshot.skills end
    if snapshot.skillFragments ~= nil then playerData.skillFragments = snapshot.skillFragments end
    if snapshot.settings ~= nil then
        playerData.settings = MergeSpeedAdUnlockSettings(snapshot.settings)
    end
    if snapshot.usedStartFloors ~= nil then playerData.usedStartFloors = snapshot.usedStartFloors end
    if snapshot.skillSlots ~= nil then playerData.skillSlots = snapshot.skillSlots end
    if snapshot.skillLoadouts ~= nil then playerData.skillLoadouts = snapshot.skillLoadouts end
    if snapshot.skillSynergy ~= nil then playerData.skillSynergy = MergeSkillSynergyData(playerData.skillSynergy, snapshot.skillSynergy) end
    if snapshot.activeSkillLoadoutIndex ~= nil then playerData.activeSkillLoadoutIndex = snapshot.activeSkillLoadoutIndex end
    if snapshot.unlockedSkillSlots ~= nil then playerData.unlockedSkillSlots = snapshot.unlockedSkillSlots end
    if snapshot.nextSkillUid ~= nil then playerData.nextSkillUid = snapshot.nextSkillUid end
    if snapshot.cloneUnlocked ~= nil then playerData.cloneUnlocked = snapshot.cloneUnlocked == true end
    if snapshot.cloneCount ~= nil then playerData.cloneCount = snapshot.cloneCount end
    if snapshot.cloneUpgradeLevels ~= nil then
        local localLevels = playerData.cloneUpgradeLevels
        if type(localLevels) ~= "table" then localLevels = {} end
        local incoming = snapshot.cloneUpgradeLevels
        if type(incoming) == "table" then
            for i = 1, math.max(#localLevels, #incoming) do
                local localLv = math.max(0, math.floor(tonumber(localLevels[i]) or 0))
                local cloudLv = math.max(0, math.floor(tonumber(incoming[i]) or 0))
                localLevels[i] = math.max(localLv, cloudLv)
            end
            playerData.cloneUpgradeLevels = localLevels
        end
    elseif snapshot.cloneUpgradeLevel ~= nil then
        local localLv = math.max(0, math.floor(tonumber((playerData.cloneUpgradeLevels or {})[1]) or
                                                   tonumber(playerData.cloneUpgradeLevel) or 0))
        local cloudLv = math.max(0, math.floor(tonumber(snapshot.cloneUpgradeLevel) or 0))
        if cloudLv > localLv then
            playerData.cloneUpgradeLevels = nil
            playerData.cloneUpgradeLevel = snapshot.cloneUpgradeLevel
        end
    end
    if snapshot.cloneProtocols ~= nil then
        playerData.cloneProtocols = NormalizeCloneProtocolsData(snapshot.cloneProtocols)
    end
    NormalizeCloneUpgradeLevels()
    NormalizeCloneProtocols()
    if snapshot.redeemedCodes ~= nil then redeemedCodes = snapshot.redeemedCodes end
    ApplyAdventureSnapshot(snapshot.adventureCodex, snapshot.skillResearch)
    NormalizeEquipment()
    NormalizeEquipmentSettings()
    NormalizeSkills()
    NormalizeSkillFragments()
    NormalizeSkillLoadouts()
    NormalizeSkillSynergy()
    NormalizeRebirthStoneSystem()
    ApplyRebirthBonuses()
    ApplyRedeemedCodeRewards()
    print("[Save] 已应用", source or "snapshot", "金币:", playerData.gold, "背包数量:", #playerData.inventory)
    return true
end

function CountEquipmentItemsForDiagnostic(source)
    if type(source) ~= "table" then return 0 end
    local count = 0
    local seenItems = {}
    local function addItem(item, fallbackSlot)
        if type(item) ~= "table" or seenItems[item] then return end
        if IsEquipmentLikeItem(item, fallbackSlot) then
            seenItems[item] = true
            count = count + 1
        end
    end
    local function scan(container)
        if type(container) ~= "table" then return end
        for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS) do
            addItem(container[slotDef.id], slotDef.id)
            addItem(container[tostring(slotDef.id)], slotDef.id)
        end
        for _, value in pairs(container) do
            addItem(value, nil)
        end
    end
    scan(source)
    scan(source.equipment)
    scan(source.slots)
    scan(source.items)
    scan(source.data)
    if type(source.equipment) == "table" then
        scan(source.equipment.equipment)
        scan(source.equipment.slots)
    end
    return count
end

function CountEquipmentSetsForDiagnostic(sets)
    if type(sets) ~= "table" then return 0 end
    local wrapped = sets.equipmentSets or sets.equipment_sets or sets.sets
    if type(wrapped) == "table" then
        sets = wrapped
    end
    local count = 0
    for index = 1, EQUIPMENT_SET_COUNT do
        count = count + CountEquipmentItemsForDiagnostic(sets[index]) + CountEquipmentItemsForDiagnostic(sets[tostring(index)])
    end
    if count <= 0 then
        count = CountEquipmentItemsForDiagnostic(sets)
    end
    return count
end

function CountInventoryEquipmentForDiagnostic(inventory)
    return CountEquipmentItemsForDiagnostic(inventory)
end

function PrintLocalEquipmentSourceDiagnostic(snapshot, label)
    if type(snapshot) ~= "table" then return end
    print(string.format("[EquipmentRecovery] %s: snapshot.equipment=%d, snapshot.equipmentSets=%d, snapshot.inventoryEquipment=%d, snapshot.activeEquipmentSetIndex=%s, snapshot.saved_at=%s",
        label or "本地快照读取",
        CountEquipmentItemsForDiagnostic(snapshot.equipment),
        CountEquipmentSetsForDiagnostic(snapshot.equipmentSets),
        CountInventoryEquipmentForDiagnostic(snapshot.inventory),
        tostring(snapshot.activeEquipmentSetIndex),
        tostring(snapshot.saved_at)))
end

function PrintCloudEquipmentSourceDiagnostic(values, label)
    values = values or {}
    local blob = type(values.save_blob) == "table" and values.save_blob or nil
    print(string.format("[EquipmentRecovery] %s: cloud.equipment=%d, cloud.equipment_sets=%d, cloud.inventoryEquipment=%d, blob.equipment=%d, blob.equipmentSets=%d, blob.inventoryEquipment=%d, current.equipment=%d, current.equipmentSets=%d, current.legacyEquipment=%d, current.inventoryEquipment=%d, cloud.active=%s, blob.active=%s, blob.saved_at=%s, localSaveLoaded=%s, localSaveTimestamp=%s",
        label or "云端读取",
        CountEquipmentItemsForDiagnostic(values.equipment),
        CountEquipmentSetsForDiagnostic(values.equipment_sets),
        CountInventoryEquipmentForDiagnostic(values.inventory),
        blob and CountEquipmentItemsForDiagnostic(blob.equipment) or 0,
        blob and CountEquipmentSetsForDiagnostic(blob.equipmentSets) or 0,
        blob and CountInventoryEquipmentForDiagnostic(blob.inventory) or 0,
        CountEquipmentItemsForDiagnostic(playerData.equipment),
        CountEquipmentSetsForDiagnostic(playerData.equipmentSets),
        CountEquipmentItemsForDiagnostic(playerData.legacyEquipment),
        CountInventoryEquipmentForDiagnostic(playerData.inventory),
        tostring(values.active_equipment_set_index),
        tostring(blob and blob.activeEquipmentSetIndex or nil),
        tostring(blob and blob.saved_at or nil),
        tostring(localSaveLoaded),
        tostring(localSaveTimestamp)))
end

local function ReadLocalSnapshotFile(path)
    if not fileSystem:FileExists(path) then return nil, "missing" end
    local file = File(path, FILE_READ)
    if file == nil or not file:IsOpen() then return nil, "open" end
    local content = file:ReadString()
    file:Close()
    local snapshot, reason = DecodeLocalSaveContent(content)
    if snapshot == nil then return nil, reason or "decode" end
    if not HasCurrentSaveGeneration(snapshot) then return nil, "generation" end
    return snapshot, nil
end

local function WriteVerifiedLocalSnapshot(path, encodedText)
    local file = File(path, FILE_WRITE)
    if file == nil or not file:IsOpen() then return false, "open" end
    file:WriteString(encodedText)
    file:Close()
    local verified, reason = ReadLocalSnapshotFile(path)
    if verified == nil then return false, reason or "verify" end
    return true, nil
end

SaveLocalSnapshot = function(skipTimestampUpdate, preparedSnapshot)
    local startedClock = os.clock()
    local snapshot = preparedSnapshot or BuildSaveSnapshot()
    local incomingSerial = math.max(0, math.floor(tonumber(snapshot.saveSerial) or 0))
    local isLatestProgressSave = not skipTimestampUpdate
        or snapshot._latest_progress_save == true
    if isLatestProgressSave then
        localSaveSerial = math.max((localSaveSerial or 0) + 1, incomingSerial)
        snapshot.saveSerial = localSaveSerial
        snapshot.saved_at = math.max(os.time(), localSaveTimestamp or 0)
    else
        snapshot.saveSerial = math.max(localSaveSerial or 0, incomingSerial)
    end
    snapshot._chk = ComputeInlineChecksum(snapshot)
    if snapshot._blob_hash ~= nil then
        snapshot._blob_hash = ComputeCloudBlobHash(snapshot)
    end
    if skipTimestampUpdate and not isLatestProgressSave and localSaveLoaded and localSaveTimestamp > 0 then
        snapshot.saved_at = localSaveTimestamp
        snapshot._chk = ComputeInlineChecksum(snapshot)
        if snapshot._blob_hash ~= nil then
            snapshot._blob_hash = ComputeCloudBlobHash(snapshot)
        end
    end
    local ok, encoded = pcall(cjson.encode, snapshot)
    if not ok then
        print("[LocalSave] 编码失败:", encoded)
        return false
    end
    local envelopeOk, envelope = pcall(EncodeLocalSaveSnapshot, tostring(encoded))
    if not envelopeOk then
        print("[LocalSave] 加密封装失败:", envelope)
        return false
    end
    local encodedText = tostring(envelope)
    local slotIndex = math.max(1, math.min(#LOCAL_SAVE_SLOT_PATHS, localSaveNextSlotIndex or 1))
    local slotPath = LOCAL_SAVE_SLOT_PATHS[slotIndex]
    local slotOk, slotReason = WriteVerifiedLocalSnapshot(slotPath, encodedText)
    if not slotOk then
        print("[LocalSave] 轮换槽写入校验失败:", slotPath, slotReason)
        return false
    end
    localSaveNextSlotIndex = (slotIndex % #LOCAL_SAVE_SLOT_PATHS) + 1

    local mainOk, mainReason = WriteVerifiedLocalSnapshot(localSavePath, encodedText)
    if not mainOk then
        print("[LocalSave] 主文件更新失败，已保留有效轮换槽:", mainReason)
    end
    if not skipTimestampUpdate and isLatestProgressSave then
        localSaveTimestamp = snapshot.saved_at or os.time()
    elseif skipTimestampUpdate and isLatestProgressSave then
        localSaveTimestamp = snapshot.saved_at or os.time()
    end
    print("[LocalSave] 已写入并校验本地快照, 槽:", slotIndex,
        "字节:", string.len(encodedText),
        "耗时:", string.format("%.1fms", (os.clock() - startedClock) * 1000),
        skipTimestampUpdate and "(保留仲裁时间戳)" or "")
    return true
end

LoadLocalSnapshot = function()
    local candidates = {
        { path = localSavePath, label = "兼容主文件" },
    }
    for index, path in ipairs(LOCAL_SAVE_SLOT_PATHS) do
        table.insert(candidates, { path = path, label = "轮换槽" .. tostring(index), slot = index })
    end

    local best = nil
    for _, candidate in ipairs(candidates) do
        local snapshot, reason = ReadLocalSnapshotFile(candidate.path)
        if snapshot ~= nil then
            local timestamp = math.max(0, math.floor(tonumber(snapshot.saved_at) or 0))
            local serial = math.max(0, math.floor(tonumber(snapshot.saveSerial) or 0))
            if best == nil or timestamp > best.timestamp
                or (timestamp == best.timestamp and serial > best.serial) then
                best = {
                    snapshot = snapshot,
                    timestamp = timestamp,
                    serial = serial,
                    path = candidate.path,
                    label = candidate.label,
                    slot = candidate.slot,
                }
            end
        elseif reason ~= "missing" then
            print("[LocalSave] 候选快照不可用:", candidate.label, reason)
        end
    end

    if best == nil then
        print("[LocalSave] 未发现有效本地快照")
        return false
    end
    PrintLocalEquipmentSourceDiagnostic(best.snapshot, best.label)
    localSaveLoaded = ApplySaveSnapshot(best.snapshot, best.label)
    if localSaveLoaded then
        localSaveTimestamp = best.timestamp
        localSaveSerial = best.serial
        if IsSaveSnapshotMeaningful(best.snapshot) then
            lastKnownGoodCloudSnapshot = best.snapshot
        end
        if best.slot ~= nil then
            localSaveNextSlotIndex = (best.slot % #LOCAL_SAVE_SLOT_PATHS) + 1
        end
        print("[LocalSave] 已选择最新有效快照:", best.label,
            "saved_at=", best.timestamp)
    end
    return localSaveLoaded
end

