local function ExtractOfficialCloudMaps(rawValues, rawScores)
    local values = {}
    local iscores = {}
    for key, value in pairs(rawValues or {}) do
        local plainKey = tostring(key):match("^" .. OFFICIAL_SAVE_PREFIX .. "(.+)$")
        if plainKey ~= nil then values[plainKey] = value end
    end
    for key, value in pairs(rawScores or {}) do
        local plainKey = tostring(key):match("^" .. OFFICIAL_SAVE_PREFIX .. "(.+)$")
        if plainKey ~= nil then iscores[plainKey] = value end
    end
    return values, iscores
end

function HasPersistableLocalProgress()
    if localSaveLoaded == true then
        return true
    end
    if type(IsSaveSnapshotMeaningful) == "function" then
        return IsSaveSnapshotMeaningful(BuildSaveSnapshot())
    end
    return false
end

function KeepCloudWriteReadyIfLocalProgress(reason)
    if not HasPersistableLocalProgress() then
        return false
    end
    cloudDataReadyForSave = true
    print("[Cloud] 已有本地进度，保持云写入开启:", tostring(reason or "local_progress"))
    return true
end

function IsSaveSnapshotMeaningful(snapshot)
    if type(snapshot) ~= "table" then return false end
    if math.max(0, math.floor(tonumber(snapshot.bestFloor) or 0)) > 0 then return true end
    if math.max(0, math.floor(tonumber(snapshot.normalHighestClearedFloor) or 0)) > 0 then return true end
    if math.max(0, math.floor(tonumber(snapshot.endlessBestFloor) or 0)) > 0 then return true end
    if math.max(0, math.floor(tonumber(snapshot.totalGoldEarned) or 0)) > 0 then return true end
    if math.max(0, math.floor(tonumber(snapshot.totalKills) or 0)) > 0 then return true end
    if math.max(0, math.floor(tonumber(snapshot.playCount) or 0)) > 0 then return true end
    if math.max(0, math.floor(tonumber(snapshot.totalPlayTime) or 0)) > 60 then return true end
    if math.max(0, math.floor(tonumber(snapshot.rebirthCount) or 0)) > 0 then return true end
    if math.max(0, math.floor(tonumber(snapshot.rebirthUpgradeCount) or 0)) > 0 then return true end
    if type(snapshot.inventory) == "table" and next(snapshot.inventory) ~= nil then return true end
    if type(snapshot.skills) == "table" and next(snapshot.skills) ~= nil then return true end
    if type(snapshot.equipmentSets) == "table" and CountEquipmentSetsForDiagnostic(snapshot.equipmentSets) > 0 then return true end
    if type(snapshot.equipment) == "table" and CountEquipmentItemsForDiagnostic(snapshot.equipment) > 0 then return true end
    return false
end

function PrepareFreshData(onComplete)
    if dataResetComplete then
        if onComplete then onComplete(true, true) end
        return
    end
    if clientCloud == nil then
        dataResetInProgress = false
        KeepCloudWriteReadyIfLocalProgress("prepare_client_cloud_nil")
        if not cloudDataReadyForSave then
            cloudDataReadyForSave = false
        end
        cloudSyncLastError = "云组件未初始化 clientCloud=nil"
        cloudSyncStatusText = "云存档组件未初始化，等待重试"
        print("[OfficialSave] clientCloud=nil，未发起核心档检查")
        if onComplete then onComplete(false, false) end
        return
    end

    dataResetInProgress = true
    local prepareStartedManualSaveRevision = manualSaveRevision or 0
    local request = clientCloud:BatchGet()
    local keys = {
        DATA_RESET_CLEANUP_KEY,
        "save_blob",
        "save_blob_backup",
    }
    print("[OfficialSave] 核心档检查开始 keyCount=", #keys)
    for _, key in ipairs(keys) do request:Key(OfficialSaveKey(key)) end
    request:Fetch({
        ok = function(rawValues, rawScores)
            if (manualSaveRevision or 0) ~= prepareStartedManualSaveRevision then
                dataResetComplete = true
                dataResetInProgress = false
                cloudDataLoaded = true
                cloudDataReadyForSave = true
                saveDirty = true
                print("[OfficialSave] 手动存档优先，跳过初始化结果应用并提交最新本地快照:",
                    "manualRevision=", tostring(manualSaveRevision or 0),
                    "prepareRevision=", tostring(prepareStartedManualSaveRevision))
                SaveLocalSnapshot(true)
                SaveCloudData(true)
                if onComplete then onComplete(true, true) end
                return
            end
            local values, iscores = ExtractOfficialCloudMaps(rawValues, rawScores)
            local currentBlob = values.save_blob
            local backupBlob = values.save_blob_backup
            local hasCurrentBlob = HasCurrentSaveGeneration(currentBlob)
            local hasBackupBlob = HasCurrentSaveGeneration(backupBlob)
            local initialized = values[DATA_RESET_CLEANUP_KEY] == true
            local hasRecoverableData = localSaveLoaded
                or hasCurrentBlob
                or hasBackupBlob
                or HasAnyCloudSave(values, iscores)
            if initialized and not hasRecoverableData then
                dataResetInProgress = false
                if not KeepCloudWriteReadyIfLocalProgress("prepare_missing_blob") then
                    cloudDataReadyForSave = false
                end
                cloudSyncLastError = "核心检查发现初始化标记存在但主/备份快照缺失"
                print("[OfficialSave] 初始化标记存在但存档内容缺失，禁止创建空档覆盖")
                if onComplete then onComplete(false, false) end
                return
            end
            local hasExistingData = initialized or hasRecoverableData

            if hasExistingData then
                dataResetComplete = true
                dataResetInProgress = false
                print("[OfficialSave] 检测到现有正式数据，跳过任何初始化清零",
                    "initialized=", tostring(initialized),
                    "currentBlob=", tostring(hasCurrentBlob),
                    "backupBlob=", tostring(hasBackupBlob))
                if onComplete then onComplete(true, true) end
                return
            end

            local preservedSettings = CopyLegacyDisplaySettings(
                rawValues and rawValues.settings or nil)
            local localSettings = LoadLegacyDisplaySettings()
            for key, value in pairs(localSettings) do preservedSettings[key] = value end
            ResetOfficialPlayerData(preservedSettings)
            local initialSnapshot = BuildSaveSnapshot()
            initialSnapshot._blob_hash = ComputeCloudBlobHash(initialSnapshot)
            local initialPublicProfile = BuildPublicProfile()

            local dailyNewDayKey = GetCurrentCstDayKey()
            local dailyNewLeaderboardKey = GetDailyNewLeaderboardPlainKey(dailyNewDayKey)
            local initBatch = OfficialBatchSet()
                :Set(DATA_RESET_CLEANUP_KEY, true)
                :Set("save_blob", initialSnapshot)
                :Set("save_blob_backup", initialSnapshot)
                :Set("public_profile", initialPublicProfile)
            if dailyNewLeaderboardKey ~= nil then
                initBatch:SetInt(dailyNewLeaderboardKey, 1)
            end
            initBatch:Save("创建正式玩家初始存档", {
                    ok = function()
                        dataResetComplete = true
                        dataResetInProgress = false
                        cloudDataLoaded = true
                        cloudDataReadyForSave = true
                        lastKnownGoodCloudSnapshot = initialSnapshot
                        if dailyNewLeaderboardKey ~= nil then
                            print("[DailyStats] 记录新增玩家:", dailyNewDayKey)
                        end
                        saveDirty = false
                        SaveLocalSnapshot(false, initialSnapshot)
                        print("[OfficialSave] 已创建新玩家初始存档（未清零历史字段）")
                        if onComplete then onComplete(true, false) end
                    end,
                    error = function(code, reason)
                        dataResetInProgress = false
                        if not KeepCloudWriteReadyIfLocalProgress("prepare_init_write_failed") then
                            cloudDataReadyForSave = false
                        end
                        cloudSyncLastError = "新玩家初始存档写入失败 code=" .. tostring(code) .. " reason=" .. tostring(reason)
                        print("[OfficialSave] 新玩家初始化失败 code=", tostring(code), "reason=", tostring(reason))
                        if onComplete then onComplete(false, false) end
                    end,
                    timeout = function()
                        dataResetInProgress = false
                        if not KeepCloudWriteReadyIfLocalProgress("prepare_init_write_timeout") then
                            cloudDataReadyForSave = false
                        end
                        cloudSyncLastError = "新玩家初始存档写入超时"
                        print("[OfficialSave] 新玩家初始化超时")
                        if onComplete then onComplete(false, false) end
                    end,
                })
        end,
        error = function(code, reason)
            dataResetInProgress = false
            if not KeepCloudWriteReadyIfLocalProgress("prepare_check_failed") then
                cloudDataReadyForSave = false
            end
            print("[OfficialSave] 核心档检查失败 keyCount=", #keys,
                "code=", tostring(code), "reason=", tostring(reason))
            cloudSyncLastError = "核心检查 code=" .. tostring(code) .. " reason=" .. tostring(reason)
            if onComplete then onComplete(false, false) end
        end,
        timeout = function()
            dataResetInProgress = false
            if not KeepCloudWriteReadyIfLocalProgress("prepare_check_timeout") then
                cloudDataReadyForSave = false
            end
            print("[OfficialSave] 核心档检查超时 keyCount=", #keys)
            cloudSyncLastError = "核心检查超时 keyCount=" .. tostring(#keys)
            if onComplete then onComplete(false, false) end
        end,
    })
end

TARGETED_INVENTORY_REPAIR_UID = "2065287529"
TARGETED_INVENTORY_REPAIR_VERSION = 1
TARGETED_INVENTORY_REPAIR_KEY = "targetedInventoryRepairVersion"

local function GetTargetedInventoryRepairVersion(settings)
    if type(settings) ~= "table" then return 0 end
    return math.max(0, math.floor(tonumber(settings[TARGETED_INVENTORY_REPAIR_KEY]) or 0))
end

local function RemoveEquipmentFromInventory(inventory)
    local kept = {}
    for _, item in ipairs(inventory or {}) do
        if item and item.type ~= "equipment" then
            table.insert(kept, item)
        end
    end
    return kept
end

local function PrepareTargetedInventoryRepair(values)
    if clientCloud == nil
        or tostring(clientCloud.userId or "") ~= TARGETED_INVENTORY_REPAIR_UID then
        return false, false
    end

    values = values or {}
    local cloudSnapshot = type(values.save_blob) == "table" and values.save_blob or nil
    local localVersion = GetTargetedInventoryRepairVersion(playerData.settings)
    local cloudVersion = math.max(
        GetTargetedInventoryRepairVersion(values.settings),
        GetTargetedInventoryRepairVersion(cloudSnapshot and cloudSnapshot.settings))

    playerData.settings = playerData.settings or {}

    if cloudVersion >= TARGETED_INVENTORY_REPAIR_VERSION then
        if localVersion < TARGETED_INVENTORY_REPAIR_VERSION then
            local staleCount = type(playerData.inventory) == "table" and #playerData.inventory or 0
            playerData.inventory = RemoveEquipmentFromInventory(playerData.inventory)
            playerData.settings[TARGETED_INVENTORY_REPAIR_KEY] = TARGETED_INVENTORY_REPAIR_VERSION
            saveDirty = true
            print("[TargetedInventoryRepair] 检测到旧设备本地快照，已丢弃修复前背包:", staleCount,
                "uid=", TARGETED_INVENTORY_REPAIR_UID)
            return false, true
        end
        return false, false
    end

    local repairedInventory = {}
    if localVersion >= TARGETED_INVENTORY_REPAIR_VERSION then
        repairedInventory = playerData.inventory or {}
        print("[TargetedInventoryRepair] 复用已修复本地背包重试云端提交, 数量:", #repairedInventory)
    else
        local localCount = type(playerData.inventory) == "table" and #playerData.inventory or 0
        local cloudCount = type(values.inventory) == "table" and #values.inventory
            or (cloudSnapshot and type(cloudSnapshot.inventory) == "table" and #cloudSnapshot.inventory or 0)
        playerData.inventory = RemoveEquipmentFromInventory(playerData.inventory)
        repairedInventory = playerData.inventory
        print("[TargetedInventoryRepair] 执行定向清理未穿戴装备, uid=", TARGETED_INVENTORY_REPAIR_UID,
            "本地数量=", localCount, "云端数量=", cloudCount)
    end

    playerData.settings[TARGETED_INVENTORY_REPAIR_KEY] = TARGETED_INVENTORY_REPAIR_VERSION
    values.inventory = repairedInventory
    if type(values.settings) == "table" then
        values.settings[TARGETED_INVENTORY_REPAIR_KEY] = TARGETED_INVENTORY_REPAIR_VERSION
    end
    if cloudSnapshot ~= nil then
        cloudSnapshot.inventory = repairedInventory
        cloudSnapshot.settings = cloudSnapshot.settings or {}
        cloudSnapshot.settings[TARGETED_INVENTORY_REPAIR_KEY] = TARGETED_INVENTORY_REPAIR_VERSION
        cloudSnapshot._chk = ComputeInlineChecksum(cloudSnapshot)
        cloudSnapshot._blob_hash = ComputeCloudBlobHash(cloudSnapshot)
    end
    saveDirty = true
    return true, false
end

function GetRuntimeSaveFingerprint()
    -- 只用稳定进度字段做指纹：不要序列化整份快照。
    -- BuildSaveSnapshot + cjson.encode 会因表键顺序和 Normalize 副作用产生误报，
    -- 进而把“本地进度变化”当成冲突，关掉云写入并回档。
    local inventoryCount = 0
    if type(playerData.inventory) == "table" then
        inventoryCount = #playerData.inventory
    end
    local skillCount = 0
    if type(playerData.skills) == "table" then
        skillCount = #playerData.skills
    end
    return table.concat({
        tostring(math.floor(tonumber(saveVersion) or 0)),
        tostring(math.floor(tonumber(REAL_PROGRESS_REVISION) or 0)),
        tostring(math.floor(tonumber(manualSaveRevision) or 0)),
        tostring(math.floor(tonumber(playerData.gold) or 0)),
        tostring(math.floor(tonumber(playerData.bestFloor) or 0)),
        tostring(math.floor(tonumber(playerData.currentFloor) or 0)),
        tostring(math.floor(tonumber(playerData.normalHighestClearedFloor) or 0)),
        tostring(math.floor(tonumber(playerData.totalGoldEarned) or 0)),
        tostring(math.floor(tonumber(playerData.rebirthCount) or 0)),
        tostring(math.floor(tonumber(playerData.rebirthUpgradeCount) or 0)),
        tostring(math.floor(tonumber(playerData.rebirthStone) or 0)),
        tostring(inventoryCount),
        tostring(skillCount),
        tostring(math.floor(tonumber(playerData.highScore) or 0)),
    }, "|")
end

function LoadCloudData(onComplete)
    CLOUD_DATA_FETCH_IN_PROGRESS = true
    local function FinishCloudDataFetch(success, failureReason)
        CLOUD_DATA_FETCH_IN_PROGRESS = false
        if success and RefreshCurrentPlayerNicknameCache ~= nil then
            RefreshCurrentPlayerNicknameCache()
        end
        if not success and failureReason ~= nil and (cloudSyncLastError == nil or cloudSyncLastError == "") then
            cloudSyncLastError = tostring(failureReason)
        end
        if onComplete then onComplete(success, failureReason) end
    end
    local fetchStartedDirty = (saveDirty == true)
    local fetchStartedVersion = saveVersion or 0
    local fetchStartedFingerprint = GetRuntimeSaveFingerprint()
    local fetchStartedManualSaveRevision = manualSaveRevision or 0
    local fetchHadWriteReady = (cloudDataReadyForSave == true)
    local fetchHadLiveSession = currentScreen == "playing"
        or currentScreen == "auto_continue"
        or currentScreen == "gameover"
    local coreKeys = {
        "save_blob_backup",
        "save_blob",
    }
    print("[Cloud] 核心云档读取开始 keyCount=", #coreKeys)
    local coreRequest = OfficialBatchGet()
    for _, key in ipairs(coreKeys) do coreRequest:Key(key) end
    coreRequest:Fetch({
            ok = function(values, iscores)
                values = values or {}
                iscores = iscores or {}
                local currentCloudSnapshot = type(values.save_blob) == "table" and values.save_blob or nil
                local backupCloudSnapshot = type(values.save_blob_backup) == "table" and values.save_blob_backup or nil
                local currentValid = HasCurrentSaveGeneration(currentCloudSnapshot)
                local backupValid = HasCurrentSaveGeneration(backupCloudSnapshot)
                if backupValid and (not currentValid
                    or (not IsSaveSnapshotMeaningful(currentCloudSnapshot)
                        and IsSaveSnapshotMeaningful(backupCloudSnapshot))) then
                    values.save_blob = backupCloudSnapshot
                    print("[CloudRecovery] 当前云快照缺失或异常为空，改用上一份有效快照")
                end
                local selectedCloudSnapshot = type(values.save_blob) == "table" and values.save_blob or nil
                if HasCurrentSaveGeneration(selectedCloudSnapshot)
                    and IsSaveSnapshotMeaningful(selectedCloudSnapshot) then
                    lastKnownGoodCloudSnapshot = selectedCloudSnapshot
                end

                local targetedRepairNeeded, targetedRepairForceCloud = false, false
                local currentFingerprint = GetRuntimeSaveFingerprint()
                local manualSaveDuringFetch = (manualSaveRevision or 0) ~= fetchStartedManualSaveRevision
                local newProgressDuringFetch = currentFingerprint ~= fetchStartedFingerprint
                    or (saveVersion or 0) ~= fetchStartedVersion
                    or (saveDirty == true and not fetchStartedDirty)
                local alreadyHadLiveSession = fetchHadLiveSession
                    or currentScreen == "playing"
                    or currentScreen == "auto_continue"
                    or currentScreen == "gameover"
                if cloudSaveInProgress or manualSaveDuringFetch or manualSavePendingCloud then
                    cloudDataLoaded = true
                    cloudDataReadyForSave = true
                    saveDirty = true
                    print("[Cloud] 手动存档优先，跳过本轮云读取应用并提交最新本地快照:",
                        "manualRevision=", tostring(manualSaveRevision or 0),
                        "fetchManualRevision=", tostring(fetchStartedManualSaveRevision),
                        "cloudSaveInProgress=", tostring(cloudSaveInProgress))
                    SaveLocalSnapshot(true)
                    SaveCloudData(true)
                    FinishCloudDataFetch(true)
                    return
                end
                if alreadyHadLiveSession and newProgressDuringFetch then
                    -- 本局已有可写云档或正在推进进度时，本地才是权威来源。
                    -- 旧逻辑会关掉云写入并把下次重试当成“首次启动”，再用旧云档覆盖本地。
                    cloudDataLoaded = true
                    cloudDataReadyForSave = true
                    print("[Cloud] 云读取期间本地进度已变化，保留本地并回写云端:",
                        "screen=", currentScreen,
                        "saveDirty=", tostring(saveDirty),
                        "startedDirty=", tostring(fetchStartedDirty),
                        "startedVersion=", tostring(fetchStartedVersion),
                        "currentVersion=", tostring(saveVersion or 0),
                        "startedFingerprint=", tostring(fetchStartedFingerprint),
                        "currentFingerprint=", tostring(currentFingerprint))
                    SaveLocalSnapshot(true)
                    SaveCloudData(true)
                    FinishCloudDataFetch(true)
                    return
                end
                if newProgressDuringFetch then
                    print("[Cloud] 首次云读取期间本地状态有变化，继续走本地/云端仲裁而非放弃")
                end
                MergeDailySpeedQuotaFromCloud(values, iscores)
                MergeDailySpeedAdClaimsFromCloud(values, iscores)
                MergeDailyRewardAdClaimsFromCloud(values, iscores)
                MergeDailySocketPuncherAdClaimsFromCloud(values, iscores)
                MergeEquipmentUpgradeProtectionState(
                    values.daily_equipment_upgrade_ad_claim_day,
                    iscores.daily_equipment_upgrade_ad_claim_count,
                    values.pending_equipment_upgrade_penalty,
                    iscores.equipment_upgrade_penalty_resolved_id,
                    iscores.next_equipment_uid
                )
                MergeDailyRebirthStoneQuotaFromCloud(values, iscores)
                MergeAdminMaterialGrantClaims(values.admin_material_grant_claims)
                MergeAdminRebirthStoneGrantClaims(values.admin_rebirth_stone_grant_claims)
                PrintCloudEquipmentSourceDiagnostic(values, "云端读取原始来源")
                local incomingSnapshot = values.save_blob
                local incomingEquipmentCount = CountEquipmentItems(values.equipment) + CountEquipmentSetsItems(values.equipment_sets)
                if incomingSnapshot then
                    incomingEquipmentCount = math.max(incomingEquipmentCount, CountEquipmentItems(incomingSnapshot.equipment) + CountEquipmentSetsItems(incomingSnapshot.equipmentSets))
                end
                local currentEquipmentCount = CountEquipmentItems(playerData.equipment) + CountEquipmentSetsItems(playerData.equipmentSets) + CountEquipmentItems(playerData.legacyEquipment)
                local shouldApplyEquipmentRecovery = currentEquipmentCount == 0 and incomingEquipmentCount > 0
                if HasAnyCloudSave(values, iscores) then
                    local cloudSnapshot = nil
                    if values.save_blob then
                        cloudSnapshot = values.save_blob
                    end
                    local cloudTimestamp = (cloudSnapshot and cloudSnapshot.saved_at) or 0
                    local cloudEquipmentCount = CountEquipmentItems(values.equipment) + CountEquipmentSetsItems(values.equipment_sets)
                    if cloudSnapshot then
                        cloudEquipmentCount = math.max(cloudEquipmentCount, CountEquipmentItems(cloudSnapshot.equipment) + CountEquipmentSetsItems(cloudSnapshot.equipmentSets))
                    end
                    local localEquipmentCount = CountEquipmentItems(playerData.equipment) + CountEquipmentSetsItems(playerData.equipmentSets) + CountEquipmentItems(playerData.legacyEquipment)
                    local localRebirthCount = math.max(0, math.floor(tonumber(playerData.rebirthUpgradeCount) or 0))
                    local cloudRebirthCount = 0
                    if iscores and iscores.rebirth_upgrade_count ~= nil then
                        cloudRebirthCount = math.max(0, math.floor(tonumber(iscores.rebirth_upgrade_count) or 0))
                    end
                    local cloudBlobRebirthCount = 0
                    if cloudSnapshot and cloudSnapshot.rebirthUpgradeCount ~= nil then
                        cloudBlobRebirthCount = math.max(0, math.floor(tonumber(cloudSnapshot.rebirthUpgradeCount) or 0))
                    end
                    cloudRebirthCount = math.max(cloudRebirthCount, cloudBlobRebirthCount)
                    -- 永久强化重置世代（看广告重置）不同时，以世代高者为准，
                    -- 避免重置后的低等级被旧云的“强化次数更多”判负而回滚。
                    local localUpgradeResetGen = math.max(0, math.floor(tonumber(playerData.rebirthUpgradeResetId) or 0))
                    local cloudUpgradeResetGen = 0
                    if iscores and iscores.rebirth_upgrade_reset_id ~= nil then
                        cloudUpgradeResetGen = math.max(0, math.floor(tonumber(iscores.rebirth_upgrade_reset_id) or 0))
                    end
                    if cloudSnapshot and cloudSnapshot.rebirthUpgradeResetId ~= nil then
                        cloudUpgradeResetGen = math.max(
                            cloudUpgradeResetGen,
                            math.max(0, math.floor(tonumber(cloudSnapshot.rebirthUpgradeResetId) or 0))
                        )
                    end
                    local preferLocalByCount = localRebirthCount > cloudRebirthCount
                    if localUpgradeResetGen ~= cloudUpgradeResetGen then
                        preferLocalByCount = localUpgradeResetGen > cloudUpgradeResetGen
                    end
                    local preferLocalByTimestamp = localSaveLoaded and localSaveTimestamp > 0 and localSaveTimestamp > cloudTimestamp
                    local localSaveSerialValue = math.max(0, math.floor(tonumber(localSaveSerial) or 0))
                    local cloudSaveSerialValue = math.max(0, math.floor(tonumber(cloudSnapshot and cloudSnapshot.saveSerial) or 0))
                    local preferLocalBySerial = localSaveSerialValue > cloudSaveSerialValue
                    local function dimCmp(localVal, cloudVal, threshold)
                        localVal = tonumber(localVal) or 0
                        cloudVal = tonumber(cloudVal) or 0
                        threshold = threshold or 0
                        if cloudVal - localVal > threshold then return "cloud" end
                        if localVal - cloudVal > threshold then return "local" end
                        return "tie"
                    end
                    local cloudBestFloor = math.max(tonumber(iscores.best_floor) or 0, tonumber(cloudSnapshot and cloudSnapshot.bestFloor) or 0)
                    local cloudTotalGold = math.max(tonumber(iscores.total_gold_earned) or 0, tonumber(cloudSnapshot and cloudSnapshot.totalGoldEarned) or 0)
                    local cloudRebirthTimes = math.max(tonumber(iscores.rebirth_count) or 0, tonumber(cloudSnapshot and cloudSnapshot.rebirthCount) or 0)
                    local dims = {
                        dimCmp(playerData.bestFloor or 0, cloudBestFloor, 1),
                        dimCmp(playerData.totalGoldEarned or 0, cloudTotalGold, 100),
                        dimCmp(playerData.rebirthCount or 0, cloudRebirthTimes, 0),
                        dimCmp(localEquipmentCount, cloudEquipmentCount, 0),
                    }
                    local localAhead, cloudAhead = 0, 0
                    for i = 1, #dims do
                        if dims[i] == "local" then localAhead = localAhead + 1 end
                        if dims[i] == "cloud" then cloudAhead = cloudAhead + 1 end
                    end
                    local cloudStronglyAhead = (cloudAhead >= 2 and localAhead == 0)
                    local localProgressRevision = math.max(
                        0, math.floor(tonumber(REAL_PROGRESS_REVISION) or 0))
                    local localManualRevision = math.max(
                        0, math.floor(tonumber(manualSaveRevision) or 0))
                    local cloudManualRevision = math.max(
                        0, math.floor(tonumber(cloudSnapshot and cloudSnapshot.manualSaveRevision) or 0))
                    local preferLocalByManualSave = localManualRevision > cloudManualRevision
                    local cloudProgressRevision = math.max(
                        0, math.floor(tonumber(cloudSnapshot and cloudSnapshot.progressRevision) or 0))
                    local preferLocalByRevision = localProgressRevision > cloudProgressRevision
                    local preferCloudByRevision = cloudProgressRevision > localProgressRevision
                    local preferLocalByLiveSession = alreadyHadLiveSession
                        and not preferCloudByRevision
                        and not (cloudManualRevision > localManualRevision)
                    local localWinsArbitration = not targetedRepairForceCloud
                        and (preferLocalByLiveSession
                            or preferLocalByManualSave
                            or (not (cloudManualRevision > localManualRevision)
                                and (preferLocalByRevision
                                    or preferLocalBySerial
                                    or (not preferCloudByRevision
                                        and (preferLocalByCount
                                            or (preferLocalByTimestamp
                                                and not (localEquipmentCount == 0 and cloudEquipmentCount > 0)
                                                and not (localSaveTimestamp == 0 and cloudTimestamp > 0)))))))
                        and not cloudStronglyAhead
                    if cloudStronglyAhead then
                        print("[Cloud][P1] 多维度仲裁判定云端领先：",
                            "cloudAhead=", cloudAhead, "localAhead=", localAhead,
                            "bestFloor(local/cloud)=", tostring(playerData.bestFloor), "/", tostring(cloudBestFloor),
                            "totalGold=", tostring(playerData.totalGoldEarned), "/", tostring(cloudTotalGold),
                            "rebirth=", tostring(playerData.rebirthCount), "/", tostring(cloudRebirthTimes),
                            "equip=", tostring(localEquipmentCount), "/", tostring(cloudEquipmentCount))
                    end
                    if localWinsArbitration then
                        print("[Cloud] 保留本地并回写云端，本地时间:", localSaveTimestamp, "云端时间:", cloudTimestamp,
                            "本地强化:", localRebirthCount, "云端强化:", cloudRebirthCount)
                        cloudDataLoaded = true
                        cloudDataReadyForSave = true
                        SaveCloudData(true)
                    else
                        if cloudSnapshot then
                            local blobHashOk = ValidateCloudBlobHash(cloudSnapshot)
                            if not blobHashOk then
                                print("[Cloud] ⚠️ blob 哈希校验未通过，但仍应用云端快照（受信存储，SanitizeSnapshot/单调 max 保护）")
                            end
                            local applied = ApplySaveSnapshot(cloudSnapshot, "云端快照")
                            if applied then
                                if IsSaveSnapshotMeaningful(cloudSnapshot) then
                                    lastKnownGoodCloudSnapshot = cloudSnapshot
                                end
                                values = {
                                    save_blob = cloudSnapshot,
                                    save_blob_backup = backupCloudSnapshot,
                                }
                                iscores = {}
                            end
                        end
                        if iscores.gold ~= nil then playerData.gold = iscores.gold end
                        if iscores.total_gold_earned ~= nil then playerData.totalGoldEarned = math.max(playerData.totalGoldEarned or 0, iscores.total_gold_earned, playerData.gold or 0) end
                        if iscores.high_score ~= nil then playerData.highScore = iscores.high_score end
                        if iscores.total_kills ~= nil then playerData.totalKills = iscores.total_kills end
                        if iscores.play_count ~= nil then playerData.playCount = iscores.play_count end
                        if values.daily_speed_admin_grants then
                            MergeDailySpeedAdminGrants(values.daily_speed_admin_grants)
                        end
                        if values.admin_material_grant_claims then
                            MergeAdminMaterialGrantClaims(values.admin_material_grant_claims)
                        end
                        if values.admin_rebirth_stone_grant_claims then
                            MergeAdminRebirthStoneGrantClaims(values.admin_rebirth_stone_grant_claims)
                        end
                        if iscores.daily_speed_usage_seconds ~= nil then
                            ApplyDailySpeedQuotaValues(iscores.daily_speed_usage_seconds, values.daily_speed_usage_day, "云端字段")
                        end
                        if iscores.total_play_time ~= nil then SetPlayTimeFromLoadedValue(iscores.total_play_time, iscores.play_time_clock_version or 0, playerData.settings) end
                        if iscores.best_floor ~= nil then playerData.bestFloor = iscores.best_floor end
                        if iscores.normal_highest_cleared_floor ~= nil then
                            playerData.normalHighestClearedFloor = math.max(
                                playerData.normalHighestClearedFloor or 0,
                                math.floor(tonumber(iscores.normal_highest_cleared_floor) or 0)
                            )
                        end
                        if iscores.rebirth_unlocked ~= nil then
                            playerData.rebirthUnlocked = playerData.rebirthUnlocked == true
                                or math.floor(tonumber(iscores.rebirth_unlocked) or 0) == 1
                        end
                        if iscores.rebirth_run_active ~= nil then
                            playerData.rebirthRunActive =
                                math.floor(tonumber(iscores.rebirth_run_active) or 0) == 1
                        end
                        if iscores.endless_best_floor ~= nil then
                            playerData.endlessBestFloor = math.max(
                                playerData.endlessBestFloor or 0,
                                math.floor(tonumber(iscores.endless_best_floor) or 0)
                            )
                        end
                        if type(values.endless_run_state) == "table" then
                            local localRun = type(playerData.endlessRunState) == "table"
                                and playerData.endlessRunState or {}
                            if math.floor(tonumber(values.endless_run_state.runId) or 0)
                                >= math.floor(tonumber(localRun.runId) or 0) then
                                playerData.endlessRunState = values.endless_run_state
                            end
                        end
                        NormalizeProgressionData()
                        if iscores.current_floor ~= nil then playerData.currentFloor = iscores.current_floor end
                        playerData.nextBaseHpRatio = nil
                        playerData.selectedStartFloor = 0
                        if iscores.rebirth_count ~= nil then playerData.rebirthCount = iscores.rebirth_count end
                        if iscores.rebirth_upgrade_count ~= nil then
                            local cloudCnt = math.max(0, math.floor(tonumber(iscores.rebirth_upgrade_count) or 0))
                            local localCnt = math.max(0, math.floor(tonumber(playerData.rebirthUpgradeCount) or 0))
                            if cloudCnt > localCnt then
                                playerData.rebirthUpgradeCount = cloudCnt
                            elseif cloudCnt < localCnt then
                                print("[Cloud] iscores 强化次数(", cloudCnt, ")低于本地(", localCnt, ")，保留本地")
                            end
                        end
                        if iscores.skip_level_upgrade_level ~= nil then
                            local cloudLv = math.max(0, math.floor(tonumber(iscores.skip_level_upgrade_level) or 0))
                            local localLv = math.max(0, math.floor(tonumber(playerData.skipLevelUpgradeLevel) or 0))
                            if cloudLv > localLv then playerData.skipLevelUpgradeLevel = cloudLv end
                        end
                        if iscores.skip_level_enabled ~= nil then
                            playerData.skipLevelEnabled = (tonumber(iscores.skip_level_enabled) or 1) == 1
                        end
                        if iscores.skill_damage_upgrade_level ~= nil then
                            local cloudLv = math.max(0, math.floor(tonumber(iscores.skill_damage_upgrade_level) or 0))
                            local localLv = math.max(0, math.floor(tonumber(playerData.skillDamageUpgradeLevel) or 0))
                            if cloudLv > localLv then playerData.skillDamageUpgradeLevel = cloudLv end
                        end
                        if iscores.clone_crit_upgrade_level ~= nil then
                            local cloudLv = math.max(0, math.floor(tonumber(iscores.clone_crit_upgrade_level) or 0))
                            local localLv = math.max(0, math.floor(tonumber(playerData.cloneCritUpgradeLevel) or 0))
                            if cloudLv > localLv then playerData.cloneCritUpgradeLevel = cloudLv end
                        end
                        if iscores.unlocked_skill_slots ~= nil then playerData.unlockedSkillSlots = iscores.unlocked_skill_slots end
                        if iscores.next_skill_uid ~= nil then playerData.nextSkillUid = iscores.next_skill_uid end
                        if iscores.rebirth_stone ~= nil then playerData.rebirthStone = iscores.rebirth_stone end
                        if iscores.rebirth_stone_best_claim_floor ~= nil then playerData.rebirthStoneBestClaimFloor = iscores.rebirth_stone_best_claim_floor end
                        ApplyDailyRebirthStoneQuotaValues(
                            iscores.daily_rebirth_stone_earned,
                            values.daily_rebirth_stone_day,
                            "云端字段"
                        )
                        if iscores.rebirth_run_start_floor ~= nil then playerData.rebirthRunStartFloor = iscores.rebirth_run_start_floor end
                        if iscores.rebirth_run_completed_floors ~= nil then playerData.rebirthRunCompletedFloors = iscores.rebirth_run_completed_floors end
                        if iscores.rebirth_run_skipped_floors ~= nil then playerData.rebirthRunSkippedFloors = iscores.rebirth_run_skipped_floors end
                        if values.roguelike_run_state ~= nil then
                            local legacyClassId = type(values.settings) == "table"
                                and values.settings.selectedClassId or nil
                            RestoreRoguelikeRunState(values.roguelike_run_state, legacyClassId)
                        end
                        if values.offline_climb_state ~= nil then
                            playerData.offlineClimbState = MergeOfflineClimbStates(
                                playerData.offlineClimbState,
                                values.offline_climb_state
                            )
                        end
                        if iscores.active_equipment_set_index ~= nil then playerData.activeEquipmentSetIndex = iscores.active_equipment_set_index end
                        if iscores.clone_count ~= nil then playerData.cloneCount = iscores.clone_count end
                        if values.equipment then
                            MaybeSetLegacyEquipment(values.equipment, "cloud.equipment")
                        end
                        if values.equipment_sets then
                            playerData.equipmentSets = values.equipment_sets
                        elseif values.equipment then
                            playerData.equipment = values.equipment
                        end
                        if values.inventory then
                            playerData.inventory = values.inventory
                        end
                        NormalizeEquipment()
                        if values.skills then
                            playerData.skills = values.skills
                        end
                        if values.skill_fragments ~= nil then
                            playerData.skillFragments = values.skill_fragments
                        end
                        if values.skill_slots then
                            playerData.skillSlots = values.skill_slots
                        end
                        if values.skill_loadouts then
                            playerData.skillLoadouts = values.skill_loadouts
                        end
                        if values.skill_synergy then
                            playerData.skillSynergy = MergeSkillSynergyData(playerData.skillSynergy, values.skill_synergy)
                        end
                        if values.active_skill_loadout_index ~= nil then
                            playerData.activeSkillLoadoutIndex = values.active_skill_loadout_index
                        end
                        if values.clone_unlocked ~= nil then
                            playerData.cloneUnlocked = values.clone_unlocked == true
                        end
                        if values.clone_upgrade_levels ~= nil then
                            local localLevels = playerData.cloneUpgradeLevels
                            if type(localLevels) ~= "table" then localLevels = {} end
                            local incoming = values.clone_upgrade_levels
                            if type(incoming) == "table" then
                                for i = 1, math.max(#localLevels, #incoming) do
                                    local localLv = math.max(0, math.floor(tonumber(localLevels[i]) or 0))
                                    local cloudLv = math.max(0, math.floor(tonumber(incoming[i]) or 0))
                                    localLevels[i] = math.max(localLv, cloudLv)
                                end
                                playerData.cloneUpgradeLevels = localLevels
                            end
                        elseif values.clone_upgrade_level ~= nil then
                            local localLv = math.max(0, math.floor(tonumber((playerData.cloneUpgradeLevels or {})[1]) or
                                                                       tonumber(playerData.cloneUpgradeLevel) or 0))
                            local cloudLv = math.max(0, math.floor(tonumber(values.clone_upgrade_level) or 0))
                            if cloudLv > localLv then
                                playerData.cloneUpgradeLevels = nil
                                playerData.cloneUpgradeLevel = values.clone_upgrade_level
                            end
                        end
                        if values.clone_protocols ~= nil then
                            playerData.cloneProtocols = NormalizeCloneProtocolsData(values.clone_protocols)
                        end
                        NormalizeCloneUpgradeLevels()
                        NormalizeCloneProtocols()
                        NormalizeSkills()
                        NormalizeSkillFragments()
                        NormalizeSkillLoadouts()
                        if values.settings then
                            playerData.settings = MergeSpeedAdUnlockSettings(values.settings)
                        end
                        if values.used_start_floors then
                            playerData.usedStartFloors = values.used_start_floors
                        end
                        if values.offline_climb_state ~= nil then
                            playerData.offlineClimbState = MergeOfflineClimbStates(
                                playerData.offlineClimbState,
                                values.offline_climb_state
                            )
                        end
                        NormalizeEquipmentSettings()
                        NormalizeRebirthStoneSystem()
                        if values.redeemed_codes then
                            redeemedCodes = values.redeemed_codes
                        end
                        ApplyRedeemedCodeRewards()
                        SaveLocalSnapshot()
                        print("[Cloud] 数据加载完成, 金币:", playerData.gold, "最高分:", playerData.highScore, "背包数量:", #playerData.inventory)
                    end
                else
                    NormalizeEquipment()
                    NormalizeEquipmentSettings()
                    NormalizeRebirthStoneSystem()
                    if KeepCloudWriteReadyIfLocalProgress("cloud_empty_keep_local") then
                        print("[Cloud] 云端为空，保留本地快照并回写云端")
                        SaveCloudData(true)
                    else
                        cloudDataLoaded = true
                        cloudDataReadyForSave = false
                        cloudSyncLastError = "核心读取成功，但没有找到可用云快照或本地备份"
                        print("[Cloud] 现有账号未取得可用云存档且无本地备份，保持只读")
                        FinishCloudDataFetch(false, "cloud_snapshot_missing")
                        return
                    end
                end
                ApplyRebirthBonuses()
                NormalizeUsedStartFloors()
                playerData.currentFloor = math.max(1, playerData.currentFloor or playerData.bestFloor or 1)
                playerData.selectedStartFloor = 0
                cloudDataLoaded = true
                cloudDataReadyForSave = true
                ResolvePendingEquipmentUpgradePenaltyOnLoad()
                EnsureRunSkillSynergies(false)
                ResolveInterruptedEndlessRun()
                ResumeOfflineClimbAndPersist("cloud_sync")
                if currentScreen == "subpage" and currentSubPage == "leaderboard" and ShowLeaderboardPage ~= nil then
                    ShowLeaderboardPage()
                end
                if currentScreen == "roguelike" and ResumePendingRoguelikeChoice ~= nil then
                    ResumePendingRoguelikeChoice()
                elseif currentScreen == "subpage" and currentSubPage == "equip" and ShowEquipmentPage ~= nil then
                    ShowEquipmentPage()
                elseif currentScreen == "subpage" and currentSubPage == "rebirth" and ShowRebirthPage ~= nil then
                    print("[Cloud] 永久强化数据已同步，刷新强化页面")
                    ShowRebirthPage()
                end
                if targetedRepairNeeded then
                    print("[TargetedInventoryRepair] 回写定向修复后的云端与本地存档")
                    SaveCloudData(true)
                elseif playTimeMigrationDirty then
                    print("[PlayTime] 回写校正后的历史游戏时长")
                    SaveCloudData(true)
                end
                FinishCloudDataFetch(true)
            end,
            error = function(code, reason)
                ApplyRebirthBonuses()
                cloudDataLoaded = true
                -- 已有本局进度时保持云写入开启，避免读失败后把后续存档全部关掉
                cloudDataReadyForSave = fetchHadWriteReady == true
                ResolvePendingEquipmentUpgradePenaltyOnLoad()
                print("[Cloud] 核心云档读取失败 keyCount=", #coreKeys,
                    "code=", tostring(code), "reason=", tostring(reason),
                    "keepWriteReady=", tostring(cloudDataReadyForSave))
                cloudSyncLastError = "核心读取 code=" .. tostring(code) .. " reason=" .. tostring(reason)
                if cloudDataReadyForSave and saveDirty then
                    SaveCloudData(true)
                    FinishCloudDataFetch(true)
                    return
                end
                FinishCloudDataFetch(false)
            end,
            timeout = function()
                ApplyRebirthBonuses()
                cloudDataLoaded = true
                cloudDataReadyForSave = fetchHadWriteReady == true
                ResolvePendingEquipmentUpgradePenaltyOnLoad()
                print("[Cloud] 核心云档读取超时 keyCount=", #coreKeys,
                    "keepWriteReady=", tostring(cloudDataReadyForSave))
                cloudSyncLastError = "核心读取超时 keyCount=" .. tostring(#coreKeys)
                if cloudDataReadyForSave and saveDirty then
                    SaveCloudData(true)
                    FinishCloudDataFetch(true)
                    return
                end
                FinishCloudDataFetch(false)
            end
        })
end

ADMIN_PUBLIC_PLAY_TIME_BONUS_SECONDS = 10 * 60 * 60
ADMIN_PUBLIC_KILL_BONUS = 50000
ADMIN_PUBLIC_PROFILE_VERSION = 4
ADMIN_PUBLIC_PROFILE_SYNCED_UID = ADMIN_PUBLIC_PROFILE_SYNCED_UID or nil
ADMIN_PUBLIC_PROFILE_SYNCED_VERSION = ADMIN_PUBLIC_PROFILE_SYNCED_VERSION or 0
PLAYER_PLATFORM_NICKNAME_CACHE = PLAYER_PLATFORM_NICKNAME_CACHE or ""
PLAYER_PLATFORM_NICKNAME_CACHE_UID = PLAYER_PLATFORM_NICKNAME_CACHE_UID or ""
PLAYER_PLATFORM_NICKNAME_CACHE_UPDATED_AT = PLAYER_PLATFORM_NICKNAME_CACHE_UPDATED_AT or 0
PLAYER_PLATFORM_NICKNAME_CACHE_QUERY_IN_FLIGHT = false

function RefreshCurrentPlayerNicknameCache()
    if not clientCloud or not cloudDataReadyForSave
        or PLAYER_PLATFORM_NICKNAME_CACHE_QUERY_IN_FLIGHT then return end
    local myUid = tostring(clientCloud.userId or "")
    if myUid == "" or PLAYER_PLATFORM_NICKNAME_CACHE_UID == myUid then return end
    PLAYER_PLATFORM_NICKNAME_CACHE_QUERY_IN_FLIGHT = true
    GetUserNickname({
        userIds = { myUid },
        onSuccess = function(nicknames)
            PLAYER_PLATFORM_NICKNAME_CACHE_QUERY_IN_FLIGHT = false
            for _, info in ipairs(nicknames or {}) do
                    if tostring(info.userId or "") == myUid then
                        local nickname = tostring(info.nickname or "")
                        if nickname == "" then
                            print("[LeaderboardNickname] 当前玩家昵称为空，允许下次重试")
                            return
                        end
                        PLAYER_PLATFORM_NICKNAME_CACHE_UID = myUid
                        if PLAYER_PLATFORM_NICKNAME_CACHE ~= nickname then
                            PLAYER_PLATFORM_NICKNAME_CACHE = nickname
                            PLAYER_PLATFORM_NICKNAME_CACHE_UPDATED_AT = os.time()
                            print("[LeaderboardNickname] 已更新当前玩家昵称缓存:", nickname)
                            SaveCloudData(true)
                        end
                        return
                    end
            end
        end,
        onError = function(errorCode)
            PLAYER_PLATFORM_NICKNAME_CACHE_QUERY_IN_FLIGHT = false
            print("[LeaderboardNickname] 当前玩家昵称查询失败:", tostring(errorCode))
        end,
    })
end

function IsConfirmedCloudAdminForPublicProfile()
    if not CLOUD_BANLIST_LOADED or not IS_CLOUD_ADMIN or not clientCloud or CLOUD_ADMIN_UID == nil then
        return false
    end
    local myUid = clientCloud.userId and tostring(clientCloud.userId) or ""
    return myUid ~= "" and tostring(CLOUD_ADMIN_UID) == myUid
end

function RefreshAdminPublicProfileIfNeeded()
    if not IsConfirmedCloudAdminForPublicProfile() or not cloudDataReadyForSave then return end
    local myUid = tostring(clientCloud.userId)
    if ADMIN_PUBLIC_PROFILE_SYNCED_UID == myUid
        and ADMIN_PUBLIC_PROFILE_SYNCED_VERSION == ADMIN_PUBLIC_PROFILE_VERSION then
        return
    end
    ADMIN_PUBLIC_PROFILE_SYNCED_UID = myUid
    ADMIN_PUBLIC_PROFILE_SYNCED_VERSION = ADMIN_PUBLIC_PROFILE_VERSION
    print("[AdminProfile] 刷新管理员公开展示资料，隐藏额外属性")
    SaveCloudData(true)
end

BuildPublicProfile = function()
    NormalizeEquipment()
    local stats = GetEquipmentStats()
    local equipmentSummary = {}
    local equipment = GetActiveEquipment()
    for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS) do
        local item = equipment[slotDef.id]
        if item then
            local affixTexts = {}
            for _, affix in ipairs(item.affixes or {}) do
                table.insert(affixTexts, MakeAffixDisplay(affix))
            end
            local upgradeLevel = nil
            if item.slot == "weapon" and item.weaponUpgradeLevel ~= nil then
                upgradeLevel = math.max(0, math.floor(item.weaponUpgradeLevel or 0))
            elseif item.slot == "armor" and item.armorUpgradeLevel ~= nil then
                upgradeLevel = math.max(0, math.floor(item.armorUpgradeLevel or 0))
            elseif item.slot == "boots" and item.bootsUpgradeLevel ~= nil then
                upgradeLevel = math.max(0, math.floor(item.bootsUpgradeLevel or 0))
            elseif item.slot == "gloves" and item.glovesUpgradeLevel ~= nil then
                upgradeLevel = math.max(0, math.floor(item.glovesUpgradeLevel or 0))
            elseif item.slot == "ring" and item.ringUpgradeLevel ~= nil then
                upgradeLevel = math.max(0, math.floor(item.ringUpgradeLevel or 0))
            end
            table.insert(equipmentSummary, {
                slot = slotDef.id,
                slotLabel = slotDef.label,
                name = item.name,
                quality = item.quality,
                floor = item.floor or 1,
                baseAffix = MakeAffixDisplay(item.baseAffix),
                affixes = affixTexts,
                score = GetEquipmentScore(item),
                upgradeLevel = upgradeLevel,
                resonanceSetId = GetEquipmentResonanceSetId(item),
            })
        else
            table.insert(equipmentSummary, {
                slot = slotDef.id,
                slotLabel = slotDef.label,
                name = "未装备",
                quality = "none",
                floor = 0,
                baseAffix = "",
                affixes = {},
                score = 0,
            })
        end
    end
    -- 管理员额外击杀/时长只给自己看，不写入公开资料。
    local publicTotalKills = playerData.totalKills or 0
    local publicTotalPlayTime = GetTotalPlayTimeForSave()
    return {
        version = ADMIN_PUBLIC_PROFILE_VERSION,
        nickname = PLAYER_PLATFORM_NICKNAME_CACHE,
        nicknameUpdatedAt = PLAYER_PLATFORM_NICKNAME_CACHE_UPDATED_AT,
        bestFloor = playerData.bestFloor or 0,
        normalHighestClearedFloor = GetNormalHighestClearedFloor(),
        endlessBestFloor = playerData.endlessBestFloor or 0,
        leaderboardProgressScore = GetLeaderboardProgressScore(),
        highScore = playerData.highScore or 0,
        totalKills = publicTotalKills,
        playCount = playerData.playCount or 0,
        totalPlayTime = publicTotalPlayTime,
        playTimeClockVersion = PLAY_TIME_CLOCK_VERSION_REAL,
        gold = playerData.gold or 0,
        totalGoldEarned = math.max(playerData.totalGoldEarned or 0, playerData.gold or 0),
        rebirthUpgradeCount = playerData.rebirthUpgradeCount or 0,
        skipLevelUpgradeLevel = playerData.skipLevelUpgradeLevel or 0,
        rebirthStone = playerData.rebirthStone or 0,
        rebirthStoneBestClaimFloor = playerData.rebirthStoneBestClaimFloor or 0,
        unlockedSkillSlots = playerData.unlockedSkillSlots or CONFIG.SkillSlotBaseCount,
        skillSlots = BuildSkillSlotsSaveData(),
        cloneUpgradeLevel = GetCloneUpgradeLevel(1),
        cloneUpgradeLevels = playerData.cloneUpgradeLevels or { 0, 0, 0 },
        cloneCount = playerData.cloneCount or 0,
        attack = GetHeroAttackDamage(),
        maxHp = GetBaseMaxHP(),
        critRate = stats.critRate or 0,
        critDamage = stats.critDamage or 0,
        attackSpeed = stats.attackSpeedPercent or 0,
        attackCount = GetHeroBaseAttackCount(),
        equipment = equipmentSummary,
    }
end

SaveCloudData = function(force)
    if not cloudDataReadyForSave then
        local pendingSnapshot = BuildSaveSnapshot()
        if localSaveLoaded or IsSaveSnapshotMeaningful(pendingSnapshot) then
            SaveLocalSnapshot(true, pendingSnapshot)
            print("[Cloud] 云档未就绪，仅保存已有/真实本地进度，跳过云端写入")
        else
            print("[Cloud] 云档未就绪且无有效本地进度，跳过全部写入")
        end
        return
    end
    if cloudSaveInProgress then
        cloudSaveQueued = true
        print("[Cloud] 保存进行中，加入待保存队列")
        return
    end
    if cloudSaveDeferred == true then
        -- 结算期延迟保存：只记脏并累计请求，由结算出口统一 flush。
        -- 避免连打结算（三选一/奖励发放）期间多次全量存档阻塞主线程。
        saveDirty = true
        cloudSaveDeferredCount = math.max(1, math.floor(cloudSaveDeferredCount or 0) + 1)
        -- 抗崩溃兜底：每若干次延迟写一次本地快照，避免结算中途被杀进程丢进度。
        -- 云存档仍由结算出口统一 flush，本地兜底不改变云存档数据一致性。
        if math.floor(cloudSaveDeferredCount) % (CLOUD_DEFER_LOCAL_EVERY or 5) == 0 then
            if SaveLocalSnapshot ~= nil then
                SaveLocalSnapshot()
                print("[Cloud] 结算期延迟保存第" .. tostring(cloudSaveDeferredCount) .. "次，已本地快照兜底")
            end
        end
        print("[Cloud] 结算期保存已延迟，累计挂起请求:", cloudSaveDeferredCount)
        return
    end
    if not force and not saveDirty then
        return
    end

    local syncStartedClock = os.clock()
    local snapshot = BuildSaveSnapshot()
    local publicProfile = BuildPublicProfile()
    snapshot._blob_hash = ComputeCloudBlobHash(snapshot)
    local snapshotMeaningful = IsSaveSnapshotMeaningful(snapshot)
    if not snapshotMeaningful
        and IsSaveSnapshotMeaningful(lastKnownGoodCloudSnapshot) then
        saveDirty = true
        SaveLocalSnapshot(true, lastKnownGoodCloudSnapshot)
        print("[CloudGuard] 拒绝用异常全空快照覆盖最后有效云存档")
        return
    end
    local backupSnapshot = IsSaveSnapshotMeaningful(lastKnownGoodCloudSnapshot)
        and lastKnownGoodCloudSnapshot or snapshot
    SaveLocalSnapshot(false, snapshot)
    playTimeMigrationDirty = false

    saveDirty = false
    cloudSaveInProgress = true
    inFlightSaveVersion = saveVersion or 0
    inFlightManualSaveRevision = manualSaveRevision or 0
    cloudSaveQueued = false
    local rewardAdCount = GetDailyRewardAdClaimCount()
    local rewardAdDayKey = playerData.dailyRewardAdClaimDayKey or GetCurrentCstDayKey()
    local rewardAdLeaderboardKey = GetRewardAdDailyLeaderboardPlainKey(rewardAdDayKey)
    local dailyActiveDayKey = GetCurrentCstDayKey()
    local dailyActiveLeaderboardKey = GetDailyActiveLeaderboardPlainKey(dailyActiveDayKey)
    local cloudRequest = OfficialBatchSet()
        :SetInt("gold", playerData.gold)
        :SetInt("total_gold_earned", math.max(playerData.totalGoldEarned or 0, playerData.gold or 0))
        :SetInt("high_score", playerData.highScore)
        :SetInt("total_kills", playerData.totalKills)
        :SetInt("play_count", playerData.playCount)
        :SetInt("total_play_time", GetTotalPlayTimeForSave())
        :SetInt("daily_speed_usage_seconds", GetDailySpeedUsageForSave())
        :Set("daily_speed_usage_day", playerData.dailySpeedUsageDayKey or GetCurrentCstDayKey())
        :SetInt("daily_speed_ad_claim_count", GetDailySpeedAdClaimCount())
        :Set("daily_speed_ad_claim_day", playerData.dailySpeedAdClaimDayKey or GetCurrentCstDayKey())
        :SetInt("daily_reward_ad_claim_count", GetDailyRewardAdClaimCount())
        :Set("daily_reward_ad_claim_day", playerData.dailyRewardAdClaimDayKey or GetCurrentCstDayKey())
        :SetInt("daily_socket_puncher_ad_claim_count", GetDailySocketPuncherAdClaimCount())
        :Set("daily_socket_puncher_ad_claim_day", playerData.dailySocketPuncherAdClaimDayKey or GetCurrentCstDayKey())
        :SetInt("daily_equipment_upgrade_ad_claim_count", playerData.dailyEquipmentUpgradeAdClaimCount or 0)
        :Set("daily_equipment_upgrade_ad_claim_day", playerData.dailyEquipmentUpgradeAdClaimDayKey or GetCurrentCstDayKey())
        :Set("pending_equipment_upgrade_penalty", playerData.pendingEquipmentUpgradePenalty or {})
        :SetInt("equipment_upgrade_penalty_resolved_id", playerData.equipmentUpgradePenaltyResolvedId or 0)
        :SetInt("next_equipment_uid", playerData.nextEquipmentUid or 1)
        :Set("daily_speed_admin_grants", playerData.dailySpeedAdminGrants or {})
        :Set("admin_material_grant_claims", playerData.adminMaterialGrantClaims or {})
        :Set("admin_rebirth_stone_grant_claims", playerData.adminRebirthStoneGrantClaims or {})
        :SetInt("daily_speed_quota_version", DAILY_SPEED_QUOTA_VERSION)
        :SetInt("play_time_clock_version", PLAY_TIME_CLOCK_VERSION_REAL)
        :SetInt("best_floor", playerData.bestFloor or 0)
        :SetInt("normal_highest_cleared_floor", GetNormalHighestClearedFloor())
        :SetInt("rebirth_unlocked", playerData.rebirthUnlocked == true and 1 or 0)
        :SetInt("rebirth_run_active", playerData.rebirthRunActive == true and 1 or 0)
        :SetInt("endless_best_floor", playerData.endlessBestFloor or 0)
        :Set("endless_run_state", playerData.endlessRunState)
        :SetInt("leaderboard_best_floor", GetLeaderboardProgressScore())
        :SetInt("current_floor", playerData.currentFloor or math.max(1, playerData.bestFloor or 0))
        :Set("offline_climb_state", playerData.offlineClimbState)
        :SetInt("rebirth_count", playerData.rebirthCount)
        :SetInt("rebirth_upgrade_count", playerData.rebirthUpgradeCount)
        :SetInt("rebirth_upgrade_reset_id", playerData.rebirthUpgradeResetId or 0)
        :SetInt("skip_level_upgrade_level", playerData.skipLevelUpgradeLevel or 0)
        :SetInt("skip_level_enabled", playerData.skipLevelEnabled == true and 1 or 0)
        :SetInt("skill_damage_upgrade_level", playerData.skillDamageUpgradeLevel or 0)
        :SetInt("clone_crit_upgrade_level", playerData.cloneCritUpgradeLevel or 0)
        :SetInt("rebirth_stone", playerData.rebirthStone or 0)
        :SetInt("rebirth_stone_best_claim_floor", playerData.rebirthStoneBestClaimFloor or 0)
        :SetInt("daily_rebirth_stone_earned", GetDailyRebirthStoneEarned())
        :Set("daily_rebirth_stone_day", playerData.dailyRebirthStoneDayKey or GetCurrentCstDayKey())
        :SetInt("daily_rebirth_stone_quota_version", DAILY_REBIRTH_STONE_QUOTA_VERSION)
        :SetInt("rebirth_run_start_floor", playerData.rebirthRunStartFloor or 1)
        :SetInt("rebirth_run_completed_floors", playerData.rebirthRunCompletedFloors or 0)
        :SetInt("rebirth_run_skipped_floors", playerData.rebirthRunSkippedFloors or 0)
        :Set("roguelike_run_state", BuildRoguelikeRunStateSaveData())
        :Set("equipment", GetActiveEquipment())
        :Set("equipment_sets", playerData.equipmentSets or {})
        :SetInt("active_equipment_set_index", GetActiveEquipmentSetIndex())
        :Set("inventory", playerData.inventory)
        :Set("skills", playerData.skills)
        :Set("skill_fragments", playerData.skillFragments)
        :Set("skill_slots", BuildSkillSlotsSaveData())
        :Set("skill_loadouts", BuildSkillLoadoutsSaveData())
        :Set("skill_synergy", NormalizeSkillSynergyData(playerData.skillSynergy))
        :SetInt("active_skill_loadout_index", playerData.activeSkillLoadoutIndex or 1)
        :SetInt("unlocked_skill_slots", playerData.unlockedSkillSlots or CONFIG.SkillSlotBaseCount)
        :SetInt("next_skill_uid", playerData.nextSkillUid or 1)
        :Set("clone_unlocked", playerData.cloneUnlocked == true)
        :SetInt("clone_count", playerData.cloneCount or 0)
        :SetInt("clone_upgrade_level", GetCloneUpgradeLevel(1))
        :Set("clone_upgrade_levels", playerData.cloneUpgradeLevels or { 0, 0, 0 })
        :Set("clone_protocols", NormalizeCloneProtocolsData(playerData.cloneProtocols))
        :Set("settings", playerData.settings)
        :Set("used_start_floors", playerData.usedStartFloors or {})
        :Set("redeemed_codes", redeemedCodes)
        :Set("public_profile", publicProfile)
        :Set("save_blob_backup", backupSnapshot)
        :Set("save_blob", snapshot)
    if rewardAdLeaderboardKey ~= nil and rewardAdCount > 0 then
        cloudRequest:SetInt(rewardAdLeaderboardKey, rewardAdCount)
        print("[RewardAdStats] 更新每日广告榜:", rewardAdDayKey, rewardAdCount)
    end
    if dailyActiveLeaderboardKey ~= nil and clientCloud ~= nil
        and clientCloud.userId ~= nil then
        cloudRequest:SetInt(dailyActiveLeaderboardKey, 1)
        print("[DailyStats] 更新每日活跃榜:", dailyActiveDayKey)
    end
    print("[Cloud] 全量存档同步耗时:",
        string.format("%.1fms", (os.clock() - syncStartedClock) * 1000))
    cloudRequest:Save("游戏存档", {
            ok = function()
                cloudSaveInProgress = false
                if snapshotMeaningful then
                    lastKnownGoodCloudSnapshot = snapshot
                end
                if manualSavePendingCloud
                    and (manualSaveRevision or 0) == (inFlightManualSaveRevision or 0) then
                    manualSavePendingCloud = false
                end
                if saveDirty ~= true
                    and (saveVersion or 0) == (inFlightSaveVersion or 0) then
                    saveDirty = false
                else
                    saveDirty = true
                end
                print("[Cloud] 数据保存成功, 背包数量:", #playerData.inventory,
                    "dirty=", tostring(saveDirty), "version=", tostring(saveVersion))
                reconnectAfterSave = false
                if saveDirty ~= true then
                    ResetCloudRetrySchedule()
                end
                if cloudSaveQueued then
                    cloudSaveQueued = false
                    SaveCloudData(true)
                end
            end,
            error = function(code, reason)
                cloudSaveInProgress = false
                saveDirty = true
                saveVersion = math.max(saveVersion or 0, inFlightSaveVersion or 0) + 1
                SaveLocalSnapshot()
                cloudSyncLastError = "云写入失败 code=" .. tostring(code) .. " reason=" .. tostring(reason)
                print("[Cloud] 保存失败:", reason, "queued=", cloudSaveQueued == true)
                cloudSaveQueued = false
                reconnectAfterSave = false
                ScheduleCloudRetry("cloud_save_failed", false)
            end,
            timeout = function()
                cloudSaveInProgress = false
                saveDirty = true
                saveVersion = math.max(saveVersion or 0, inFlightSaveVersion or 0) + 1
                SaveLocalSnapshot()
                cloudSyncLastError = "云写入超时"
                print("[Cloud] 保存超时, queued=", cloudSaveQueued == true)
                cloudSaveQueued = false
                reconnectAfterSave = false
                ScheduleCloudRetry("cloud_save_timeout", false)
            end
        })
end

-- 结算期云存档合并会话：BeginDeferredCloudSave 后 SaveCloudData(true) 只置脏，
-- EndDeferredCloudSave 时统一 flush 一次，避免连打结算（三选一/奖励发放）期间
-- 多次全量存档阻塞主线程。支持嵌套：深度归零时才真正 flush。
BeginDeferredCloudSave = function()
    cloudSaveDeferred = true
    cloudSaveDeferredDepth = math.max(0, math.floor(cloudSaveDeferredDepth or 0)) + 1
    print("[Cloud] 结算期延迟保存开启，深度:", cloudSaveDeferredDepth)
    return true
end

EndDeferredCloudSave = function()
    if cloudSaveDeferred ~= true or math.floor(cloudSaveDeferredDepth or 0) <= 0 then
        return false
    end
    cloudSaveDeferredDepth = math.max(0, math.floor(cloudSaveDeferredDepth or 1) - 1)
    if cloudSaveDeferredDepth > 0 then
        print("[Cloud] 结算期延迟保存嵌套，深度:", cloudSaveDeferredDepth, "暂不 flush")
        return false
    end
    cloudSaveDeferred = false
    local hadRequests = math.floor(cloudSaveDeferredCount or 0) > 0
    cloudSaveDeferredCount = 0
    print("[Cloud] 结算期延迟保存已结束，挂起请求:", hadRequests and "有" or "无")
    if hadRequests or saveDirty == true then
        SaveCloudData(true)
    end
    return true
end

function NormalizeAdminRebirthStoneGrantClaims()
    local claims = playerData.adminRebirthStoneGrantClaims
    if type(claims) ~= "table" then
        claims = {}
        playerData.adminRebirthStoneGrantClaims = claims
    end
    local count = 0
    for grantId, claimedAt in pairs(claims) do
        if tostring(grantId or "") == "" or type(claimedAt) ~= "number" then
            claims[grantId] = nil
        else
            count = count + 1
        end
    end
    if count > LOCAL_SAVE_SANITY_MAX.adminRebirthStoneGrantClaims then
        local keys = {}
        for grantId, claimedAt in pairs(claims) do
            table.insert(keys, { id = grantId, at = claimedAt })
        end
        table.sort(keys, function(a, b) return a.at > b.at end)
        for index = LOCAL_SAVE_SANITY_MAX.adminRebirthStoneGrantClaims + 1, #keys do
            claims[keys[index].id] = nil
        end
    end
end

function MergeAdminRebirthStoneGrantClaims(incoming)
    if type(incoming) ~= "table" then return false end
    NormalizeAdminRebirthStoneGrantClaims()
    local changed = false
    for grantId, claimedAt in pairs(incoming) do
        local key = tostring(grantId or "")
        local timestamp = math.floor(tonumber(claimedAt) or 0)
        if key ~= "" and timestamp > 0
            and playerData.adminRebirthStoneGrantClaims[key] == nil then
            playerData.adminRebirthStoneGrantClaims[key] = timestamp
            changed = true
        end
    end
    if changed then saveDirty = true end
    return changed
end

REAL_PROGRESS_REVISION = REAL_PROGRESS_REVISION or 0

function MarkPlayerProgressDirty()
    saveDirty = true
    saveVersion = (saveVersion or 0) + 1
    REAL_PROGRESS_REVISION = (REAL_PROGRESS_REVISION or 0) + 1
end

function MarkSaveDirty()
    MarkPlayerProgressDirty()
end

SyncRunningProgress = function()
end

function ScheduleCloudRetry(reason, immediate)
    if appIsInBackground then return end
    cloudRetryPending = true
    local retryReason = tostring(reason or "unknown")
    cloudSaveRetryOnly = retryReason == "cloud_save_failed"
        or retryReason == "cloud_save_timeout"
        or retryReason == "manual_save_waiting_cloud"
    if immediate then
        cloudRetryTimer = 0
    else
        cloudRetryTimer = math.max(0, cloudRetryDelay or CLOUD_RETRY_INITIAL_DELAY)
        cloudRetryDelay = math.min(
            CLOUD_RETRY_MAX_DELAY,
            math.max(CLOUD_RETRY_INITIAL_DELAY, cloudRetryDelay or CLOUD_RETRY_INITIAL_DELAY) * 2
        )
    end
    local isInitialSchedule = immediate == true and retryReason == "startup"
    if not isInitialSchedule and (cloudSyncLastError == nil or cloudSyncLastError == "") then
        cloudSyncLastError = "失败阶段: " .. retryReason
    end
    local retryText = "云同步失败，" .. tostring(math.floor(cloudRetryTimer)) .. " 秒后重试"
    if cloudSyncLastError ~= nil and cloudSyncLastError ~= "" then
        retryText = retryText .. "\n" .. cloudSyncLastError
    end
    cloudSyncStatusText = immediate and "云存档正在同步..." or retryText
    print("[Cloud] 已计划后台重试:", tostring(reason or "unknown"),
        "delay=", tostring(cloudRetryTimer), "detail=", tostring(cloudSyncLastError or ""))
    if currentScreen == "menu" and ShowMainMenu ~= nil then
        ShowMainMenu()
    end
end

function ResetCloudRetrySchedule()
    cloudRetryPending = false
    cloudRetryTimer = 0
    cloudRetryDelay = CLOUD_RETRY_INITIAL_DELAY
    cloudSaveRetryOnly = false
    cloudSyncStatusText = "云存档已同步"
    cloudSyncLastError = ""
    if currentScreen == "menu" and ShowMainMenu ~= nil then
        ShowMainMenu()
    end
end

function AutoSaveIfNeeded(force)
    CommitForegroundPlayTime()
    if currentScreen == "playing" then
        SyncRunningProgress()
    end
    if force or saveDirty then
        SaveCloudData(force == true)
    end
end

ReconnectCloudData = function(reason)
    if not clientCloud then
        KeepCloudWriteReadyIfLocalProgress("reconnect_client_cloud_nil")
        if not cloudDataReadyForSave then
            cloudDataReadyForSave = false
        end
        cloudSyncLastError = "云组件未初始化 clientCloud=nil"
        cloudSyncStatusText = "云存档组件未初始化，等待重试"
        print("[Cloud] clientCloud=nil，跳过完整云档读取")
        ScheduleCloudRetry("client_cloud_nil", false)
        return
    end
    if reconnectInProgress or CLOUD_DATA_FETCH_IN_PROGRESS then return end
    if cloudSaveInProgress then
        reconnectAfterSave = true
        print("[Cloud] 保存未完成，延后重新同步")
        return
    end
    if cloudDataReadyForSave and saveDirty then
        reconnectAfterSave = true
        AutoSaveIfNeeded(true)
        return
    end
    reconnectInProgress = true
    cloudSyncStatusText = "正在读取云存档..."
    if currentScreen == "menu" and ShowMainMenu ~= nil then
        ShowMainMenu()
    end
    print("[Cloud] 开始重新同步:", reason or "resume",
        "writeReady=", tostring(cloudDataReadyForSave))
    LoadCloudData(function(success, failureReason)
        reconnectInProgress = false
        if success then
            ResetCloudRetrySchedule()
            print("[Cloud] 重新同步完成")
            if LoadCloudBanlist ~= nil then
                LoadCloudBanlist(function(banlistLoaded)
                    if banlistLoaded and RefreshLeaderboardFirstWingEligibility ~= nil then
                        RefreshLeaderboardFirstWingEligibility(true)
                    end
                    -- 非管理员重连成功后立即补领一次，不必等 60 秒轮询
                    if not IS_CLOUD_ADMIN and PollAdminGrantsForNormalPlayer ~= nil then
                        ADMIN_GRANT_POLL_TIMER = 0
                        PollAdminGrantsForNormalPlayer()
                    end
                end)
            end
            if saveDirty then
                SaveCloudData(true)
            end
            if currentScreen == "menu" then
                GameEvents.Emit("scene:main")
            end
        else
            print("[Cloud] 重新同步失败:", tostring(failureReason or cloudSyncLastError or "unknown"))
            ScheduleCloudRetry(failureReason or "reconnect_failed", false)
        end
    end)
end

function BeginCloudRecovery(reason)
    if clientCloud == nil then
        KeepCloudWriteReadyIfLocalProgress("recovery_client_cloud_nil")
        if not cloudDataReadyForSave then
            cloudDataReadyForSave = false
        end
        cloudSyncLastError = "云组件未初始化 clientCloud=nil"
        cloudSyncStatusText = "云存档组件未初始化，等待重试"
        print("[Cloud] BeginCloudRecovery 检测到 clientCloud=nil")
        ScheduleCloudRetry("client_cloud_nil", false)
        return
    end
    if cloudPrepareInProgress or reconnectInProgress
        or CLOUD_DATA_FETCH_IN_PROGRESS then return end
    if not dataResetComplete then
        cloudPrepareInProgress = true
        cloudSyncStatusText = "正在校验云存档..."
        if currentScreen == "menu" and ShowMainMenu ~= nil then
            ShowMainMenu()
        end
        print("[Cloud] 开始正式档检查:", tostring(reason or "retry"))
        PrepareFreshData(function(success, alreadyClean)
            cloudPrepareInProgress = false
            if not success then
                if not KeepCloudWriteReadyIfLocalProgress("recovery_prepare_failed") then
                    cloudDataReadyForSave = false
                end
                if cloudSyncLastError == nil or cloudSyncLastError == "" then
                    cloudSyncLastError = "正式档检查失败，未返回具体错误码"
                end
                print("[Cloud] 正式档检查失败，继续本地运行")
                if cloudDataReadyForSave then
                    SaveCloudData(true)
                    ResetCloudRetrySchedule()
                    return
                end
                ScheduleCloudRetry("prepare_failed", false)
                return
            end
            if not alreadyClean then
                ResetCloudRetrySchedule()
                if LoadCloudBanlist ~= nil then
                    LoadCloudBanlist(function(banlistLoaded)
                        if banlistLoaded and RefreshLeaderboardFirstWingEligibility ~= nil then
                            RefreshLeaderboardFirstWingEligibility(true)
                        end
                    end)
                end
                return
            end
            ReconnectCloudData(reason or "after_prepare")
        end)
        return
    end
    ReconnectCloudData(reason or "retry")
end

function HandleEnterBackground(eventType, eventData)
    if appIsInBackground then return end
    CommitForegroundPlayTime()
    StartOfflineClimbIfEligible("background")
    appIsInBackground = true
    print("[App] 进入后台，执行自动存档")
    -- 若正处于结算期云存档延迟合并中，切后台前强制 flush，
    -- 保证后台/被杀进程时结算数据已落盘。
    if EndDeferredCloudSave ~= nil then
        EndDeferredCloudSave()
    end
    AutoSaveIfNeeded(true)
end

function HandleEnterForeground(eventType, eventData)
    if not appIsInBackground then return end
    ResetDailySpeedClockRuntime()
    local _, _, hadTask = ResumeOfflineClimbAndPersist(
        "foreground"
    )
    appIsInBackground = false
    print("[App] 回到前台，重新同步云存档")
    -- 非管理员回到前台时立即补领一次管理员发放，不必等 60 秒轮询
    ADMIN_GRANT_POLL_TIMER = 0
    if not hadTask then
        ScheduleCloudRetry("foreground", true)
    end
end

function GetMonsterImageCategory(monsterType)
    if monsterType == "splitter" then
        return "slime"
    elseif monsterType == "ranged" then
        return "ranged"
    elseif monsterType == "blood" then
        return "blood"
    elseif monsterType == "treasure" or monsterType == "skill_treasure" then
        return nil
    end
    return monsterType or "normal"
end

function IsTreasureMonsterType(monsterType)
    return monsterType == "treasure" or monsterType == "skill_treasure"
end

monsterSpawnOccupiedSlots = {}

function RefillMonsterImageBag(category)
    local list = monsterImages and monsterImages[category] or nil
    local bag = {}
    if list ~= nil then
        for i = 1, #list do
            bag[i] = list[i]
        end
    end
    for i = #bag, 2, -1 do
        local j = math.random(1, i)
        bag[i], bag[j] = bag[j], bag[i]
    end
    monsterImageBags = monsterImageBags or {}
    monsterImageBags[category] = bag
    return bag
end

function PickMonsterImage(category)
    if category == nil then return 0 end
    local list = monsterImages and monsterImages[category] or nil
    if list == nil or #list == 0 then
        if category ~= "normal" then
            return PickMonsterImage("normal")
        end
        return 0
    end

    monsterImageBags = monsterImageBags or {}
    local bag = monsterImageBags[category]
    if bag == nil or #bag == 0 then
        bag = RefillMonsterImageBag(category)
    end
    if bag ~= nil and #bag > 0 then
        return table.remove(bag)
    end
    return 0
end

function GetFloorMonsterCount(floor)
    floor = math.max(1, floor)
    local fiveFloorBonus = math.floor((floor - 1) / CONFIG.FloorMonsterGrowthStep) * CONFIG.FloorMonsterGrowthAmount
    local tenFloorBonus = math.floor((floor - 1) / CONFIG.FloorMonsterBonusStep) * CONFIG.FloorMonsterBonusAmount
    return CONFIG.FloorBaseMonsterCount + fiveFloorBonus + tenFloorBonus
end

function AddPlannedMonster(plan, preferredIndex, monsterType)
    local count = #plan
    for offset = 0, count - 1 do
        local index = ((preferredIndex + offset - 1) % count) + 1
        if plan[index] == "normal" then
            plan[index] = monsterType
            return true
        end
    end
    return false
end

function RollTreasureCount()
    local roll = math.random()
    local accumulatedChance = 0
    local fallbackCount = 0
    for _, entry in ipairs(CONFIG.TreasureCountChances or {}) do
        local count = math.max(0, math.floor(entry.count or 0))
        fallbackCount = count
        accumulatedChance = accumulatedChance + math.max(0, entry.chance or 0)
        if roll < accumulatedChance then
            return math.min(CONFIG.TreasureMaxPerFloor or 4, count)
        end
    end
    return math.min(CONFIG.TreasureMaxPerFloor or 4, fallbackCount)
end

function RollSkillTreasureCount()
    local roll = math.random()
    local accumulatedChance = 0
    local fallbackCount = 0
    for _, entry in ipairs(CONFIG.SkillTreasureCountChances or {}) do
        local count = math.max(0, math.floor(entry.count or 0))
        fallbackCount = count
        accumulatedChance = accumulatedChance + math.max(0, entry.chance or 0)
        if roll < accumulatedChance then
            return math.min(CONFIG.SkillTreasureMaxPerFloor or 2, count)
        end
    end
    return math.min(CONFIG.SkillTreasureMaxPerFloor or 2, fallbackCount)
end

function BuildSingleFloorSpawnPlan(floor)
    local planFloor = floor
    local rewardFloor = endlessTrialActive and (
        1000000 + math.max(
            CONFIG.EndlessStartFloor or 600,
            math.floor(runFloor or floor or 600)
        )
    ) or floor
    local count = GetFloorMonsterCount(floor)
    local plan = {}
    for i = 1, count do
        plan[i] = "normal"
    end

    local eliteCount = 0
    for i = CONFIG.EliteEveryMonsters, count, CONFIG.EliteEveryMonsters do
        if AddPlannedMonster(plan, i, "elite") then
            eliteCount = eliteCount + 1
        end
    end
    local splitterCount = 0
    for i = CONFIG.SplitterEveryMonsters, count, CONFIG.SplitterEveryMonsters do
        if AddPlannedMonster(plan, i, "splitter") then
            splitterCount = splitterCount + 1
        end
    end
    for i = CONFIG.RangedEveryMonsters, count, CONFIG.RangedEveryMonsters do
        AddPlannedMonster(plan, i, "ranged")
    end
    for i = CONFIG.BloodEveryMonsters, count, CONFIG.BloodEveryMonsters do
        AddPlannedMonster(plan, i, "blood")
    end

    local treasureCount = 0
    local skillTreasureCount = 0
    local treasureMax = (trainingModeActive or equipmentRiftActive) and 0 or (CONFIG.TreasureMaxPerFloor or 4)
    local skillTreasureMax = (trainingModeActive or equipmentRiftActive) and 0 or (CONFIG.SkillTreasureMaxPerFloor or 2)
    local plannedTreasureCount = (trainingModeActive or equipmentRiftActive) and 0
        or (GetTreasurePlannedCount and GetTreasurePlannedCount(planFloor) or nil)
    local plannedSkillTreasureCount = (trainingModeActive or equipmentRiftActive) and 0
        or (GetSkillTreasurePlannedCount and GetSkillTreasurePlannedCount(planFloor) or nil)
    if plannedTreasureCount ~= nil then
        local remaining = math.max(0, math.floor(plannedTreasureCount) - GetTreasureConsumedCount(rewardFloor))
        if remaining > 0 then
            local normalIndices = {}
            for i = 1, count do
                if plan[i] == "normal" then table.insert(normalIndices, i) end
            end
            for index = 1, math.min(remaining, #normalIndices) do
                plan[normalIndices[index]] = "treasure"
                treasureCount = treasureCount + 1
            end
        end
    elseif treasureMax > 0 then
        local targetTreasureCount = math.min(treasureMax, RollTreasureCount())
        local normalIndices = {}
        for i = 1, count do
            if plan[i] == "normal" then table.insert(normalIndices, i) end
        end
        for index = #normalIndices, 2, -1 do
            local swapIndex = math.random(1, index)
            normalIndices[index], normalIndices[swapIndex] = normalIndices[swapIndex], normalIndices[index]
        end
        for index = 1, math.min(targetTreasureCount, #normalIndices) do
            plan[normalIndices[index]] = "treasure"
            treasureCount = treasureCount + 1
        end
        if SetTreasurePlannedCount ~= nil then SetTreasurePlannedCount(planFloor, treasureCount) end
    end

    if plannedSkillTreasureCount ~= nil then
        local requiredCount = math.max(0, math.floor(plannedSkillTreasureCount))
        if floor == 1 and not trainingModeActive then
            requiredCount = math.max(1, requiredCount)
            if requiredCount ~= plannedSkillTreasureCount
                and SetSkillTreasurePlannedCount ~= nil then
                SetSkillTreasurePlannedCount(planFloor, requiredCount)
            end
        end
        local remaining = math.max(0, requiredCount - GetSkillTreasureConsumedCount(rewardFloor))
        if remaining > 0 then
            local normalIndices = {}
            for i = 1, #plan do
                if plan[i] == "normal" then table.insert(normalIndices, i) end
            end
            for index = 1, math.min(remaining, #normalIndices) do
                plan[normalIndices[index]] = "skill_treasure"
                skillTreasureCount = skillTreasureCount + 1
            end
        end
    elseif skillTreasureMax > 0 then
        local targetSkillTreasureCount = math.min(skillTreasureMax, RollSkillTreasureCount())
        if floor == 1 and not trainingModeActive then
            targetSkillTreasureCount = math.max(1, targetSkillTreasureCount)
        end
        local normalIndices = {}
        for i = 1, #plan do
            if plan[i] == "normal" then table.insert(normalIndices, i) end
        end
        for index = #normalIndices, 2, -1 do
            local swapIndex = math.random(1, index)
            normalIndices[index], normalIndices[swapIndex] = normalIndices[swapIndex], normalIndices[index]
        end
        for index = 1, math.min(targetSkillTreasureCount, #normalIndices) do
            plan[normalIndices[index]] = "skill_treasure"
            skillTreasureCount = skillTreasureCount + 1
        end
        if SetSkillTreasurePlannedCount ~= nil then SetSkillTreasurePlannedCount(planFloor, skillTreasureCount) end
    end

    local replacementTarget = splitterCount * 12
    local normalIndices = {}
    for index, monsterType in ipairs(plan) do
        if monsterType == "normal" then
            table.insert(normalIndices, index)
        end
    end
    local replacementCount = math.min(replacementTarget, #normalIndices)
    if replacementCount > 0 then
        local removedIndices = {}
        for replacementIndex = 1, replacementCount do
            local normalPosition = math.floor(
                (replacementIndex - 0.5) * #normalIndices / replacementCount
            ) + 1
            removedIndices[normalIndices[normalPosition]] = true
        end

        local adjustedPlan = {}
        for index, monsterType in ipairs(plan) do
            if not removedIndices[index] then
                table.insert(adjustedPlan, monsterType)
            end
        end
        plan = adjustedPlan
    end

    local bossCount = math.max(1, math.floor(eliteCount / CONFIG.BossEveryElites))
    print("[Floor] 生成刷怪计划, 层数:", floor,
        "基础怪数:", count,
        "精英:", eliteCount,
        "分裂父怪:", splitterCount,
        "分裂后代替代普通怪:", replacementCount,
        "实际初始怪数:", #plan,
        "金币宝箱:", treasureCount,
        "技能宝箱:", skillTreasureCount,
        "Boss:", bossCount)
    return plan, bossCount
end

function BuildFloorSpawnPlan(floor)
    if equipmentRiftActive then
        return BuildEquipmentRiftSpawnPlan(floor)
    end
    local combinedPlan = {}
    local totalBossCount = 0
    floorBossSpawnPlan = {}
    floorBossSpawnIndex = 1

    local startFloor = math.max(1, math.floor(floor or 1))
    local battleFloorCount = fiveBattleActive and math.max(2, math.floor(fiveBattleFloorCount or 5)) or 1
    if endlessTrialActive then battleFloorCount = 1 end
    local endFloor = math.min(
        startFloor + battleFloorCount - 1,
        endlessTrialActive and startFloor or (CONFIG.NormalFloorCap or 600)
    )
    battleFloorCount = endFloor - startFloor + 1
    fiveBattleStartFloor = startFloor
    fiveBattleEndFloor = endFloor
    fiveBattleFloorCount = battleFloorCount

    for sourceFloor = startFloor, endFloor do
        local templateFloor = endlessTrialActive
            and (CONFIG.EndlessStartFloor or 600)
            or sourceFloor
        local plan, bossCount = BuildSingleFloorSpawnPlan(templateFloor)
        totalBossCount = totalBossCount + bossCount
        local treasureIndex = 0
        local skillTreasureIndex = 0
        for _, monsterType in ipairs(plan) do
            local entryRewardFloor = endlessTrialActive
                and (1000000 + sourceFloor)
                or sourceFloor
            local combinedEntry = {
                type = monsterType,
                floor = sourceFloor,
                spawnFloor = templateFloor,
                rewardFloor = entryRewardFloor,
            }
            if monsterType == "treasure" then
                treasureIndex = treasureIndex + 1
                combinedEntry.treasureIndex = GetTreasureConsumedCount(entryRewardFloor) + treasureIndex
            elseif monsterType == "skill_treasure" then
                skillTreasureIndex = skillTreasureIndex + 1
                combinedEntry.skillTreasureIndex = GetSkillTreasureConsumedCount(entryRewardFloor) + skillTreasureIndex
            end
            table.insert(combinedPlan, combinedEntry)
        end
        if fiveBattleActive then
            for bossIndex = 1, bossCount do
                table.insert(combinedPlan, { type = "boss", floor = sourceFloor, bossIndex = bossIndex, bossTotal = bossCount })
            end
        else
            for bossIndex = 1, bossCount do
                table.insert(floorBossSpawnPlan, { floor = sourceFloor, index = bossIndex, total = bossCount })
            end
        end
    end

    if fiveBattleActive then
        print("[MultiBattle] 生成" .. tostring(fiveBattleFloorCount) .. "连打计划, 层数:", startFloor, "-", endFloor, "怪物/Boss条目:", #combinedPlan, "Boss:", totalBossCount)
    end
    -- 连打计划可能跨多层，上面的 SetTreasurePlannedCount/SetSkillTreasurePlannedCount
    -- 只更新内存（置 saveDirty），此处仅在确实新增了规划时统一落盘一次，
    -- 避免每层同步全量写盘导致出发卡顿；已规划过的层重玩不写盘（维持原行为）。
    if roguelikeSpawnPlanDirty == true and PersistRoguelikeRunState ~= nil then
        roguelikeSpawnPlanDirty = false
        PersistRoguelikeRunState(false)
    end
    return combinedPlan, totalBossCount
end


function GetMonsterDifficultyScale(floor)
    floor = math.max(1, math.floor(floor or runFloor or 1))
    local floorIndex = math.max(0, floor - 1)
    local midFloor = math.max(0, floorIndex - 20)
    local endFloor = math.max(0, floorIndex - 50)
    local lateStep = math.floor(floorIndex / CONFIG.FloorLateHPGrowthStep)
    local lateScale = lateStep * lateStep * CONFIG.FloorLateHPGrowthScale
    return 1
        + gameTime * CONFIG.WaveDifficultyScale
        + floorIndex * CONFIG.FloorHPGrowthScale
        + midFloor * CONFIG.FloorMidHPGrowthScale
        + endFloor * endFloor * CONFIG.FloorEndHPGrowthScale
        + lateScale
end

function GetFloorDifficultyStepMultiplier(floor)
    floor = math.max(1, math.floor(floor or runFloor or 1))
    local startFloor = math.max(1, math.floor(CONFIG.FloorDifficultyStepStart or 50))
    local baseMultiplier = 1.0
    if floor >= startFloor then
        local interval = math.max(1, math.floor(CONFIG.FloorDifficultyStepInterval or 50))
        local completedSteps = math.floor((floor - startFloor) / interval) + 1
        baseMultiplier = 1 + completedSteps * (CONFIG.FloorDifficultyBonusPerStep or 0.05)
    end

    local extraStartFloor = math.max(1, math.floor(CONFIG.FloorExtraDifficultyStepStart or 100))
    local extraMultiplier = 1.0
    if floor >= extraStartFloor then
        local extraInterval = math.max(1, math.floor(CONFIG.FloorExtraDifficultyStepInterval or 100))
        local completedExtraSteps = math.floor((floor - extraStartFloor) / extraInterval) + 1
        extraMultiplier = 1 + completedExtraSteps * (CONFIG.FloorExtraDifficultyBonusPerStep or 0.05)
    end

    return baseMultiplier * extraMultiplier
end

function GetMonsterSpeedScale(floor)
    floor = math.max(1, math.floor(floor or runFloor or 1))
    local floorIndex = math.max(0, floor - 1)
    return math.min(2.6, 1 + floorIndex * CONFIG.FloorSpeedGrowthScale)
end

function GetMonsterDamageScale(floor)
    floor = math.max(1, math.floor(floor or runFloor or 1))
    local floorIndex = math.max(0, floor - 1)
    local endFloor = math.max(0, floorIndex - 40)
    return 1 + floorIndex * CONFIG.FloorDamageGrowthScale + endFloor * 0.02
end

function GetMonsterBaseAttackCooldown(floor)
    floor = math.max(1, math.floor(floor or runFloor or 1))
    if floor >= 500 then return 0.80 end
    if floor >= 300 then return 0.85 end
    if floor >= 200 then return 0.90 end
    if floor >= 100 then return 0.95 end
    return CONFIG.MonsterBaseAttackCooldown or 1.0
end

function GetBossLateHPMult(floor)
    floor = math.max(1, math.floor(floor or runFloor or 1))
    local startFloor = math.max(1, math.floor(CONFIG.BossLateScaleStartFloor or 100))
    local lateFloor = math.max(0, floor - startFloor)
    return 1 + lateFloor * (CONFIG.BossLateHPMultPerFloor or 0.006)
end

function GetBossLateDamageMult(floor)
    local hpMult = GetBossLateHPMult(floor)
    return 1 + (hpMult - 1) * (CONFIG.BossLateDamageScaleRatio or 0.25)
end

function IsHardFloor(floor)
    floor = math.max(1, math.floor(floor or runFloor or 1))
    local interval = math.max(1, math.floor(CONFIG.HardFloorInterval or 50))
    return floor >= interval and floor % interval == 0
end

function RollMonsterBuff(monsterType, floor)
    floor = math.max(1, math.floor(floor or runFloor or 1))
    if trainingModeActive
        or monsterType == "treasure"
        or monsterType == "skill_treasure" then
        return nil
    end
    local buffs = CONFIG.BossBuffs or {}
    if #buffs <= 0 then return nil end
    local chance = nil
    if IsHardFloor(floor) then
        chance = CONFIG.HardFloorBuffChance or 0.80
    elseif monsterType == "boss"
        and floor >= (CONFIG.BossBuffStartFloor or 10) then
        chance = CONFIG.BossBuffChance or 0.40
    end
    if chance == nil
        or math.random() >= math.max(0, math.min(1, chance)) then
        return nil
    end
    return buffs[math.random(1, #buffs)]
end

function RollBossBuff(floor)
    return RollMonsterBuff("boss", floor)
end

function IsBossShieldActive(monster)
    if monster == nil or monster.bossBuff == nil or monster.bossBuff.id ~= "shield" then return false end
    local interval = monster.bossBuff.shieldInterval or 6.0
    local duration = monster.bossBuff.shieldDuration or 1.5
    if interval <= 0 or duration <= 0 then return false end
    local timer = monster.bossShieldTimer or 0
    return timer % interval < duration
end

function CreateMonster(
    monsterType,
    x,
    y,
    diffScale,
    splitDepth,
    sourceFloor,
    inheritedBuff,
    buffAlreadyResolved
)
    monsterType = monsterType or "normal"
    sourceFloor = math.max(1, math.floor(sourceFloor or runFloor or playerData.currentFloor or 1))
    diffScale = diffScale or GetMonsterDifficultyScale(sourceFloor)
    splitDepth = splitDepth or 0

    local hpMult = 1
    local speedMult = 1 + math.random() * 0.3
    local radius = 16 + math.random(-2, 2)
    local color = nil
    local damage = CONFIG.MonsterDamage
    local bossBuff = inheritedBuff
    if not buffAlreadyResolved then
        bossBuff = RollMonsterBuff(monsterType, sourceFloor)
    end

    if monsterType == "elite" then
        hpMult = CONFIG.EliteHPMult
        speedMult = 1
        radius = 24
        color = {255, 90, 45}
    elseif monsterType == "ranged" then
        hpMult = CONFIG.RangedHPMult
        speedMult = CONFIG.RangedSpeedMult
        radius = 16
        color = {70, 180, 255}
    elseif monsterType == "splitter" then
        hpMult = CONFIG.SplitterHPMult * (0.5 ^ splitDepth)
        speedMult = CONFIG.SplitterSpeedMult
        radius = math.max(16, 26 - splitDepth * 5)
        color = {180, 90, 255}
    elseif monsterType == "blood" then
        hpMult = CONFIG.BloodHPMult
        speedMult = CONFIG.BloodSpeedMult
        radius = 20
        color = {170, 25, 45}
    elseif monsterType == "treasure" or monsterType == "skill_treasure" then
        hpMult = CONFIG.TreasureHPMult or 5.0
        speedMult = CONFIG.TreasureSpeedMult or 0.45
        radius = CONFIG.TreasureRadius or 22
        color = monsterType == "skill_treasure" and {100, 190, 255} or {235, 178, 58}
        damage = 0
    elseif monsterType == "boss" then
        hpMult = CONFIG.BossHPMult * GetBossLateHPMult(sourceFloor)
        speedMult = CONFIG.BossSpeedMultNew
        radius = 36
        color = {255, 70, 70}
        damage = CONFIG.MonsterDamage * CONFIG.BossDamageScale * GetBossLateDamageMult(sourceFloor)
    else
        local colors = { {180,60,200}, {60,200,80}, {200,60,60}, {60,150,200}, {200,150,60} }
        color = colors[math.random(1, #colors)]
    end

    if bossBuff ~= nil then
        if bossBuff.id == "hp" then
            hpMult = hpMult * (bossBuff.hpMult or 1.0)
        elseif bossBuff.id == "speed" then
            speedMult = speedMult * (bossBuff.speedMult or 1.0)
        elseif bossBuff.id == "damage" then
            damage = damage * (bossBuff.damageMult or 1.0)
        end
    end

    local floorDifficultyMultiplier = GetFloorDifficultyStepMultiplier(sourceFloor)
    local hp = CONFIG.MonsterHP * diffScale * hpMult * CONFIG.MonsterGlobalHPMult
        * floorDifficultyMultiplier
    local monsterHpPercent = GetRoguelikeModifier("monsterHpPercent")
    local moveSpeedPercent = GetRoguelikeModifier("monsterMoveSpeedPercent")
    local attackSpeedPercent = GetRoguelikeModifier("monsterAttackSpeedPercent")
    hp = hp * (1 + monsterHpPercent / 100)

    local imgCategory = GetMonsterImageCategory(monsterType)
    local imgHandle = monsterType == "splitter" and (splitterImage or 0) or PickMonsterImage(imgCategory)

    local monster = {
        type = monsterType,
        x = x,
        y = y,
        hp = hp,
        maxHp = hp,
        floor = sourceFloor,
        speed = CONFIG.MonsterSpeed * speedMult * GetMonsterSpeedScale(sourceFloor) * (1 + moveSpeedPercent / 100),
        radius = math.floor(tonumber(radius) or 0),
        damage = damage * GetMonsterDamageScale(sourceFloor) * floorDifficultyMultiplier,
        bossBuff = bossBuff,
        bossShieldTimer = 0,
        color = color,
        hitFlash = 0,
        freezeTimer = 0,
        isBoss = monsterType == "boss",
        isOriginalSpawn = splitDepth == 0,
        isSplitChild = splitDepth > 0,
        isSummon = false,
        riftGemRollResolved = false,
        splitDepth = splitDepth,
        chargeTimer = 0,
        chargeDuration = 0,
        baseAttackCooldown = 0,
        attackCooldownMultiplier = 1 / math.max(0.1, 1 + attackSpeedPercent / 100),
        hitStunTimer = 0,
        shootTimer = CONFIG.RangedAttackCooldown * (0.35 + math.random() * 0.5) * (1 / math.max(0.1, 1 + attackSpeedPercent / 100)),
        imageCategory = imgCategory,
        imageHandle = imgHandle,
        strafePhase = math.random() * math.pi * 2,
        strafeSpeed = (CONFIG.MonsterStrafeSpeedMin or 1.2) + math.random() * ((CONFIG.MonsterStrafeSpeedMax or 2.4) - (CONFIG.MonsterStrafeSpeedMin or 1.2)),
        strafeStrength = (CONFIG.MonsterStrafeStrength or 0.22) * (monsterType == "boss" and 0.35 or (monsterType == "ranged" and 0.75 or 1.0)),
        spawnVisualTimer = monsterType == "splitter" and 0.18 or (monsterType == "boss" and 0.75 or 0.36),
        spawnVisualDuration = monsterType == "splitter" and 0.18 or (monsterType == "boss" and 0.75 or 0.36),
        bloodTrailTimer = math.random() * 0.5,
    }
    if monsterType == "treasure" or monsterType == "skill_treasure" then
        local escapeDirection = x <= screenW * 0.5 and 1 or -1
        monster.treasureEscapeDirection = escapeDirection
        monster.treasureStartX = escapeDirection > 0 and math.max(radius + 8, x) or math.min(screenW - radius - 8, x)
        monster.treasureStartY = math.max(radius + 24, math.min(screenH * 0.32, y))
        monster.x = monster.treasureStartX
        monster.y = monster.treasureStartY
        monster.treasureWarningTimer = math.max(0, CONFIG.TreasureWarningDuration or 0.8)
        monster.treasureEscapeTimer = math.max(1, CONFIG.TreasureEscapeDuration or 10.0)
        monster.treasureEscapeDuration = monster.treasureEscapeTimer
        monster.treasureDisplayRefreshTimer = 0
        monster.treasureDisplayText = monsterType == "skill_treasure"
            and "5本技能宝箱出现"
            or "5倍金币宝箱出现"
        monster.treasureMiddlePauseTimer = 0
        monster.treasureMiddlePaused = false
        monster.treasureControlOffsetX = 0
        monster.treasureControlOffsetY = 0
        monster.treasureEscaped = false
    end
    if monsterType ~= "splitter" then
        AddEffect({
            type = "monster_spawn",
            x = x,
            y = y,
            radius = radius,
            color = monsterType == "boss" and {190, 80, 255}
                or (monsterType == "blood" and {230, 48, 70} or {105, 90, 180}),
            life = monster.spawnVisualDuration,
            maxLife = monster.spawnVisualDuration,
            boss = monsterType == "boss",
        })
    end
    if equipmentRiftActive then
        ApplyEquipmentRiftDifficultyToMonster(monster)
    end
    return monster
end

function SpawnSplitChildren(monster)
    if monster.type ~= "splitter" or (monster.splitDepth or 0) >= CONFIG.SplitterMaxDepth then return end
    local childCount = 3
    if IsTwentyBattleActive() then
        childCount = math.min(
            childCount,
            math.max(0, CONFIG.MaxMonsters - #monsters)
        )
    end
    if childCount <= 0 then return end

    local nextDepth = (monster.splitDepth or 0) + 1
    for i = 1, childCount do
        local angle = (i - 1) / childCount * math.pi * 2 + math.random() * 0.45
        local sourceFloor = monster.floor or runFloor
        local child = CreateMonster(
            "splitter",
            monster.x + math.cos(angle) * 18,
            monster.y + math.sin(angle) * 18,
            GetMonsterDifficultyScale(sourceFloor),
            nextDepth,
            sourceFloor,
            monster.bossBuff,
            true
        )
        table.insert(monsters, child)
    end
    AddEffect({ type = "split_burst", x = monster.x, y = monster.y, radius = monster.radius + 14, life = 0.48, maxLife = 0.48 })
end

function IsMonsterInsideBattleArea(monster)
    if monster == nil then return false end
    local radius = monster.radius or CONFIG.MonsterRadius or 0
    return monster.x >= radius and monster.x <= screenW - radius and monster.y >= radius and monster.y <= screenH - radius
end

function FireMonsterProjectile(monster)
    if not IsMonsterInsideBattleArea(monster) then return end
    local dx = base.x - monster.x
    local dy = base.y - monster.y
    local dist = math.sqrt(dx * dx + dy * dy)
    if dist <= 0 then return end
    table.insert(monsterProjectiles, {
        x = monster.x,
        y = monster.y,
        vx = dx / dist * CONFIG.RangedProjectileSpeed,
        vy = dy / dist * CONFIG.RangedProjectileSpeed,
        damage = monster.damage or CONFIG.MonsterDamage,
        radius = 5,
        life = 5,
    })
    AddEffect({ type = "monster_shot", x1 = monster.x, y1 = monster.y, x2 = monster.x + dx / dist * 18, y2 = monster.y + dy / dist * 18, life = 0.22, maxLife = 0.22 })
end

function GetBaseDamageAfterEquipment(damage)
    local stats = GetBattleEquipmentStats and GetBattleEquipmentStats() or GetEquipmentStats()
    local reduction = math.min(20, math.max(0, stats.damageReductionPercent or 0))
    local gemFinalReduction = math.min(
        100,
        math.max(0, stats.gemIncomingDamageReductionPercent or 0)
    )
    local remainingDamage = math.max(0, damage or 0) * (1 - reduction / 100)
    remainingDamage = remainingDamage * (1 - gemFinalReduction / 100)
    if (battleBulwarkDamageReductionTimer or 0) > 0 then
        remainingDamage = remainingDamage * 0.85
    end
    return remainingDamage
end

function ApplyBaseHpDamage(damage)
    local maxHp = math.max(1, base.maxHp or 1)
    local previousHp = base.hp or maxHp
    local previousRatio = previousHp / maxHp
    base.hp = previousHp - GetBaseDamageAfterEquipment(damage)
    base.flashTimer = 0.3

    local stats = GetBattleEquipmentStats
        and GetBattleEquipmentStats()
        or GetEquipmentStats()
    local currentRatio = base.hp / maxHp
    if stats.bulwarkEmergencyRecovery == true
        and battleBulwarkRecoveryTriggered ~= true
        and previousRatio >= 0.10
        and currentRatio < 0.10
    then
        battleBulwarkRecoveryTriggered = true
        battleBulwarkDamageReductionTimer = 5
        local previousDamagedHp = base.hp
        base.hp = math.min(maxHp, base.hp + maxHp * 0.30)
        local recoveredHp = math.max(0, base.hp - previousDamagedHp)
        AddEffect({
            type = "heal",
            x = base.x,
            y = base.y - CONFIG.BaseHeight * 0.35,
            life = 0.9,
            maxLife = 0.9,
            text = "铁壁共鸣 +" .. math.floor(recoveredHp) .. "｜5秒15%减伤",
        })
        print(
            "[EquipmentResonance] 铁壁5件恢复触发:",
            math.floor(recoveredHp),
            "当前生命:",
            math.floor(base.hp),
            "/",
            math.floor(maxHp),
            "5秒减伤: 15%"
        )
    end
end

function UpdateMonsterProjectiles(dt)
    for i = #monsterProjectiles, 1, -1 do
        local p = monsterProjectiles[i]
        local oldX = p.x
        local oldY = p.y
        p.life = p.life - dt
        p.x = oldX + p.vx * dt
        p.y = oldY + p.vy * dt
        local hitRadius = CONFIG.BaseWidth + p.radius
        local hitBase = PointToSegmentDistanceSquared(
            base.x,
            base.y,
            oldX,
            oldY,
            p.x,
            p.y
        ) <= hitRadius * hitRadius
        if hitBase then
            if base.shield and base.shield > 0 then
                base.shield = math.max(0, base.shield - 1)
                if OnShieldLayerAbsorbed then OnShieldLayerAbsorbed() end
                AddEffect({ type = "shield_break", x = base.x, y = base.y - CONFIG.BaseHeight * 0.35, radius = 70, life = 0.55 })
            else
                ApplyBaseHpDamage(p.damage)
            end
            table.remove(monsterProjectiles, i)
            SpawnParticles(base.x, base.y - CONFIG.BaseHeight / 3, 4, {80, 190, 255})
        elseif p.life <= 0 or p.x < -40 or p.x > screenW + 40 or p.y < -60 or p.y > screenH + 60 then
            table.remove(monsterProjectiles, i)
        end
    end
end

function MonsterAttackBase(monster, dist)
    if monster.baseAttackCooldown and monster.baseAttackCooldown > 0 then return end
    if base.shield and base.shield > 0 then
        base.shield = math.max(0, base.shield - 1)
        if OnShieldLayerAbsorbed then OnShieldLayerAbsorbed() end
        AddEffect({ type = "shield_break", x = base.x, y = base.y - CONFIG.BaseHeight * 0.35, radius = 70, life = 0.55 })
    else
        ApplyBaseHpDamage(
            monster.damage or CONFIG.MonsterDamage
        )
    end

    local dx = monster.x - base.x
    local dy = monster.y - base.y
    local len = math.sqrt(dx * dx + dy * dy)
    if len <= 0 then
        dx, dy, len = 0, -1, 1
    end
    local knockback = CONFIG.MonsterBaseKnockback
    if monster.isBoss then
        knockback = knockback * 0.5
    end
    monster.x = math.max(monster.radius, math.min(screenW - monster.radius, monster.x + dx / len * knockback))
    monster.y = math.max(monster.radius, math.min(screenH - monster.radius, monster.y + dy / len * knockback))
    monster.baseAttackCooldown = GetMonsterBaseAttackCooldown(monster.floor) * (monster.attackCooldownMultiplier or 1)
    monster.hitStunTimer = CONFIG.MonsterHitStun
    monster.chargeDuration = 0
    SpawnParticles(base.x, base.y - CONFIG.BaseHeight / 3, 5, {255, 80, 80})
end


function CountAliveBosses()
    local count = 0
    for _, monster in ipairs(monsters) do
        if monster.isBoss and monster.hp > 0 then
            count = count + 1
        end
    end
    return count
end

function GetBossSpawnX(index, total)
    local margin = math.max(CONFIG.SpawnMargin, (CONFIG.MonsterRadius or 16) * 4)
    local usableWidth = math.max(0, screenW - margin * 2)
    if total <= 1 or usableWidth <= 0 then
        return screenW * 0.5
    end
    return margin + usableWidth * (index - 1) / (total - 1)
end

function SpawnBossAt(index, total, sourceFloor)
    sourceFloor = math.max(1, math.floor(sourceFloor or runFloor or 1))
    local x = GetBossSpawnX(index, total)
    local boss = CreateMonster("boss", x, -CONFIG.MonsterRadius * 6, GetMonsterDifficultyScale(sourceFloor), 0, sourceFloor)
    table.insert(monsters, boss)
    bossAlive = true
    specialUnitSpawnedThisFrame = true
    print("[Floor] Boss 出现, 层数:", sourceFloor, "批次:", index, "/", total, "总进度:", floorBossDefeatedCount + 1, "/", floorBossCount, "血量:", math.floor(boss.hp))
end

function SpawnAllBosses(dt)
    if floorBossDefeatedCount >= floorBossCount then return end
    if floorBossSpawnPlan == nil or #floorBossSpawnPlan == 0 then return end
    if floorBossSpawnIndex > #floorBossSpawnPlan then return end
    if #monsters >= CONFIG.MaxMonsters then return end

    bossSpawned = true
    local maxAliveBosses = math.max(1, math.floor(CONFIG.MaxAliveBosses or 4))
    local aliveBosses = CountAliveBosses()
    if aliveBosses >= maxAliveBosses then
        bossAlive = aliveBosses > 0
        return
    end

    local interval = math.max(0.1, CONFIG.BossSpawnInterval or 2.0)
    bossSpawnTimer = (bossSpawnTimer or interval) + (dt or 0)
    if bossSpawnTimer < interval then return end
    bossSpawnTimer = bossSpawnTimer - interval

    local entry = floorBossSpawnPlan[floorBossSpawnIndex]
    SpawnBossAt(entry.index or 1, entry.total or 1, entry.floor or runFloor)
    floorBossSpawnIndex = floorBossSpawnIndex + 1
    bossAlive = CountAliveBosses() > 0

    if floorBossSpawnIndex <= #floorBossSpawnPlan then
        print("[Floor] Boss 分批出现, 已生成:", floorBossSpawnIndex - 1, "/", #floorBossSpawnPlan, "场上Boss:", bossAlive and CountAliveBosses() or 0)
    else
        print("[Floor] 本层 Boss 已全部安排生成, 数量:", #floorBossSpawnPlan)
    end
end

function StartFloor(floor)
    floorKillCount = 0
    pendingTreasureSpawnQueue = {}
    floorSpawnPlan, floorBossCount = BuildFloorSpawnPlan(floor)
    floorSpawnIndex = 1

    local splitterExtraPerParent = 0
    do
        local childCount = 3
        local maxDepth = CONFIG.SplitterMaxDepth or 0
        local depth = 1
        local n = childCount
        while depth <= maxDepth do
            splitterExtraPerParent = splitterExtraPerParent + n
            n = n * childCount
            depth = depth + 1
        end
    end

    floorKillTarget = 0
    local splitterParentsInPlan = 0
    for _, entry in ipairs(floorSpawnPlan or {}) do
        if entry.type ~= "boss" then
            floorKillTarget = floorKillTarget + 1
            if entry.type == "splitter" then
                splitterParentsInPlan = splitterParentsInPlan + 1
            end
        end
    end
    floorKillTarget = floorKillTarget + splitterParentsInPlan * splitterExtraPerParent
    if splitterParentsInPlan > 0 then
        print("[Floor] 分裂怪计入目标: 父怪", splitterParentsInPlan, "只, 每只额外子/孙", splitterExtraPerParent, "只, 目标合计:", floorKillTarget)
    end
    floorBossDefeatedCount = 0
    floorBossSpawnIndex = 1
    bossSpawned = false
    bossAlive = false
    bossSpawnTimer = CONFIG.BossSpawnInterval or 2.0
    firstFloorBlueDropDone = not (floor <= 1 and (fiveBattleActive and fiveBattleEndFloor >= 1 or floor == 1))
    spawnTimer = 0
    spawnBatchCredit = 0
    local firstEntry = floorSpawnPlan[1]
    local firstSourceFloor = firstEntry and firstEntry.floor or floor
    print("[Spawner] 本局投放配置, 起始层:", floor, "模式层数:", fiveBattleActive and fiveBattleFloorCount or 1, "首批均值:", string.format("%.2f", GetSpawnBatchTarget(firstSourceFloor)), "场上上限:", CONFIG.MaxMonsters, "Boss上限:", CONFIG.MaxAliveBosses)
end

function FinishFloorSettlement()
    local settlement = pendingFloorSettlement
    if type(settlement) == "table" then
        BeginAutoContinueCountdown(settlement)
        -- 续关倒计时已启动，结算期云存档延迟合并到此结束，统一 flush 一次。
        if EndDeferredCloudSave ~= nil then
            EndDeferredCloudSave()
        end
        return
    end
    pendingFloorSettlement = nil
    fiveBattleActive = false
    fiveBattleFloorCount = 1
    fiveBattleSpeedMul = 1.0
    currentScreen = "menu"
    SaveCloudData(true)
    if EndDeferredCloudSave ~= nil then
        EndDeferredCloudSave()
    end
    print("[Roguelike] 本次结算无续关数据，返回主菜单")
    GameEvents.Emit("scene:main")
end

function CompleteEndlessFloor()
    CommitSessionPlayTime()
    local clearedFloor = math.max(
        CONFIG.EndlessStartFloor or 600,
        math.floor(runFloor or (CONFIG.EndlessStartFloor or 600))
    )
    local overflowGoldBonus = GetOverflowLuckGoldBonus()
    local floorReward = math.floor(
        clearedFloor * 45 * (1 + overflowGoldBonus / 100)
    )
    local totalReward = ApplyHiddenAdminGoldBonus(floorReward)
        + (runGoldReward or 0)
    -- 与普通模式保持一致：每层结算后重新初始化技能 CD，
    -- 随机化初始 CD + 相同技能按技能栏顺序错开释放，
    -- 避免无尽模式技能同步齐射。
    CommitPendingLoot("floor_complete")
    TryAutoDismantleSkills("floor_complete")
    InitSkillRuntime(true)
    AddGold(totalReward)
    runGoldReward = 0

    if base.maxHp and base.maxHp > 0 then
        base.hp = math.min(
            base.maxHp,
            math.max(1, base.hp) + base.maxHp * (CONFIG.FloorClearHealRatio or 0)
        )
    end

    playerData.endlessBestFloor = math.max(
        playerData.endlessBestFloor or 0,
        clearedFloor
    )
    endlessResultFloor = clearedFloor
    runFloor = clearedFloor + 1
    playerData.endlessRunState.active = true
    playerData.endlessRunState.currentFloor = runFloor
    playerData.endlessRunState.penaltyState = "pending"
    ResetPendingLoot()
    saveDirty = true
    SaveCloudData(true)
    print("[Endless] 无尽第" .. tostring(clearedFloor)
        .. "层通关，奖励金币+" .. tostring(totalReward)
        .. "，继续第" .. tostring(runFloor) .. "层")
    StartFloor(runFloor)
end

function CompleteFloor()
    if trainingModeActive then
        FinishTraining(true)
        return
    end
    if equipmentRiftActive then
        CompleteEquipmentRiftDifficulty()
        return
    end
    if endlessTrialActive then
        CompleteEndlessFloor()
        return
    end
    -- 方案C：进入结算链路（普通/连打）即开启云存档延迟合并，
    -- 期间多次 SaveCloudData(true) 只置脏，由结算出口统一 flush 一次。
    if BeginDeferredCloudSave ~= nil then
        BeginDeferredCloudSave()
    end
    CommitSessionPlayTime()
    local previousHighestClearedFloor = GetHighestClearedFloor()
    local normalCap = CONFIG.NormalFloorCap or 600
    local clearedFloor = math.min(normalCap, runFloor)
    local floorReward = 0
    local completedFloors = 1
    local nextFloor = clearedFloor + 1
    local skipText = ""

    if fiveBattleActive then
        completedFloors = math.max(1, math.floor(fiveBattleFloorCount or 5))
        local startFloor = math.max(1, math.floor(fiveBattleStartFloor or clearedFloor))
        local endFloor = math.min(
            normalCap,
            math.max(startFloor, math.floor(fiveBattleEndFloor or (startFloor + completedFloors - 1)))
        )
        completedFloors = endFloor - startFloor + 1
        for floor = startFloor, endFloor do
            floorReward = floorReward + floor * 45
        end
        nextFloor = endFloor + 1
        skipText = "，连打禁用跳层"
    else
        floorReward = clearedFloor * 45
    end

    local overflowGoldBonus = GetOverflowLuckGoldBonus()
    local overflowAdjustedFloorReward = math.floor(
        floorReward * (1 + overflowGoldBonus / 100))
    local totalReward = ApplyHiddenAdminGoldBonus(overflowAdjustedFloorReward)
        + (runGoldReward or 0)
    local milestoneStartFloor = fiveBattleActive
        and math.max(1, math.floor(fiveBattleStartFloor or clearedFloor))
        or clearedFloor
    local milestoneEndFloor = fiveBattleActive
        and math.max(milestoneStartFloor, math.floor(fiveBattleEndFloor or clearedFloor))
        or clearedFloor
    local milestoneRewardCount = ClaimMilestoneRedWeapons(
        milestoneStartFloor,
        math.min(normalCap, milestoneEndFloor)
    )
    CommitPendingLoot("floor_complete")
    TryAutoDismantleSkills("floor_complete")
    AddGold(totalReward)
    if base.maxHp and base.maxHp > 0 then
        local carryHp = math.min(base.maxHp, math.max(1, base.hp) + base.maxHp * (CONFIG.FloorClearHealRatio or 0))
        playerData.nextBaseHpRatio = carryHp / base.maxHp
    else
        playerData.nextBaseHpRatio = nil
    end
    runGoldReward = 0
    playerData.rebirthRunStartFloor = math.max(1, playerData.rebirthRunStartFloor or clearedFloor)
    playerData.rebirthRunCompletedFloors = math.max(0, math.floor(playerData.rebirthRunCompletedFloors or 0)) + completedFloors

    if not fiveBattleActive then
        local skippedFloors = RollSkipFloorsOnFloorClear()
        skippedFloors = math.min(
            skippedFloors,
            math.max(0, normalCap - clearedFloor)
        )
        nextFloor = math.min(normalCap + 1, clearedFloor + 1 + skippedFloors)
        if skippedFloors > 0 then
            playerData.rebirthRunSkippedFloors = math.max(0, math.floor(playerData.rebirthRunSkippedFloors or 0)) + skippedFloors
            skipText = "，跳层生效，少打" .. tostring(skippedFloors) .. "关"
        end
    end

    playerData.normalHighestClearedFloor = math.max(
        playerData.normalHighestClearedFloor or 0,
        math.min(normalCap, fiveBattleActive and (fiveBattleEndFloor or clearedFloor) or clearedFloor)
    )
    runFloor = math.min(normalCap, nextFloor)
    playerData.currentFloor = runFloor
    playerData.bestFloor = math.max(
        playerData.bestFloor or 1,
        math.min(normalCap + 1, nextFloor)
    )
    local currentHighestClearedFloor = GetHighestClearedFloor()
    local previousPressureMilestone = math.floor(
        previousHighestClearedFloor / 5
    )
    local currentPressureMilestone = math.floor(
        currentHighestClearedFloor / 5
    )
    local pressureReduction = math.max(
        0,
        currentPressureMilestone - previousPressureMilestone
    )
    if pressureReduction > 0 then
        AdjustEquipmentRiftPressure(
            -pressureReduction,
            "历史最高通关每5层减压" .. tostring(pressureReduction) .. "层"
        )
    end
    saveDirty = true
    if fiveBattleActive then
        print("[MultiBattle] " .. tostring(fiveBattleFloorCount) .. "连打第" .. tostring(fiveBattleStartFloor) .. "-" .. tostring(fiveBattleEndFloor) .. "层通关! 金币+" .. totalReward .. "，宝箱奖励+" .. tostring(totalReward - floorReward) .. skipText)
    else
        print("[Floor] 第" .. clearedFloor .. "层通关! 金币+" .. totalReward .. "，宝箱奖励+" .. tostring(totalReward - floorReward) .. skipText)
    end

    if nextFloor > normalCap then
        pendingFloorSettlement = nil
        fiveBattleActive = false
        fiveBattleFloorCount = 1
        fiveBattleSpeedMul = 1.0
        playerData.currentFloor = normalCap
        playerData.rebirthUnlocked = true
        playerData.rebirthRunActive = false
        playerData.nextBaseHpRatio = nil
        SaveCloudData(true)
        if EndDeferredCloudSave ~= nil then
            EndDeferredCloudSave()
        end
        currentScreen = "menu"
        print("[Floor] 普通模式第600层已完成，普通进度封顶")
        GameEvents.Emit("scene:main")
        return
    end

    local settlementStartFloor = fiveBattleActive and math.max(1, math.floor(fiveBattleStartFloor or clearedFloor)) or clearedFloor
    local settlementEndFloor = math.max(settlementStartFloor, math.floor(nextFloor - 1))
    pendingFloorSettlement = {
        nextFloor = nextFloor,
        fiveBattle = fiveBattleActive == true,
        battleFloorCount = completedFloors,
        gameSpeed = gameSpeed,
        clearedStartFloor = settlementStartFloor,
        clearedEndFloor = settlementEndFloor,
    }
    local nodes = CollectRoguelikeNodes(
        settlementStartFloor,
        settlementEndFloor
    )
    QueueRandomRoguelikeBonusNodes(
        milestoneStartFloor,
        milestoneEndFloor
    )
    fiveBattleActive = false
    fiveBattleFloorCount = 1
    fiveBattleSpeedMul = 1.0
    if BeginRoguelikeSettlement(nodes) then
        return
    end
    FinishFloorSettlement()
end

function TryCompleteFloorIfCleared()
    if floorSpawnIndex <= #floorSpawnPlan then return end
    if floorSpawnIndex > #floorSpawnPlan
        and pendingTreasureSpawnQueue ~= nil
        and #pendingTreasureSpawnQueue > 0 then
        return
    end
    if floorBossDefeatedCount < floorBossCount then return end
    if #monsters > 0 then return end
    CompleteFloor()
end


function GetSpawnBatchTarget(sourceFloor)
    sourceFloor = math.max(1, math.floor(sourceFloor or runFloor or 1))
    local startFloor = math.max(1, math.floor(CONFIG.SpawnBatchGrowthStartFloor or 100))
    if sourceFloor <= startFloor then
        return 1.0
    end

    local midFloor = math.max(
        startFloor + 1,
        math.floor(CONFIG.SpawnBatchGrowthMidFloor or 300)
    )
    local maxMultiplier = math.max(1, CONFIG.SpawnBatchMaxMultiplier or 5)
    if sourceFloor <= midFloor then
        local floorsToDouble = math.max(
            1,
            CONFIG.SpawnBatchGrowthFloorsToDouble or (midFloor - startFloor)
        )
        return math.min(
            maxMultiplier,
            1 + (sourceFloor - startFloor) / floorsToDouble
        )
    end

    local floorsPerMultiplier = math.max(1, CONFIG.SpawnBatchGrowthFloorsPerMultiplier or 150)
    return math.min(
        maxMultiplier,
        2 + (sourceFloor - midFloor) / floorsPerMultiplier
    )
end

function GetTwentyBattleSpawnIntervalMultiplier()
    if not IsTwentyBattleActive() then return 1.0 end

    local fastUntil = math.max(0, math.floor(CONFIG.TwentyBattleSpawnFastUntil or 40))
    local normalAt = math.max(
        fastUntil + 1,
        math.floor(CONFIG.TwentyBattleSpawnNormalAt or 70)
    )
    local fastMultiplier = math.max(
        0.1,
        math.min(1.0, CONFIG.TwentyBattleSpawnIntervalMultiplier or 0.5)
    )
    local monsterCount = #monsters
    if monsterCount <= fastUntil then return fastMultiplier end
    if monsterCount >= normalAt then return 1.0 end

    local occupancy = (monsterCount - fastUntil) / (normalAt - fastUntil)
    return fastMultiplier + (1.0 - fastMultiplier) * occupancy
end

function HasTwentyBattleSpawnBudget()
    if not IsTwentyBattleActive() then return true end
    local budget = math.max(
        1,
        math.floor(CONFIG.TwentyBattleSpawnPerFrameBudget or 6)
    )
    return (spawnedMonstersThisFrame or 0) < budget
end

function CanSpawnPlannedBoss()
    local maxAliveBosses = math.max(1, math.floor(CONFIG.MaxAliveBosses or 4))
    return CountAliveBosses() < maxAliveBosses
end

function UpdateSpawner(dt)
    if specialUnitSpawnedThisFrame then return end

    local hasQueuedTreasure = pendingTreasureSpawnQueue ~= nil
        and #pendingTreasureSpawnQueue > 0
    if floorSpawnIndex > #floorSpawnPlan
        and floorBossDefeatedCount < floorBossCount
        and floorBossSpawnIndex <= #floorBossSpawnPlan
        and (spawnedMonstersThisFrame or 0) == 0 then
        SpawnAllBosses(dt)
        if specialUnitSpawnedThisFrame then
            spawnedMonstersThisFrame = (spawnedMonstersThisFrame or 0) + 1
            return
        end
    end
    if floorSpawnIndex > #floorSpawnPlan
        and not hasQueuedTreasure then
        return
    end

    local cadenceFloor = endlessTrialActive
        and (CONFIG.EndlessStartFloor or 600)
        or runFloor
    local baseSpawnInterval = math.max(
        CONFIG.SpawnIntervalMin,
        CONFIG.SpawnInterval
            - gameTime * CONFIG.SpawnAcceleration
            - (cadenceFloor - 1) * 0.03
    )
    currentSpawnInterval = math.max(
        0.12,
        baseSpawnInterval * GetTwentyBattleSpawnIntervalMultiplier()
    )
    spawnTimer = spawnTimer + dt
    if spawnTimer >= currentSpawnInterval
        and #monsters < CONFIG.MaxMonsters
        and HasTwentyBattleSpawnBudget() then
        spawnTimer = spawnTimer - currentSpawnInterval
        if hasQueuedTreasure
            and not HasAnyActiveTreasureMonster()
            and (spawnedMonstersThisFrame or 0) == 0 then
            if SpawnQueuedTreasure() then
                spawnedMonstersThisFrame = (spawnedMonstersThisFrame or 0) + 1
                return
            end
        end

        local firstEntry = floorSpawnPlan[floorSpawnIndex]
        local batchFloor = firstEntry and (firstEntry.spawnFloor or firstEntry.floor) or runFloor
        local batchTarget = GetSpawnBatchTarget(batchFloor)
        local baseBatchSize = math.max(1, math.floor(batchTarget))
        local fractionalBatch = math.max(0, batchTarget - baseBatchSize)
        spawnBatchCredit = (spawnBatchCredit or 0) + fractionalBatch
        local extraBatchSize = math.floor(spawnBatchCredit + 0.000001)
        spawnBatchCredit = math.max(0, spawnBatchCredit - extraBatchSize)
        local batchSize = baseBatchSize + extraBatchSize
        local spawnedCount = 0
        local bossSpawnedThisBatch = false

        while floorSpawnIndex <= #floorSpawnPlan
            and #monsters < CONFIG.MaxMonsters
            and HasTwentyBattleSpawnBudget() do
            local entry = floorSpawnPlan[floorSpawnIndex]
            local entryType = entry.type or "normal"
            local entryIsTreasure = IsTreasureMonsterType(entryType)
            local entryFloor = math.max(
                1,
                math.floor(entry.spawnFloor or entry.floor or batchFloor)
            )
            if (entryIsTreasure or entryType == "boss")
                and ((spawnedMonstersThisFrame or 0) > 0 or spawnedCount > 0) then
                break
            end
            if not entryIsTreasure and entryFloor ~= batchFloor then
                break
            end
            if not entryIsTreasure and spawnedCount >= batchSize then
                break
            end
            if entryType == "boss" then
                if bossSpawnedThisBatch or not CanSpawnPlannedBoss() then
                    break
                end
                bossSpawnedThisBatch = true
            end
            local monsterCountBefore = #monsters
            SpawnMonster()
            spawnedMonstersThisFrame = (spawnedMonstersThisFrame or 0)
                + math.max(0, #monsters - monsterCountBefore)
            if specialUnitSpawnedThisFrame then
                return
            end
            if not entryIsTreasure then
                spawnedCount = spawnedCount + 1
            end
        end
    elseif #monsters >= CONFIG.MaxMonsters
        or not HasTwentyBattleSpawnBudget() then
        spawnTimer = math.min(spawnTimer, currentSpawnInterval)
    end
end

function GetDistributedMonsterSpawnPosition()
    local margin = math.max(CONFIG.SpawnMargin or 20, CONFIG.MonsterRadius or 8)
    local minGap = CONFIG.MonsterSpawnMinXGap or 42
    local jitter = CONFIG.MonsterSpawnVerticalJitter or 90
    local sideChance = CONFIG.MonsterSpawnSideChance or 0.30
    local usableWidth = math.max(1, screenW - margin * 2)
    local x = margin + math.random() * usableWidth
    local y = -CONFIG.MonsterRadius * 3 - math.random() * jitter

    if math.random() < sideChance then
        local side = math.random() < 0.5 and -1 or 1
        x = side < 0 and -CONFIG.MonsterRadius * 4 or screenW + CONFIG.MonsterRadius * 4
        local sideMaxY = math.max(margin + 1, math.min(screenH * 0.46, base.y - margin * 1.8))
        y = margin + math.random() * math.max(1, sideMaxY - margin)
        return x, y
    end

    local slotCount = math.max(1, math.floor(usableWidth / minGap))
    local slotWidth = usableWidth / slotCount
    local occupiedSlots = monsterSpawnOccupiedSlots
    local freeCount = slotCount
    for slot = 1, slotCount do
        occupiedSlots[slot] = false
    end
    for _, m in ipairs(monsters) do
        if m.y < margin * 2 then
            local slot = math.floor((m.x - margin) / slotWidth) + 1
            if slot >= 1 and slot <= slotCount and not occupiedSlots[slot] then
                occupiedSlots[slot] = true
                freeCount = freeCount - 1
            end
        end
    end

    if freeCount > 0 then
        local targetRank = math.random(1, freeCount)
        for slot = 1, slotCount do
            if not occupiedSlots[slot] then
                targetRank = targetRank - 1
                if targetRank <= 0 then
                    x = margin + (slot - 0.5) * slotWidth
                    break
                end
            end
        end
    end

    return x, y
end

function SpawnTreasureEntry(entry)
    local sourceFloor = math.max(1, math.floor(entry.floor or runFloor or 1))
    local rewardFloor = math.max(1, math.floor(entry.rewardFloor or sourceFloor))
    local allowedIndex = math.max(1, math.floor(entry.treasureIndex or 1))
    if GetTreasureConsumedCount(rewardFloor) >= allowedIndex then
        floorKillCount = floorKillCount + 1
        print("[Treasure] 已消耗的宝箱机会不再补发, 层数:", sourceFloor, "序号:", allowedIndex)
        TryCompleteFloorIfCleared()
        return false
    end

    local x, y = GetDistributedMonsterSpawnPosition()
    local monster = CreateMonster(
        "treasure",
        x,
        y,
        GetMonsterDifficultyScale(sourceFloor),
        0,
        sourceFloor
    )
    table.insert(monsters, monster)
    ConsumeTreasureOpportunity(rewardFloor)
    specialUnitSpawnedThisFrame = true
    print("[Treasure] 宝箱出现, 层数:", sourceFloor, "序号:", allowedIndex)
    return true
end

function SpawnQueuedTreasure()
    if HasAnyActiveTreasureMonster()
        or pendingTreasureSpawnQueue == nil
        or #pendingTreasureSpawnQueue <= 0 then
        return false
    end
    local entry = table.remove(pendingTreasureSpawnQueue, 1)
    if entry.type == "skill_treasure" then
        return SpawnSkillTreasureEntry(entry)
    end
    return SpawnTreasureEntry(entry)
end

function SpawnSkillTreasureEntry(entry)
    local sourceFloor = math.max(1, math.floor(entry.floor or runFloor or 1))
    local rewardFloor = math.max(1, math.floor(entry.rewardFloor or sourceFloor))
    local allowedIndex = math.max(1, math.floor(entry.skillTreasureIndex or 1))
    if GetSkillTreasureConsumedCount(rewardFloor) >= allowedIndex then
        floorKillCount = floorKillCount + 1
        print("[SkillTreasure] 已消耗的技能宝箱机会不再补发, 层数:", sourceFloor, "序号:", allowedIndex)
        TryCompleteFloorIfCleared()
        return false
    end

    local x, y = GetDistributedMonsterSpawnPosition()
    local monster = CreateMonster(
        "skill_treasure",
        x,
        y,
        GetMonsterDifficultyScale(sourceFloor),
        0,
        sourceFloor
    )
    table.insert(monsters, monster)
    ConsumeSkillTreasureOpportunity(rewardFloor)
    specialUnitSpawnedThisFrame = true
    print("[SkillTreasure] 技能宝箱出现, 层数:", sourceFloor, "序号:", allowedIndex)
    return true
end

function SpawnMonster()
    local entry = floorSpawnPlan[floorSpawnIndex] or { type = "normal", floor = runFloor }
    local monsterType = entry.type or "normal"
    local sourceFloor = math.max(1, math.floor(entry.floor or runFloor or 1))
    floorSpawnIndex = floorSpawnIndex + 1

    if monsterType == "treasure" or monsterType == "skill_treasure" then
        if HasAnyActiveTreasureMonster() then
            table.insert(pendingTreasureSpawnQueue, entry)
            print("[Treasure] 宝箱进入统一待生成队列, 类型:", monsterType, "当前排队:", #pendingTreasureSpawnQueue)
            return
        end
        if monsterType == "treasure" then
            SpawnTreasureEntry(entry)
        else
            SpawnSkillTreasureEntry(entry)
        end
        return
    end

    if monsterType == "boss" then
        SpawnBossAt(entry.bossIndex or 1, entry.bossTotal or 1, sourceFloor)
        return
    end
    local x, y = GetDistributedMonsterSpawnPosition()
    local monster = CreateMonster(monsterType, x, y, GetMonsterDifficultyScale(sourceFloor), 0, sourceFloor)
    table.insert(monsters, monster)
end

function GetEquipmentDropChanceCap(monsterType)
    local cap
    if monsterType == "boss" then
        cap = CONFIG.BossEquipmentDropChanceCap
    elseif monsterType == "elite" then
        cap = CONFIG.EliteEquipmentDropChanceCap
    elseif monsterType == "blood" then
        cap = CONFIG.BloodEquipmentDropChanceCap
    else
        cap = CONFIG.NormalEquipmentDropChanceCap
    end
    if IS_CLOUD_ADMIN == true then
        return cap * 2
    end
    return cap
end

function GetLuckEquipmentDropBonus()
    local stats = GetEquipmentStats()
    local luckPercent = GetRoguelikeLuckPercent and GetRoguelikeLuckPercent() or (stats.luckPercent or 0)
    local effectiveLuck = math.min(200, math.max(0, luckPercent))
    local normalizedLuck = effectiveLuck / 200
    return (CONFIG.LuckEquipmentDropBonusCap or 0.1667) * normalizedLuck
end

function GetLuckSkillScrollDropBonus()
    local stats = GetEquipmentStats()
    local luckPercent = GetRoguelikeLuckPercent and GetRoguelikeLuckPercent() or (stats.luckPercent or 0)
    local effectiveLuck = math.min(150, math.max(0, luckPercent))
    local normalizedLuck = effectiveLuck / 150
    return (CONFIG.LuckSkillScrollDropBonusCap or 0.1667) * normalizedLuck
end

function TryDropEquipment(x, y, chance, floor, monsterType)
    local luckBonus = GetLuckEquipmentDropBonus()
    if IS_CLOUD_ADMIN == true then
        luckBonus = luckBonus * 2
    end
    local finalChance = math.min(GetEquipmentDropChanceCap(monsterType), chance + luckBonus)
    if math.random() >= finalChance then return false end
    local slotDef = EQUIPMENT_SLOT_DEFS[math.random(1, #EQUIPMENT_SLOT_DEFS)]
    local item = GenerateEquipment(
        slotDef.id,
        nil,
        floor,
        nil,
        true
    )
    local status = PendingAddEquipment(item)
    if status == "destroyed" then
        SpawnParticles(x, y, 18, {255, 80, 180})
        AddEffect({ type = "drop", x = x, y = y, text = "彩色已满·销毁", life = 1.4, maxLife = 1.4 })
    end
    return status == "kept" or status == "autoSold"
end

function TryDropRefineStone(x, y)
    return false
end

function ForceDropBlueEquipment(x, y, floor)
    local slotId = "weapon"
    local item = GenerateEquipment(
        slotId,
        "blue",
        floor,
        false,
        true
    )
    local status = PendingAddEquipment(item)
    if status == "kept" then
        print("[Drop] 第一层首只普通怪保底蓝装:", item.name, "层数:", floor)
        return true
    end
    print("[Drop] 第一层保底蓝装未获取:", item.name, "原因:", status or "unknown")
    return status == "autoSold"
end


function CountInventoryScroll(skillId)
    local count = 0
    for _, item in ipairs(playerData.inventory) do
        if item.type == "skill_scroll" and item.skillId == skillId then
            count = count + (item.count or 1)
        end
    end
    return count
end

function GetDroppedSkillStar(floor)
    floor = math.max(1, math.floor(floor or 1))
    local maxNaturalStar = math.max(1, math.min(CONFIG.SkillDropMaxNaturalStar or 5, CONFIG.SkillMaxStar or 10))
    local dropStarChances = CONFIG.SkillDropStarChances or {}

    for _, rule in ipairs(dropStarChances) do
        if floor >= (rule.floor or 1) then
            local roll = math.random()
            local accumulatedChance = 0
            for _, entry in ipairs(rule.chances or {}) do
                accumulatedChance = accumulatedChance + (entry.chance or 0)
                if roll < accumulatedChance then
                    return math.max(1, math.min(maxNaturalStar, entry.star or 1))
                end
            end
            return 1
        end
    end

    return 1
end

function AddSkillScroll(skillId, floor)
    local def = GetSkillDef(skillId)
    if def == nil then return end
    local star = GetDroppedSkillStar(floor or runFloor or 1)

    local skillCard = {
        uid = AllocateSkillUid(),
        id = skillId,
        name = def.name,
        desc = def.desc,
        icon = def.icon,
        star = star,
        cooldown = GetSkillBaseCooldown(skillId),
    }
    local status = PendingAddSkill(skillCard)
    if status ~= "kept" then return nil end
    return star
end

function TryDropSkillScroll(x, y, monsterType, floor)
    local finalChance = GetSkillScrollDropChance(monsterType)
    if math.random() >= finalChance then return false end
    local dropFloor = math.tointeger(math.floor(math.max(1, floor or runFloor or 1))) or 1
    local skillId = SKILL_ORDER[math.random(1, #SKILL_ORDER)]
    return AddSkillScroll(skillId, dropFloor) ~= nil
end

