end

AddAwakeningEnergy = function(amount)
    if awakeningActive then return end
    awakeningEnergy = math.min(AWAKENING_MAX_ENERGY, awakeningEnergy + amount)
    if awakeningEnergy >= AWAKENING_MAX_ENERGY then
        TriggerAwakening()
    end
end

UpdateAwakening = function(dt)
    if not awakeningActive then return end
    awakeningTimer = awakeningTimer - dt
    if awakeningTimer <= 0 then
        awakeningTimer = 0
        awakeningActive = false
        print("[Awakening] 觉醒结束")
    end
end

