function NormalizeRunSkillSynergyIds(raw)
    local normalized = {}
    local seen = {}
    for _, synergyId in ipairs(type(raw) == "table" and raw or {}) do
        if #normalized >= RUN_SKILL_SYNERGY_COUNT then break end
        if type(synergyId) == "string"
            and SKILL_SYNERGY_DEFS
            and SKILL_SYNERGY_DEFS[synergyId] ~= nil
            and not seen[synergyId] then
            seen[synergyId] = true
            table.insert(normalized, synergyId)
        end
    end
    return normalized
end

function RollRunSkillSynergies()
    local pool = {}
    for _, synergyId in ipairs(SKILL_SYNERGY_ORDER or {}) do
        if SKILL_SYNERGY_DEFS and SKILL_SYNERGY_DEFS[synergyId] ~= nil then
            table.insert(pool, synergyId)
        end
    end
    local selected = {}
    while #selected < RUN_SKILL_SYNERGY_COUNT and #pool > 0 do
        table.insert(selected, table.remove(pool, math.random(1, #pool)))
    end
    print("[Synergy] 本局自动随机联携:", table.concat(selected, ","))
    return selected
end

function CreateEmptyRoguelikeRunState(runId, randomizeSynergies)
    local selectedSynergyIds = randomizeSynergies == true
        and RollRunSkillSynergies()
        or {}
    return {
        version = ROGUELIKE_RUN_STATE_VERSION,
        runId = math.max(0, math.floor(runId or (playerData and playerData.rebirthCount) or 0)),
        classId = nil,
        active = false,
        rewardCount = 0,
        freeRefreshRemaining = 1,
        selectedSynergyIds = selectedSynergyIds,
        modifiers = {},
        pendingNodes = {},
        pendingChoice = nil,
        pendingFloorSettlement = nil,
        pendingBattleStart = false,
        nodeStartFloor = nil,
        treasureConsumedByFloor = {},
        treasurePlannedByFloor = {},
        skillTreasureConsumedByFloor = {},
        skillTreasurePlannedByFloor = {},
    }
end

local function NormalizeRoguelikeOption(raw)
    if type(raw) ~= "table" or GetRoguelikeOptionByStat(raw.stat) == nil then return nil end
    local value = math.max(-100, math.min(100, math.floor(tonumber(raw.value) or 0)))
    return {
        stat = raw.stat,
        label = tostring(raw.label or GetRoguelikeOptionByStat(raw.stat).label or ""),
        value = value,
        positive = raw.positive == true,
        monsterOnly = raw.monsterOnly == true,
    }
end

function NormalizeRoguelikeRunState(raw, legacyClassId)
    if type(raw) ~= "table" then
        local empty = CreateEmptyRoguelikeRunState()
        if type(legacyClassId) == "string" and CLASS_DEFS[legacyClassId] ~= nil then
            empty.classId = legacyClassId
        end
        return empty
    end
    local state = CreateEmptyRoguelikeRunState()
    state.runId = math.max(0, math.floor(tonumber(raw.runId) or 0))
    local rawClassId = type(raw.classId) == "string" and raw.classId or nil
    if rawClassId ~= nil and CLASS_DEFS[rawClassId] ~= nil then
        state.classId = rawClassId
    elseif type(legacyClassId) == "string" and CLASS_DEFS[legacyClassId] ~= nil then
        state.classId = legacyClassId
    end
    state.rewardCount = math.max(0, math.min(GetMaxRoguelikeRewards(), math.floor(tonumber(raw.rewardCount) or 0)))
    if raw.freeRefreshRemaining == nil then
        state.freeRefreshRemaining = 1
    else
        state.freeRefreshRemaining = math.max(
            0,
            math.min(1, math.floor(tonumber(raw.freeRefreshRemaining) or 0))
        )
    end
    state.active = raw.active == true or state.rewardCount > 0
    state.selectedSynergyIds = NormalizeRunSkillSynergyIds(
        raw.selectedSynergyIds or raw.runSynergyIds
    )
    if #state.selectedSynergyIds > 0 then state.active = true end
    for stat, value in pairs(type(raw.modifiers) == "table" and raw.modifiers or {}) do
        if GetRoguelikeOptionByStat(stat) ~= nil then
            state.modifiers[stat] = math.max(-1000, math.min(1000, math.floor(tonumber(value) or 0)))
        end
    end
    for _, node in ipairs(type(raw.pendingNodes) == "table" and raw.pendingNodes or {}) do
        local value = math.floor(tonumber(node) or 0)
        if value ~= 0 then
            table.insert(state.pendingNodes, value)
        end
    end
    if type(raw.pendingChoice) == "table" then
        local options = {}
        for _, option in ipairs(type(raw.pendingChoice.options) == "table" and raw.pendingChoice.options or {}) do
            local normalized = NormalizeRoguelikeOption(option)
            if normalized ~= nil and #options < 3 then table.insert(options, normalized) end
        end
        if #options == 3 then
            state.pendingChoice = {
                node = (function()
                    local node = math.floor(
                        tonumber(raw.pendingChoice.node) or 1
                    )
                    return node == 0 and 1 or node
                end)(),
                options = options,
            }
        end
    end
    if type(raw.pendingFloorSettlement) == "table" then
        state.pendingFloorSettlement = {
            nextFloor = math.max(1, math.floor(tonumber(raw.pendingFloorSettlement.nextFloor) or 1)),
            fiveBattle = raw.pendingFloorSettlement.fiveBattle == true,
            battleFloorCount = math.max(
                1,
                math.floor(tonumber(raw.pendingFloorSettlement.battleFloorCount)
                    or (raw.pendingFloorSettlement.fiveBattle == true and 5 or 1))
            ),
            gameSpeed = math.max(1, tonumber(raw.pendingFloorSettlement.gameSpeed) or 1),
            clearedStartFloor = math.max(
                1,
                math.floor(tonumber(raw.pendingFloorSettlement.clearedStartFloor) or 1)
            ),
            clearedEndFloor = math.max(
                1,
                math.floor(tonumber(raw.pendingFloorSettlement.clearedEndFloor)
                    or tonumber(raw.pendingFloorSettlement.nextFloor)
                    or 1)
            ),
        }
    end
    state.pendingBattleStart = raw.pendingBattleStart == true
    if raw.nodeStartFloor ~= nil then
        state.nodeStartFloor = math.max(1, math.floor(tonumber(raw.nodeStartFloor) or 1))
    end
    for floorKey, count in pairs(type(raw.treasureConsumedByFloor) == "table" and raw.treasureConsumedByFloor or {}) do
        local floor = math.max(1, math.floor(tonumber(floorKey) or 1))
        local consumed = math.max(0, math.min(CONFIG.TreasureMaxPerFloor or 4, math.floor(tonumber(count) or 0)))
        if consumed > 0 then state.treasureConsumedByFloor[tostring(floor)] = consumed end
    end
    for floorKey, count in pairs(type(raw.treasurePlannedByFloor) == "table" and raw.treasurePlannedByFloor or {}) do
        local floor = math.max(1, math.floor(tonumber(floorKey) or 1))
        local planned = math.max(0, math.min(CONFIG.TreasureMaxPerFloor or 4, math.floor(tonumber(count) or 0)))
        state.treasurePlannedByFloor[tostring(floor)] = planned
    end
    for floorKey, count in pairs(type(raw.skillTreasureConsumedByFloor) == "table" and raw.skillTreasureConsumedByFloor or {}) do
        local floor = math.max(1, math.floor(tonumber(floorKey) or 1))
        local consumed = math.max(0, math.min(CONFIG.SkillTreasureMaxPerFloor or 2, math.floor(tonumber(count) or 0)))
        if consumed > 0 then state.skillTreasureConsumedByFloor[tostring(floor)] = consumed end
    end
    for floorKey, count in pairs(type(raw.skillTreasurePlannedByFloor) == "table" and raw.skillTreasurePlannedByFloor or {}) do
        local floor = math.max(1, math.floor(tonumber(floorKey) or 1))
        local planned = math.max(0, math.min(CONFIG.SkillTreasureMaxPerFloor or 2, math.floor(tonumber(count) or 0)))
        state.skillTreasurePlannedByFloor[tostring(floor)] = planned
    end
    return state
end

function BuildRoguelikeRunStateSaveData()
    local currentRunState = playerData.roguelikeRunState or {}
    local selectedSynergyIds = NormalizeRunSkillSynergyIds(
        currentRunState.selectedSynergyIds
    )
    return NormalizeRoguelikeRunState({
        version = ROGUELIKE_RUN_STATE_VERSION,
        runId = math.max(0, math.floor(currentRunState.runId
            or (playerData and playerData.rebirthCount) or 0)),
        classId = currentRunState.classId,
        active = roguelikeRewardCount > 0 or next(roguelikeModifiers or {}) ~= nil
            or pendingRoguelikeChoice ~= nil or #pendingRoguelikeNodes > 0
            or #selectedSynergyIds > 0,
        rewardCount = roguelikeRewardCount,
        freeRefreshRemaining = roguelikeFreeRefreshRemaining,
        selectedSynergyIds = selectedSynergyIds,
        modifiers = roguelikeModifiers,
        pendingNodes = pendingRoguelikeNodes,
        pendingChoice = pendingRoguelikeChoice,
        pendingFloorSettlement = pendingFloorSettlement,
        pendingBattleStart = pendingRoguelikeBattleStart,
        nodeStartFloor = roguelikeNodeStartFloor,
        treasureConsumedByFloor = playerData.roguelikeRunState
            and playerData.roguelikeRunState.treasureConsumedByFloor or {},
        treasurePlannedByFloor = playerData.roguelikeRunState
            and playerData.roguelikeRunState.treasurePlannedByFloor or {},
        skillTreasureConsumedByFloor = playerData.roguelikeRunState
            and playerData.roguelikeRunState.skillTreasureConsumedByFloor or {},
        skillTreasurePlannedByFloor = playerData.roguelikeRunState
            and playerData.roguelikeRunState.skillTreasurePlannedByFloor or {},
    })
end

local function GetRoguelikeStateCompleteness(state)
    if type(state) ~= "table" then return 0 end
    local score = math.max(0, math.floor(tonumber(state.rewardCount) or 0)) * 100
    score = score + #NormalizeRunSkillSynergyIds(state.selectedSynergyIds)
    for _, value in pairs(type(state.modifiers) == "table" and state.modifiers or {}) do
        if tonumber(value) ~= nil and tonumber(value) ~= 0 then score = score + 10 end
    end
    score = score + math.min(10, #(type(state.pendingNodes) == "table" and state.pendingNodes or {}))
    if type(state.pendingChoice) == "table" then
        score = score + 30 + #(type(state.pendingChoice.options) == "table" and state.pendingChoice.options or {})
    end
    if type(state.pendingFloorSettlement) == "table" then score = score + 5 end
    if state.pendingBattleStart == true then score = score + 2 end
    if state.nodeStartFloor ~= nil then score = score + 1 end
    if state.freeRefreshRemaining == 0 then score = score + 1 end
    return score
end

function RestoreRoguelikeRunState(raw, legacyClassId)
    local incoming = NormalizeRoguelikeRunState(raw, legacyClassId)
    local current = NormalizeRoguelikeRunState(playerData.roguelikeRunState)
    local sameRun = incoming.runId == current.runId
    if sameRun and current.classId ~= nil then
        incoming.classId = current.classId
    end
    if incoming.runId < current.runId
        or (sameRun and GetRoguelikeStateCompleteness(incoming)
            < GetRoguelikeStateCompleteness(current)) then
        incoming = current
    elseif sameRun then
        if #current.selectedSynergyIds >= RUN_SKILL_SYNERGY_COUNT then
            incoming.selectedSynergyIds = current.selectedSynergyIds
            incoming.active = true
        end
        incoming.freeRefreshRemaining = math.min(
            incoming.freeRefreshRemaining or 1,
            current.freeRefreshRemaining or 1
        )
        for floorKey, count in pairs(current.treasureConsumedByFloor or {}) do
            incoming.treasureConsumedByFloor[floorKey] = math.max(
                incoming.treasureConsumedByFloor[floorKey] or 0,
                count
            )
        end
        for floorKey, count in pairs(current.treasurePlannedByFloor or {}) do
            incoming.treasurePlannedByFloor[floorKey] = math.max(
                incoming.treasurePlannedByFloor[floorKey] or 0,
                count
            )
        end
        for floorKey, count in pairs(current.skillTreasureConsumedByFloor or {}) do
            incoming.skillTreasureConsumedByFloor[floorKey] = math.max(
                incoming.skillTreasureConsumedByFloor[floorKey] or 0,
                count
            )
        end
        for floorKey, count in pairs(current.skillTreasurePlannedByFloor or {}) do
            incoming.skillTreasurePlannedByFloor[floorKey] = math.max(
                incoming.skillTreasurePlannedByFloor[floorKey] or 0,
                count
            )
        end
    end
    playerData.roguelikeRunState = incoming
    roguelikeModifiers = incoming.modifiers
    pendingRoguelikeNodes = incoming.pendingNodes
    pendingRoguelikeChoice = incoming.pendingChoice
    pendingFloorSettlement = incoming.pendingFloorSettlement
    pendingRoguelikeBattleStart = incoming.pendingBattleStart
    roguelikeNodeStartFloor = incoming.nodeStartFloor
    roguelikeRewardCount = incoming.rewardCount
    roguelikeFreeRefreshRemaining = incoming.freeRefreshRemaining
    roguelikeChoiceActive = false
end

function PersistRoguelikeRunState(forceCloud)
    playerData.roguelikeRunState = BuildRoguelikeRunStateSaveData()
    saveDirty = true
    if forceCloud and SaveCloudData ~= nil then
        SaveCloudData(true)
    elseif SaveLocalSnapshot ~= nil then
        SaveLocalSnapshot()
    end
end

function ResumePendingRoguelikeChoice()
    if pendingRoguelikeChoice == nil then return false end
    roguelikeChoiceActive = true
    currentScreen = "roguelike"
    ShowRoguelikeChoicePage(pendingRoguelikeChoice.node, pendingRoguelikeChoice.options)
    print("[Roguelike] 已恢复待选节点:", pendingRoguelikeChoice.node,
        "本轮已领取:", roguelikeRewardCount)
    return true
end

function GetRunSkillSynergyIds()
    local state = NormalizeRoguelikeRunState(playerData.roguelikeRunState)
    playerData.roguelikeRunState = state
    return state.selectedSynergyIds
end

function IsRunSkillSynergySelected(synergyId)
    for _, selectedId in ipairs(GetRunSkillSynergyIds()) do
        if selectedId == synergyId then return true end
    end
    return false
end

function EnsureRunSkillSynergies(forceSave)
    local state = NormalizeRoguelikeRunState(playerData.roguelikeRunState)
    if #state.selectedSynergyIds >= math.min(
        RUN_SKILL_SYNERGY_COUNT,
        #(SKILL_SYNERGY_ORDER or {})
    ) then
        playerData.roguelikeRunState = state
        return false
    end
    state.selectedSynergyIds = RollRunSkillSynergies()
    state.active = #state.selectedSynergyIds > 0
    playerData.roguelikeRunState = state
    saveDirty = true
    if forceSave and SaveCloudData ~= nil then
        SaveCloudData(true)
    elseif SaveLocalSnapshot ~= nil then
        SaveLocalSnapshot()
    end
    return true
end

function GetCurrentRunClassId()
    local runState = playerData and playerData.roguelikeRunState
    local classId = runState and runState.classId
    if type(classId) == "string" and CLASS_DEFS[classId] ~= nil then
        return classId
    end
    return nil
end

function HasSelectedRunClass()
    return GetCurrentRunClassId() ~= nil
end

function SelectCurrentRunClass(classId)
    if type(classId) ~= "string" or CLASS_DEFS[classId] == nil then
        return false
    end
    local runState = playerData.roguelikeRunState
    if type(runState) ~= "table" then
        runState = CreateEmptyRoguelikeRunState(playerData.rebirthCount or 0, false)
        playerData.roguelikeRunState = runState
    end
    if runState.classId ~= nil then
        return runState.classId == classId
    end
    runState.classId = classId
    playerData.settings = playerData.settings or {}
    playerData.settings.selectedClassId = classId
    saveDirty = true
    PersistRoguelikeRunState(true)
    print("[Class] 当前局职业已锁定:", classId, CLASS_DEFS[classId].name)
    return true
end

function ResetRoguelikeRun(runId)
    roguelikeModifiers = {}
    pendingRoguelikeNodes = {}
    pendingFloorSettlement = nil
    pendingRoguelikeBattleStart = false
    roguelikeNodeStartFloor = nil
    pendingRoguelikeChoice = nil
    roguelikeChoiceActive = false
    roguelikeRewardCount = 0
    roguelikeFreeRefreshRemaining = 1
    playerData.roguelikeRunState = CreateEmptyRoguelikeRunState(runId, true)
    saveDirty = true
end

function GetRoguelikeModifier(stat)
    -- 训练场木桩测试不吃肉鸽加成；无尽模式继承普通模式本局已选的三选一属性，
    -- 因此不再在无尽时归零（普通通关600封顶返回主菜单后 roguelikeModifiers 仍保留，
    -- 从试炼页进入无尽时自然延续）。
    if trainingModeActive then return 0 end
    return (roguelikeModifiers and roguelikeModifiers[stat]) or 0
end

function GetRoguelikeMonsterModifier(stat)
    if trainingModeActive then return 0 end
    return (roguelikeModifiers and roguelikeModifiers[stat]) or 0
end

function GetRoguelikeOptionByStat(stat)
    for _, def in ipairs(ROGUELIKE_OPTION_DEFS) do
        if def.stat == stat then return def end
    end
    return nil
end

function ApplyRoguelikeModifier(stat, value)
    if stat == nil then return end
    local def = GetRoguelikeOptionByStat(stat)
    local current = GetRoguelikeModifier(stat)
    if def and def.monsterOnly then
        roguelikeModifiers = roguelikeModifiers or {}
        roguelikeModifiers[stat] = current + math.abs(value or 0)
        print("[Roguelike] 选择怪物负状态:", stat, math.abs(value or 0), "当前:", roguelikeModifiers[stat])
        return
    end
    if def and value > 0 then
        value = math.min(value, math.max(0, (def.positiveCap or 100) - current))
    elseif def and value < 0 and def.negativeCap ~= nil then
        value = math.max(value, def.negativeCap - current)
    end
    if value == 0 then return end
    roguelikeModifiers = roguelikeModifiers or {}
    roguelikeModifiers[stat] = current + value
    print("[Roguelike] 选择效果:", stat, value, "当前:", roguelikeModifiers[stat])
end

function BuildRoguelikeOptions(excludedStat)
    local pool = {}
    for _, def in ipairs(ROGUELIKE_OPTION_DEFS) do
        if def.stat ~= excludedStat then
            table.insert(pool, def)
        end
    end
    local positiveCandidates = {}
    for _, def in ipairs(pool) do
        if not def.monsterOnly then
            local remaining = math.max(0, (def.positiveCap or 100) - GetRoguelikeModifier(def.stat))
            if remaining > 0 then
                table.insert(positiveCandidates, def)
            end
        end
    end
    local guaranteedPositive = nil
    if #positiveCandidates > 0 then
        guaranteedPositive = positiveCandidates[math.random(1, #positiveCandidates)]
    end
    local options = {}
    local guaranteedSelected = false
    while #options < 3 and #pool > 0 do
        local index = nil
        if guaranteedPositive ~= nil and not guaranteedSelected then
            for candidateIndex, candidate in ipairs(pool) do
                if candidate == guaranteedPositive then
                    index = candidateIndex
                    break
                end
            end
        end
        index = index or math.random(1, #pool)
        local def = table.remove(pool, index)
        local positive = guaranteedPositive ~= nil and def == guaranteedPositive
        if def.monsterOnly then
            positive = false
        elseif positive then
            guaranteedSelected = true
        elseif guaranteedPositive ~= nil then
            positive = math.random() < 0.5
        end
        local values = positive and def.positive or def.negative
        local value = values[math.random(1, #values)]
        if positive then
            local remaining = math.max(0, (def.positiveCap or 100) - GetRoguelikeModifier(def.stat))
            if remaining <= 0 then
                positive = false
                values = def.negative
                value = values[math.random(1, #values)]
            else
                value = math.min(value, remaining)
            end
        end
        if not positive and def.negativeCap ~= nil then
            local current = GetRoguelikeModifier(def.stat)
            local negativeRemaining = current - def.negativeCap
            if negativeRemaining <= 0 then
                positive = true
                values = def.positive
                local positiveRemaining = math.max(0, (def.positiveCap or 100) - current)
                value = math.min(values[math.random(1, #values)], positiveRemaining)
            else
                value = math.max(value, -negativeRemaining)
            end
        end
        table.insert(options, {
            stat = def.stat,
            label = def.label,
            value = value,
            positive = not def.monsterOnly and value > 0,
            monsterOnly = def.monsterOnly == true,
        })
    end
    for i = #options, 2, -1 do
        local swapIndex = math.random(1, i)
        options[i], options[swapIndex] = options[swapIndex], options[i]
    end
    return options
end

function GetRoguelikeFreeRefreshRemaining()
    return math.max(
        0,
        math.min(1, math.floor(roguelikeFreeRefreshRemaining or 0))
    )
end

function RefreshPendingRoguelikeChoice()
    if not roguelikeChoiceActive or pendingRoguelikeChoice == nil then
        return false
    end
    if GetRoguelikeFreeRefreshRemaining() <= 0 then
        return false
    end
    local oldOptions = pendingRoguelikeChoice.options or {}
    if #oldOptions <= 0 then return false end
    local excludedOption = oldOptions[math.random(1, #oldOptions)]
    local excludedStat = excludedOption and excludedOption.stat or nil
    local newOptions = BuildRoguelikeOptions(excludedStat)
    if #newOptions ~= 3 then return false end

    roguelikeFreeRefreshRemaining = 0
    pendingRoguelikeChoice.options = newOptions
    PersistRoguelikeRunState(true)
    print(
        "[Roguelike] 已使用本局免费刷新，排除旧属性:",
        tostring(excludedStat)
    )
    ShowRoguelikeChoicePage(
        pendingRoguelikeChoice.node,
        pendingRoguelikeChoice.options
    )
    return true
end

function CollectRoguelikeNodes(startFloor, endFloor)
    local nodes = {}
    startFloor = math.max(1, math.floor(startFloor or 1))
    endFloor = math.max(startFloor, math.floor(endFloor or startFloor))

    local firstNode = 0
    if roguelikeNodeStartFloor ~= nil then
        local nextNode = math.max(1, math.floor(roguelikeNodeStartFloor)) + ROGUELIKE_NODE_INTERVAL
        firstNode = nextNode
            + math.ceil(math.max(0, startFloor - nextNode) / ROGUELIKE_NODE_INTERVAL)
            * ROGUELIKE_NODE_INTERVAL
    else
        firstNode = math.ceil(startFloor / ROGUELIKE_NODE_INTERVAL) * ROGUELIKE_NODE_INTERVAL
    end

    for node = firstNode, endFloor, ROGUELIKE_NODE_INTERVAL do
        table.insert(nodes, node)
    end
    return nodes
end

function RefreshRoguelikeMaxHP()
    if base == nil then return end
    local oldMaxHp = math.max(1, base.maxHp or GetBaseMaxHP())
    local oldHp = math.max(1, base.hp or oldMaxHp)
    local newMaxHp = math.max(1, GetBaseMaxHP())
    base.maxHp = newMaxHp
    base.hp = math.max(1, math.min(newMaxHp, oldHp + newMaxHp - oldMaxHp))
end

function FinishRoguelikeChoiceSequence()
    if pendingRoguelikeBattleStart then
        pendingRoguelikeBattleStart = false
        PersistRoguelikeRunState(false)
        print("[Roguelike] 起始层选择完成，初始化第" .. tostring(playerData.currentFloor or runFloor) .. "层")
        StartGame({})
        return
    end
    FinishFloorSettlement()
end

function IsRandomRoguelikeBonusNode(node)
    return math.floor(tonumber(node) or 0) < 0
end

function GetRoguelikeNodeFloor(node)
    return math.abs(math.floor(tonumber(node) or 1))
end

function GetRoguelikeRandomBonusChance()
    -- 管理员隐藏触发率，不在 UI / 公开资料中展示。
    if IS_CLOUD_ADMIN == true
        and CLOUD_BANLIST_LOADED == true
        and clientCloud ~= nil
        and CLOUD_ADMIN_UID ~= nil then
        local myUid = tostring(clientCloud.userId or "")
        if myUid ~= "" and tostring(CLOUD_ADMIN_UID) == myUid then
            return ADMIN_HIDDEN_ROGUELIKE_RANDOM_BONUS_CHANCE
        end
    end
    return ROGUELIKE_RANDOM_BONUS_CHANCE
end

function QueueRandomRoguelikeBonusNodes(startFloor, endFloor)
    startFloor = math.max(1, math.floor(startFloor or 1))
    endFloor = math.max(startFloor, math.floor(endFloor or startFloor))
    local added = 0
    for floor = startFloor, endFloor do
        if math.random() < GetRoguelikeRandomBonusChance() then
            table.insert(pendingRoguelikeNodes, -floor)
            added = added + 1
            print("[Roguelike] 随机额外三选一入队: 第", floor, "层")
        end
    end
    return added
end

function StartNextRoguelikeChoice()
    while #pendingRoguelikeNodes > 0 do
        local node = table.remove(pendingRoguelikeNodes, 1)
        if IsRandomRoguelikeBonusNode(node)
            or roguelikeRewardCount < GetMaxRoguelikeRewards() then
            roguelikeChoiceActive = true
            currentScreen = "roguelike"
            local options = BuildRoguelikeOptions()
            pendingRoguelikeChoice = { node = node, options = options }
            PersistRoguelikeRunState(true)
            print("[Roguelike] 触发", IsRandomRoguelikeBonusNode(node) and "随机额外" or "常规", "三选一，剩余节点:", #pendingRoguelikeNodes)
            ShowRoguelikeChoicePage(node, options)
            return
        end
    end
    roguelikeChoiceActive = false
    FinishRoguelikeChoiceSequence()
end

function ChooseRoguelikeOption(option)
    if not roguelikeChoiceActive or option == nil or pendingRoguelikeChoice == nil then return end
    local bonusNode = IsRandomRoguelikeBonusNode(pendingRoguelikeChoice.node)
    if not bonusNode and roguelikeRewardCount >= GetMaxRoguelikeRewards() then
        pendingRoguelikeChoice = nil
        roguelikeChoiceActive = false
        StartNextRoguelikeChoice()
        return
    end
    local validOption = false
    for _, currentOption in ipairs(pendingRoguelikeChoice.options or {}) do
        if currentOption == option then validOption = true break end
    end
    if not validOption then return end
    roguelikeChoiceActive = false
    pendingRoguelikeChoice = nil
    ApplyRoguelikeModifier(option.stat, option.value)
    if not bonusNode then
        roguelikeRewardCount = math.min(GetMaxRoguelikeRewards(), roguelikeRewardCount + 1)
        print("[Roguelike] 本局常规奖励", roguelikeRewardCount, "/", GetMaxRoguelikeRewards())
    else
        print("[Roguelike] 已领取不计上限的随机额外三选一")
    end
    if option.stat == "hpPercent" then RefreshRoguelikeMaxHP() end
    PersistRoguelikeRunState(true)
    StartNextRoguelikeChoice()
end

function GetMaxRoguelikeRewards()
    return ROGUELIKE_MAX_REWARDS
end

function GetPendingRegularRoguelikeRewardCount()
    local count = 0
    if pendingRoguelikeChoice ~= nil
        and not IsRandomRoguelikeBonusNode(
            pendingRoguelikeChoice.node
        ) then
        count = count + 1
    end
    for _, node in ipairs(pendingRoguelikeNodes or {}) do
        if not IsRandomRoguelikeBonusNode(node) then
            count = count + 1
        end
    end
    return count
end

function BeginRoguelikeSettlementForFloorRange(startFloor, endFloor, source)
    startFloor = math.max(1, math.floor(startFloor or 1))
    endFloor = math.max(startFloor, math.floor(endFloor or startFloor))

    local regularNodeByFloor = {}
    for _, node in ipairs(CollectRoguelikeNodes(
        startFloor,
        endFloor
    )) do
        regularNodeByFloor[node] = true
    end

    local remainingRegularRewards = math.max(
        0,
        GetMaxRoguelikeRewards()
            - roguelikeRewardCount
            - GetPendingRegularRoguelikeRewardCount()
    )
    local addedRegular = 0
    local addedBonus = 0
    for floor = startFloor, endFloor do
        if regularNodeByFloor[floor]
            and remainingRegularRewards > 0 then
            table.insert(pendingRoguelikeNodes, floor)
            remainingRegularRewards = remainingRegularRewards - 1
            addedRegular = addedRegular + 1
        end
        if math.random() < GetRoguelikeRandomBonusChance() then
            table.insert(pendingRoguelikeNodes, -floor)
            addedBonus = addedBonus + 1
            print(
                "[Roguelike] ",
                source or "楼层结算",
                "随机额外三选一入队: 第",
                floor,
                "层"
            )
        end
    end

    if addedRegular <= 0 and addedBonus <= 0 then
        return pendingRoguelikeChoice ~= nil
            or #pendingRoguelikeNodes > 0
    end

    print(
        "[Roguelike] ",
        source or "楼层结算",
        "节点入队，区间:",
        startFloor,
        "-",
        endFloor,
        "常规:",
        addedRegular,
        "随机额外:",
        addedBonus
    )
    if pendingRoguelikeChoice == nil
        and not roguelikeChoiceActive then
        StartNextRoguelikeChoice()
    else
        PersistRoguelikeRunState(true)
    end
    return true
end

function BeginRoguelikeSettlement(nodes)
    local remainingRewards = math.max(
        0,
        GetMaxRoguelikeRewards()
            - roguelikeRewardCount
            - GetPendingRegularRoguelikeRewardCount()
    )
    for _, node in ipairs(nodes or {}) do
        if remainingRewards <= 0 then break end
        table.insert(pendingRoguelikeNodes, math.max(1, math.floor(node or 1)))
        remainingRewards = remainingRewards - 1
    end
    if #pendingRoguelikeNodes > 0 then
        StartNextRoguelikeChoice()
        return true
    end
    return false
end

SyncRunningProgress = function()
    if currentScreen ~= "playing" or trainingModeActive then return end
    playerData.totalKills = math.max(playerData.totalKills or 0, killCount)
    playerData.currentFloor = runFloor
    if score > (playerData.highScore or 0) then
        playerData.highScore = score
    end
    if base and base.maxHp and base.maxHp > 0 then
        if base.hp > 0 and base.hp < base.maxHp then
            playerData.nextBaseHpRatio = base.hp / base.maxHp
        elseif base.hp >= base.maxHp then
            playerData.nextBaseHpRatio = nil
        end
    end
end


function GetSkillDef(skillId)
    return SKILL_DEFS[skillId]
end

function GetBattleEquipmentStats()
    if currentScreen ~= "playing" then
        return GetEquipmentStats()
    end
    if battleEquipmentStatsCache == nil then
        battleEquipmentStatsCache = GetEquipmentStats()
    end
    return battleEquipmentStatsCache
end

function IsTwentyBattleActive()
    return currentScreen == "playing"
        and fiveBattleActive == true
        and math.floor(fiveBattleFloorCount or 1) >= 20
end

function GetBattleSimulationScale()
    return math.max(1, gameSpeed or 1)
        * math.max(1, fiveBattleSpeedMul or 1)
end

function IsTwentyBattleTurboMode()
    return IsTwentyBattleActive()
        and GetBattleSimulationScale() >= 10
end

function IsBattleHighVisualLoad()
    if currentScreen ~= "playing" then return false end
    return battleSimulationOverloaded == true
        or IsTwentyBattleTurboMode()
        or #monsters >= 70
        or #particles >= 400
        or visualEffectCount >= 100
end

function IsBattleMediumVisualLoad()
    if currentScreen ~= "playing" then return false end
    return #monsters >= 40
        or #particles >= 260
        or visualEffectCount >= 70
        or (gameSpeed or 1) >= 5
        or fiveBattleActive == true
end

function GetCurrentParticleLimit()
    if IsTwentyBattleTurboMode() then
        return 90
    elseif IsBattleHighVisualLoad() then
        return 220
    elseif IsBattleMediumVisualLoad() then
        return 400
    end
    return MAX_PARTICLES
end

function GetCurrentVisualEffectLimit()
    if IsTwentyBattleTurboMode() then
        return 36
    elseif IsBattleHighVisualLoad() then
        return 75
    elseif IsBattleMediumVisualLoad() then
        return 120
    end
    return MAX_VISUAL_EFFECTS
end

function GetHeroAttackDamage()
    local stats = GetBattleEquipmentStats()
    local attackPercent = stats.attackPercent + GetRoguelikeModifier("attackPercent")
    local atk = CONFIG.AttackDamage + stats.attackFlat
    atk = atk * (1 + attackPercent / 100)
    return math.floor(atk)
end

function GetHighestClearedFloor()
    if GetNormalHighestClearedFloor ~= nil then
        return GetNormalHighestClearedFloor()
    end
    return math.min(
        CONFIG.NormalFloorCap or 600,
        math.max(0, math.floor(playerData.bestFloor or 0) - 1)
    )
end

function GetCritRateHistoryPenalty()
    return math.floor(GetHighestClearedFloor() / 50) * 20
end

function GetCritRateAfterHistoryPenalty(stats)
    stats = stats or GetBattleEquipmentStats()
    return math.max(0, (stats.critRate or 0) - GetCritRateHistoryPenalty())
end

function GetEffectiveCritRate(stats)
    return math.min(100, GetCritRateAfterHistoryPenalty(stats))
end

function GetOverflowCritRate(stats)
    return math.max(0, GetCritRateAfterHistoryPenalty(stats) - 100)
end

function GetEffectiveCritDamage(stats)
    stats = stats or GetBattleEquipmentStats()
    local overflowCritRate = GetOverflowCritRate(stats)
    return (stats.critDamage or 0) + GetRoguelikeModifier("critDamage") + overflowCritRate * 5
end

function GetMonsterCritDamageReduction(floor)
    local startFloor = CONFIG.MonsterCritDamageReductionStartFloor or 250
    local perFloor = CONFIG.MonsterCritDamageReductionPerFloor or 1
    floor = math.max(1, math.floor(floor or runFloor or playerData.currentFloor or 1))
    if floor < startFloor then return 0 end
    return (floor - startFloor + 1) * perFloor
end

function GetEffectiveCritDamageAgainstMonster(stats, target)
    local critDamage = GetEffectiveCritDamage(stats)
    local floor = target and target.floor or runFloor or playerData.currentFloor or 1
    return math.max(0, critDamage - GetMonsterCritDamageReduction(floor))
end

function RollHeroAttackDamage(target)
    local stats = GetBattleEquipmentStats()
    local damage = GetHeroAttackDamage()
    damage = damage * (1 + (stats.primaryAttackDamagePercent or 0) / 100)
    if target and target.isBoss then
        damage = damage * (1 + stats.bossDamagePercent / 100)
    end
    if math.random(0, 99) < GetEffectiveCritRate(stats) then
        damage = damage * (1 + GetEffectiveCritDamageAgainstMonster(stats, target) / 100)
    end
    damage = damage * (1 + (stats.gemPrimaryDamagePercent or 0) / 100)
    return math.floor(damage)
end

function GetHeroAttackCooldown()
    local stats = GetBattleEquipmentStats()
    local attackSpeedPercent = stats.attackSpeedPercent + GetRoguelikeModifier("attackSpeedPercent")
    return CONFIG.AttackCooldown / math.max(0.1, 1 + attackSpeedPercent / 100)
end

function GetCloneAttackCooldown()
    local stats = GetBattleEquipmentStats()
    local cloneAttackSpeedPercent = math.max(
        0,
        stats.cloneAttackSpeedPercent or 0
    )
    return GetHeroAttackCooldown()
        / math.max(0.1, 1 + cloneAttackSpeedPercent / 100)
end

function GetSkillCooldownReductionForSlot(slot)
    local reduction = 0
    for _, item in pairs(GetActiveEquipment() or {}) do
        for _, affix in ipairs(item and item.affixes or {}) do
            if affix.id == "skill_cooldown" and (affix.slot or 1) == slot then
                reduction = reduction + (affix.value or 0)
            end
        end
    end
    return reduction
end

function GetSkillBaseCooldown(skill)
    local skillId = type(skill) == "table" and skill.id or skill
    if skillId ~= nil and CONFIG.SkillCooldowns and CONFIG.SkillCooldowns[skillId] ~= nil then
        return CONFIG.SkillCooldowns[skillId]
    end
    return CONFIG.SkillCooldown
end

function CalculateSkillCooldown(slot, skill, stats)
    stats = stats or GetEquipmentStats()
    local percent = math.max(
        0,
        math.min(40, stats.skillCooldownPercent or 0)
    )
    return math.max(
        1.0,
        GetSkillBaseCooldown(skill) * (1 - percent / 100)
            - GetSkillCooldownReductionForSlot(slot or 1)
    )
end

function GetSkillCooldown(slot, skill)
    slot = slot or 1
    if currentScreen == "playing" and battleSkillCooldownCache[slot] ~= nil then
        return battleSkillCooldownCache[slot]
    end
    local cooldown = CalculateSkillCooldown(slot, skill, GetEquipmentStats())
    if IsSkillAwakened ~= nil and IsSkillAwakened(skill) then
        cooldown = cooldown * (1 - 0.04 * GetSkillAwakeningLevel(skill))
    end
    return math.max(1.0, cooldown)
end

function GetHeroMoveSpeed()
    local stats = GetBattleEquipmentStats()
    local moveSpeedPercent = stats.moveSpeedPercent + GetRoguelikeModifier("moveSpeedPercent")
    return CONFIG.HeroSpeed * math.max(0.1, 1 + moveSpeedPercent / 100)
end

function GetBaseMaxHP()
    local stats = GetBattleEquipmentStats()
    local hpPercent = (stats.hpPercent or 0)
        + (stats.gemMaxHpPercent or 0)
        + GetRoguelikeModifier("hpPercent")
    return math.max(1, math.floor((CONFIG.BaseMaxHP + stats.hpFlat) * (1 + hpPercent / 100)))
end

function GetRoguelikeLuckPercent()
    local stats = GetBattleEquipmentStats()
    return (stats.luckPercent or 0) + GetRoguelikeModifier("luckPercent")
end

function GetOverflowLuckGoldBonus()
    local luckPercent = GetRoguelikeLuckPercent()
    local overflowLuck = math.max(0, luckPercent - 200)
    return math.floor(overflowLuck * 5)
end

ADMIN_HIDDEN_GOLD_BONUS_PERCENT = 100

function GetHiddenAdminGoldBonusPercent()
    if IS_CLOUD_ADMIN ~= true
        or CLOUD_BANLIST_LOADED ~= true
        or clientCloud == nil
        or CLOUD_ADMIN_UID == nil then
        return 0
    end
    local myUid = tostring(clientCloud.userId or "")
    if myUid == "" or tostring(CLOUD_ADMIN_UID) ~= myUid then
        return 0
    end
    return ADMIN_HIDDEN_GOLD_BONUS_PERCENT
end

function ApplyHiddenAdminGoldBonus(amount)
    amount = math.max(0, math.floor(amount or 0))
    return math.floor(amount * (1 + GetHiddenAdminGoldBonusPercent() / 100))
end

function GetScoreGoldReward(baseScore)
    local stats = GetBattleEquipmentStats()
    local goldPercent = stats.goldPercent
        + GetOverflowLuckGoldBonus()
        + GetHiddenAdminGoldBonusPercent()
    return math.floor(baseScore * 0.9 * (1 + goldPercent / 100))
end

function GetTreasurePlannedCount(floor)
    local state = playerData.roguelikeRunState
    if type(state) ~= "table" then
        state = CreateEmptyRoguelikeRunState()
        playerData.roguelikeRunState = state
    end
    state.treasurePlannedByFloor = state.treasurePlannedByFloor or {}
    return state.treasurePlannedByFloor[tostring(math.max(1, math.floor(floor or 1)))]
end

roguelikeSpawnPlanDirty = false

function SetTreasurePlannedCount(floor, count)
    floor = math.max(1, math.floor(floor or runFloor or 1))
    local state = playerData.roguelikeRunState
    if type(state) ~= "table" then
        state = CreateEmptyRoguelikeRunState()
        playerData.roguelikeRunState = state
    end
    state.treasurePlannedByFloor = state.treasurePlannedByFloor or {}
    state.treasurePlannedByFloor[tostring(floor)] = math.max(0,
        math.min(CONFIG.TreasureMaxPerFloor or 4, math.floor(count or 0)))
    -- 仅更新内存，不立即写盘：连打计划会逐层调用本函数，
    -- 立即写盘会造成多层同步全量存档叠加卡顿，由 BuildFloorSpawnPlan 末尾统一落盘。
    saveDirty = true
    roguelikeSpawnPlanDirty = true
end

function GetTreasureConsumedCount(floor)
    local state = playerData.roguelikeRunState
    if type(state) ~= "table" then
        state = CreateEmptyRoguelikeRunState()
        playerData.roguelikeRunState = state
    end
    state.treasureConsumedByFloor = state.treasureConsumedByFloor or {}
    return math.max(0, math.floor(state.treasureConsumedByFloor[tostring(math.max(1, math.floor(floor or 1)))] or 0))
end

function ConsumeTreasureOpportunity(floor)
    if trainingModeActive then return end
    floor = math.max(1, math.floor(floor or runFloor or 1))
    local state = playerData.roguelikeRunState
    if type(state) ~= "table" then
        state = CreateEmptyRoguelikeRunState()
        playerData.roguelikeRunState = state
    end
    state.treasureConsumedByFloor = state.treasureConsumedByFloor or {}
    local key = tostring(floor)
    state.treasureConsumedByFloor[key] = GetTreasureConsumedCount(floor) + 1
    -- 宝箱机会已消耗是纯计数标记，无需立即同步全量云端存档（BuildSaveSnapshot 序列化+双写盘+校验+网络在宝箱上场帧开销大）。
    -- 与 SetTreasurePlannedCount 一致：仅置 saveDirty，由自动保存(20s)/切后台统一写盘。
    -- BuildRoguelikeRunStateSaveData 在落盘时会从 playerData.roguelikeRunState.treasureConsumedByFloor 读取本值。
    saveDirty = true
end

