function CountActiveSkillTreasureMonsters()
    local count = 0
    for _, monster in ipairs(monsters or {}) do
        if monster.type == "skill_treasure" and (monster.hp or 0) > 0 then
            count = count + 1
        end
    end
    return count
end

function HasActiveSkillTreasureMonster()
    return CountActiveSkillTreasureMonsters() > 0
end

function GetTreasureGoldReward(floor)
    local stats = GetBattleEquipmentStats()
    floor = math.max(1, math.floor(floor or runFloor or 1))
    local baseGold = (CONFIG.TreasureGoldBase or 100) + floor * (CONFIG.TreasureGoldPerFloor or 50)
    local multiplier = math.max(1, CONFIG.TreasureGoldMultiplier or 5)
    local goldPercent = (stats.goldPercent or 0)
        + GetOverflowLuckGoldBonus()
        + GetHiddenAdminGoldBonusPercent()
    return math.floor(baseGold * (1 + goldPercent / 100) * multiplier)
end

function AddRunGoldReward(amount)
    if trainingModeActive then return 0 end
    amount = math.max(0, math.floor(amount or 0))
    if amount <= 0 then return 0 end
    runGoldReward = (runGoldReward or 0) + amount
    return amount
end

function GetHeroBaseAttackCount()
    local stats = GetBattleEquipmentStats()
    return math.max(1, 3 + stats.attackCount)
end

function GetHeroAttackCount()
    local baseCount = GetHeroBaseAttackCount()
    if awakeningActive then
        return math.max(1, baseCount * 5)
    end
    return baseCount
end

function GetSkillAttackCountMultiplier()
    local attackCount = GetHeroBaseAttackCount()
    return 1 + math.max(0, attackCount - 3) * 0.08
end

function GetEquippedWeaponUpgradeLevel()
    local weapon = GetActiveEquipment().weapon or nil
    if weapon == nil then return 0 end
    return math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, weapon.weaponUpgradeLevel or 0))
end

GetHeroAttackRadius = function()
    local stats = GetBattleEquipmentStats()
    local rangeMult = 1 + (
        GetWeaponUpgradeRangePercent(GetEquippedWeaponUpgradeLevel())
        + (stats.attackRangePercent or 0)
        + GetRoguelikeModifier("attackRangePercent")
    ) / 100
    return CONFIG.AttackRadius * math.max(0.5, rangeMult) * (awakeningActive and 2.0 or 1.0)
end

GetAwakeningDuration = function()
    local stats = GetBattleEquipmentStats()
    return AWAKENING_BASE_DURATION + stats.awakeningDuration
end

function GetSkillScrollDropChanceCap(monsterType)
    local cap
    if monsterType == "boss" then
        cap = CONFIG.BossSkillScrollDropChanceCap
    elseif monsterType == "elite" then
        cap = CONFIG.EliteSkillScrollDropChanceCap
    elseif monsterType == "blood" then
        cap = CONFIG.BloodSkillScrollDropChanceCap
    else
        cap = CONFIG.NormalSkillScrollDropChanceCap
    end
    -- 超级管理员：技能卡掉率上限翻倍（隐藏加成，属性面板不显示）
    if IS_CLOUD_ADMIN == true then
        return cap * 2
    end
    return cap
end

function GetSkillScrollMonsterMultiplier(monsterType)
    if monsterType == "boss" then
        return 5
    elseif monsterType == "elite" then
        return 2
    end
    return 1
end

function GetSkillScrollDropChance(monsterType)
    local baseChance = CONFIG.SkillScrollDropChance or 0.027
    local finalChance = baseChance
    if monsterType == "boss" then
        finalChance = CONFIG.BossSkillScrollDropChance or 0.144
    elseif monsterType == "elite" then
        finalChance = CONFIG.EliteSkillScrollDropChance or 0.054
    end
    if GetLuckSkillScrollDropBonus then
        local skillLuckBonus = GetLuckSkillScrollDropBonus()
        -- 超级管理员：技能卡幸运加成翻倍（隐藏加成，只作用于技能卡，属性面板不显示）
        if IS_CLOUD_ADMIN == true then
            skillLuckBonus = skillLuckBonus * 2
        end
        finalChance = finalChance + skillLuckBonus
    end
    return math.min(GetSkillScrollDropChanceCap(monsterType), finalChance)
end


function RandomDamageByAttack(minMul, maxMul, skill)
    local atk = GetHeroAttackDamage()
    local starMult = GetSkillDamageMultiplier(skill)
    local stats = GetBattleEquipmentStats()
    local skillDamageMult = 1 + (stats.skillDamagePercent or 0) / 100
    local mageSkillMult = 1 + (stats.mageSkillMultiplierPercent or 0) / 100
    local attackCountMult = GetSkillAttackCountMultiplier()
    local baseDamageMult = CONFIG.SkillBaseDamageMultiplier or 0.95
    return atk * (minMul + math.random() * (maxMul - minMul)) * baseDamageMult * starMult * skillDamageMult * mageSkillMult * attackCountMult
end

function ResetDamageStats()
    damageStats = { hero = 0, clone = 0, skills = {}, total = 0 }
    trainingDamageSamples = {}
    damageRankRowsCache = {}
    damageRankRowsCacheTime = -1
    for _, skillId in ipairs(SKILL_ORDER or {}) do
        damageStats.skills[skillId] = 0
    end
end

function IsTrainingDummyMode()
    return trainingModeActive and trainingModeKind == "dummy"
end

function IsTrainingDummyBossTarget()
    return IsTrainingDummyMode() and trainingDummyTargetKind == "boss"
end

function RecordTrainingDamageSample(amount)
    if not IsTrainingDummyMode() then return end
    amount = math.max(0, math.floor(amount or 0))
    if amount <= 0 then return end
    trainingDamageSamples = trainingDamageSamples or {}
    table.insert(trainingDamageSamples, {
        time = math.max(0, trainingElapsedTime or 0),
        amount = amount,
    })
end

function TrimTrainingDamageSamples()
    if not IsTrainingDummyMode() then return end
    local cutoff = math.max(0, (trainingElapsedTime or 0) - 5)
    while #trainingDamageSamples > 0
        and (trainingDamageSamples[1].time or 0) < cutoff do
        table.remove(trainingDamageSamples, 1)
    end
end

function GetTrainingAverageDps()
    local elapsed = math.max(0, trainingElapsedTime or 0)
    if elapsed <= 0 then return 0 end
    return math.max(0, damageStats and damageStats.total or 0) / elapsed
end

function GetTrainingRecentDps()
    local elapsed = math.max(0, trainingElapsedTime or 0)
    if elapsed <= 0 then return 0 end
    TrimTrainingDamageSamples()
    local recentDamage = 0
    for _, sample in ipairs(trainingDamageSamples or {}) do
        recentDamage = recentDamage + math.max(0, sample.amount or 0)
    end
    return recentDamage / math.min(5, elapsed)
end

function RecordDamageStat(sourceId, amount)
    amount = math.max(0, math.floor(amount or 0))
    if amount <= 0 then return end
    damageStats.total = (damageStats.total or 0) + amount
    RecordTrainingDamageSample(amount)
    if sourceId == nil or sourceId == DAMAGE_STAT_HERO_ID then
        damageStats.hero = (damageStats.hero or 0) + amount
        return
    end
    if sourceId == DAMAGE_STAT_CLONE_ID then
        damageStats.clone = (damageStats.clone or 0) + amount
        return
    end
    damageStats.skills = damageStats.skills or {}
    damageStats.skills[sourceId] = (damageStats.skills[sourceId] or 0) + amount
end

function GetDamageSourceId(source)
    if source == nil or source == DAMAGE_STAT_HERO_ID then return DAMAGE_STAT_HERO_ID end
    if type(source) == "table" then
        return source.id or DAMAGE_STAT_HERO_ID
    end
    return tostring(source)
end

function GetExecuteThresholdForMonster(monster)
    if monster == nil
        or monster.isTrainingDummy
        or monster.isBoss
        or monster.type == "boss"
        or monster.type == "treasure"
        or monster.type == "skill_treasure" then
        return 0
    end
    local stats = GetBattleEquipmentStats()
    local threshold = math.min(10, math.max(0, stats.executeThresholdPercent or 0))
    if monster.type == "elite" then
        threshold = threshold * 0.5
    end
    return threshold
end

function DamageMonster(monster, damage, source)
    if monster == nil or monster.hp <= 0 then return 0 end
    if IsBossShieldActive(monster) then
        monster.hitFlash = 0.08
        AddEffect({ type = "gold_drop", x = monster.x, y = monster.y - monster.radius - 12, text = "无敌", life = 0.42, maxLife = 0.42 })
        return 0
    end
    local stats = GetBattleEquipmentStats()
    local sourceId = GetDamageSourceId(source)
    local finalDamage = math.max(0, damage or 0)
    if sourceId ~= DAMAGE_STAT_HERO_ID
        and sourceId ~= DAMAGE_STAT_CLONE_ID then
        finalDamage = finalDamage * (1 + (stats.gemSkillDamagePercent or 0) / 100)
        finalDamage = finalDamage * RollSkillCriticalDamage(source)
    end
    if monster.isBoss == true or monster.type == "elite" then
        finalDamage = finalDamage * (1 + (stats.gemEliteBossDamagePercent or 0) / 100)
    end
    if monster.isTrainingDummy then
        monster.hitFlash = 0.15
        RecordDamageStat(sourceId, finalDamage)
        return finalDamage
    end
    local effectiveDamage = math.min(monster.hp, finalDamage)
    monster.hp = monster.hp - finalDamage
    monster.hitFlash = 0.15
    RecordDamageStat(sourceId, effectiveDamage)

    local executeThreshold = GetExecuteThresholdForMonster(monster)
    if monster.hp > 0
        and (monster.maxHp or 0) > 0
        and executeThreshold > 0
        and monster.hp <= monster.maxHp * executeThreshold / 100 then
        local executeDamage = monster.hp
        monster.hp = 0
        effectiveDamage = effectiveDamage + executeDamage
        RecordDamageStat(sourceId, executeDamage)
    end

    if monster.hp <= 0 then
        battleStepMonsterCount = -1
        battleStepAliveCount = 0
    end
    return effectiveDamage
end

function EnsureAudioScene()
    if audioScene == nil then
        audioScene = Scene()
    end
end

function GetMusicGain()
    local volume = 70
    if playerData.settings and playerData.settings.musicVolume ~= nil then
        volume = playerData.settings.musicVolume
    end
    return 0.55 * math.max(0, math.min(100, volume)) / 100
end

function UpdateBackgroundMusicVolume()
    if bgmSource ~= nil then
        bgmSource.gain = GetMusicGain()
    end
end

function StartBackgroundMusic()
    EnsureAudioScene()
    if bgmSource ~= nil and bgmSource.playing then
        UpdateBackgroundMusicVolume()
        return
    end

    bgmSound = bgmSound or cache:GetResource("Sound", BGM_PATH)
    if bgmSound == nil then
        print("[Audio] 背景音乐加载失败: " .. tostring(BGM_PATH))
        return
    end
    bgmSound.looped = true

    if bgmNode == nil then
        bgmNode = audioScene:CreateChild("BackgroundMusic")
        bgmSource = bgmNode:CreateComponent("SoundSource")
        bgmSource.soundType = SOUND_MUSIC
    end
    bgmSource.gain = GetMusicGain()
    bgmSource:Play(bgmSound)
    print("[Audio] 背景音乐开始播放: Last Bastion Blade")
end

function StopBackgroundMusic()
    if bgmSource ~= nil then
        bgmSource:StopImmediate()
    end
    if bgmNode ~= nil then
        bgmNode:Dispose()
        bgmNode = nil
    end
    bgmSource = nil
end

function PlayHitSfx()
    if playerData.settings and playerData.settings.sfxEnabled == false then return end
    if hitSfxTimer > 0 then return end
    EnsureAudioScene()
    hitSfxSound = hitSfxSound or cache:GetResource("Sound", "audio/sfx/sword_hit.ogg")
    if hitSfxSound == nil then return end
    local soundNode = audioScene:CreateChild("HitSfx")
    local source = soundNode:CreateComponent("SoundSource")
    source.soundType = SOUND_EFFECT
    source.autoRemoveMode = REMOVE_NODE
    local gain = 0.55
    if playerData.settings and playerData.settings.sfxVolume then
        gain = gain * math.max(0, math.min(100, playerData.settings.sfxVolume)) / 100
    end
    source.gain = gain
    source:Play(hitSfxSound)
    if IsTwentyBattleTurboMode() then
        hitSfxTimer = 0.22
    else
        hitSfxTimer = 0.12
    end
end

function AddSkillHitEffect(x, y, color, radius)
    AddEffect({ type = "skill_hit", x = x, y = y, radius = radius or 18, color = color or {255, 220, 90}, life = 0.32, maxLife = 0.32 })
end

function GetRangedMonsterSkillDamageMultiplier(monster)
    if monster and monster.type == "ranged" then
        return 0.7
    end
    return 1.0
end

function DamageMonsterBySkill(monster, damage, color, radius, skill)
    if monster == nil or monster.hp <= 0 then return 0 end
    local scaledDamage = (damage or 0) * GetRangedMonsterSkillDamageMultiplier(monster)
    local effectiveDamage = DamageMonster(monster, scaledDamage, skill)
    AddSkillHitEffect(monster.x, monster.y, color, radius)
    return effectiveDamage
end

function GetBattleStepAliveMonsters()
    if battleStepMonsterCount >= 0
        and battleStepMonsterCount == #monsters then
        return battleStepAliveMonsters, battleStepAliveCount
    end

    local result = battleStepAliveMonsters
    local count = 0
    for _, monster in ipairs(monsters) do
        if monster.hp > 0 then
            count = count + 1
            result[count] = monster
        end
    end
    for index = count + 1, #result do
        result[index] = nil
    end
    battleStepMonsterCount = #monsters
    battleStepAliveCount = count
    return result, count
end

function DamageArea(cx, cy, radius, damage, color, skill, showHitEffect, maxHitEffects)
    if cx == nil then return end
    local r2 = radius * radius
    local hitEffectCount = 0
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local m = aliveMonsters[index]
        local dx = m.x - cx
        local dy = m.y - cy
        if m.hp > 0 and dx * dx + dy * dy <= r2 then
            local canShowHit = showHitEffect ~= false
                and (maxHitEffects == nil or hitEffectCount < maxHitEffects)
            if canShowHit then
                DamageMonsterBySkill(m, damage, color, 16, skill)
                hitEffectCount = hitEffectCount + 1
            else
                local scaledDamage = damage * GetRangedMonsterSkillDamageMultiplier(m)
                DamageMonster(m, scaledDamage, skill)
            end
        end
    end
end


function AllocateSkillUid()
    playerData.nextSkillUid = math.max(1, playerData.nextSkillUid or 1)
    local uid = "skill_" .. tostring(playerData.nextSkillUid)
    playerData.nextSkillUid = playerData.nextSkillUid + 1
    return uid
end

function FindSkillCardByUid(uid)
    if uid == nil then return nil end
    for _, skill in ipairs(playerData.skills or {}) do
        if skill.uid == uid then return skill end
    end
    return nil
end

function GetUnlockedSkillSlotCount()
    return math.max(CONFIG.SkillSlotBaseCount, math.min(CONFIG.SkillSlotMaxCount, playerData.unlockedSkillSlots or CONFIG.SkillSlotBaseCount))
end

function BuildSkillSlotsSaveData()
    local entries = {}
    local rawSlots = type(playerData.skillSlots) == "table" and playerData.skillSlots or {}
    for i = 1, CONFIG.SkillSlotMaxCount do
        entries[i] = {
            slot = i,
            uid = rawSlots[i] or rawSlots[tostring(i)] or "",
        }
    end
    return {
        version = 1,
        slots = entries,
    }
end

function ReadSkillSlotsByIndex(rawSlots)
    local byIndex = {}
    if type(rawSlots) ~= "table" then return byIndex end

    for i = 1, CONFIG.SkillSlotMaxCount do
        local value = rawSlots[i]
        if value == nil then value = rawSlots[tostring(i)] end
        if type(value) == "string" and value ~= "" then
            byIndex[i] = value
        end
    end

    local records = rawSlots.slots
    if type(records) == "table" then
        for _, record in pairs(records) do
            if type(record) == "table" then
                local index = math.tointeger(tonumber(record.slot or record.index))
                local value = record.uid or record.skillUid or record.skillId or record.value
                if index ~= nil
                    and index >= 1
                    and index <= CONFIG.SkillSlotMaxCount
                    and type(value) == "string"
                    and value ~= ""
                then
                    byIndex[index] = value
                end
            end
        end
    end

    return byIndex
end

function CreateEmptySkillLoadout()
    return {
        version = 1,
        slots = {},
    }
end

function NormalizeSkillLoadouts()
    local rawLoadouts = type(playerData.skillLoadouts) == "table"
        and playerData.skillLoadouts
        or {}
    local normalized = {}
    for loadoutIndex = 1, 2 do
        local rawLoadout = rawLoadouts[loadoutIndex]
            or rawLoadouts[tostring(loadoutIndex)]
            or {}
        local rawSlots = type(rawLoadout.slots) == "table"
            and rawLoadout.slots
            or rawLoadout
        local byIndex = {}
        for slotIndex = 1, CONFIG.SkillSlotMaxCount do
            local record = rawSlots[slotIndex]
                or rawSlots[tostring(slotIndex)]
            if type(record) == "table" then
                local uid = record.uid or record.skillUid
                local skillId = record.skillId or record.id
                if type(uid) == "string" and uid == "" then uid = nil end
                if type(skillId) == "string" and skillId == "" then skillId = nil end
                if uid ~= nil or skillId ~= nil then
                    byIndex[slotIndex] = {
                        uid = type(uid) == "string" and uid or nil,
                        skillId = type(skillId) == "string" and skillId or nil,
                        star = math.max(
                            1,
                            math.min(
                                CONFIG.SkillMaxStar or 10,
                                math.floor(tonumber(record.star) or 1)
                            )
                        ),
                    }
                end
            end
        end
        for _, record in pairs(rawSlots) do
            if type(record) == "table" then
                local slotIndex = math.tointeger(tonumber(record.slot or record.index))
                local uid = record.uid or record.skillUid
                local skillId = record.skillId or record.id
                if slotIndex ~= nil
                    and slotIndex >= 1
                    and slotIndex <= CONFIG.SkillSlotMaxCount
                    and (type(uid) == "string" or type(skillId) == "string")
                then
                    byIndex[slotIndex] = {
                        uid = type(uid) == "string" and uid ~= "" and uid or nil,
                        skillId = type(skillId) == "string" and skillId ~= "" and skillId or nil,
                        star = math.max(
                            1,
                            math.min(
                                CONFIG.SkillMaxStar or 10,
                                math.floor(tonumber(record.star) or 1)
                            )
                        ),
                    }
                end
            end
        end
        normalized[loadoutIndex] = {
            version = 1,
            slots = byIndex,
        }
    end
    playerData.skillLoadouts = normalized
    playerData.activeSkillLoadoutIndex = math.max(
        1,
        math.min(2, math.floor(tonumber(playerData.activeSkillLoadoutIndex) or 1))
    )
    return normalized
end

function BuildSkillLoadoutsSaveData()
    NormalizeSkillLoadouts()
    local saveData = {}
    for loadoutIndex = 1, 2 do
        local entries = {}
        local slots = playerData.skillLoadouts[loadoutIndex].slots
        for slotIndex = 1, CONFIG.SkillSlotMaxCount do
            local record = slots[slotIndex]
            table.insert(entries, {
                slot = slotIndex,
                uid = record and record.uid or "",
                skillId = record and record.skillId or "",
                star = record and record.star or 0,
            })
        end
        saveData[loadoutIndex] = {
            version = 1,
            slots = entries,
        }
    end
    return saveData
end

function SaveCurrentSkillLoadout(loadoutIndex)
    NormalizeSkills()
    NormalizeSkillLoadouts()
    loadoutIndex = math.max(1, math.min(2, math.floor(tonumber(loadoutIndex) or 1)))
    local slots = {}
    for slotIndex = 1, CONFIG.SkillSlotMaxCount do
        local skill = FindSkillCardByUid(playerData.skillSlots[slotIndex])
        if skill ~= nil then
            slots[slotIndex] = {
                uid = skill.uid,
                skillId = skill.id,
                star = GetSkillStar(skill),
            }
        end
    end
    playerData.skillLoadouts[loadoutIndex] = {
        version = 1,
        slots = slots,
    }
    playerData.activeSkillLoadoutIndex = loadoutIndex
    saveDirty = true
    return true
end

local function FindSkillLoadoutReplacement(record, usedUids)
    if record == nil or type(record.skillId) ~= "string" then return nil end
    local candidates = {}
    for _, skill in ipairs(playerData.skills or {}) do
        if skill.id == record.skillId and usedUids[skill.uid] ~= true then
            table.insert(candidates, skill)
        end
    end
    table.sort(candidates, function(a, b)
        local starA = GetSkillStar(a)
        local starB = GetSkillStar(b)
        if starA ~= starB then return starA > starB end
        return tostring(a.uid or "") < tostring(b.uid or "")
    end)
    return candidates[1]
end

function ApplySkillLoadout(loadoutIndex)
    NormalizeSkills()
    NormalizeSkillLoadouts()
    loadoutIndex = math.max(1, math.min(2, math.floor(tonumber(loadoutIndex) or 1)))
    local loadout = playerData.skillLoadouts[loadoutIndex]
    local nextSlots = {}
    local usedUids = {}
    local equippedCounts = {}
    local duplicateLimit = math.max(1, CONFIG.SkillEquipDuplicateLimit or 3)
    local replacedCount = 0
    local missingCount = 0

    for slotIndex = 1, GetUnlockedSkillSlotCount() do
        local record = loadout.slots[slotIndex]
        if record ~= nil then
            local skill = FindSkillLoadoutReplacement(record, usedUids)
            if skill ~= nil
                and (equippedCounts[skill.id] or 0) >= duplicateLimit
            then
                skill = nil
            end
            if skill ~= nil and skill.uid ~= record.uid then
                replacedCount = replacedCount + 1
            end
            if skill ~= nil then
                nextSlots[slotIndex] = skill.uid
                usedUids[skill.uid] = true
                equippedCounts[skill.id] = (equippedCounts[skill.id] or 0) + 1
            else
                missingCount = missingCount + 1
            end
        end
    end

    local currentUnequippedCount = CountUnequippedSkillCards()
    local nextUnequippedCount = CountUnequippedSkillCardsForSlots(nextSlots)
    local skillCap = CONFIG.MaxUnequippedSkillCards or 300
    if nextUnequippedCount > skillCap and nextUnequippedCount > currentUnequippedCount then
        print("[InventoryCapacity] 技能方案切换被拒绝: 未装备技能", currentUnequippedCount,
            "→", nextUnequippedCount, "上限", skillCap)
        return nil, nil, "技能背包空间不足，无法应用该方案"
    end

    playerData.skillSlots = nextSlots
    playerData.activeSkillLoadoutIndex = loadoutIndex
    NormalizeSkills()
    InitSkillRuntime()
    saveDirty = true
    return replacedCount, missingCount, nil
end

function IsSkillUidEquipped(uid)
    if uid == nil then return false end
    for i = 1, GetUnlockedSkillSlotCount() do
        if playerData.skillSlots and playerData.skillSlots[i] == uid then return true end
    end
    return false
end

function CountUnequippedSkillCardsForSlots(slots)
    local equippedUids = {}
    for i = 1, GetUnlockedSkillSlotCount() do
        local uid = slots and slots[i] or nil
        if uid ~= nil then equippedUids[uid] = true end
    end
    local count = 0
    for _, skill in ipairs(playerData.skills or {}) do
        if equippedUids[skill.uid] ~= true then
            count = count + 1
        end
    end
    return count
end

function CountUnequippedSkillCards()
    return CountUnequippedSkillCardsForSlots(playerData.skillSlots)
end

function GetSkillStar(skill)
    local star = 1
    if type(skill) == "table" then
        star = skill.star or 1
    end
    return math.max(1, math.min(CONFIG.SkillMaxStar, star))
end

function SnapshotSkillDamageSource(skill)
    if type(skill) ~= "table" then return skill end
    return {
        uid = skill.uid,
        id = skill.id,
        star = GetSkillStar(skill),
    }
end

function GetSkillHighStarLevel(skill)
    return math.max(0, GetSkillStar(skill) - 4)
end

function GetSkillAwakeningLevel(skill)
    return math.max(0, GetSkillStar(skill) - (CONFIG.SkillAwakeningStar or 8) + 1)
end

function IsSkillAwakened(skill)
    return GetSkillAwakeningLevel(skill) > 0
end

function GetSkillDamageMultiplier(skill)
    local star = GetSkillStar(skill)
    local baseBonus = CONFIG.SkillStarDamageBonus or 0.12
    local awakeningBonus = CONFIG.SkillAwakeningDamageBonus or 0.20
    local awakeningStart = CONFIG.SkillAwakeningStar or 8
    local baseStarSteps = math.min(star - 1, awakeningStart - 2)
    local awakeningLevel = GetSkillAwakeningLevel(skill)
    return 1 + baseStarSteps * baseBonus + awakeningLevel * awakeningBonus
end

local SKILL_CRIT_DAMAGE_BY_STAR = {
    [1] = 5, [2] = 10, [3] = 15, [4] = 20, [5] = 25,
    [6] = 35, [7] = 45, [8] = 60, [9] = 75, [10] = 100,
}

function GetSkillCriticalDamagePercent(skill)
    return SKILL_CRIT_DAMAGE_BY_STAR[GetSkillStar(skill)] or 5
end

function ResolveSkillDamageSource(skill)
    if type(skill) == "table" then return skill end
    local skillId = tostring(skill or "")
    local bestSkill = nil
    for _, card in ipairs(playerData.skills or {}) do
        if tostring(card.id or "") == skillId
            and (bestSkill == nil or GetSkillStar(card) > GetSkillStar(bestSkill)) then
            bestSkill = card
        end
    end
    return bestSkill or { id = skillId, star = 1 }
end

function RollSkillCriticalDamage(skill)
    if math.random() >= 0.20 then return 1 end
    return 1 + GetSkillCriticalDamagePercent(ResolveSkillDamageSource(skill)) / 100
end

local function FormatSkillNumber(value)
    local rounded = math.floor((value or 0) * 10 + 0.5) / 10
    if math.abs(rounded - math.floor(rounded + 0.5)) < 0.001 then
        return tostring(math.floor(rounded + 0.5))
    end
    return string.format("%.1f", rounded)
end

local function FormatSkillPercent(value)
    return FormatSkillNumber(value) .. "%"
end

local function AddSkillDamageLines(lines, label, minMultiplier, maxMultiplier, starMultiplier)
    maxMultiplier = maxMultiplier or minMultiplier
    local prefix = label or "每次"
    local baseMin = minMultiplier * 100
    local baseMax = maxMultiplier * 100
    local currentMin = baseMin * starMultiplier
    local currentMax = baseMax * starMultiplier
    local function FormatRange(minValue, maxValue)
        if math.abs(minValue - maxValue) < 0.001 then
            return FormatSkillPercent(minValue)
        end
        return FormatSkillPercent(minValue) .. "–" .. FormatSkillPercent(maxValue)
    end
    table.insert(lines, prefix .. "基础伤害：攻击力" .. FormatRange(baseMin, baseMax))
    table.insert(lines, prefix .. "当前伤害：攻击力" .. FormatRange(currentMin, currentMax))
    return currentMin, currentMax
end

local function AddSkillTotalDamageLine(lines, hitCount, minMultiplier, maxMultiplier, starMultiplier)
    maxMultiplier = maxMultiplier or minMultiplier
    local totalMin = minMultiplier * hitCount * starMultiplier * 100
    local totalMax = maxMultiplier * hitCount * starMultiplier * 100
    local totalText = FormatSkillPercent(totalMin)
    if math.abs(totalMin - totalMax) >= 0.001 then
        totalText = totalText .. "–" .. FormatSkillPercent(totalMax)
    end
    table.insert(lines, "全部命中总伤害：攻击力" .. totalText)
end

function GetSkillCurrentDescription(skill, equippedSlot)
    if skill == nil then return "暂无技能简介" end
    local id = skill.id
    local star = GetSkillStar(skill)
    local high = GetSkillHighStarLevel(skill)
    local awakening = GetSkillAwakeningLevel(skill)
    local starMultiplier = GetSkillDamageMultiplier(skill)
    local effectLines = {}
    local awakeningLines = {}
    local hasDamage = false

    if id == "thunder" then
        local strikeCount = 11 + high + awakening * 3
        table.insert(effectLines, "随机攻击存活敌人，优先避免重复目标；目标不足时可重复命中。")
        table.insert(effectLines, "当前雷击次数：" .. tostring(strikeCount) .. "次")
        AddSkillDamageLines(effectLines, "雷击", 0.48, 0.64, starMultiplier)
        hasDamage = true
    elseif id == "fireball" then
        local volleyCount = 2 + (awakening > 0 and 1 or 0)
        if high >= 3 then volleyCount = volleyCount + 1 end
        if high >= 6 then volleyCount = volleyCount + 1 end
        local radius = 70 * (1 + high * 0.05 + awakening * 0.10)
        table.insert(effectLines, "每发重新锁定当前生命值最高的敌人。")
        table.insert(effectLines, "当前火球数量：" .. tostring(volleyCount) .. "发")
        table.insert(effectLines, "爆炸半径：" .. FormatSkillNumber(radius))
        AddSkillDamageLines(effectLines, "火球", 1.65, 2.25, starMultiplier)
        if high > 0 then
            table.insert(effectLines, "溅射伤害：主目标实际伤害的35%")
        else
            table.insert(effectLines, "当前星级尚未解锁溅射伤害。")
        end
        hasDamage = true
    elseif id == "flying_sword" then
        local swordCount = 28 + high * 2 + awakening * 4
        local maxHits = 6 + math.floor(high / 2)
        local range = (CONFIG.SkillAreaRadius + 76)
            * (1 + high * 0.025 + awakening * 0.05)
        table.insert(effectLines, "围绕密集区域发射飞剑，找不到有效目标的飞剑不会造成伤害。")
        table.insert(effectLines, "当前飞剑数量：" .. tostring(swordCount) .. "把")
        table.insert(effectLines, "同一目标最多命中：" .. tostring(maxHits) .. "把")
        table.insert(effectLines, "覆盖范围：" .. FormatSkillNumber(range))
        AddSkillDamageLines(effectLines, "飞剑", 0.25, 0.33, starMultiplier)
        hasDamage = true
    elseif id == "dart" then
        local dartCount = 5 + high + awakening * 2
        table.insert(effectLines, "优先追击不同的低生命敌人，目标不足时可重复命中。")
        table.insert(effectLines, "当前飞镖数量：" .. tostring(dartCount) .. "把")
        AddSkillDamageLines(effectLines, "飞镖", 0.55, 0.72, starMultiplier)
        hasDamage = true
    elseif id == "shield" then
        local layers = GetShieldLayers(skill)
        table.insert(effectLines, "将基地护盾刷新至至少" .. tostring(layers) .. "层，不与现有层数直接相加。")
        if awakening > 0 then
            local radius = 68 + awakening * 14
            local reflectMultiplier = 0.22 + awakening * 0.10
            table.insert(awakeningLines, "每吸收1次真实攻击，触发1次范围反震。")
            table.insert(awakeningLines, "反震范围：" .. FormatSkillNumber(radius))
            AddSkillDamageLines(awakeningLines, "反震", reflectMultiplier, reflectMultiplier, starMultiplier)
            AddSkillTotalDamageLine(awakeningLines, layers, reflectMultiplier, reflectMultiplier, starMultiplier)
            if awakening >= 3 then
                table.insert(awakeningLines, "反震额外冻结范围内敌人0.5秒。")
            end
            hasDamage = true
        end
    elseif id == "heal" then
        local healRatio = 0.03 + (star - 1) * 0.01 + high * 0.005
        table.insert(effectLines, "恢复基地已损失生命的" .. FormatSkillPercent(healRatio * 100) .. "。")
