            table.insert(awakeningLines, "0.7秒后在密集区域触发霜爆。")
            table.insert(awakeningLines, "霜爆范围：" .. tostring(62 + awakening * 16))
            table.insert(awakeningLines, "霜爆冻结：" .. FormatSkillNumber(0.25 * awakening) .. "秒")
