    elseif id == "meteor" then
        local radius = 98 * (1 + high * 0.04)
        local delay = math.max(0.35, 0.55 - high * 0.02)
        table.insert(effectLines, "锁定施放时的密集区域，延迟" .. FormatSkillNumber(delay) .. "秒落地。")
        table.insert(effectLines, "爆炸范围：" .. FormatSkillNumber(radius))
