    elseif id == "blackhole" then
        local duration = 2.6 + (star - 1) * 0.15 + high * 0.1
        local radius = CONFIG.BlackHoleRadius + high * 4
        table.insert(effectLines, "施放时造成1次范围伤害，随后持续拉拽敌人，不再造成持续伤害。")
