    elseif id == "blade_orbit" then
        local duration = 2.4 + high * 0.12
        local tickCount = 6 + math.floor(high / 2)
        local radius = 118 + high * 3
        table.insert(effectLines, "以英雄当前位置为中心持续移动并伤害周围敌人。")
        table.insert(effectLines, "范围：" .. tostring(radius) .. "，持续：" .. FormatSkillNumber(duration) .. "秒")
