        hasDamage = true
    elseif id == "flame_zone" then
        local duration = 3.0 + high * 0.12
        local tickCount = 8 + math.floor(high / 2)
        local radius = 92 + high * 3
        table.insert(effectLines, "在施放时的密集区域生成固定火场。")
