        AddSkillDamageLines(effectLines, "每段", 0.16, 0.16, starMultiplier)
        AddSkillTotalDamageLine(effectLines, tickCount, 0.16, 0.16, starMultiplier)
        hasDamage = true
    elseif id == "returning_axe" then
        local width = 34 + high * 3
        local maxTargets = 6 + high
        table.insert(effectLines, "锁定最远敌人，战斧去程与回程各切割1次。")
