        hasDamage = true
    elseif id == "ground_slam" then
        local radius = 112 + high * 3
        local normalDuration, eliteDuration = GetGroundSlamSlowDurations(skill)
        table.insert(effectLines, "重击基地前方区域，伤害范围内全部敌人。")
        table.insert(effectLines, "范围：" .. tostring(radius))
        table.insert(effectLines, "普通敌人减速45%，持续" .. FormatSkillNumber(normalDuration) .. "秒。")
