        AddSkillDamageLines(effectLines, "重击", 1.15, 1.45, starMultiplier)
        hasDamage = true
    end

    if awakening > 0 and id ~= "shield" and id ~= "heal" and id ~= "freeze" then
        local rawDamage = 0.30 + awakening * 0.08
        if id == "thunder" or id == "ground_slam" or id == "storm_push" or id == "holy_judgement" then
            table.insert(awakeningLines, "0.3秒后在密集区域触发1次余波。")
            table.insert(awakeningLines, "余波范围：" .. tostring(62 + awakening * 16))
            AddSkillDamageLines(awakeningLines, "余波", rawDamage, rawDamage, starMultiplier)
            if id == "storm_push" then
                table.insert(awakeningLines, "余波减速：" .. FormatSkillPercent((0.2 + awakening * 0.05) * 100) .. "，持续1秒。")
            end
        elseif id == "fireball" or id == "meteor" or id == "blackhole"
            or id == "blade_orbit" or id == "flame_zone" or id == "poison_mist" then
            local tickCount = 2 + awakening
            local duration = 1.3 + awakening * 0.35
            local tickDamage = rawDamage * 0.65
            table.insert(awakeningLines, "生成觉醒伤害区域，范围：" .. tostring(64 + awakening * 14)
                .. "，持续：" .. FormatSkillNumber(duration) .. "秒。")
            table.insert(awakeningLines, "觉醒伤害段数：" .. tostring(tickCount) .. "段")
            AddSkillDamageLines(awakeningLines, "觉醒每段", tickDamage, tickDamage, starMultiplier)
            AddSkillTotalDamageLine(awakeningLines, tickCount, tickDamage, tickDamage, starMultiplier)
            if id == "blackhole" or id == "blade_orbit" or id == "flame_zone" then
                local terminalDamage = rawDamage * (1.0 + awakening * 0.25)
                AddSkillDamageLines(awakeningLines, "终结爆发", terminalDamage, terminalDamage, starMultiplier)
            end
        elseif id == "flying_sword" or id == "dart" or id == "chain_lightning" then
            local repeats = id == "dart" and awakening or 1
            table.insert(awakeningLines, "延迟追击当前生命值最高的敌人。")
            table.insert(awakeningLines, "觉醒追击次数：" .. tostring(repeats) .. "次")
            AddSkillDamageLines(awakeningLines, "追击", rawDamage, rawDamage, starMultiplier)
            if id == "chain_lightning" then
                table.insert(awakeningLines, "每次追击在目标周围追加55%伤害的电击爆裂。")
                table.insert(awakeningLines, "爆裂范围：" .. tostring(38 + awakening * 10))
            end
        elseif id == "piercing_lance" or id == "returning_axe" or id == "sword_wave" then
            local segmentDamage = rawDamage * 1.35
