            table.insert(awakeningLines, "宽度：" .. tostring(38 + awakening * 8)
                .. "，最多命中：" .. tostring(4 + awakening * 2) .. "个目标")
            AddSkillDamageLines(awakeningLines, "追击", segmentDamage, segmentDamage, starMultiplier)
        end
        hasDamage = true
    end

    local sections = { "【当前效果】\n" .. table.concat(effectLines, "\n") }
    if hasDamage then
        table.insert(sections, "【技能卡伤害】\n当前星级伤害倍率："
            .. FormatSkillPercent(starMultiplier * 100))
    end
    if #awakeningLines > 0 then
        table.insert(sections, "【觉醒" .. tostring(awakening) .. "阶】\n"
            .. table.concat(awakeningLines, "\n"))
    elseif awakening <= 0 then
        table.insert(sections, "【觉醒】\n8★解锁专属觉醒效果。")
    end
    if hasDamage then
        local critDamage = GetSkillCriticalDamagePercent(skill)
        table.insert(sections, "【技能暴击】\n技能暴击率：20%\n技能暴击伤害：+"
            .. FormatSkillPercent(critDamage)
            .. "\n暴击倍率：" .. FormatSkillPercent(100 + critDamage)
            .. "\n每次伤害独立判定暴击；装备暴击不影响技能。")
    end

    local baseCooldown = GetSkillBaseCooldown(skill)
    local starCooldown = math.max(1.0, baseCooldown * (1 - 0.04 * awakening))
    local cooldownLines = {
        "基础冷却：" .. FormatSkillNumber(baseCooldown) .. "秒",
        "当前星级冷却：" .. FormatSkillNumber(starCooldown) .. "秒",
    }
    if equippedSlot ~= nil then
        table.insert(cooldownLines, "装备后实战冷却："
            .. FormatSkillNumber(GetSkillCooldown(equippedSlot, skill)) .. "秒")
    else
        table.insert(cooldownLines, "装备后实战冷却：装备后显示")
    end
    table.insert(sections, "【冷却】\n" .. table.concat(cooldownLines, "\n"))
    table.insert(sections, "说明：当前伤害只计算技能卡自身星级与觉醒，不计装备、宝石、局内增益和敌人减伤。")
    return table.concat(sections, "\n\n")
end

NormalizeSkills = function()
    playerData.skills = playerData.skills or {}
    playerData.skillSlots = ReadSkillSlotsByIndex(playerData.skillSlots)
    playerData.unlockedSkillSlots = GetUnlockedSkillSlotCount()
    playerData.nextSkillUid = math.max(1, playerData.nextSkillUid or 1)

    local normalized = {}
    local normalizedByUid = {}
    local usedUids = {}
    local maxUidNumber = 0
    for _, skill in ipairs(playerData.skills) do
        local skillId = skill.id or skill.skillId
        local def = GetSkillDef(skillId)
        if def then
            local uid = skill.uid
            if uid == nil or usedUids[uid] then
                uid = AllocateSkillUid()
            end
            usedUids[uid] = true
            local uidNumber = tonumber(string.match(uid, "skill_(%d+)"))
            if uidNumber then maxUidNumber = math.max(maxUidNumber, uidNumber) end
            local star = math.max(1, math.min(CONFIG.SkillMaxStar, skill.star or 1))
            local normalizedSkill = {
                uid = uid,
                id = skillId,
                name = def.name,
                desc = def.desc,
                icon = def.icon,
                star = star,
                cooldown = GetSkillBaseCooldown(skillId),
            }
            normalized[#normalized + 1] = normalizedSkill
            normalizedByUid[uid] = normalizedSkill
        end
    end
    playerData.skills = normalized
    playerData.nextSkillUid = math.max(playerData.nextSkillUid or 1, maxUidNumber + 1)

    local slots = {}
    local usedSlotUids = {}
    local equippedSkillCounts = {}
    local duplicateLimit = math.max(1, CONFIG.SkillEquipDuplicateLimit or 3)

    local function TryAssignSkillSlot(index, card)
        if card == nil or usedSlotUids[card.uid] then return false end
        local count = equippedSkillCounts[card.id] or 0
        if count >= duplicateLimit then return false end
        slots[index] = card.uid
        usedSlotUids[card.uid] = true
        equippedSkillCounts[card.id] = count + 1
        return true
    end

    for i = 1, playerData.unlockedSkillSlots do
        local slotValue = playerData.skillSlots[i]
        local card = normalizedByUid[slotValue]
        if card then
            TryAssignSkillSlot(i, card)
        elseif slotValue ~= nil then
            for _, skill in ipairs(playerData.skills) do
                if skill.id == slotValue and TryAssignSkillSlot(i, skill) then
                    break
                end
            end
        end
    end
    playerData.skillSlots = slots
end

GetEquippedSkills = function()
    if currentScreen == "playing" and battleRuntimeCacheReady then
        return battleEquippedSkillsCache
    end
    NormalizeSkills()
    local equipped = {}
    for i = 1, GetUnlockedSkillSlotCount() do
        local skill = FindSkillCardByUid(playerData.skillSlots[i])
        if skill then
            table.insert(equipped, {
                uid = skill.uid,
                id = skill.id,
                name = skill.name,
                desc = skill.desc,
                icon = skill.icon,
                star = skill.star or 1,
                cooldown = GetSkillBaseCooldown(skill.id),
                slot = i,
            })
        end
    end
    return equipped
end

function GetSkillSynergyDef(synergyId)
    return SKILL_SYNERGY_DEFS and SKILL_SYNERGY_DEFS[synergyId] or nil
end

function NormalizeSkillSynergy()
    playerData.skillSynergy = NormalizeSkillSynergyData(playerData.skillSynergy)
    return playerData.skillSynergy
end

local function GetEquippedSkillStarsById()
    local stars = {}
    for _, skill in ipairs(GetEquippedSkills()) do
        local current = stars[skill.id]
        stars[skill.id] = math.max(current or 0, GetSkillStar(skill))
    end
    return stars
end

function RebuildBattleSynergyRuntime()
    local selectedIds = GetRunSkillSynergyIds()
    local stars = GetEquippedSkillStarsById()
    local byId = {}
    for _, synergyId in ipairs(selectedIds) do
        local def = GetSkillSynergyDef(synergyId)
        if def ~= nil then
            local firstStar = stars[def.skills[1]]
            local secondStar = stars[def.skills[2]]
            local enabled = firstStar ~= nil and secondStar ~= nil
            local minimumStar = enabled and math.min(firstStar, secondStar) or 0
            local awakeningLevel = math.max(0, math.min(3, minimumStar - 7))
            byId[synergyId] = {
                enabled = enabled,
                componentStars = enabled and {
                    [def.skills[1]] = firstStar,
                    [def.skills[2]] = secondStar,
                } or {},
                minimumStar = minimumStar,
                awakeningLevel = awakeningLevel,
                firstSkillId = nil,
                windowRemaining = 0,
                cooldownRemaining = 0,
            }
        end
    end
    battleSynergyRuntime = {
        selectedIds = selectedIds,
        byId = byId,
    }
end

function ClearBattleSynergyRuntime()
    battleSynergyRuntime = {
        selectedIds = {},
        byId = {},
    }
end

function GetSkillSynergyDamageMultiplier(synergyId)
    local runtime = battleSynergyRuntime.byId
        and battleSynergyRuntime.byId[synergyId]
        or nil
    local minimumStar = runtime and runtime.minimumStar or 0
    local lowStarBonus = math.max(0, math.min(minimumStar, 7) - 1) * 0.06
    local awakeningBonus = math.max(0, minimumStar - 7) * 0.12
    return 1 + lowStarBonus + awakeningBonus
end

function GetSkillSynergyCenter()
    local cx, cy = FindClusterCenter(CONFIG.SkillClusterRadius)
    return cx or hero.x, cy or hero.y
end

function ApplySkillSynergyStormPush(cx, cy, radius)
    local r2 = radius * radius
    for _, m in ipairs(monsters) do
        if m.hp > 0 then
            local dx = m.x - cx
            local dy = m.y - cy
            local d2 = dx * dx + dy * dy
            if d2 <= r2 and d2 > 0 then
                local distance = math.sqrt(d2)
                local push = 72 * (m.isBoss and 0.6 or 1.0)
                AddMonsterControlDisplacement(m, dx / distance * push, dy / distance * push)
            end
        end
    end
end

function TriggerSkillSynergy(synergyId)
    local def = GetSkillSynergyDef(synergyId)
    if def == nil then return end
    local runtime = battleSynergyRuntime.byId
        and battleSynergyRuntime.byId[synergyId]
        or nil
    local awakeningLevel = runtime and runtime.awakeningLevel or 0
    local starMultiplier = GetSkillSynergyDamageMultiplier(synergyId)
    local skill = { id = synergyId, star = 1 }
    local cx, cy = GetSkillSynergyCenter()
    if synergyId == "overload_grid" then
        local radius = GetSkillAreaRadius(122)
        DamageArea(cx, cy, radius, RandomDamageByAttack(0.58, 0.58, skill) * starMultiplier, {100, 220, 255}, synergyId, true, 10)
        AddEffect({ type = "synergy_burst", x = cx, y = cy, radius = radius, color = {100, 220, 255}, life = 0.55, maxLife = 0.55 })
        if awakeningLevel >= 1 then
            AddEffect({
                type = "awakening_delay", gameplayEffect = true,
                x = cx, y = cy, radius = GetSkillAreaRadius(96 + awakeningLevel * 12),
                life = 0.45, maxLife = 0.45,
                damage = RandomDamageByAttack(0.40 + awakeningLevel * 0.08, 0.40 + awakeningLevel * 0.08, skill) * starMultiplier,
                color = {125, 235, 255}, skillId = synergyId,
            })
        end
    elseif synergyId == "molten_bombardment" then
        local radius = GetSkillAreaRadius(110)
        AddEffect({ type = "synergy_flame", gameplayEffect = true, x = cx, y = cy, radius = radius, life = 4.5, maxLife = 4.5, tickTimer = 0.5, tickInterval = 0.5, remainingTicks = 9, damage = RandomDamageByAttack(0.32, 0.32, skill) * starMultiplier, skillId = synergyId })
        if awakeningLevel >= 1 then
            local tickDamage = RandomDamageByAttack(0.24 + awakeningLevel * 0.06, 0.24 + awakeningLevel * 0.06, skill) * starMultiplier
            AddEffect({
                type = "awakening_zone", gameplayEffect = true,
                x = cx, y = cy, radius = GetSkillAreaRadius(92 + awakeningLevel * 12),
                life = 1.5 + awakeningLevel * 0.5, maxLife = 1.5 + awakeningLevel * 0.5,
                tickTimer = 0, tickInterval = 0.45, remainingTicks = 3 + awakeningLevel,
                damage = tickDamage, terminalDamage = tickDamage * (1.15 + awakeningLevel * 0.15),
                color = {255, 105, 35}, skillId = synergyId,
            })
        end
    elseif synergyId == "sword_storm" then
        local target = FindNearestAliveMonster(hero.x, hero.y)
        local dx, dy = target and target.x - hero.x or 1, target and target.y - hero.y or 0
        local distance = math.max(1, math.sqrt(dx * dx + dy * dy))
        local nx, ny = dx / distance, dy / distance
        for offset = -1, 1 do
            local px, py = -ny * offset * 82, nx * offset * 82
            DamageSkillAlongSegment(hero.x + px, hero.y + py, hero.x + nx * 465 + px, hero.y + ny * 465 + py, 56, RandomDamageByAttack(0.72, 0.72, skill) * starMultiplier, synergyId, 12, {190, 220, 255})
        end
        if awakeningLevel >= 1 then
            for index = 1, awakeningLevel do
                local offset = (index - (awakeningLevel + 1) * 0.5) * 82
                local px, py = -ny * offset, nx * offset
                AddEffect({
                    type = "awakening_segment", gameplayEffect = true,
                    x1 = hero.x + nx * 465 + px, y1 = hero.y + ny * 465 + py,
                    x2 = hero.x + px, y2 = hero.y + py,
                    width = 44 + awakeningLevel * 6,
                    damage = RandomDamageByAttack(0.38 + awakeningLevel * 0.08, 0.38 + awakeningLevel * 0.08, skill) * starMultiplier,
                    skillId = synergyId, maxTargets = 8 + awakeningLevel * 2,
                    color = {215, 235, 255}, life = 0.42 + index * 0.10, maxLife = 0.42 + index * 0.10,
                })
            end
        end
    elseif synergyId == "execution_horn" then
        local target = FindFarthestAliveMonster(hero.x, hero.y)
        if target ~= nil then
            local damage = RandomDamageByAttack(1.00, 1.00, skill) * starMultiplier
            DamageSkillAlongSegment(hero.x, hero.y, target.x, target.y, 50, damage, synergyId, 10, {255, 190, 80})
            AddEffect({ type = "synergy_axe", gameplayEffect = true, x1 = hero.x, y1 = hero.y, x2 = target.x, y2 = target.y, width = 50, damage = damage, skillId = synergyId, maxTargets = 10, life = 0.8, maxLife = 0.8, returnHit = false })
            if awakeningLevel >= 1 then
                AddEffect({
                    type = "awakening_target", gameplayEffect = true,
                    target = target, life = 0.55, maxLife = 0.55,
                    repeats = awakeningLevel,
                    damage = RandomDamageByAttack(0.44 + awakeningLevel * 0.10, 0.44 + awakeningLevel * 0.10, skill) * starMultiplier,
                    color = {255, 210, 110}, skillId = synergyId,
                })
            end
        end
    elseif synergyId == "sanctuary_guard" then
        local missingHp = math.max(0, base.maxHp - base.hp)
        base.hp = math.min(base.maxHp, base.hp + missingHp * 0.15)
        local previousShield = base.shield or 0
        base.shield = math.max(previousShield, 3)
        if base.shield > previousShield then
            base.shieldAwakeningLevel = 0
            base.shieldDamageSource = nil
        end
        AddEffect({ type = "synergy_heal", x = base.x, y = base.y - CONFIG.BaseHeight * 0.35, life = 0.9, maxLife = 0.9 })
        if awakeningLevel >= 1 then
            AddEffect({
                type = "awakening_delay", gameplayEffect = true,
                x = base.x, y = base.y, radius = GetSkillAreaRadius(82 + awakeningLevel * 14),
                life = 0.75, maxLife = 0.75,
                damage = RandomDamageByAttack(0.30 + awakeningLevel * 0.08, 0.30 + awakeningLevel * 0.08, skill) * starMultiplier,
                color = {255, 240, 160}, skillId = synergyId,
            })
        end
    elseif synergyId == "absolute_zero" then
        local radius = GetSkillAreaRadius(145)
        ApplyFreezeArea(cx, cy, radius, 2.1)
        AddEffect({ type = "synergy_cold", x = cx, y = cy, radius = radius, life = 0.6, maxLife = 0.6 })
        for index = 1, 5 do
            AddEffect({ type = "synergy_cold_tick", gameplayEffect = true, x = cx, y = cy, radius = radius, tickTimer = 0.16 * index, life = 0.16 * index + 0.05, maxLife = 0.16 * index + 0.05, damage = RandomDamageByAttack(0.44, 0.44, skill) * starMultiplier, skillId = synergyId })
        end
        if awakeningLevel >= 1 then
            local tickDamage = RandomDamageByAttack(0.25 + awakeningLevel * 0.06, 0.25 + awakeningLevel * 0.06, skill) * starMultiplier
            AddEffect({
                type = "awakening_zone", gameplayEffect = true,
                x = cx, y = cy, radius = GetSkillAreaRadius(94 + awakeningLevel * 14),
                life = 1.5 + awakeningLevel * 0.5, maxLife = 1.5 + awakeningLevel * 0.5,
                tickTimer = 0, tickInterval = 0.45, remainingTicks = 2 + awakeningLevel,
                damage = tickDamage, terminalDamage = tickDamage * (1.2 + awakeningLevel * 0.15),
                color = {150, 225, 255}, skillId = synergyId,
            })
        end
    elseif synergyId == "meteor_crater" then
        local radius = GetSkillAreaRadius(134)
        DamageAreaWithGroundSlamSlow(
            cx,
            cy,
            radius,
            RandomDamageByAttack(2.15, 2.15, skill) * starMultiplier,
            {255, 125, 55},
            synergyId,
            skill,
            10
        )
        AddEffect({ type = "synergy_burst", x = cx, y = cy, radius = radius, color = {255, 125, 55}, life = 0.72, maxLife = 0.72 })
        if awakeningLevel >= 1 then
            AddEffect({
                type = "awakening_delay", gameplayEffect = true,
                x = cx, y = cy, radius = GetSkillAreaRadius(104 + awakeningLevel * 14),
                life = 0.65, maxLife = 0.65,
                damage = RandomDamageByAttack(0.58 + awakeningLevel * 0.12, 0.58 + awakeningLevel * 0.12, skill) * starMultiplier,
                slowScale = math.max(0.45, 0.74 - awakeningLevel * 0.08),
                color = {255, 145, 65}, skillId = synergyId,
            })
        end
    elseif synergyId == "miasma_storm" then
        local radius = GetSkillAreaRadius(120)
        AddEffect({ type = "synergy_poison", gameplayEffect = true, x = cx, y = cy, radius = radius, life = 3.5, maxLife = 3.5, tickTimer = 0.5, tickInterval = 0.5, remainingTicks = 7, damage = RandomDamageByAttack(0.35, 0.35, skill) * starMultiplier, skillId = synergyId })
        ApplySkillSynergyStormPush(cx, cy, radius)
        if awakeningLevel >= 1 then
            AddEffect({
                type = "synergy_storm_echo", gameplayEffect = true,
                x = cx, y = cy, radius = GetSkillAreaRadius(92 + awakeningLevel * 14),
                life = 1.4 + awakeningLevel * 0.5, maxLife = 1.4 + awakeningLevel * 0.5,
                tickTimer = 0, tickInterval = 0.45, remainingTicks = 2 + awakeningLevel,
                damage = RandomDamageByAttack(0.24 + awakeningLevel * 0.07, 0.24 + awakeningLevel * 0.07, skill) * starMultiplier,
                skillId = synergyId,
            })
        end
    elseif synergyId == "radiant_annihilation" then
        local target = FindNearestAliveMonster(hero.x, hero.y)
        if target ~= nil then
            DamageMonsterBySkill(target, RandomDamageByAttack(0.72, 0.72, skill) * starMultiplier, {255, 235, 140}, 10, synergyId)
        end
        local previousShield = base.shield or 0
        base.shield = math.max(previousShield, 1 + math.floor((runtime and runtime.minimumStar or 1) / 4))
        if base.shield > previousShield then
            base.shieldAwakeningLevel = 0
            base.shieldDamageSource = nil
        end
        AddEffect({ type = "synergy_heal", x = base.x, y = base.y - CONFIG.BaseHeight * 0.35, life = 0.75, maxLife = 0.75 })
        if awakeningLevel >= 1 then
            local radius = GetSkillAreaRadius(82 + awakeningLevel * 10)
            local burstX, burstY = target and target.x or cx, target and target.y or cy
            DamageArea(burstX, burstY, radius, RandomDamageByAttack(0.42 + awakeningLevel * 0.08, 0.42 + awakeningLevel * 0.08, skill) * starMultiplier, {255, 225, 120}, synergyId, true, 8)
            AddEffect({ type = "synergy_burst", x = burstX, y = burstY, radius = radius, color = {255, 230, 135}, life = 0.45, maxLife = 0.45 })
        end
    elseif synergyId == "gravity_lance" then
        local radius = GetSkillAreaRadius(108 + awakeningLevel * 8)
        local target = FindNearestAliveMonster(cx, cy)
        local tx, ty = target and target.x or cx + 1, target and target.y or cy
        local dx, dy = tx - cx, ty - cy
        local distance = math.max(1, math.sqrt(dx * dx + dy * dy))
        local nx, ny = dx / distance, dy / distance
        DamageSkillAlongSegment(cx, cy, cx + nx * 430, cy + ny * 430, 42 + awakeningLevel * 4, RandomDamageByAttack(0.88, 0.88, skill) * starMultiplier, synergyId, 8 + awakeningLevel, {190, 220, 255})
        AddEffect({ type = "synergy_cold", x = cx, y = cy, radius = radius, life = 0.38, maxLife = 0.38 })
        if awakeningLevel >= 1 then
            DamageSkillAlongSegment(cx, cy, cx - nx * 360, cy - ny * 360, 34 + awakeningLevel * 4, RandomDamageByAttack(0.32 + awakeningLevel * 0.07, 0.32 + awakeningLevel * 0.07, skill) * starMultiplier, synergyId, 6, {145, 195, 255})
        end
    elseif synergyId == "frostfire_prison" then
        local radius = GetSkillAreaRadius(112)
        ApplyFreezeArea(cx, cy, radius, 1.35)
        AddEffect({ type = "synergy_flame", gameplayEffect = true, x = cx, y = cy, radius = radius, life = 2.5, maxLife = 2.5, tickTimer = 0.5, tickInterval = 0.5, remainingTicks = 5, damage = RandomDamageByAttack(0.27, 0.27, skill) * starMultiplier, skillId = synergyId })
        if awakeningLevel >= 1 then
            local burstRadius = GetSkillAreaRadius(76 + awakeningLevel * 9)
            DamageArea(cx, cy, burstRadius, RandomDamageByAttack(0.48 + awakeningLevel * 0.08, 0.48 + awakeningLevel * 0.08, skill) * starMultiplier, {255, 155, 70}, synergyId, true, 8)
            AddEffect({ type = "synergy_burst", x = cx, y = cy, radius = burstRadius, color = {255, 160, 80}, life = 0.48, maxLife = 0.48 })
        end
    elseif synergyId == "venomous_execution" then
        local radius = GetSkillAreaRadius(105)
        AddEffect({ type = "synergy_poison", gameplayEffect = true, x = cx, y = cy, radius = radius, life = 2.5, maxLife = 2.5, tickTimer = 0.5, tickInterval = 0.5, remainingTicks = 5, damage = RandomDamageByAttack(0.22, 0.22, skill) * starMultiplier, skillId = synergyId })
        local candidates = {}
        for _, monster in ipairs(monsters) do
            local dx, dy = monster.x - cx, monster.y - cy
            if monster.hp > 0 and dx * dx + dy * dy <= radius * radius then table.insert(candidates, monster) end
        end
        table.sort(candidates, function(a, b) return a.hp > b.hp end)
        for index = 1, math.min(#candidates, 3 + awakeningLevel) do
            AddEffect({ type = "awakening_target", gameplayEffect = true, target = candidates[index], life = 0.28, maxLife = 0.28, repeats = 1, damage = RandomDamageByAttack(0.36 + awakeningLevel * 0.06, 0.36 + awakeningLevel * 0.06, skill) * starMultiplier, color = {150, 255, 120}, skillId = synergyId })
        end
    end
end

function RecordSkillSynergyCast(skill)
    local skillId = type(skill) == "table" and skill.id or skill
    for _, synergyId in ipairs(battleSynergyRuntime.selectedIds or {}) do
        local runtime = battleSynergyRuntime.byId
            and battleSynergyRuntime.byId[synergyId]
            or nil
        local def = GetSkillSynergyDef(synergyId)
        if runtime ~= nil and runtime.enabled and def ~= nil
            and runtime.cooldownRemaining <= 0 then
            local isComponent = skillId == def.skills[1]
                or skillId == def.skills[2]
            if isComponent then
                if runtime.firstSkillId == nil then
                    runtime.firstSkillId = skillId
                    runtime.windowRemaining = CONFIG.SkillSynergyWindow or 3.0
                elseif runtime.firstSkillId ~= skillId then
                    if runtime.windowRemaining > 0 then
                        TriggerSkillSynergy(synergyId)
                        runtime.firstSkillId = nil
                        runtime.windowRemaining = 0
                        runtime.cooldownRemaining = def.cooldown
                            or CONFIG.SkillSynergyDefaultCooldown
                            or 20.0
                    else
                        runtime.firstSkillId = skillId
                        runtime.windowRemaining = CONFIG.SkillSynergyWindow or 3.0
                    end
                end
            end
        end
    end
end

function UpdateSkillSynergy(dt)
    for _, synergyId in ipairs(battleSynergyRuntime.selectedIds or {}) do
        local runtime = battleSynergyRuntime.byId
            and battleSynergyRuntime.byId[synergyId]
            or nil
        if runtime ~= nil and runtime.enabled then
            runtime.cooldownRemaining = math.max(
                0,
                (runtime.cooldownRemaining or 0) - dt
            )
            if runtime.windowRemaining > 0 then
                runtime.windowRemaining = runtime.windowRemaining - dt
                if runtime.windowRemaining <= 0 then
                    runtime.firstSkillId = nil
                    runtime.windowRemaining = 0
                end
            end
        end
    end
end

function RebuildBattleRuntimeCache()
    battleEquipmentStatsCache = GetEquipmentStats()
    battleEquippedSkillsCache = {}
    battleSkillCooldownCache = {}
    battleCloneProtocolId = GetCloneProtocolId(1)
    battleCloneFocusTarget = nil
    battleCloneFocusScanTimer = 0
    NormalizeSkills()
    for i = 1, GetUnlockedSkillSlotCount() do
        local skill = FindSkillCardByUid(playerData.skillSlots[i])
        if skill then
            local cachedSkill = {
                uid = skill.uid,
                id = skill.id,
                name = skill.name,
                desc = skill.desc,
                icon = skill.icon,
                star = skill.star or 1,
                cooldown = GetSkillBaseCooldown(skill.id),
                slot = i,
            }
            table.insert(battleEquippedSkillsCache, cachedSkill)
            battleSkillCooldownCache[i] = CalculateSkillCooldown(
                i,
                cachedSkill.id,
                battleEquipmentStatsCache
            )
            if IsSkillAwakened(cachedSkill) then
                battleSkillCooldownCache[i] = math.max(
                    1.0,
                    battleSkillCooldownCache[i]
                        * (1 - 0.04 * GetSkillAwakeningLevel(cachedSkill))
                )
            end
        end
    end
    RebuildBattleSynergyRuntime()
    battleRuntimeCacheReady = true
end

function ClearBattleRuntimeCache()
    battleEquipmentStatsCache = nil
    battleEquippedSkillsCache = {}
    battleSkillCooldownCache = {}
    battleCloneProtocolId = "balanced"
    battleCloneFocusTarget = nil
    battleCloneFocusScanTimer = 0
    ClearBattleSynergyRuntime()
    battleRuntimeCacheReady = false
end

function DropHighestStarSkillsOnDeath()
    NormalizeSkills()
    local droppedSkills = {}
    if #playerData.skills == 0 then return droppedSkills end

    local dropCount = math.min(#playerData.skills, math.random(2, 3))
    for _ = 1, dropCount do
        local highestStar = 0
        local candidates = {}
        for _, skill in ipairs(playerData.skills) do
            local star = math.max(1, math.min(CONFIG.SkillMaxStar, skill.star or 1))
            if star > highestStar then
                highestStar = star
                candidates = { skill }
            elseif star == highestStar then
                table.insert(candidates, skill)
            end
        end

        if #candidates == 0 then break end
        local dropped = candidates[math.random(1, #candidates)]
        local removed = false
        for i = #playerData.skills, 1, -1 do
            local candidate = playerData.skills[i]
            if candidate == dropped
                or (
                    dropped.uid ~= nil
                    and candidate.uid == dropped.uid
                )
            then
                table.remove(playerData.skills, i)
                removed = true
                break
            end
        end
        if not removed then
            print("[SkillDeath] 最高星技能删除失败:",
                dropped.name or dropped.id, dropped.uid or "missing_uid")
            break
        end
        for i = 1, CONFIG.SkillSlotMaxCount do
            if playerData.skillSlots[i] == dropped.uid then
                playerData.skillSlots[i] = nil
            end
        end
        table.insert(droppedSkills, dropped)
    end

    NormalizeSkills()
    InitSkillRuntime()
    return droppedSkills
end

InitSkillRuntime = function(randomizeInitialCooldown)
    if currentScreen == "playing" and not battleRuntimeCacheReady then
        RebuildBattleRuntimeCache()
    end
    skillRuntime = {}

    local duplicateTotals = {}
    for i = 1, GetUnlockedSkillSlotCount() do
        local skill = FindSkillCardByUid(playerData.skillSlots and playerData.skillSlots[i])
        if skill then
            duplicateTotals[skill.id] = (duplicateTotals[skill.id] or 0) + 1
        end
    end

    local duplicateIndexes = {}
    for i = 1, GetUnlockedSkillSlotCount() do
        local skill = FindSkillCardByUid(playerData.skillSlots and playerData.skillSlots[i])
        local skillCooldown = skill and GetSkillCooldown(i, skill) or 0
        local initialDelay = 0
        local initialTimer = skillCooldown
        if skill then
            local duplicateIndex = (duplicateIndexes[skill.id] or 0) + 1
            duplicateIndexes[skill.id] = duplicateIndex
            local duplicateTotal = duplicateTotals[skill.id] or 1
            local staggerInterval = math.min(0.15, 1.0 / duplicateTotal)
            initialDelay = (duplicateIndex - 1) * staggerInterval
            if randomizeInitialCooldown then
                initialTimer = math.random() * skillCooldown
                print("[Skill] 本局随机初始CD, 槽位:", i,
                    "技能:", skill.name or skill.id,
                    "首次等待:", string.format("%.2f", skillCooldown - initialTimer + initialDelay))
            end
        end
        skillRuntime[i] = {
            timer = initialTimer,
            initialDelay = initialDelay,
        }
    end
end

function GetSkillMergeSuccessRate(sourceStar)
    local star = math.max(1, math.floor(sourceStar or 1))
    local startRate = CONFIG.SkillMergeStartSuccessRate or 1.0
    local step = CONFIG.SkillMergeSuccessRateStep or 0.1
    local minimum = CONFIG.SkillMergeMinimumSuccessRate or 0.5
    return math.max(minimum, startRate - (star - 1) * step)
end

function AutoMergeSkillsToTarget(targetStar)
    NormalizeSkills()
    targetStar = math.max(2, math.min(CONFIG.SkillMaxStar or 10, math.floor(targetStar or 3)))
    -- 方案D：快速短路。若当前已无可合并组合（同id同星未装备数量<3），
    -- 直接返回，省掉 while 空转 + 末尾重复的 NormalizeSkills/InitSkillRuntime。
    -- 这在连打结算逐张提交技能卡时（每张都会调用本函数）收益显著。
    local hasMergeable = false
    local mergeGroupCheck = {}
    for _, skill in ipairs(playerData.skills) do
        local star = math.max(1, math.min(CONFIG.SkillMaxStar or 10, skill.star or 1))
        if not IsSkillUidEquipped(skill.uid) and star < targetStar then
            local key = skill.id .. "#" .. tostring(star)
            mergeGroupCheck[key] = (mergeGroupCheck[key] or 0) + 1
            if mergeGroupCheck[key] >= 3 then
                hasMergeable = true
                break
            end
        end
    end
    if not hasMergeable then
        return 0, 0, 0
    end
    local totalAttempts = 0
    local successCount = 0
    local failCount = 0
    local changed = true

    while changed do
        changed = false
        local groups = {}
        for _, skill in ipairs(playerData.skills) do
            local star = math.max(1, math.min(CONFIG.SkillMaxStar or 10, skill.star or 1))
            if not IsSkillUidEquipped(skill.uid) and star < targetStar then
                local key = skill.id .. "#" .. tostring(star)
                groups[key] = groups[key] or {}
                table.insert(groups[key], skill)
            end
        end

        -- 每轮先把被消耗的卡收集起来，轮末一次性过滤重建；
        -- 不再每次合成反向扫描全表删除，避免 O(合成次数×卡池大小) 的卡顿
        local removeUids = {}
        local newCards = {}
        for _, cards in pairs(groups) do
            local index = 1
            local count = #cards
            while index + 2 <= count do
                totalAttempts = totalAttempts + 1
                local a = cards[index]
                local b = cards[index + 1]
                local c = cards[index + 2]
                index = index + 3
                removeUids[a.uid] = true
                removeUids[b.uid] = true
                removeUids[c.uid] = true
                local def = GetSkillDef(a.id)
                local sourceStar = math.max(1, math.floor(a.star or 1))
                local baseMergeRate = GetSkillMergeSuccessRate(sourceStar)
                local mergeRate = GetEffectiveHiddenAdminSuccessRate(baseMergeRate)
                if math.random() < mergeRate then
                    table.insert(newCards, {
                        uid = AllocateSkillUid(),
                        id = a.id,
                        name = def.name,
                        desc = def.desc,
                        icon = def.icon,
                        star = math.min(CONFIG.SkillMaxStar, (a.star or 1) + 1),
                        cooldown = GetSkillBaseCooldown(a.id),
                    })
                    successCount = successCount + 1
                    changed = true
                else
                    local kept = ({ a, b, c })[math.random(1, 3)]
                    table.insert(newCards, {
                        uid = AllocateSkillUid(),
                        id = kept.id,
                        name = kept.name,
                        desc = kept.desc,
                        icon = kept.icon,
                        star = kept.star or 1,
                        cooldown = GetSkillBaseCooldown(kept.id),
                    })
                    failCount = failCount + 1
                    changed = true
                end
            end
        end

        if #newCards > 0 then
            local keptCards = {}
            for _, skill in ipairs(playerData.skills) do
                if removeUids[skill.uid] ~= true then
                    table.insert(keptCards, skill)
                end
            end
            for _, newSkill in ipairs(newCards) do
                table.insert(keptCards, newSkill)
            end
            playerData.skills = keptCards
        end
    end

    NormalizeSkills()
    InitSkillRuntime()
    saveDirty = totalAttempts > 0 or saveDirty
    if totalAttempts > 0 then
        print("[SkillAutoMerge] 自动合成到", targetStar, "星，次数:", totalAttempts, "成功:", successCount, "失败:", failCount, "技能卡:", #playerData.skills)
    end
    return totalAttempts, successCount, failCount
end

function TryAutoMergeSkills(reason)
    NormalizeEquipmentSettings()
    if playerData.settings.autoSkillMergeEnabled ~= true then
        return 0, 0, 0
    end
    local targetStar = playerData.settings.autoSkillMergeTargetStar or 3
    local attempts, successCount, failCount = AutoMergeSkillsToTarget(targetStar)
    if attempts > 0 then
        SaveCloudData(true)
        print("[SkillAutoMerge] 触发:", reason or "auto", "目标:", targetStar, "次数:", attempts)
    end
    return attempts, successCount, failCount
end

function OneKeyMergeSkills()
    NormalizeSkills()
    local totalAttempts = 0
    local successCount = 0
    local failCount = 0
    local changed = true

    while changed do
        changed = false
        local groups = {}
        for _, skill in ipairs(playerData.skills) do
            if not IsSkillUidEquipped(skill.uid) and (skill.star or 1) < CONFIG.SkillMaxStar then
                local key = skill.id .. "#" .. tostring(skill.star or 1)
                groups[key] = groups[key] or {}
                table.insert(groups[key], skill)
            end
        end

        for _, cards in pairs(groups) do
            while #cards >= 3 do
                totalAttempts = totalAttempts + 1
                local a = table.remove(cards, 1)
                local b = table.remove(cards, 1)
                local c = table.remove(cards, 1)
                for i = #playerData.skills, 1, -1 do
                    local uid = playerData.skills[i].uid
                    if uid == a.uid or uid == b.uid or uid == c.uid then
                        table.remove(playerData.skills, i)
                    end
                end
                local sourceStar = math.max(1, math.floor(a.star or 1))
                local baseMergeRate = GetSkillMergeSuccessRate(sourceStar)
                local mergeRate = GetEffectiveHiddenAdminSuccessRate(baseMergeRate)
                if math.random() < mergeRate then
                    local def = GetSkillDef(a.id)
                    table.insert(playerData.skills, {
                        uid = AllocateSkillUid(),
                        id = a.id,
                        name = def.name,
                        desc = def.desc,
                        icon = def.icon,
                        star = math.min(CONFIG.SkillMaxStar, (a.star or 1) + 1),
                        cooldown = GetSkillBaseCooldown(a.id),
                    })
                    successCount = successCount + 1
                    changed = true
                else
                    local kept = ({ a, b, c })[math.random(1, 3)]
                    table.insert(playerData.skills, {
                        uid = AllocateSkillUid(),
                        id = kept.id,
                        name = kept.name,
                        desc = kept.desc,
                        icon = kept.icon,
                        star = kept.star or 1,
                        cooldown = GetSkillBaseCooldown(kept.id),
                    })
                    failCount = failCount + 1
                    changed = true
                end
            end
        end
    end

    NormalizeSkills()
    InitSkillRuntime()
    saveDirty = totalAttempts > 0 or saveDirty
    if totalAttempts > 0 then
        SaveCloudData(true)
    end
    return totalAttempts, successCount, failCount
end

function FindLowestHpMonster(excluded)
    local best = nil
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local m = aliveMonsters[index]
        if not (excluded and excluded[m]) then
            if best == nil or m.hp < best.hp then best = m end
        end
    end
    return best
end

function FindHighestHpMonster()
    local best = nil
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local monster = aliveMonsters[index]
        if best == nil or monster.hp > best.hp then best = monster end
    end
    return best
end

function BuildClusterSpatialBuckets()
    local cellSize = CLUSTER_SPATIAL_CELL_SIZE
    local buckets = {}
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local monster = aliveMonsters[index]
        local cellX = math.floor(monster.x / cellSize)
        local cellY = math.floor(monster.y / cellSize)
        local column = buckets[cellX]
        if column == nil then
            column = {}
            buckets[cellX] = column
        end
        local bucket = column[cellY]
        if bucket == nil then
            bucket = {}
            column[cellY] = bucket
        end
        bucket[#bucket + 1] = monster
    end
    clusterSpatialBuckets = buckets
    return buckets
end

function FindClusterCenter(radius)
    local cacheKey = tostring(radius or 0)
    local cached = clusterCenterCache[cacheKey]
    if cached then
        return cached.x, cached.y, cached.count
    end

    radius = math.max(0, radius or 0)
    local radiusSq = radius * radius
    local cellSize = CLUSTER_SPATIAL_CELL_SIZE
    local cellRange = math.ceil(radius / cellSize)
    local buckets = clusterSpatialBuckets or BuildClusterSpatialBuckets()
    local best = nil
    local bestCount = 0
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local center = aliveMonsters[index]
        local count = 0
        local centerCellX = math.floor(center.x / cellSize)
        local centerCellY = math.floor(center.y / cellSize)
        for cellX = centerCellX - cellRange, centerCellX + cellRange do
            local column = buckets[cellX]
            if column ~= nil then
                for cellY = centerCellY - cellRange, centerCellY + cellRange do
                    local bucket = column[cellY]
                    if bucket ~= nil then
                        for bucketIndex = 1, #bucket do
                            local monster = bucket[bucketIndex]
                            if monster.hp > 0 then
                                local dx = monster.x - center.x
                                local dy = monster.y - center.y
                                if dx * dx + dy * dy <= radiusSq then
                                    count = count + 1
                                end
                            end
                        end
                    end
                end
            end
        end
        if count > bestCount then
            best = center
            bestCount = count
        end
    end
    local result = {
        x = best and best.x or nil,
        y = best and best.y or nil,
        count = bestCount,
    }
    clusterCenterCache[cacheKey] = result
    return result.x, result.y, result.count
end

function GetSkillAreaMultiplier()
    local stats = GetBattleEquipmentStats()
    return 1 + math.min(15, math.max(0, stats.skillAreaPercent or 0)) / 100
end

function GetSkillAreaRadius(radius)
    return (radius or 0) * GetSkillAreaMultiplier()
end

function ApplyFreezeArea(cx, cy, radius, duration)
    if cx == nil then return end
    local r2 = radius * radius
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local m = aliveMonsters[index]
        local dx = m.x - cx
        local dy = m.y - cy
        if m.hp > 0 and dx * dx + dy * dy <= r2 then
            local appliedDuration = duration
            if m.type == "treasure" or m.type == "skill_treasure" then
                appliedDuration = appliedDuration * (CONFIG.TreasureControlDurationMultiplier or 0.5)
            end
            m.freezeTimer = math.max(m.freezeTimer or 0, appliedDuration)
        end
    end
end

AddEffect = function(effect)
    effect.maxLife = effect.maxLife or effect.life
    if VISUAL_EFFECT_TYPES[effect.type] then
        local visualLimit = GetCurrentVisualEffectLimit()
        local essential = ESSENTIAL_VISUAL_EFFECT_TYPES[effect.type] == true
        local allowedLimit = essential and (visualLimit + 12) or visualLimit
        if visualEffectCount >= allowedLimit then
            if effect.gameplayEffect == true then
                effect.suppressVisual = true
                table.insert(skillEffects, effect)
                return true
            end
            return false
        end
        effect.visualOnly = effect.gameplayEffect ~= true
        effect.countedVisual = true
        visualEffectCount = visualEffectCount + 1
    end
    table.insert(skillEffects, effect)
    return true
end

function GetRandomAliveMonster(excluded)
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    local candidateCount = 0
    for index = 1, aliveCount do
        local monster = aliveMonsters[index]
        if not (excluded and excluded[monster]) then
            candidateCount = candidateCount + 1
        end
    end
    if candidateCount == 0 then return nil end

    local selectedIndex = math.random(1, candidateCount)
    for index = 1, aliveCount do
        local monster = aliveMonsters[index]
        if not (excluded and excluded[monster]) then
            selectedIndex = selectedIndex - 1
            if selectedIndex == 0 then return monster end
        end
    end
    return nil
end

function FindNearestAliveMonster(cx, cy, range, excluded)
    local best = nil
    local bestDist = nil
    local r2 = range and range * range or nil
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local m = aliveMonsters[index]
        if not (excluded and excluded[m]) then
            local dx = m.x - cx
            local dy = m.y - cy
            local d2 = dx * dx + dy * dy
            if (r2 == nil or d2 <= r2) and (bestDist == nil or d2 < bestDist) then
                best = m
                bestDist = d2
            end
        end
    end
    return best
end

function FindNearestTreasureMonster(cx, cy)
    local best = nil
    local bestDist = nil
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local m = aliveMonsters[index]
        if (m.hp or 0) > 0
            and m.treasureEscaped ~= true
            and IsAnyTreasureMonster(m.type) then
            local dx = m.x - cx
            local dy = m.y - cy
            local d2 = dx * dx + dy * dy
            if bestDist == nil or d2 < bestDist then
                best = m
                bestDist = d2
            end
        end
    end
    return best
end

function FindDirectionalTarget(cx, cy, angle, range, excluded)
    local best = nil
    local bestScore = nil
    local maxDiff = math.pi / 8
    local rangeSq = range * range
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local monster = aliveMonsters[index]
        if not (excluded and excluded[monster]) then
            local dx = monster.x - cx
            local dy = monster.y - cy
            local distanceSq = dx * dx + dy * dy
            if distanceSq > 0 and distanceSq <= rangeSq then
                local distance = math.sqrt(distanceSq)
                local targetAngle = math.atan(dy, dx)
                local angleDelta = targetAngle - angle
                local diff = math.abs(math.atan(
                    math.sin(angleDelta),
                    math.cos(angleDelta)
                ))
                if diff <= maxDiff then
                    local score = distance + diff * 80
                    if bestScore == nil or score < bestScore then
                        best = monster
                        bestScore = score
                    end
                end
            end
        end
    end
    return best
end

function FindFlyingSwordTarget(cx, cy, angle, range, targetX, targetY, hitCounts, maxHits)
    local directionalTarget = nil
    local directionalScore = nil
    local nearestTarget = nil
    local nearestDistanceSq = nil
    local maxDiff = math.pi / 8
    local rangeSq = range * range

    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local monster = aliveMonsters[index]
        if (hitCounts[monster] or 0) < maxHits then
            local fallbackDx = monster.x - targetX
            local fallbackDy = monster.y - targetY
            local fallbackDistanceSq = fallbackDx * fallbackDx + fallbackDy * fallbackDy
            if fallbackDistanceSq <= rangeSq
                and (nearestDistanceSq == nil or fallbackDistanceSq < nearestDistanceSq) then
                nearestTarget = monster
                nearestDistanceSq = fallbackDistanceSq
            end

            local dx = monster.x - cx
            local dy = monster.y - cy
            local distanceSq = dx * dx + dy * dy
            if distanceSq > 0 and distanceSq <= rangeSq then
                local distance = math.sqrt(distanceSq)
                local targetAngle = math.atan(dy, dx)
                local angleDelta = targetAngle - angle
                local diff = math.abs(math.atan(
                    math.sin(angleDelta),
                    math.cos(angleDelta)
                ))
                if diff <= maxDiff then
                    local score = distance + diff * 80
                    if directionalScore == nil or score < directionalScore then
                        directionalTarget = monster
                        directionalScore = score
                    end
                end
            end
        end
    end

    return directionalTarget or nearestTarget
end

function CastThunder(skill)
    local highStarLevel = GetSkillHighStarLevel(skill)
    local awakeningLevel = GetSkillAwakeningLevel(skill)
    local strikeCount = 11 + highStarLevel + awakeningLevel * 3
    local targets = {}
    local used = {}
    for i = 1, strikeCount do
        local target = GetRandomAliveMonster(used)
        if target == nil then
            used = {}
            target = GetRandomAliveMonster(nil)
        end
        if target == nil then break end
        used[target] = true
        table.insert(targets, target)
    end
    if #targets <= 0 then return end
    AddEffect({
        type = "thunder_sequence",
        targets = targets,
        nextStrike = 1,
        strikeTimer = 0,
        strikeInterval = 0.07,
        damageMin = 0.48,
        damageMax = 0.64,
        awakeningLevel = awakeningLevel,
        skill = SnapshotSkillDamageSource(skill),
        life = 0.85,
        maxLife = 0.85,
    })
end

function LaunchFireballVolley(skill, volleyIndex)
    local target = FindHighestHpMonster()
    if target == nil then return false end
    local highStarLevel = GetSkillHighStarLevel(skill)
    local awakeningLevel = GetSkillAwakeningLevel(skill)
    local radius = 70 * (1 + highStarLevel * 0.05 + awakeningLevel * 0.10)
    local damage = RandomDamageByAttack(1.65, 2.25, skill)
    DamageMonsterBySkill(target, damage, {255, 120, 30}, 28, skill)
    if highStarLevel > 0 then
        local radiusSq = radius * radius
        for _, monster in ipairs(monsters) do
            if monster ~= target and monster.hp > 0 then
                local dx = monster.x - target.x
                local dy = monster.y - target.y
                if dx * dx + dy * dy <= radiusSq then
                    DamageMonsterBySkill(monster, damage * 0.35, {255, 120, 30}, 12, skill)
                end
            end
        end
    end
    AddEffect({
        type = "fireball",
        x = target.x,
        y = target.y,
        x1 = hero.x,
        y1 = hero.y,
        x2 = target.x,
        y2 = target.y,
        radius = radius,
        volleyIndex = volleyIndex,
        visualDelay = 0,
        visualDuration = 0.55,
        life = 0.55,
    })
    SpawnParticles(target.x, target.y, 18, {255, 100, 20})
    return true
end

function CastFireball(skill)
    if not LaunchFireballVolley(skill, 1) then return end
    local highStarLevel = GetSkillHighStarLevel(skill)
    local awakeningLevel = GetSkillAwakeningLevel(skill)
    local volleyCount = 2 + (awakeningLevel > 0 and 1 or 0)
    if highStarLevel >= 3 then volleyCount = volleyCount + 1 end
    if highStarLevel >= 6 then volleyCount = volleyCount + 1 end
    for volleyIndex = 2, volleyCount do
        AddEffect({
            type = "fireball_followup",
            timer = 0.25 * (volleyIndex - 1),
            volleyIndex = volleyIndex,
            skill = SnapshotSkillDamageSource(skill),
            life = 0.3 * volleyIndex,
            maxLife = 0.3 * volleyIndex,
        })
    end
end

function CastFlyingSword(skill)
    local cx, cy = FindClusterCenter(CONFIG.SkillClusterRadius)
    if cx == nil then return end
    local highStarLevel = GetSkillHighStarLevel(skill)
    local awakeningLevel = GetSkillAwakeningLevel(skill)
    local swordCount = 28 + highStarLevel * 2 + awakeningLevel * 4
    AddEffect({
        type = "flying_sword_sequence",
        x = cx,
        y = cy,
        range = (CONFIG.SkillAreaRadius + 76) * (1 + highStarLevel * 0.025 + awakeningLevel * 0.05),
        nextSword = 1,
        swordCount = swordCount,
        maxHitsPerTarget = 6 + math.floor(highStarLevel / 2),
        targetHitCounts = {},
        swordTimer = 0,
        swordInterval = 0.035,
        skill = SnapshotSkillDamageSource(skill),
        life = 1.05,
        maxLife = 1.05,
    })
end

function CastDart(skill)
    local highStarLevel = GetSkillHighStarLevel(skill)
    local awakeningLevel = GetSkillAwakeningLevel(skill)
    local dartCount = 5 + highStarLevel + awakeningLevel * 2
    local used = {}
    for i = 1, dartCount do
        local target = FindLowestHpMonster(used) or FindLowestHpMonster(nil)
        if target == nil then break end
        used[target] = true
        DamageMonsterBySkill(target, RandomDamageByAttack(0.55, 0.72, skill), {120, 255, 130}, 16, skill)
        local visualDelay = (i - 1) * 0.07
        AddEffect({
            type = "dart",
            x1 = hero.x,
            y1 = hero.y,
            x2 = target.x,
            y2 = target.y,
            volleyIndex = i,
            visualDelay = visualDelay,
            visualDuration = 0.45,
            life = 0.45 + visualDelay,
        })
    end
end

function GetShieldLayers(skill)
    local star = GetSkillStar(skill)
    local layers = star >= 5 and (star - 2) or (star >= 3 and 2 or 1)
    return layers + GetSkillAwakeningLevel(skill)
end

function CastShield(skill)
    local shieldLayers = GetShieldLayers(skill)
    base.shield = math.max(base.shield or 0, shieldLayers)
    base.shieldAwakeningLevel = GetSkillAwakeningLevel(skill)
    base.shieldDamageSource = SnapshotSkillDamageSource(skill)
    AddEffect({
        type = "shield",
        x = base.x,
        y = base.y - CONFIG.BaseHeight * 0.35,
        radius = 58,
        layers = shieldLayers,
        life = 0.8,
    })
end

function CastHeal(skill)
    if base.hp <= 0 then return false end
    local star = GetSkillStar(skill)
    local missingHp = math.max(0, base.maxHp - base.hp)
    local healRatio = 0.03 + (star - 1) * 0.01
        + GetSkillHighStarLevel(skill) * 0.005
    local heal = missingHp * healRatio
    if heal < 1 then return false end
    base.hp = math.min(base.maxHp, base.hp + heal)
    AddEffect({ type = "heal", x = base.x, y = base.y - CONFIG.BaseHeight * 0.35, life = 0.9, text = "+" .. math.floor(heal) })
    print(string.format("[Skill][Heal] 星级=%d 恢复=%.1f 当前生命=%.1f/%.1f", star, heal, base.hp, base.maxHp))
    return true
end

function CastFreeze(skill)
    local cx, cy = FindClusterCenter(CONFIG.SkillClusterRadius)
    if cx == nil then return end
    local star = GetSkillStar(skill)
    local highStarLevel = GetSkillHighStarLevel(skill)
    local radius = GetSkillAreaRadius(CONFIG.FreezeRadius + (star - 1) * 2 + highStarLevel * 2)
    local duration = 3.2 + (star - 1) * 0.2 + highStarLevel * 0.1
    ApplyFreezeArea(cx, cy, radius, duration)
    AddEffect({ type = "freeze", x = cx, y = cy, radius = radius, life = 0.65, maxLife = 0.65 })
    print(string.format("[Skill][Freeze] 星级=%d 半径=%.1f 减速时长=%.1f秒", star, radius, duration))
end

function CastMeteor(skill)
    local cx, cy = FindClusterCenter(CONFIG.SkillClusterRadius)
    if cx == nil then return end
    local highStarLevel = GetSkillHighStarLevel(skill)
    AddEffect({
        type = "meteor_warning",
        x = cx,
        y = cy,
        radius = GetSkillAreaRadius(98 * (1 + highStarLevel * 0.04)),
        damage = RandomDamageByAttack(2.00, 2.60, skill),
        skillId = type(skill) == "table" and skill.id or skill,
        sourceSkill = SnapshotSkillDamageSource(skill),
        life = math.max(0.35, 0.55 - highStarLevel * 0.02),
        maxLife = math.max(0.35, 0.55 - highStarLevel * 0.02),
    })
end

function CastBlackHole(skill)
    local cx, cy = FindClusterCenter(CONFIG.SkillClusterRadius)
    if cx == nil then return end
    local star = GetSkillStar(skill)
    local highStarLevel = GetSkillHighStarLevel(skill)
    local duration = 2.6 + (star - 1) * 0.15 + highStarLevel * 0.1
    local radius = GetSkillAreaRadius(CONFIG.BlackHoleRadius + highStarLevel * 4)
    local damage = RandomDamageByAttack(0.70, 0.70, skill)
    DamageArea(cx, cy, radius, damage, {160, 70, 255}, skill, false)
    AddEffect({ type = "blackhole", x = cx, y = cy, radius = radius, life = duration })
end

function CastChainLightning(skill)
    local current = FindLowestHpMonster(nil)
    if current == nil then return end
    local highStarLevel = GetSkillHighStarLevel(skill)
    local maxJumps = 6 + highStarLevel
    local decay = math.max(0.08, 0.85 + highStarLevel * 0.01)
    local jumpDistance = 180 * (1 + highStarLevel * 0.03)
    local used = {}
    local last = nil
    local maxJumpDistanceSq = jumpDistance * jumpDistance
    for i = 1, maxJumps do
        if current == nil then break end
        used[current] = true
        local damage = RandomDamageByAttack(0.95, 1.20, skill) * (decay ^ (i - 1))
        DamageMonsterBySkill(current, damage, {235, 245, 80}, 16, skill)
        local chainStart = last or hero
        local visualDelay = (i - 1) * 0.055
        AddEffect({
            type = "chain",
            x1 = chainStart.x,
            y1 = chainStart.y,
            x2 = current.x,
            y2 = current.y,
            chainIndex = i,
            visualDelay = visualDelay,
            visualDuration = 0.55,
            life = 0.55 + visualDelay,
        })
        last = current

        local nearest = nil
        local nearestDist = nil
        for _, m in ipairs(monsters) do
            if m.hp > 0 and not used[m] then
                local dx = m.x - current.x
                local dy = m.y - current.y
                local d2 = dx * dx + dy * dy
                if d2 <= maxJumpDistanceSq
                    and (nearestDist == nil or d2 < nearestDist) then
                    nearest = m
                    nearestDist = d2
                end
            end
        end
        current = nearest
    end
end

function PointToSegmentDistanceSquared(px, py, x1, y1, x2, y2)
    local dx = x2 - x1
    local dy = y2 - y1
    local len2 = dx * dx + dy * dy
    if len2 <= 0.001 then
        local ox = px - x1
        local oy = py - y1
        return ox * ox + oy * oy
    end
    local t = ((px - x1) * dx + (py - y1) * dy) / len2
    t = math.max(0, math.min(1, t))
    local cx = x1 + dx * t
    local cy = y1 + dy * t
    local ox = px - cx
    local oy = py - cy
    return ox * ox + oy * oy
end

function DamageSkillAlongSegment(x1, y1, x2, y2, width, damage, skill, maxTargets, color)
    local candidates = {}
    local hitRadius = width * 0.5
    for _, m in ipairs(monsters) do
        if m.hp > 0 then
            local radius = hitRadius + (m.radius or CONFIG.MonsterRadius or 8) * 0.45
            local distanceSq = PointToSegmentDistanceSquared(m.x, m.y, x1, y1, x2, y2)
            if distanceSq <= radius * radius then
                table.insert(candidates, { monster = m, distanceSq = distanceSq })
            end
        end
    end
    table.sort(candidates, function(a, b)
        return a.distanceSq < b.distanceSq
    end)
    local hitCount = math.min(maxTargets or #candidates, #candidates)
    for i = 1, hitCount do
        DamageMonsterBySkill(candidates[i].monster, damage, color, 18, skill)
    end
    return hitCount
end

function FindFarthestAliveMonster(cx, cy)
    local target = nil
    local farthestDistanceSq = -1
    for _, m in ipairs(monsters) do
        if m.hp > 0 then
            local dx = m.x - cx
            local dy = m.y - cy
            local distanceSq = dx * dx + dy * dy
            if distanceSq > farthestDistanceSq then
                target = m
                farthestDistanceSq = distanceSq
            end
        end
    end
    return target
end

function ApplyGroundSlamSlowToMonster(monster, normalDuration, eliteDuration)
    local isEliteOrBoss = monster.isBoss or monster.type == "elite"
    local appliedDuration = isEliteOrBoss and eliteDuration or normalDuration
    local appliedScale = isEliteOrBoss and 0.8 or 0.55
    if monster.type == "treasure" or monster.type == "skill_treasure" then
        appliedDuration = appliedDuration
            * (CONFIG.TreasureControlDurationMultiplier or 0.5)
        appliedScale = 1 - (1 - appliedScale)
            * (CONFIG.TreasureControlStrengthMultiplier or 0.5)
    end
    monster.groundSlamSlowTimer = math.max(
        monster.groundSlamSlowTimer or 0,
        appliedDuration
    )
    monster.groundSlamSlowScale = appliedScale
end

function GetGroundSlamSlowDurations(skill)
    local star = GetSkillStar(skill)
    local starProgress = (star - 1) / math.max(1, CONFIG.SkillMaxStar - 1)
    local highStarLevel = GetSkillHighStarLevel(skill)
    return 0.9 + starProgress * 0.3 + highStarLevel * 0.05,
        0.45 + starProgress * 0.15 + highStarLevel * 0.025
end

function ApplyGroundSlamSlow(cx, cy, radius, skill)
    local normalDuration, eliteDuration = GetGroundSlamSlowDurations(skill)
    local radiusSq = radius * radius
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local monster = aliveMonsters[index]
        local dx = monster.x - cx
        local dy = monster.y - cy
        if monster.hp > 0 and dx * dx + dy * dy <= radiusSq then
            ApplyGroundSlamSlowToMonster(monster, normalDuration, eliteDuration)
        end
    end
end

function DamageAreaWithGroundSlamSlow(
    cx,
    cy,
    radius,
    damage,
    color,
    damageSource,
    slowSkill,
    maxHitEffects
)
    local normalDuration, eliteDuration = GetGroundSlamSlowDurations(slowSkill)
    local radiusSq = radius * radius
    local hitEffectCount = 0
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local monster = aliveMonsters[index]
        local dx = monster.x - cx
        local dy = monster.y - cy
        if monster.hp > 0 and dx * dx + dy * dy <= radiusSq then
            if maxHitEffects == nil or hitEffectCount < maxHitEffects then
                DamageMonsterBySkill(
                    monster,
                    damage,
                    color,
                    16,
                    damageSource
                )
                hitEffectCount = hitEffectCount + 1
            else
                local scaledDamage = damage
                    * GetRangedMonsterSkillDamageMultiplier(monster)
                DamageMonster(monster, scaledDamage, damageSource)
            end
            if monster.hp > 0 then
                ApplyGroundSlamSlowToMonster(
                    monster,
                    normalDuration,
                    eliteDuration
                )
            end
        end
    end
end

function CastBladeOrbit(skill)
    local highStarLevel = GetSkillHighStarLevel(skill)
    local duration = 2.4 + highStarLevel * 0.12
    local tickCount = 6 + math.floor(highStarLevel / 2)
    local tickInterval = duration / tickCount
    AddEffect({
        type = "blade_orbit",
        radius = GetSkillAreaRadius(118 + highStarLevel * 3),
        life = duration,
        maxLife = duration,
        tickTimer = tickInterval,
        tickInterval = tickInterval,
        remainingTicks = tickCount,
        damage = RandomDamageByAttack(0.24, 0.24, skill),
        skillId = type(skill) == "table" and skill.id or skill,
        sourceSkill = SnapshotSkillDamageSource(skill),
    })
end

function CastPiercingLance(skill)
    local cx, cy = FindClusterCenter(CONFIG.SkillClusterRadius)
    if cx == nil then return end
    local dx = cx - hero.x
    local dy = cy - hero.y
    local distance = math.sqrt(dx * dx + dy * dy)
    if distance <= 0 then return end
    local highStarLevel = GetSkillHighStarLevel(skill)
    local length = 560 + highStarLevel * 20
    local width = GetSkillAreaRadius(28 + highStarLevel * 2)
    local x1, y1 = hero.x, hero.y
    local x2 = x1 + dx / distance * length
    local y2 = y1 + dy / distance * length
    local hitRadius = width * 0.5
    local damage = RandomDamageByAttack(1.55, 1.95, skill)
    for _, m in ipairs(monsters) do
        if m.hp > 0 then
            local radius = hitRadius + (m.radius or CONFIG.MonsterRadius or 8) * 0.45
            if PointToSegmentDistanceSquared(m.x, m.y, x1, y1, x2, y2) <= radius * radius then
                DamageMonsterBySkill(m, damage, {135, 220, 255}, 15, skill)
            end
        end
    end
    AddEffect({
        type = "piercing_lance",
        x1 = x1,
        y1 = y1,
        x2 = x2,
        y2 = y2,
        width = width,
        life = 0.62,
        maxLife = 0.62,
    })
end

function CastFlameZone(skill)
    local cx, cy = FindClusterCenter(CONFIG.SkillClusterRadius)
    if cx == nil then return end
    local highStarLevel = GetSkillHighStarLevel(skill)
    local duration = 3.0 + highStarLevel * 0.12
    local tickCount = 8 + math.floor(highStarLevel / 2)
    local tickInterval = duration / tickCount
    AddEffect({
        type = "flame_zone",
        x = cx,
        y = cy,
        radius = GetSkillAreaRadius(92 + highStarLevel * 3),
        life = duration,
        maxLife = duration,
        tickTimer = tickInterval,
        tickInterval = tickInterval,
        remainingTicks = tickCount,
        damage = RandomDamageByAttack(0.16, 0.16, skill),
        skillId = type(skill) == "table" and skill.id or skill,
        sourceSkill = SnapshotSkillDamageSource(skill),
    })
end

function CastReturningAxe(skill)
    local target = FindFarthestAliveMonster(hero.x, hero.y)
    if target == nil then return end
    local highStarLevel = GetSkillHighStarLevel(skill)
    local damage = RandomDamageByAttack(0.65, 0.85, skill)
    local x1, y1 = hero.x, hero.y
    local x2, y2 = target.x, target.y
    local width = GetSkillAreaRadius(34 + highStarLevel * 3)
    local maxTargets = 6 + highStarLevel
    local skillId = type(skill) == "table" and skill.id or skill
    local sourceSkill = SnapshotSkillDamageSource(skill)
    DamageSkillAlongSegment(x1, y1, x2, y2, width, damage, sourceSkill, maxTargets, {255, 185, 75})
    AddEffect({
        type = "returning_axe",
        x1 = x1,
        y1 = y1,
        x2 = x2,
        y2 = y2,
        width = width,
        damage = damage,
        skillId = skillId,
        sourceSkill = sourceSkill,
        maxTargets = maxTargets,
        life = 0.8,
        maxLife = 0.8,
        returnHit = false,
    })
end

function CastGroundSlam(skill)
    local target = FindNearestAliveMonster(base.x, base.y)
    if target == nil then return end
    local dx = target.x - base.x
    local dy = target.y - base.y
    local distance = math.sqrt(dx * dx + dy * dy)
    if distance <= 0 then return end
    local highStarLevel = GetSkillHighStarLevel(skill)
    local radius = GetSkillAreaRadius(112 + highStarLevel * 3)
    local cx = target.isTrainingDummy and target.x or (base.x + dx / distance * 72)
    local cy = target.isTrainingDummy and target.y or (base.y + dy / distance * 72)
    DamageAreaWithGroundSlamSlow(
        cx,
        cy,
        radius,
        RandomDamageByAttack(1.15, 1.45, skill),
        {185, 135, 95},
        skill,
        skill,
        6 + highStarLevel
    )
    AddEffect({ type = "ground_slam", x = cx, y = cy, radius = radius, life = 0.62, maxLife = 0.62 })
end

function CastSwordWave(skill)
    local target = FindNearestAliveMonster(hero.x, hero.y)
    if target == nil then return end
    local dx = target.x - hero.x
    local dy = target.y - hero.y
    local dist = math.sqrt(dx * dx + dy * dy)
    if dist <= 0 then return end
    local highStarLevel = GetSkillHighStarLevel(skill)
    local length = 350 + highStarLevel * 15
    local width = GetSkillAreaRadius(72 + highStarLevel * 3)
    local ux = dx / dist
    local uy = dy / dist
    local x1 = hero.x
    local y1 = hero.y
    local x2 = x1 + ux * length
    local y2 = y1 + uy * length
    local hitRadius = width * 0.5
    for _, m in ipairs(monsters) do
        if m.hp > 0 then
            local radius = hitRadius + (m.radius or CONFIG.MonsterRadius or 8) * 0.45
            if PointToSegmentDistanceSquared(m.x, m.y, x1, y1, x2, y2) <= radius * radius then
                DamageMonsterBySkill(m, RandomDamageByAttack(1.00, 1.30, skill), {210, 230, 255}, 14, skill)
            end
        end
    end
    AddEffect({ type = "sword_wave", x1 = x1, y1 = y1, x2 = x2, y2 = y2, width = width, life = 0.45, maxLife = 0.45 })
end

function GetPoisonMistSlowScale(skill)
    local star = GetSkillStar(skill)
    if star >= 10 then return 0.60 end
    if star >= 7 then return 0.65 end
    if star >= 4 then return 0.70 end
    return 0.75
end

function CastPoisonMist(skill)
    local cx, cy = FindClusterCenter(CONFIG.SkillClusterRadius)
    if cx == nil then return end
    local highStarLevel = GetSkillHighStarLevel(skill)
    local duration = 4.0 + highStarLevel * 0.15
    local tickCount = 7 + math.floor(highStarLevel / 2)
    local tickInterval = duration / tickCount
    local skillId = type(skill) == "table" and skill.id or tostring(skill)
    AddEffect({
        type = "poison_mist",
        x = cx,
        y = cy,
        radius = GetSkillAreaRadius(110 + highStarLevel * 3),
        life = duration,
        maxLife = duration,
        tickTimer = tickInterval,
        tickInterval = tickInterval,
        remainingTicks = tickCount,
        damage = RandomDamageByAttack(0.18, 0.18, skill),
        slowScale = GetPoisonMistSlowScale(skill),
        skillId = skillId,
        sourceSkill = SnapshotSkillDamageSource(skill),
    })
end

function CastStormPush(skill)
    local cx = IsTrainingDummyMode() and hero.x or base.x
    local cy = IsTrainingDummyMode() and hero.y or (base.y - CONFIG.BaseHeight * 0.35)
    local highStarLevel = GetSkillHighStarLevel(skill)
    local radius = GetSkillAreaRadius(150 + highStarLevel * 4)
    local knockback = 130 + highStarLevel * 5
    local r2 = radius * radius
    for _, m in ipairs(monsters) do
        if m.hp > 0 then
            local dx = m.x - cx
            local dy = m.y - cy
            local d2 = dx * dx + dy * dy
            if d2 <= r2 then
                DamageMonsterBySkill(m, RandomDamageByAttack(0.90, 1.20, skill), {100, 220, 255}, 14, skill)
                local dist = math.sqrt(d2)
                if dist > 0 then
                    local push = knockback * (m.isBoss and 0.6 or 1.0)
                    if m.type == "treasure" or m.type == "skill_treasure" then
                        push = push * (CONFIG.TreasureControlStrengthMultiplier or 0.5)
                    end
                    local nextX = math.max(-m.radius,
                        math.min(screenW + m.radius, m.x + dx / dist * push))
                    local nextY = math.max(-m.radius,
                        math.min(screenH - m.radius, m.y + dy / dist * push))
                    AddMonsterControlDisplacement(m, nextX - m.x, nextY - m.y)
                end
            end
        end
    end
    AddEffect({ type = "storm_push", x = cx, y = cy, radius = radius, life = 0.55, maxLife = 0.55 })
end

function CastHolyJudgement(skill)
    local target = nil
    for _, m in ipairs(monsters) do
        if m.hp > 0 and m.isBoss then
            if target == nil or m.hp > target.hp then target = m end
        end
    end
    if target == nil then
        for _, m in ipairs(monsters) do
            if m.hp > 0 and m.type == "elite" then
                if target == nil or m.hp > target.hp then target = m end
            end
        end
    end
    if target == nil then
        target = FindHighestHpMonster()
    end
    if target == nil then return end
    local damage = RandomDamageByAttack(2.35, 3.00, skill)
    if target.isBoss or target.type == "elite" then
        damage = damage * (2.0 + GetSkillHighStarLevel(skill) * 0.10)
    end
    DamageMonsterBySkill(target, damage, {255, 235, 140}, 24, skill)
    AddEffect({ type = "holy_judgement", x1 = target.x, y1 = -24, x2 = target.x, y2 = target.y, radius = target.radius or 24, life = 0.65, maxLife = 0.65 })
end

function HasAliveMonster()
    for _, monster in ipairs(monsters) do
        if monster.hp > 0 then
            return true
        end
    end
    return false
end

function SkillRequiresAliveMonster(skillId)
    return skillId ~= "shield"
        and skillId ~= "heal"
end

function OnShieldLayerAbsorbed()
    local awakening = math.max(0, math.floor(base.shieldAwakeningLevel or 0))
    if awakening <= 0 then return end
    local sourceSkill = base.shieldDamageSource or { id = "shield", star = 1 }
    local radius = GetSkillAreaRadius(68 + awakening * 14)
    local damage = GetHeroAttackDamage()
        * (0.22 + awakening * 0.10)
        * GetSkillDamageMultiplier(sourceSkill)
    DamageArea(base.x, base.y - CONFIG.BaseHeight * 0.35, radius, damage, {170, 230, 255}, sourceSkill, true, 8)
    if awakening >= 3 then
        ApplyFreezeArea(base.x, base.y - CONFIG.BaseHeight * 0.35, radius, 0.45)
    end
    AddEffect({ type = "area_pulse", x = base.x, y = base.y - CONFIG.BaseHeight * 0.35, radius = radius, color = {170, 230, 255}, life = 0.3, maxLife = 0.3 })
    if (base.shield or 0) <= 0 then
        base.shieldAwakeningLevel = 0
        base.shieldDamageSource = nil
    end
end

function TriggerSkillAwakening(skill)
    local awakening = GetSkillAwakeningLevel(skill)
    if awakening <= 0 then return end
    local skillId = skill.id
    local sourceSkill = SnapshotSkillDamageSource(skill)
    local cx, cy = GetSkillSynergyCenter()
    local damage = RandomDamageByAttack(0.30 + awakening * 0.08, 0.30 + awakening * 0.08, skill)
    if skillId == "thunder" or skillId == "freeze" or skillId == "ground_slam" or skillId == "storm_push" or skillId == "holy_judgement" then
        AddEffect({ type = "awakening_delay", gameplayEffect = true, x = cx, y = cy, radius = GetSkillAreaRadius(62 + awakening * 16), damage = damage * (skillId == "freeze" and 1.35 or 1.0), skillId = skillId, sourceSkill = sourceSkill, color = {130, 220, 255}, freezeDuration = skillId == "freeze" and 0.25 * awakening or nil, slowScale = skillId == "storm_push" and (0.8 - awakening * 0.05) or nil, life = skillId == "freeze" and 0.7 or 0.28, maxLife = skillId == "freeze" and 0.7 or 0.28 })
    elseif skillId == "fireball" or skillId == "meteor" or skillId == "blackhole" or skillId == "blade_orbit" or skillId == "flame_zone" or skillId == "poison_mist" then
        AddEffect({ type = "awakening_zone", gameplayEffect = true, x = skillId == "blade_orbit" and hero.x or cx, y = skillId == "blade_orbit" and hero.y or cy, radius = GetSkillAreaRadius(64 + awakening * 14), damage = damage * 0.65, skillId = skillId, sourceSkill = sourceSkill, color = {255, 120, 40}, life = 1.3 + awakening * 0.35, maxLife = 1.3 + awakening * 0.35, tickTimer = 0, tickInterval = 0.45, remainingTicks = 2 + awakening, terminalDamage = (skillId == "blackhole" or skillId == "blade_orbit" or skillId == "flame_zone") and damage * (1.0 + awakening * 0.25) or nil })
    elseif skillId == "flying_sword" or skillId == "dart" or skillId == "chain_lightning" then
        local target = FindHighestHpMonster()
        if target then AddEffect({ type = "awakening_target", gameplayEffect = true, target = target, x1 = hero.x, y1 = hero.y, damage = damage, skillId = skillId, sourceSkill = sourceSkill, color = {210, 230, 255}, repeats = skillId == "dart" and awakening or 1, radius = GetSkillAreaRadius(38 + awakening * 10), life = 0.22, maxLife = 0.22 }) end
    elseif skillId == "heal" then
        local previousShield = base.shield or 0
        base.shield = math.max(previousShield, awakening)
        if base.shield > previousShield then
            base.shieldAwakeningLevel = 0
            base.shieldDamageSource = nil
        end
        if awakening >= 3 then base.hp = math.min(base.maxHp, base.hp + base.maxHp * 0.03) end
    elseif skillId == "shield" then
        base.shieldAwakeningLevel = awakening
        base.shieldDamageSource = sourceSkill
    elseif skillId == "piercing_lance" or skillId == "returning_axe" or skillId == "sword_wave" then
        local target = FindNearestAliveMonster(hero.x, hero.y)
        if target then AddEffect({ type = "awakening_segment", gameplayEffect = true, x1 = hero.x, y1 = hero.y, x2 = target.x, y2 = target.y, width = GetSkillAreaRadius(38 + awakening * 8), damage = damage * 1.35, skillId = skillId, sourceSkill = sourceSkill, color = {210, 230, 255}, maxTargets = 4 + awakening * 2, life = 0.3, maxLife = 0.3 }) end
    end
end

function CastSkill(skill)
    local sourceSkill = SnapshotSkillDamageSource(skill)
    local skillId = type(sourceSkill) == "table" and sourceSkill.id or sourceSkill
    if SkillRequiresAliveMonster(skillId) and not HasAliveMonster() then
        return false
    end

    if skillId == "thunder" then CastThunder(sourceSkill)
    elseif skillId == "fireball" then CastFireball(sourceSkill)
    elseif skillId == "flying_sword" then CastFlyingSword(sourceSkill)
    elseif skillId == "dart" then CastDart(sourceSkill)
    elseif skillId == "shield" then CastShield(sourceSkill)
    elseif skillId == "heal" then
        if not CastHeal(sourceSkill) then return false end
    elseif skillId == "freeze" then CastFreeze(sourceSkill)
    elseif skillId == "meteor" then CastMeteor(sourceSkill)
    elseif skillId == "blackhole" then CastBlackHole(sourceSkill)
    elseif skillId == "chain_lightning" then CastChainLightning(sourceSkill)
    elseif skillId == "sword_wave" then CastSwordWave(sourceSkill)
    elseif skillId == "poison_mist" then CastPoisonMist(sourceSkill)
    elseif skillId == "storm_push" then CastStormPush(sourceSkill)
    elseif skillId == "holy_judgement" then CastHolyJudgement(sourceSkill)
    elseif skillId == "blade_orbit" then CastBladeOrbit(sourceSkill)
    elseif skillId == "piercing_lance" then CastPiercingLance(sourceSkill)
    elseif skillId == "flame_zone" then CastFlameZone(sourceSkill)
    elseif skillId == "returning_axe" then CastReturningAxe(sourceSkill)
    elseif skillId == "ground_slam" then CastGroundSlam(sourceSkill)
    else
        return false
    end

    TriggerSkillAwakening(sourceSkill)
    RecordSkillSynergyCast(sourceSkill)
    return true
end

function UpdateSkills(dt)
    UpdateSkillSynergy(dt)
    local equipped = GetEquippedSkills()
    local hasAliveMonster = HasAliveMonster()
    for _, skill in ipairs(equipped) do
        local slot = skill.slot or 1
        local skillCooldown = GetSkillCooldown(slot, skill)
        if skillRuntime[slot] == nil then
            skillRuntime[slot] = {
                timer = skillCooldown,
                initialDelay = 0,
            }
        end
        local runtime = skillRuntime[slot]
        local skillId = skill.id
        local canAdvanceInitialDelay = not SkillRequiresAliveMonster(skillId)
            or hasAliveMonster

        if (runtime.initialDelay or 0) > 0 then
            if canAdvanceInitialDelay then
                runtime.initialDelay = math.max(0, runtime.initialDelay - dt)
            end
        else
            runtime.timer = runtime.timer + dt
            if runtime.timer >= skillCooldown and CastSkill(skill) then
                runtime.timer = 0
            end
        end
    end
end

function UpdateSkillEffects(dt)
    for i = #skillEffects, 1, -1 do
        local e = skillEffects[i]
        local oldLife = math.max(0, e.life or 0)
        local activeDt = math.min(dt, oldLife)
        if e.type == "thunder_sequence" and oldLife > 0 then
            e.strikeTimer = (e.strikeTimer or 0) + activeDt
            local interval = e.strikeInterval or 0.07
            while e.strikeTimer >= interval and (e.nextStrike or 1) <= #(e.targets or {}) do
                e.strikeTimer = e.strikeTimer - interval
                local target = e.targets[e.nextStrike]
                e.nextStrike = e.nextStrike + 1
                if target and target.hp > 0 then
                    DamageMonsterBySkill(target, RandomDamageByAttack(e.damageMin or 0.42, e.damageMax or 0.56, e.skill), {130, 220, 255}, 18, e.skill)
                    AddEffect({ type = "thunder", x1 = target.x + math.random(-24, 24), y1 = -18, x2 = target.x, y2 = target.y, life = 0.35 })
                end
            end
        elseif e.type == "fireball_followup" and oldLife > 0 then
            e.timer = (e.timer or 0) - activeDt
            if e.timer <= 0 and not e.triggered then
                e.triggered = true
                LaunchFireballVolley(e.skill, e.volleyIndex or 2)
            end
        elseif e.type == "flying_sword_sequence" and oldLife > 0 then
            e.swordTimer = (e.swordTimer or 0) + activeDt
            local interval = e.swordInterval or 0.035
            local swordCount = e.swordCount or 24
            while e.swordTimer >= interval and (e.nextSword or 1) <= swordCount do
                e.swordTimer = e.swordTimer - interval
                local swordIndex = e.nextSword
                e.nextSword = swordIndex + 1
                local angle = (swordIndex - 1) / swordCount * math.pi * 2
                local range = e.range or 160
                local tx = e.x + math.cos(angle) * range
                local ty = e.y + math.sin(angle) * range
                local hitCounts = e.targetHitCounts or {}
                e.targetHitCounts = hitCounts
                local maxHits = e.maxHitsPerTarget or 6
                local target = FindFlyingSwordTarget(
                    e.x,
                    e.y,
                    angle,
                    range,
                    tx,
                    ty,
                    hitCounts,
                    maxHits
                )
                if target then
                    hitCounts[target] = (hitCounts[target] or 0) + 1
                    DamageMonsterBySkill(target, RandomDamageByAttack(0.25, 0.33, e.skill), {210, 230, 255}, 14, e.skill)
                    tx, ty = target.x, target.y
                end
                AddEffect({ type = "flying_sword", x1 = e.x, y1 = e.y, x2 = tx, y2 = ty, life = 0.55 })
            end
        elseif e.type == "meteor_warning" then
            local sourceSkill = e.sourceSkill or e.skillId or "meteor"
            if oldLife > 0 and oldLife - dt <= 0 and not e.triggered then
                e.triggered = true
                DamageArea(e.x, e.y, e.radius or CONFIG.SkillAreaRadius, e.damage or 0, {255, 120, 40}, sourceSkill, true, 6)
                AddEffect({ type = "meteor", x = e.x, y = e.y, radius = e.radius or CONFIG.SkillAreaRadius, life = 0.75 })
                SpawnParticles(e.x, e.y, 18, {255, 120, 40})
            end
        elseif e.type == "blade_orbit" and oldLife > 0 then
            e.tickTimer = (e.tickTimer or 0) + activeDt
            local interval = e.tickInterval or 0.6
            while e.tickTimer >= interval and (e.remainingTicks or 0) > 0 do
                e.tickTimer = e.tickTimer - interval
                e.remainingTicks = e.remainingTicks - 1
                DamageArea(hero.x, hero.y, e.radius or 118, e.damage or 0, {110, 210, 255}, e.sourceSkill or e.skillId or "blade_orbit", true, 6)
                AddEffect({ type = "area_pulse", x = hero.x, y = hero.y, radius = e.radius or 118, color = {110, 210, 255}, life = 0.28, maxLife = 0.28 })
            end
        elseif e.type == "synergy_flame" or e.type == "synergy_poison" then
            e.tickTimer = (e.tickTimer or 0) + activeDt
            local interval = e.tickInterval or 0.5
            while e.tickTimer >= interval and (e.remainingTicks or 0) > 0 do
                e.tickTimer = e.tickTimer - interval
                e.remainingTicks = e.remainingTicks - 1
                DamageArea(e.x, e.y, e.radius or 96, e.damage or 0, e.type == "synergy_flame" and {255, 110, 40} or {100, 255, 130}, e.skillId, true, 6)
            end
        elseif e.type == "synergy_storm_echo" and oldLife > 0 then
            e.tickTimer = (e.tickTimer or 0) + activeDt
            local interval = e.tickInterval or 0.45
            while e.tickTimer >= interval and (e.remainingTicks or 0) > 0 do
                e.tickTimer = e.tickTimer - interval
                e.remainingTicks = e.remainingTicks - 1
                DamageArea(e.x, e.y, e.radius or 96, e.damage or 0, {120, 220, 255}, e.skillId, true, 6)
                ApplySkillSynergyStormPush(e.x, e.y, e.radius or 96)
                AddEffect({ type = "area_pulse", x = e.x, y = e.y, radius = e.radius or 96, color = {120, 220, 255}, life = 0.28, maxLife = 0.28 })
            end
        elseif e.type == "synergy_cold_tick" and oldLife > 0 then
            e.tickTimer = (e.tickTimer or 0) - activeDt
            if e.tickTimer <= 0 and not e.triggered then
                e.triggered = true
                DamageArea(e.x, e.y, e.radius or 135, e.damage or 0, {130, 210, 255}, e.skillId, true, 6)
            end
        elseif e.type == "synergy_axe" and oldLife > 0 then
            local nextLife = math.max(0, oldLife - activeDt)
            local progress = 1 - nextLife / (e.maxLife or 0.8)
            if progress >= 0.5 and not e.returnHit then
                e.returnHit = true
                DamageSkillAlongSegment(e.x2, e.y2, e.x1, e.y1, e.width or 40, e.damage or 0, e.skillId, e.maxTargets or 8, {255, 190, 80})
            end
        elseif e.type == "flame_zone" and oldLife > 0 then
            e.tickTimer = (e.tickTimer or 0) + activeDt
            local interval = e.tickInterval or 0.6
            while e.tickTimer >= interval and (e.remainingTicks or 0) > 0 do
                e.tickTimer = e.tickTimer - interval
                e.remainingTicks = e.remainingTicks - 1
                DamageArea(e.x, e.y, e.radius or 92, e.damage or 0, {255, 105, 35}, e.sourceSkill or e.skillId or "flame_zone", true, 6)
                AddEffect({ type = "area_pulse", x = e.x, y = e.y, radius = e.radius or 92, color = {255, 105, 35}, life = 0.28, maxLife = 0.28 })
            end
        elseif e.type == "returning_axe" and oldLife > 0 then
            local nextLife = math.max(0, oldLife - activeDt)
            local progress = 1 - nextLife / (e.maxLife or 0.8)
            if progress >= 0.5 and not e.returnHit then
                e.returnHit = true
                DamageSkillAlongSegment(
                    e.x2,
                    e.y2,
                    e.x1,
                    e.y1,
                    e.width or 34,
                    e.damage or 0,
                    e.sourceSkill or e.skillId or "returning_axe",
                    e.maxTargets or 6,
                    {255, 185, 75}
                )
            end
        elseif e.type == "blackhole" and oldLife > 0 then
            local r2 = e.radius * e.radius
            for _, m in ipairs(monsters) do
                local dx = e.x - m.x
                local dy = e.y - m.y
                local d2 = dx * dx + dy * dy
                if m.hp > 0 and d2 > 4 and d2 <= r2 then
                    local dist = math.sqrt(d2)
                    local pullMultiplier = m.isBoss and 0.6 or 1.0
                    if m.type == "treasure" or m.type == "skill_treasure" then
                        pullMultiplier = pullMultiplier * (CONFIG.TreasureControlStrengthMultiplier or 0.5)
                    end
                    local pull = 170 * pullMultiplier * activeDt
                    AddMonsterControlDisplacement(
                        m,
                        dx / dist * pull,
                        dy / dist * pull
                    )
                end
            end
        elseif e.type == "poison_mist" and oldLife > 0 then
            e.tickTimer = (e.tickTimer or 0) + activeDt
            local interval = e.tickInterval or 0.5
            while e.tickTimer >= interval and (e.remainingTicks or 0) > 0 do
                e.tickTimer = e.tickTimer - interval
                e.remainingTicks = e.remainingTicks - 1
                local sourceSkill = e.sourceSkill or e.skillId or "poison_mist"
                local r2 = (e.radius or 105) * (e.radius or 105)
                local hitEffectCount = 0
                for _, m in ipairs(monsters) do
                    local dx = m.x - e.x
                    local dy = m.y - e.y
                    if m.hp > 0 and dx * dx + dy * dy <= r2 then
                        if hitEffectCount < 6 then
                            DamageMonsterBySkill(m, e.damage or 0, {100, 255, 120}, 10, sourceSkill)
                            hitEffectCount = hitEffectCount + 1
                        else
                            local damage = (e.damage or 0) * GetRangedMonsterSkillDamageMultiplier(m)
                            DamageMonster(m, damage, sourceSkill)
                        end
                        m.poisonSlowTimer = interval + 0.05
                        local slowScale = e.slowScale or 0.75
                        if m.type == "treasure" or m.type == "skill_treasure" then
                            slowScale = 1 - (1 - slowScale) * (CONFIG.TreasureControlStrengthMultiplier or 0.5)
                            m.poisonSlowTimer = m.poisonSlowTimer * (CONFIG.TreasureControlDurationMultiplier or 0.5)
                        end
                        m.poisonSlowScale = slowScale
                    end
                end
                AddEffect({ type = "area_pulse", x = e.x, y = e.y, radius = e.radius or 105, color = {100, 255, 120}, life = 0.28, maxLife = 0.28 })
            end
        elseif e.type == "awakening_delay" and oldLife > 0 then
            if oldLife - activeDt <= 0 and not e.triggered then
                e.triggered = true
                DamageArea(e.x, e.y, e.radius or 80, e.damage or 0, e.color or {210, 230, 255}, e.sourceSkill or e.skillId, true, 8)
                if e.freezeDuration then ApplyFreezeArea(e.x, e.y, e.radius or 80, e.freezeDuration) end
                if e.slowScale then
                    for _, monster in ipairs(monsters) do
                        local dx, dy = monster.x - e.x, monster.y - e.y
                        if monster.hp > 0 and dx * dx + dy * dy <= (e.radius or 80) ^ 2 then
                            monster.groundSlamSlowTimer = math.max(monster.groundSlamSlowTimer or 0, 1.0)
                            monster.groundSlamSlowScale = e.slowScale
                        end
                    end
                end
                AddEffect({ type = "area_pulse", x = e.x, y = e.y, radius = e.radius or 80, color = e.color or {210, 230, 255}, life = 0.35, maxLife = 0.35 })
            end
        elseif e.type == "awakening_zone" and oldLife > 0 then
            e.tickTimer = (e.tickTimer or 0) + activeDt
            while e.tickTimer >= (e.tickInterval or 0.45) and (e.remainingTicks or 0) > 0 do
                e.tickTimer = e.tickTimer - (e.tickInterval or 0.45)
                e.remainingTicks = e.remainingTicks - 1
                DamageArea(e.x, e.y, e.radius or 80, e.damage or 0, e.color or {255, 120, 40}, e.sourceSkill or e.skillId, true, 8)
            end
            if oldLife - activeDt <= 0 and e.terminalDamage and not e.triggered then
                e.triggered = true
                DamageArea(e.x, e.y, e.radius or 80, e.terminalDamage, e.color or {255, 120, 40}, e.sourceSkill or e.skillId, true, 10)
            end
        elseif e.type == "awakening_target" and oldLife > 0 then
            if oldLife - activeDt <= 0 and not e.triggered then
                e.triggered = true
                local target = e.target
                if target and target.hp > 0 then
                    local repeats = math.max(1, math.floor(e.repeats or 1))
                    for _ = 1, repeats do
                        DamageMonsterBySkill(target, e.damage or 0, e.color or {210, 230, 255}, 16, e.sourceSkill or e.skillId)
                    end
                    if e.skillId == "chain_lightning" then
                        DamageArea(target.x, target.y, e.radius or 48, (e.damage or 0) * 0.55, e.color or {210, 230, 255}, e.sourceSkill or e.skillId, true, 5)
                    end
                end
            end
        elseif e.type == "awakening_segment" and oldLife > 0 then
            if oldLife - activeDt <= 0 and not e.triggered then
                e.triggered = true
                DamageSkillAlongSegment(e.x1, e.y1, e.x2, e.y2, e.width or 40, e.damage or 0, e.sourceSkill or e.skillId, e.maxTargets or 6, e.color or {210, 230, 255})
                AddEffect({ type = "sword_wave", x1 = e.x1, y1 = e.y1, x2 = e.x2, y2 = e.y2, width = e.width or 40, life = 0.35, maxLife = 0.35 })
            end
        end
        e.life = oldLife - dt
        if e.life <= 0 then
            if e.countedVisual then
                visualEffectCount = math.max(0, visualEffectCount - 1)
            end
            table.remove(skillEffects, i)
        end
    end
end


function CommitDailySpeedUsage()
    NormalizeDailySpeedQuota()
    local pending = math.floor(dailySpeedSessionUsageSeconds or 0)
    if pending > 0 then
        playerData.dailySpeedUsageSeconds = math.min(
            GetDailySpeedQuotaLimit(),
            math.max(0, playerData.dailySpeedUsageSeconds or 0) + pending)
        dailySpeedSessionUsageSeconds = 0
        saveDirty = true
    end
end

function ConsumeDailySpeedQuota(dt)
    NormalizeDailySpeedQuota()
    if not IsQuotaLimitedGameSpeed(gameSpeed) then return end
    local remaining = GetDailySpeedQuotaRemaining()
    if remaining <= 0 then
        gameSpeed = 1
        if equipmentRiftActive then
            playerData.settings.lastEquipmentRiftGameSpeed = 1
        else
            playerData.settings.lastGameSpeed = 1
        end
        saveDirty = true
        speedQuotaNoticeText = GetDailySpeedAdClaimCount() < DAILY_SPEED_AD_MAX_CLAIMS
            and "倍速额度已用完，再点倍速可看广告增加2小时"
            or "今日倍速额度已全部用完，明日恢复"
        speedQuotaNoticeUntil = os.clock() + 5
        print("[SpeedQuota] 今日额度已用尽，已切换为 x1")
        return
    end
    dailySpeedSessionUsageSeconds = (dailySpeedSessionUsageSeconds or 0) + math.min(dt, remaining)
    if GetDailySpeedQuotaRemaining() <= 0 then
        gameSpeed = 1
        if equipmentRiftActive then
            playerData.settings.lastEquipmentRiftGameSpeed = 1
        else
            playerData.settings.lastGameSpeed = 1
        end
        saveDirty = true
        speedQuotaNoticeText = GetDailySpeedAdClaimCount() < DAILY_SPEED_AD_MAX_CLAIMS
            and "倍速额度已用完，再点倍速可看广告增加2小时"
            or "今日倍速额度已全部用完，明日恢复"
        speedQuotaNoticeUntil = os.clock() + 5
        print("[SpeedQuota] 今日额度已用尽，已切换为 x1")
    end
end

function CommitSessionPlayTime()
    CommitForegroundPlayTime()
    CommitDailySpeedUsage()
    realSessionPlayTime = 0
    sessionPlayTimeSaved = true
end

function BuildTrainingResult(cleared)
    local elapsed = math.max(0.01, trainingElapsedTime or gameTime or 0)
    local totalDamage = math.max(0, math.floor(damageStats and damageStats.total or 0))
    local rows = {
        { label = "主角", value = math.max(0, math.floor(damageStats and damageStats.hero or 0)) },
        { label = "分身", value = math.max(0, math.floor(damageStats and damageStats.clone or 0)) },
    }
    for skillId, value in pairs(damageStats and damageStats.skills or {}) do
        value = math.max(0, math.floor(value or 0))
        if value > 0 then
            local def = SKILL_DEFS and SKILL_DEFS[skillId] or nil
            table.insert(rows, {
                label = def and def.name or tostring(skillId),
                value = value,
            })
        end
    end
    table.sort(rows, function(a, b) return a.value > b.value end)
    return {
        cleared = cleared == true,
        mode = trainingModeKind,
        dummyTargetKind = trainingDummyTargetKind,
        floor = trainingFloor,
        elapsed = elapsed,
        totalDamage = totalDamage,
        dps = totalDamage / elapsed,
        kills = trainingKillCount or 0,
        rows = rows,
    }
end

function RestoreFormalStateAfterTraining()
    local state = trainingFormalState or {}
    playerData.currentFloor = math.max(1, math.floor(state.currentFloor or playerData.currentFloor or 1))
    playerData.nextBaseHpRatio = state.nextBaseHpRatio
    runFloor = playerData.currentFloor
    trainingFormalState = nil
end

function FinishTraining(cleared)
    if not trainingModeActive then return end
    trainingResult = BuildTrainingResult(cleared)
    ClearBattleRuntimeCache()
    ResetPendingLoot()
    runGoldReward = 0
    fiveBattleActive = false
    fiveBattleRequested = false
    fiveBattleRequestedFloorCount = 1
    fiveBattleFloorCount = 1
    fiveBattleSpeedMul = 1.0
    trainingModeActive = false
    RestoreFormalStateAfterTraining()
    currentScreen = "training_result"
    UI.SetRoot(UI.Panel { width = 0, height = 0 }, true)
    simulationAccumulator = 0
    print("[Training] 测试结束, 层数:", trainingResult.floor,
        "通关:", trainingResult.cleared,
        "总伤害:", trainingResult.totalDamage,
        "DPS:", math.floor(trainingResult.dps))
end

function StartEndlessRunState()
    NormalizeProgressionData()
    local previous = playerData.endlessRunState or {}
    local runId = math.max(
        os.time(),
        math.floor(tonumber(previous.runId) or 0) + 1
    )
    playerData.endlessRunState = {
        version = 1,
        active = true,
        runId = runId,
        currentFloor = CONFIG.EndlessStartFloor or 601,
        penaltyState = "pending",
        pausePending = false,
    }
    saveDirty = true
    SaveCloudData(true)
    print("[Endless] 新无尽挑战已登记, runId=", runId)
end

function ResolveEndlessRunState(reason)
    local state = playerData.endlessRunState or {}
    state.active = false
    state.currentFloor = math.max(
        CONFIG.EndlessStartFloor or 600,
        math.floor(tonumber(state.currentFloor) or (CONFIG.EndlessStartFloor or 600))
    )
    state.penaltyState = "resolved"
    playerData.endlessRunState = state
    saveDirty = true
    print("[Endless] 无尽挑战已结算, runId=", state.runId or 0,
        "原因=", tostring(reason))
end

function ResolveInterruptedEndlessRun()
    NormalizeProgressionData()
    local state = playerData.endlessRunState
    if type(state) ~= "table"
        or state.active ~= true
        or state.penaltyState ~= "pending" then
        return false
    end
    -- 主动暂存退出（返回主菜单继续）：不是中途死亡，不清算、保留进度
    if state.pausePending == true then
        state.pausePending = nil
        state.penaltyState = "pending"
        playerData.endlessRunState = state
        print("[Endless] 检测到主动暂存的无尽进度，保留继续（第",
            tostring(state.currentFloor), "层）")
        return false
    end
    state.penaltyState = "processing"
    playerData.endlessRunState = state
    SaveLocalSnapshot()

    ResetPendingLoot()
    runGoldReward = 0
    local goldBeforeDeath = math.max(0, playerData.gold or 0)
    local goldLoss = math.floor(goldBeforeDeath * 0.5)
    playerData.gold = goldBeforeDeath - goldLoss
    local interruptedFloor = math.max(
        CONFIG.EndlessStartFloor or 600,
        math.floor(tonumber(state.currentFloor) or (CONFIG.EndlessStartFloor or 600))
    )
    local goldReward = GetScoreGoldReward(0)
    AddGold(goldReward)
    local stoneReward = AwardRebirthStoneOnDeath(
        interruptedFloor,
        CONFIG.EndlessStartFloor or 600,
        1
    )
    local droppedSkills = DropHighestStarSkillsOnDeath()
    playerData.playCount = (playerData.playCount or 0) + 1
    playerData.rebirthCount = (playerData.rebirthCount or 0) + 1
    -- 无尽挑战中断（上次未正常结算）补执行死亡惩罚：同样扣减 2 层秘境压力
    AdjustEquipmentRiftPressure(-2, "无尽挑战死亡惩罚补结算")
    playerData.currentFloor = 1
    playerData.nextBaseHpRatio = nil
    playerData.selectedStartFloor = 0
    ResolveEndlessRunState("interrupted")
    SaveCloudData(true)
    print("[Endless] 启动时补执行死亡惩罚, 金币损失=", goldLoss,
        "金币奖励=", goldReward, "转生石=", stoneReward,
        "技能丢失=", #droppedSkills)
    return true
end

function HasPendingEndlessRun()
    local state = playerData.endlessRunState
    if type(state) ~= "table" or state.active ~= true then return false end
    if currentScreen == "playing" and endlessTrialActive then return false end
    return true
end

function PauseEndlessRunAndReturnToMenu()
    if not endlessTrialActive or currentScreen ~= "playing" then return false end
    endlessPauseMenuOpen = false
    endlessExitNoticeOpen = false
    local state = playerData.endlessRunState
    if type(state) ~= "table" then
        state = {}
        playerData.endlessRunState = state
    end
    -- 暂存进度：保持 active=true，记录当前层（下一层起点），不结算不惩罚
    state.active = true
    state.currentFloor = math.max(
        CONFIG.EndlessStartFloor or 600,
        math.floor(tonumber(runFloor) or state.currentFloor or (CONFIG.EndlessStartFloor or 600))
    )
    state.penaltyState = "pending"
    -- 标记为"主动暂存退出"，避免启动补结算把暂存误判为中途死亡
    state.pausePending = true
    playerData.endlessRunState = state
    endlessTrialActive = false
    ClearBattleRuntimeCache()
    ResetPendingLoot()
    runGoldReward = 0
    fiveBattleActive = false
    fiveBattleRequested = false
    fiveBattleRequestedFloorCount = 1
    fiveBattleFloorCount = 1
    fiveBattleSpeedMul = 1.0
    -- 暂存退出不重置普通爬塔进度（无尽进度独立存于 endlessRunState）
    currentScreen = "menu"
    saveDirty = true
    SaveCloudData(true)
    print(
        "[Endless] 无尽进度已暂存，返回主菜单；下次可从第",
        state.currentFloor, "层继续",
        "runId=", tostring(state.runId or 0)
    )
    GameEvents.Emit("scene:main")
    return true
end

function ShowEndlessExitNotice()
    if not endlessTrialActive or endlessExitNoticeOpen then return false end
    endlessExitNoticeOpen = true
    -- 暂停战斗模拟，避免弹窗期间基地继续掉血/刷怪
    endlessPauseMenuOpen = true
    local modal
    modal = UI.Modal {
        title = "无尽挑战",
        size = "sm",
        isOpen = false,
        closeOnOverlay = false,
        closeOnEscape = false,
        showCloseButton = false,
        children = {
            UI.Label {
                text = "当前无尽进度可暂存，返回主菜单后可从本层继续",
                fontSize = 13,
                fontColor = PX.textGold,
                textAlign = "center",
                whiteSpace = "normal",
            },
            UI.Button {
                width = "100%",
                text = "继续挑战",
                variant = "primary",
                onClick = function()
                    modal:Close()
                end,
            },
            UI.Button {
                width = "100%",
                text = "返回主菜单",
                variant = "secondary",
                onClick = function()
                    modal:Close()
                    PauseEndlessRunAndReturnToMenu()
                end,
            },
            UI.Button {
                width = "100%",
                text = "主动重生",
                variant = "danger",
                onClick = function()
                    modal:Close()
                    if RebirthToFirstFloor ~= nil then
                        RebirthToFirstFloor()
                    end
                end,
            },
        },
        onClose = function(self)
            endlessExitNoticeOpen = false
            endlessPauseMenuOpen = false
            self:Destroy()
        end,
    }
    modal:Open()
    return true
end

function StartGame(data)
    data = data or {}
    if not HasSelectedRunClass() then
        print("[Class] 当前局未选择职业，拒绝开始战斗")
        ShowClassSelectionPage(true)
        return
    end
    local requestedEquipmentRift = data.equipmentRift == true
    local requestedEndless = data.endlessTrial == true
    if requestedEndless and not IsEndlessUnlocked() then
        print("[Endless] 普通第600层尚未通关，拒绝启动")
        ShowTrialSelectionPage("通关普通第600层后开放无尽试炼")
        return
    end
    endlessTrialActive = requestedEndless
    endlessResultFloor = 0
    trainingModeActive = data.training == true
        and not requestedEquipmentRift
        and not requestedEndless
    trainingModeKind = data.trainingMode == "dummy" and "dummy" or "wave"
    trainingDummyTargetKind = data.trainingDummyTarget == "boss" and "boss" or "normal"
    trainingFloor = math.max(1, math.floor(data.trainingFloor or 1))
    if trainingModeActive and (IsTrainingGroundUnlocked == nil or not IsTrainingGroundUnlocked()) then
        trainingModeActive = false
        print("[Training] 未解锁训练场，拒绝启动")
        ShowTrainingGroundPage("通关第10层后开放训练场")
        return
    end
    if trainingModeActive then
        local maxTrainingFloor = GetMaxTrainingFloor and GetMaxTrainingFloor() or 1
        if trainingFloor >= 10 then
            trainingFloor = math.min(maxTrainingFloor, math.floor(trainingFloor / 10) * 10)
        else
            trainingFloor = 1
        end
        trainingFormalState = {
            currentFloor = playerData.currentFloor,
            nextBaseHpRatio = playerData.nextBaseHpRatio,
        }
        trainingElapsedTime = 0
        trainingKillCount = 0
        trainingDamageSamples = {}
        trainingResult = nil
        fiveBattleRequested = false
        fiveBattleRequestedFloorCount = 1
        if IsTrainingDummyMode() then
            print("[Training] 开始" .. (IsTrainingDummyBossTarget() and "Boss" or "普通") .. "木桩 DPS 测试")
        else
            print("[Training] 开始第" .. tostring(trainingFloor) .. "层怪潮伤害测试")
        end
    elseif requestedEquipmentRift then
        if not PrepareEquipmentRiftRun(data) then return end
    else
        equipmentRiftActive = false
    end
    if endlessTrialActive then
        equipmentRiftActive = false
        fiveBattleRequested = false
        fiveBattleRequestedFloorCount = 1
        if data.endlessContinue == true then
            -- 继续上次暂存的无尽进度：沿用原 runId 与层数，不重新登记
            local state = playerData.endlessRunState
            if type(state) ~= "table" or state.active ~= true then
                state = {}
                playerData.endlessRunState = state
            end
            state.active = true
            state.penaltyState = "pending"
            state.pausePending = nil
            playerData.endlessRunState = state
            endlessRunContinueFloor = math.max(
                CONFIG.EndlessStartFloor or 600,
                math.floor(tonumber(state.currentFloor) or (CONFIG.EndlessStartFloor or 600))
            )
            print("[Endless] 继续暂存无尽进度, runId=", tostring(state.runId or 0),
                "从第", endlessRunContinueFloor, "层开始")
        else
            endlessRunContinueFloor = 0
            StartEndlessRunState()
        end
    end
    if not equipmentRiftActive then
        EnsureRunSkillSynergies(true)
    end
    currentScreen = "playing"
    local requestedRoguelikeStartFloor = data
        and data.roguelikeStartFloor
        and math.max(1, math.floor(data.roguelikeStartFloor))
        or nil
    ResetPendingLoot()
    NormalizeEquipmentSettings()
    local requestedFloorCount = math.max(1, math.floor(data and data.battleFloorCount or 1))
    if data.autoContinue == true then
        fiveBattleRequestedFloorCount = requestedFloorCount >= 20 and 20
            or (requestedFloorCount >= 10 and 10
                or (requestedFloorCount >= 5 and 5 or 1))
        fiveBattleRequested = fiveBattleRequestedFloorCount > 1
    elseif requestedFloorCount >= 20 then
        fiveBattleRequested = playerData.settings
            and playerData.settings.twentyBattleUnlocked == true
            and playerData.settings.twentyBattleEnabled == true
        fiveBattleRequestedFloorCount = fiveBattleRequested and 20 or 1
    elseif requestedFloorCount >= 10 then
        fiveBattleRequested = playerData.settings
            and playerData.settings.tenBattleUnlocked == true
            and playerData.settings.tenBattleEnabled == true
        fiveBattleRequestedFloorCount = fiveBattleRequested and 10 or 1
    elseif requestedFloorCount >= 5 then
        fiveBattleRequested = playerData.settings
            and playerData.settings.fiveBattleEnabled == true
        fiveBattleRequestedFloorCount = fiveBattleRequested and 5 or 1
    else
        fiveBattleRequested = false
        fiveBattleRequestedFloorCount = 1
    end
    if equipmentRiftActive or endlessTrialActive then
        fiveBattleRequested = false
        fiveBattleRequestedFloorCount = 1
    end
    NormalizeDailySpeedQuota()
    local inheritedGameSpeed = tonumber(data and data.inheritedGameSpeed)
    if equipmentRiftActive then
        -- 装备秘境(装备试炼)每把沿用上一把秘境设置的倍速
        gameSpeed = inheritedGameSpeed
            or math.max(1, math.floor(playerData.settings.lastEquipmentRiftGameSpeed or 1))
    else
        gameSpeed = inheritedGameSpeed or playerData.settings.lastGameSpeed or 1
    end
    if not trainingModeActive
        and IsQuotaLimitedGameSpeed(gameSpeed)
        and IsDailySpeedQuotaExhausted() then
        gameSpeed = 1
        if equipmentRiftActive then
            playerData.settings.lastEquipmentRiftGameSpeed = 1
        else
            playerData.settings.lastGameSpeed = 1
        end
    end
    if gameSpeed == 10 and not (playerData.settings and playerData.settings.tenSpeedUnlocked) then
        gameSpeed = 1
    elseif gameSpeed ~= 10 and gameSpeed > GetMaxGameSpeed() then
        gameSpeed = GetMaxGameSpeed()
    end
    autoSaveTimer = 0
    autoSavePending = false
    autoSavePendingTimer = 0
    if #bgImages > 0 then
        currentBgIndex = math.random(1, #bgImages)
    end
    UI.SetRoot(UI.Panel { width = 0, height = 0 }, true)
    InitGame()
    if requestedRoguelikeStartFloor ~= nil then
        roguelikeNodeStartFloor = requestedRoguelikeStartFloor
        pendingRoguelikeBattleStart = true
        print("[Roguelike] 选层复活以第" .. tostring(roguelikeNodeStartFloor) .. "层作为首个节点")
        if BeginRoguelikeSettlement({ roguelikeNodeStartFloor }) then
            print("[Game] 等待起始层肉鸽选择完成")
            return
        end
        pendingRoguelikeBattleStart = false
    end
    print("[Game] 游戏开始! 背景:", currentBgIndex)
end

function ShowGameOver()
    print("[DeathPath] ShowGameOver 进入: 训练=", tostring(trainingModeActive),
        "秘境=", tostring(equipmentRiftActive),
        "无尽=", tostring(endlessTrialActive),
        "当前压力=", tostring(playerData.equipmentRiftPressure))
    if trainingModeActive then
        SpawnParticles(base.x, base.y, 20, {255, 100, 50})
        FinishTraining(false)
        return
    end
    if equipmentRiftActive then
        SpawnParticles(base.x, base.y, 20, {255, 100, 50})
        FailEquipmentRift("base_destroyed")
        return
    end
    local wasEndless = endlessTrialActive == true
    if wasEndless then
        endlessResultFloor = math.max(
            playerData.endlessBestFloor or 0,
            (CONFIG.EndlessStartFloor or 600) - 1
        )
        ResolveEndlessRunState("base_destroyed")
    end
    -- 主线爬塔/无尽挑战基地死亡：统一扣减 2 层秘境压力
    AdjustEquipmentRiftPressure(-2, "主线爬塔死亡惩罚")
    ClearBattleRuntimeCache()
    local nextRunId = math.max(0, math.floor(playerData.rebirthCount or 0)) + 1
    ResetRoguelikeRun(nextRunId)
    currentScreen = "gameover"
    saveDirty = true
    SpawnParticles(base.x, base.y, 20, {255, 100, 50})
    SpawnParticles(base.x, base.y - 30, 15, {255, 200, 50})

    CommitPendingLoot("death")

    local goldReward = GetScoreGoldReward(score) + (runGoldReward or 0)
    local goldBeforeDeath = playerData.gold or 0
    local goldLoss = math.floor(goldBeforeDeath * 0.5)
    playerData.gold = math.max(0, goldBeforeDeath - goldLoss)
    AddGold(goldReward)
    lastDeathGoldLoss = goldLoss
    lastDeathGoldReward = goldReward
    ---@type number
    local rebirthStoneReward = AwardRebirthStoneOnDeath(runFloor or playerData.currentFloor or 1, runStartFloor or runFloor or 1, wasEndless and 1 or 0)
    lastDeathRebirthStoneReward = rebirthStoneReward
    runGoldReward = 0
    fiveBattleActive = false
    fiveBattleRequested = false
    fiveBattleRequestedFloorCount = 1
    fiveBattleFloorCount = 1
    fiveBattleSpeedMul = 1.0
    local droppedSkills = DropHighestStarSkillsOnDeath()
    if #droppedSkills > 0 then
        local parts = {}
        for _, skill in ipairs(droppedSkills) do
            table.insert(parts, tostring(skill.name or "技能") .. " " .. tostring(skill.star or 1) .. "星")
            print("[GameOver] 死亡丢失技能", skill.name or skill.id, skill.star or 1, "星")
        end
        lastDeathSkillLossText = "技能丢失 " .. tostring(#droppedSkills) .. "张：" .. table.concat(parts, "、")
    else
        lastDeathSkillLossText = "没有技能可丢失"
    end
    CommitSessionPlayTime()
    playerData.totalKills = playerData.totalKills + killCount
    playerData.playCount = playerData.playCount + 1
    -- 无尽死亡后与普通死亡一致，强制回到第1层重新爬塔：
    -- 无尽挑战结束时本轮肉鸽属性已被 ResetRoguelikeRun 清空，
    -- 需要重新从低层通关积攒三选一属性，才能再次带入下一把无尽挑战。
    playerData.currentFloor = 1
    playerData.nextBaseHpRatio = nil
    playerData.selectedStartFloor = 0
    deathSelectAvailable = true
    deathSelectPromptVisible = false
    deathSelectPromptDismissed = false
    playerData.rebirthCount = playerData.rebirthCount + 1
    if score > playerData.highScore then
        playerData.highScore = score
    end
    UpdateCloneUnlockProgress()
    endlessTrialActive = false
    endlessPauseMenuOpen = false
    endlessExitNoticeOpen = false

    SaveCloudData(true)
    print("[GameOver] 分数已提交, 金币损失", goldLoss, "金币+", goldReward, "转生石+", rebirthStoneReward, "击杀+", killCount, "下次重生第1层")
end

function SpawnTrainingDummy()
    local dummyX = screenW * 0.5
    local dummyY = screenH * 0.46
    local bossTarget = IsTrainingDummyBossTarget()
    local dummy = {
        type = "training_dummy",
        isTrainingDummy = true,
        isBoss = bossTarget,
        x = dummyX,
        y = dummyY,
        anchorX = dummyX,
        anchorY = dummyY,
        radius = bossTarget and 34 or 30,
        hp = 1,
        maxHp = 1,
        speed = 0,
        damage = 0,
        color = bossTarget and { 164, 76, 190 } or { 194, 142, 66 },
        floor = 1,
        hitFlash = 0,
        hitStunTimer = 0,
        freezeTimer = 0,
        poisonSlowTimer = 0,
        groundSlamSlowTimer = 0,
        spawnVisualTimer = 0,
        spawnVisualDuration = 0.01,
        baseAttackCooldown = 0,
    }
    monsters = { dummy }
    floorSpawnPlan = {}
    floorSpawnIndex = 1
    floorKillCount = 0
    floorKillTarget = 0
    floorBossCount = 0
    floorBossDefeatedCount = 0
    bossAlive = bossTarget
    print("[Training] 木桩已生成, 类型:", bossTarget and "Boss" or "普通",
        "位置:", math.floor(dummyX), math.floor(dummyY))
end

function InitGame()
    UpdateScreenMetrics()
    battleBulwarkRecoveryTriggered = false
    battleBulwarkDamageReductionTimer = 0
    ClearBattleRuntimeCache()
    RebuildBattleRuntimeCache()
    local bottomInset = (safeInset and safeInset.bottom or 0)
    base.x = screenW / 2
    base.y = screenH - CONFIG.BaseHeight / 2 - 18 - bottomInset
    local maxHp = GetBaseMaxHP()
    local hpRatio = (trainingModeActive or equipmentRiftActive)
        and nil
        or playerData.nextBaseHpRatio
    if hpRatio ~= nil then
        base.hp = math.max(1, math.min(maxHp, maxHp * hpRatio))
        playerData.nextBaseHpRatio = nil
        print("[Floor] 继承上一层血量:", math.floor(base.hp), "/", maxHp)
    else
        base.hp = maxHp
    end
    base.maxHp = maxHp
    base.flashTimer = 0
    base.shield = 0
    base.shieldAwakeningLevel = 0
    base.shieldDamageSource = nil
    hero.x = screenW / 2
    hero.y = screenH - CONFIG.BaseHeight - 130 - bottomInset
    if IsTrainingDummyMode() then
        hero.y = screenH * 0.46 + math.max(16, GetHeroAttackRadius() * 0.72)
    end
    hero.targetX = hero.x
    hero.targetY = hero.y
    autoBattleDefendX = hero.x
    autoBattleDefendY = hero.y
    autoBattleTarget = nil
    autoBattleRetargetTimer = 0
    autoBattleManualOverrideTimer = 0
    autoBattleManualInputActive = false
    autoBattleManualTouchId = nil
    if playerData.settings == nil then
        playerData.settings = {}
    end
    if playerData.settings.autoBattleEnabled == nil then
        playerData.settings.autoBattleEnabled = true
    end
    print(
        playerData.settings.autoBattleEnabled
            and "[AutoBattle] 已启用，空场防守位置:"
            or "[AutoBattle] 已关闭，等待玩家手动移动，空场位置:",
        math.floor(autoBattleDefendX),
        math.floor(autoBattleDefendY)
    )
    hero.attackTimer = 0
    hero.swingAngle = 0
    hero.isSwinging = false
    hero.facingAngle = -math.pi / 2
    monsters = {}
    monsterProjectiles = {}
    clones = {}
    if playerData.cloneUnlocked and (playerData.cloneCount or 0) > 0 then
        for i = 1, playerData.cloneCount do
            table.insert(clones, {
                index = i,
                x = hero.x + math.random(-60, 60),
                y = hero.y + math.random(-60, 60),
                targetX = hero.x,
                targetY = hero.y,
                attackTimer = math.random() * CONFIG.AttackCooldown,
                target = nil,
                retargetTimer = (i - 1) * 0.07,
                targetLockTimer = 0,
                wanderTimer = 0,
            })
        end
    end
    particles = {}
    skillEffects = {}
    visualEffectCount = 0
    ClearBattleSynergyRuntime()
    RebuildBattleSynergyRuntime()
    damageRankExpanded = false
    ResetDamageStats()
    awakeningEnergy = 0
    awakeningTimer = 0
    awakeningActive = false
    InitSkillRuntime(true)
    spawnTimer = 0
    currentSpawnInterval = CONFIG.SpawnInterval
    gameTime = 0
    simulationAccumulator = 0
    realSessionPlayTime = 0
    sessionPlayTimeSaved = false
    score = 0
    runGoldReward = 0
    killCount = 0
    runFloor = equipmentRiftActive
        and equipmentRiftSourceFloor
        or (trainingModeActive
            and trainingFloor
            or (endlessTrialActive
                and math.max(
                    CONFIG.EndlessStartFloor or 600,
                    math.floor(endlessRunContinueFloor or (CONFIG.EndlessStartFloor or 600))
                )
                or math.min(
                    CONFIG.NormalFloorCap or 600,
                    math.max(1, playerData.currentFloor or (playerData.selectedStartFloor or 0))
                )))
    fiveBattleActive = fiveBattleRequested == true
    fiveBattleFloorCount = fiveBattleActive and math.max(2, math.floor(fiveBattleRequestedFloorCount or 5)) or 1
    if fiveBattleActive and fiveBattleFloorCount >= 20 then
        fiveBattleSpeedMul = 2.0
        print(
            "[TwentyBattle] 动态刷怪启用, 快速补怪阈值:",
            CONFIG.TwentyBattleSpawnFastUntil,
            "恢复正常阈值:",
            CONFIG.TwentyBattleSpawnNormalAt,
            "单帧预算:",
            CONFIG.TwentyBattleSpawnPerFrameBudget,
            "怪物上限:",
            CONFIG.MaxMonsters
        )
    elseif fiveBattleActive then
        fiveBattleSpeedMul = 1.5
    else
        fiveBattleSpeedMul = 1.0
    end
    fiveBattleStartFloor = runFloor
    fiveBattleEndFloor = fiveBattleActive and (runFloor + fiveBattleFloorCount - 1) or runFloor
    if endlessTrialActive then
        runStartFloor = CONFIG.EndlessStartFloor or 601
        playerData.endlessRunState.currentFloor = runFloor
        playerData.nextBaseHpRatio = nil
    elseif not trainingModeActive and not equipmentRiftActive then
        if (playerData.rebirthRunStartFloor or 0) <= 0 or (playerData.rebirthRunCompletedFloors or 0) <= 0 then
            playerData.rebirthRunStartFloor = runFloor
        end
        runStartFloor = math.max(1, playerData.rebirthRunStartFloor or runFloor)
        playerData.currentFloor = runFloor
        playerData.rebirthRunActive = true
        print("[RebirthStone] 本轮挑战起始层:", runStartFloor, "累计通关层数:", playerData.rebirthRunCompletedFloors or 0)
    else
        runStartFloor = runFloor
    end
    if IsTrainingDummyMode() then
        SpawnTrainingDummy()
    elseif equipmentRiftActive then
        StartEquipmentRiftDifficulty(1)
    else
        StartFloor(runFloor)
    end
end


function SimulateBattleStep(dt)
    battleStepMonsterCount = -1
    battleStepAliveCount = 0
    for cacheKey in pairs(clusterCenterCache) do
        clusterCenterCache[cacheKey] = nil
    end
    clusterSpatialBuckets = nil
    battleBulwarkDamageReductionTimer = math.max(
        0,
        (battleBulwarkDamageReductionTimer or 0) - dt
    )
    gameTime = gameTime + dt
    UpdateHero(dt)
    UpdateMonsters(dt)
    battleStepMonsterCount = -1
    battleStepAliveCount = 0
    if currentScreen ~= "playing" then
        simulationAccumulator = 0
        return false
    end
    if base.hp <= 0 then
        simulationAccumulator = 0
        ShowGameOver()
        return false
    end
    if not IsTrainingDummyMode() then
        UpdateSpawner(dt)
    end
    UpdateAttack(dt)
    UpdateAwakening(dt)
    UpdateSkills(dt)
    UpdateSkillEffects(dt)
    UpdateClones(dt)
    UpdateBase(dt)
    return currentScreen == "playing"
end

function HandleKeyDown(eventType, eventData)
    local key = eventData["Key"]:GetInt()
    if endlessTrialActive
        and currentScreen == "playing"
        and key == KEY_ESCAPE then
        ShowEndlessExitNotice()
    end
end

function HandleUpdate(eventType, eventData)
    local dt = eventData["TimeStep"]:GetFloat()
    spawnedMonstersThisFrame = 0
    specialUnitSpawnedThisFrame = false
    -- 兜底：若结算期云存档延迟合并已开启，但已离开结算界面
    -- （三选一/续关倒计时），说明结算链路已结束或中途跳出，强制 flush，
    -- 防止 defer 悬空导致进度不落盘。
    if cloudSaveDeferred == true
        and currentScreen ~= "roguelike"
        and currentScreen ~= "auto_continue" then
        if EndDeferredCloudSave ~= nil then
            EndDeferredCloudSave()
        end
    end
    UpdateScreenMetrics()
    ProcessAssetLoadQueue(ASSET_LOADS_PER_FRAME)
    -- 先投递挂起的广告结果（脱离 SDK native 回调栈后再做 UI 结算/重建）
    DeliverPendingRewardAdResult()
    if rewardAdInFlight and rewardAdDeadline > 0 and os.clock() >= rewardAdDeadline then
        -- 仅结束本次流程并解锁 UI；SDK 迟到返回 success 时仍会补发奖励
        rewardAdFlowEnded = true
        FinishRewardAd({ success = false, msg = "广告响应超时" })
    end
    if UpdateLeaderboardFirstWingRefresh ~= nil then
        UpdateLeaderboardFirstWingRefresh(dt)
    end
    if cloudRetryPending and not appIsInBackground
        and not cloudPrepareInProgress
        and not reconnectInProgress
        and not CLOUD_DATA_FETCH_IN_PROGRESS
        and not cloudSaveInProgress then
        cloudRetryTimer = math.max(0, (cloudRetryTimer or 0) - dt)
        if cloudRetryTimer <= 0 then
            cloudRetryPending = false
            if cloudSaveRetryOnly and cloudDataReadyForSave then
                cloudSaveRetryOnly = false
                print("[Cloud] 到期后只重试云写入，不重新读取云档")
                AutoSaveIfNeeded(true)
            elseif BeginCloudRecovery ~= nil then
                BeginCloudRecovery("scheduled_retry")
            end
        end
    end

    -- 管理员自发放挂起重试：云存档就绪后自动补领到账
    if ADMIN_MATERIAL_GRANT_SYNC_PENDING
        and not ADMIN_MATERIAL_GRANT_SYNC_IN_FLIGHT
        and not cloudPrepareInProgress
        and not reconnectInProgress then
        ADMIN_MATERIAL_GRANT_SYNC_TIMER = math.max(0, (ADMIN_MATERIAL_GRANT_SYNC_TIMER or 0) - dt)
        if ADMIN_MATERIAL_GRANT_SYNC_TIMER <= 0 then
            ADMIN_MATERIAL_GRANT_SYNC_TIMER = ADMIN_MATERIAL_GRANT_SYNC_INTERVAL
            if RetryAdminSelfGrants ~= nil then
                RetryAdminSelfGrants()
            end
        end
    end

    -- 普通玩家自动补领管理员发放：周期性拉取管理员队列并领取
    if not IS_CLOUD_ADMIN
        and cloudDataLoaded
        and cloudDataReadyForSave
        and not ADMIN_GRANT_POLL_IN_FLIGHT
        and not cloudPrepareInProgress
        and not reconnectInProgress
        and not CLOUD_DATA_FETCH_IN_PROGRESS then
        ADMIN_GRANT_POLL_TIMER = math.max(0, (ADMIN_GRANT_POLL_TIMER or 0) - dt)
        if ADMIN_GRANT_POLL_TIMER <= 0 then
            ADMIN_GRANT_POLL_TIMER = ADMIN_GRANT_POLL_INTERVAL
            if PollAdminGrantsForNormalPlayer ~= nil then
                PollAdminGrantsForNormalPlayer()
            end
        end
    end

    if appIsInBackground or rewardAdBattlePaused or endlessPauseMenuOpen then
        simulationAccumulator = 0
        return
    end

    if currentScreen == "playing"
        and playerData.settings ~= nil
        and playerData.settings.autoBattleEnabled == true
        and not autoBattleManualInputActive
        and autoBattleManualOverrideTimer > 0 then
        autoBattleManualOverrideTimer = math.max(0, autoBattleManualOverrideTimer - dt)
        if autoBattleManualOverrideTimer <= 0 then
            autoBattleTarget = nil
            autoBattleRetargetTimer = 0
            print("[AutoBattle] 手动接管结束，恢复自动索敌")
        end
    end

    if currentScreen == "auto_continue" then
        UpdateAutoContinueCountdown(dt)
    end

    ObserveDailySpeedClock(dt)
    autoSaveTimer = autoSaveTimer + dt
    if gamePlayTimeTrackingStarted and not isGameLoading
        and not trainingModeActive
        and not equipmentRiftActive
        and currentScreen ~= "training_result"
        and currentScreen ~= "rift_result" then
        foregroundPlayTimeSessionSeconds = (foregroundPlayTimeSessionSeconds or 0) + dt
    end
    if currentScreen == "playing" then
        if not trainingModeActive and not equipmentRiftActive then
            MarkSaveDirty()
            if autoSaveTimer >= AUTO_SAVE_INTERVAL then
                autoSaveTimer = 0
                autoSavePending = true
                autoSavePendingTimer = 0
                print("[AutoSave] 定时存档已排队")
            end
            ConsumeDailySpeedQuota(dt)
            realSessionPlayTime = realSessionPlayTime + dt
        elseif trainingModeActive then
            trainingElapsedTime = trainingElapsedTime + dt * gameSpeed
            TrimTrainingDamageSamples()
        end
        local simulationScale = GetBattleSimulationScale()
        local gameDt = dt * simulationScale
        battleSimulationOverloaded = false
        battleSimulationBacklogFrames = 0
        battleSimulationSubstepsLastFrame = 0
        if simulationScale > 5 then
            simulationAccumulator = math.min(
                SIM_MAX_ACCUMULATOR,
                simulationAccumulator + gameDt
            )
            local substeps = 0
            while simulationAccumulator >= SIM_FIXED_STEP
                and substeps < SIM_MAX_SUBSTEPS
                and currentScreen == "playing" do
                simulationAccumulator = simulationAccumulator - SIM_FIXED_STEP
                substeps = substeps + 1
                if not SimulateBattleStep(SIM_FIXED_STEP) then
                    break
                end
            end
            battleSimulationSubstepsLastFrame = substeps
            if substeps >= SIM_MAX_SUBSTEPS
                and simulationAccumulator >= SIM_FIXED_STEP then
                battleSimulationBacklogFrames = 1
                battleSimulationOverloaded = true
            end
        else
            simulationAccumulator = 0
            SimulateBattleStep(gameDt)
        end
        if autoSavePending then
            autoSavePendingTimer = autoSavePendingTimer + dt
            local lightFrame = not battleSimulationOverloaded
                and battleSimulationSubstepsLastFrame <= 1
                and #monsters < 45
                and #skillEffects < 35
            if lightFrame or autoSavePendingTimer >= AUTO_SAVE_MAX_DEFER then
                autoSavePending = false
                autoSavePendingTimer = 0
                print(lightFrame
                    and "[AutoSave] 轻负载帧执行定时存档"
                    or "[AutoSave] 达到最大延迟，执行定时存档")
                AutoSaveIfNeeded(false)
            end
        end
        UpdateParticles(dt)  -- 粒子不加速，保持视觉流畅
        if IsTwentyBattleTurboMode()
            and #particles > GetCurrentParticleLimit() then
            local excess = #particles - GetCurrentParticleLimit()
            for _ = 1, excess do
                table.remove(particles)
            end
        end
    else
        simulationAccumulator = 0
    end
end

function IsValidAutoBattleTarget(target)
    return target ~= nil and (target.hp or 0) > 0 and target.treasureEscaped ~= true
end

function UpdateAutoBattleControl(dt)
    if playerData.settings == nil
        or playerData.settings.autoBattleEnabled ~= true then
        autoBattleTarget = nil
        autoBattleRetargetTimer = 0
        autoBattleManualOverrideTimer = 0
        return
    end
    if autoBattleManualInputActive or autoBattleManualOverrideTimer > 0 then return end

    if not IsValidAutoBattleTarget(autoBattleTarget) then
        autoBattleTarget = nil
        autoBattleRetargetTimer = 0
    end

    autoBattleRetargetTimer = math.max(0, (autoBattleRetargetTimer or 0) - dt)
    if autoBattleTarget == nil and autoBattleRetargetTimer <= 0 then
        autoBattleTarget = FindNearestTreasureMonster(hero.x, hero.y)
            or FindNearestAliveMonster(base.x, base.y)
        autoBattleRetargetTimer = AUTO_BATTLE_RETARGET_INTERVAL
        if autoBattleTarget ~= nil then
            print("[AutoBattle] 锁定目标:", autoBattleTarget.type or "normal",
                IsAnyTreasureMonster(autoBattleTarget.type) and "(宝箱优先)" or "(离基地最近)")
        end
    end

    if autoBattleTarget ~= nil then
        local dx = autoBattleTarget.x - hero.x
        local dy = autoBattleTarget.y - hero.y
        local distance = math.sqrt(dx * dx + dy * dy)
        local stopDistance = GetHeroAttackRadius() * 0.78
        if distance > stopDistance then
            hero.targetX = autoBattleTarget.x - dx / distance * stopDistance
            hero.targetY = autoBattleTarget.y - dy / distance * stopDistance
        else
            hero.targetX = hero.x
            hero.targetY = hero.y
            if distance > 0 then
                hero.facingAngle = math.atan(dy, dx)
            end
        end
        return
    end

    hero.targetX = autoBattleDefendX
    hero.targetY = autoBattleDefendY
end

function UpdateHero(dt)
    UpdateAutoBattleControl(dt)
    local dx = hero.targetX - hero.x
    local dy = hero.targetY - hero.y
    local dist = math.sqrt(dx * dx + dy * dy)
    if dist > 2 then
        local moveSpeed = GetHeroMoveSpeed()
        local isAutoControlling = playerData.settings ~= nil
            and playerData.settings.autoBattleEnabled == true
            and not autoBattleManualInputActive
            and (autoBattleManualOverrideTimer or 0) <= 0
        if isAutoControlling then
            moveSpeed = moveSpeed * AUTO_BATTLE_MOVE_SPEED_MULTIPLIER
        end
        local speed = math.min(moveSpeed * dt, dist)
        hero.x = hero.x + (dx / dist) * speed
        hero.y = hero.y + (dy / dist) * speed
        hero.facingAngle = math.atan(dy, dx)
    end
    hero.x = math.max(CONFIG.HeroRadius, math.min(screenW - CONFIG.HeroRadius, hero.x))
    hero.y = math.max(CONFIG.HeroRadius, math.min(screenH - CONFIG.HeroRadius - 30, hero.y))
    if hero.isSwinging then
        hero.swingAngle = hero.swingAngle + dt * 15 * hero.swingDir
        if math.abs(hero.swingAngle) > math.pi * 0.8 then
            hero.isSwinging = false
            hero.swingAngle = 0
        end
    end
end

function AddMonsterControlDisplacement(monster, offsetX, offsetY)
    if monster.isTrainingDummy then return end
    if monster.type == "treasure" or monster.type == "skill_treasure" then
        monster.treasureControlOffsetX = (monster.treasureControlOffsetX or 0) + offsetX
        monster.treasureControlOffsetY = (monster.treasureControlOffsetY or 0) + offsetY
    else
        monster.x = monster.x + offsetX
        monster.y = monster.y + offsetY
    end
end

function GetTreasureEscapeSpeedScale(monster)
    local scale = 1.0
    if monster.freezeTimer and monster.freezeTimer > 0 then scale = scale * 0.8 end
    if monster.poisonSlowTimer and monster.poisonSlowTimer > 0 then
        scale = scale * (monster.poisonSlowScale or 0.875)
    end
    if monster.groundSlamSlowTimer and monster.groundSlamSlowTimer > 0 then
        scale = scale * (monster.groundSlamSlowScale or 0.775)
    end
    return math.max(0.45, scale)
end

function UpdateTreasureDisplayText(monster)
    monster.treasureDisplayRefreshTimer = (monster.treasureDisplayRefreshTimer or 0) - SIM_FIXED_STEP
    if monster.treasureDisplayRefreshTimer > 0
        and monster.treasureDisplayText ~= nil then
        return
    end
    monster.treasureDisplayRefreshTimer = 0.1
    local isSkillTreasure = monster.type == "skill_treasure"
    local warningRemaining = math.max(0, monster.treasureWarningTimer or 0)
    local escapeRemaining = math.max(0,
        monster.treasureEscapeTimer or CONFIG.TreasureEscapeDuration or 10)
    if warningRemaining > 0 then
        monster.treasureDisplayText = isSkillTreasure
            and "5本技能宝箱出现"
            or "5倍金币宝箱出现"
        return
    end
    local urgentText = escapeRemaining <= 2.5
        and "逃逸 " .. string.format("%.1f", escapeRemaining) .. "秒"
        or (escapeRemaining <= 5
            and "逃逸 " .. string.format("%.1f", escapeRemaining) .. "秒"
            or nil)
    if (monster.treasureMiddlePauseTimer or 0) > 0 then
        monster.treasureDisplayText = "停留 " .. string.format("%.1f", escapeRemaining) .. "秒"
    else
        monster.treasureDisplayText = urgentText
            or string.format("逃逸 %.1f秒", escapeRemaining)
    end
end

function UpdateTreasureEscape(monster, dt, monsterIndex)
    local warningDuration = math.max(0, CONFIG.TreasureWarningDuration or 0.8)
    if (monster.treasureWarningTimer or 0) > 0 then
        monster.treasureWarningTimer = math.max(0, monster.treasureWarningTimer - dt)
        monster.treasureEscapeTimer = monster.treasureWarningTimer
            + math.max(0, CONFIG.TreasureMiddlePauseDuration or 0.6)
            + math.max(0.4,
                math.max(1, CONFIG.TreasureEscapeDuration or 10.0)
                    - warningDuration
                    - math.max(0, CONFIG.TreasureMiddlePauseDuration or 0.6))
        return
    end

    local pauseDuration = math.max(0, CONFIG.TreasureMiddlePauseDuration or 0.6)
    local escapeDuration = math.max(1, CONFIG.TreasureEscapeDuration or 10.0)
    local travelDuration = math.max(0.4, escapeDuration - warningDuration - pauseDuration)
    monster.treasureTravelProgress = math.max(0, monster.treasureTravelProgress or 0)

    if monster.treasureTravelProgress >= 0.5 and not monster.treasureMiddlePaused then
        monster.treasureMiddlePaused = true
        monster.treasureMiddlePauseTimer = pauseDuration
    end
    if (monster.treasureMiddlePauseTimer or 0) > 0 then
        monster.treasureMiddlePauseTimer = math.max(0, monster.treasureMiddlePauseTimer - dt)
    else
        local controlScale = GetTreasureEscapeSpeedScale(monster)
        monster.treasureTravelProgress = math.min(1,
            monster.treasureTravelProgress + dt * controlScale / travelDuration)
    end

    local progress = monster.treasureTravelProgress
    local direction = monster.treasureEscapeDirection or 1
    local startX = monster.treasureStartX or monster.x
    local centerX = screenW * 0.5
    local exitX = direction > 0
        and screenW + (monster.radius or CONFIG.TreasureRadius or 22) * 1.6
        or -(monster.radius or CONFIG.TreasureRadius or 22) * 1.6
    local pathX = 0
    local pathY = 0
    if progress <= 0.5 then
        local t = progress / 0.5
        pathX = startX + (centerX - startX) * t
        pathY = (monster.treasureStartY or monster.y) + math.sin(t * math.pi) * 34
    else
        local t = (progress - 0.5) / 0.5
        pathX = centerX + (exitX - centerX) * t
        pathY = (monster.treasureStartY or monster.y) + math.sin((1 - t) * math.pi) * 22
    end
    local offsetDecay = math.max(0, 1 - dt * 1.8)
    monster.treasureControlOffsetX = (monster.treasureControlOffsetX or 0) * offsetDecay
    monster.treasureControlOffsetY = (monster.treasureControlOffsetY or 0) * offsetDecay
    monster.x = pathX + monster.treasureControlOffsetX
    monster.y = pathY + monster.treasureControlOffsetY
    local remainingPause = monster.treasureMiddlePaused
        and math.max(0, monster.treasureMiddlePauseTimer or 0)
        or pauseDuration
    monster.treasureEscapeTimer = math.max(0,
        remainingPause + (1 - progress) * travelDuration)

    if progress < 1 then return end
    monster.treasureEscaped = true
    table.remove(monsters, monsterIndex)
    floorKillCount = floorKillCount + 1
    local escapedSkillTreasure = monster.type == "skill_treasure"
    AddEffect({
        type = "gold_drop",
        x = math.max(24, math.min(screenW - 24, monster.x)),
        y = math.max(30, math.min(screenH - 30, monster.y)),
        text = escapedSkillTreasure and "技能宝箱逃走了" or "宝箱逃走了",
        life = 1.2,
        maxLife = 1.2,
    })
    if escapedSkillTreasure then
        print("[SkillTreasure] 技能宝箱逃逸，技能书丢失，层数:", monster.floor or runFloor)
    else
        print("[Treasure] 宝箱逃逸，金币丢失，层数:", monster.floor or runFloor)
    end
    TryCompleteFloorIfCleared()
end

function UpdateMonsters(dt)
    UpdateMonsterProjectiles(dt)
    local rangedAttackDistance = math.max(160, (base.y + CONFIG.MonsterRadius) * 0.5)
    for i = #monsters, 1, -1 do
        local m = monsters[i]
        local dx = base.x - m.x
        local dy = base.y - m.y
        local dist = math.sqrt(dx * dx + dy * dy)
        local monsterType = m.type or "normal"
        local isTreasure = IsAnyTreasureMonster(monsterType)
        local isSkillTreasure = monsterType == "skill_treasure"
        if isTreasure then
            UpdateTreasureDisplayText(m)
        end

        if m.isTrainingDummy then
            m.x = m.anchorX or screenW * 0.5
            m.y = m.anchorY or screenH * 0.46
            m.hp = 1
            m.maxHp = 1
            m.hitStunTimer = 0
            m.freezeTimer = 0
            m.poisonSlowTimer = 0
            m.groundSlamSlowTimer = 0
        elseif m.baseAttackCooldown and m.baseAttackCooldown > 0 then
            m.baseAttackCooldown = math.max(0, m.baseAttackCooldown - dt)
        end
        if m.bossBuff ~= nil and m.bossBuff.id == "shield" then
            m.bossShieldTimer = (m.bossShieldTimer or 0) + dt
        end
        if m.hitStunTimer and m.hitStunTimer > 0 then
            m.hitStunTimer = math.max(0, m.hitStunTimer - dt)
        end
        if m.freezeTimer and m.freezeTimer > 0 then
            m.freezeTimer = m.freezeTimer - dt
        end
        if m.poisonSlowTimer and m.poisonSlowTimer > 0 then
            m.poisonSlowTimer = m.poisonSlowTimer - dt
        end
        if m.groundSlamSlowTimer and m.groundSlamSlowTimer > 0 then
            m.groundSlamSlowTimer = m.groundSlamSlowTimer - dt
        end
        if m.spawnVisualTimer and m.spawnVisualTimer > 0 then
            m.spawnVisualTimer = math.max(0, m.spawnVisualTimer - dt)
        end
        if monsterType == "blood" and not IsBattleMediumVisualLoad() then
            m.bloodTrailTimer = (m.bloodTrailTimer or 0) - dt
            if m.bloodTrailTimer <= 0 then
                m.bloodTrailTimer = 0.48
                AddEffect({ type = "blood_pool", x = m.x, y = m.y + (m.radius or 20) * 0.45, radius = (m.radius or 20) * 0.58, life = 0.7, maxLife = 0.7, trail = true })
            end
        end

        if m.hp <= 0 then
            local dropX, dropY = m.x, m.y
            local dropFloor = math.max(1, math.floor(m.floor or runFloor or 1))
            local wasBoss = m.isBoss
            local splitDepth = m.splitDepth or 0
            local deathColor = isTreasure and {255, 210, 70} or m.color
            SpawnParticles(m.x, m.y, wasBoss and 24 or (isTreasure and 22 or 8), deathColor)
            if wasBoss then
                AddEffect({ type = "boss_death", x = dropX, y = dropY, radius = (m.radius or 36) + 42, color = {205, 92, 255}, life = 0.9, maxLife = 0.9 })
            elseif monsterType == "blood" then
                AddEffect({ type = "blood_pool", x = dropX, y = dropY, radius = (m.radius or 20) + 18, life = 1.1, maxLife = 1.1 })
                AddEffect({ type = "monster_death", x = dropX, y = dropY, radius = (m.radius or 20) + 12, color = {235, 45, 70}, life = 0.46, maxLife = 0.46 })
            elseif not isTreasure and monsterType ~= "splitter" then
                AddEffect({ type = "monster_death", x = dropX, y = dropY, radius = (m.radius or 16) + (monsterType == "elite" and 18 or 10), color = deathColor, life = monsterType == "elite" and 0.56 or 0.38, maxLife = monsterType == "elite" and 0.56 or 0.38 })
            end
            score = score + (wasBoss and 100 or 10)
            killCount = killCount + 1
            if not trainingModeActive and not equipmentRiftActive
                and RecordMonsterDiscovery ~= nil then
                RecordMonsterDiscovery(monsterType)
            end
            if trainingModeActive then
                trainingKillCount = trainingKillCount + 1
            end
            AddAwakeningEnergy(AWAKENING_ENERGY_PER_KILL)
            table.remove(monsters, i)

            if wasBoss then
                if equipmentRiftActive then
                    HandleEquipmentRiftMonsterRewards(m, dropX, dropY, splitDepth)
                elseif not trainingModeActive then
                    TryDropRefineStone(dropX, dropY)
                end
                floorBossDefeatedCount = floorBossDefeatedCount + 1
                bossAlive = CountAliveBosses() > 0
                if not trainingModeActive and not equipmentRiftActive then
                    TryDropEquipment(dropX, dropY, CONFIG.BossEquipmentDropChance, dropFloor, "boss")
                    TryDropSkillScroll(dropX, dropY, "boss", dropFloor)
                end
                TryCompleteFloorIfCleared()
            else
                floorKillCount = floorKillCount + 1
                if isTreasure then
                    if isSkillTreasure then
                        for _ = 1, 5 do
                            local skillId = SKILL_ORDER[math.random(1, #SKILL_ORDER)]
                            AddSkillScroll(skillId, dropFloor)
                        end
                    else
                        local gold = AddRunGoldReward(GetTreasureGoldReward(dropFloor))
                        AddEffect({ type = "gold_drop", x = dropX, y = dropY, text = "金币+" .. tostring(gold), life = 1.45, maxLife = 1.45 })
                        print("[Treasure] 宝箱怪掉落金币:", gold, "层数:", dropFloor)
                    end
                elseif equipmentRiftActive then
                    HandleEquipmentRiftMonsterRewards(m, dropX, dropY, splitDepth)
                    if monsterType == "splitter" then
                        SpawnSplitChildren(m)
                    end
                elseif not trainingModeActive then
                    TryDropRefineStone(dropX, dropY)
                    if monsterType == "elite" then
                        TryDropEquipment(dropX, dropY, CONFIG.EliteDropChance, dropFloor, "elite")
                    elseif monsterType == "splitter" then
                        if splitDepth == 0 then
                            TryDropEquipment(dropX, dropY, CONFIG.SplitterDropChance, dropFloor, "normal")
                        end
                        SpawnSplitChildren(m)
                    elseif monsterType == "blood" then
                        TryDropEquipment(dropX, dropY, CONFIG.BloodDropChance, dropFloor, "blood")
                    else
                        if dropFloor == 1 and not firstFloorBlueDropDone then
                            firstFloorBlueDropDone = true
                            ForceDropBlueEquipment(dropX, dropY, dropFloor)
                        else
                            TryDropEquipment(dropX, dropY, CONFIG.MonsterEquipmentDropChance, dropFloor, "normal")
                        end
                    end
                    TryDropSkillScroll(dropX, dropY, monsterType, dropFloor)
                elseif monsterType == "splitter" then
                    SpawnSplitChildren(m)
                end
                TryCompleteFloorIfCleared()
            end
        else
            if m.isTrainingDummy then
            elseif isTreasure then
                UpdateTreasureEscape(m, dt, i)
            else
            local canMove = dist > 5 and not (m.hitStunTimer and m.hitStunTimer > 0)
            if m.type == "ranged" then
                local canShoot = IsMonsterInsideBattleArea(m)
                    and dist <= rangedAttackDistance
                if canShoot then
                    canMove = false
                    m.shootTimer = math.max(
                        0,
                        (m.shootTimer or CONFIG.RangedAttackCooldown) - dt
                    )
                    if m.shootTimer <= 0 then
                        local shootCooldown = CONFIG.RangedAttackCooldown
                            * (m.attackCooldownMultiplier or 1)
                        m.shootTimer = shootCooldown
                        FireMonsterProjectile(m)
                    end
                end
            elseif m.type == "elite" then
                m.chargeTimer = (m.chargeTimer or 0) - dt
                if (m.chargeDuration or 0) > 0 then
                    m.chargeDuration = m.chargeDuration - dt
                elseif m.chargeTimer <= 0 then
                    m.chargeTimer = CONFIG.EliteChargeCooldown * (m.attackCooldownMultiplier or 1)
                    m.chargeDuration = CONFIG.EliteChargeDuration
                    AddEffect({ type = "elite_charge", x = m.x, y = m.y, radius = m.radius + 12, life = 0.32, maxLife = 0.32 })
                end
            elseif isTreasure and dist < CONFIG.BaseWidth + (m.radius or CONFIG.MonsterRadius) + 18 then
                canMove = false
                local side = (m.x >= base.x) and 1 or -1
                m.x = math.max(m.radius, math.min(screenW - m.radius, m.x + side * m.speed * 0.35 * dt))
            end

            if canMove and dist > 0 then
                local speedScale = (m.freezeTimer and m.freezeTimer > 0) and 0.6 or 1.0
                if m.poisonSlowTimer and m.poisonSlowTimer > 0 then
                    speedScale = speedScale * (m.poisonSlowScale or 0.75)
                end
                if m.groundSlamSlowTimer and m.groundSlamSlowTimer > 0 then
                    speedScale = speedScale * (m.groundSlamSlowScale or 0.55)
                end
                if m.type == "elite" and (m.chargeDuration or 0) > 0 then
                    speedScale = speedScale * CONFIG.EliteChargeSpeedMult
                end
                m.strafePhase = (m.strafePhase or 0) + dt * (m.strafeSpeed or CONFIG.MonsterStrafeSpeedMin or 1.2)
                local strafe = math.sin(m.strafePhase) * (m.strafeStrength or CONFIG.MonsterStrafeStrength or 0)
                if dist < 70 or (m.hitStunTimer and m.hitStunTimer > 0) then
                    strafe = 0
                end
                local dirX = dx / dist
                local dirY = dy / dist
                local moveX = dirX + (-dirY) * strafe
                local moveY = dirY + dirX * strafe
                local moveLen = math.sqrt(moveX * moveX + moveY * moveY)
                if moveLen > 0 then
                    moveX = moveX / moveLen
                    moveY = moveY / moveLen
                end
                m.x = m.x + moveX * m.speed * speedScale * dt
                m.y = m.y + moveY * m.speed * speedScale * dt
                m.x = math.max(-m.radius, math.min(screenW + m.radius, m.x))
            end

            if dist < CONFIG.BaseWidth and not isTreasure then
                MonsterAttackBase(m, dist)
            end
            end
        end
    end
end


heroAttackTargets = {}

function CollectHeroAttackTargets()
    local targets = heroAttackTargets
    local targetCount = 0
    local attackRadiusSq = GetHeroAttackRadius() ^ 2
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local monster = aliveMonsters[index]
        local dx = monster.x - hero.x
        local dy = monster.y - hero.y
        if dx * dx + dy * dy < attackRadiusSq then
            targetCount = targetCount + 1
            targets[targetCount] = monster
        end
    end
    for index = #targets, targetCount + 1, -1 do
        targets[index] = nil
    end
    return targets
end

function PerformHeroAttackRound(targets)
    local hitCount = math.min(GetHeroAttackCount(), #targets)
    for _ = 1, hitCount do
        local treasureIndex = nil
        for index, monster in ipairs(targets) do
            if monster.type == "treasure"
                or monster.type == "skill_treasure" then
                treasureIndex = index
                break
            end
        end
        local targetIndex = treasureIndex
        if targetIndex == nil then
            if playerData.settings ~= nil
                and playerData.settings.autoBattleEnabled == true then
                -- 自动战斗：优先攻击离基地最近的怪
                local nearestIndex = 1
                local nearestDistSq = 0
                for index, monster in ipairs(targets) do
                    local dx = monster.x - base.x
                    local dy = monster.y - base.y
                    local d2 = dx * dx + dy * dy
                    if index == 1 or d2 < nearestDistSq then
                        nearestIndex = index
                        nearestDistSq = d2
                    end
                end
                targetIndex = nearestIndex
            else
                targetIndex = math.random(1, #targets)
            end
        end
        local monster = table.remove(targets, targetIndex)
        local dx = monster.x - hero.x
        local dy = monster.y - hero.y
        local distance = math.sqrt(dx * dx + dy * dy)
        DamageMonster(
            monster,
            RollHeroAttackDamage(monster),
            DAMAGE_STAT_HERO_ID
        )
        if distance > 0 then
            local push = IsAnyTreasureMonster(monster.type)
                and 15 * (CONFIG.TreasureControlStrengthMultiplier or 0.5)
                or 15
            AddMonsterControlDisplacement(
                monster,
                (dx / distance) * push,
                (dy / distance) * push
            )
        end
    end
end

function UpdateAttack(dt)
    if hitSfxTimer > 0 then
        hitSfxTimer = math.max(0, hitSfxTimer - dt)
    end
    hero.attackTimer = hero.attackTimer + dt
    local attackCooldown = GetHeroAttackCooldown()
    if hero.attackTimer >= attackCooldown then
        local targets = CollectHeroAttackTargets()
        if #targets > 0 then
            hero.attackTimer = hero.attackTimer - attackCooldown
            hero.isSwinging = true
            hero.swingAngle = -math.pi * 0.4
            hero.swingDir = 1
            PerformHeroAttackRound(targets)
            local stats = GetBattleEquipmentStats()
            if (stats.doubleAttackChance or 0) > 0 and math.random(1, 100) <= math.min(20, stats.doubleAttackChance) then
                local secondTargets = CollectHeroAttackTargets()
                if #secondTargets > 0 then
                    PerformHeroAttackRound(secondTargets)
                end
            end
            PlayHitSfx()
            SpawnParticles(hero.x, hero.y, 4, {255, 220, 100})
        else
            hero.attackTimer = math.min(hero.attackTimer, attackCooldown)
        end
    end
    local aliveMonsters, aliveCount = GetBattleStepAliveMonsters()
    for index = 1, aliveCount do
        local m = aliveMonsters[index]
        if m.hitFlash > 0 then m.hitFlash = m.hitFlash - dt end
    end
end

local CLONE_RETARGET_INTERVAL = 0.2
local CLONE_TARGET_LOCK_DURATION = 0.8

local function IsValidCloneTarget(target)
    return target ~= nil and (target.hp or 0) > 0
end

local function GetCloneThreatTier(monster)
    if monster == nil then return 3 end
    if monster.isBoss or monster.type == "boss" then return 0 end
    if monster.type == "elite" then return 1 end
    return 2
end

local function FindCloneProtocolTarget(clone, protocolId)
    local best = nil
    local bestPrimary = nil
    local bestSecondary = nil
    local cx = clone and clone.x or base.x
    local cy = clone and clone.y or base.y

    for _, monster in ipairs(monsters) do
        if (monster.hp or 0) > 0 then
            local dx = monster.x - cx
            local dy = monster.y - cy
            local cloneDistSq = dx * dx + dy * dy
            local baseDx = monster.x - base.x
            local baseDy = monster.y - base.y
            local baseDistSq = baseDx * baseDx + baseDy * baseDy
            local primary = cloneDistSq
            local secondary = baseDistSq

            if protocolId == "guard" then
                primary = baseDistSq
                secondary = cloneDistSq
            elseif protocolId == "hunter" then
                primary = GetCloneThreatTier(monster)
                secondary = cloneDistSq
            elseif protocolId == "harvest" then
                primary = (monster.hp or 0) / math.max(1, monster.maxHp or monster.hp or 1)
                secondary = baseDistSq
            elseif protocolId == "clear" then
                primary = GetCloneThreatTier(monster) == 2 and 0
                    or (monster.type == "elite" and 1 or 2)
                secondary = cloneDistSq
            elseif protocolId == "focus" then
                primary = GetCloneThreatTier(monster)
                secondary = -(monster.maxHp or monster.hp or 0)
            end

            if best == nil
                or primary < bestPrimary
                or (primary == bestPrimary and secondary < bestSecondary) then
                best = monster
                bestPrimary = primary
                bestSecondary = secondary
            end
        end
    end
    return best
end

local function ShouldReplaceLockedCloneTarget(current, candidate, protocolId)
    if not IsValidCloneTarget(current) then return true end
    if not IsValidCloneTarget(candidate) or current == candidate then return false end
    if protocolId == "hunter" then
        return GetCloneThreatTier(candidate) < GetCloneThreatTier(current)
    end
    if protocolId == "guard" then
        local heroRange = GetHeroAttackRadius() / (awakeningActive and 2.0 or 1.0)
        local dangerRadiusSq = (heroRange * 1.2) ^ 2
        local function DistanceToBaseSq(monster)
            local dx = monster.x - base.x
            local dy = monster.y - base.y
            return dx * dx + dy * dy
        end
        return DistanceToBaseSq(candidate) <= dangerRadiusSq
            and DistanceToBaseSq(current) > dangerRadiusSq
    end
    return false
end

local function UpdateCloneCachedTarget(clone, dt, protocolId)
    clone.retargetTimer = math.max(0, (clone.retargetTimer or 0) - dt)
    clone.targetLockTimer = math.max(0, (clone.targetLockTimer or 0) - dt)
    if clone.target ~= nil and not IsValidCloneTarget(clone.target) then
        clone.target = nil
        clone.retargetTimer = 0
        clone.targetLockTimer = 0
    end
    if clone.retargetTimer > 0 then
        return IsValidCloneTarget(clone.target) and clone.target or nil
    end

    clone.retargetTimer = CLONE_RETARGET_INTERVAL
    local candidate = FindCloneProtocolTarget(clone, protocolId)
    if not IsValidCloneTarget(clone.target)
        or clone.targetLockTimer <= 0
        or ShouldReplaceLockedCloneTarget(clone.target, candidate, protocolId) then
        if clone.target ~= candidate then
            clone.target = candidate
            clone.targetLockTimer = CLONE_TARGET_LOCK_DURATION
        end
    end
    return clone.target
end

local function IsCloneAttackCandidateBetter(a, b, clone, protocolId)
    if b == nil then return true end
    if protocolId == "hunter" or protocolId == "clear" then
        local aTier = GetCloneThreatTier(a)
        local bTier = GetCloneThreatTier(b)
        if protocolId == "clear" then
            aTier = aTier == 2 and 0 or aTier
            bTier = bTier == 2 and 0 or bTier
        end
        if aTier ~= bTier then return aTier < bTier end
    elseif protocolId == "harvest" then
        local aRatio = (a.hp or 0) / math.max(1, a.maxHp or a.hp or 1)
        local bRatio = (b.hp or 0) / math.max(1, b.maxHp or b.hp or 1)
        if aRatio ~= bRatio then return aRatio < bRatio end
    elseif protocolId == "guard" then
        local adx, ady = a.x - base.x, a.y - base.y
        local bdx, bdy = b.x - base.x, b.y - base.y
        local aBaseDistSq = adx * adx + ady * ady
        local bBaseDistSq = bdx * bdx + bdy * bdy
        if aBaseDistSq ~= bBaseDistSq then return aBaseDistSq < bBaseDistSq end
    end
    local adx, ady = a.x - clone.x, a.y - clone.y
    local bdx, bdy = b.x - clone.x, b.y - clone.y
    return adx * adx + ady * ady < bdx * bdx + bdy * bdy
end

local function CollectCloneAttackTargets(clone, cloneRange, protocolId, maxTargets, focusTarget)
    local candidates = {}
    local rangeSq = cloneRange * cloneRange
    if protocolId == "focus" and IsValidCloneTarget(focusTarget) then
        local focusDx = focusTarget.x - clone.x
        local focusDy = focusTarget.y - clone.y
        if focusDx * focusDx + focusDy * focusDy < rangeSq then
            table.insert(candidates, focusTarget)
        end
    end

    for _, monster in ipairs(monsters) do
        if (monster.hp or 0) > 0 and monster ~= focusTarget then
            local dx = monster.x - clone.x
            local dy = monster.y - clone.y
            if dx * dx + dy * dy < rangeSq then
                local insertAt = #candidates + 1
                if protocolId ~= "focus" then
                    for index = 1, #candidates do
                        if IsCloneAttackCandidateBetter(monster, candidates[index], clone, protocolId) then
                            insertAt = index
                            break
                        end
                    end
                end
                if insertAt <= maxTargets then
                    table.insert(candidates, insertAt, monster)
                    if #candidates > maxTargets then
                        table.remove(candidates)
                    end
                end
            end
        end
    end
    return candidates
end

local function GetCloneProtocolDamageMultiplier(protocolId, target)
    if protocolId == "guard" then
        local heroRange = GetHeroAttackRadius() / (awakeningActive and 2.0 or 1.0)
        local dx = target.x - base.x
        local dy = target.y - base.y
        return dx * dx + dy * dy <= (heroRange * 1.2) ^ 2 and 1.08 or 0.92
    elseif protocolId == "hunter" then
        if target.isBoss or target.type == "boss" then return 1.12 end
        if target.type == "elite" then return 1.08 end
        return 0.88
    elseif protocolId == "harvest" then
        local hpRatio = (target.hp or 0) / math.max(1, target.maxHp or target.hp or 1)
        return hpRatio <= 0.25 and 1.10 or 0.92
    elseif protocolId == "clear" then
        return 0.78
    elseif protocolId == "focus" then
        return 0.96
    end
    return 1.0
end

function UpdateClones(dt)
    if #clones == 0 then return end

    local protocolId = battleCloneProtocolId or "balanced"
    local cloneRadius = CONFIG.HeroRadius * 0.5
    local cloneSpeedMultiplier = protocolId == "guard" and 1.05 or 1.0
    local cloneSpeed = GetHeroMoveSpeed() * 0.9 * cloneSpeedMultiplier
    local baseHeroRange = GetHeroAttackRadius() / (awakeningActive and 2.0 or 1.0)
    local cloneRange = baseHeroRange * 0.8
    local chaseStopRange = cloneRange * 0.7

    if protocolId == "focus" then
        battleCloneFocusScanTimer = math.max(0, (battleCloneFocusScanTimer or 0) - dt)
        if battleCloneFocusScanTimer <= 0 or not IsValidCloneTarget(battleCloneFocusTarget) then
            battleCloneFocusTarget = FindCloneProtocolTarget(nil, "focus")
            battleCloneFocusScanTimer = CLONE_RETARGET_INTERVAL
        end
    else
        battleCloneFocusTarget = nil
    end

    for _, clone in ipairs(clones) do
        local target = protocolId == "focus"
            and battleCloneFocusTarget
            or UpdateCloneCachedTarget(clone, dt, protocolId)
        if target ~= nil then
            local dxToTarget = target.x - clone.x
            local dyToTarget = target.y - clone.y
            local distToTarget = math.sqrt(dxToTarget * dxToTarget + dyToTarget * dyToTarget)
            if distToTarget > chaseStopRange then
                clone.targetX = math.max(cloneRadius, math.min(screenW - cloneRadius, target.x))
                clone.targetY = math.max(cloneRadius, math.min(screenH - cloneRadius - 30, target.y))
            else
                clone.targetX = clone.x
                clone.targetY = clone.y
            end
        else
            local index = clone.index or 1
            local offsetX = (index - 2) * 55
            clone.targetX = math.max(cloneRadius, math.min(screenW - cloneRadius, base.x + offsetX))
            clone.targetY = math.max(cloneRadius, math.min(screenH - cloneRadius - 30, base.y - CONFIG.BaseHeight - 80))
        end

        local dx = clone.targetX - clone.x
        local dy = clone.targetY - clone.y
        local dist = math.sqrt(dx * dx + dy * dy)
        if dist > 3 then
            local speed = math.min(cloneSpeed * dt, dist)
            clone.x = clone.x + (dx / dist) * speed
            clone.y = clone.y + (dy / dist) * speed
        end

        clone.attackTimer = clone.attackTimer + dt
        local cloneAttackCooldown = GetCloneAttackCooldown()
        if clone.attackTimer >= cloneAttackCooldown then
            local inheritedCount = GetCloneInheritedAttackCount(clone.index or 1)
            local maxTargets = inheritedCount
            if protocolId == "clear" then
                maxTargets = math.min(6, inheritedCount + 1)
            end
            local targets = CollectCloneAttackTargets(
                clone,
                cloneRange,
                protocolId,
                maxTargets,
                battleCloneFocusTarget
            )
            if #targets > 0 then
                clone.attackTimer = clone.attackTimer - cloneAttackCooldown
                local stats = GetBattleEquipmentStats()
                local cloneDamageMultiplier = 1 + (stats.cloneDamagePercent or 0) / 100
                local cloneBaseDamage = GetHeroAttackDamage()
                    * GetCloneDamagePercent(clone.index or 1) / 100
                    * cloneDamageMultiplier
                for _, attackTarget in ipairs(targets) do
                    local targetFloor = math.max(
                        1,
                        math.floor(
                            attackTarget.floor
                                or runFloor
                                or playerData.currentFloor
                                or 1
                        )
                    )
                    local cloneCritRate, cloneCritDamage =
                        GetCloneEffectiveCritStats(targetFloor)
                    local cloneDamage = cloneBaseDamage
                        * GetCloneProtocolDamageMultiplier(protocolId, attackTarget)
                    if math.random() * 100 < cloneCritRate then
                        cloneDamage = cloneDamage * (1 + cloneCritDamage / 100)
                    end
                    cloneDamage = math.floor(cloneDamage)
                    DamageMonster(attackTarget, cloneDamage, DAMAGE_STAT_CLONE_ID)
                    attackTarget.hitFlash = 0.1
                end
                SpawnParticles(clone.x, clone.y, 1 + #targets, {150, 200, 255})
            else
                clone.attackTimer = math.min(
                    clone.attackTimer,
                    cloneAttackCooldown
                )
            end
        end
    end
end

function UpdateBase(dt)
    if base.flashTimer > 0 then base.flashTimer = base.flashTimer - dt end
    if base.hp <= 0 then ShowGameOver() end
end

function UpdateParticles(dt)
    for i = #particles, 1, -1 do
        local p = particles[i]
        p.life = p.life - dt
        p.x = p.x + p.vx * dt
        p.y = p.y + p.vy * dt
        p.vy = p.vy + 200 * dt
        if p.life <= 0 then table.remove(particles, i) end
    end
end

function SpawnParticles(x, y, count, color)
    local available = math.max(0, GetCurrentParticleLimit() - #particles)
    local spawnCount = math.min(math.max(0, math.floor(count or 0)), available)
    for i = 1, spawnCount do
        local angle = math.random() * math.pi * 2
        local speed = 80 + math.random() * 120
        table.insert(particles, {
            x = x, y = y,
            vx = math.cos(angle) * speed,
            vy = math.sin(angle) * speed - 80,
            life = 0.4 + math.random() * 0.3, maxLife = 0.7,
            color = color, size = 3 + math.random() * 4,
        })
    end
end

function BeginAutoBattleManualControl(px, py, touchId)
    autoBattleManualInputActive = true
    autoBattleManualOverrideTimer = 0
    autoBattleManualTouchId = touchId
    hero.targetX = px
    hero.targetY = py
    print("[AutoBattle] 玩家临时接管")
end

function EndAutoBattleManualControl()
    if not autoBattleManualInputActive then return end
    autoBattleManualInputActive = false
    autoBattleManualTouchId = nil
    if playerData.settings ~= nil
        and playerData.settings.autoBattleEnabled == true then
        autoBattleManualOverrideTimer = AUTO_BATTLE_REENGAGE_DELAY
        print("[AutoBattle] 玩家松手，1秒后恢复")
    else
        autoBattleManualOverrideTimer = 0
        autoBattleTarget = nil
        autoBattleRetargetTimer = 0
        print("[AutoBattle] 自动战斗关闭，玩家松手后保持手动控制")
    end
end

function HandleMouseMove(eventType, eventData)
    if currentScreen == "playing" and autoBattleManualInputActive
        and autoBattleManualTouchId == nil then
        hero.targetX = eventData["X"]:GetInt() / screenDpr
        hero.targetY = eventData["Y"]:GetInt() / screenDpr
    end
end

function GetGameSpeedOptions()
    local speeds = { 1 }
    if not IsDailySpeedQuotaExhausted() then
        -- 2/3倍速共用广告解锁：tripleSpeedUnlocked 同时代表 2倍速与3倍速已解锁
        if playerData.settings and playerData.settings.tripleSpeedUnlocked then
            table.insert(speeds, 2)
            table.insert(speeds, 3)
        end
        if playerData.settings
            and playerData.settings.fiveSpeedAdUnlockDayKey == GetCurrentCstDayKey()
            and (playerData.bestFloor or 1) > 50 then
            table.insert(speeds, 5)
        end
    end
    return speeds
end

function GetMaxGameSpeed()
    local speeds = GetGameSpeedOptions()
    return speeds[#speeds] or 2
end

function TryToggleDamageRank(px, py)
    local r = damageRankRect
    if r ~= nil and px >= r.x and px <= r.x + r.w and py >= r.y and py <= r.y + r.h then
        damageRankExpanded = not damageRankExpanded
        print("[HUD] 伤害排行" .. (damageRankExpanded and "展开" or "缩小"))
        return true
    end
    return false
end

function TryToggleTenSpeed(px, py)
    local settings = playerData.settings
    local hasReal = settings and settings.tenSpeedUnlocked
    local hasFake = settings and settings.fakeTenSpeedUnlocked
    if not hasReal and not hasFake then return false end
    local r = tenSpeedBtnRect
    if r ~= nil and px >= r.x and px <= r.x + r.w and py >= r.y and py <= r.y + r.h then
        if hasReal then
            if gameSpeed == 10 then
                gameSpeed = 1
            else
                gameSpeed = 10
            end
            if equipmentRiftActive then
                playerData.settings.lastEquipmentRiftGameSpeed = gameSpeed
                SaveCloudData(true)
            elseif not trainingModeActive then
                playerData.settings.lastGameSpeed = gameSpeed
                SaveCloudData(true)
            end
            print("[速度] 切换为 x" .. gameSpeed)
        else
            fakeTenBtnFlashUntil = os.clock() + 0.15
            print("[速度] 切换为 x10")
        end
        return true
    end
    return false
end

function ShowSpeedQuotaAdModal()
    if speedQuotaModalOpen or rewardAdInFlight then return end
    NormalizeDailySpeedQuota()
    if NormalizeDailyRewardAdQuota ~= nil then
        NormalizeDailyRewardAdQuota()
    end
    local claimCount = GetDailySpeedAdClaimCount()
    local dailyAdRemaining = GetDailyRewardAdRemaining and GetDailyRewardAdRemaining() or 0
    if claimCount >= DAILY_SPEED_AD_MAX_CLAIMS then
        speedQuotaNoticeText = "今日倍速额度已全部用完，明日恢复"
        speedQuotaNoticeUntil = os.clock() + 5
        return
    end
    if dailyAdRemaining <= 0 then
        speedQuotaNoticeText = "今日广告次数已用完（"
            .. tostring(DAILY_REWARD_AD_MAX_CLAIMS or 20) .. "/"
            .. tostring(DAILY_REWARD_AD_MAX_CLAIMS or 20) .. "），明天再来"
        speedQuotaNoticeUntil = os.clock() + 5
        return
    end
    if not IsDailySpeedQuotaExhausted() then return end

    speedQuotaModalOpen = true
    rewardAdBattlePaused = true
    local modal
    modal = UI.Modal {
        title = "倍速额度已用完",
        size = "sm",
        isOpen = false,
        closeOnOverlay = false,
        closeOnEscape = false,
        showCloseButton = false,
        contentPadding = 12,
        contentGap = 8,
        backgroundColor = { 20, 17, 35, 255 },
        borderWidth = 2,
        borderColor = PX.gold,
        children = {
            UI.Label {
                text = "完整观看广告可增加今日2小时倍速额度",
                fontSize = 13,
                fontColor = PX.textWhite,
                textAlign = "center",
                whiteSpace = "normal",
            },
            UI.Label {
                text = "今日额度广告 " .. tostring(claimCount) .. "/" .. tostring(DAILY_SPEED_AD_MAX_CLAIMS)
                    .. "  ·  "
                    .. (FormatDailyRewardAdProgressText and FormatDailyRewardAdProgressText() or ""),
                fontSize = 11,
                fontColor = PX.textGold,
                textAlign = "center",
                whiteSpace = "normal",
            },
        },
        onClose = function(self)
            speedQuotaModalOpen = false
            if not rewardAdInFlight then rewardAdBattlePaused = false end
            self:Destroy()
        end,
    }
    modal:SetFooter(UI.Panel {
        width = "100%",
        flexDirection = "row",
        justifyContent = "center",
        gap = 8,
        children = {
            UI.Button {
                text = "暂不观看",
                variant = "secondary",
                onClick = function()
                    modal:Close()
                end,
            },
            UI.Button {
                text = "看广告 +2小时",
                variant = "primary",
                onClick = function()
                    if rewardAdInFlight then return end
                    ShowRewardAd(function(success, msg)
                        if success and GrantDailySpeedAdBonus() then
                            CommitDailySpeedUsage()
                            SaveCloudData(true)
                            speedQuotaNoticeText = "已增加今日2小时倍速额度"
                            speedQuotaNoticeUntil = os.clock() + 5
                            print("[RewardAd] 倍速额度奖励已发放")
                        else
                            speedQuotaNoticeText = GetRewardAdFailureMessage(msg)
                            speedQuotaNoticeUntil = os.clock() + 5
                            print("[RewardAd] 倍速额度奖励未发放:", tostring(msg))
                        end
                        rewardAdBattlePaused = false
                        if speedQuotaModalOpen then modal:Close() end
                    end)
                end,
            },
        },
    })
    modal:Open()
end

-- 2/3倍速未解锁时，战斗右上角点倍速弹出的提醒：引导玩家去设置页看广告解锁
