function TryToggleSpeed(px, py)
    local r = speedBtnRect
    if px >= r.x and px <= r.x + r.w and py >= r.y and py <= r.y + r.h then
        if IsDailySpeedQuotaExhausted() then
            ShowSpeedQuotaAdModal()
            return true
        end
        -- 2/3倍速未解锁：弹窗提醒去设置页看广告解锁
        if not (playerData.settings and playerData.settings.tripleSpeedUnlocked) then
            ShowSpeedUnlockGuideModal()
            return true
        end
        local speeds = GetGameSpeedOptions()
        local nextIndex = 1
        for index, speed in ipairs(speeds) do
            if gameSpeed == speed then
                nextIndex = index + 1
                break
            end
        end
        if nextIndex > #speeds then nextIndex = 1 end
        gameSpeed = speeds[nextIndex] or 1
        if equipmentRiftActive then
            playerData.settings.lastEquipmentRiftGameSpeed = gameSpeed
            SaveCloudData(true)
        elseif not trainingModeActive then
            playerData.settings.lastGameSpeed = gameSpeed
            SaveCloudData(true)
        end
        print("[速度] 切换为 x" .. gameSpeed)
        return true
    end
    return false
end

function TryEndlessPause(px, py)
    if not endlessTrialActive then return false end
    local r = endlessPauseBtnRect
    if r ~= nil and px >= r.x and px <= r.x + r.w and py >= r.y and py <= r.y + r.h then
        print("[Endless] 玩家点击暂停按钮，弹出暂存/退出菜单")
        ShowEndlessExitNotice()
        return true
    end
    return false
end

function TryFinishTrainingDummy(px, py)
    if not IsTrainingDummyMode() then return false end
    local r = trainingEndButtonRect
    if r ~= nil and px >= r.x and px <= r.x + r.w and py >= r.y and py <= r.y + r.h then
        print("[Training] 玩家手动结束木桩测试")
        FinishTraining(true)
        return true
    end
    return false
end

function HandleTrainingResultClick(px, py)
    for index, rect in ipairs(trainingResultButtonRects or {}) do
        if px >= rect.x and px <= rect.x + rect.w
            and py >= rect.y and py <= rect.y + rect.h then
            if index == 1 then
                StartGame({
                    training = true,
                    trainingMode = trainingResult and trainingResult.mode or trainingModeKind,
                    trainingDummyTarget = trainingResult and trainingResult.dummyTargetKind or trainingDummyTargetKind,
                    trainingFloor = trainingResult and trainingResult.floor or trainingFloor,
                })
            elseif index == 2 then
                trainingSelectedMode = trainingResult and trainingResult.mode or trainingModeKind
                trainingSelectedDummyTarget = trainingResult and trainingResult.dummyTargetKind or trainingDummyTargetKind
                trainingSelectedFloor = trainingResult and trainingResult.floor or trainingFloor
                ShowTrainingGroundPage()
            else
                GameEvents.Emit("scene:main")
            end
            return true
        end
    end
    return false
end

function HandleMouseDown(eventType, eventData)
    local button = eventData["Button"]:GetInt()
    if button ~= MOUSEB_LEFT then return end
    if currentScreen == "gameover" then GameEvents.Emit("scene:main"); return end
    if currentScreen == "auto_continue" then
        HandleAutoContinueClick(
            eventData["X"]:GetInt() / screenDpr,
            eventData["Y"]:GetInt() / screenDpr
        )
        return
    end
    if currentScreen == "training_result" then
        HandleTrainingResultClick(eventData["X"]:GetInt() / screenDpr, eventData["Y"]:GetInt() / screenDpr)
        return
    end
    if currentScreen == "rift_decision" then
        HandleEquipmentRiftDecisionClick(eventData["X"]:GetInt() / screenDpr, eventData["Y"]:GetInt() / screenDpr)
        return
    end
    if currentScreen == "rift_exit_confirm" then
        HandleEquipmentRiftExitConfirmClick(eventData["X"]:GetInt() / screenDpr, eventData["Y"]:GetInt() / screenDpr)
        return
    end
    if currentScreen == "rift_result" then
        HandleEquipmentRiftResultClick(eventData["X"]:GetInt() / screenDpr, eventData["Y"]:GetInt() / screenDpr)
        return
    end
    if currentScreen == "playing" then
        local px = eventData["X"]:GetInt() / screenDpr
        local py = eventData["Y"]:GetInt() / screenDpr
        if TryEquipmentRiftExitButton(px, py) then return end
        if TryEndlessPause(px, py) then return end
        if TryFinishTrainingDummy(px, py) then return end
        if TryToggleDamageRank(px, py) then return end
        if TryToggleTenSpeed(px, py) then return end
        if TryToggleSpeed(px, py) then return end
        BeginAutoBattleManualControl(px, py, nil)
    end
end

function HandleMouseUp(eventType, eventData)
    if eventData["Button"]:GetInt() ~= MOUSEB_LEFT then return end
    if currentScreen == "playing" and autoBattleManualTouchId == nil then
        EndAutoBattleManualControl()
    end
end

function HandleTouchBegin(eventType, eventData)
    if currentScreen == "gameover" then GameEvents.Emit("scene:main"); return end
    if currentScreen == "auto_continue" then
        HandleAutoContinueClick(
            eventData["X"]:GetInt() / screenDpr,
            eventData["Y"]:GetInt() / screenDpr
        )
        return
    end
    if currentScreen == "training_result" then
        HandleTrainingResultClick(eventData["X"]:GetInt() / screenDpr, eventData["Y"]:GetInt() / screenDpr)
        return
    end
    if currentScreen == "rift_decision" then
        HandleEquipmentRiftDecisionClick(eventData["X"]:GetInt() / screenDpr, eventData["Y"]:GetInt() / screenDpr)
        return
    end
    if currentScreen == "rift_exit_confirm" then
        HandleEquipmentRiftExitConfirmClick(eventData["X"]:GetInt() / screenDpr, eventData["Y"]:GetInt() / screenDpr)
        return
    end
    if currentScreen == "rift_result" then
        HandleEquipmentRiftResultClick(eventData["X"]:GetInt() / screenDpr, eventData["Y"]:GetInt() / screenDpr)
        return
    end
    if currentScreen == "playing" then
        local px = eventData["X"]:GetInt() / screenDpr
        local py = eventData["Y"]:GetInt() / screenDpr
        if TryEquipmentRiftExitButton(px, py) then return end
        if TryEndlessPause(px, py) then return end
        if TryFinishTrainingDummy(px, py) then return end
        if TryToggleDamageRank(px, py) then return end
        if TryToggleTenSpeed(px, py) then return end
        if TryToggleSpeed(px, py) then return end
        BeginAutoBattleManualControl(px, py, eventData["TouchID"]:GetInt())
    end
end

function HandleTouchMove(eventType, eventData)
    if currentScreen == "playing" and autoBattleManualInputActive then
        local touchId = eventData["TouchID"]:GetInt()
        if autoBattleManualTouchId == touchId then
            hero.targetX = eventData["X"]:GetInt() / screenDpr
            hero.targetY = eventData["Y"]:GetInt() / screenDpr
        end
    end
end

function HandleTouchEnd(eventType, eventData)
    if currentScreen == "playing" and autoBattleManualInputActive
        and autoBattleManualTouchId == eventData["TouchID"]:GetInt() then
        EndAutoBattleManualControl()
    end
end



AUTO_CONTINUE_COUNTDOWN_SECONDS = 6

autoContinueActive = false
autoContinueRemaining = 0
autoContinueBattleFloorCount = 1
autoContinueGameSpeed = 1
autoContinueNextFloor = 1
autoContinueClearedStartFloor = 1
autoContinueClearedEndFloor = 1
autoContinueButtonRects = {}

function ResetAutoContinueState()
    autoContinueActive = false
    autoContinueRemaining = 0
    autoContinueBattleFloorCount = 1
    autoContinueGameSpeed = 1
    autoContinueNextFloor = math.max(1, math.floor(playerData.currentFloor or 1))
    autoContinueClearedStartFloor = autoContinueNextFloor
    autoContinueClearedEndFloor = autoContinueNextFloor
    autoContinueButtonRects = {}
end

local function NormalizeAutoContinueBattleFloorCount(count)
    count = math.max(1, math.floor(count or 1))
    if count >= 20 then return 20 end
    if count >= 10 then return 10 end
    if count >= 5 then return 5 end
    return 1
end

local function NormalizeAutoContinueGameSpeed(speed)
    speed = tonumber(speed) or 1
    if speed == 10 then
        if playerData.settings and playerData.settings.tenSpeedUnlocked then
            return 10
        end
        return 1
    end
    if IsDailySpeedQuotaExhausted() then return 1 end
    return math.max(1, math.min(GetMaxGameSpeed(), speed))
end

function BeginAutoContinueCountdown(settlement)
    settlement = type(settlement) == "table" and settlement or {}
    autoContinueActive = true
    autoContinueRemaining = AUTO_CONTINUE_COUNTDOWN_SECONDS
    autoContinueBattleFloorCount = NormalizeAutoContinueBattleFloorCount(
        settlement.battleFloorCount or (settlement.fiveBattle and 5 or 1)
    )
    autoContinueGameSpeed = NormalizeAutoContinueGameSpeed(
        settlement.gameSpeed or gameSpeed or 1
    )
    autoContinueNextFloor = math.max(
        1,
        math.floor(settlement.nextFloor or playerData.currentFloor or 1)
    )
    autoContinueClearedStartFloor = math.max(
        1,
        math.floor(settlement.clearedStartFloor or autoContinueNextFloor - autoContinueBattleFloorCount)
    )
    autoContinueClearedEndFloor = math.max(
        autoContinueClearedStartFloor,
        math.floor(settlement.clearedEndFloor or autoContinueNextFloor - 1)
    )
    autoContinueButtonRects = {}
    pendingFloorSettlement = nil
    fiveBattleActive = false
    fiveBattleFloorCount = 1
    fiveBattleSpeedMul = 1.0
    currentScreen = "auto_continue"
    UI.SetRoot(UI.Panel { width = 0, height = 0 }, true)
    simulationAccumulator = 0
    SaveCloudData(true)
    print(
        "[AutoContinue] 开始10秒倒计时, 下一层:",
        autoContinueNextFloor,
        "连打档位:",
        autoContinueBattleFloorCount,
        "倍速:",
        autoContinueGameSpeed
    )
    return true
end

function StartAutoContinueNextBattle(reason)
    if not autoContinueActive or currentScreen ~= "auto_continue" then return false end
    local battleFloorCount = autoContinueBattleFloorCount
    local inheritedGameSpeed = NormalizeAutoContinueGameSpeed(autoContinueGameSpeed)
    local nextFloor = autoContinueNextFloor
    autoContinueActive = false
    autoContinueRemaining = 0
    autoContinueButtonRects = {}
    pendingFloorSettlement = nil
    playerData.currentFloor = math.max(1, nextFloor)
    print(
        "[AutoContinue] 启动下一轮, 原因:",
        reason or "countdown",
        "层数:",
        playerData.currentFloor,
        "连打:",
        battleFloorCount,
        "倍速:",
        inheritedGameSpeed
    )
    StartGame({
        battleFloorCount = battleFloorCount,
        inheritedGameSpeed = inheritedGameSpeed,
        autoContinue = true,
    })
    return true
end

function StopAutoContinueAndReturnToMenu()
    if currentScreen ~= "auto_continue" then return false end
    local nextFloor = autoContinueNextFloor
    ResetAutoContinueState()
    pendingFloorSettlement = nil
    fiveBattleActive = false
    fiveBattleRequested = false
    fiveBattleRequestedFloorCount = 1
    fiveBattleFloorCount = 1
    fiveBattleSpeedMul = 1.0
    currentScreen = "menu"
    SaveCloudData(true)
    print("[AutoContinue] 玩家停止续关, 保留下一层:", nextFloor)
    GameEvents.Emit("scene:main")
    return true
end

function UpdateAutoContinueCountdown(dt)
    if not autoContinueActive or currentScreen ~= "auto_continue" then return false end
    autoContinueRemaining = math.max(0, autoContinueRemaining - math.max(0, dt or 0))
    if autoContinueRemaining <= 0 then
        StartAutoContinueNextBattle("countdown")
        return true
    end
    return false
end

function HandleAutoContinueClick(px, py)
    for index, rect in ipairs(autoContinueButtonRects or {}) do
        if px >= rect.x and px <= rect.x + rect.w
            and py >= rect.y and py <= rect.y + rect.h then
            if index == 1 then
                StartAutoContinueNextBattle("manual")
            else
                StopAutoContinueAndReturnToMenu()
            end
            return true
        end
    end
    return false
end

local function DrawAutoContinueButton(vg, rect, label, primary)
    nvgBeginPath(vg)
    nvgRect(vg, rect.x, rect.y, rect.w, rect.h)
    nvgFillColor(vg, primary
        and nvgRGBA(142, 38, 54, 248)
        or nvgRGBA(52, 36, 72, 248))
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(225, 178, 74, 235))
    nvgStrokeWidth(vg, 1)
    nvgStroke(vg)
    nvgFontFace(vg, "pixel")
    nvgFontSize(vg, 11)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
    nvgText(vg, rect.x + rect.w * 0.5, rect.y + rect.h * 0.5, label, nil)
end

function DrawAutoContinuePanel(vg)
    nvgBeginPath(vg)
    nvgRect(vg, 0, 0, screenW, screenH)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 190))
    nvgFill(vg)

    local panelW = math.min(410, screenW - 36)
    local panelH = math.min(300, screenH - 34)
    local panelX = (screenW - panelW) * 0.5
    local panelY = (screenH - panelH) * 0.5
    nvgBeginPath(vg)
    nvgRect(vg, panelX, panelY, panelW, panelH)
    local fill = nvgLinearGradient(
        vg,
        panelX,
        panelY,
        panelX,
        panelY + panelH,
        nvgRGBA(34, 22, 52, 252),
        nvgRGBA(12, 12, 24, 252)
    )
    nvgFillPaint(vg, fill)
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(235, 185, 76, 245))
    nvgStrokeWidth(vg, 2)
    nvgStroke(vg)

    nvgFontFace(vg, "pixel")
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 24)
    nvgFillColor(vg, nvgRGBA(255, 220, 100, 255))
    nvgText(vg, screenW * 0.5, panelY + 38, "战斗胜利", nil)

    nvgFontSize(vg, 10)
    nvgFillColor(vg, nvgRGBA(182, 182, 208, 245))
    local clearedText = autoContinueClearedStartFloor == autoContinueClearedEndFloor
        and ("第" .. tostring(autoContinueClearedStartFloor) .. "层已完成")
        or ("第" .. tostring(autoContinueClearedStartFloor) .. "-"
            .. tostring(autoContinueClearedEndFloor) .. "层已完成")
    nvgText(vg, screenW * 0.5, panelY + 68, clearedText, nil)

    local seconds = math.max(0, math.ceil(autoContinueRemaining or 0))
    nvgFontSize(vg, 42)
    nvgFillColor(vg, nvgRGBA(255, 105, 92, 255))
    nvgText(vg, screenW * 0.5, panelY + 119, tostring(seconds), nil)
    nvgFontSize(vg, 11)
    nvgFillColor(vg, nvgRGBA(225, 225, 238, 245))
    nvgText(vg, screenW * 0.5, panelY + 151, "秒后自动开始下一轮", nil)

