        "下一层 " .. tostring(autoContinueNextFloor)
            .. "｜" .. modeText
            .. "｜倍速 x" .. tostring(autoContinueGameSpeed), nil)
    nvgFontSize(vg, 9)
    nvgFillColor(vg, nvgRGBA(160, 160, 190, 240))
    nvgText(vg, screenW * 0.5, panelY + 202,
        "生命、肉鸽效果、职业和技能联携延续", nil)

    local gap = 10
    local buttonW = (panelW - 46 - gap) * 0.5
    local buttonY = panelY + panelH - 48
    autoContinueButtonRects = {
        { x = panelX + 18, y = buttonY, w = buttonW, h = 32 },
        { x = panelX + 18 + buttonW + gap, y = buttonY, w = buttonW, h = 32 },
    }
    DrawAutoContinueButton(vg, autoContinueButtonRects[1], "立即开始", true)
    DrawAutoContinueButton(vg, autoContinueButtonRects[2], "停止续关", false)
end


