function GetEquipmentRiftPressureMultipliers(pressure)
    pressure = math.max(
        EQUIPMENT_RIFT_PRESSURE_MIN,
        math.floor(tonumber(pressure) or 0)
    )
    local baseHpMultiplier = EQUIPMENT_RIFT_PRESSURE_HP_PER_LEVEL ^ pressure
    local baseDamageMultiplier = EQUIPMENT_RIFT_PRESSURE_DAMAGE_PER_LEVEL ^ pressure
    local extraPressureLevels = math.max(
        0,
        pressure - EQUIPMENT_RIFT_EXTRA_PRESSURE_START + 1
    )
    local extraHpMultiplier = 1 + extraPressureLevels * EQUIPMENT_RIFT_EXTRA_HP_PER_LEVEL
    local extraDamageMultiplier = 1 + extraPressureLevels * EQUIPMENT_RIFT_EXTRA_DAMAGE_PER_LEVEL
    -- 压力 10 以上额外强化：压力 11 起，每层再按线性额外倍率叠加
    local highPressureLevels = math.max(
        0,
        pressure - EQUIPMENT_RIFT_HIGH_PRESSURE_START + 1
    )
    local highHpMultiplier = 1 + highPressureLevels * EQUIPMENT_RIFT_HIGH_HP_PER_LEVEL
    local highDamageMultiplier = 1 + highPressureLevels * EQUIPMENT_RIFT_HIGH_DAMAGE_PER_LEVEL
    return baseHpMultiplier * extraHpMultiplier * highHpMultiplier,
        baseDamageMultiplier * extraDamageMultiplier * highDamageMultiplier
end

function IsEquipmentRiftUnlocked()
    return GetHighestClearedFloor() >= 100
end

function GetEquipmentRiftDifficultyModifiers(difficulty)
    difficulty = math.max(1, math.min(5, math.floor(difficulty or equipmentRiftDifficulty or 1)))
    return EQUIPMENT_RIFT_DIFFICULTY_MODIFIERS[difficulty]
        or EQUIPMENT_RIFT_DIFFICULTY_MODIFIERS[1]
end

-- 装备秘境的战斗/掉落基准层：
-- 取「普通模式历史最高通关（封顶600）」与「无尽模式历史最高层」的较大者。
-- 普通通关600进入无尽后，秘境基准会随无尽层数持续成长，不再锁死在600。
function GetEquipmentRiftReferenceFloor()
    local normalFloor = math.max(1, math.floor(GetHighestClearedFloor() or 1))
    local endlessFloor = math.max(0, math.floor(tonumber(playerData.endlessBestFloor) or 0))
    return math.max(normalFloor, endlessFloor)
end

function GetEquipmentRiftGearFloor()
    if equipmentRiftActive then
        return math.max(1, math.floor(equipmentRiftGearFloor or 1))
    end
    return math.max(1, GetEquipmentRiftReferenceFloor() - 20)
end

function RollEquipmentRiftMutation()
    local mutations = EQUIPMENT_RIFT_MUTATIONS or {}
    if #mutations <= 0 then return nil end
    local mutation = mutations[math.random(1, #mutations)]
    table.insert(equipmentRiftMutations, mutation)
    print("[EquipmentRift] 难度", equipmentRiftDifficulty,
        "新增异变:", mutation.name,
        mutation.description,
        "累计:", #equipmentRiftMutations)
    return mutation
end

local function DoesEquipmentRiftMutationAffectMonster(mutation, monster)
    if mutation == nil or monster == nil then
        return false
    end
    if mutation.bossOnly then return monster.isBoss == true end
    if mutation.monsterTypes ~= nil then
        return mutation.monsterTypes[monster.type or "normal"] == true
    end
    return true
end

function GetEquipmentRiftMutationSummary()
    local counts = {}
    local orderedIds = {}
    for _, mutation in ipairs(equipmentRiftMutations or {}) do
        local id = mutation.id or mutation.name
        if counts[id] == nil then
            counts[id] = { name = mutation.name or "未知异变", count = 0 }
            table.insert(orderedIds, id)
        end
        counts[id].count = counts[id].count + 1
    end
    local names = {}
    for _, id in ipairs(orderedIds) do
        local entry = counts[id]
        local suffix = entry.count > 1 and ("×" .. tostring(entry.count)) or ""
        table.insert(names, entry.name .. suffix)
    end
    return #(equipmentRiftMutations or {}), table.concat(names, " · ")
end

function GetEquipmentRiftPreferredSetDef()
    return EQUIPMENT_RESONANCE_DEFS[equipmentRiftPreferredSetId]
        or EQUIPMENT_RESONANCE_DEFS[EQUIPMENT_RESONANCE_ORDER[1]]
end

function SelectEquipmentRiftPreferredSet(setId)
    if EQUIPMENT_RESONANCE_DEFS[setId] == nil then return false end
    equipmentRiftPreferredSetId = setId
    ShowEquipmentRiftSetupPage()
    return true
end

