        math.floor(tonumber(playerData.normalHighestClearedFloor) or 0),
        math.floor(tonumber(playerData.bestFloor) or 0) - 1
    )
    local endlessUnlocked = normalCleared >= (CONFIG.NormalFloorCap or 600)
    local endlessPending = HasPendingEndlessRun()
    local endlessPendingFloor = endlessPending
        and math.max(
            CONFIG.EndlessStartFloor or 600,
            math.floor(tonumber(playerData.endlessRunState and playerData.endlessRunState.currentFloor) or (CONFIG.EndlessStartFloor or 600))
        )
        or nil
    local content = {
        UI.Label {
            text = message or "选择试炼内容",
            fontSize = 11,
            fontColor = message and PX.redBright or PX.textGray,
            fontWeight = "bold",
            textAlign = "center",
        },
        MakeTrialModeCard(
            "伤害测试",
            trialUnlocked and "怪潮与木桩输出测试" or "通关第10层后解锁",
            "无奖励，不影响正式进度，可查看总伤害与 DPS",
            trialUnlocked,
            function()
                if trialUnlocked then
                    ShowTrainingGroundPage()
                else
                    ShowTrialSelectionPage("通关第10层后开放伤害测试")
                end
            end
        ),
        MakeTrialModeCard(
            "装备秘境",
            riftUnlocked and "五档连续挑战 · 装备专属产出" or "通关第100层后解锁",
            "难度3、4可安全撤离；主动退出或基地沦陷会损失临时装备与宝石、50%金币及2至3张最高星技能",
            riftUnlocked,
            function()
                if riftUnlocked then
                    ShowEquipmentRiftSetupPage()
                else
                    ShowTrialSelectionPage("通关第100层后开放装备秘境")
                end
            end
        ),
        MakeTrialModeCard(
            "无尽试炼",
            endlessPending
                and ("有暂存进度，可从第" .. tostring(endlessPendingFloor or 600) .. "层继续")
                or (endlessUnlocked and "从第600层起，永不停歇的怪潮" or "通关普通第600层后解锁"),
            endlessPending
                and "暂存后可从本层继续，不会按死亡结算。"
                or "可暂存返回主菜单。怪物投放保持第600层配置，实际属性会随无尽层数持续成长。",
            endlessUnlocked,
            function()
                if endlessUnlocked then
                    if HasPendingEndlessRun() then
                        local pendingFloor = math.max(
                            CONFIG.EndlessStartFloor or 600,
                            math.floor(tonumber(playerData.endlessRunState and playerData.endlessRunState.currentFloor) or (CONFIG.EndlessStartFloor or 600))
                        )
                        print("[Endless] 检测到暂存的无尽进度，从第", pendingFloor, "层继续")
                        GameEvents.Emit("battle:start", {
                            endlessTrial = true,
                            endlessContinue = true,
                        })
                    else
                        print("[Endless] 从试炼页请求启动无尽试炼")
                        GameEvents.Emit("battle:start", { endlessTrial = true })
                    end
                else
                    print("[Endless] 无尽试炼尚未解锁")
                    ShowTrialSelectionPage("通关普通第600层后开放无尽试炼")
                end
            end
        ),
    }
    UI.SetRoot(BuildSubPage("试炼", content), true)
    print("[Trial] 试炼选择页, 伤害测试:", trialUnlocked, "装备秘境:", riftUnlocked,
        "无尽试炼:", endlessUnlocked)
end

