function PrepareEquipmentRiftRun(data)
    if not IsEquipmentRiftUnlocked() then
        equipmentRiftActive = false
        ShowEquipmentRiftSetupPage("通关第100层后开放装备秘境")
        return false
    end
    local preferredSetId = data and data.preferredSetId or equipmentRiftPreferredSetId
    if EQUIPMENT_RESONANCE_DEFS[preferredSetId] == nil then
        preferredSetId = EQUIPMENT_RESONANCE_ORDER[1]
    end
    equipmentRiftPreferredSetId = preferredSetId
    equipmentRiftActive = true
    equipmentRiftDifficulty = 1
    equipmentRiftMutations = {}
    equipmentRiftLockedPressure = GetEquipmentRiftPressure()
    equipmentRiftSourceFloor = math.max(1, GetEquipmentRiftReferenceFloor())
    equipmentRiftGearFloor = math.max(1, equipmentRiftSourceFloor - 20)
    equipmentRiftTemporaryEquipment = {}
    equipmentRiftTemporaryGems = {}
    equipmentRiftAncientReward = nil
    equipmentRiftDecision = nil
    equipmentRiftResult = nil
    equipmentRiftFormalState = {
        currentFloor = playerData.currentFloor,
        nextBaseHpRatio = playerData.nextBaseHpRatio,
    }
    print("[EquipmentRift] 准备进入, 战斗层:", equipmentRiftSourceFloor,
        "装备层:", equipmentRiftGearFloor, "优先套装:", equipmentRiftPreferredSetId,
        "锁定压力:", equipmentRiftLockedPressure)
    return true
end

function RestoreFormalStateAfterEquipmentRift()
    local state = equipmentRiftFormalState or {}
    playerData.currentFloor = math.max(1, math.floor(state.currentFloor or playerData.currentFloor or 1))
    playerData.nextBaseHpRatio = state.nextBaseHpRatio
    runFloor = playerData.currentFloor
    equipmentRiftFormalState = nil
end

function RollEquipmentRiftResonanceSetId()
    local preferred = equipmentRiftPreferredSetId
    local order = EQUIPMENT_RESONANCE_ORDER or {}
    if EQUIPMENT_RESONANCE_DEFS[preferred] == nil or #order <= 0 then
        return RollEquipmentResonanceSetId()
    end
    if math.random() < EQUIPMENT_RIFT_PREFERRED_SET_CHANCE then
        return preferred
    end
    local others = {}
    for _, setId in ipairs(order) do
        if setId ~= preferred then table.insert(others, setId) end
    end
    if #others <= 0 then return preferred end
    return others[math.random(1, #others)]
end

function GenerateEquipmentRiftEquipment(slot, quality, ancientOverride)
    local item = GenerateEquipment(
        slot,
        quality,
        GetEquipmentRiftGearFloor(),
        ancientOverride,
        false
    )
    item.resonanceSetId = RollEquipmentRiftResonanceSetId()
    item.riftDrop = true
    return item
end

function AddEquipmentRiftTemporaryItem(item)
    if not equipmentRiftActive or item == nil then return false end
    table.insert(equipmentRiftTemporaryEquipment, item)
    print("[EquipmentRift] 临时装备:", GetEquipmentDisplayName(item),
        "品质:", item.quality, "装等:", item.floor,
        "当前数量:", #equipmentRiftTemporaryEquipment)
    return true
end

function GetEquipmentRiftTemporaryGemCount()
    local count = 0
    for _, gemCount in pairs(equipmentRiftTemporaryGems or {}) do
        count = count + math.max(0, math.floor(gemCount or 0))
    end
    return count
end

function GetEquipmentRiftGemSummary(stack)
    local parts = {}
    for _, gemType in ipairs(GEM_ORDER or {}) do
        local count = math.max(0, math.floor((stack or {})[gemType] or 0))
        if count > 0 then
            local def = GetGemDef(gemType)
            table.insert(parts, (def and def.name or gemType) .. "x" .. tostring(count))
        end
    end
    return #parts > 0 and table.concat(parts, "、") or "无"
end

function AddEquipmentRiftTemporaryGem(gemType, amount)
    if not equipmentRiftActive or GetGemDef(gemType) == nil then return false end
    amount = math.max(1, math.floor(tonumber(amount) or 1))
    equipmentRiftTemporaryGems[gemType] = math.max(
        0,
        math.floor(equipmentRiftTemporaryGems[gemType] or 0)
    ) + amount
    print("[EquipmentRiftGem] 临时获得:", GetGemDisplayName(gemType, 1),
        "数量:", amount, "本局总数:", GetEquipmentRiftTemporaryGemCount())
    return true
end

function CanRollEquipmentRiftGem(monster)
    if not equipmentRiftActive or trainingModeActive or monster == nil then return false end
    if monster.isTrainingDummy == true or monster.isTrainingTarget == true then return false end
    if monster.isSummon == true or monster.isOriginalSpawn == false then return false end
    if monster.isSplitChild == true or (monster.splitDepth or 0) > 0 then return false end
    if monster.riftGemRollResolved == true then return false end
    return true
end

function TryDropEquipmentRiftGem(monster, x, y)
    if not CanRollEquipmentRiftGem(monster) then return false end
    monster.riftGemRollResolved = true
    local category = monster.isBoss == true and "boss"
        or (monster.type == "elite" and "elite" or "normal")
    local baseChance = EQUIPMENT_RIFT_GEM_BASE_CHANCES[category] or 0
    local difficultyMultiplier = EQUIPMENT_RIFT_GEM_DROP_MULTIPLIERS[equipmentRiftDifficulty] or 1.0
    local finalChance = math.min(1.0, baseChance * difficultyMultiplier)
    print("[EquipmentRiftGem] 判定:", category, "难度:", equipmentRiftDifficulty,
        "概率:", finalChance)
    if math.random() >= finalChance then return false end
    local gemType = GEM_ORDER[math.random(1, #GEM_ORDER)]
    local amountConfig = EQUIPMENT_RIFT_GEM_DROP_AMOUNTS[category]
        or EQUIPMENT_RIFT_GEM_DROP_AMOUNTS.normal
    local amount = math.random(amountConfig.min, amountConfig.max)
    AddEquipmentRiftTemporaryGem(gemType, amount)
    AddEffect({
        type = "drop", x = x, y = y,
        text = GetGemDisplayName(gemType, 1) .. "x" .. tostring(amount),
        life = 1.2, maxLife = 1.2,
    })
    return true
end

function HandleEquipmentRiftMonsterRewards(monster, x, y, splitDepth)
    local equipmentDropped = HandleEquipmentRiftMonsterDrop(monster, x, y, splitDepth)
    local gemDropped = TryDropEquipmentRiftGem(monster, x, y)
    return equipmentDropped or gemDropped
end

function HandleEquipmentRiftMonsterDrop(monster, x, y, splitDepth)
    if not equipmentRiftActive or monster == nil then return false end
    local monsterType = monster.type or "normal"
    if monster.isBoss then
        return TryDropEquipmentRift(x, y, CONFIG.BossEquipmentDropChance, "boss")
    elseif monsterType == "elite" then
        return TryDropEquipmentRift(x, y, CONFIG.EliteDropChance, "elite")
    elseif monsterType == "splitter" then
        if (splitDepth or monster.splitDepth or 0) == 0 then
            return TryDropEquipmentRift(x, y, CONFIG.SplitterDropChance, "normal")
        end
    elseif monsterType == "blood" then
        return TryDropEquipmentRift(x, y, CONFIG.BloodDropChance, "blood")
    elseif monsterType == "ranged" then
        return TryDropEquipmentRift(x, y, CONFIG.MonsterEquipmentDropChance, "normal")
    end
    return false
end

function TryDropEquipmentRift(x, y, chance, monsterType)
    local luckBonus = GetLuckEquipmentDropBonus()
    if IS_CLOUD_ADMIN == true then luckBonus = luckBonus * 2 end
    local finalChance = math.min(
        GetEquipmentDropChanceCap(monsterType),
        (chance or 0) + luckBonus
    )
    if math.random() >= finalChance then return false end
    local slotDef = EQUIPMENT_SLOT_DEFS[math.random(1, #EQUIPMENT_SLOT_DEFS)]
    local item = GenerateEquipmentRiftEquipment(slotDef.id, nil, nil)
    AddEquipmentRiftTemporaryItem(item)
    AddEffect({
        type = "drop", x = x, y = y,
        text = GetEquipmentQualityLabel(item) .. "装备",
        life = 1.2, maxLife = 1.2,
    })
    return true
end

function CommitEquipmentRiftTemporaryGems()
    local summary = {}
    local total = 0
    for _, gemType in ipairs(GEM_ORDER or {}) do
        local count = math.max(0, math.floor((equipmentRiftTemporaryGems or {})[gemType] or 0))
        if count > 0 then
            summary[gemType] = count
            AddGem(gemType, 1, count, false)
            total = total + count
        end
    end
    equipmentRiftTemporaryGems = {}
    if total > 0 then saveDirty = true end
    return summary, total
end

function CommitEquipmentRiftTemporaryEquipment()
    NormalizeEquipment()
    ResetPendingLoot()
    local kept = 0
    local autoSold = 0
    local autoSoldGold = 0
    local autoSoldRefineStone = 0
    local discardedColorful = 0
    local rejectedCapacity = 0
    local itemResults = {}
    for _, item in ipairs(equipmentRiftTemporaryEquipment or {}) do
        local gold, refineStone = 0, 0
        if ShouldAutoSellEquipment(item) then
            gold, refineStone = GetEquipmentSellRewards(item)
        end
        local status = PendingAddEquipment(item)
        local statusText = "未获取"
        if status == "kept" then
            kept = kept + 1
            statusText = "已保留"
        elseif status == "autoSold" then
            autoSold = autoSold + 1
            autoSoldGold = autoSoldGold + gold
            autoSoldRefineStone = autoSoldRefineStone + refineStone
            statusText = "自动出售"
        elseif status == "destroyed" then
            discardedColorful = discardedColorful + 1
            statusText = "彩色上限销毁"
        elseif status == "inventoryFull" then
            rejectedCapacity = rejectedCapacity + 1
            statusText = "背包满未获取"
        end
        table.insert(itemResults, {
            name = GetEquipmentDisplayName(item),
            quality = GetEquipmentQualityLabel(item),
            color = GetEquipmentDisplayColor(item),
            status = statusText,
        })
    end
    CommitPendingLoot("equipment_rift_extract")
    equipmentRiftTemporaryEquipment = {}
    NormalizeEquipment()
    saveDirty = true
    return kept, discardedColorful, rejectedCapacity,
        autoSold, autoSoldGold, autoSoldRefineStone, itemResults
end

function GenerateEquipmentRiftGuaranteedAncient()
    if equipmentRiftAncientReward ~= nil then return equipmentRiftAncientReward end
    local slotDef = EQUIPMENT_SLOT_DEFS[math.random(1, #EQUIPMENT_SLOT_DEFS)]
    local item = GenerateEquipmentRiftEquipment(slotDef.id, "orange", true)
    item.riftGuaranteedAncient = true
    equipmentRiftAncientReward = item
    AddEquipmentRiftTemporaryItem(item)
    print("[EquipmentRift] 难度4橙色太古保底:", GetEquipmentDisplayName(item))
    return item
end

function UpgradeEquipmentRiftAncientRewardToRed()
    local orangeItem = equipmentRiftAncientReward
    if orangeItem == nil then orangeItem = GenerateEquipmentRiftGuaranteedAncient() end
    local redItem = GenerateEquipment(
        orangeItem.slot,
        "red",
        orangeItem.floor,
        true,
        false
    )
    redItem.name = orangeItem.name
    redItem.visualId = orangeItem.visualId
    redItem.resonanceSetId = orangeItem.resonanceSetId
    redItem.riftDrop = true
    redItem.riftGuaranteedAncient = true
    redItem.riftUpgradedFromOrange = true
    local replaced = false
    for index, item in ipairs(equipmentRiftTemporaryEquipment) do
        if item == orangeItem then
            equipmentRiftTemporaryEquipment[index] = redItem
            replaced = true
            break
        end
    end
    if not replaced then table.insert(equipmentRiftTemporaryEquipment, redItem) end
    equipmentRiftAncientReward = redItem
    print("[EquipmentRift] 难度5同件升级红色太古:", GetEquipmentDisplayName(redItem))
    return redItem
end

function BuildEquipmentRiftSpawnPlan(sourceFloor)
    sourceFloor = math.max(1, math.floor(sourceFloor or equipmentRiftSourceFloor or 1))
    local normalFloorCount = GetFloorMonsterCount(sourceFloor)
    local count = math.max(
        EQUIPMENT_RIFT_MIN_MONSTERS,
        math.floor(normalFloorCount * EQUIPMENT_RIFT_SPAWN_RATIO + 0.5)
    )
    local rawPlan = {}
    for i = 1, count do rawPlan[i] = "normal" end
    local eliteCount = 0
    for i = CONFIG.EliteEveryMonsters, count, CONFIG.EliteEveryMonsters do
        if AddPlannedMonster(rawPlan, i, "elite") then eliteCount = eliteCount + 1 end
    end
    local splitterCount = 0
    for i = CONFIG.SplitterEveryMonsters, count, CONFIG.SplitterEveryMonsters do
        if AddPlannedMonster(rawPlan, i, "splitter") then
            splitterCount = splitterCount + 1
        end
    end
    for i = CONFIG.RangedEveryMonsters, count, CONFIG.RangedEveryMonsters do
        AddPlannedMonster(rawPlan, i, "ranged")
    end
    for i = CONFIG.BloodEveryMonsters, count, CONFIG.BloodEveryMonsters do
        AddPlannedMonster(rawPlan, i, "blood")
    end

    local replacementTarget = splitterCount * 12
    local normalIndices = {}
    for index, monsterType in ipairs(rawPlan) do
        if monsterType == "normal" then table.insert(normalIndices, index) end
    end
    local replacementCount = math.min(replacementTarget, #normalIndices)
    if replacementCount > 0 then
        local removedIndices = {}
        for replacementIndex = 1, replacementCount do
            local normalPosition = math.floor(
                (replacementIndex - 0.5) * #normalIndices / replacementCount
            ) + 1
            removedIndices[normalIndices[normalPosition]] = true
        end
        local adjustedPlan = {}
        for index, monsterType in ipairs(rawPlan) do
            if not removedIndices[index] then table.insert(adjustedPlan, monsterType) end
        end
        rawPlan = adjustedPlan
    end

    local plan = {}
    for _, monsterType in ipairs(rawPlan) do
        table.insert(plan, { type = monsterType, floor = sourceFloor })
    end
    local bossCount = math.max(1, math.floor(eliteCount / CONFIG.BossEveryElites))
    floorBossSpawnPlan = {}
    floorBossSpawnIndex = 1
    for bossIndex = 1, bossCount do
        table.insert(floorBossSpawnPlan, {
            floor = sourceFloor,
            index = bossIndex,
            total = bossCount,
        })
    end
    print("[EquipmentRift] 难度", equipmentRiftDifficulty,
        "刷怪计划:", count, "Boss:", bossCount,
        "战斗层:", sourceFloor)
    return plan, bossCount
end

function ApplyEquipmentRiftDifficultyToMonster(monster)
    if not equipmentRiftActive or monster == nil then return monster end
    local modifier = GetEquipmentRiftDifficultyModifiers(equipmentRiftDifficulty)
    local hpMultiplier = modifier.hp
    local damageMultiplier = modifier.damage
    local attackSpeedMultiplier = modifier.attackSpeed
    local moveSpeedMultiplier = modifier.moveSpeed
    for _, mutation in ipairs(equipmentRiftMutations or {}) do
        if DoesEquipmentRiftMutationAffectMonster(mutation, monster) then
            hpMultiplier = hpMultiplier * (mutation.hp or 1)
            damageMultiplier = damageMultiplier * (mutation.damage or 1)
            attackSpeedMultiplier = attackSpeedMultiplier * (mutation.attackSpeed or 1)
            moveSpeedMultiplier = moveSpeedMultiplier * (mutation.moveSpeed or 1)
        end
    end
    local pressureHpMultiplier, pressureDamageMultiplier =
        GetEquipmentRiftPressureMultipliers(equipmentRiftLockedPressure)
    hpMultiplier = hpMultiplier * pressureHpMultiplier
    damageMultiplier = damageMultiplier * pressureDamageMultiplier
    monster.hp = monster.hp * hpMultiplier
    monster.maxHp = monster.hp
    monster.damage = monster.damage * damageMultiplier
    monster.speed = monster.speed * moveSpeedMultiplier
    monster.attackCooldownMultiplier = (monster.attackCooldownMultiplier or 1) / attackSpeedMultiplier
    monster.shootTimer = (monster.shootTimer or 0) / attackSpeedMultiplier
    return monster
end

function ClearEquipmentRiftTransientCombatState()
    monsters = {}
    monsterProjectiles = {}
    particles = {}
    skillEffects = {}
    visualEffectCount = 0
    pendingTreasureSpawnQueue = {}
    floorSpawnPlan = {}
    floorSpawnIndex = 1
    floorBossSpawnPlan = {}
    floorBossSpawnIndex = 1
    bossAlive = false
    bossSpawned = false
    battleCloneFocusTarget = nil
    for _, clone in ipairs(clones or {}) do
        clone.target = nil
        clone.targetLockTimer = 0
        clone.retargetTimer = 0
    end
    clusterCenterCache = {}
end

function StartEquipmentRiftDifficulty(difficulty)
    if not equipmentRiftActive then return false end
    equipmentRiftDifficulty = math.max(1, math.min(5, math.floor(difficulty or 1)))
    equipmentRiftDecision = nil
    currentScreen = "playing"
    ClearEquipmentRiftTransientCombatState()
    RollEquipmentRiftMutation()
    gameTime = 0
    runFloor = equipmentRiftSourceFloor
    StartFloor(equipmentRiftSourceFloor)
    simulationAccumulator = 0
    print("[EquipmentRift] 开始难度", equipmentRiftDifficulty,
        "临时装备:", #equipmentRiftTemporaryEquipment,
        "基地生命:", math.floor(base.hp), "/", math.floor(base.maxHp))
    return true
end

function StartEquipmentRiftNextDifficulty()
    return StartEquipmentRiftDifficulty(equipmentRiftDifficulty + 1)
end

-- 通关难度5时，按入场锁定的战斗基准层发放粉色洗练石数量：
-- 200层以下固定1个，200层起2个，300层起3个，400层起4个，500层起5个，600层起6个。
function GetEquipmentRiftPinkRefineStoneReward()
    local floor = math.max(1, math.floor(equipmentRiftSourceFloor or 1))
    if floor >= 600 then
        return 6
    elseif floor >= 500 then
        return 5
    elseif floor >= 400 then
        return 4
    elseif floor >= 300 then
        return 3
    elseif floor >= 200 then
        return 2
    end
    return 1
end

function FinishEquipmentRiftRunCommon()
    ClearEquipmentRiftTransientCombatState()
    ClearBattleRuntimeCache()
    ResetPendingLoot()
    runGoldReward = 0
    fiveBattleActive = false
    fiveBattleRequested = false
    fiveBattleRequestedFloorCount = 1
    fiveBattleFloorCount = 1
    fiveBattleSpeedMul = 1.0
    RestoreFormalStateAfterEquipmentRift()
    equipmentRiftActive = false
    equipmentRiftMutations = {}
    equipmentRiftLockedPressure = 0
    equipmentRiftDecision = nil
    simulationAccumulator = 0
end

function ExtractEquipmentRift(reason)
    if not equipmentRiftActive then return false end
    -- ⚠️ 压力+1 必须最先执行：后续装备/宝石提交等操作若因异常数据抛错，
    -- 不能再让成功结算的压力+1被跳过（与失败结算的压力扣减保持对称防护）
    AdjustEquipmentRiftPressure(1, "秘境成功结算")
    local difficulty = equipmentRiftDifficulty
    local pityGemGranted = false
    if difficulty >= EQUIPMENT_RIFT_GEM_PITY_MIN_DIFFICULTY
        and GetEquipmentRiftTemporaryGemCount() <= 0 then
        local pityGemType = GEM_ORDER[math.random(1, #GEM_ORDER)]
        AddEquipmentRiftTemporaryGem(pityGemType, 1)
        pityGemGranted = true
        print("[EquipmentRiftGem] 高难度零掉落保底:",
            GetGemDisplayName(pityGemType, 1))
    end
    local gemSummary, gemCount = CommitEquipmentRiftTemporaryGems()
    local kept, discarded, rejectedCapacity,
        autoSold, autoSoldGold, autoSoldRefineStone, itemResults =
        CommitEquipmentRiftTemporaryEquipment()
    local socketPuncherReward = 0
    if difficulty >= EQUIPMENT_RIFT_SOCKET_PUNCHER_MIN_DIFFICULTY
        and math.random() < EQUIPMENT_RIFT_SOCKET_PUNCHER_CHANCE then
        socketPuncherReward = 1
        AddSocketPuncher(socketPuncherReward, true)
    end
    local pinkRefineStoneReward = 0
    if reason == "difficulty_5_complete" then
        pinkRefineStoneReward = GetEquipmentRiftPinkRefineStoneReward()
        AddPinkRefineStone(pinkRefineStoneReward, true)
    end
    equipmentRiftResult = {
        success = true,
        title = difficulty >= 5 and "秘境征服" or "安全撤离",
        difficulty = difficulty,
        kept = kept,
        autoSold = autoSold,
        autoSoldGold = autoSoldGold,
        autoSoldRefineStone = autoSoldRefineStone,
        discarded = discarded,
        rejectedCapacity = rejectedCapacity,
        items = itemResults,
        gems = gemSummary,
        gemCount = gemCount,
        pityGemGranted = pityGemGranted,
        socketPuncherReward = socketPuncherReward,
        pinkRefineStoneReward = pinkRefineStoneReward,
        pinkRefineStoneFloor = math.max(1, math.floor(equipmentRiftSourceFloor or 1)),
        reason = reason or "extract",
        ancient = equipmentRiftAncientReward,
    }
    FinishEquipmentRiftRunCommon()
    currentScreen = "rift_result"
    SaveCloudData(true)
    print("[EquipmentRift] 安全结算, 难度:", difficulty,
        "保留装备:", kept, "自动出售:", autoSold,
        "自动出售金币:", autoSoldGold, "自动出售" .. REFINE_STONE_NAME .. ":", autoSoldRefineStone,
        "粉色洗练石奖励:", pinkRefineStoneReward,
        "彩色销毁:", discarded, "容量满未获取:", rejectedCapacity)
    return true
end

function FailEquipmentRift(reason)
    print("[RiftFail] FailEquipmentRift 进入: reason=", tostring(reason),
        "active=", tostring(equipmentRiftActive),
        "当前压力=", tostring(playerData.equipmentRiftPressure))
    if not equipmentRiftActive then
        print("[RiftFail] equipmentRiftActive 为 false，提前返回不扣压力!")
        return false
    end
    -- ⚠️ 压力扣除必须最先执行：后续金币扣减/技能掉落等操作若因异常数据抛错，
    -- 不能再让压力扣减被跳过（否则会出现“金币装备已扣但压力没扣”的不一致）
    if reason ~= "active_exit" then
        AdjustEquipmentRiftPressure(-2, "秘境失败惩罚")
    else
        print("[EquipmentRiftPressure] 主动退出不降低压力")
    end
    local difficulty = equipmentRiftDifficulty
    local lostEquipmentCount = #equipmentRiftTemporaryEquipment
    local lostGems = equipmentRiftTemporaryGems or {}
    local lostGemCount = GetEquipmentRiftTemporaryGemCount()
    equipmentRiftTemporaryEquipment = {}
    equipmentRiftTemporaryGems = {}
    equipmentRiftAncientReward = nil
    local goldBefore = math.max(0, math.floor(playerData.gold or 0))
    local goldLoss = math.floor(goldBefore * 0.5)
    playerData.gold = math.max(0, goldBefore - goldLoss)
    local droppedSkills = {}
    local dropOk, dropResult = pcall(DropHighestStarSkillsOnDeath)
    if dropOk then
        droppedSkills = dropResult
    else
        print("[RiftFail] 技能掉落处理异常，已跳过:", tostring(dropResult))
    end
    if type(droppedSkills) ~= "table" then droppedSkills = {} end
    local skillParts = {}
    for _, skill in ipairs(droppedSkills) do
        table.insert(skillParts, tostring(skill.name or "技能") .. " " .. tostring(skill.star or 1) .. "星")
        print("[EquipmentRift] 失败丢失技能:", skill.name or skill.id, skill.star or 1)
    end
    equipmentRiftResult = {
        success = false,
        title = "秘境失败",
        difficulty = difficulty,
        lostEquipmentCount = lostEquipmentCount,
        lostGems = lostGems,
        lostGemCount = lostGemCount,
        goldLoss = goldLoss,
        droppedSkills = droppedSkills,
        skillLossText = #skillParts > 0 and table.concat(skillParts, "、") or "没有技能可丢失",
        reason = reason or "death",
    }
    saveDirty = true
    FinishEquipmentRiftRunCommon()
    currentScreen = "rift_result"
    SaveCloudData(true)
    print("[EquipmentRift] 失败结算, 原因:", reason,
        "临时装备损失:", lostEquipmentCount, "金币损失:", goldLoss,
        "技能损失:", #droppedSkills)
    return true
end

function CompleteEquipmentRiftDifficulty()
    if not equipmentRiftActive then return false end
    local difficulty = equipmentRiftDifficulty
    if difficulty == 4 then
        GenerateEquipmentRiftGuaranteedAncient()
    elseif difficulty >= 5 then
        UpgradeEquipmentRiftAncientRewardToRed()
        ExtractEquipmentRift("difficulty_5_complete")
        return true
    end

    if difficulty == 3 or difficulty == 4 then
        equipmentRiftDecision = {
            difficulty = difficulty,
            ancient = difficulty == 4 and equipmentRiftAncientReward or nil,
        }
        currentScreen = "rift_decision"
        ClearEquipmentRiftTransientCombatState()
        simulationAccumulator = 0
        print("[EquipmentRift] 难度", difficulty, "完成，等待撤离选择")
        return true
    end

    StartEquipmentRiftNextDifficulty()
    return true
end

function RequestEquipmentRiftExit()
    if not equipmentRiftActive or currentScreen ~= "playing" then return false end
    currentScreen = "rift_exit_confirm"
    simulationAccumulator = 0
    print("[EquipmentRift] 请求主动退出确认")
    return true
end

function CancelEquipmentRiftExit()
    if not equipmentRiftActive then return false end
    currentScreen = "playing"
    simulationAccumulator = 0
    return true
end

function HandleEquipmentRiftDecisionClick(px, py)
    for index, rect in ipairs(equipmentRiftDecisionButtonRects or {}) do
        if px >= rect.x and px <= rect.x + rect.w
            and py >= rect.y and py <= rect.y + rect.h then
            if index == 1 then
                StartEquipmentRiftNextDifficulty()
            else
                ExtractEquipmentRift("safe_extract")
            end
            return true
        end
    end
    return false
end

function HandleEquipmentRiftExitConfirmClick(px, py)
    for index, rect in ipairs(equipmentRiftExitConfirmButtonRects or {}) do
        if px >= rect.x and px <= rect.x + rect.w
            and py >= rect.y and py <= rect.y + rect.h then
            if index == 1 then
                FailEquipmentRift("active_exit")
            else
                CancelEquipmentRiftExit()
            end
            return true
        end
    end
    return false
end

function HandleEquipmentRiftResultClick(px, py)
    for index, rect in ipairs(equipmentRiftResultButtonRects or {}) do
        if px >= rect.x and px <= rect.x + rect.w
            and py >= rect.y and py <= rect.y + rect.h then
            if index == 1 then
                ShowEquipmentRiftSetupPage()
            else
                ShowTrialSelectionPage()
            end
            return true
        end
    end
    return false
end

function TryEquipmentRiftExitButton(px, py)
    if not equipmentRiftActive then return false end
    local rect = equipmentRiftExitButtonRect
    if rect ~= nil and px >= rect.x and px <= rect.x + rect.w
        and py >= rect.y and py <= rect.y + rect.h then
        return RequestEquipmentRiftExit()
    end
    return false
end

function DrawEquipmentRiftHud(vg)
    if not equipmentRiftActive then
        equipmentRiftExitButtonRect = nil
        return
    end
    local si = safeInset or { top = 0 }
    local buttonW, buttonH = 82, 28
    local buttonX = screenW * 0.5 - buttonW * 0.5
    local buttonY = si.top + 8
    equipmentRiftExitButtonRect = {
        x = buttonX - 6, y = buttonY - 6,
        w = buttonW + 12, h = buttonH + 12,
    }
    nvgBeginPath(vg)
    nvgRect(vg, buttonX, buttonY, buttonW, buttonH)
    nvgFillColor(vg, nvgRGBA(126, 32, 48, 245))
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(255, 105, 92, 245))
    nvgStrokeWidth(vg, 2)
    nvgStroke(vg)
    nvgFontFace(vg, "pixel")
    nvgFontSize(vg, 11)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
    nvgText(vg, buttonX + buttonW * 0.5, buttonY + buttonH * 0.5, "主动退出", nil)

    local infoY = buttonY + buttonH + 5
    nvgFontSize(vg, 9)
    nvgFillColor(vg, nvgRGBA(255, 222, 115, 245))
    nvgText(vg, screenW * 0.5, infoY,
        "临时装备 " .. tostring(#equipmentRiftTemporaryEquipment)
            .. "｜临时宝石 " .. tostring(GetEquipmentRiftTemporaryGemCount())
            .. "｜装等 " .. tostring(GetEquipmentRiftGearFloor()), nil)

    local pressureHpMultiplier, pressureDamageMultiplier =
        GetEquipmentRiftPressureMultipliers(equipmentRiftLockedPressure)
    nvgFontSize(vg, 8)
    nvgFillColor(vg, equipmentRiftLockedPressure > 0
        and nvgRGBA(255, 142, 110, 250)
        or nvgRGBA(176, 210, 188, 235))
    nvgText(vg, screenW * 0.5, infoY + 14,
        "秘境压力 " .. tostring(equipmentRiftLockedPressure)
            .. "｜生命×" .. string.format("%.2f", pressureHpMultiplier)
            .. "｜伤害×" .. string.format("%.2f", pressureDamageMultiplier), nil)

    local mutationCount, mutationSummary = GetEquipmentRiftMutationSummary()
    local mutationText = "累计异变 " .. tostring(mutationCount)
    if mutationSummary ~= "" then
        mutationText = mutationText .. "｜" .. mutationSummary
    end
    nvgFontSize(vg, screenW < 360 and 7 or 8)
    nvgFillColor(vg, nvgRGBA(255, 132, 92, 255))
    nvgText(vg, screenW * 0.5, infoY + 28, mutationText, nil)
end

local function DrawRiftOverlay(vg, panelW, panelH)
    nvgBeginPath(vg)
    nvgRect(vg, 0, 0, screenW, screenH)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 196))
    nvgFill(vg)
    local x = (screenW - panelW) * 0.5
    local y = (screenH - panelH) * 0.5
    nvgBeginPath(vg)
    nvgRect(vg, x, y, panelW, panelH)
    local fill = nvgLinearGradient(vg, x, y, x, y + panelH,
        nvgRGBA(34, 22, 52, 252), nvgRGBA(12, 12, 24, 252))
    nvgFillPaint(vg, fill)
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(235, 185, 76, 245))
    nvgStrokeWidth(vg, 2)
    nvgStroke(vg)
    return x, y
end

local function DrawRiftButton(vg, rect, label, primary)
    nvgBeginPath(vg)
    nvgRect(vg, rect.x, rect.y, rect.w, rect.h)
    nvgFillColor(vg, primary and nvgRGBA(142, 38, 54, 248) or nvgRGBA(52, 36, 72, 248))
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(225, 178, 74, 235))
    nvgStrokeWidth(vg, 1)
    nvgStroke(vg)
    nvgFontSize(vg, 10)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
    nvgText(vg, rect.x + rect.w * 0.5, rect.y + rect.h * 0.5, label, nil)
end

function DrawEquipmentRiftDecisionPanel(vg)
    local decision = equipmentRiftDecision or {}
    local hasAncient = decision.ancient ~= nil
    local panelW = math.min(430, screenW - 34)
    local panelH = hasAncient and math.min(410, screenH - 30) or 235
    local x, y = DrawRiftOverlay(vg, panelW, panelH)
    nvgFontFace(vg, "pixel")
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 22)
    nvgFillColor(vg, nvgRGBA(255, 220, 100, 255))
    nvgText(vg, screenW * 0.5, y + 34,
        "难度" .. tostring(decision.difficulty or equipmentRiftDifficulty) .. "完成", nil)
    nvgFontSize(vg, 10)
    nvgFillColor(vg, nvgRGBA(182, 182, 208, 245))
    nvgText(vg, screenW * 0.5, y + 59,
        "当前临时装备 " .. tostring(#equipmentRiftTemporaryEquipment)
            .. " 件｜宝石 " .. tostring(GetEquipmentRiftTemporaryGemCount()) .. " 颗", nil)

    local contentBottom = y + 96
    if hasAncient then
        local item = decision.ancient
        nvgFontSize(vg, 14)
        nvgFillColor(vg, nvgRGBA(255, 220, 105, 255))
        nvgText(vg, screenW * 0.5, y + 86, GetEquipmentDisplayName(item), nil)
        nvgFontSize(vg, 10)
        nvgFillColor(vg, nvgRGBA(235, 205, 125, 245))
        nvgText(vg, screenW * 0.5, y + 108,
            GetEquipmentQualityLabel(item) .. "｜第" .. tostring(item.floor) .. "层｜"
                .. tostring((EQUIPMENT_SLOT_BY_ID[item.slot] or {}).name or item.slot), nil)
        local lines = { MakeAffixDisplay(item.baseAffix) }
        for _, affix in ipairs(item.affixes or {}) do
            table.insert(lines, MakeAffixDisplay(affix))
        end
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        for index, line in ipairs(lines) do
            nvgFontSize(vg, 9)
            nvgFillColor(vg, index == 1
                and nvgRGBA(255, 225, 120, 250)
                or nvgRGBA(210, 210, 228, 245))
            nvgText(vg, x + 34, y + 132 + (index - 1) * 20, line, nil)
        end
        contentBottom = y + 146 + #lines * 20
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFontSize(vg, 9)
        nvgFillColor(vg, nvgRGBA(255, 112, 104, 245))
        nvgText(vg, screenW * 0.5, contentBottom,
            "继续挑战：通关难度5后同件升级替换为红色太古", nil)
    else
        nvgFontSize(vg, 10)
        nvgFillColor(vg, nvgRGBA(220, 220, 235, 245))
        nvgText(vg, screenW * 0.5, y + 96,
            "撤离时按普通掉落设置自动出售装备", nil)
        nvgFillColor(vg, nvgRGBA(255, 112, 104, 245))
        nvgText(vg, screenW * 0.5, y + 119,
            "继续后若失败，临时装备将全部丢失", nil)
        contentBottom = y + 136
    end

    local buttonY = math.min(y + panelH - 46, contentBottom + 22)
    local gap = 10
    local buttonW = (panelW - 46 - gap) * 0.5
    equipmentRiftDecisionButtonRects = {
        { x = x + 18, y = buttonY, w = buttonW, h = 32 },
        { x = x + 18 + buttonW + gap, y = buttonY, w = buttonW, h = 32 },
    }
    DrawRiftButton(vg, equipmentRiftDecisionButtonRects[1], "继续挑战", true)
    DrawRiftButton(vg, equipmentRiftDecisionButtonRects[2], "安全撤离", false)
end

