function DrawEquipmentRiftResultPanel(vg)
    local result = equipmentRiftResult or {}
    local items = result.items or {}
    local maxRows = math.min(7, #items)
    local rewardLineHeight = ((result.pinkRefineStoneReward or 0) > 0
        and 24 or 0)
        + ((result.socketPuncherReward or 0) > 0
            and 22 or 0)
    local itemStartY = 132 + rewardLineHeight
    local panelW = math.min(430, screenW - 34)
    local panelH = math.min(screenH - 28, 270 + rewardLineHeight + maxRows * 22)
    local x, y = DrawRiftOverlay(vg, panelW, panelH)
    nvgFontFace(vg, "pixel")
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 24)
    nvgFillColor(vg, result.success
        and nvgRGBA(255, 220, 100, 255)
        or nvgRGBA(255, 92, 92, 255))
    nvgText(vg, screenW * 0.5, y + 38, result.title or "秘境结算", nil)
    nvgFontSize(vg, 10)
    nvgFillColor(vg, nvgRGBA(182, 182, 208, 245))
    nvgText(vg, screenW * 0.5, y + 64,
        "完成至难度 " .. tostring(result.difficulty or 0), nil)

    if result.success then
        nvgFontSize(vg, 12)
        nvgFillColor(vg, nvgRGBA(135, 235, 165, 255))
        nvgText(vg, screenW * 0.5, y + 91,
            "保留装备 " .. tostring(result.kept or 0)
                .. " 件｜自动出售 " .. tostring(result.autoSold or 0)
                .. " 件｜宝石 " .. tostring(result.gemCount or 0) .. " 颗", nil)
        local summaryParts = {}
        if (result.autoSold or 0) > 0 then
            table.insert(summaryParts,
                "出售得金币" .. tostring(result.autoSoldGold or 0)
                    .. "、" .. REFINE_STONE_NAME .. tostring(result.autoSoldRefineStone or 0))
        end
        if (result.discarded or 0) > 0 then
            table.insert(summaryParts, "彩色上限销毁" .. tostring(result.discarded) .. "件")
        end
        if (result.rejectedCapacity or 0) > 0 then
            table.insert(summaryParts, "背包满未获取" .. tostring(result.rejectedCapacity) .. "件")
        end
        if #summaryParts > 0 then
            nvgFontSize(vg, 9)
            local summaryColor = nvgRGBA(255, 214, 112, 245)
            if (result.discarded or 0) > 0 or (result.rejectedCapacity or 0) > 0 then
                summaryColor = nvgRGBA(255, 112, 104, 245)
            end
            nvgFillColor(vg, summaryColor)
            nvgText(vg, screenW * 0.5, y + 112, table.concat(summaryParts, "｜"), nil)
        end
        local rewardY = y + 134
        if (result.pinkRefineStoneReward or 0) > 0 then
            nvgFontSize(vg, 10)
            nvgFillColor(vg, nvgRGBA(255, 145, 225, 255))
            nvgText(vg, screenW * 0.5, rewardY,
                "通关难度5奖励：粉色洗练石 ×" .. tostring(result.pinkRefineStoneReward)
                    .. "（基准第" .. tostring(result.pinkRefineStoneFloor or equipmentRiftSourceFloor or 1) .. "层）", nil)
            rewardY = rewardY + 22
        end
        if (result.socketPuncherReward or 0) > 0 then
            nvgFontSize(vg, 10)
            nvgFillColor(vg, nvgRGBA(255, 210, 100, 255))
            nvgText(vg, screenW * 0.5, rewardY,
                "幸运奖励：打孔器 ×" .. tostring(result.socketPuncherReward), nil)
        end
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        for index = 1, maxRows do
            local item = items[index]
            nvgFontSize(vg, 9)
            local color = item.color or { 220, 220, 235, 245 }
            nvgFillColor(vg, nvgRGBA(color[1], color[2], color[3], color[4] or 255))
            nvgText(vg, x + 28, y + itemStartY + (index - 1) * 22,
                tostring(index) .. ". " .. tostring(item.name) .. "  "
                    .. tostring(item.quality) .. "｜" .. tostring(item.status or "已处理"), nil)
        end
        if #items > maxRows then
            nvgFontSize(vg, 9)
            nvgFillColor(vg, nvgRGBA(180, 180, 205, 245))
            nvgText(vg, x + 28, y + itemStartY + maxRows * 22,
                "另有 " .. tostring(#items - maxRows) .. " 件装备已完成结算", nil)
        end
    else
        nvgFontSize(vg, 11)
        nvgFillColor(vg, nvgRGBA(255, 112, 104, 255))
        nvgText(vg, screenW * 0.5, y + 96,
            "临时装备丢失 " .. tostring(result.lostEquipmentCount or 0)
                .. " 件｜宝石 " .. tostring(result.lostGemCount or 0) .. " 颗", nil)
        nvgText(vg, screenW * 0.5, y + 121,
            "金币损失 " .. tostring(result.goldLoss or 0), nil)
        nvgFontSize(vg, 9)
        nvgFillColor(vg, nvgRGBA(225, 225, 238, 245))
        nvgText(vg, screenW * 0.5, y + 151,
            "技能丢失：" .. tostring(result.skillLossText or "没有技能可丢失"), nil)
        nvgFillColor(vg, nvgRGBA(160, 160, 190, 240))
        nvgText(vg, screenW * 0.5, y + 178,
            "正式层数、最高纪录、转生和肉鸽状态均未改变", nil)
    end

    local gap = 10
    local buttonW = (panelW - 46 - gap) * 0.5
    equipmentRiftResultButtonRects = {
        { x = x + 18, y = y + panelH - 46, w = buttonW, h = 32 },
        { x = x + 18 + buttonW + gap, y = y + panelH - 46, w = buttonW, h = 32 },
    }
    DrawRiftButton(vg, equipmentRiftResultButtonRects[1], "再次挑战", true)
    DrawRiftButton(vg, equipmentRiftResultButtonRects[2], "返回试炼", false)
end


