function BuildPixelSword(cellSize)
    cellSize = cellSize or 5
    local C_BLADE = { 200, 210, 240, 255 }      -- 剑身银蓝
    local C_BLADE_HI = { 240, 245, 255, 255 }   -- 剑身高光
    local C_EDGE = { 160, 180, 220, 255 }       -- 剑刃暗部
    local C_GUARD = { 210, 170, 50, 255 }       -- 护手金色
    local C_GUARD_HI = { 240, 200, 80, 255 }    -- 护手高光
    local C_GRIP = { 90, 30, 20, 255 }          -- 握柄深红褐
    local C_GRIP_HI = { 140, 50, 30, 255 }      -- 握柄高光
    local C_GEM = { 220, 40, 40, 255 }          -- 红宝石
    local C_GEM_HI = { 255, 100, 100, 255 }     -- 宝石高光
    local C_POMMEL = { 180, 140, 40, 255 }      -- 剑柄底球
    local C_GLOW = { 200, 50, 50, 80 }          -- 红色发光

    local swordMap = {
        { 0, 0, 0, 2, 0, 0, 0 },  -- 剑尖
        { 0, 0, 3, 2, 1, 0, 0 },
        { 0, 0, 3, 1, 2, 0, 0 },
        { 0, 0, 3, 1, 2, 0, 0 },
        { 0, 3, 3, 1, 2, 2, 0 },
        { 0, 3, 1, 2, 1, 2, 0 },
        { 0, 3, 1, 1, 1, 2, 0 },
        { 0, 3, 1, 2, 1, 2, 0 },
        { 0, 3, 1, 1, 1, 2, 0 },
        { 0, 3, 1, 2, 1, 2, 0 },
        { 0, 3, 1, 1, 1, 2, 0 },
        { 0, 3, 1, 2, 1, 2, 0 },
        { 0, 3, 1, 1, 1, 2, 0 },
        { 0, 3, 1, 2, 1, 2, 0 },
        { 0, 3, 1, 1, 1, 2, 0 },
        { 0, 3, 1, 2, 1, 2, 0 },
        { 0, 3, 1, 1, 1, 2, 0 },
        { 0, 3, 1, 2, 1, 2, 0 },  -- 剑身结束
        { 4, 5, 4, 8, 4, 5, 4 },  -- 护手上
        { 5, 4, 4, 9, 4, 4, 5 },  -- 护手下+宝石高光
        { 0, 0, 6, 7, 6, 0, 0 },  -- 握柄
        { 0, 0, 7, 6, 7, 0, 0 },
        { 0, 0, 6, 7, 6, 0, 0 },
        { 0, 0, 7, 6, 7, 0, 0 },
        { 0, 0, 6, 7, 6, 0, 0 },
        { 0, 0, 7, 6, 7, 0, 0 },
        { 0, 4, 5, 10, 5, 4, 0 },  -- 底球
        { 0, 0, 4, 5, 4, 0, 0 },   -- 底球下
    }

    local colorMap = {
        [0] = nil,
        [1] = C_BLADE,
        [2] = C_BLADE_HI,
        [3] = C_EDGE,
        [4] = C_GUARD,
        [5] = C_GUARD_HI,
        [6] = C_GRIP,
        [7] = C_GRIP_HI,
        [8] = C_GEM,
        [9] = C_GEM_HI,
        [10] = C_POMMEL,
    }

    local rows = {}
    for _, row in ipairs(swordMap) do
        local cells = {}
        for _, val in ipairs(row) do
            local color = colorMap[val]
            if color then
                table.insert(cells, UI.Panel {
                    width = cellSize,
                    height = cellSize,
                    backgroundColor = color,
                })
            else
                table.insert(cells, UI.Panel {
                    width = cellSize,
                    height = cellSize,
                })
            end
        end
        table.insert(rows, UI.Panel {
            flexDirection = "row",
            height = cellSize,
            children = cells,
        })
    end

    return UI.Panel {
        alignItems = "center",
        justifyContent = "center",
        padding = 8,
        backgroundColor = { 200, 50, 50, 16 },
        borderWidth = 1,
        borderColor = { 210, 170, 50, 60 },
        children = {
            UI.Panel {
                alignItems = "center",
                children = rows,
            },
        },
    }
end

function ShowRoguelikeChoicePage(node, options)
    currentScreen = "roguelike"
    UpdateScreenMetrics()

    local compactRoguelikeLayout = screenW < 680

    local function MakeModifierChip(def, value)
        local monsterOnly = def.monsterOnly == true
        local positive = not monsterOnly and value > 0
        local color = monsterOnly
            and { 236, 154, 70, 255 }
            or (positive
                and { 104, 220, 132, 255 }
                or { 242, 104, 104, 255 })
        local prefix = value > 0 and "+" or ""
        return UI.Panel {
            minHeight = 25,
            paddingHorizontal = 8,
            paddingVertical = 4,
            backgroundColor = { color[1], color[2], color[3], 32 },
            borderWidth = 1,
            borderColor = color,
            borderRadius = 5,
            children = {
                UI.Label {
                    text = def.label .. " " .. prefix .. tostring(value) .. "%",
                    fontSize = 9,
                    fontColor = color,
                    fontWeight = "bold",
                    textAlign = "center",
                },
            },
        }
    end

    local playerBuffs = {}
    local playerDebuffs = {}
    local monsterBuffs = {}
    for _, def in ipairs(ROGUELIKE_OPTION_DEFS or {}) do
        local value = GetRoguelikeModifier(def.stat)
        if value ~= 0 then
            local chip = MakeModifierChip(def, value)
            if def.monsterOnly then
                table.insert(monsterBuffs, chip)
            elseif value > 0 then
                table.insert(playerBuffs, chip)
            else
                table.insert(playerDebuffs, chip)
            end
        end
    end

    local function MakeModifierGroup(title, items, accentColor)
        if #items == 0 then
            table.insert(items, UI.Label {
