-- 当前显示第几页（1=第1~20名，2=第21~40名，...，5=第81~100名）；进入排行榜时固定重置为第1页
leaderboardDisplayPage = leaderboardDisplayPage or 1

function _BanKey(uid)
    if uid == nil then return nil end
    return tostring(uid)
end

function IsLeaderboardBanned(roleId)
    if roleId == nil then return false end
    local key = _BanKey(roleId)
    if LEADERBOARD_BANLIST[roleId] == true or LEADERBOARD_BANLIST[key] == true then
        return true
    end
    if CLOUD_BANLIST[key] then return true end
    return false
end

function IsCloudAdminUserId(roleId)
    if roleId == nil or CLOUD_ADMIN_UID == nil then return false end
    return tostring(roleId) == tostring(CLOUD_ADMIN_UID)
end

-- 管理员排行榜条目对所有玩家可见，不再对其他人隐藏。
-- 管理员的额外击杀/时长等展示加成仍只对管理员自己生效（见 ShouldApplyAdminPublicDisplayBonus）。
function ShouldHideCloudAdminFromOthers(roleId)
    return false
end

function IsLeaderboardNameBanned(nickname)
    if nickname == nil then return false end
    return LEADERBOARD_NAME_BANLIST[tostring(nickname)] == true
end

function FilterLeaderboardBannedEntries(entries)
    local filtered = {}
    for _, entry in ipairs(entries or {}) do
        if not IsLeaderboardBanned(entry.userId)
            and not IsLeaderboardNameBanned(entry.platformNickname or entry.nickname)
            and not ShouldHideCloudAdminFromOthers(entry.userId) then
            table.insert(filtered, entry)
            entry.rank = #filtered
        end
    end
    return filtered
end

function _CountTable(t)
    local n = 0
    for _ in pairs(t or {}) do n = n + 1 end
    return n
end

function ClaimAdminMaterialGrants(grants)
    if type(grants) ~= "table" then
        return false, 0, 0, 0
    end
    if not cloudDataReadyForSave or CLOUD_DATA_FETCH_IN_PROGRESS then
        ADMIN_MATERIAL_GRANT_SYNC_PENDING = true
        ADMIN_MATERIAL_GRANT_SYNC_TIMER = 0
        ADMIN_MATERIAL_GRANT_SYNC_IN_FLIGHT = false
        print("[MaterialGrant] 云存档尚未完成同步，延后领取管理员洗练石奖励")
        return false, 0, 0, 0
    end
    NormalizeAdminMaterialGrantClaims()
    local whiteCount = 0
    local pinkCount = 0
    local changed = false
    for grantId, grant in pairs(grants) do
        local key = tostring(grantId or "")
        if key ~= "" and type(grant) == "table" then
            local materialId = tostring(grant.materialId or "")
            local amount = math.floor(tonumber(grant.amount) or 0)
            local validAmount = amount >= 1 and amount <= 9999
            if playerData.adminMaterialGrantClaims[key] == nil
                and validAmount
                and (materialId == REFINE_STONE_ITEM_ID or materialId == PINK_REFINE_STONE_ITEM_ID) then
                GrantMaterialToCurrentPlayer(materialId, amount, true)
                if materialId == REFINE_STONE_ITEM_ID then
                    whiteCount = whiteCount + amount
                else
                    pinkCount = pinkCount + amount
                end
                playerData.adminMaterialGrantClaims[key] = math.max(
                    1, math.floor(tonumber(grant.createdAt) or os.time()))
                changed = true
                print("[MaterialGrant] 洗练石 grant 已领取", key, materialId, amount)
            end
        end
    end
    if whiteCount > 0 or pinkCount > 0 then
        RecordAdminGrantNotice({ whiteRefine = whiteCount, pinkRefine = pinkCount })
    end
    if changed then
        NormalizeAdminMaterialGrantClaims()
        MarkSaveDirty()
        SaveCloudData(true)
    end
    ADMIN_MATERIAL_GRANT_SYNC_PENDING = false
    ADMIN_MATERIAL_GRANT_SYNC_IN_FLIGHT = false
    return changed, whiteCount, pinkCount, 0
end

function ClaimAdminGrantsFromOwnAccount()
    -- 单机客户端无法依赖 GetRankList 可靠读回 values 键（发放队列存在 values 里），
    -- 因此对自己账号直接用 BatchGet 读取发放队列并领取，绕开排行榜通道。
    if not clientCloud or not cloudDataLoaded or not cloudDataReadyForSave then
        return
    end
    local myUid = tostring(clientCloud.userId or "")
    if myUid == "" then return end
    local request = clientCloud:BatchGet()
    request:Key(ADMIN_MATERIAL_GRANTS_KEY)
    request:Key(ADMIN_REBIRTH_STONE_GRANTS_KEY)
    request:Fetch({
        ok = function(values)
            values = values or {}
            local materialGrants = values[ADMIN_MATERIAL_GRANTS_KEY]
            if type(materialGrants) == "table" then
                local claimed, whiteCount, pinkCount = ClaimAdminMaterialGrants(materialGrants[myUid])
                if claimed then
                    print("[MaterialGrant] 直读管理员账号发放已领取, uid=", myUid,
                        "白色=", whiteCount, "粉色=", pinkCount)
                end
            end
            local rebirthGrants = values[ADMIN_REBIRTH_STONE_GRANTS_KEY]
            if type(rebirthGrants) == "table" then
                local claimed, count = ClaimAdminRebirthStoneGrants(rebirthGrants[myUid])
                if claimed then
                    print("[RebirthStoneGrant] 直读管理员账号发放已领取, uid=", myUid, "数量=", count)
                end
            end
        end,
        error = function(code, reason)
            print("[AdminGrant] 直读管理员账号发放失败:", tostring(reason))
        end,
        timeout = function()
            print("[AdminGrant] 直读管理员账号发放超时")
        end,
    })
end

-- 合并管理员发放队列：云端新读到的 grant 与内存中本会话新发放的 grant 取并集，
-- 避免 LoadCloudBanlist 用旧云端快照覆盖刚写入的发放导致丢失。
-- 返回合并后的表（直接改 target，返回 target）。
function MergeGrantQueues(target, incoming)
    if type(target) ~= "table" then target = {} end
    if type(incoming) ~= "table" then return target end
    for uid, grants in pairs(incoming) do
        if type(grants) == "table" then
            local targetGrants = target[tostring(uid)]
            if type(targetGrants) ~= "table" then
                target[tostring(uid)] = {}
                targetGrants = target[tostring(uid)]
            end
            for grantId, grant in pairs(grants) do
                local key = tostring(grantId or "")
                if key ~= "" and targetGrants[key] == nil then
                    targetGrants[key] = grant
                end
            end
        end
    end
    return target
end

-- 普通玩家周期性补领管理员发放：拉取管理员发放队列并领取自己的 grant
function PollAdminGrantsForNormalPlayer()
    if not clientCloud or not cloudDataLoaded or not cloudDataReadyForSave
        or CLOUD_DATA_FETCH_IN_PROGRESS then return false end
    if IS_CLOUD_ADMIN then return false end
    if ADMIN_GRANT_POLL_IN_FLIGHT then return false end
    local myUid = tostring(clientCloud.userId or "")
    if myUid == "" then return false end
    ADMIN_GRANT_POLL_IN_FLIGHT = true
    -- 普通玩家读不到管理员账号的 BatchGet，只能通过 GetRankList 读管理员记录的 values
    clientCloud:GetRankList(ADMIN_CLAIM_KEY, 0, 1, {
        ok = function(rankList)
            ADMIN_GRANT_POLL_IN_FLIGHT = false
            if not rankList or #rankList == 0 then return end
            local item = rankList[1]
            local materialGrants = (item.score and item.score[ADMIN_MATERIAL_GRANTS_KEY]) or {}
            local rebirthStoneGrants = (item.score and item.score[ADMIN_REBIRTH_STONE_GRANTS_KEY]) or {}
            if type(materialGrants) ~= "table" then materialGrants = {} end
            if type(rebirthStoneGrants) ~= "table" then rebirthStoneGrants = {} end
            local claimed = false
            if ClaimAdminMaterialGrants ~= nil then
                local c, w, p = ClaimAdminMaterialGrants(materialGrants[myUid])
                if c then
                    claimed = true
                    print("[MaterialGrant] 轮询领取成功, uid=", myUid, "白色=", w, "粉色=", p)
                end
            end
            if ClaimAdminRebirthStoneGrants ~= nil then
                local c, count = ClaimAdminRebirthStoneGrants(rebirthStoneGrants[myUid])
                if c then
                    claimed = true
                    print("[RebirthStoneGrant] 轮询领取成功, uid=", myUid, "数量=", count)
                end
            end
            if claimed then
                SaveCloudData(true)
            end
        end,
        error = function(code, reason)
            ADMIN_GRANT_POLL_IN_FLIGHT = false
            print("[AdminGrant] 轮询拉取失败:", tostring(reason))
        end,
        timeout = function()
            ADMIN_GRANT_POLL_IN_FLIGHT = false
            print("[AdminGrant] 轮询拉取超时")
        end,
    })
    return true
end

-- 管理员给自己发放时若云存档未就绪，主循环定时调用本函数补领
-- 通过 BatchGet 直读自己账号上的发放队列（发放队列存在管理员自己账号），
-- 避免内存快照被旧数据覆盖导致的丢发放
function RetryAdminSelfGrants()
    if not clientCloud or not cloudDataLoaded or not cloudDataReadyForSave
        or CLOUD_DATA_FETCH_IN_PROGRESS then return false end
    if ADMIN_MATERIAL_GRANT_SYNC_IN_FLIGHT then return false end
    if not ADMIN_MATERIAL_GRANT_SYNC_PENDING then return false end
    local myUid = tostring(clientCloud.userId or "")
    if myUid == "" then return false end
    ADMIN_MATERIAL_GRANT_SYNC_IN_FLIGHT = true
    local request = clientCloud:BatchGet()
    request:Key(ADMIN_MATERIAL_GRANTS_KEY)
    request:Key(ADMIN_REBIRTH_STONE_GRANTS_KEY)
    request:Fetch({
        ok = function(values)
            values = values or {}
            local claimed = false
            local materialGrants = values[ADMIN_MATERIAL_GRANTS_KEY]
            if type(materialGrants) == "table" then
                local c, w, p = ClaimAdminMaterialGrants(materialGrants[myUid])
                if c then
                    claimed = true
                    print("[MaterialGrant] 挂起重试领取成功, uid=", myUid, "白色=", w, "粉色=", p)
                end
            end
            local rebirthGrants = values[ADMIN_REBIRTH_STONE_GRANTS_KEY]
            if type(rebirthGrants) == "table" then
                local c, count = ClaimAdminRebirthStoneGrants(rebirthGrants[myUid])
                if c then
                    claimed = true
                    print("[RebirthStoneGrant] 挂起重试领取成功, uid=", myUid, "数量=", count)
                end
            end
            ADMIN_MATERIAL_GRANT_SYNC_IN_FLIGHT = false
            if not claimed then
                ADMIN_MATERIAL_GRANT_SYNC_PENDING = true
            end
        end,
        error = function(code, reason)
            ADMIN_MATERIAL_GRANT_SYNC_IN_FLIGHT = false
            ADMIN_MATERIAL_GRANT_SYNC_PENDING = true
            print("[AdminGrant] 挂起重试直读失败:", tostring(reason))
        end,
        timeout = function()
            ADMIN_MATERIAL_GRANT_SYNC_IN_FLIGHT = false
            ADMIN_MATERIAL_GRANT_SYNC_PENDING = true
            print("[AdminGrant] 挂起重试直读超时")
        end,
    })
    return true
end

function LoadCloudBanlist(onDone)
    CLOUD_BANLIST_LOADED = false
    if not clientCloud then
        cloudSyncLastError = "云组件未初始化 clientCloud=nil"
        cloudSyncStatusText = "云存档组件未初始化，等待重试"
        print("[AdminBan] clientCloud=nil，跳过管理员数据读取")
        if onDone then onDone(false) end
        return
    end
    clientCloud:GetRankList(ADMIN_CLAIM_KEY, 0, 1, {
        ok = function(rankList)
            if not rankList or #rankList == 0 then
                CLOUD_BANLIST = {}
                CLOUD_NICKNAME_OVERRIDES = {}
                CLOUD_SPEED_GRANTS = {}
                CLOUD_MATERIAL_GRANTS = {}
                CLOUD_BANLIST_VERSION = 0
                CLOUD_BANLIST_LOADED = true
                CLOUD_ADMIN_UID = nil
                IS_CLOUD_ADMIN = false
                print("[AdminBan] 无管理员, 云封禁列表为空")
                if onDone then onDone(true, {}, 0) end
                return
            end
            local item = rankList[1]
            CLOUD_ADMIN_UID = item.userId
            local version = (item.iscore and item.iscore[ADMIN_BANLIST_VERSION_KEY]) or 0
            local banlist = (item.score and item.score[ADMIN_BANLIST_KEY]) or {}
            local nicknameOverrides = (item.score and item.score[ADMIN_NICKNAME_OVERRIDES_KEY]) or {}
            local speedGrants = (item.score and item.score[ADMIN_SPEED_GRANTS_KEY]) or {}
            local materialGrants = (item.score and item.score[ADMIN_MATERIAL_GRANTS_KEY]) or {}
            local rebirthStoneGrants = (item.score and item.score[ADMIN_REBIRTH_STONE_GRANTS_KEY]) or {}
            if type(banlist) ~= "table" then banlist = {} end
            if type(nicknameOverrides) ~= "table" then nicknameOverrides = {} end
            if type(speedGrants) ~= "table" then speedGrants = {} end
            if type(materialGrants) ~= "table" then materialGrants = {} end
            if type(rebirthStoneGrants) ~= "table" then rebirthStoneGrants = {} end
            local normalized = {}
            for k, v in pairs(banlist) do
                if k and v then normalized[tostring(k)] = v end
            end
            CLOUD_BANLIST = normalized
            CLOUD_NICKNAME_OVERRIDES = nicknameOverrides
            CLOUD_SPEED_GRANTS = speedGrants
            -- 合并而非覆盖：避免旧云端快照覆盖本会话刚发放的 grant
            CLOUD_MATERIAL_GRANTS = MergeGrantQueues(CLOUD_MATERIAL_GRANTS, materialGrants)
            CLOUD_REBIRTH_STONE_GRANTS = MergeGrantQueues(CLOUD_REBIRTH_STONE_GRANTS, rebirthStoneGrants)
            CLOUD_BANLIST_VERSION = version
            CLOUD_BANLIST_LOADED = true
            local myUid = clientCloud and tostring(clientCloud.userId) or ""
            IS_CLOUD_ADMIN = (tostring(item.userId) == myUid)
            if MergeDailySpeedAdminGrants ~= nil then
                local myGrants = speedGrants[myUid]
                if type(myGrants) == "table" and MergeDailySpeedAdminGrants(myGrants) then
                    print("[SpeedGrant] 已领取管理员定向倍速补偿, uid=", myUid)
                    SaveCloudData(true)
                end
            end
            if ClaimAdminMaterialGrants ~= nil then
                local myMaterialGrants = materialGrants[myUid]
                local claimed, whiteCount, pinkCount = ClaimAdminMaterialGrants(myMaterialGrants)
                if claimed then
                    print("[MaterialGrant] 管理员洗练石奖励领取完成, uid=", myUid,
                        "白色=", whiteCount, "粉色=", pinkCount)
                end
            end
            if ClaimAdminRebirthStoneGrants ~= nil then
                local myRebirthGrants = rebirthStoneGrants[myUid]
                local claimed, count = ClaimAdminRebirthStoneGrants(myRebirthGrants)
                if claimed then
                    print("[RebirthStoneGrant] 管理员转生石奖励领取完成, uid=", myUid, "数量=", count)
                end
            end
            print(string.format("[AdminBan] 加载完成 adminUid=%s isMe=%s version=%d banCount=%d",
                tostring(item.userId), tostring(IS_CLOUD_ADMIN), version, _CountTable(normalized)))
            if RefreshAdminPublicProfileIfNeeded ~= nil then
                RefreshAdminPublicProfileIfNeeded()
            end
            -- 兜底：GetRankList 对 values 键（发放队列）不可靠时，
            -- 直接 BatchGet 自己账号的发放键并领取，保证管理员给自己发也能到账。
            if ClaimAdminGrantsFromOwnAccount ~= nil then
                ClaimAdminGrantsFromOwnAccount()
            end
            if onDone then onDone(true, normalized, version) end
        end,
        error = function(code, reason)
            print("[AdminBan] 拉取失败:", tostring(reason))
            if onDone then onDone(false) end
        end,
        timeout = function()
            print("[AdminBan] 拉取超时")
            if onDone then onDone(false) end
        end,
    }, ADMIN_BANLIST_KEY, ADMIN_BANLIST_VERSION_KEY, ADMIN_NICKNAME_OVERRIDES_KEY,
        ADMIN_SPEED_GRANTS_KEY, ADMIN_MATERIAL_GRANTS_KEY, ADMIN_REBIRTH_STONE_GRANTS_KEY)
end

function SaveCloudBanlist(onDone)
    if not IS_CLOUD_ADMIN or not clientCloud then
        if onDone then onDone(false, "not admin") end
        return
    end
    CLOUD_BANLIST_VERSION = (CLOUD_BANLIST_VERSION or 0) + 1
    clientCloud:BatchSet()
        :SetInt(ADMIN_CLAIM_KEY, 1)
        :SetInt(ADMIN_BANLIST_VERSION_KEY, CLOUD_BANLIST_VERSION)
        :Set(ADMIN_BANLIST_KEY, CLOUD_BANLIST)
        :Set(ADMIN_NICKNAME_OVERRIDES_KEY, CLOUD_NICKNAME_OVERRIDES)
        :Set(ADMIN_SPEED_GRANTS_KEY, CLOUD_SPEED_GRANTS)
        :Set(ADMIN_MATERIAL_GRANTS_KEY, CLOUD_MATERIAL_GRANTS)
        :Set(ADMIN_REBIRTH_STONE_GRANTS_KEY, CLOUD_REBIRTH_STONE_GRANTS)
        :Save("管理员数据", {
            ok = function()
                print("[AdminBan] 保存成功 version=" .. tostring(CLOUD_BANLIST_VERSION) .. " count=" .. tostring(_CountTable(CLOUD_BANLIST)))
                if onDone then onDone(true) end
            end,
            error = function(code, reason)
                print("[AdminBan] 保存失败:", tostring(reason))
                if onDone then onDone(false, reason) end
            end,
            timeout = function()
                print("[AdminBan] 保存超时")
                if onDone then onDone(false, "timeout") end
            end,
        })
end

function ClaimAdmin(onResult)
    if not clientCloud then
        if onResult then onResult(false, "云端不可用") end
        return
    end
    clientCloud:GetRankList(ADMIN_CLAIM_KEY, 0, 1, {
        ok = function(rankList)
            local myUid = tostring(clientCloud.userId)
            if not rankList or #rankList == 0 then
                IS_CLOUD_ADMIN = true
                CLOUD_ADMIN_UID = myUid
                if CLOUD_BANLIST == nil then CLOUD_BANLIST = {} end
                if CLOUD_NICKNAME_OVERRIDES == nil then CLOUD_NICKNAME_OVERRIDES = {} end
                clientCloud:BatchSet()
                    :SetInt(ADMIN_CLAIM_KEY, 1)
                    :SetInt(ADMIN_BANLIST_VERSION_KEY, CLOUD_BANLIST_VERSION or 0)
                    :Set(ADMIN_BANLIST_KEY, CLOUD_BANLIST)
                    :Set(ADMIN_NICKNAME_OVERRIDES_KEY, CLOUD_NICKNAME_OVERRIDES)
                    :Set(ADMIN_SPEED_GRANTS_KEY, CLOUD_SPEED_GRANTS)
                    :Set(ADMIN_MATERIAL_GRANTS_KEY, CLOUD_MATERIAL_GRANTS)
                    :Set(ADMIN_REBIRTH_STONE_GRANTS_KEY, CLOUD_REBIRTH_STONE_GRANTS)
                    :Save("激活管理员", {
                        ok = function()
                            print("[AdminBan] 管理员激活成功, uid=" .. myUid)
                            LoadCloudBanlist(function(loaded)
                                if not loaded then
                                    print("[AdminProfile] 管理员身份复核失败，暂不刷新公开资料")
                                end
                            end)
                            if onResult then onResult(true, "activated") end
                        end,
                        error = function(_, r) if onResult then onResult(false, "激活失败: " .. tostring(r)) end end,
                        timeout = function() if onResult then onResult(false, "激活超时") end end,
                    })
                return
            end
            local existingUid = tostring(rankList[1].userId)
            if existingUid == myUid then
                IS_CLOUD_ADMIN = true
                CLOUD_ADMIN_UID = myUid
                print("[AdminBan] 你已经是管理员")
                if onResult then onResult(true, "already") end
            else
                IS_CLOUD_ADMIN = false
                print("[AdminBan] 管理员已被占据 uid=" .. existingUid)
                if onResult then onResult(false, "管理员位置已被其他人激活") end
            end
        end,
        error = function(_, r)
            if onResult then onResult(false, "查询失败: " .. tostring(r)) end
        end,
    })
end

function AdminBanEntry(entry, reason, onDone)
    if not IS_CLOUD_ADMIN then
        if onDone then onDone(false, "not admin") end
        return
    end
    local uid = entry and entry.userId
    local key = _BanKey(uid)
    if not key then
        if onDone then onDone(false, "invalid uid") end
        return
    end
    CLOUD_BANLIST[key] = {
        nick = entry.nickname or ("玩家" .. key:sub(-4)),
        ts = os.time and os.time() or 0,
        reason = reason or "违规",
        bestFloor = entry.score or 0,
    }
    SaveCloudBanlist(function(ok, err)
        if onDone then onDone(ok, err) end
    end)
end

function AdminUnban(uid, onDone)
    if not IS_CLOUD_ADMIN then
        if onDone then onDone(false, "not admin") end
        return
    end
    local key = _BanKey(uid)
    if not key then return end
    CLOUD_BANLIST[key] = nil
    SaveCloudBanlist(function(ok, err)
        if onDone then onDone(ok, err) end
    end)
end

ADMIN_NICKNAME_SENSITIVE_WORDS = ADMIN_NICKNAME_SENSITIVE_WORDS or {
    "管理员", "admin", "官方", "客服", "GM", "系统", "测试员",
}

function ValidateAdminNickname(name, targetUid)
    name = tostring(name or "")
    if name == "" then return true, "" end
    local length = utf8 and utf8.len and utf8.len(name) or #name
    if not length or length < 2 or length > 16 then
        return false, "昵称长度必须为2～16个字符"
    end
    if name:find("%c") then
        return false, "昵称不能包含特殊控制字符"
    end
    local lowerName = string.lower(name)
    for _, word in ipairs(ADMIN_NICKNAME_SENSITIVE_WORDS) do
        if string.find(lowerName, string.lower(word), 1, true) then
            return false, "昵称包含禁止使用的敏感词"
        end
    end
    for _, entry in ipairs(CURRENT_LEADERBOARD_ENTRIES or {}) do
        if tostring(entry.userId) ~= tostring(targetUid) and tostring(entry.nickname or "") == name then
            return false, "该昵称已被使用"
        end
    end
    for uid, overrideName in pairs(CLOUD_NICKNAME_OVERRIDES or {}) do
        if tostring(uid) ~= tostring(targetUid) and overrideName == name then
            return false, "该昵称已被使用"
        end
    end
    return true, name
end

function AdminGrantSpeedTime(entry, seconds, onDone)
    if not IS_CLOUD_ADMIN then
        if onDone then onDone(false, "没有管理员权限") end
        return
    end
    local uid = entry and _BanKey(entry.userId)
    seconds = math.floor(tonumber(seconds) or 0)
    if not uid or seconds <= 0 or seconds > 4 * 60 * 60 then
        if onDone then onDone(false, "补偿时间无效") end
        return
    end
    CLOUD_SPEED_GRANTS = CLOUD_SPEED_GRANTS or {}
    local playerGrants = CLOUD_SPEED_GRANTS[uid]
    if type(playerGrants) ~= "table" then playerGrants = {} end
    local now = math.floor(os.time and os.time() or 0)
    local grantId = table.concat({
        "speed",
        tostring(uid),
        tostring(now),
        tostring(math.random(100000, 999999)),
    }, "-")
    playerGrants[grantId] = {
        grantId = grantId,
        seconds = seconds,
        dayKey = GetCurrentCstDayKey(),
        createdAt = now,
        issuedBy = tostring(clientCloud and clientCloud.userId or ""),
    }
    CLOUD_SPEED_GRANTS[uid] = playerGrants
    SaveCloudBanlist(function(ok, err)
        if onDone then onDone(ok, err) end
    end)
end

function ClaimAdminRebirthStoneGrants(grants)
    if type(grants) ~= "table" then
        return false, 0
    end
    if not cloudDataReadyForSave or CLOUD_DATA_FETCH_IN_PROGRESS then
        ADMIN_MATERIAL_GRANT_SYNC_PENDING = true
        ADMIN_MATERIAL_GRANT_SYNC_TIMER = 0
        ADMIN_MATERIAL_GRANT_SYNC_IN_FLIGHT = false
        print("[RebirthStoneGrant] 云存档尚未完成同步，延后领取管理员转生石奖励")
        return false, 0
    end
    local changed = false
    local total = 0
    NormalizeAdminRebirthStoneGrantClaims()
    for grantId, grant in pairs(grants) do
        local key = tostring(grantId or "")
        local amount = type(grant) == "table" and math.floor(tonumber(grant.amount) or 0) or 0
        if key ~= "" and playerData.adminRebirthStoneGrantClaims[key] == nil
            and amount >= 1 and amount <= 9999 then
            GrantRebirthStoneToCurrentPlayer(amount, true)
            playerData.adminRebirthStoneGrantClaims[key] = math.max(
                1, math.floor(tonumber(grant.createdAt) or os.time()))
            total = total + amount
            changed = true
            print("[RebirthStoneGrant] 已领取", key, amount)
        end
    end
    if total > 0 then
        RecordAdminGrantNotice({ rebirthStone = total })
    end
    if changed then
        NormalizeAdminRebirthStoneGrantClaims()
        MarkSaveDirty()
        SaveCloudData(true)
    end
    ADMIN_MATERIAL_GRANT_SYNC_PENDING = false
    ADMIN_MATERIAL_GRANT_SYNC_IN_FLIGHT = false
    return changed, total
end

function RequestAdminRebirthStoneGrant(entry, amount, onDone)
    if not IS_CLOUD_ADMIN then
        if onDone then onDone(false, "没有管理员权限", 0) end
        return
    end
    local uid = entry and _BanKey(entry.userId)
    amount = math.floor(tonumber(amount) or 0)
    if not uid or amount < 1 or amount > 9999 then
        if onDone then onDone(false, "数量必须是1～9999的整数", 0) end
        return
    end
    CLOUD_REBIRTH_STONE_GRANTS = CLOUD_REBIRTH_STONE_GRANTS or {}
    local playerGrants = CLOUD_REBIRTH_STONE_GRANTS[uid]
    if type(playerGrants) ~= "table" then playerGrants = {} end
    local now = math.floor(os.time and os.time() or 0)
    local grantId = table.concat({
        "rebirth",
        tostring(uid),
        tostring(now),
        tostring(math.random(100000, 999999)),
    }, "-")
    playerGrants[grantId] = {
        grantId = grantId,
        amount = amount,
        createdAt = now,
        issuedBy = tostring(clientCloud and clientCloud.userId or ""),
    }
    CLOUD_REBIRTH_STONE_GRANTS[uid] = playerGrants
    SaveCloudBanlist(function(ok, err)
        if not ok then playerGrants[grantId] = nil end
        if ok and uid == tostring(clientCloud and clientCloud.userId or "") then
            -- 发给自己的发放：直接用本次发放的 grant 入包并保存，
            -- 不依赖 CLOUD_REBIRTH_STONE_GRANTS 内存（可能被并发 LoadCloudBanlist 覆盖），
            -- 也不依赖云就绪门槛，保证立即到账。
            GrantRebirthStoneToCurrentPlayer(amount, true)
            playerData.adminRebirthStoneGrantClaims = playerData.adminRebirthStoneGrantClaims or {}
            playerData.adminRebirthStoneGrantClaims[grantId] = math.max(1, now)
            MarkSaveDirty()
            SaveCloudData(true)
            print("[RebirthStoneGrant] 自己给自己发放已即时到账, uid=", uid, "数量=", amount)
        end
        if onDone then
            onDone(ok, ok and "已写入发放队列，目标玩家下次同步时到账" or err, 0)
        end
    end)
end

function AdminGrantMaterial(entry, materialId, amount, onDone)
    if not IS_CLOUD_ADMIN then
        if onDone then onDone(false, "没有管理员权限") end
        return
    end
    local uid = entry and _BanKey(entry.userId)
    amount = math.floor(tonumber(amount) or 0)
    local materialName = nil
    if materialId == REFINE_STONE_ITEM_ID then
        materialName = REFINE_STONE_NAME
    elseif materialId == PINK_REFINE_STONE_ITEM_ID then
        materialName = PINK_REFINE_STONE_NAME
    end
    if not uid or materialName == nil or amount < 1 or amount > 9999 then
        if onDone then onDone(false, "材料或数量无效") end
        return
    end
    CLOUD_MATERIAL_GRANTS = CLOUD_MATERIAL_GRANTS or {}
    local playerGrants = CLOUD_MATERIAL_GRANTS[uid]
    if type(playerGrants) ~= "table" then playerGrants = {} end
    local now = math.floor(os.time and os.time() or 0)
    local grantId = table.concat({
        "material",
        tostring(uid),
        tostring(now),
        tostring(math.random(100000, 999999)),
    }, "-")
    playerGrants[grantId] = {
        grantId = grantId,
        materialId = materialId,
        amount = amount,
        createdAt = now,
        issuedBy = tostring(clientCloud and clientCloud.userId or ""),
    }
    CLOUD_MATERIAL_GRANTS[uid] = playerGrants
    SaveCloudBanlist(function(ok, err)
        if not ok then
            playerGrants[grantId] = nil
        end
        if ok and uid == tostring(clientCloud and clientCloud.userId or "") then
            -- 发给自己的发放：直接用本次发放的 grant 入包并保存，
            -- 不依赖 CLOUD_MATERIAL_GRANTS 内存（可能被并发 LoadCloudBanlist 覆盖），
            -- 也不依赖云就绪门槛，保证立即到账。
            GrantMaterialToCurrentPlayer(materialId, amount, true)
            playerData.adminMaterialGrantClaims = playerData.adminMaterialGrantClaims or {}
            playerData.adminMaterialGrantClaims[grantId] = math.max(1, now)
            MarkSaveDirty()
            SaveCloudData(true)
            print("[MaterialGrant] 自己给自己发放已即时到账, uid=", uid,
                "材料=", tostring(materialId), "数量=", amount)
        end
        if onDone then onDone(ok, err, materialName) end
    end)
end

function AdminSetNicknameOverride(entry, name, onDone)
    if not IS_CLOUD_ADMIN then
        if onDone then onDone(false, "没有管理员权限") end
        return
    end
    local uid = entry and _BanKey(entry.userId)
    if not uid then
        if onDone then onDone(false, "无效的玩家") end
        return
    end
    local valid, result = ValidateAdminNickname(name, uid)
    if not valid then
        if onDone then onDone(false, result) end
        return
    end
    if result == "" then
        CLOUD_NICKNAME_OVERRIDES[uid] = nil
    else
        CLOUD_NICKNAME_OVERRIDES[uid] = result
    end
    SaveCloudBanlist(function(ok, err)
        if ok then
            entry.nickname = result ~= "" and result or entry.platformNickname or ("玩家" .. uid:sub(-4))
        end
        if onDone then onDone(ok, err) end
    end)
end

selectedBtn = "出发"
trainingSelectedFloor = trainingSelectedFloor or 1
trainingSelectedMode = trainingSelectedMode == "dummy" and "dummy" or "wave"
trainingSelectedDummyTarget = trainingSelectedDummyTarget == "boss" and "boss" or "normal"
trainingPageMessage = trainingPageMessage or nil

function IsTrainingGroundUnlocked()
    return math.max(0, math.floor(playerData.bestFloor or 0)) >= 11
end

function GetMaxTrainingFloor()
    if not IsTrainingGroundUnlocked() then return 1 end
    local highestClearedFloor = math.max(1, math.floor(playerData.bestFloor or 1) - 1)
    return math.max(10, math.floor(highestClearedFloor / 10) * 10)
end

function NormalizeTrainingFloor(floor)
    local maxFloor = GetMaxTrainingFloor()
    floor = math.max(1, math.floor(floor or 1))
    if floor < 10 then return 1 end
    return math.max(10, math.min(maxFloor, math.floor(floor / 10) * 10))
end

function ChangeTrainingFloor(delta)
    local current = NormalizeTrainingFloor(trainingSelectedFloor)
    local maxFloor = GetMaxTrainingFloor()
    local nextFloor = current + delta
    if current < 10 and delta > 0 then
        nextFloor = 10
    end
    trainingSelectedFloor = NormalizeTrainingFloor(math.max(1, math.min(maxFloor, nextFloor)))
    trainingPageMessage = nil
    ShowTrainingGroundPage()
end

function SelectTrainingMode(mode)
    trainingSelectedMode = mode == "dummy" and "dummy" or "wave"
    trainingPageMessage = nil
    ShowTrainingGroundPage()
end

function SelectTrainingDummyTarget(targetKind)
    trainingSelectedDummyTarget = targetKind == "boss" and "boss" or "normal"
    trainingPageMessage = nil
    ShowTrainingGroundPage()
end

