function FormatPlayTime(seconds)
    seconds = math.max(0, math.floor(seconds or 0))
    local hours = math.floor(seconds / 3600)
    local minutes = math.floor((seconds % 3600) / 60)
    if hours > 0 then
        return tostring(hours) .. "小时" .. tostring(minutes) .. "分"
    end
    return tostring(minutes) .. "分钟"
end

function GetLeaderboardPlayTime(entry)
    if entry == nil then return 0 end
    local profile = entry.profile
    local value = profile and profile.totalPlayTime or entry.playTime or 0
    local version = profile and profile.playTimeClockVersion or entry.playTimeClockVersion or 0
    local corrected = CorrectLegacyPlayTime(value, version, profile and profile.settings or nil)
    if ShouldApplyAdminPublicDisplayBonus(entry) then
        corrected = corrected + ADMIN_PUBLIC_PLAY_TIME_BONUS_SECONDS
    end
    return corrected
end

function CountUnlockedSkillSlots(profile)
    return math.max(CONFIG.SkillSlotBaseCount, math.min(CONFIG.SkillSlotMaxCount, profile and profile.unlockedSkillSlots or CONFIG.SkillSlotBaseCount))
end

LEADERBOARD_DISPLAY_LIMIT = 20
LEADERBOARD_FETCH_LIMIT = 200
LEADERBOARD_SCORE_KEY = OfficialSaveKey("leaderboard_best_floor")
LEADERBOARD_PROFILE_KEY = OfficialSaveKey("public_profile")
LEADERBOARD_BANNED_KEY = OfficialSaveKey("leaderboard_banned")
LEADERBOARD_ENDLESS_SCORE_OFFSET = 1000000

function DecodeLeaderboardProgress(score)
    score = math.max(0, math.floor(tonumber(score) or 0))
    if score >= LEADERBOARD_ENDLESS_SCORE_OFFSET then
        return "endless", score - LEADERBOARD_ENDLESS_SCORE_OFFSET
    end
    return "normal", math.min(CONFIG.NormalFloorCap or 600, score)
end

function FormatLeaderboardProgress(score)
    local mode, floor = DecodeLeaderboardProgress(score)
    return (mode == "endless" and "无尽 第" or "普通 第")
        .. tostring(floor) .. "层"
end

LEADERBOARD_FIRST_WING_REFRESH_INTERVAL = 5 * 60
LEADERBOARD_DEBUG = true
leaderboardFirstWingEligible = leaderboardFirstWingEligible == true
leaderboardFirstWingRefreshTimer = leaderboardFirstWingRefreshTimer or 0
leaderboardFirstWingRefreshInProgress = false
leaderboardFirstWingRefreshGeneration = leaderboardFirstWingRefreshGeneration or 0
leaderboardFirstWingHasSuccessfulQuery = leaderboardFirstWingHasSuccessfulQuery == true
leaderboardFirstWingChampionUserId = leaderboardFirstWingChampionUserId or nil

function IsLeaderboardFirstWingEligible()
    return leaderboardFirstWingEligible == true
end

function ConfirmLeaderboardFirstWingEligibility(isEligible, championUserId)
    local previous = leaderboardFirstWingEligible == true
    leaderboardFirstWingEligible = isEligible == true
    leaderboardFirstWingChampionUserId = championUserId
    leaderboardFirstWingHasSuccessfulQuery = true
    leaderboardFirstWingRefreshTimer = 0
    if previous ~= leaderboardFirstWingEligible then
        print("[RankWing] 榜一白金圣翼资格变更:", leaderboardFirstWingEligible,
            "championUid=", tostring(championUserId))
    end
end

function ConfirmLeaderboardFirstWingFromEntries(entries)
    local first = entries and entries[1] or nil
    local myUid = clientCloud and tostring(clientCloud.userId or "") or ""
    local championUid = first and tostring(first.userId or "") or ""
    ConfirmLeaderboardFirstWingEligibility(
        championUid ~= "" and championUid == myUid,
        championUid ~= "" and championUid or nil
    )
end

function RefreshLeaderboardFirstWingEligibility(force)
    if not clientCloud or leaderboardFirstWingRefreshInProgress then return end
    if not force and leaderboardFirstWingRefreshTimer < LEADERBOARD_FIRST_WING_REFRESH_INTERVAL then
        return
    end

    leaderboardFirstWingRefreshGeneration = leaderboardFirstWingRefreshGeneration + 1
    local requestGeneration = leaderboardFirstWingRefreshGeneration
    leaderboardFirstWingRefreshInProgress = true
    clientCloud:GetRankList(LEADERBOARD_SCORE_KEY, 0, LEADERBOARD_FETCH_LIMIT, {
        ok = function(rankList)
            if requestGeneration ~= leaderboardFirstWingRefreshGeneration then return end
            local candidates = {}
            for _, item in ipairs(rankList or {}) do
                local bestFloor = item.iscore and item.iscore[LEADERBOARD_SCORE_KEY] or nil
                local cloudBanned = item.score and item.score[LEADERBOARD_BANNED_KEY] == true
                if IsValidLeaderboardItem(item)
                    and not IsLeaderboardBanned(item.userId)
                    and not ShouldHideCloudAdminFromOthers(item.userId)
                    and not cloudBanned
                    and bestFloor ~= nil
                    and bestFloor >= 1 then
                    table.insert(candidates, item)
                end
            end

            local function ResolveCandidate(index)
                if requestGeneration ~= leaderboardFirstWingRefreshGeneration then return end
                local item = candidates[index]
                if item == nil then
                    leaderboardFirstWingRefreshInProgress = false
                    leaderboardFirstWingRefreshTimer = 0
                    return
                end

                GetUserNickname({
                    userIds = { item.userId },
                    onSuccess = function(nicknames)
                        if requestGeneration ~= leaderboardFirstWingRefreshGeneration then return end
                        local platformNickname = nil
                        for _, info in ipairs(nicknames or {}) do
                            if tostring(info.userId or "") == tostring(item.userId or "") then
                                platformNickname = info.nickname
                                break
                            end
                        end
                        local overrideName = (CLOUD_NICKNAME_OVERRIDES or {})[tostring(item.userId)]
                        local effectiveName = platformNickname
                        if effectiveName == nil or effectiveName == "" then
                            effectiveName = overrideName
                        end
                        if IsLeaderboardNameBanned(effectiveName) then
                            ResolveCandidate(index + 1)
                            return
                        end

                        leaderboardFirstWingRefreshInProgress = false
                        local myUid = tostring(clientCloud.userId or "")
                        local championUid = tostring(item.userId or "")
                        ConfirmLeaderboardFirstWingEligibility(
                            championUid ~= "" and championUid == myUid,
                            championUid ~= "" and championUid or nil
                        )
                    end,
                    onError = function(errorCode)
                        if requestGeneration ~= leaderboardFirstWingRefreshGeneration then return end
                        leaderboardFirstWingRefreshInProgress = false
                        leaderboardFirstWingRefreshTimer = 0
                        print("[RankWing] 昵称查询失败，保留最近资格:", tostring(errorCode))
                    end,
                })
            end

            ResolveCandidate(1)
        end,
        error = function(code, reason)
            if requestGeneration ~= leaderboardFirstWingRefreshGeneration then return end
            leaderboardFirstWingRefreshInProgress = false
            leaderboardFirstWingRefreshTimer = 0
            print("[RankWing] 排行榜查询失败，保留最近资格:", tostring(reason or code))
        end,
        timeout = function()
            if requestGeneration ~= leaderboardFirstWingRefreshGeneration then return end
            leaderboardFirstWingRefreshInProgress = false
            leaderboardFirstWingRefreshTimer = 0
            print("[RankWing] 排行榜查询超时，保留最近资格")
        end,
    }, LEADERBOARD_BANNED_KEY)
end

function UpdateLeaderboardFirstWingRefresh(dt)
    if appIsInBackground then return end
    leaderboardFirstWingRefreshTimer = math.min(
        LEADERBOARD_FIRST_WING_REFRESH_INTERVAL,
        leaderboardFirstWingRefreshTimer + math.max(0, dt or 0)
    )
    RefreshLeaderboardFirstWingEligibility(false)
end

function IsValidLeaderboardItem(item)
    return item ~= nil
end

function LimitLeaderboardEntries(entries, limit)
    local limited = {}
    limit = limit or LEADERBOARD_DISPLAY_LIMIT
    for _, entry in ipairs(entries or {}) do
        if #limited >= limit then break end
        table.insert(limited, entry)
        entry.rank = #limited
    end
    return limited
end

function NormalizeLeaderboardUid(uid)
    local value = tostring(uid or "")
    local integerPart = value:match("^(.-)%.0+$")
    if integerPart ~= nil and integerPart ~= "" then
        return integerPart
    end
    return value
end

function GetLeaderboardProfileNickname(profile)
    if type(profile) ~= "table" then return "" end
    return tostring(profile.nickname or "")
end

function ApplyLeaderboardNicknameOverrides(entries)
    for _, entry in ipairs(entries or {}) do
        local overrideName = (CLOUD_NICKNAME_OVERRIDES or {})[tostring(entry.userId)]
        if overrideName and overrideName ~= "" then
            entry.nickname = overrideName
        end
    end
end

function ResolvePlayerNicknames(entries, onDone)
    local userIds = {}
    for _, entry in ipairs(entries or {}) do
        local fallbackName = "玩家" .. tostring(entry.userId or ""):sub(-4)
        entry.nickname = entry.nickname or (fallbackName ~= "玩家" and fallbackName or "未知玩家")
        table.insert(userIds, entry.userId)
    end

    if #userIds == 0 then
        ApplyLeaderboardNicknameOverrides(entries)
        if onDone then onDone() end
        return
    end

    GetUserNickname({
        userIds = userIds,
        onSuccess = function(nicknames)
            local map = {}
            for _, info in ipairs(nicknames or {}) do
                local nickname = info.nickname or ""
                map[info.userId] = nickname
                map[tostring(info.userId)] = nickname
            end
            for _, entry in ipairs(entries or {}) do
                local nickname = map[entry.userId] or map[tostring(entry.userId)] or ""
                if nickname ~= "" then
                    entry.platformNickname = nickname
                    entry.nickname = nickname
                end
            end
            ApplyLeaderboardNicknameOverrides(entries)
            if onDone then onDone() end
        end,
        onError = function(errorCode)
            print("[昵称] 查询失败，使用默认名称:", tostring(errorCode))
            ApplyLeaderboardNicknameOverrides(entries)
            if onDone then onDone() end
        end,
    })
end

REWARD_AD_STATS_FETCH_LIMIT = 20
rewardAdStatsPageGeneration = rewardAdStatsPageGeneration or 0
REWARD_AD_NICKNAME_CACHE = REWARD_AD_NICKNAME_CACHE or {}

function GetRewardAdStatsDayKey(daysAgo)
    local cstTimestamp = os.time() + 8 * 60 * 60
        - math.max(0, math.floor(tonumber(daysAgo) or 0)) * 24 * 60 * 60
    local date = os.date("!*t", cstTimestamp)
    return date.year .. "-"
        .. string.format("%02d", date.month) .. "-"
        .. string.format("%02d", date.day)
end

function GetRewardAdStatsPeriodDays(period)
    if period == "30d" then return 30 end
    if period == "7d" then return 7 end
    return 1
end

function GetRewardAdStatsPeriodLabel(period)
    if period == "30d" then return "近30天" end
    if period == "7d" then return "近7天" end
    return "今日"
end

function FetchRewardAdStatsPeriod(period, pageGeneration, onDone)
    local totalDays = GetRewardAdStatsPeriodDays(period)
    local groups = {}
    local dayIndex = 0

    local function IsCurrentRequest()
        return currentScreen == "subpage"
            and currentSubPage == "reward_ad_stats"
            and rewardAdStatsPageGeneration == pageGeneration
    end

    local function ResolveNames(dayGroup, nextDay)
        REWARD_AD_NICKNAME_CACHE = REWARD_AD_NICKNAME_CACHE or {}
        local userIds = {}
        local userIdKeys = {}
        local invalidEntries = {}

        local function GetUserIdKey(userId)
            local key = tostring(userId or "")
            local numericId = tonumber(userId)
            if key == "" or numericId == nil or numericId <= 0
                or numericId ~= math.floor(numericId) then
                return nil
            end
            return key
        end

        local function GetFallbackName(userId)
            local key = tostring(userId or "")
            if key == "" then return "未知玩家" end
            return "玩家" .. key:sub(-4)
        end

        local function ApplyNames(nicknames)
            for _, info in ipairs(nicknames or {}) do
                local uid = GetUserIdKey(info.userId)
                local nickname = tostring(info.nickname or "")
                if uid ~= nil and nickname ~= "" then
                    REWARD_AD_NICKNAME_CACHE[uid] = nickname
                end
            end
        end

        local function FinishNames()
            if not IsCurrentRequest() then return end
            for _, entry in ipairs(dayGroup.entries) do
                local uid = tostring(entry.userId or "")
                local overrideName = tostring((CLOUD_NICKNAME_OVERRIDES or {})[uid] or "")
                local cachedName = tostring(REWARD_AD_NICKNAME_CACHE[uid] or "")
                if overrideName ~= "" then
                    entry.nickname = overrideName
                elseif cachedName ~= "" then
                    entry.nickname = cachedName
                else
                    entry.nickname = GetFallbackName(entry.userId)
                end
                print("[RewardAdStats] 昵称映射:", uid, "->", entry.nickname)
            end
            nextDay()
        end

        for _, entry in ipairs(dayGroup.entries) do
            local uid = GetUserIdKey(entry.userId)
            if uid == nil then
                table.insert(invalidEntries, entry)
            elseif userIdKeys[uid] == nil then
                userIdKeys[uid] = true
                table.insert(userIds, entry.userId)
            end
        end

        for _, entry in ipairs(invalidEntries) do
            entry.nickname = GetFallbackName(entry.userId)
            print("[RewardAdStats] 无效 UID，使用默认名称:", tostring(entry.userId))
        end

        if #userIds == 0 then
            FinishNames()
            return
        end

        local function ResolveFallback(fallbackIds, index)
            if not IsCurrentRequest() then return end
            if index > #fallbackIds then
                FinishNames()
                return
            end

            local requestedId = fallbackIds[index]
            local requestFinished = false
            local function FinishRequest()
                if requestFinished then return end
                requestFinished = true
                ResolveFallback(fallbackIds, index + 1)
            end

            GetUserNickname {
                userIds = { requestedId },
                onSuccess = function(nicknames)
                    ApplyNames(nicknames)
                    FinishRequest()
                end,
                onError = function(errorCode)
                    print("[RewardAdStats] 单 UID 昵称查询失败:",
                        tostring(requestedId), tostring(errorCode))
                    FinishRequest()
                end,
            }
        end

        local batchFinished = false
        local function FinishBatch(nicknames, errorCode)
            if batchFinished then return end
            batchFinished = true
            if errorCode ~= nil then
                print("[RewardAdStats] 批量昵称查询失败，降级单 UID:",
                    tostring(errorCode), "UID数量:", #userIds)
                ResolveFallback(userIds, 1)
                return
            end

            ApplyNames(nicknames)
            local missingIds = {}
            local returnedIds = {}
            for _, info in ipairs(nicknames or {}) do
                local uid = GetUserIdKey(info.userId)
                if uid ~= nil then returnedIds[uid] = true end
            end
            for _, requestedId in ipairs(userIds) do
                local uid = GetUserIdKey(requestedId)
                if uid ~= nil and not returnedIds[uid]
                    and REWARD_AD_NICKNAME_CACHE[uid] == nil then
                    table.insert(missingIds, requestedId)
                end
            end
            if #missingIds > 0 then
                print("[RewardAdStats] 批量结果缺少 UID，降级单 UID:", #missingIds)
                ResolveFallback(missingIds, 1)
            else
                FinishNames()
            end
        end

        print("[RewardAdStats] 查询昵称 UID 数量:", #userIds)
        GetUserNickname {
            userIds = userIds,
            onSuccess = function(nicknames)
                FinishBatch(nicknames)
            end,
            onError = function(errorCode)
                FinishBatch(nil, errorCode)
            end,
        }
    end

    local function FetchNextDay()
        if not IsCurrentRequest() then return end
        dayIndex = dayIndex + 1
        if dayIndex > totalDays then
            if onDone then onDone(AggregateRewardAdStatsGroups(period, groups)) end
            return
        end

        local dayKey = GetRewardAdStatsDayKey(dayIndex - 1)
        local scoreKey = GetRewardAdDailyLeaderboardScoreKey(dayKey)
        local dayGroup = { dayKey = dayKey, entries = {} }
        table.insert(groups, dayGroup)
        if scoreKey == nil then
            dayGroup.error = "日期键无效"
            FetchNextDay()
            return
        end

        clientCloud:GetRankList(scoreKey, 0, REWARD_AD_STATS_FETCH_LIMIT, {
            ok = function(rankList)
                if not IsCurrentRequest() then return end
                for _, item in ipairs(rankList or {}) do
                    local count = item.iscore and item.iscore[scoreKey] or 0
                    if item.userId ~= nil
                        and math.floor(tonumber(count) or 0) > 0 then
                        table.insert(dayGroup.entries, {
                            userId = item.userId,
                            count = math.max(0, math.floor(tonumber(count) or 0)),
                            rank = #dayGroup.entries + 1,
                        })
                    end
                end
                ResolvePlayerNicknames(dayGroup.entries, FetchNextDay)
            end,
            error = function(code, reason)
                if not IsCurrentRequest() then return end
                dayGroup.error = tostring(reason or code or "读取失败")
                print("[RewardAdStats] 读取失败:", dayKey, dayGroup.error)
                FetchNextDay()
            end,
            timeout = function()
                if not IsCurrentRequest() then return end
                dayGroup.error = "读取超时"
                print("[RewardAdStats] 读取超时:", dayKey)
                FetchNextDay()
            end,
        })
    end

    FetchNextDay()
end

function AggregateRewardAdStatsGroups(period, groups)
    if period == "1d" then return groups end

    local mergedByUserId = {}
    local firstOrder = 0
    local errorCount = 0
    for _, group in ipairs(groups or {}) do
        if group.error then errorCount = errorCount + 1 end
        for _, entry in ipairs(group.entries or {}) do
            local userIdKey = tostring(entry.userId or "")
            local merged = mergedByUserId[userIdKey]
            if merged == nil then
                firstOrder = firstOrder + 1
                merged = {
                    userId = entry.userId,
                    count = 0,
                    nickname = entry.nickname,
                    firstOrder = firstOrder,
                }
                mergedByUserId[userIdKey] = merged
            end
            merged.count = merged.count + math.max(0, math.floor(tonumber(entry.count) or 0))
            if (merged.nickname == nil or merged.nickname == "")
                and entry.nickname ~= nil and entry.nickname ~= "" then
                merged.nickname = entry.nickname
            end
        end
    end

    local mergedEntries = {}
    for _, entry in pairs(mergedByUserId) do
        table.insert(mergedEntries, entry)
    end
    table.sort(mergedEntries, function(a, b)
        if a.count ~= b.count then return a.count > b.count end
        return a.firstOrder < b.firstOrder
    end)

    local entries = {}
    for rank, entry in ipairs(mergedEntries) do
        entry.rank = rank
        entry.firstOrder = nil
        table.insert(entries, entry)
    end

    return {
        {
            dayKey = GetRewardAdStatsPeriodLabel(period) .. "合计",
            entries = entries,
            isPeriodAggregate = true,
            error = #entries == 0 and errorCount > 0
                and "周期数据读取失败" or nil,
        },
    }
end

