DAILY_OPS_FETCH_LIMIT = 100
dailyOpsPageGeneration = dailyOpsPageGeneration or 0

function GetDailyOpsPeriodDays(period)
    if period == "30d" then return 30 end
    if period == "7d" then return 7 end
    return 1
end

-- 抓取某一天的运营数据：新增玩家、活跃玩家（GetRankTotal 去重人数）与广告总次数（分页求和）。
function FetchDailyOpsDay(dayKey, day, onDone)
    local newKey = GetDailyNewLeaderboardScoreKey(dayKey)
    local activeKey = GetDailyActiveLeaderboardScoreKey(dayKey)
    local adKey = GetRewardAdDailyLeaderboardScoreKey(dayKey)

    local pending = 0
    local function Done()
        pending = pending - 1
        if pending == 0 and onDone then onDone() end
    end

    if newKey then
        pending = pending + 1
        clientCloud:GetRankTotal(newKey, {
            ok = function(total)
                day.newCount = math.max(0, math.floor(tonumber(total) or 0))
                Done()
            end,
            error = function() Done() end,
            timeout = function() Done() end,
        })
    end

    if activeKey then
        pending = pending + 1
        clientCloud:GetRankTotal(activeKey, {
            ok = function(total)
                day.activeCount = math.max(0, math.floor(tonumber(total) or 0))
                Done()
            end,
            error = function() Done() end,
            timeout = function() Done() end,
        })
    end

    if adKey then
        pending = pending + 1
        local adSum = 0
        local start = 0
        local function FetchAdPage()
            clientCloud:GetRankList(adKey, start, DAILY_OPS_FETCH_LIMIT, {
                ok = function(rankList)
                    local entries = rankList or {}
                    for _, item in ipairs(entries) do
                        adSum = adSum + math.max(0, math.floor(
                            tonumber((item.iscore and item.iscore[adKey]) or 0)))
                    end
                    if #entries < DAILY_OPS_FETCH_LIMIT then
                        day.adTotal = adSum
                        Done()
                    else
                        start = start + #entries
                        FetchAdPage()
                    end
                end,
                error = function(code, reason)
                    day.error = day.error or ("广告读取失败:" .. tostring(reason or code))
                    Done()
                end,
                timeout = function()
                    day.error = day.error or "广告读取超时"
                    Done()
                end,
            })
        end
        FetchAdPage()
    end

    if pending == 0 and onDone then onDone() end
end

function FetchDailyOpsPeriod(period, pageGeneration, onDone)
    local totalDays = GetDailyOpsPeriodDays(period)
    local days = {}
    local dayIndex = 0

    local function IsCurrentRequest()
        return currentScreen == "subpage"
            and currentSubPage == "daily_ops_stats"
            and dailyOpsPageGeneration == pageGeneration
    end

    local function FetchNextDay()
        if not IsCurrentRequest() then return end
        dayIndex = dayIndex + 1
        if dayIndex > totalDays then
            if onDone then onDone(days) end
            return
        end
        local dayKey = GetRewardAdStatsDayKey(dayIndex - 1)
        local day = { dayKey = dayKey, newCount = 0, activeCount = 0, adTotal = 0, error = nil }
        table.insert(days, day)
        FetchDailyOpsDay(dayKey, day, FetchNextDay)
    end

    FetchNextDay()
end

