-- 玩家打开排行榜时，若本会话有管理员发放已到账（含本次打开触发的补领），
-- 弹窗告知"领取成功 + 具体到账内容"；每次展示后清空提示缓冲。
function TryShowAdminGrantNoticePopup()
    local notice = ADMIN_GRANT_NOTICE_PENDING
    if type(notice) ~= "table" then return end
    local rowList = {}
    if (notice.whiteRefine or 0) > 0 then
        table.insert(rowList, { text = REFINE_STONE_NAME .. "  +" .. tostring(notice.whiteRefine), color = { 255, 218, 170, 255 } })
    end
    if (notice.pinkRefine or 0) > 0 then
        table.insert(rowList, { text = PINK_REFINE_STONE_NAME .. "  +" .. tostring(notice.pinkRefine), color = { 255, 158, 224, 255 } })
    end
    if (notice.rebirthStone or 0) > 0 then
        table.insert(rowList, { text = "转生石  +" .. tostring(notice.rebirthStone), color = { 176, 140, 255, 255 } })
    end
    if (notice.speedSeconds or 0) > 0 then
        table.insert(rowList, { text = "今日倍速额度  +" .. tostring(notice.speedSeconds) .. "秒", color = { 118, 226, 255, 255 } })
    end
    if #rowList == 0 then return end
    ADMIN_GRANT_NOTICE_PENDING = nil
    local summaryParts = {}
    for _, row in ipairs(rowList) do table.insert(summaryParts, row.text) end
    print("[AdminGrant] 排行榜打开，弹窗提示到账:", table.concat(summaryParts, "，"))
    local childList = {
        UI.Label {
            text = "管理员发放的奖励已领取成功：",
            fontSize = 10,
            fontColor = PX.textWhite,
            textAlign = "center",
            whiteSpace = "normal",
        },
    }
    for _, row in ipairs(rowList) do
        table.insert(childList, UI.Label {
            text = row.text,
            fontSize = 11,
            fontColor = row.color,
            fontWeight = "bold",
            textAlign = "center",
            textStroke = { width = 1, color = { 10, 7, 18, 220 } },
        })
    end
    local modal = UI.Modal {
        title = "领取成功",
        size = "sm",
        isOpen = false,
        closeOnOverlay = true,
        closeOnEscape = true,
        showCloseButton = true,
        contentPadding = 12,
        contentGap = 7,
        backgroundColor = { 24, 21, 32, 255 },
        borderWidth = 2,
        borderColor = PX.goldDim,
        onClose = function(self)
            self:Destroy()
        end,
        children = childList,
    }
    modal:Open()
end

function ShowLeaderboardPage()
    currentScreen = "subpage"
    currentSubPage = "leaderboard"
    leaderboardPageGeneration = (leaderboardPageGeneration or 0) + 1
    local pageGeneration = leaderboardPageGeneration
    UpdateScreenMetrics()

    local loadingContent = {
        UI.Panel {
            width = "100%",
            minHeight = 108,
            padding = 14,
            gap = 7,
            justifyContent = "center",
            alignItems = "center",
            backgroundColor = { 18, 18, 36, 244 },
            borderWidth = { 1, 1, 3, 1 },
            borderColor = PX.goldDim,
            children = {
                UI.Label { text = "排行数据同步中", fontSize = uiValueSize, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center", textStroke = { width = 1, color = { 10, 7, 18, 220 } } },
                UI.Panel { width = "64%", height = 3, backgroundColor = PX.red, borderWidth = 1, borderColor = PX.redBright },
                UI.Label { text = "正在读取云端最高层记录...", fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
            },
        },
    }
    UI.SetRoot(BuildSubPage("排行榜", loadingContent), true)

    LoadCloudBanlist(function(ok)
        if currentScreen ~= "subpage"
            or currentSubPage ~= "leaderboard"
            or leaderboardPageGeneration ~= pageGeneration then return end
        if not ok then
            print("[排行榜] 管理员云数据加载失败，继续读取排行榜，使用默认封禁和昵称数据")
        end
        _FetchLeaderboardBestFloor(pageGeneration)
    end)
end

function _FetchLeaderboardBestFloor(pageGeneration)
    pageGeneration = pageGeneration or leaderboardPageGeneration
    if currentScreen ~= "subpage"
        or currentSubPage ~= "leaderboard"
        or leaderboardPageGeneration ~= pageGeneration then
        return
    end
    clientCloud:GetRankList(LEADERBOARD_SCORE_KEY, 0, LEADERBOARD_FETCH_LIMIT, {
        ok = function(rankList)
            if LEADERBOARD_DEBUG then
                print("[LB-DBG] 云端返回条数:", #rankList, " myUserId:", tostring(clientCloud and clientCloud.userId))
                for i = 1, math.min(#rankList, 15) do
                    local it = rankList[i]
                    print(string.format("[LB-DBG] #%d uid=%s best_floor=%s banned=%s",
                        i, tostring(it.userId),
                        tostring(it.iscore and it.iscore[LEADERBOARD_SCORE_KEY]),
                        tostring(it.score and it.score[LEADERBOARD_BANNED_KEY])))
                end
            end
            if #rankList == 0 then
                local emptyContent = {
                    UI.Panel {
                        width = "100%",
                        minHeight = 108,
                        padding = 14,
                        justifyContent = "center",
                        alignItems = "center",
                        gap = 7,
                        backgroundColor = { 22, 20, 37, 244 },
                        borderWidth = { 1, 1, 3, 1 },
                        borderColor = PX.goldDim,
                        children = {
                            UI.Label { text = "排行榜尚未开榜", fontSize = uiValueSize, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
                            UI.Label { text = "完成一局并刷新最高层记录", fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
                        },
                    },
                }
                if currentScreen == "subpage"
                    and currentSubPage == "leaderboard"
                    and leaderboardPageGeneration == pageGeneration then
                    UI.SetRoot(BuildSubPage("排行榜", emptyContent), true)
                    TryShowAdminGrantNoticePopup()
                end
                return
            end

            local entries = {}
            local userIds = {}
            local nicknameUserIds = {}
            local rawNicknameUserIds = {}
            local dbgInvalidDrop, dbgBanDrop, dbgCloudBanDrop, dbgSelfFound = 0, 0, 0, 0
            local myUid = tostring(clientCloud and clientCloud.userId or "")
            for _, item in ipairs(rankList) do
                local itemUid = tostring(item.userId or "")
                local itemOk = IsValidLeaderboardItem(item)
                local uidBanned = IsLeaderboardBanned(itemUid)
                local cloudBanned = (item.score and item.score[LEADERBOARD_BANNED_KEY] == true)
                if LEADERBOARD_DEBUG and itemUid == myUid then
                    dbgSelfFound = dbgSelfFound + 1
                    print(string.format("[LB-DBG] 自己条目状态: rankList中存在 itemOk=%s uidBanned=%s cloudBanned=%s best_floor=%s",
                        tostring(itemOk), tostring(uidBanned), tostring(cloudBanned),
                        tostring(item.iscore and item.iscore[LEADERBOARD_SCORE_KEY])))
                elseif itemUid == myUid then
                    dbgSelfFound = dbgSelfFound + 1
                end
                if not itemOk then dbgInvalidDrop = dbgInvalidDrop + 1
                elseif uidBanned then dbgBanDrop = dbgBanDrop + 1
                elseif cloudBanned then dbgCloudBanDrop = dbgCloudBanDrop + 1
                end
                local bestFloor = item.iscore and item.iscore[LEADERBOARD_SCORE_KEY] or nil
                local hasProgress = (bestFloor ~= nil) and (bestFloor >= 1)
                if itemOk and not uidBanned and not cloudBanned
                    and not ShouldHideCloudAdminFromOthers(itemUid)
                    and hasProgress then
                    table.insert(entries, {
                        rank = #entries + 1,
                        userId = itemUid,
                        score = bestFloor,
                        profile = item.score and item.score[LEADERBOARD_PROFILE_KEY] or nil,
                        playTime = item.iscore[OfficialSaveKey("total_play_time")] or 0,
                        playTimeClockVersion = item.iscore[OfficialSaveKey("play_time_clock_version")] or 0,
                        gold = item.iscore[OfficialSaveKey("gold")] or 0,
                        totalGoldEarned = item.iscore[OfficialSaveKey("total_gold_earned")]
                            or item.iscore[OfficialSaveKey("gold")] or 0,
                        rebirthUpgradeCount = item.iscore[OfficialSaveKey("rebirth_upgrade_count")] or 0,
                        unlockedSkillSlots = item.iscore[OfficialSaveKey("unlocked_skill_slots")] or CONFIG.SkillSlotBaseCount,
                        nickname = GetLeaderboardProfileNickname(
                            item.score and item.score[LEADERBOARD_PROFILE_KEY] or nil
                        ),
                        isMe = (itemUid == myUid),
                    })
                    table.insert(userIds, itemUid)
                    table.insert(nicknameUserIds, itemUid)
                    table.insert(rawNicknameUserIds, item.userId)
                end
            end
            if LEADERBOARD_DEBUG then
                print(string.format("[LB-DBG] 过滤统计: 总返回=%d 通过=%d 无效条目=%d userId封禁=%d 云端封禁=%d 自己是否在rankList=%s 自己是否通过=%s",
                    #rankList, #entries, dbgInvalidDrop, dbgBanDrop, dbgCloudBanDrop,
                    tostring(dbgSelfFound > 0),
                    tostring((function() for _, e in ipairs(entries) do if e.userId == myUid then return true end end return false end)())))
            end

            if #entries == 0 then
                CURRENT_LEADERBOARD_ENTRIES = {}
                CURRENT_LEADERBOARD_ALL_ENTRIES = {}
                leaderboardDisplayPage = 1
                RenderLeaderboard(entries)
                return
            end

            local function ApplyLeaderboardNicknames(nicknames, sourceLabel)
                local map = {}
                local returnedCount = 0
                local firstInfo = nil
                for _, info in ipairs(nicknames or {}) do
                    if firstInfo == nil then firstInfo = info end
                    local nickname = tostring(info.nickname or info.name or info.userName or "")
                    local uid = NormalizeLeaderboardUid(info.userId or info.user_id or info.uid)
                    if uid ~= "" then
                        map[uid] = nickname
                        returnedCount = returnedCount + 1
                    end
                end
                print("[LeaderboardNickname] 来源=", sourceLabel or "primary",
                    "请求数量=", #nicknameUserIds, "返回有效数量=", returnedCount)
                LEADERBOARD_NICKNAME_REQUEST_COUNT = #nicknameUserIds
                LEADERBOARD_NICKNAME_RETURN_COUNT = returnedCount
                LEADERBOARD_NICKNAME_MATCH_COUNT = 0
                LEADERBOARD_NICKNAME_ERROR = "无"
                LEADERBOARD_NICKNAME_FIRST_RANK_UID = tostring(entries[1] and entries[1].userId or "")
                LEADERBOARD_NICKNAME_FIRST_RETURN_UID = NormalizeLeaderboardUid(firstInfo and (firstInfo.userId or firstInfo.user_id or firstInfo.uid) or "")
                LEADERBOARD_NICKNAME_FIRST_RETURN_NAME = tostring(firstInfo and (firstInfo.nickname or firstInfo.name or firstInfo.userName) or "")
                for _, entry in ipairs(entries) do
                    local nickname = map[NormalizeLeaderboardUid(entry.userId)] or ""
                    if nickname ~= "" then
                        LEADERBOARD_NICKNAME_MATCH_COUNT = LEADERBOARD_NICKNAME_MATCH_COUNT + 1
                        entry.platformNickname = nickname
                        entry.nickname = nickname
                    end
                    if entry.nickname == nil or entry.nickname == "" then
                        entry.nickname = GetLeaderboardProfileNickname(entry.profile)
                    end
                    if entry.nickname == nil or entry.nickname == "" then
                        entry.nickname = "玩家" .. tostring(entry.userId):sub(-4)
                    end
                end
                ApplyLeaderboardNicknameOverrides(entries)
                -- 记录“排行榜中我的最终展示名”（覆写已应用、封禁过滤前），
                -- 让设置页能显示与排行榜页完全一致的名字
                for _, myNameEntry in ipairs(entries) do
                    if myNameEntry.isMe and myNameEntry.nickname ~= nil and myNameEntry.nickname ~= "" then
                        MY_LEADERBOARD_NAME = myNameEntry.nickname
                        MY_LEADERBOARD_NAME_UPDATED_AT = os.time()
                        break
                    end
                end
                entries = FilterLeaderboardBannedEntries(entries)
                -- 缓存过滤后的完整名单（第1页仅取前20展示，完整名单供第2页展示第21~40名）
                CURRENT_LEADERBOARD_ALL_ENTRIES = entries
                leaderboardDisplayPage = 1
                entries = LimitLeaderboardEntries(entries, LEADERBOARD_DISPLAY_LIMIT)
                CURRENT_LEADERBOARD_ENTRIES = entries
                RenderLeaderboard(entries, pageGeneration)
                return returnedCount
            end

            GetUserNickname({
                userIds = nicknameUserIds,
                onSuccess = function(nicknames)
                    local returnedCount = ApplyLeaderboardNicknames(nicknames, "标准化UID")
                    if returnedCount == 0 then
                        print("[LeaderboardNickname] 标准化UID未返回昵称，使用原始UID重试")
                        GetUserNickname({
                            userIds = rawNicknameUserIds,
                            onSuccess = function(rawNicknames)
                                ApplyLeaderboardNicknames(rawNicknames, "原始UID重试")
                            end,
                            onError = function(rawErrorCode)
                                LEADERBOARD_NICKNAME_ERROR = tostring(rawErrorCode)
                            print("[LeaderboardNickname] 原始UID重试失败 code=", tostring(rawErrorCode))
                            end,
                        })
                    end
                end,
                onError = function(errorCode)
                    LEADERBOARD_NICKNAME_ERROR = tostring(errorCode)
                    print("[LeaderboardNickname] 批量昵称查询失败 code=", tostring(errorCode),
                        "请求数量=", #nicknameUserIds)
                    GetUserNickname({
                        userIds = rawNicknameUserIds,
                        onSuccess = function(rawNicknames)
                            ApplyLeaderboardNicknames(rawNicknames, "原始UID重试")
                        end,
                        onError = function(rawErrorCode)
                            print("[LeaderboardNickname] 原始UID重试失败 code=", tostring(rawErrorCode))
                            ApplyLeaderboardNicknames({}, "全部查询失败")
                        end,
                    })
                end
            })
        end,
        error = function(code, reason)
            print("[排行榜] 加载失败:", reason)
            local errContent = {
                UI.Panel {
                    width = "100%",
                    minHeight = 92,
                    padding = 12,
                    gap = 6,
                    justifyContent = "center",
                    alignItems = "center",
                    backgroundColor = { 48, 20, 28, 238 },
                    borderWidth = { 1, 1, 3, 1 },
                    borderColor = PX.redBright,
                    children = {
                        UI.Label { text = "排行榜读取失败", fontSize = uiValueSize, fontColor = PX.redBright, fontWeight = "bold", textAlign = "center" },
                        UI.Label { text = "请稍后返回重试", fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
                    },
                },
            }
            if currentScreen == "subpage"
                and currentSubPage == "leaderboard"
                and leaderboardPageGeneration == pageGeneration then
                UI.SetRoot(BuildSubPage("排行榜", errContent), true)
                TryShowAdminGrantNoticePopup()
            end
        end,
        timeout = function()
            print("[排行榜] 加载超时")
            if currentScreen == "subpage"
                and currentSubPage == "leaderboard"
                and leaderboardPageGeneration == pageGeneration then
                UI.SetRoot(BuildSubPage("排行榜", {
                    UI.Panel {
                        width = "100%", minHeight = 92, padding = 12, gap = 6,
                        justifyContent = "center", alignItems = "center",
                        backgroundColor = { 48, 20, 28, 238 },
                        borderWidth = { 1, 1, 3, 1 }, borderColor = PX.redBright,
                        children = {
                            UI.Label { text = "排行榜读取超时", fontSize = uiValueSize, fontColor = PX.redBright, fontWeight = "bold", textAlign = "center" },
                            UI.Label { text = "请稍后返回重试", fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
                        },
                    },
                }), true)
                TryShowAdminGrantNoticePopup()
            end
        end
    }, LEADERBOARD_PROFILE_KEY, LEADERBOARD_BANNED_KEY,
        OfficialSaveKey("total_play_time"), OfficialSaveKey("play_time_clock_version"),
        OfficialSaveKey("gold"), OfficialSaveKey("total_gold_earned"),
        OfficialSaveKey("rebirth_upgrade_count"), OfficialSaveKey("unlocked_skill_slots"))
end

function ShowLeaderboardProfile(entry)
    currentScreen = "subpage"
    UpdateScreenMetrics()
    local profile = entry and entry.profile or nil
    local content = {}
    local function FormatLeaderboardCloneLevels(profileData)
        local levels = profileData and profileData.cloneUpgradeLevels or {}
        if type(levels) ~= "table" then
            levels = { profileData and profileData.cloneUpgradeLevel or 0, 0, 0 }
        end
        local cloneCount = profileData and profileData.cloneCount
        if cloneCount == nil and profileData and profileData.cloneUpgradeLevel ~= nil then
            cloneCount = 1
        end
        cloneCount = math.max(0, math.floor(cloneCount or 0))
        local parts = {}
        for index = 1, 3 do
            if index <= cloneCount then
                table.insert(parts, "Lv." .. tostring(math.max(0, math.floor(levels[index] or 0))))
            else
                table.insert(parts, "未解锁")
            end
        end
        return table.concat(parts, " / ")
    end
    local profileQualityColors = {
        blue = { 83, 164, 255, 255 },
        purple = { 181, 102, 255, 255 },
        orange = { 255, 160, 55, 255 },
        red = { 255, 76, 82, 255 },
        colorful = { 255, 102, 224, 255 },
        none = { 82, 82, 102, 180 },
    }
    local profileQualityLabels = {
        blue = "蓝",
        purple = "紫",
        orange = "橙",
        red = "红",
        colorful = "彩",
        none = "空",
    }
    local function MakeProfileMetric(label, value, accentColor)
