                    UI.Label { text = "基础公开档案", fontSize = 9, fontColor = PX.textGray, fontWeight = "bold", backgroundColor = { 12, 11, 24, 220 }, borderWidth = 1, borderColor = PX.goldDim, paddingHorizontal = 7, paddingVertical = 2 },
