            end
        end
        if #setTagPanels > 0 then
            table.insert(content, UI.Panel {
                width = "100%",
                flexDirection = "row",
                flexWrap = "wrap",
                justifyContent = "center",
                alignItems = "center",
                gap = 6,
                paddingHorizontal = 8,
                paddingVertical = 4,
                backgroundColor = { 13, 12, 24, 210 },
                borderWidth = { 1, 1, 2, 1 },
                borderColor = PX.goldDim,
                children = setTagPanels,
            })
        end
        for _, item in ipairs(profile.equipment or {}) do
            local quality = item.quality or "none"
            local qualityColor = profileQualityColors[quality] or PX.goldDim
            local qualityLabel = profileQualityLabels[quality] or "装"
            local hasEquipment = item.floor and item.floor > 0
            local itemSetDef = item.resonanceSetId ~= nil and (EQUIPMENT_RESONANCE_DEFS or {})[item.resonanceSetId] or nil
            local equipmentChildren = {
                UI.Panel {
                    width = "100%",
                    flexDirection = "row",
                    alignItems = "center",
                    gap = 8,
                    children = {
                        UI.Label {
                            text = qualityLabel,
                            width = 28,
                            height = 28,
                            fontSize = uiLabelSize,
                            fontColor = hasEquipment and PX.textWhite or PX.textGray,
                            fontWeight = "bold",
                            textAlign = "center",
                            backgroundColor = hasEquipment and { math.floor(qualityColor[1] * 0.35), math.floor(qualityColor[2] * 0.35), math.floor(qualityColor[3] * 0.35), 255 } or { 29, 29, 39, 230 },
                            borderWidth = 2,
                            borderColor = qualityColor,
                        },
                        UI.Panel {
                            flexGrow = 1,
                            flexShrink = 1,
                            gap = 2,
                            children = {
                                UI.Label { text = item.slotLabel or item.slot or "装备", fontSize = 8, fontColor = PX.textGray, fontWeight = "bold" },
                                UI.Label { text = item.name or "未装备", fontSize = uiLabelSize, fontColor = hasEquipment and qualityColor or PX.textGray, fontWeight = "bold", maxLines = 1, flexShrink = 1, textStroke = hasEquipment and { width = 1, color = { 7, 6, 14, 220 } } or nil },
                            },
                        },
                        UI.Label {
                            text = hasEquipment and ("评分 " .. tostring(item.score or 0)) or "空槽位",
                            fontSize = 9,
                            fontColor = hasEquipment and PX.textGold or PX.textGray,
                            fontWeight = "bold",
                            flexShrink = 0,
                        },
                    },
                },
                hasEquipment and itemSetDef ~= nil and UI.Label {
                    text = "套装 · " .. itemSetDef.name,
                    fontSize = 9,
                    fontColor = itemSetDef.color,
                    fontWeight = "bold",
                } or UI.Panel { width = 0, height = 0 },
                hasEquipment and UI.Label { text = "获取层数  第" .. item.floor .. "层", fontSize = 9, fontColor = PX.textGray } or UI.Panel { width = 0, height = 0 },
                hasEquipment and UI.Label { text = item.baseAffix or "", fontSize = 10, fontColor = PX.textGold, fontWeight = "bold", whiteSpace = "normal" } or UI.Panel { width = 0, height = 0 },
            }
            if item.upgradeLevel ~= nil then
                table.insert(equipmentChildren, UI.Label { text = "强化等级  Lv." .. tostring(item.upgradeLevel), fontSize = 9, fontColor = qualityColor, fontWeight = "bold" })
            end
            for _, affixText in ipairs(item.affixes or {}) do
                table.insert(equipmentChildren, UI.Label { text = "· " .. affixText, fontSize = 9, fontColor = PX.textGray, whiteSpace = "normal" })
            end
            table.insert(content, UI.Panel {
                width = "100%",
                padding = 8,
                gap = 4,
                backgroundColor = hasEquipment and { 17, 16, 31, 242 } or { 22, 22, 30, 205 },
                borderWidth = hasEquipment and { 1, 1, 3, 4 } or { 1, 1, 2, 3 },
                borderColor = qualityColor,
                children = equipmentChildren,
            })
        end
    end
    UI.SetRoot(BuildSubPage("玩家详情", content, function()
        -- 从排行榜进入的详情页，点返回应回到排行榜（保留当前分页）而非主菜单
        if currentScreen ~= "subpage" or currentSubPage ~= "leaderboard" then
            -- 确保回到排行榜子页状态
            currentScreen = "subpage"
            currentSubPage = "leaderboard"
        end
        if CURRENT_LEADERBOARD_ENTRIES and #CURRENT_LEADERBOARD_ENTRIES > 0 then
            RenderLeaderboard(CURRENT_LEADERBOARD_ENTRIES, leaderboardPageGeneration)
        else
            ShowLeaderboardPage()
        end
    end), true)
end

function ShowAdminSpeedGrantConfirmPage(entry, seconds)
    if not IS_CLOUD_ADMIN or not entry then return end
    currentScreen = "subpage"
    local hoursText = seconds % 3600 == 0
        and (tostring(seconds / 3600) .. " 小时")
        or (tostring(seconds / 60) .. " 分钟")
    local content = {
        UI.Panel {
            width = "100%", padding = 14, gap = 10, alignItems = "center",
            backgroundColor = { 20, 38, 28, 240 }, borderWidth = 1,
            borderColor = { 80, 180, 100, 255 },
            children = {
                UI.Label { text = "确认发放倍速补偿", fontSize = 17, fontColor = { 110, 220, 130, 255 }, fontWeight = "bold", textAlign = "center" },
                UI.Label { text = "目标: " .. tostring(entry.platformNickname or entry.nickname or "玩家"), fontSize = 12, fontColor = PX.textGold, textAlign = "center" },
                UI.Label { text = "完整 UID: " .. tostring(entry.userId), fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
                UI.Label { text = "增加 " .. hoursText .. " 的 2/3/5 倍速时间", fontSize = 12, fontColor = PX.textWhite, textAlign = "center" },
                UI.Panel { width = "100%", flexDirection = "row", justifyContent = "center", gap = 10, children = {
                    UI.Button { text = "确认发放", variant = "primary", onClick = function()
                        AdminGrantSpeedTime(entry, seconds, function(ok, err)
                            ShowAdminNicknamePage(entry, ok and ("已发放 " .. hoursText .. "倍速补偿") or tostring(err or "发放失败"))
                        end)
                    end },
                    UI.Button { text = "取消", onClick = function() ShowAdminNicknamePage(entry) end },
                } },
            },
        },
    }
    UI.SetRoot(BuildSubPage("倍速补偿确认", content, function() ShowAdminNicknamePage(entry) end), true)
end

function ShowAdminMaterialGrantConfirmPage(entry, materialId, amount)
    if not IS_CLOUD_ADMIN or not entry then return end
    local materialName = materialId == REFINE_STONE_ITEM_ID and REFINE_STONE_NAME
        or (materialId == PINK_REFINE_STONE_ITEM_ID and PINK_REFINE_STONE_NAME
        or (materialId == REBIRTH_STONE_ITEM_ID and REBIRTH_STONE_NAME or nil))
    amount = math.floor(tonumber(amount) or 0)
    if materialName == nil then
        ShowAdminNicknamePage(entry, "奖励类型无效")
        return
    end
    if amount < 1 or amount > 9999 then
        ShowAdminNicknamePage(entry, "数量必须是1～9999的整数")
        return
    end
    currentScreen = "subpage"
    local content = {
        UI.Panel {
            width = "100%",
            padding = 14,
            gap = 10,
            alignItems = "center",
            backgroundColor = { 42, 28, 18, 245 },
            borderWidth = 1,
            borderColor = PX.gold,
            children = {
                UI.Label { text = "确认发放材料", fontSize = 17, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
                UI.Label { text = "目标: " .. tostring(entry.platformNickname or entry.nickname or "玩家"), fontSize = 12, fontColor = PX.textGold, textAlign = "center" },
                UI.Label { text = "完整 UID: " .. tostring(entry.userId), fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
                UI.Label { text = materialName .. " ×" .. tostring(amount), fontSize = 14, fontColor = materialId == PINK_REFINE_STONE_ITEM_ID and { 255, 145, 225, 255 } or (materialId == REBIRTH_STONE_ITEM_ID and { 220, 180, 255, 255 } or PX.textWhite), fontWeight = "bold", textAlign = "center" },
                UI.Label { text = "奖励将在目标玩家云存档加载后自动领取。", fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
                UI.Panel {
                    width = "100%",
                    flexDirection = "row",
                    justifyContent = "center",
                    gap = 10,
                    children = {
                        UI.Button { text = "确认发放", variant = "primary", onClick = function()
                            AdminGrantMaterial(entry, materialId, amount, function(ok, err, name)
                                local message = ok
                                    and ("已发放 " .. tostring(name or materialName) .. " ×" .. tostring(amount) .. "，等待玩家领取")
                                    or tostring(err or "发放失败")
                                ShowAdminNicknamePage(entry, message)
                            end)
                        end },
                        UI.Button { text = "取消", onClick = function() ShowAdminNicknamePage(entry) end },
                    },
                },
            },
        },
    }
    UI.SetRoot(BuildSubPage("材料发放确认", content, function() ShowAdminNicknamePage(entry) end), true)
end

