function RenderLeaderboard(entries, pageGeneration)
    pageGeneration = pageGeneration or leaderboardPageGeneration
    if currentScreen ~= "subpage"
        or currentSubPage ~= "leaderboard"
        or leaderboardPageGeneration ~= pageGeneration then return end

    -- 第2页起：从缓存的完整名单取第21~100名重新切片（第1页仍直接使用传入的 entries，逻辑不变；共5页=100人）
    if leaderboardDisplayPage >= 2
        and #(CURRENT_LEADERBOARD_ALL_ENTRIES or {}) > LEADERBOARD_DISPLAY_LIMIT then
        local pageEntries = {}
        local pageFrom = (leaderboardDisplayPage - 1) * LEADERBOARD_DISPLAY_LIMIT + 1
        local pageTo = math.min(
            math.min(#CURRENT_LEADERBOARD_ALL_ENTRIES, LEADERBOARD_DISPLAY_LIMIT * 5),
            leaderboardDisplayPage * LEADERBOARD_DISPLAY_LIMIT
        )
        for i = pageFrom, pageTo do
            table.insert(pageEntries, CURRENT_LEADERBOARD_ALL_ENTRIES[i])
        end
        entries = pageEntries
    end

    local rows = {}

    if IS_CLOUD_ADMIN then
        table.insert(rows, UI.Panel {
            width = "100%",
            minHeight = 42,
            flexDirection = "row",
            alignItems = "center",
            justifyContent = "space-between",
            paddingHorizontal = 9,
            paddingVertical = 6,
            gap = 8,
            backgroundColor = { 55, 18, 28, 244 },
            borderWidth = { 1, 1, 3, 4 },
            borderColor = PX.redBright,
            children = {
                UI.Panel {
                    flexDirection = "row",
                    alignItems = "center",
                    gap = 6,
                    children = {
                        UI.Label { text = "管理", fontSize = 9, fontColor = PX.textWhite, fontWeight = "bold", backgroundColor = PX.red, borderWidth = 1, borderColor = PX.redBright, paddingHorizontal = 5, paddingVertical = 2 },
                        UI.Label { text = "排行榜管理模式", fontSize = uiLabelSize, fontColor = PX.redBright, fontWeight = "bold" },
                    },
                },
                UI.Panel {
                    flexDirection = "row",
                    alignItems = "center",
                    gap = 6,
                    children = {
                        UI.Panel {
                            width = 82,
                            height = 30,
                            justifyContent = "center",
                            alignItems = "center",
                            backgroundColor = { 92, 54, 18, 255 },
                            borderWidth = { 1, 2, 3, 1 },
                            borderColor = PX.gold,
                            onClick = function(self)
                                ShowRewardAdStatsPage("1d")
                            end,
                            children = {
                                UI.Label { text = "广告统计", fontSize = uiLabelSize, fontColor = PX.textWhite, fontWeight = "bold", textAlign = "center" },
                            },
                        },
                        UI.Panel {
                            width = 82,
                            height = 30,
                            justifyContent = "center",
                            alignItems = "center",
                            backgroundColor = { 30, 62, 30, 255 },
                            borderWidth = { 1, 2, 3, 1 },
                            borderColor = { 80, 180, 100, 255 },
                            onClick = function(self)
                                ShowDailyOpsPage("1d")
                            end,
                            children = {
                                UI.Label { text = "每日运营", fontSize = uiLabelSize, fontColor = PX.textWhite, fontWeight = "bold", textAlign = "center" },
                            },
                        },
                        UI.Panel {
                            width = 82,
                            height = 30,
                            justifyContent = "center",
                            alignItems = "center",
                            backgroundColor = { 112, 28, 37, 255 },
                            borderWidth = { 1, 2, 3, 1 },
                            borderColor = PX.redBright,
                            onClick = function(self)
                                ShowBanListPage()
                            end,
                            children = {
                                UI.Label { text = "封禁名单", fontSize = uiLabelSize, fontColor = PX.textWhite, fontWeight = "bold", textAlign = "center" },
                            },
                        },
                    },
                },
            },
        })
    end

    if #entries == 0 then
        table.insert(rows, UI.Panel {
            width = "100%",
            minHeight = 92,
            padding = 12,
            gap = 6,
            justifyContent = "center",
            alignItems = "center",
            backgroundColor = { 22, 20, 37, 244 },
            borderWidth = { 1, 1, 3, 1 },
            borderColor = PX.goldDim,
            children = {
                UI.Label { text = "暂无可显示排行", fontSize = uiValueSize, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
                UI.Label { text = "有效排行记录会显示在这里", fontSize = 9, fontColor = PX.textGray, textAlign = "center" },
            },
        })
    end
    for _, entry in ipairs(entries) do
        local isTop3 = entry.rank >= 1 and entry.rank <= 3
        local top3Config = {
            [1] = { rowBg = { 72, 52, 20, 244 }, border = { 255, 215, 100, 255 }, rankText = { 255, 230, 128, 255 }, badge = { 128, 88, 18, 255 }, title = "王者" },
            [2] = { rowBg = { 48, 54, 70, 244 }, border = { 205, 220, 238, 255 }, rankText = { 235, 241, 248, 255 }, badge = { 91, 103, 124, 255 }, title = "精英" },
            [3] = { rowBg = { 68, 43, 29, 244 }, border = { 224, 150, 79, 255 }, rankText = { 244, 184, 112, 255 }, badge = { 126, 73, 38, 255 }, title = "勇者" },
        }
        local top3 = isTop3 and top3Config[entry.rank] or nil
        local rankColor = top3 and top3.rankText or PX.textGray
        local nicknamePrefix = entry.isMe and "[你] " or ""
        local rankBadge = UI.Panel {
            width = isTop3 and 46 or 38,
            minHeight = isTop3 and 42 or 34,
            paddingHorizontal = 3,
            paddingVertical = 3,
