function _RenderBanListPage()
    local rows = {}
    local count = _CountTable(CLOUD_BANLIST)
    table.insert(rows, UI.Panel {
        width = "100%", padding = 8, alignItems = "center",
        backgroundColor = { 60, 20, 20, 200 }, borderWidth = 1, borderColor = PX.redBright,
        children = {
            UI.Label { text = "已封禁玩家: " .. tostring(count) .. " 人", fontSize = uiLabelSize, fontColor = PX.redBright, fontWeight = "bold", textAlign = "center" },
        },
    })
    if count == 0 then
        table.insert(rows, UI.Panel {
            width = "100%", height = 80, justifyContent = "center", alignItems = "center",
            children = { UI.Label { text = "暂无封禁记录", fontSize = uiValueSize, fontColor = PX.textGray, textAlign = "center" } },
        })
    else
        local list = {}
        for uid, info in pairs(CLOUD_BANLIST) do
            table.insert(list, { uid = uid, info = info })
        end
        table.sort(list, function(a, b) return (a.info.ts or 0) > (b.info.ts or 0) end)
        for _, item in ipairs(list) do
            local uid = item.uid
            local info = item.info or {}
            local ts = info.ts or 0
            local timeStr = ""
            if ts > 0 and os and os.date then
                timeStr = os.date("%Y-%m-%d %H:%M", ts)
            else
                timeStr = "未知时间"
            end
            table.insert(rows, UI.Panel {
                width = "100%",
                flexDirection = "row",
                alignItems = "center",
                padding = 8,
                gap = 8,
                backgroundColor = { 20, 20, 38, 240 },
                borderWidth = 1,
                borderColor = PX.goldDim,
                children = {
                    UI.Panel {
                        flexGrow = 1,
                        children = {
                            UI.Label { text = tostring(info.nick or ("玩家" .. tostring(uid):sub(-4))), fontSize = uiValueSize, fontColor = PX.textGold, fontWeight = "bold" },
                            UI.Label { text = "最高层: " .. FormatLeaderboardProgress(info.bestFloor or 0) .. "  原因: " .. tostring(info.reason or "违规"), fontSize = 9, fontColor = PX.textGray },
                            UI.Label { text = timeStr .. "  UID:" .. tostring(uid):sub(-6), fontSize = 9, fontColor = { 100, 100, 120, 255 } },
                        },
                    },
                    UI.Panel {
                        width = 60,
                        height = 30,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = { 40, 80, 40, 255 },
                        borderWidth = 1,
                        borderColor = { 80, 180, 80, 255 },
                        onClick = (function(banUid) return function(self)
                            AdminUnban(banUid, function(ok, err)
                                if ok then
                                    print("[AdminBan] 已解封:", banUid)
                                    ShowBanListPage()
                                else
                                    print("[AdminBan] 解封失败:", tostring(err))
                                end
                            end)
                        end end)(uid),
                        children = {
                            UI.Label { text = "解封", fontSize = uiLabelSize, fontColor = PX.textWhite, fontWeight = "bold", textAlign = "center" },
                        },
                    },
                },
            })
        end
    end
    UI.SetRoot(BuildSubPage("封禁名单", rows, function() ShowLeaderboardPage() end), true)
end

function GetCloneUpgradeCost(level, index)
    level = math.max(0, level or 0)
    local idx = math.floor(index or 1)
    local multiplier = idx == 3 and 3 or (idx == 2 and 1.5 or 1)
    local cost = CONFIG.CloneUpgradeCostBase * (level + 1) * (level + 1) * multiplier
    return math.floor(cost + 0.5)
end

function GetCloneDamagePercent(index)
    local level = GetCloneUpgradeLevel(index or 1)
    return CONFIG.CloneBaseDamagePercent + level * CONFIG.CloneDamagePercentPerLevel
end

