function TryUpgradeClone(index)
    if not playerData.cloneUnlocked then return end
    index = math.max(1, math.min(3, math.floor(index or 1)))
    if index > math.max(0, playerData.cloneCount or 0) then return end
    local level = GetCloneUpgradeLevel(index)
    if level >= CONFIG.CloneMaxUpgradeLevel then
        playerData.cloneUpgradeMessage = "分身" .. index .. "强化已满级"
        ShowClonePage()
        return
    end
    local cost = GetCloneUpgradeCost(level, index)
    if playerData.gold < cost then
        playerData.cloneUpgradeMessage = "分身" .. index .. "金币不足，需要" .. tostring(cost)
        ShowClonePage()
        return
    end
    playerData.gold = playerData.gold - cost
    local successRate = GetEffectiveHiddenAdminSuccessRate(CONFIG.CloneUpgradeSuccessRate)
    if math.random() < successRate then
        SetCloneUpgradeLevel(index, level + 1)
        playerData.cloneUpgradeMessage = "强化成功！分身" .. index .. "等级+1"
    else
        playerData.cloneUpgradeMessage = "强化失败，分身" .. index .. "等级不变"
        saveDirty = true
    end
    SaveCloudData(true)
    ShowClonePage()
end

function GetCloneUnlockCountByFloor(floor)
    floor = math.max(1, floor or 1)
    if floor >= 200 then return 3 end
    if floor >= 100 then return 2 end
    if floor >= 20 then return 1 end
    return 0
end

function UpdateCloneUnlockProgress()
    local unlockedCount = GetCloneUnlockCountByFloor(playerData.bestFloor or 1)
    local currentCount = math.max(0, playerData.cloneCount or 0)
    if unlockedCount > currentCount then
        playerData.cloneUnlocked = true
        playerData.cloneCount = unlockedCount
        saveDirty = true
        SaveCloudData(true)
        return true
    end
    if currentCount > 0 and not playerData.cloneUnlocked then
        playerData.cloneUnlocked = true
        saveDirty = true
        SaveCloudData(true)
        return true
    end
    return false
end

