                            local inheritPercent = GetCloneAttackCountInheritPercent(index)
                            local inheritedAttackCount = GetCloneInheritedAttackCount(index)
                            local cloneDmg = GetHeroAttackDamage() * damagePercent / 100
                            local cost = GetCloneUpgradeCost(level, index)
                            local maxed = level >= CONFIG.CloneMaxUpgradeLevel
