    end

    UI.SetRoot(BuildSubPage("分身", content), true)
    print("[Page] 分身页面")
end

function GetCurrentUpdateLogRevision()
    return CONFIG
        and CONFIG.UpdateLogRevision
        or (
            "version-"
            .. tostring(
                CONFIG
                and CONFIG.GameVersion
                or "1.0.0"
            )
        )
end

function MarkUpdateVersionSeen()
    playerData.settings =
        playerData.settings or {}

    local revision =
        GetCurrentUpdateLogRevision()

    if playerData.settings.lastSeenUpdateRevision
        ~= revision then
        playerData.settings.lastSeenUpdateRevision =
            revision
        saveDirty = true
    end
end

function HasUpdateRedDot()
    local settings =
        playerData.settings or {}

    return (
        settings.lastSeenUpdateRevision
        or ""
    ) ~= GetCurrentUpdateLogRevision()
end

function ShowUpdateLogPage()
    currentScreen = "subpage"
    UpdateScreenMetrics()
    MarkUpdateVersionSeen()
    saveDirty = true

    local uiLabelSize = screenW < 340 and 13 or 12
    local uiValueSize = screenW < 340 and 14 or 13

    local function Section(title, lines, highlight)
        local children = {
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                alignItems = "center",
                gap = 6,
