function ShowGameGuidePage(returnAction)
    currentScreen = "subpage"
    UpdateScreenMetrics()

    local uiLabelSize = screenW < 340 and 12 or 11
    local uiValueSize = screenW < 340 and 14 or 13
    local sectionTitleSize = screenW < 340 and 14 or 13

    local function Section(title, lines, titleColor)
        local children = {
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                alignItems = "center",
                gap = 6,
                children = {
                    UI.Panel { width = 3, height = 16, backgroundColor = PX.gold },
                    UI.Label { text = title, fontSize = sectionTitleSize, fontColor = titleColor or PX.textGold, fontWeight = "bold" },
                },
            },
        }
        for _, line in ipairs(lines) do
            table.insert(children, UI.Label {
                text = line,
                fontSize = uiLabelSize,
                fontColor = PX.textWhite,
                whiteSpace = "normal",
            })
        end
        return UI.Panel {
            width = "100%",
            padding = 10,
            gap = 5,
            backgroundColor = { 20, 20, 38, 240 },
            borderWidth = 1,
            borderColor = PX.goldDim,
            children = children,
        }
    end

    local content = {
        UI.Label { text = "暗黑割草大剑守卫 游戏说明", fontSize = 16, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
        UI.Label { text = "v" .. (CONFIG and CONFIG.GameVersion or "1.0.0"), fontSize = uiLabelSize, fontColor = PX.textGray, textAlign = "center" },
        UI.Panel { width = "90%", height = 1, backgroundColor = { 245, 200, 92, 120 } },

