manualSaveRevision = manualSaveRevision or 0
manualSaveAt = manualSaveAt or 0

function ManualSaveNow()
    manualSaveRevision = math.max(0, math.floor(tonumber(manualSaveRevision) or 0)) + 1
    manualSavePendingCloud = true
    manualSaveAt = os.time()
    local snapshot = BuildSaveSnapshot()
    snapshot._latest_progress_save = true
    snapshot._manual_save_revision = manualSaveRevision
    local saved = SaveLocalSnapshot(true, snapshot)
    if not saved then
        manualSavePendingCloud = false
        return false, "本地存档失败"
    end
    saveDirty = true
    cloudSyncStatusText = "一键存档已落地，正在同步云端..."
    print("[ManualSave] 本地快照已落地，revision=", tostring(manualSaveRevision),
        "cloudReady=", tostring(cloudDataReadyForSave),
        "cloudInProgress=", tostring(cloudSaveInProgress))
    if cloudDataReadyForSave then
        SaveCloudData(true)
        return true, "一键存档已完成，云同步已开始"
    end
    ScheduleCloudRetry("manual_save_waiting_cloud", false)
    return true, "一键存档已完成，云同步等待中"
end

function ShowSettingsRewardAd(rewardKind, pageGeneration)
    if rewardAdInFlight then
        ShowSettingsPage("广告正在播放，请稍候")
        return
    end
    if NormalizeDailyRewardAdQuota ~= nil then
        NormalizeDailyRewardAdQuota()
    end
    if CanClaimDailyRewardAd ~= nil and not CanClaimDailyRewardAd() then
        ShowSettingsPage("今日广告次数已用完（"
            .. tostring(DAILY_REWARD_AD_MAX_CLAIMS or 20) .. "/"
            .. tostring(DAILY_REWARD_AD_MAX_CLAIMS or 20) .. "），明天再来")
        return
    end
    if rewardKind == "rebirth_stone_ad" and not CanClaimRebirthStoneAdReward() then
        ShowSettingsPage("今日转生石额度不足500，无法观看此广告")
        return
    end
    if rewardKind == "rift_pressure_ad" and GetEquipmentRiftPressure() <= EQUIPMENT_RIFT_PRESSURE_MIN then
        ShowSettingsPage("试炼压力已是最低值 -6，无法获得收益")
        return
    end
    if rewardKind == "socket_puncher"
        and (CanClaimDailySocketPuncherAd == nil
            or not CanClaimDailySocketPuncherAd()) then
        ShowSettingsPage("打孔器广告今日已领取，明天再来")
        return
    end
    if rewardKind == "triple_speed" and playerData.settings.tripleSpeedUnlocked == true then
        ShowSettingsPage("2/3倍速已永久解锁")
        return
    end
    if rewardKind == "ten_battle" and playerData.settings.tenBattleUnlocked == true then
        ShowSettingsPage("10连打已永久解锁")
        return
    end
    if rewardKind == "five_speed" then
        if (playerData.bestFloor or 0) <= 50 then
            ShowSettingsPage("历史最高超过50层后可解锁今日 5 倍速")
            return
        end
        if IsFiveSpeedUnlockedToday and IsFiveSpeedUnlockedToday() then
            ShowSettingsPage("5倍速：今日已解锁")
            return
        end
    end

    ShowRewardAd(function(success, msg)
        local message = GetRewardAdFailureMessage(msg)
        if success then
            -- 广告完整观看成功。发奖只允许在 success 回调里进行。
            -- 顺序固定为：此刻仍可领的校验 -> 先发奖 -> 最后才扣次数，
            -- 避免“先扣次数再发奖”在发奖异常时扣了次数却没发奖。
            local blockReason = nil
            if rewardKind == "triple_speed" and playerData.settings.tripleSpeedUnlocked == true then
                blockReason = "2/3倍速已永久解锁，奖励未发放"
            elseif rewardKind == "ten_battle" and playerData.settings.tenBattleUnlocked == true then
                blockReason = "10连打已永久解锁，奖励未发放"
            elseif rewardKind == "five_speed" then
                if (playerData.bestFloor or 0) <= 50 then
                    blockReason = "历史最高超过50层后可解锁今日 5 倍速"
                elseif IsFiveSpeedUnlockedToday and IsFiveSpeedUnlockedToday() then
                    blockReason = "5倍速今日已解锁，奖励未发放"
                end
            elseif rewardKind == "rebirth_stone_ad" and not CanClaimRebirthStoneAdReward() then
                blockReason = "今日转生石额度不足500，奖励未发放"
            elseif rewardKind == "rift_pressure_ad"
                and GetEquipmentRiftPressure() <= EQUIPMENT_RIFT_PRESSURE_MIN then
                blockReason = "试炼压力已是最低值 -6，奖励未发放"
            elseif rewardKind == "socket_puncher"
                and (CanClaimDailySocketPuncherAd == nil
                    or not CanClaimDailySocketPuncherAd()) then
                blockReason = "打孔器广告今日已领取，奖励未发放"
            elseif not CanClaimDailyRewardAd() then
                blockReason = "今日广告次数已用完，奖励未发放"
            end
            if blockReason ~= nil then
                message = blockReason
                print("[RewardAd] 设置页广告成功但条件已不满足，不扣次数:", rewardKind, blockReason)
            else
                -- 1) 先发奖（发奖失败不会进入扣次数）
                local granted = true
                if rewardKind == "triple_speed" then
                    playerData.settings.tripleSpeedUnlocked = true
                    message = "2/3倍速已永久解锁"
                elseif rewardKind == "ten_battle" then
                    playerData.settings.tenBattleUnlocked = true
                    message = "10连打已永久解锁"
                elseif rewardKind == "five_speed" then
                    playerData.settings.fiveSpeedAdUnlockDayKey = GetCurrentCstDayKey()
                    message = "5倍速已解锁至今日24:00"
                elseif rewardKind == "white_refine_stone" then
                    local amount = WHITE_REFINE_AD_REWARD or 50
                    AddRefineStone(amount, true)
                    message = "获得白色洗练石 ×" .. tostring(amount)
                elseif rewardKind == "pink_refine_stone" then
                    local amount = PINK_REFINE_AD_REWARD or 5
                    AddPinkRefineStone(amount, true)
                    message = "获得粉色洗练石 ×" .. tostring(amount)
                elseif rewardKind == "socket_puncher" then
                    AddSocketPuncher(1, true)
                    message = "获得打孔器 ×1"
                elseif rewardKind == "rebirth_stone_ad" then
                    local grantedOk, amount = GrantRebirthStoneAdReward()
                    if not grantedOk then
                        granted = false
                        message = "今日转生石额度不足500，奖励未发放"
                        print("[RewardAd] 转生石广告奖励未发放，实际额度:", tostring(amount))
                    else
                        message = "获得转生石 ×" .. tostring(amount)
                    end
                elseif rewardKind == "gold_ad" then
                    local amount = GrantSettingsGoldAdReward()
                    message = "获得金币 ×" .. tostring(amount)
                elseif rewardKind == "gem_ad" then
                    local parts = GrantSettingsGemAdReward()
                    message = "获得1级宝石 ×" .. tostring(GEM_AD_REWARD_COUNT or 10)
                    if parts ~= nil and #parts > 0 then
                        message = message .. "：" .. table.concat(parts, "，")
                    end
                elseif rewardKind == "rift_pressure_ad" then
                    local reduced, pressure = GrantSettingsRiftPressureAdReward()
                    message = "试炼压力减少 " .. tostring(reduced)
                        .. " 层，当前压力 " .. tostring(pressure)
                else
                    granted = false
                    message = "奖励类型无效，未扣次数"
                    print("[RewardAd] 未知设置页奖励类型:", tostring(rewardKind))
                end
                if granted then
                    -- 2) 发奖成功后才扣次数；极端情况下扣次数失败只记日志，不影响已发奖励
                    local claimConsumed = false
                    if rewardKind == "socket_puncher" then
                        claimConsumed = ConsumeDailySocketPuncherAdClaim ~= nil
                            and ConsumeDailySocketPuncherAdClaim()
                    else
                        claimConsumed = ConsumeDailyRewardAdClaim ~= nil
                            and ConsumeDailyRewardAdClaim()
                    end
                    if not claimConsumed then
                        print("[RewardAd] 设置页奖励已发但扣次数失败，需人工核对:", rewardKind)
                    end
                    message = message .. "（" .. FormatDailyRewardAdProgressText() .. "）"
                    saveDirty = true
                    SaveCloudData(true)
                    print("[RewardAd] 设置页奖励已发放:", rewardKind)
                end
            end
        else
            print("[RewardAd] 设置页奖励未发放:", rewardKind, tostring(msg))
        end
        if currentScreen == "subpage" and settingsPageGeneration == pageGeneration then
            ShowSettingsPage(message)
        end
    end)
end

-- 解析当前玩家在排行榜中展示的最终名字。
-- 与排行榜页显示完全同源的取值顺序：
-- 1) 排行榜名字解析时记录的 MY_LEADERBOARD_NAME（含管理员覆写，最优先）
-- 2) 管理员覆写名
-- 3) TapTap 平台昵称
-- 4) 自动生成的“玩家+尾号”兜底名
-- 返回值: displayName(展示名), sourceText(来源说明), needQuery(是否需要异步补查平台昵称)
function GetMyLeaderboardDisplayNameInfo()
    local myUid = clientCloud and tostring(clientCloud.userId or "") or ""
    if myUid == "" then
        return "未登录", "登录云账号后即可在排行榜展示名字", false
    end
    if MY_LEADERBOARD_NAME ~= nil and MY_LEADERBOARD_NAME ~= "" then
        return tostring(MY_LEADERBOARD_NAME), "排行榜上展示的名字", false
    end
    local overrideName = (CLOUD_NICKNAME_OVERRIDES or {})[myUid]
    if overrideName ~= nil and tostring(overrideName) ~= "" then
        return tostring(overrideName), "由管理员设置的名字", false
    end
    local platformName = tostring(PLAYER_PLATFORM_NICKNAME_CACHE or "")
    if platformName ~= "" then
        return platformName, "来自你的 TapTap 昵称", false
    end
    local suffix = #myUid >= 4 and myUid:sub(-4) or myUid
    return "玩家" .. suffix, "自动生成的临时名字：未获取到 TapTap 昵称", true
end

function ShowSettingsPage(redeemMsg)
    settingsPageGeneration = settingsPageGeneration + 1
    local pageGeneration = settingsPageGeneration
    currentScreen = "subpage"
    UpdateScreenMetrics()

    local compact = screenW < 340
    local uiLabelSize = compact and 11 or 12
    local uiValueSize = compact and 12 or 13
    local smallGap = compact and 3 or 5
    local smallPadding = compact and 5 or 7
    local cardColor = { 20, 20, 38, 240 }

    local function CloseAndDestroyModal(modal, name)
        if modal == nil then return end
        print("[SettingsModal] 关闭:", name)
        modal:Close()
    end

    local function OpenRedeemModal()
        local codeInput = UI.TextField {
            width = "100%",
            placeholder = "输入兑换码",
            fontSize = uiValueSize,
        }
        local modal
        local function RedeemCode()
            local code = codeInput:GetText()
            if not code or code == "" then
                CloseAndDestroyModal(modal, "兑换码")
                ShowSettingsPage("请输入兑换码")
                return
            end

            local entry = REDEEM_CODES[code]
            if not entry then
                CloseAndDestroyModal(modal, "兑换码")
                ShowSettingsPage("无效的兑换码")
                return
            end

            if entry.admin == true then
                CloseAndDestroyModal(modal, "兑换码")
                ShowSettingsPage("正在激活管理员...")
                print("[兑换码] 管理员激活请求:", code)
                ClaimAdmin(function(ok, result)
                    if ok then
                        ShowSettingsPage("管理员激活成功！现在你可以在游戏内封禁违规玩家。")
                    else
                        ShowSettingsPage("激活失败: " .. tostring(result or "未知错误"))
                    end
                end)
                return
            end

            for _, used in ipairs(redeemedCodes) do
                if used == code then
                    CloseAndDestroyModal(modal, "兑换码")
                    ShowSettingsPage("该码已兑换过")
                    return
                end
            end

            local reward = entry.reward or {}
            if reward.gold then
                AddGold(reward.gold)
            end
            if reward.tripleSpeedUnlocked then
                playerData.settings.tripleSpeedUnlocked = true
            end
            if reward.fiveSpeedUnlocked then
                playerData.settings.fiveSpeedUnlocked = true
                playerData.settings.tripleSpeedUnlocked = true
            end
            if reward.tenSpeedUnlocked then
                playerData.settings.tenSpeedUnlocked = true
            end
            if reward.fakeTenSpeedUnlocked then
                playerData.settings.fakeTenSpeedUnlocked = true
            end
            if reward.tenBattleUnlocked then
                playerData.settings.tenBattleUnlocked = true
            end
            if reward.twentyBattleUnlocked then
                playerData.settings.twentyBattleUnlocked = true
            end
            if reward.rebirthStone then
                playerData.rebirthStone = (playerData.rebirthStone or 0)
                    + (tonumber(reward.rebirthStone) or 0)
            end
            if reward.refineStone then
                AddRefineStone(reward.refineStone)
            end
            if reward.unlockSkillSlots then
                local baseSlotCount = (CONFIG and CONFIG.SkillSlotBaseCount) or 10
                local target = tonumber(reward.unlockSkillSlots) or 0
                local current = tonumber(playerData.unlockedSkillSlots) or baseSlotCount
                if target > current then
                    playerData.unlockedSkillSlots = target
                end
                NormalizeSkills()
                InitSkillRuntime()
            end
            table.insert(redeemedCodes, code)
            SaveCloudData(true)
            CloseAndDestroyModal(modal, "兑换码")
            ShowSettingsPage("兑换成功: " .. entry.desc)
            print("[兑换码] 成功:", code, entry.desc)
        end

        modal = UI.Modal {
            title = "兑换码",
            size = "sm",
            isOpen = false,
            closeOnOverlay = true,
            closeOnEscape = true,
            showCloseButton = true,
            contentPadding = 12,
            contentGap = 8,
            backgroundColor = { 25, 18, 26, 255 },
            borderWidth = 2,
            borderColor = PX.goldDim,
            onClose = function(self)
                print("[SettingsModal] 兑换码弹窗已销毁")
                self:Destroy()
            end,
            children = {
                UI.Label {
                    text = "输入有效兑换码后立即发放奖励",
                    fontSize = uiLabelSize,
                    fontColor = PX.textGray,
                    textAlign = "center",
                },
                codeInput,
                UI.Button {
                    width = "100%",
                    text = "兑换",
                    variant = "primary",
                    onClick = RedeemCode,
                },
            },
        }
        print("[SettingsModal] 打开兑换码弹窗")
        modal:Open()
    end

    local function BuildCompactControl(text, active, onClick, disabled)
        return UI.Button {
            flexGrow = 1,
            flexBasis = 0,
            height = compact and 26 or 28,
            text = text,
            variant = active and "success" or "secondary",
            disabled = disabled == true,
            onClick = onClick,
        }
    end

    local function BuildAudioControl(label, value, onChange)
        return UI.Panel {
            flexGrow = 1,
            flexBasis = 0,
            flexShrink = 1,
            gap = smallGap,
            padding = smallPadding,
            backgroundColor = { 28, 25, 45, 238 },
            borderWidth = 1,
            borderColor = PX.goldDim,
            children = {
                UI.Panel {
                    width = "100%",
                    flexDirection = "row",
                    justifyContent = "space-between",
                    alignItems = "center",
                    children = {
                        UI.Label { text = label, fontSize = uiLabelSize, fontColor = PX.textWhite },
                        UI.Label { text = tostring(value) .. "%", fontSize = uiLabelSize, fontColor = PX.textGold },
                    },
                },
                UI.Slider {
                    width = "100%",
                    value = value,
                    min = 0,
                    max = 100,
                    step = 10,
                    onChange = onChange,
                },
            },
        }
    end

    if NormalizeDailyRewardAdQuota ~= nil then
        NormalizeDailyRewardAdQuota()
    end
    local dailyAdClaimed = GetDailyRewardAdClaimCount and GetDailyRewardAdClaimCount() or 0
    local dailyAdMax = DAILY_REWARD_AD_MAX_CLAIMS or 20
    local dailyAdRemaining = GetDailyRewardAdRemaining and GetDailyRewardAdRemaining() or 0
    local dailyAdExhausted = dailyAdRemaining <= 0
    local socketPuncherAdRemaining = GetDailySocketPuncherAdRemaining
        and GetDailySocketPuncherAdRemaining() or 0
    local socketPuncherAdExhausted = socketPuncherAdRemaining <= 0
    local fiveSpeedUnlocked = IsFiveSpeedUnlockedToday and IsFiveSpeedUnlockedToday()
    local fiveSpeedAvailable = (playerData.bestFloor or 0) > 50

    local battleButtons = {
