    SETTINGS_NAME_QUERY_DONE = SETTINGS_NAME_QUERY_DONE or false
    if myNameNeedQuery and not SETTINGS_NAME_QUERY_DONE then
        SETTINGS_NAME_QUERY_DONE = true
        local myUid = clientCloud and tostring(clientCloud.userId or "") or ""
        if myUid ~= "" and GetUserNickname ~= nil then
            GetUserNickname({
                userIds = { myUid },
                onSuccess = function(nicknames)
                    if currentScreen ~= "subpage" or settingsPageGeneration ~= pageGeneration then
                        return
                    end
                    for _, info in ipairs(nicknames or {}) do
                        if tostring(info.userId or "") == myUid then
                            local nickname = tostring(info.nickname or "")
                            if nickname ~= "" then
                                PLAYER_PLATFORM_NICKNAME_CACHE = nickname
                                PLAYER_PLATFORM_NICKNAME_CACHE_UID = myUid
                                PLAYER_PLATFORM_NICKNAME_CACHE_UPDATED_AT = os.time()
                                MY_LEADERBOARD_NAME = nickname
