                                    nameSourceLabel:SetText("来自你的 TapTap 昵称")
                                end
                                print("[SettingsName] 我的名字刷新为:", nickname)
                            end
                            break
                        end
                    end
                end,
                onError = function(errorCode)
                    print("[SettingsName] 昵称补查失败，保持自动名:", tostring(errorCode))
                end,
            })
        end
    end

