function IsRebirthUnlocked()
    NormalizeProgressionData()
    return playerData.rebirthUnlocked == true
end

function RebirthToFirstFloor()
    if not IsRebirthUnlocked() then return false end

    local rebirthStoneReward = 0
    local runCompletedFloors = math.max(
        0,
        math.floor(tonumber(playerData.rebirthRunCompletedFloors) or 0)
    )
    if not endlessTrialActive
        and not trainingModeActive
        and not equipmentRiftActive
        and runCompletedFloors > 0 then
        local normalCap = math.max(
            1,
            math.floor(tonumber(CONFIG.NormalFloorCap) or 600)
        )
        local runStart = math.max(
            1,
            math.floor(tonumber(playerData.rebirthRunStartFloor) or 1)
        )
        local runSkippedFloors = math.max(
            0,
            math.floor(tonumber(playerData.rebirthRunSkippedFloors) or 0)
        )
        local reachedFloor = math.min(
            normalCap,
            runStart + runCompletedFloors + runSkippedFloors - 1
        )
        rebirthStoneReward = math.floor(tonumber(AwardRebirthStoneOnDeath(reachedFloor, runStart)) or 0)
    else
        playerData.rebirthRunStartFloor = 1
        playerData.rebirthRunCompletedFloors = 0
        playerData.rebirthRunSkippedFloors = 0
    end

    local currentGold = math.max(0, math.floor(tonumber(playerData.gold) or 0))
    local goldLoss = math.floor(currentGold * 0.5)
    playerData.gold = currentGold - goldLoss
    if endlessTrialActive then
        ResolveEndlessRunState("manual_rebirth")
        ClearBattleRuntimeCache()
        endlessTrialActive = false
        endlessPauseMenuOpen = false
        endlessExitNoticeOpen = false
    end
    ResetPendingLoot()
    runGoldReward = 0
    fiveBattleActive = false
    fiveBattleRequested = false
    fiveBattleRequestedFloorCount = 1
    fiveBattleFloorCount = 1
    fiveBattleSpeedMul = 1.0
    playerData.currentFloor = 1
    playerData.rebirthRunActive = true
    playerData.nextBaseHpRatio = nil
    playerData.selectedStartFloor = 0
    deathSelectAvailable = false
    deathSelectPromptVisible = false
    deathSelectPromptDismissed = false
    ResetRoguelikeRun(math.max(0, math.floor(playerData.rebirthCount or 0)) + 1)
    playerData.roguelikeRunState.classId = nil
    playerData.rebirthCount = math.max(0, math.floor(playerData.rebirthCount or 0)) + 1
    currentScreen = "menu"
    saveDirty = true
    SaveCloudData(true)
    print(
        "[Rebirth] 重生至第1层，金币损失:", goldLoss,
        "转生石实际到账:", rebirthStoneReward,
        "技能与永久属性保留"
    )
    GameEvents.Emit("scene:main")
    return true
end

function ShowRebirthConfirm()
    if not IsRebirthUnlocked() then return false end
    local modal
    modal = UI.Modal {
        title = "确认重生",
        size = "sm",
        closeOnOverlay = true,
        closeOnEscape = true,
        children = {
            UI.Label {
                text = "从第1层重新开始，当前金币减少一半（向下取整）。技能、技能星级和永久养成属性保留，本轮肉鸽属性清除后重新选择。也可以暂不重生，直接进入无尽模式。",
                fontSize = 12,
                fontColor = PX.textWhite,
                textAlign = "center",
                whiteSpace = "normal",
            },
        },
        onClose = function(self) self:Destroy() end,
    }
    modal:SetFooter(UI.Panel {
        width = "100%",
        flexDirection = "row",
        justifyContent = "center",
        gap = 8,
        children = {
            UI.Button { text = "暂不重生，进入无尽", variant = "secondary", onClick = function()
                modal:Close()
                GameEvents.Emit("battle:start", { endlessTrial = true })
            end },
            UI.Button {
                text = "确认重生",
                variant = "danger",
                onClick = function()
                    if RebirthToFirstFloor() then modal:Close() end
                end,
            },
        },
    })
    modal:Open()
    return true
end

function HasPendingDeathStartFloorChoice()
    if deathSelectAvailable ~= true then return false end
    if GetMaxSelectableStartFloor() <= 0 then return false end
    return FindSelectableStartFloor(playerData.selectedStartFloor or 0) > 0
end

function RequestDeathStartFloorPrompt()
    if not HasPendingDeathStartFloorChoice() then return false end
    deathSelectPromptVisible = true
    ShowMainMenu()
    return true
end

