    local trainingUnlocked = IsTrainingGroundUnlocked()
    local rebirthUnlocked = IsRebirthUnlocked()
    local function StartNormalBattle()
        local normalCap = CONFIG.NormalFloorCap or 600
        local currentFloor = math.max(
            1,
            math.floor(tonumber(playerData.currentFloor) or 1)
        )
        if rebirthUnlocked
            and playerData.rebirthRunActive ~= true
            and currentFloor >= normalCap then
            ShowRebirthConfirm()
            return
        end
        if HasPendingDeathStartFloorChoice() then
            RequestDeathStartFloorPrompt()
            return
        end
        deathSelectAvailable = false
        deathSelectPromptVisible = false
        deathSelectPromptDismissed = false
        playerData.selectedStartFloor = 0
        local battleFloorCount = 1
        if playerData.settings and playerData.settings.twentyBattleUnlocked == true and playerData.settings.twentyBattleEnabled == true then
            battleFloorCount = 20
        elseif playerData.settings and playerData.settings.tenBattleUnlocked == true and playerData.settings.tenBattleEnabled == true then
            battleFloorCount = 10
        elseif playerData.settings and playerData.settings.fiveBattleEnabled == true then
            battleFloorCount = 5
        end
