    local function FormatResourceNumber(value)
        local number = math.max(
            0,
            math.floor(tonumber(value) or 0)
        )
        local divisor = nil
        local suffix = ""
        if number >= 100000000 then
            divisor = 100000000
            suffix = "亿"
        elseif number >= 10000 then
            divisor = 10000
            suffix = "万"
        end
        if divisor == nil then
            return tostring(number)
        end

        local compactValue = number / divisor
        local text
        if compactValue >= 100 then
            text = string.format("%.0f", compactValue)
        elseif compactValue >= 10 then
            text = string.format("%.1f", compactValue)
        else
            text = string.format("%.2f", compactValue)
        end
        text = text:gsub("(%..-)0+$", "%1")
        text = text:gsub("%.$", "")
        return text .. suffix
    end

