    local function ChangeSelectedStartFloor(delta)
        if not canDeathSelect or maxSelectableFloor <= 0 then
            playerData.selectedStartFloor = 0
        else
            local direction = delta < 0 and -1 or 1
            local nextFloor = math.max(0, math.min(
                maxSelectableFloor,
                (playerData.selectedStartFloor or 0) + delta
            ))
            while nextFloor >= 1 and nextFloor <= maxSelectableFloor and IsStartFloorUsed(nextFloor) do
                nextFloor = nextFloor + direction
            end
            if nextFloor > maxSelectableFloor then
                nextFloor = maxSelectableFloor
                while nextFloor >= 1 and IsStartFloorUsed(nextFloor) do
                    nextFloor = nextFloor - 1
                end
            end
            playerData.selectedStartFloor = math.max(0, nextFloor)
        end
        saveDirty = true
        ShowMainMenu()
    end

