function GetEquipmentIconPath(itemOrSlotId)
    local slotId = itemOrSlotId
    if type(itemOrSlotId) == "table" then
        slotId = itemOrSlotId.slot
        if slotId == "weapon" then
            local visualId = GetWeaponVisualId and GetWeaponVisualId(itemOrSlotId) or itemOrSlotId.visualId
            if type(visualId) == "string" and weaponImagePaths and weaponImagePaths[visualId] ~= nil then
                return weaponImagePaths[visualId]
            end
        end
    end
    local slotDef = EQUIPMENT_SLOT_BY_ID[slotId]
    return slotDef and slotDef.icon or "image/装备图标_黑红重甲_20260729141807.png"
end

function GetEquipmentVisualBackground(itemOrSlotId, qualityDef)
    if type(itemOrSlotId) ~= "table" then
        return { 14, 13, 25, 250 }
    end

    local color = GetEquipmentDisplayColor(itemOrSlotId)
    local ancientBoost = IsAncientEquipment(itemOrSlotId) and 0.18 or 0.10
    return {
        math.floor(12 + color[1] * ancientBoost),
        math.floor(11 + color[2] * ancientBoost),
        math.floor(22 + color[3] * ancientBoost),
        250,
    }
end

