function MakeEquipmentResonanceEffectRows(def, count, fontSize)
    local rows = {}
    for _, threshold in ipairs(EQUIPMENT_RESONANCE_THRESHOLDS or {}) do
        local active = count >= threshold
        table.insert(rows, UI.Label {
            text = (active and "已激活 " or "未激活 ")
                .. threshold .. "件 · "
                .. (def.effects[threshold] or ""),
            fontSize = fontSize or 9,
            fontColor = active and def.color or PX.textGray,
            fontWeight = active and "bold" or "normal",
            textAlign = "center",
            whiteSpace = "normal",
        })
    end
    return rows
end

function MakeEquipmentSocketPanel(
    item,
    onEmptySocketClick,
    onSocketPuncherClick
)
    NormalizeEquipmentGemState(item)
    local socketCount = GetEquipmentSocketCount(item)
    local socketRows = {}

    if socketCount <= 0 then
        table.insert(socketRows, UI.Label {
            text = "该装备没有宝石孔",
            fontSize = 10,
            fontColor = PX.textGray,
            textAlign = "center",
        })
    else
        for socketIndex = 1, socketCount do
            local gem = item.gems and item.gems[socketIndex] or nil
            if gem ~= nil then
                local def = GetGemDef(gem.gemType)
                table.insert(socketRows, UI.Panel {
                    width = "100%",
                    minHeight = 38,
                    paddingHorizontal = 9,
                    paddingVertical = 6,
                    justifyContent = "center",
                    backgroundColor = { 28, 25, 42, 245 },
                    borderWidth = 1,
                    borderColor = def and def.color or PX.goldDim,
                    children = {
                        UI.Label {
                            text = "孔" .. socketIndex .. "  " .. GetGemDisplayName(gem.gemType, gem.level),
                            fontSize = 10,
                            fontColor = def and def.color or PX.textWhite,
                            fontWeight = "bold",
                            textAlign = "center",
                        },
                        UI.Label {
                            text = GetGemEffectText(gem.gemType, gem.level) .. "｜永久镶嵌",
                            fontSize = 9,
                            fontColor = PX.textGray,
                            textAlign = "center",
                        },
                    },
                })
            else
                table.insert(socketRows, UI.Panel {
                    width = "100%",
                    height = 38,
                    justifyContent = "center",
                    alignItems = "center",
                    backgroundColor = { 34, 42, 54, 245 },
                    borderWidth = 1,
                    borderColor = { 105, 160, 205, 210 },
                    onClick = onEmptySocketClick,
                    children = {
                        UI.Label {
                            text = "孔" .. socketIndex .. "  空孔 · 点击选择宝石",
                            fontSize = 10,
                            fontColor = { 150, 210, 255, 255 },
                            fontWeight = "bold",
                            textAlign = "center",
                        },
                    },
                })
            end
        end
    end

    local panelChildren = {
        UI.Label {
            text = "宝石孔 " .. GetEquipmentSocketedGemCount(item) .. "/" .. socketCount,
            fontSize = 11,
            fontColor = PX.textGold,
            fontWeight = "bold",
            textAlign = "center",
        },
        UI.Label {
            text = "镶嵌不可替换、不可拆卸；属性从下一场战斗开始生效",
            fontSize = 9,
            fontColor = PX.textGray,
            textAlign = "center",
            whiteSpace = "normal",
        },
    }

    if socketCount < 2 then
        table.insert(panelChildren, UI.Panel {
            width = "100%",
            height = 34,
            justifyContent = "center",
            alignItems = "center",
            backgroundColor = onSocketPuncherClick ~= nil
                and { 85, 55, 28, 245 }
                or { 45, 45, 58, 210 },
            borderWidth = 2,
            borderColor = onSocketPuncherClick ~= nil
                and { 245, 190, 85, 230 }
                or { 90, 90, 110, 180 },
            onClick = onSocketPuncherClick,
            children = {
                UI.Label {
                    text = onSocketPuncherClick ~= nil
                        and "使用打孔器增加空孔"
                        or "打孔器不足",
                    fontSize = 10,
                    fontColor = onSocketPuncherClick ~= nil
                        and PX.textWhite
                        or PX.textGray,
                    fontWeight = "bold",
                    textAlign = "center",
                },
            },
        })
        table.insert(panelChildren, UI.Label {
            text = "打孔器 " .. tostring(GetSocketPuncherCount())
                .. "｜已锁定或已镶嵌装备也可打孔",
            fontSize = 9,
            fontColor = PX.textGray,
            textAlign = "center",
            whiteSpace = "normal",
        })
    end

    for _, socketRow in ipairs(socketRows) do
        table.insert(panelChildren, socketRow)
    end

    return UI.Panel {
        width = "100%",
        padding = 9,
        gap = 6,
        alignItems = "center",
        backgroundColor = { 18, 18, 32, 245 },
        borderWidth = 1,
        borderColor = { 105, 160, 205, 190 },
        children = panelChildren,
    }
end

