function ShowGemSocketSelectionPage(item, returnCallback, message)
    currentScreen = "subpage"
    currentSubPage = "gem_socket_select"
    UpdateScreenMetrics()

    NormalizeEquipmentGemState(item)
    if GetEquipmentSocketedGemCount(item) >= GetEquipmentSocketCount(item) then
        AddEffect({ type = "drop", x = screenW * 0.5, y = screenH * 0.35, text = "该装备没有空宝石孔", life = 1.0, maxLife = 1.0 })
        returnCallback()
        return
    end

    local content = {
        UI.Label { text = GetEquipmentDisplayName(item), fontSize = 13, fontColor = GetEquipmentDisplayColor(item), fontWeight = "bold", textAlign = "center" },
        UI.Label { text = "只显示背包中可用且该装备尚未镶嵌的宝石类型", fontSize = 9, fontColor = PX.textGray, textAlign = "center", whiteSpace = "normal" },
        message and UI.Label { text = message, fontSize = 10, fontColor = PX.textGold, textAlign = "center" } or nil,
    }

    local availableCount = 0
    for _, gemType in ipairs(GEM_ORDER or {}) do
        if not HasEquipmentGemType(item, gemType) then
            local def = GetGemDef(gemType)
            for level = 1, GEM_MAX_LEVEL do
                local gemLevel = level
                local count = GetGemCount(gemType, gemLevel)
                if count > 0 then
                    availableCount = availableCount + 1
                    table.insert(content, UI.Panel {
                        width = "100%",
                        minHeight = 48,
                        flexDirection = "row",
                        padding = 8,
                        gap = 8,
                        alignItems = "center",
                        backgroundColor = { 22, 22, 40, 245 },
                        borderWidth = 1,
                        borderColor = def and def.color or PX.goldDim,
                        onClick = function(self)
                            ShowGemSocketConfirmationPage(item, gemType, gemLevel, returnCallback)
                        end,
                        children = {
                            UI.Label { text = def and def.shortName or "宝", width = 30, fontSize = 13, fontColor = def and def.color or PX.textWhite, fontWeight = "bold", textAlign = "center" },
                            UI.Panel {
                                flexGrow = 1,
                                flexShrink = 1,
                                gap = 2,
                                children = {
                                    UI.Label { text = GetGemDisplayName(gemType, gemLevel) .. " ×" .. count, fontSize = 11, fontColor = def and def.color or PX.textWhite, fontWeight = "bold" },
                                    UI.Label { text = GetGemEffectText(gemType, gemLevel), fontSize = 9, fontColor = PX.textGray },
                                },
                            },
                            UI.Label { text = "选择", width = 40, fontSize = 10, fontColor = PX.textGold, textAlign = "center" },
                        },
                    })
                end
            end
        end
    end

    if availableCount <= 0 then
        table.insert(content, UI.Panel {
            width = "100%",
            height = 72,
            justifyContent = "center",
            alignItems = "center",
            backgroundColor = { 20, 20, 38, 240 },
            borderWidth = 1,
            borderColor = PX.goldDim,
            children = {
                UI.Label { text = "没有可镶嵌的宝石", fontSize = 11, fontColor = PX.textGray, textAlign = "center" },
                UI.Label { text = "秘境中获得的宝石会在安全撤离后进入背包", fontSize = 9, fontColor = PX.textGray, textAlign = "center" },
            },
        })
    end

    UI.SetRoot(BuildSubPage("选择宝石", content, returnCallback, "返回装备详情"), true)
end

