function GetEquipmentResonanceProgressText(def, count)
    local activeThresholds = {}
    local nextThreshold = nil
    for _, threshold in ipairs(EQUIPMENT_RESONANCE_THRESHOLDS or {}) do
        if count >= threshold then
            table.insert(activeThresholds, tostring(threshold))
        elseif nextThreshold == nil then
            nextThreshold = threshold
        end
    end
    local activeText = #activeThresholds > 0
        and ("已激活" .. table.concat(activeThresholds, "/") .. "件效果")
        or "尚未激活"
    local nextText = nextThreshold ~= nil
        and ("下一档" .. nextThreshold .. "件")
        or "全部激活"
    return def.shortName .. " " .. count .. "件｜"
        .. activeText .. "｜" .. nextText
end

function ShowEquipmentResonanceDetailModal(
    equipment,
    replacementItem,
    replacementSlot
)
    equipment = equipment or GetActiveEquipment()
    local counts = replacementSlot ~= nil
        and CountEquipmentResonanceSets(
            equipment,
            replacementItem,
            replacementSlot
        )
        or CountEquipmentResonanceSets(equipment)
    local detailCards = {}
    for _, setId in ipairs(EQUIPMENT_RESONANCE_ORDER or {}) do
        local def = GetEquipmentResonanceDef(setId)
        if def ~= nil then
            local count = counts[setId] or 0
            local rows = {
                UI.Label {
                    text = def.name .. " · " .. count .. "件",
                    fontSize = 11,
                    fontColor = count >= 2 and def.color or PX.textGray,
                    fontWeight = "bold",
                    textAlign = "center",
                },
            }
            for _, row in ipairs(
                MakeEquipmentResonanceEffectRows(def, count, 9)
            ) do
                table.insert(rows, row)
            end
            table.insert(detailCards, UI.Panel {
                width = "100%",
                padding = 7,
                gap = 3,
                alignItems = "center",
                backgroundColor = { 18, 18, 32, 245 },
                borderWidth = 1,
                borderColor = count >= 2
                    and def.color
                    or { 70, 70, 90, 160 },
                children = rows,
            })
        end
    end

    local modal = UI.Modal {
        title = "套装共鸣详情",
        size = "md",
        isOpen = false,
        closeOnOverlay = true,
        closeOnEscape = true,
        showCloseButton = true,
        contentPadding = 10,
        children = {
            UI.ScrollView {
                width = "100%",
                height = 320,
                scrollX = false,
                scrollY = true,
                showScrollbar = true,
                children = {
                    UI.Panel {
                        width = "100%",
                        gap = 6,
                        children = detailCards,
                    },
                },
            },
        },
    }
    modal:Open()
end

