function MakeActiveEquipmentResonancePanel(equipment)
    equipment = equipment or GetActiveEquipment()
    local counts = CountEquipmentResonanceSets(equipment)
    local tags = {}
    for _, setId in ipairs(EQUIPMENT_RESONANCE_ORDER or {}) do
        local def = GetEquipmentResonanceDef(setId)
        local count = counts[setId] or 0
        if def ~= nil and count > 0 then
            table.insert(tags, UI.Label {
                text = "[" .. def.shortName .. " " .. count .. "件]",
                fontSize = 9,
                fontColor = count >= 2 and def.color or PX.textGray,
                fontWeight = count >= 2 and "bold" or "normal",
                textAlign = "center",
            })
        end
    end
    if #tags == 0 then
        table.insert(tags, UI.Label {
            text = "暂无套装装备",
            fontSize = 9,
            fontColor = PX.textGray,
            textAlign = "center",
        })
    end
    local _, mixedDef = GetMixedEquipmentResonance(counts)
    local mixedText = mixedDef ~= nil
        and ("双套混搭 · " .. mixedDef.name .. "：" .. mixedDef.effect)
        or "双套混搭 · 两种不同套装各至少2件即可激活"
    return UI.Panel {
        width = "100%",
        paddingHorizontal = 8,
        paddingVertical = 5,
        gap = 4,
        backgroundColor = { 13, 12, 24, 220 },
        borderWidth = 1,
        borderColor = PX.goldDim,
        onClick = function(self)
            ShowEquipmentResonanceDetailModal(equipment)
        end,
        children = {
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                justifyContent = "space-between",
                alignItems = "center",
                children = {
                    UI.Label {
                        text = "套装共鸣",
                        fontSize = 10,
                        fontColor = PX.textGold,
                        fontWeight = "bold",
                    },
                    UI.Label {
                        text = "查看详情",
                        fontSize = 8,
                        fontColor = PX.textGray,
                    },
                },
            },
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                flexWrap = "wrap",
                justifyContent = "center",
                gap = 6,
                children = tags,
            },
            UI.Label {
                text = mixedText,
                fontSize = 8,
                fontColor = mixedDef ~= nil
                    and { 255, 190, 92, 255 }
                    or PX.textGray,
                fontWeight = mixedDef ~= nil and "bold" or "normal",
                textAlign = "center",
                whiteSpace = "normal",
            },
        },
    }
end

function MakeEquipmentResonanceComparisonPanel(
    equipment,
    newItem,
    replacementSlot
)
    equipment = equipment or GetActiveEquipment()
    local beforeCounts = CountEquipmentResonanceSets(equipment)
    local afterCounts = CountEquipmentResonanceSets(
        equipment,
        newItem,
        replacementSlot
    )
    local rows = {}
    for _, setId in ipairs(EQUIPMENT_RESONANCE_ORDER or {}) do
        local def = GetEquipmentResonanceDef(setId)
        local before = beforeCounts[setId] or 0
        local after = afterCounts[setId] or 0
        if def ~= nil and before ~= after then
            local changes = {}
            for _, threshold in ipairs(
                EQUIPMENT_RESONANCE_THRESHOLDS or {}
            ) do
                if before < threshold and after >= threshold then
                    table.insert(
                        changes,
                        "新增" .. threshold .. "件·"
                            .. (def.effects[threshold] or "")
                    )
                elseif before >= threshold and after < threshold then
                    table.insert(
                        changes,
                        "失去" .. threshold .. "件·"
                            .. (def.effects[threshold] or "")
                    )
                end
            end
            local changeText = #changes > 0
                and ("｜" .. table.concat(changes, "；"))
                or ""
            table.insert(rows, UI.Label {
                text = def.shortName .. " " .. before .. "→" .. after
                    .. "件" .. changeText,
                fontSize = 8,
                fontColor = after > before and def.color or PX.textGray,
                fontWeight = "bold",
                textAlign = "center",
                whiteSpace = "normal",
            })
        end
    end
    local beforeMixedId, beforeMixedDef =
        GetMixedEquipmentResonance(beforeCounts)
    local afterMixedId, afterMixedDef =
        GetMixedEquipmentResonance(afterCounts)
    if beforeMixedId ~= afterMixedId then
        local beforeText = beforeMixedDef ~= nil
            and beforeMixedDef.name
            or "未激活"
        local afterText = afterMixedDef ~= nil
            and (afterMixedDef.name .. "（" .. afterMixedDef.effect .. "）")
            or "未激活"
        table.insert(rows, UI.Label {
            text = "双套混搭 " .. beforeText .. " → " .. afterText,
            fontSize = 8,
            fontColor = afterMixedDef ~= nil
                and { 255, 190, 92, 255 }
                or PX.textGray,
            fontWeight = "bold",
            textAlign = "center",
            whiteSpace = "normal",
        })
    end
    if #rows == 0 then
        table.insert(rows, UI.Label {
            text = "套装共鸣无变化",
            fontSize = 8,
            fontColor = PX.textGray,
            textAlign = "center",
        })
    end
    return UI.Panel {
        width = "100%",
        padding = 6,
        gap = 3,
        alignItems = "center",
        backgroundColor = { 17, 16, 30, 235 },
        borderWidth = 1,
        borderColor = PX.goldDim,
        onClick = function(self)
            ShowEquipmentResonanceDetailModal(
                equipment,
                newItem,
                replacementSlot
            )
        end,
        children = {
            UI.Label {
                text = "套装共鸣变化 · 点击查看详情",
                fontSize = 9,
                fontColor = PX.textGold,
                fontWeight = "bold",
                textAlign = "center",
            },
            table.unpack(rows),
        },
    }
end

function MakeEquipmentIcon(itemOrSlotId, size, qualityDef)
    local iconPath = GetEquipmentIconPath(itemOrSlotId)
    local isItem = type(itemOrSlotId) == "table"
    local isAncient = isItem and IsAncientEquipment(itemOrSlotId)
    local borderColor = isAncient and GetEquipmentDisplayColor(itemOrSlotId)
        or (qualityDef and qualityDef.color or PX.goldDim)
    return UI.Panel {
        width = size,
        height = size,
        minWidth = size,
        minHeight = size,
        flexShrink = 0,
        justifyContent = "center",
        alignItems = "center",
        backgroundColor = GetEquipmentVisualBackground(itemOrSlotId, qualityDef),
        backgroundImage = iconPath,
        backgroundFit = "contain",
        borderWidth = isAncient and 3 or 2,
        borderColor = borderColor,
        children = {
            UI.Panel {
                position = "absolute",
                left = 1,
                right = 1,
                top = 1,
                height = 1,
                backgroundColor = { 255, 245, 205, isAncient and 145 or 72 },
            },
            UI.Panel {
                position = "absolute",
                left = 1,
                right = 1,
                bottom = 1,
                height = 2,
                backgroundColor = { 5, 4, 12, 150 },
            },
            isItem and MakeEquipmentResonanceBadge(
                GetEquipmentResonanceBadgeText(itemOrSlotId),
                math.max(7, math.min(9, math.floor(size * 0.24)))
            ) or nil,
            isItem and itemOrSlotId.viewed == false and MakeEquipmentUnreadDot(9) or nil,
            isAncient and UI.Label {
                text = "古",
                fontSize = 8,
                fontColor = { 70, 35, 8, 255 },
                fontWeight = "bold",
                textAlign = "center",
                position = "absolute",
                right = 1,
                top = 1,
                backgroundColor = { 255, 220, 105, 255 },
                borderWidth = 1,
                borderColor = { 115, 62, 16, 255 },
                paddingHorizontal = 3,
            } or (isItem and itemOrSlotId.synthesized == true) and UI.Label {
                text = "合",
                fontSize = 8,
                fontColor = { 255, 245, 220, 255 },
                fontWeight = "bold",
                textAlign = "center",
                position = "absolute",
                right = 1,
                top = 1,
                backgroundColor = { 130, 65, 35, 255 },
                borderWidth = 1,
                borderColor = { 245, 175, 90, 255 },
                paddingHorizontal = 3,
            } or nil,
        },
    }
end

function MakeRefineStoneIcon(size)
    size = size or 34
    return UI.Panel {
        width = size,
        height = size,
        minWidth = size,
        minHeight = size,
        flexShrink = 0,
        justifyContent = "center",
        alignItems = "center",
        backgroundColor = { 45, 30, 60, 220 },
        backgroundImage = REFINE_STONE_ICON,
        backgroundFit = "contain",
        borderWidth = 1,
        borderColor = { 220, 180, 255, 210 },
    }
end

function MakePinkRefineStoneIcon(size)
    size = size or 34
    return UI.Panel {
        width = size,
        height = size,
        minWidth = size,
        minHeight = size,
        flexShrink = 0,
        justifyContent = "center",
        alignItems = "center",
        backgroundColor = { 70, 30, 65, 220 },
        backgroundImage = PINK_REFINE_STONE_ICON,
        backgroundFit = "contain",
        borderWidth = 1,
        borderColor = { 255, 120, 220, 220 },
    }
end

function FindInventoryEquipmentIndex(item)
    for index, inventoryItem in ipairs(playerData.inventory) do
        if inventoryItem == item then
            return index
        end
    end
    return nil
end

function IsEquipmentUpgradeable(item)
    if item == nil then return false end
    return item.slot == "weapon"
        or item.slot == "armor"
        or item.slot == "boots"
        or item.slot == "gloves"
        or item.slot == "ring"
end

function ShowEquipmentRefinePage(item, slotId, inventoryIndex)
    currentScreen = "subpage"
    currentSubPage = "equip_refine"
    UpdateScreenMetrics()
    NormalizeEquipmentRefineState(item)

    local slotDef = EQUIPMENT_SLOT_BY_ID[slotId or item.slot]
    local qualityDef = GetEquipmentQualityDef(item.quality)
    local displayColor = GetEquipmentDisplayColor(item)
    local usePinkStone = item.quality == "colorful"
    local stoneName = usePinkStone and PINK_REFINE_STONE_NAME or REFINE_STONE_NAME
    local stoneCount = usePinkStone and GetPinkRefineStoneCount() or GetRefineStoneCount()
    local stoneCost = GetEquipmentRefineStoneCost(item)
    local canRefine = usePinkStone
        and IsColorfulEquipmentRefinable(item)
        or IsEquipmentRefinable(item)
    local content = {
        UI.Panel {
            width = "100%",
            padding = 10,
            gap = 5,
            alignItems = "center",
            backgroundColor = GetEquipmentCardBackground(item),
            borderWidth = IsAncientEquipment(item) and 3 or 1,
            borderColor = displayColor,
            children = {
                MakeEquipmentIcon(item, 54, qualityDef),
                UI.Label { text = GetEquipmentDisplayName(item), fontSize = 14, fontColor = displayColor, fontWeight = "bold", textAlign = "center" },
                UI.Label { text = (slotDef and slotDef.label or "装备") .. " | " .. GetEquipmentQualityLabel(item) .. " | 评分" .. GetEquipmentScore(item), fontSize = 10, fontColor = displayColor, textAlign = "center" },
                IsAncientEquipment(item) and UI.Label { text = "洗炼新词条按正常范围随机，太古标记与满值基础属性保留", fontSize = 9, fontColor = displayColor, textAlign = "center", whiteSpace = "normal" } or nil,
                UI.Panel {
                    flexDirection = "row",
                    justifyContent = "center",
                    alignItems = "center",
                    gap = 6,
                    children = {
                        usePinkStone and MakePinkRefineStoneIcon(28) or MakeRefineStoneIcon(28),
                        UI.Label { text = stoneName .. ": " .. stoneCount .. " | 本次消耗 " .. stoneCost, fontSize = uiLabelSize, fontColor = stoneCount >= stoneCost and PX.textGold or PX.textGray, textAlign = "center" },
                    },
                },
                UI.Label { text = GetEquipmentRefineStatusText(item), fontSize = 10, fontColor = canRefine and PX.textWhite or PX.textGray, textAlign = "center" },
                refineMessage and UI.Label { text = refineMessage, fontSize = 10, fontColor = refineMessage:find("成功") and PX.textGold or PX.textGray, textAlign = "center" } or nil,
            },
        },
    }

    if item.baseAffix then
        table.insert(content, UI.Panel {
            width = "100%",
            padding = 8,
            gap = 4,
            backgroundColor = { 18, 18, 32, 235 },
            borderWidth = 1,
            borderColor = PX.goldDim,
            children = {
                UI.Label { text = "基础词条不可洗炼", fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
                UI.Label { text = "基础 " .. MakeAffixDisplay(item.baseAffix), fontSize = 11, fontColor = PX.textGold, textAlign = "center" },
            },
        })
    end

    for index, affix in ipairs(item.affixes or {}) do
        local lockedIndex = item.refineAffixIndex
        local isFixed = affix.fixed == true
        local locked = lockedIndex ~= nil and lockedIndex ~= index
        local selected = lockedIndex == index
        local canClick = canRefine and not locked and not isFixed
        local buttonText = isFixed and "固定词条"
            or (locked and "已锁定" or (selected and "洗炼一次" or "选择并洗炼"))
        local refineRangeText = MakeEquipmentRefineRangeDisplay(item, affix)
        table.insert(content, UI.Panel {
            width = "100%",
            flexDirection = "row",
            padding = 8,
            gap = 8,
            alignItems = "center",
            backgroundColor = selected and { 70, 45, 25, 245 } or { 20, 20, 38, 240 },
            borderWidth = 1,
            borderColor = selected and PX.textGold or (locked and { 80, 80, 100, 160 } or PX.goldDim),
            children = {
                UI.Panel {
                    flexGrow = 1,
                    flexShrink = 1,
                    gap = 2,
                    children = {
                        UI.Label { text = "第" .. index .. "条 " .. MakeAffixDisplay(affix), fontSize = uiLabelSize, fontColor = selected and PX.textGold or PX.textWhite },
                        refineRangeText and UI.Label {
                            text = refineRangeText,
                            fontSize = 9,
                            fontColor = PX.textGold,
                        } or nil,
                        UI.Label {
                            text = isFixed and "彩色固定词条不可洗炼"
                                or (locked and "其他词条已锁定" or (selected and "已选定，可无限洗炼" or "可作为首次洗炼词条")),
                            fontSize = 9,
                            fontColor = PX.textGray,
                        },
                    },
                },
                UI.Panel {
                    width = 92,
                    height = 32,
                    flexShrink = 0,
                    justifyContent = "center",
                    alignItems = "center",
                    backgroundColor = canClick and PX.red or { 45, 45, 58, 220 },
                    borderWidth = 2,
                    borderColor = canClick and PX.redBright or { 90, 90, 110, 180 },
                    onClick = canClick and function(self)
                        local ok, message
                        if usePinkStone then
                            ok, message = TryPinkRefineEquipment(item, index, inventoryIndex)
                        else
                            ok, message = TryRefineEquipment(item, index, inventoryIndex)
                        end
                        refineMessage = message
                        ShowEquipmentRefinePage(item, slotId or item.slot, inventoryIndex)
                    end or nil,
                    children = {
                        UI.Label { text = buttonText, fontSize = 10, fontColor = canClick and PX.textWhite or PX.textGray, fontWeight = "bold", textAlign = "center" },
                    },
                },
            },
        })
    end

    if not canRefine then
        table.insert(content, UI.Label {
            text = usePinkStone and "该彩色装备没有可洗炼普通词条" or "没有可洗炼词条",
            fontSize = uiLabelSize,
            fontColor = PX.textGray,
            textAlign = "center",
        })
    end

    table.insert(content, UI.Panel {
        width = 120,
        height = 34,
        justifyContent = "center",
        alignItems = "center",
        backgroundColor = { 30, 30, 48, 255 },
        borderWidth = 2,
        borderColor = PX.goldDim,
        onClick = function(self)
            refineMessage = nil
            if inventoryIndex ~= nil then
                ShowInventoryEquipmentDetail(inventoryIndex)
            else
                ShowEquippedItemDetail(item, slotId or item.slot)
            end
        end,
        children = {
            UI.Label { text = inventoryIndex ~= nil and "返回背包详情" or "返回详情", fontSize = uiLabelSize, fontColor = PX.textWhite, textAlign = "center" },
        },
    })

    UI.SetRoot(BuildSubPage(
        "装备洗炼",
        content,
        inventoryIndex ~= nil and function()
            ShowInventoryEquipmentDetail(inventoryIndex)
        end or function()
            ShowEquippedItemDetail(item, slotId or item.slot)
        end,
        inventoryIndex ~= nil and "返回背包详情" or "返回装备详情"
    ), true)
end

function ShowEquippedItemDetail(item, slotId, inventoryIndex)
    currentScreen = "subpage"
    currentSubPage = "equip_detail"
    UpdateScreenMetrics()

    local slotDef = EQUIPMENT_SLOT_BY_ID[slotId]
    local qualityDef = GetEquipmentQualityDef(item.quality)
    local displayColor = GetEquipmentDisplayColor(item)
    local children = {
        UI.Label { text = slotDef.label .. (inventoryIndex ~= nil and " 背包装备" or " 当前装备"), fontSize = 13, fontColor = PX.textWhite, textAlign = "center" },
        UI.Panel {
            width = "100%",
            padding = 10,
            gap = 5,
            alignItems = "center",
            backgroundColor = GetEquipmentCardBackground(item),
            borderWidth = IsAncientEquipment(item) and 3 or 1,
            borderColor = displayColor,
            children = {
                MakeEquipmentIcon(item, 58, qualityDef),
                UI.Label { text = GetEquipmentDisplayName(item), fontSize = 14, fontColor = displayColor, fontWeight = "bold", textAlign = "center" },
                UI.Label { text = GetEquipmentQualityLabel(item) .. " | 第" .. (item.floor or 1) .. "层 | 评分" .. GetEquipmentScore(item), fontSize = 10, fontColor = displayColor, textAlign = "center" },
                IsAncientEquipment(item) and UI.Label { text = "太古掉落属性：基础满值，初始随机词条满值", fontSize = 9, fontColor = displayColor, textAlign = "center" } or nil,
                item.synthesized == true and UI.Label { text = "合成装备 · 不可再次合成", fontSize = 9, fontColor = PX.textGray, textAlign = "center" } or nil,
            },
        },
    }

    table.insert(children, MakeEquipmentResonanceItemPanel(
        item,
        GetActiveEquipment(),
        inventoryIndex ~= nil and slotId or nil,
        false
    ))

    local function ReturnToEquipmentDetail()
        ShowEquippedItemDetail(item, slotId, inventoryIndex)
    end
    table.insert(children, MakeEquipmentSocketPanel(
        item,
        function()
            ShowGemSocketSelectionPage(item, ReturnToEquipmentDetail)
        end,
        GetSocketPuncherCount() > 0 and function()
            local ok, message = UseSocketPuncherOnEquipment(item)
            if ok then
                AddEffect({
                    type = "drop",
                    x = screenW * 0.5,
                    y = screenH * 0.35,
                    text = message,
                    life = 1.0,
                    maxLife = 1.0,
                })
            end
            ShowEquippedItemDetail(item, slotId, inventoryIndex)
        end or nil
    ))

    local affixRows = {}
    if item.baseAffix then
        table.insert(affixRows, UI.Label { text = "基础 " .. MakeBaseAffixDisplay(item), fontSize = 10, fontColor = PX.textGold, textAlign = "center", whiteSpace = "normal" })
    end
    for _, affix in ipairs(item.affixes or {}) do
        table.insert(affixRows, UI.Label { text = MakeAffixDisplay(affix), fontSize = 10, fontColor = PX.textWhite, textAlign = "center" })
    end
    table.insert(children, UI.Panel {
        width = "100%",
        padding = 10,
        gap = 4,
        alignItems = "center",
        backgroundColor = { 20, 20, 38, 240 },
        borderWidth = 1,
        borderColor = PX.goldDim,
        children = affixRows,
    })

    local canRefine = IsAnyEquipmentRefinable(item)
    local usePinkStone = item.quality == "colorful"
    local refineStoneCount = usePinkStone and GetPinkRefineStoneCount() or GetRefineStoneCount()
    local refineStoneName = usePinkStone and PINK_REFINE_STONE_NAME or REFINE_STONE_NAME
    table.insert(children, UI.Panel {
        width = "100%",
        padding = 10,
        gap = 6,
        alignItems = "center",
        backgroundColor = { 18, 18, 32, 245 },
        borderWidth = 1,
        borderColor = canRefine and { 220, 180, 255, 190 } or { 90, 90, 110, 160 },
        children = {
            UI.Label { text = "装备洗炼", fontSize = uiValueSize, fontColor = canRefine and PX.textGold or PX.textGray, fontWeight = "bold", textAlign = "center" },
            UI.Panel {
                flexDirection = "row",
                justifyContent = "center",
                alignItems = "center",
                gap = 6,
                children = {
                    usePinkStone and MakePinkRefineStoneIcon(26) or MakeRefineStoneIcon(26),
                    UI.Label { text = GetEquipmentRefineStatusText(item) .. "｜" .. refineStoneName .. ": " .. refineStoneCount .. "｜本次消耗: " .. GetEquipmentRefineStoneCost(item), fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
                },
            },
            UI.Panel {
                width = "100%",
                height = 34,
                justifyContent = "center",
                alignItems = "center",
                backgroundColor = canRefine and PX.red or { 45, 45, 58, 210 },
                borderWidth = 2,
                borderColor = canRefine and PX.redBright or { 90, 90, 110, 180 },
                onClick = canRefine and function(self)
                    refineMessage = nil
                    ShowEquipmentRefinePage(item, slotId, inventoryIndex)
                end or nil,
                children = {
                    UI.Label { text = canRefine and "洗炼" or "不可洗炼", fontSize = uiLabelSize, fontColor = canRefine and PX.textWhite or PX.textGray, fontWeight = "bold", textAlign = "center" },
                },
            },
        },
    })

    if slotId == "weapon" then
        item.weaponUpgradeLevel = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, item.weaponUpgradeLevel or 0))
        local level = item.weaponUpgradeLevel
        local attackBonus = GetWeaponUpgradeAttackPercent(level)
        local rangeBonus = GetWeaponUpgradeRangePercent(level)
        local successRate = GetWeaponUpgradeSuccessRate(level)
        local cost = GetWeaponUpgradeCost(level, item)
        local maxed = level >= CONFIG.WeaponUpgradeMaxLevel
        local canProtectedUpgrade = not maxed
            and level <= (CONFIG.EquipmentProtectedUpgradeMaxLevel or 16)
        table.insert(children, UI.Panel {
            width = "100%",
            padding = 10,
            gap = 6,
            alignItems = "center",
            backgroundColor = { 18, 18, 32, 245 },
            borderWidth = 1,
            borderColor = { 120, 210, 255, 170 },
            children = {
                UI.Label { text = "武器强化 Lv." .. level .. "/" .. CONFIG.WeaponUpgradeMaxLevel, fontSize = uiValueSize, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
                UI.Label { text = "武器可消耗金币强化，提升攻击力和攻击范围", fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
                UI.Label { text = "基础攻击力 +" .. attackBonus .. "%  攻击范围 +" .. rangeBonus .. "%", fontSize = uiLabelSize, fontColor = PX.textWhite, textAlign = "center" },
                UI.Label { text = maxed and "已满级" or ("成功率 " .. successRate .. "%｜消耗 " .. cost .. " 金币"), fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
                weaponUpgradeMessage and UI.Label { text = weaponUpgradeMessage, fontSize = uiLabelSize, fontColor = PX.textGold, textAlign = "center" } or UI.Panel { width = 0, height = 0 },
                UI.Panel {
                    width = "100%",
                    height = 34,
                    justifyContent = "center",
                    alignItems = "center",
                    backgroundColor = (not maxed and playerData.gold >= cost) and PX.red or { 45, 45, 58, 210 },
                    borderWidth = 2,
                    borderColor = (not maxed and playerData.gold >= cost) and PX.redBright or { 90, 90, 110, 180 },
                    onClick = function(self)
                        TryUpgradeWeapon(item, inventoryIndex)
                    end,
                    children = {
                        UI.Label { text = maxed and "强化已满" or "强化武器", fontSize = uiLabelSize, fontColor = PX.textWhite, fontWeight = "bold", textAlign = "center" },
                    },
                },
                UI.Panel {
                    width = "100%",
                    height = 34,
                    justifyContent = "center",
                    alignItems = "center",
                    backgroundColor = (canProtectedUpgrade and playerData.gold >= cost * 3)
                        and { 85, 55, 28, 245 }
                        or { 45, 45, 58, 210 },
                    borderWidth = 2,
                    borderColor = (canProtectedUpgrade and playerData.gold >= cost * 3)
                        and { 245, 190, 85, 230 }
                        or { 90, 90, 110, 180 },
                    onClick = canProtectedUpgrade and function(self)
                        TryUpgradeEquipment(item, inventoryIndex, true)
