                UI.Label { text = "鞋子强化 Lv." .. level .. "/" .. CONFIG.WeaponUpgradeMaxLevel, fontSize = uiValueSize, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
                UI.Label { text = "鞋子可消耗金币强化，提升基础暴击伤害", fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
