function IsEquipmentSelectedForSynthesis(item)
    for index, selectedItem in ipairs(equipmentSynthesisSelection) do
        if selectedItem == item then
            return true, index
        end
    end
    return false, nil
end

function ResetEquipmentSynthesisSelection()
    equipmentSynthesisSelection = {}
    equipmentSynthesisConfirmPending = false
end

function SelectEquipmentSynthesisQuality(quality)
    if equipmentSynthesisQualityFilter == quality then return end
    equipmentSynthesisQualityFilter = quality
    ResetEquipmentSynthesisSelection()
    equipmentSynthesisMessage = nil
    equipmentSynthesisResult = nil
    print("[Synthesis] 切换材料品质:", quality)
end

function ShowEquipmentSynthesisPage()
    currentScreen = "subpage"
    currentSubPage = "equip_synthesis"
    UpdateScreenMetrics()

    local inventorySet = {}
    for _, item in ipairs(playerData.inventory or {}) do
        inventorySet[item] = true
    end
    for index = #equipmentSynthesisSelection, 1, -1 do
        local item = equipmentSynthesisSelection[index]
        if not inventorySet[item]
            or not CanUseEquipmentAsSynthesisMaterial(item) then
            table.remove(equipmentSynthesisSelection, index)
            equipmentSynthesisConfirmPending = false
        end
    end

    local selectedQuality = equipmentSynthesisQualityFilter
    if selectedQuality ~= nil
        and EQUIPMENT_SYNTHESIS_RESULT_QUALITY[selectedQuality] == nil then
        selectedQuality = nil
        equipmentSynthesisQualityFilter = nil
        ResetEquipmentSynthesisSelection()
    end
    for index = #equipmentSynthesisSelection, 1, -1 do
        if equipmentSynthesisSelection[index].quality ~= selectedQuality then
            table.remove(equipmentSynthesisSelection, index)
            equipmentSynthesisConfirmPending = false
        end
    end

    local preview = nil
    if #equipmentSynthesisSelection > 0 then
        preview = GetEquipmentSynthesisPreview(equipmentSynthesisSelection)
    end

    local content = {
        UI.Panel {
            width = "100%",
            padding = 9,
            gap = 5,
            alignItems = "center",
            backgroundColor = { 20, 20, 38, 240 },
            borderWidth = 1,
            borderColor = PX.goldDim,
            children = {
                UI.Label {
                    text = "五件同品质装备合成一件全新装备",
                    fontSize = 12,
                    fontColor = PX.textGold,
                    fontWeight = "bold",
                    textAlign = "center",
                },
                UI.Label {
                    text = "蓝色、紫色免费｜橙色、红色每次消耗100万金币",
                    fontSize = 9,
                    fontColor = PX.textWhite,
                    textAlign = "center",
                },
                UI.Label {
                    text = "锁定、太古、彩色、已强化、已镶嵌宝石和合成产物不可作为材料",
                    fontSize = 9,
                    fontColor = PX.textGray,
                    textAlign = "center",
                    whiteSpace = "normal",
                },
            },
        },
    }

    local qualityFilterButtons = {}
    for _, quality in ipairs({ "blue", "purple", "orange", "red" }) do
        local buttonQuality = quality
        local qualityDef = GetEquipmentQualityDef(buttonQuality)
        local active = selectedQuality == buttonQuality
        table.insert(qualityFilterButtons, UI.Panel {
            flexGrow = 1,
            height = 34,
            justifyContent = "center",
            alignItems = "center",
            backgroundColor = active and GetEquipmentVisualBackground({ type = "equipment", quality = buttonQuality }, qualityDef) or { 28, 28, 44, 245 },
            borderWidth = active and 3 or 1,
            borderColor = active and qualityDef.color or { 85, 85, 105, 190 },
            onClick = function(self)
                SelectEquipmentSynthesisQuality(buttonQuality)
                ShowEquipmentSynthesisPage()
            end,
            children = {
                UI.Label {
                    text = qualityDef.label,
                    fontSize = 10,
                    fontColor = active and qualityDef.color or PX.textGray,
                    fontWeight = active and "bold" or "normal",
                    textAlign = "center",
                },
            },
        })
    end
    table.insert(content, UI.Panel {
        width = "100%",
        padding = 8,
        gap = 6,
        backgroundColor = { 18, 18, 32, 235 },
        borderWidth = 1,
        borderColor = selectedQuality and GetEquipmentQualityDef(selectedQuality).color or PX.goldDim,
        children = {
            UI.Label { text = "选择材料品质", fontSize = 11, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                gap = 6,
                children = qualityFilterButtons,
            },
            UI.Label {
                text = selectedQuality == "red"
                    and "红色合成仍产出红色装备：材料平均层数+10"
                    or (selectedQuality and "仅显示所选品质的可合成装备" or "请先选择品质，再选择5件装备"),
                fontSize = 9,
                fontColor = selectedQuality == "red" and PX.textGold or PX.textGray,
                textAlign = "center",
            },
        },
    })

    if equipmentSynthesisResult ~= nil then
        local result = equipmentSynthesisResult
        local qualityDef = GetEquipmentQualityDef(result.quality)
        local displayColor = GetEquipmentDisplayColor(result)
        table.insert(content, UI.Panel {
            width = "100%",
            padding = 10,
            gap = 5,
            alignItems = "center",
            backgroundColor = GetEquipmentCardBackground(result),
            borderWidth = IsAncientEquipment(result) and 3 or 2,
            borderColor = displayColor,
            children = {
                UI.Label {
                    text = IsAncientEquipment(result) and "合成成功 · 太古产物不会自动锁定" or "合成成功",
                    fontSize = 12,
                    fontColor = displayColor,
                    fontWeight = "bold",
                    textAlign = "center",
                },
                MakeEquipmentIcon(result, 58, qualityDef),
                UI.Label {
                    text = GetEquipmentDisplayName(result),
                    fontSize = 13,
                    fontColor = displayColor,
                    fontWeight = "bold",
                    textAlign = "center",
                },
                UI.Label {
                    text = GetEquipmentQualityLabel(result)
                        .. "｜第" .. (result.floor or 1) .. "层｜评分" .. GetEquipmentScore(result),
                    fontSize = 10,
                    fontColor = displayColor,
                    textAlign = "center",
                },
                UI.Label {
                    text = "合成装备 · 不可再次合成",
                    fontSize = 9,
                    fontColor = PX.textGray,
                    textAlign = "center",
                },
            },
        })
    end

    local selectedColor = selectedQuality
        and GetEquipmentQualityDef(selectedQuality).color
        or PX.goldDim
    table.insert(content, UI.Panel {
        width = "100%",
        padding = 8,
        gap = 5,
        backgroundColor = { 18, 18, 32, 235 },
        borderWidth = 1,
        borderColor = selectedColor,
        children = {
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                alignItems = "center",
                children = {
                    UI.Label {
                        text = "已选材料 " .. #equipmentSynthesisSelection .. "/5",
                        fontSize = 11,
                        fontColor = selectedQuality and selectedColor or PX.textGold,
                        fontWeight = "bold",
                        flexGrow = 1,
                    },
                    UI.Label {
                        text = selectedQuality
                            and (GetEquipmentQualityDef(selectedQuality).label .. "品质")
                            or "请选择首件材料",
                        fontSize = 9,
                        fontColor = PX.textGray,
                    },
                },
            },
        },
    })

    if #equipmentSynthesisSelection > 0 then
        local selectedCells = {}
        for _, item in ipairs(equipmentSynthesisSelection) do
            local qualityDef = GetEquipmentQualityDef(item.quality)
            table.insert(selectedCells, UI.Panel {
                width = 54,
                height = 62,
                alignItems = "center",
                justifyContent = "center",
                gap = 2,
                backgroundColor = GetEquipmentVisualBackground(item, qualityDef),
                borderWidth = 2,
                borderColor = GetEquipmentDisplayColor(item),
                children = {
                    MakeEquipmentIcon(item, 40, qualityDef),
                    UI.Label {
                        text = "层" .. math.floor(item.floor or 1),
                        fontSize = 8,
                        fontColor = PX.textWhite,
                        textAlign = "center",
                    },
                },
            })
        end
        table.insert(content, UI.Panel {
            width = "100%",
            flexDirection = "row",
            flexWrap = "wrap",
            justifyContent = "center",
            gap = 5,
            children = selectedCells,
        })
    end

    if preview ~= nil then
        local resultQualityDef = GetEquipmentQualityDef(preview.resultQuality)
        table.insert(content, UI.Panel {
            width = "100%",
            padding = 9,
            gap = 4,
            alignItems = "center",
            backgroundColor = { 25, 20, 38, 244 },
            borderWidth = 2,
            borderColor = resultQualityDef.color,
            children = {
                UI.Label {
                    text = "产物预览",
                    fontSize = 11,
                    fontColor = resultQualityDef.color,
                    fontWeight = "bold",
                    textAlign = "center",
                },
                UI.Label {
                    text = GetEquipmentQualityDef(preview.sourceQuality).label
                        .. " → " .. resultQualityDef.label
                        .. "｜材料平均层数 " .. preview.averageFloor
                        .. "｜消耗 " .. (preview.cost or 0) .. " 金币",
                    fontSize = 10,
                    fontColor = PX.textWhite,
                    textAlign = "center",
                },
                UI.Label {
                    text = "产物层数 " .. preview.resultFloor
                        .. (preview.sourceQuality == "red" and "（平均层数+10）" or "")
                        .. "｜太古概率 " .. preview.ancientChance .. "%",
                    fontSize = 10,
                    fontColor = preview.ancientChance > 0 and PX.textGold or PX.textGray,
                    textAlign = "center",
                },
                UI.Label {
                    text = "名称、部位、基础属性、随机词条和武器外观全部重新生成",
                    fontSize = 9,
                    fontColor = PX.textGray,
                    textAlign = "center",
                    whiteSpace = "normal",
                },
            },
        })
    end

    local materialRows = {}
    local materialEntries = {}
    if selectedQuality ~= nil then
        for inventoryIndex, item in ipairs(playerData.inventory or {}) do
            if item.quality == selectedQuality
                and GetEquipmentSynthesisBlockReason(item) == nil then
                table.insert(materialEntries, {
                    item = item,
                    inventoryIndex = inventoryIndex,
                    floor = math.max(1, math.floor(item.floor or 1)),
                    score = GetEquipmentScore(item),
                })
            end
        end
        table.sort(materialEntries, function(a, b)
            if a.floor ~= b.floor then return a.floor > b.floor end
            if a.score ~= b.score then return a.score > b.score end
            return a.inventoryIndex < b.inventoryIndex
        end)
    end

    local availableCount = #materialEntries
    for _, entry in ipairs(materialEntries) do
        local item = entry.item
        local selected = IsEquipmentSelectedForSynthesis(item)
        local selectable = selected or #equipmentSynthesisSelection < 5
        local qualityDef = GetEquipmentQualityDef(item.quality)
        local displayColor = GetEquipmentDisplayColor(item)
        local slotDef = EQUIPMENT_SLOT_BY_ID[item.slot]
        local statusText = selected and "已选择"
            or (#equipmentSynthesisSelection >= 5 and "已选满" or "点击选择")
        table.insert(materialRows, UI.Panel {
            width = "100%",
            minHeight = 50,
            flexDirection = "row",
            alignItems = "center",
            padding = 6,
            gap = 7,
            backgroundColor = selected and { 61, 44, 30, 248 } or GetEquipmentCardBackground(item),
            borderWidth = selected and 3 or 1,
            borderColor = selected and PX.gold or displayColor,
            onClick = selectable and function(self)
                local isSelected, selectedIndex = IsEquipmentSelectedForSynthesis(item)
                if isSelected then
                    table.remove(equipmentSynthesisSelection, selectedIndex)
                else
                    table.insert(equipmentSynthesisSelection, item)
                end
                equipmentSynthesisConfirmPending = false
                equipmentSynthesisMessage = nil
                equipmentSynthesisResult = nil
                ShowEquipmentSynthesisPage()
            end or nil,
            children = {
                MakeEquipmentIcon(item, 40, qualityDef),
                UI.Panel {
                    flexGrow = 1,
                    flexShrink = 1,
                    gap = 2,
                    children = {
                        UI.Label {
                            text = GetEquipmentDisplayName(item),
                            fontSize = 10,
                            fontColor = displayColor,
                            fontWeight = "bold",
                            maxLines = 1,
                        },
                        UI.Label {
                            text = (slotDef and slotDef.label or "装备")
                                .. "｜" .. GetEquipmentQualityLabel(item)
                                .. "｜层" .. entry.floor
                                .. "｜评分" .. entry.score,
                            fontSize = 8,
                            fontColor = PX.textGray,
                            maxLines = 1,
                        },
                    },
                },
                UI.Label {
                    text = statusText,
                    fontSize = 9,
                    fontColor = selected and PX.textGold or (selectable and PX.textWhite or PX.textGray),
                    fontWeight = selected and "bold" or "normal",
                    flexShrink = 0,
                },
            },
        })
    end

    local canSynthesize = #equipmentSynthesisSelection == 5
        and preview ~= nil
        and (playerData.gold or 0) >= (preview and preview.cost or 0)
    local unreadSelectedCount = 0
    for _, item in ipairs(equipmentSynthesisSelection) do
        if item.viewed == false then unreadSelectedCount = unreadSelectedCount + 1 end
    end
    local actionText = "请选择5件材料"
    if #equipmentSynthesisSelection == 5 and preview ~= nil
        and (playerData.gold or 0) < (preview.cost or 0) then
        actionText = "金币不足（需要" .. (preview.cost or 0) .. "）"
    elseif canSynthesize then
        actionText = equipmentSynthesisConfirmPending
            and "再次点击 · 消耗" .. (preview.cost or 0) .. "金币与5件材料"
            or "确认合成（" .. (preview.cost or 0) .. "金币）"
    end
    table.insert(content, UI.Panel {
        width = "100%",
        flexDirection = "row",
        gap = 8,
        children = {
            UI.Panel {
                width = 86,
                height = 36,
                flexShrink = 0,
                justifyContent = "center",
                alignItems = "center",
                backgroundColor = #equipmentSynthesisSelection > 0 and { 35, 35, 55, 255 } or { 45, 45, 58, 210 },
                borderWidth = 2,
                borderColor = #equipmentSynthesisSelection > 0 and PX.goldDim or { 80, 80, 95, 180 },
                onClick = #equipmentSynthesisSelection > 0 and function(self)
                    ResetEquipmentSynthesisSelection()
                    equipmentSynthesisMessage = nil
                    equipmentSynthesisResult = nil
                    ShowEquipmentSynthesisPage()
                end or nil,
                children = {
                    UI.Label {
                        text = "清空选择",
                        fontSize = 10,
                        fontColor = #equipmentSynthesisSelection > 0 and PX.textWhite or PX.textGray,
                        textAlign = "center",
                    },
                },
            },
            UI.Panel {
                flexGrow = 1,
                height = 36,
                justifyContent = "center",
                alignItems = "center",
                backgroundColor = canSynthesize and PX.red or { 45, 45, 58, 210 },
                borderWidth = 2,
                borderColor = canSynthesize and PX.redBright or { 90, 90, 110, 180 },
                onClick = canSynthesize and function(self)
                    if not equipmentSynthesisConfirmPending then
                        equipmentSynthesisConfirmPending = true
                        equipmentSynthesisMessage = unreadSelectedCount > 0
                            and ("所选材料含" .. unreadSelectedCount .. "件未查看装备，合成不可撤销，请再次点击确认")
                            or "合成不可撤销，请再次点击确认"
                        ShowEquipmentSynthesisPage()
                        return
                    end
                    local result, message = SynthesizeEquipment(equipmentSynthesisSelection)
                    if result ~= nil then
                        equipmentSynthesisResult = result
                        equipmentSynthesisMessage = IsAncientEquipment(result)
                            and "合成成功，太古产物不会自动锁定"
                            or "合成成功，产物已进入背包"
                        ResetEquipmentSynthesisSelection()
                    else
                        equipmentSynthesisMessage = message or "合成失败"
                        equipmentSynthesisConfirmPending = false
                    end
                    ShowEquipmentSynthesisPage()
                end or nil,
                children = {
                    UI.Label {
                        text = actionText,
                        fontSize = 10,
                        fontColor = canSynthesize and PX.textWhite or PX.textGray,
                        fontWeight = "bold",
                        textAlign = "center",
                    },
                },
            },
        },
    })

    if equipmentSynthesisMessage ~= nil then
        table.insert(content, UI.Label {
            text = equipmentSynthesisMessage,
            fontSize = 10,
            fontColor = equipmentSynthesisMessage:find("成功") and PX.textGold or PX.textGray,
            textAlign = "center",
            whiteSpace = "normal",
        })
    end

    table.insert(content, MakeEquipmentSectionTitle(
        "可用材料 · " .. availableCount .. "件",
        selectedColor,
        selectedQuality and "按装备层数由高到低排列" or "请先选择材料品质"
    ))
    if #materialRows > 0 then
        for _, row in ipairs(materialRows) do
            table.insert(content, row)
        end
    else
        table.insert(content, UI.Label {
            text = "暂无可用于合成的装备",
            fontSize = 10,
            fontColor = PX.textGray,
            textAlign = "center",
        })
    end

    UI.SetRoot(BuildSubPage(
        "装备合成",
        content,
        function()
            ResetEquipmentSynthesisSelection()
            equipmentSynthesisMessage = nil
            equipmentSynthesisResult = nil
            GameEvents.Emit("scene:equip")
        end,
        "← 返回装备"
    ), true)
    print("[Page] 装备合成，已选:", #equipmentSynthesisSelection)
end

function ShowEquipmentPage()
    currentScreen = "subpage"
    currentSubPage = "equip"
    UpdateScreenMetrics()

    NormalizeEquipment()
    local eq = GetActiveEquipment()
    local activeSetIndex = GetActiveEquipmentSetIndex()
    local setTabs = {}
    for index = 1, EQUIPMENT_SET_COUNT do
        local active = index == activeSetIndex
        table.insert(setTabs, UI.Panel {
            flexGrow = 1,
            height = 32,
            justifyContent = "center",
            alignItems = "center",
            backgroundColor = active and PX.red or { 30, 30, 48, 255 },
            borderWidth = 2,
            borderColor = active and PX.redBright or PX.goldDim,
            onClick = function(self)
                if SetActiveEquipmentSetIndex(index) then
                    GameEvents.Emit("scene:equip")
                end
            end,
            children = {
                UI.Label { text = EQUIPMENT_SET_NAMES[index] or ("套" .. index), fontSize = 11, fontColor = active and PX.textWhite or PX.textGold, fontWeight = "bold", textAlign = "center" },
            },
        })
    end

    local equippedRows = {}
    for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS) do
        local item = eq[slotDef.id]
        local hasItem = item ~= nil
        local qualityDef = hasItem and GetEquipmentQualityDef(item.quality) or nil
        local displayColor = hasItem and GetEquipmentDisplayColor(item) or PX.goldDim
        local upgradeHint = nil
        if slotDef.id == "weapon" and hasItem then
            local level = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, item.weaponUpgradeLevel or 0))
            upgradeHint = level > 0 and ("强化 Lv." .. level) or "可强化"
        elseif slotDef.id == "armor" and hasItem then
            local level = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, item.armorUpgradeLevel or 0))
            upgradeHint = level > 0 and ("强化 Lv." .. level) or "可强化"
        elseif slotDef.id == "boots" and hasItem then
            local level = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, item.bootsUpgradeLevel or 0))
            upgradeHint = level > 0 and ("强化 Lv." .. level) or "可强化"
        elseif slotDef.id == "gloves" and hasItem then
            local level = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, item.glovesUpgradeLevel or 0))
            upgradeHint = level > 0 and ("强化 Lv." .. level) or "可强化"
        elseif slotDef.id == "ring" and hasItem then
            local level = math.max(0, math.min(CONFIG.WeaponUpgradeMaxLevel, item.ringUpgradeLevel or 0))
            upgradeHint = level > 0 and ("强化 Lv." .. level) or "可强化"
        end
        local labelText = slotDef.label .. ": "
        if hasItem then
            labelText = labelText .. GetEquipmentDisplayName(item) .. " (" .. GetEquipmentQualityLabel(item) .. ")"
        else
            labelText = labelText .. "空"
        end
        table.insert(equippedRows, UI.Panel {
            width = "100%",
            minHeight = 46,
            flexDirection = "row",
            padding = 6,
            gap = 7,
            alignItems = "center",
            backgroundColor = hasItem and GetEquipmentCardBackground(item) or { 20, 18, 34, 244 },
            borderWidth = hasItem and IsAncientEquipment(item) and 3 or { 1, 1, 2, 1 },
            borderColor = hasItem and displayColor or PX.goldDim,
            onClick = hasItem and function(self)
                ShowEquippedItemDetail(item, slotDef.id)
            end or nil,
            children = {
                MakeEquipmentIcon(hasItem and item or slotDef.id, 34, qualityDef),
                UI.Label { text = slotDef.label, fontSize = 10, fontColor = PX.textGray, width = 38, flexShrink = 0 },
                UI.Label {
                    text = hasItem and GetEquipmentDisplayName(item) or "空",
                    fontSize = 11,
                    fontColor = hasItem and displayColor or PX.textGray,
                    fontWeight = hasItem and "bold" or "normal",
                    flexGrow = 1,
                    flexShrink = 1,
                    maxLines = 1,
                    textStroke = hasItem and { width = 1, color = { 8, 6, 16, 210 } } or nil,
                },
                upgradeHint and UI.Label {
                    text = upgradeHint,
                    fontSize = 9,
                    fontColor = PX.textGold,
                    fontWeight = "bold",
                    flexShrink = 0,
                } or nil,
                hasItem and UI.Label {
                    text = "孔 " .. tostring(GetEquipmentSocketedGemCount(item))
                        .. "/" .. tostring(GetEquipmentSocketCount(item)),
                    fontSize = 8,
                    fontColor = { 165, 220, 255, 255 },
                    fontWeight = "bold",
                    flexShrink = 0,
                    backgroundColor = { 8, 12, 22, 220 },
                    borderWidth = 1,
                    borderColor = { 90, 155, 205, 210 },
                    paddingHorizontal = 4,
                    paddingVertical = 2,
                } or nil,
                hasItem and UI.Label {
                    text = GetEquipmentQualityLabel(item),
                    fontSize = 9,
                    fontColor = displayColor,
                    fontWeight = "bold",
                    flexShrink = 0,
                    backgroundColor = { 10, 8, 18, 190 },
                    borderWidth = 1,
                    borderColor = displayColor,
                    paddingHorizontal = 4,
                    paddingVertical = 2,
                } or nil,
            },
        })
    end

    local equipmentData = {}
    local materialRows = {}
    local materialStackCount = 0
    local gemMaterialRows = {}
    for inventoryIndex, item in ipairs(playerData.inventory) do
        if item.type == "equipment" then
            table.insert(equipmentData, {
                index = inventoryIndex,
                item = item,
            })
        elseif item.type == "material" then
            materialStackCount = materialStackCount + 1
            if IsGemItem(item) then
                local gemType = item.gemType
                local gemLevel = math.max(1, math.min(GEM_MAX_LEVEL, math.floor(item.gemLevel or 1)))
                local gemOrderIndex = 0
                for gi, gt in ipairs(GEM_ORDER or {}) do
                    if gt == gemType then gemOrderIndex = gi break end
                end
                local def = GetGemDef(gemType)
                table.insert(gemMaterialRows, {
                    level = gemLevel,
                    orderIndex = gemOrderIndex,
                    gemType = gemType,
                    gemLevel = gemLevel,
                    def = def,
                    row = UI.Panel {
                        width = "100%",
                        minHeight = 58,
                        flexDirection = "row",
                        padding = 7,
                        gap = 9,
                        alignItems = "center",
                        backgroundColor = { 20, 20, 38, 240 },
                        borderWidth = { 1, 1, 2, 1 },
                        borderColor = def and def.color or PX.goldDim,
                        onClick = function(self)
                            equipmentBackpackTab = "material"
                            ShowGemSynthesisPage(gemType, nil, "scene:equip")
                        end,
                        children = {
                            MakeGemIcon(gemType, 46),
                            UI.Panel {
                                flexGrow = 1,
                                flexShrink = 1,
                                gap = 2,
                                children = {
                                    UI.Label {
                                        text = GetGemDisplayName(gemType, gemLevel),
                                        fontSize = 11,
                                        fontColor = def and def.color or PX.textGold,
                                        fontWeight = "bold",
                                    },
                                    UI.Label {
                                        text = "数量 x" .. tostring(item.count or 1),
                                        fontSize = 9,
                                        fontColor = PX.textWhite,
                                    },
                                    UI.Label {
                                        text = GetGemEffectText(gemType, gemLevel) .. "｜点击合成",
                                        fontSize = 8,
                                        fontColor = PX.textGray,
                                    },
                                },
                            },
                            UI.Label {
                                text = "合成 >",
                                width = 48,
                                flexShrink = 0,
                                fontSize = 9,
                                fontColor = PX.textGold,
                                textAlign = "center",
                            },
                        },
                    },
                })
            elseif IsPinkRefineStoneItem(item) then
                table.insert(materialRows, UI.Panel {
                    width = "100%",
                    minHeight = 58,
                    flexDirection = "row",
                    padding = 7,
                    gap = 9,
                    alignItems = "center",
                    backgroundColor = { 30, 20, 42, 240 },
                    borderWidth = { 1, 1, 2, 1 },
                    borderColor = { 255, 120, 220, 210 },
                    children = {
                        MakePinkRefineStoneIcon(46),
                        UI.Panel {
                            flexGrow = 1,
                            flexShrink = 1,
                            gap = 2,
                            children = {
                                UI.Label {
                                    text = item.name or PINK_REFINE_STONE_NAME,
                                    fontSize = 11,
                                    fontColor = { 255, 145, 225, 255 },
                                    fontWeight = "bold",
                                },
                                UI.Label {
                                    text = "数量 x" .. tostring(item.count or 1),
                                    fontSize = 9,
                                    fontColor = PX.textWhite,
                                },
                                UI.Label {
                                    text = "仅用于彩色装备普通词条洗炼",
                                    fontSize = 8,
                                    fontColor = PX.textGray,
                                },
                            },
                        },
                    },
                })
            elseif IsSocketPuncherItem(item) then
                table.insert(materialRows, UI.Panel {
                    width = "100%",
                    minHeight = 58,
                    flexDirection = "row",
                    padding = 7,
                    gap = 9,
                    alignItems = "center",
                    backgroundColor = { 49, 34, 20, 240 },
                    borderWidth = { 1, 1, 2, 1 },
                    borderColor = { 245, 190, 85, 220 },
                    children = {
                        UI.Panel {
                            width = 46,
                            height = 46,
                            flexShrink = 0,
                            justifyContent = "center",
                            alignItems = "center",
                            backgroundColor = { 85, 55, 28, 245 },
                            borderWidth = 2,
                            borderColor = { 245, 190, 85, 230 },
                            children = {
                                UI.Label {
                                    text = "孔",
                                    fontSize = 17,
                                    fontColor = { 255, 220, 130, 255 },
                                    fontWeight = "bold",
                                    textAlign = "center",
                                },
                            },
                        },
                        UI.Panel {
                            flexGrow = 1,
                            flexShrink = 1,
                            gap = 2,
                            children = {
                                UI.Label {
                                    text = item.name or SOCKET_PUNCHER_NAME,
                                    fontSize = 11,
                                    fontColor = { 255, 220, 130, 255 },
                                    fontWeight = "bold",
                                },
                                UI.Label {
                                    text = "数量 x" .. tostring(item.count or 1),
                                    fontSize = 9,
                                    fontColor = PX.textWhite,
                                },
                                UI.Label {
                                    text = "在装备培养页为未满孔装备增加空孔，最多两孔",
                                    fontSize = 8,
                                    fontColor = PX.textGray,
                                },
                            },
                        },
                    },
                })
            elseif IsRefineStoneItem(item) then
                table.insert(materialRows, UI.Panel {
                    width = "100%",
                    minHeight = 58,
                    flexDirection = "row",
                    padding = 7,
                    gap = 9,
                    alignItems = "center",
                    backgroundColor = { 20, 20, 38, 240 },
                    borderWidth = { 1, 1, 2, 1 },
                    borderColor = { 220, 180, 255, 190 },
                    children = {
                        MakeRefineStoneIcon(46),
                        UI.Panel {
                            flexGrow = 1,
                            flexShrink = 1,
                            gap = 2,
                            children = {
                                UI.Label {
                                    text = item.name or REFINE_STONE_NAME,
                                    fontSize = 11,
                                    fontColor = PX.textGold,
                                    fontWeight = "bold",
                                },
                                UI.Label {
                                    text = "数量 x" .. tostring(item.count or 1),
                                    fontSize = 9,
                                    fontColor = PX.textWhite,
                                },
                                UI.Label {
                                    text = "用于普通品质装备洗炼，消耗随装备层数提高",
                                    fontSize = 8,
                                    fontColor = PX.textGray,
                                },
                            },
                        },
                    },
                })
            else
                table.insert(materialRows, UI.Panel {
                    width = "100%",
                    minHeight = 54,
                    flexDirection = "row",
                    padding = 7,
                    gap = 9,
                    alignItems = "center",
                    backgroundColor = { 20, 20, 38, 240 },
                    borderWidth = { 1, 1, 2, 1 },
                    borderColor = PX.goldDim,
                    children = {
                        UI.Panel {
                            width = 42,
                            height = 42,
                            flexShrink = 0,
                            justifyContent = "center",
                            alignItems = "center",
                            backgroundColor = { 35, 31, 52, 255 },
                            borderWidth = 1,
                            borderColor = PX.goldDim,
                            children = {
                                UI.Label {
                                    text = "材",
                                    fontSize = 13,
                                    fontColor = PX.textGold,
                                    fontWeight = "bold",
                                    textAlign = "center",
                                },
                            },
                        },
                        UI.Panel {
                            flexGrow = 1,
                            flexShrink = 1,
                            gap = 2,
                            children = {
                                UI.Label {
                                    text = item.name or item.id or "未知材料",
                                    fontSize = 11,
                                    fontColor = PX.textWhite,
                                    fontWeight = "bold",
                                },
                                UI.Label {
                                    text = "数量 x" .. tostring(item.count or 1),
                                    fontSize = 9,
                                    fontColor = PX.textGold,
                                },
                            },
                        },
                    },
                })
            end
        end
    end

    -- 宝石合成入口按等级升序排列（1级在最上），同等级按 GEM_ORDER 顺序，放在材料区顶部
    table.sort(gemMaterialRows, function(a, b)
        if a.level ~= b.level then return a.level < b.level end
        if a.orderIndex ~= b.orderIndex then return a.orderIndex < b.orderIndex end
        return false
    end)
    local firstMaterialRow = {}
    for _, gemEntry in ipairs(gemMaterialRows) do
        table.insert(firstMaterialRow, gemEntry.row)
    end
    local restMaterialRows = {}
    for _, row in ipairs(materialRows) do
        table.insert(restMaterialRows, row)
    end
    materialRows = {}
    for _, row in ipairs(firstMaterialRow) do
        table.insert(materialRows, row)
    end
    for _, row in ipairs(restMaterialRows) do
        table.insert(materialRows, row)
    end

    local equipmentGridSection
    if #equipmentData == 0 then
        equipmentGridSection = UI.Panel {
            width = "100%", height = 54,
            justifyContent = "center", alignItems = "center",
            children = {
                UI.Label { text = "装备背包为空", fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
            },
        }
    else
        local EQUIPMENT_CARD_SIZE = 52
        local EQUIPMENT_ROW_HEIGHT = 56
        local EQUIPMENT_GAP = 4
        local equipmentColumns = math.max(4, math.floor((screenW - 28) / (EQUIPMENT_CARD_SIZE + EQUIPMENT_GAP)))
        local equipmentRows = {}
        for rowStart = 1, #equipmentData, equipmentColumns do
            local rowItems = {}
            for offset = 0, equipmentColumns - 1 do
                local data = equipmentData[rowStart + offset]
                if data then table.insert(rowItems, data) end
            end
            table.insert(equipmentRows, rowItems)
        end

        equipmentGridSection = UI.VirtualList {
            width = "100%",
            height = math.min(330, math.max(180, screenH * 0.40)),
            data = equipmentRows,
            itemHeight = EQUIPMENT_ROW_HEIGHT,
            itemGap = EQUIPMENT_GAP,
            viewportHeight = math.min(330, math.max(180, screenH * 0.40)),
            poolBuffer = 3,
            createItem = function()
                local row = UI.Panel {
                    width = "100%",
                    height = EQUIPMENT_ROW_HEIGHT,
                    flexDirection = "row",
                    gap = EQUIPMENT_GAP,
                    alignItems = "center",
                }
                row._cards = {}
                for cardIndex = 1, equipmentColumns do
                    local iconPanel = UI.Panel {
                        width = 46,
                        height = 46,
                        minWidth = 46,
                        minHeight = 46,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = { 12, 12, 24, 245 },
                        borderWidth = 2,
                    }
                    local qualityBadge = UI.Label {
                        text = "",
                        fontSize = 7,
                        fontWeight = "bold",
                        textAlign = "center",
                        position = "absolute",
                        left = 1,
                        bottom = 1,
                        paddingHorizontal = 2,
                        backgroundColor = { 8, 6, 16, 220 },
                        borderWidth = 1,
                    }
                    local socketBadge = UI.Label {
                        text = "",
                        fontSize = 6,
                        fontColor = { 165, 220, 255, 255 },
                        fontWeight = "bold",
                        textAlign = "center",
                        position = "absolute",
                        right = 1,
                        bottom = 1,
                        paddingHorizontal = 2,
                        backgroundColor = { 8, 12, 22, 230 },
                        borderWidth = 1,
                    }
                    local lockBadge = UI.Label {
                        text = "",
                        fontSize = 7,
                        fontColor = { 50, 25, 8, 255 },
                        fontWeight = "bold",
                        textAlign = "center",
                        position = "absolute",
                        right = 1,
                        top = 1,
                        paddingHorizontal = 2,
                        backgroundColor = { 255, 206, 86, 255 },
                        borderWidth = 1,
                    }
                    local unreadBadge = UI.Label {
                        text = "",
                        fontSize = 9,
                        fontColor = { 245, 38, 52, 255 },
                        textAlign = "center",
                        position = "absolute",
                        right = 0,
                        top = -3,
                        textStroke = { width = 1, color = { 255, 190, 190, 255 } },
                    }
                    local resonanceBadge = MakeEquipmentResonanceBadge("", 8)
                    local specialBadge = UI.Label {
                        text = "",
                        fontSize = 8,
                        fontColor = { 70, 35, 8, 255 },
                        fontWeight = "bold",
                        textAlign = "center",
                        position = "absolute",
                        right = 1,
                        top = 13,
                        paddingHorizontal = 3,
                    }
                    local card = UI.Panel {
                        width = EQUIPMENT_CARD_SIZE,
                        height = EQUIPMENT_CARD_SIZE,
                        minWidth = EQUIPMENT_CARD_SIZE,
                        minHeight = EQUIPMENT_CARD_SIZE,
                        flexShrink = 0,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = { 20, 18, 34, 244 },
                        borderWidth = 2,
                        borderColor = PX.goldDim,
                        onClick = function(self)
                            local data = self._boundData
                            if data and data.item then
                                MarkEquipmentViewed(data.item)
                                ShowEquipCompare(data.item, data.item.slot)
                            end
                        end,
                        children = {
                            iconPanel,
                            resonanceBadge,
                            qualityBadge,
                            socketBadge,
                            lockBadge,
                            unreadBadge,
                            specialBadge,
                        },
                    }
                    card._iconPanel = iconPanel
                    card._resonanceBadge = resonanceBadge
                    card._qualityBadge = qualityBadge
                    card._socketBadge = socketBadge
                    card._lockBadge = lockBadge
                    card._unreadBadge = unreadBadge
                    card._specialBadge = specialBadge
                    table.insert(row._cards, card)
                    row:AddChild(card)
                end
                return row
            end,
            bindItem = function(row, rowItems, rowIndex)
                for cardIndex = 1, equipmentColumns do
                    local card = row._cards[cardIndex]
                    local data = rowItems[cardIndex]
                    card._boundData = data
                    if data == nil or data.item == nil then
                        card:SetVisible(false)
                    else
                        card:SetVisible(true)
                        local item = data.item
                        local qualityDef = GetEquipmentQualityDef(item.quality)
                        local displayColor = GetEquipmentDisplayColor(item)
                        card._iconPanel:SetBackgroundImage(GetEquipmentIconPath(item))
                        card._iconPanel:SetBackgroundFit("contain")
                        card._resonanceBadge:SetText(GetEquipmentResonanceBadgeText(item))
                        card._iconPanel.props.backgroundColor = GetEquipmentVisualBackground(item, qualityDef)
                        card._iconPanel.props.borderWidth = IsAncientEquipment(item) and 3 or 2
                        card._iconPanel.props.borderColor = displayColor
                        card._qualityBadge:SetText(GetEquipmentQualityBadgeText(item))
                        card._qualityBadge.props.fontColor = displayColor
                        card._qualityBadge.props.borderColor = displayColor
                        card._socketBadge:SetText("孔" .. tostring(GetEquipmentSocketedGemCount(item))
                            .. "/" .. tostring(GetEquipmentSocketCount(item)))
                        card._socketBadge.props.borderColor = { 90, 155, 205, 220 }
                        card._lockBadge:SetText(item.locked and "上锁" or "")
                        card._lockBadge.props.borderColor = item.locked and { 105, 55, 12, 255 } or { 0, 0, 0, 0 }
                        card._unreadBadge:SetText(item.viewed == false and "●" or "")
                        card._specialBadge:SetText(IsAncientEquipment(item) and "古" or (item.synthesized == true and "合" or ""))
                        card._specialBadge.props.backgroundColor = IsAncientEquipment(item)
                            and { 255, 220, 105, 255 }
                            or (item.synthesized == true and { 130, 65, 35, 255 } or { 0, 0, 0, 0 })
                        card._specialBadge.props.borderWidth = (IsAncientEquipment(item) or item.synthesized == true) and 1 or 0
                        card.props.backgroundColor = GetEquipmentCardBackground(item)
                        card.props.borderWidth = IsAncientEquipment(item) and 3 or 2
                        card.props.borderColor = displayColor
                    end
                end
            end,
        }
    end

    local materialListSection
    if #materialRows == 0 then
        materialListSection = UI.Panel {
            width = "100%", height = 54,
            justifyContent = "center", alignItems = "center",
            children = {
                UI.Label { text = "材料背包为空", fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
            },
        }
    else
        materialListSection = UI.Panel {
            width = "100%",
            gap = 5,
            children = materialRows,
        }
    end

    local sellToolButton = UI.Panel {
        width = 30,
        height = 30,
        flexShrink = 0,
        justifyContent = "center",
        alignItems = "center",
        backgroundColor = { 76, 28, 34, 255 },
        borderWidth = { 1, 1, 3, 1 },
        borderColor = playerData.settings.autoSellEnabled
            and { 90, 220, 120, 230 }
            or PX.redBright,
        onClick = function(self)
            quickSellConfirmPending = false
            ShowEquipmentSellSettingsPage()
        end,
        children = {
            UI.Label {
                text = "售",
                fontSize = 13,
                fontColor = PX.textGold,
                fontWeight = "bold",
                textAlign = "center",
                textStroke = { width = 1, color = { 25, 8, 12, 220 } },
            },
        },
    }

    local sortToolButton = UI.Panel {
        width = 30,
        height = 30,
        flexShrink = 0,
        justifyContent = "center",
        alignItems = "center",
        backgroundColor = { 35, 31, 52, 255 },
        borderWidth = { 1, 1, 3, 1 },
        borderColor = PX.goldDim,
        onClick = function(self)
            local count = SortInventoryEquipment()
            AddEffect({ type = "drop", x = screenW * 0.5, y = screenH * 0.35, text = count > 0 and "装备已按品质、古代、层数、评分排序" or "暂无装备可排序", life = 1.2, maxLife = 1.2 })
            GameEvents.Emit("scene:equip")
        end,
        children = {
            UI.Label {
                text = "排",
                fontSize = 13,
                fontColor = PX.textWhite,
                fontWeight = "bold",
                textAlign = "center",
            },
        },
    }

    local synthesisToolButton = UI.Panel {
        width = 30,
        height = 30,
        flexShrink = 0,
        justifyContent = "center",
        alignItems = "center",
        backgroundColor = { 73, 43, 25, 255 },
        borderWidth = { 1, 1, 3, 1 },
        borderColor = { 245, 175, 90, 230 },
        onClick = function(self)
            equipmentSynthesisQualityFilter = nil
            ResetEquipmentSynthesisSelection()
            equipmentSynthesisMessage = nil
            equipmentSynthesisResult = nil
