    UI.SetRoot(BuildSubPage("装备", content), true)
    print("[Page] 装备页面")
end


quickSellConfirmPending = quickSellConfirmPending or false

function ShowGemSynthesisPage(gemType, message, returnScene)
    currentScreen = "subpage"
    currentSubPage = "gem_synthesis"
    UpdateScreenMetrics()

    local returnEvent = returnScene == "scene:equip" and "scene:equip" or "scene:bag"
    local def = GetGemDef(gemType)
    if def == nil then
        GameEvents.Emit(returnEvent)
        return
    end

    local content = {
        UI.Panel {
            width = "100%",
            padding = 10,
            gap = 5,
            alignItems = "center",
            backgroundColor = { 22, 22, 40, 245 },
            borderWidth = 2,
            borderColor = def.color,
            children = {
                UI.Label { text = def.name .. "合成", fontSize = 15, fontColor = def.color, fontWeight = "bold", textAlign = "center" },
                UI.Label { text = tostring(GEM_MERGE_COST) .. "颗同类型、同等级宝石合成1颗下一级宝石", fontSize = 10, fontColor = PX.textWhite, textAlign = "center" },
                UI.Label { text = "合成免费，只消耗背包中未镶嵌的宝石", fontSize = 9, fontColor = PX.textGray, textAlign = "center" },
                message and UI.Label { text = message, fontSize = 10, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" } or nil,
            },
        },
    }

    for level = 1, GEM_MAX_LEVEL do
        local gemLevel = level
        local count = GetGemCount(gemType, gemLevel)
        local canMerge = gemLevel < GEM_MAX_LEVEL and count >= GEM_MERGE_COST
        table.insert(content, UI.Panel {
            width = "100%",
            minHeight = 58,
            flexDirection = "row",
            padding = 8,
            gap = 8,
            alignItems = "center",
            backgroundColor = { 20, 20, 38, 240 },
            borderWidth = 1,
            borderColor = gemLevel == GEM_MAX_LEVEL and { 235, 190, 80, 220 } or def.color,
            children = {
                MakeGemIcon(gemType, 40),
                UI.Panel {
                    flexGrow = 1,
                    flexShrink = 1,
                    gap = 2,
                    children = {
                        UI.Label { text = GetGemDisplayName(gemType, gemLevel) .. " ×" .. count, fontSize = 11, fontColor = def.color, fontWeight = "bold" },
                        UI.Label { text = GetGemEffectText(gemType, gemLevel), fontSize = 9, fontColor = PX.textGray },
                    },
                },
                gemLevel < GEM_MAX_LEVEL and UI.Panel {
                    width = 78,
                    height = 32,
                    justifyContent = "center",
                    alignItems = "center",
                    backgroundColor = canMerge and PX.red or { 45, 45, 58, 220 },
                    borderWidth = 1,
                    borderColor = canMerge and PX.redBright or { 90, 90, 110, 180 },
                    onClick = function(self)
                        local ok, result = MergeGemOnce(gemType, gemLevel)
                        ShowGemSynthesisPage(
                            gemType,
                            ok and ("已合成 " .. result) or result,
                            returnEvent
                        )
                    end,
                    children = {
                        UI.Label { text = canMerge and "合成一次" or ("需要" .. GEM_MERGE_COST .. "颗"), fontSize = 10, fontColor = canMerge and PX.textWhite or PX.textGray, fontWeight = "bold", textAlign = "center" },
                    },
                } or UI.Label { text = "最高级", width = 78, fontSize = 10, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
            },
        })
    end

    local totalMergeable = 0
    for level = 1, GEM_MAX_LEVEL - 1 do
        totalMergeable = totalMergeable + math.floor(GetGemCount(gemType, level) / GEM_MERGE_COST)
    end
    table.insert(content, UI.Panel {
        width = "100%",
        height = 38,
        justifyContent = "center",
        alignItems = "center",
        backgroundColor = totalMergeable > 0 and { 70, 45, 90, 255 } or { 45, 45, 58, 220 },
        borderWidth = 2,
        borderColor = totalMergeable > 0 and { 220, 180, 255, 220 } or { 90, 90, 110, 180 },
        onClick = function(self)
            local merged, result = MergeAllGems(gemType)
            ShowGemSynthesisPage(gemType, result, returnEvent)
        end,
        children = {
            UI.Label { text = totalMergeable > 0 and "全部合成（自动向上进阶）" or "没有可合成的宝石", fontSize = 11, fontColor = totalMergeable > 0 and PX.textWhite or PX.textGray, fontWeight = "bold", textAlign = "center" },
        },
    })

    UI.SetRoot(BuildSubPage("宝石合成", content, function()
        GameEvents.Emit(returnEvent)
    end, returnEvent == "scene:equip" and "返回材料背包" or "返回背包"), true)
end

function ShowInventoryEquipmentDetail(index)
