    if item == nil or item.type ~= "equipment" then
        GameEvents.Emit("scene:bag")
        return
    end
    MarkEquipmentViewed(item)
    local slotDef = EQUIPMENT_SLOT_BY_ID[item.slot]
    local qualityDef = GetEquipmentQualityDef(item.quality)
    local displayColor = GetEquipmentDisplayColor(item)
    local current = GetActiveEquipment()[item.slot]
    local content = {
        UI.Panel {
            width = "100%",
            padding = 10,
            gap = 6,
            alignItems = "center",
            backgroundColor = GetEquipmentCardBackground(item),
            borderWidth = IsAncientEquipment(item) and 3 or { 1, 1, 3, 1 },
            borderColor = displayColor,
            children = {
                UI.Panel {
                    width = "100%",
