                MakeEquipmentIcon(item, 62, qualityDef),
                IsAncientEquipment(item) and UI.Label { text = "太古装备", fontSize = 9, fontColor = { 70, 35, 8, 255 }, fontWeight = "bold", textAlign = "center", backgroundColor = { 255, 220, 105, 255 }, borderWidth = 1, borderColor = { 115, 62, 16, 255 }, paddingHorizontal = 8, paddingVertical = 2 } or nil,
                UI.Label {
