                    textAlign = "center",
                    textStroke = { width = 1, color = { 8, 6, 16, 220 } },
                },
                UI.Label { text = GetEquipmentQualityLabel(item) .. "｜" .. (slotDef and slotDef.label or "装备") .. "｜第" .. (item.floor or 1) .. "层｜出售 " .. GetEquipmentSellRewardText(item), fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
                IsAncientEquipment(item) and UI.Label { text = "掉落时基础属性与初始随机词条均为满值；洗炼新词条按正常范围随机", fontSize = 9, fontColor = displayColor, textAlign = "center", whiteSpace = "normal" } or nil,
