                UI.Label { text = "新装备：" .. MakeEquipmentCompareText(item), fontSize = 10, fontColor = PX.textWhite, textAlign = "center" },
                UI.Label { text = current and ("当前装备：" .. MakeEquipmentCompareText(current)) or "当前装备：无", fontSize = 10, fontColor = PX.textGray, textAlign = "center" },
            },
        },
        MakeEquipmentResonanceItemPanel(
            item,
            GetActiveEquipment(),
            item.slot,
            false
        ),
        MakeEquipmentSocketPanel(item, function()
            ShowGemSocketSelectionPage(item, function()
                ShowInventoryEquipmentDetail(index)
            end)
        end),
        IsEquipmentUpgradeable(item) and UI.Panel {
