            alignItems = "center",
            backgroundColor = { 42, 62, 82, 255 },
            borderWidth = 2,
            borderColor = { 120, 210, 255, 210 },
            onClick = function(self)
                weaponUpgradeMessage = nil
                ShowEquippedItemDetail(item, item.slot, index)
            end,
            children = {
                UI.Label {
                    text = "强化养成",
                    fontSize = 12,
                    fontColor = PX.textWhite,
                    fontWeight = "bold",
                    textAlign = "center",
                },
            },
        } or nil,
        UI.Panel {
            width = "100%",
            flexDirection = "row",
            gap = 8,
            children = {
                UI.Panel {
                    flexGrow = 1,
                    height = 38,
                    justifyContent = "center",
                    alignItems = "center",
                    backgroundColor = item.locked and { 70, 55, 28, 255 } or { 35, 35, 55, 255 },
                    borderWidth = 2,
                    borderColor = item.locked and PX.gold or PX.goldDim,
                    onClick = function(self)
                        ToggleInventoryEquipmentLocked(index)
                        ShowInventoryEquipmentDetail(index)
                    end,
                    children = { UI.Label { text = item.locked and "解锁" or "上锁", fontSize = 12, fontColor = item.locked and PX.textGold or PX.textWhite, fontWeight = "bold", textAlign = "center" } },
                },
                UI.Panel {
                    flexGrow = 1,
                    height = 38,
                    justifyContent = "center",
                    alignItems = "center",
                    backgroundColor = IsAnyEquipmentRefinable(item) and { 70, 45, 90, 255 } or { 45, 45, 58, 220 },
                    borderWidth = 2,
                    borderColor = IsAnyEquipmentRefinable(item) and { 220, 180, 255, 220 } or { 90, 90, 110, 180 },
                    onClick = IsAnyEquipmentRefinable(item) and function(self)
                        refineMessage = nil
                        ShowEquipmentRefinePage(item, item.slot, index)
                    end or nil,
                    children = { UI.Label { text = IsAnyEquipmentRefinable(item) and "洗炼" or "不可洗", fontSize = 12, fontColor = IsAnyEquipmentRefinable(item) and PX.textWhite or PX.textGray, fontWeight = "bold", textAlign = "center" } },
                },
                UI.Panel {
                    flexGrow = 1,
                    height = 38,
                    justifyContent = "center",
                    alignItems = "center",
                    backgroundColor = PX.red,
                    borderWidth = 2,
                    borderColor = PX.redBright,
                    onClick = function(self)
                        EquipInventoryItem(index)
                    end,
                    children = { UI.Label { text = "穿戴", fontSize = 12, fontColor = PX.textWhite, fontWeight = "bold", textAlign = "center" } },
                },
                UI.Panel {
                    flexGrow = 1,
                    height = 38,
                    justifyContent = "center",
                    alignItems = "center",
                    backgroundColor = item.locked and { 45, 45, 58, 220 } or { 55, 35, 25, 255 },
                    borderWidth = 2,
                    borderColor = item.locked and { 90, 90, 110, 180 } or PX.gold,
                    onClick = function(self)
                        if item.locked then
                            AddEffect({ type = "drop", x = screenW * 0.5, y = screenH * 0.35, text = "装备已锁定", life = 1.0, maxLife = 1.0 })
                            return
                        end
                        if HasSocketedGems(item) then
                            ShowGemmedEquipmentSaleConfirmPage(
                                item,
                                function()
                                    ShowInventoryEquipmentDetail(index)
                                end,
                                function(gold, refineStone)
                                    AddEffect({ type = "drop", x = screenW * 0.5, y = screenH * 0.35, text = "出售装备 " .. FormatEquipmentSellRewardValues(gold, refineStone), life = 1.2, maxLife = 1.2 })
                                    GameEvents.Emit("scene:bag")
                                end
                            )
                            return
                        end
                        local gold, refineStone = SellInventoryEquipment(index)
                        AddEffect({ type = "drop", x = screenW * 0.5, y = screenH * 0.35, text = "出售装备 " .. FormatEquipmentSellRewardValues(gold, refineStone), life = 1.2, maxLife = 1.2 })
                        GameEvents.Emit("scene:bag")
                    end,
                    children = { UI.Label { text = item.locked and "已锁定" or "出售", fontSize = 12, fontColor = item.locked and PX.textGray or PX.textGold, fontWeight = "bold", textAlign = "center" } },
                },
            },
        },
    }
    UI.SetRoot(BuildSubPage("装备详情", content), true)
end

function ShowInventoryPage()
    currentScreen = "subpage"
    UpdateScreenMetrics()

    NormalizeEquipmentSettings()
    local sellQualityDef = GetEquipmentQualityDef(playerData.settings.sellThreshold)
    local autoQualityDef = GetEquipmentQualityDef(playerData.settings.autoSellThreshold)
    local autoFloorText = FormatAutoSellFloorText(playerData.settings.autoSellMaxFloor or 0)
    local equipmentUsage, inventoryEquipmentCount, pendingEquipmentCount = GetEquipmentCapacityUsage()
    local equipmentCap = CONFIG.MaxEquipmentInventory or 500
    local equipmentUsageText = tostring(equipmentUsage) .. "/" .. tostring(equipmentCap)
    if pendingEquipmentCount > 0 then
        equipmentUsageText = equipmentUsageText .. "（背包" .. tostring(inventoryEquipmentCount)
            .. "+本局暂存" .. tostring(pendingEquipmentCount) .. "）"
    end
    local sellCount = 0
    local sellGold = 0
    local sellRefineStone = 0
    for _, item in ipairs(playerData.inventory) do
        if item.type == "equipment"
            and not item.locked
            and not HasSocketedGems(item)
            and IsQualityAtOrBelow(item.quality, playerData.settings.sellThreshold) then
            local gold, refineStone = GetEquipmentSellRewards(item)
            sellCount = sellCount + 1
            sellGold = sellGold + gold
            sellRefineStone = sellRefineStone + refineStone
        end
    end
    local sellRewardText = FormatEquipmentSellRewardValues(sellGold, sellRefineStone)
    if sellCount == 0 then
        quickSellConfirmPending = false
    end
    local autoSellSlotButtons = {}
    for _, slotDef in ipairs(EQUIPMENT_SLOT_DEFS) do
        local slotId = slotDef.id
        local slotLabel = slotDef.label
        local selected = IsAutoSellSlotSelected(slotId)
        table.insert(autoSellSlotButtons, UI.Panel {
            height = 28,
            paddingHorizontal = 10,
            justifyContent = "center",
            alignItems = "center",
            backgroundColor = selected and { 35, 70, 45, 255 } or { 40, 40, 58, 255 },
            borderWidth = 1,
            borderColor = selected and { 90, 220, 120, 255 } or PX.goldDim,
            onClick = function(self)
                ToggleAutoSellSlot(slotId)
                SaveCloudData(true)
                GameEvents.Emit("scene:bag")
            end,
            children = { UI.Label { text = (selected and "✓ " or "") .. slotLabel, fontSize = 10, fontColor = selected and PX.textWhite or PX.textGray, textAlign = "center" } },
        })
    end

    local autoSellAffixCountButtons = {}
    for count = 1, 6 do
        local affixCount = count
        local selected = IsAutoSellAffixCountSelected(affixCount)
        table.insert(autoSellAffixCountButtons, UI.Panel {
            height = 28,
            paddingHorizontal = 10,
            justifyContent = "center",
            alignItems = "center",
            backgroundColor = selected and { 35, 70, 45, 255 } or { 40, 40, 58, 255 },
            borderWidth = 1,
            borderColor = selected and { 90, 220, 120, 255 } or PX.goldDim,
            onClick = function(self)
                ToggleAutoSellAffixCount(affixCount)
                SaveCloudData(true)
                GameEvents.Emit("scene:bag")
            end,
            children = { UI.Label { text = (selected and "✓ " or "") .. affixCount .. "词条", fontSize = 10, fontColor = selected and PX.textWhite or PX.textGray, textAlign = "center" } },
