                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = sellCount > 0 and (quickSellConfirmPending and { 180, 82, 42, 255 } or PX.red) or { 40, 40, 60, 200 },
                        borderWidth = 1,
                        borderColor = sellCount > 0 and PX.redBright or { 80, 80, 100, 150 },
                        onClick = function(self)
                            if sellCount == 0 then
                                quickSellConfirmPending = false
                                return
                            end
                            if not quickSellConfirmPending then
                                quickSellConfirmPending = true
                                GameEvents.Emit("scene:bag")
                                return
                            end
                            quickSellConfirmPending = false
                            local count, gold, refineStone = SellEquipmentByThreshold(playerData.settings.sellThreshold)
                            AddEffect({ type = "drop", x = screenW * 0.5, y = screenH * 0.35, text = "出售" .. count .. "件 " .. FormatEquipmentSellRewardValues(gold, refineStone), life = 1.2, maxLife = 1.2 })
                            GameEvents.Emit("scene:bag")
                        end,
                        children = { UI.Label { text = sellCount <= 0 and "无可售装备" or (quickSellConfirmPending and ("确认出售" .. sellCount .. "件") or ("出售" .. sellCount .. "件 " .. sellRewardText)), fontSize = 10, fontColor = PX.textWhite, textAlign = "center" } },
                    },
                },
            },
            UI.Label { text = quickSellConfirmPending and "再次点击红色按钮确认出售" or "锁定和已镶嵌宝石的装备不会被一键出售", fontSize = 9, fontColor = quickSellConfirmPending and PX.textGold or PX.textGray, textAlign = "center" },
            UI.Label { text = "自动出售", fontSize = 12, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                gap = 6,
                children = {
                    UI.Panel {
                        flexGrow = 1,
                        height = 32,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = playerData.settings.autoSellEnabled and { 35, 70, 45, 255 } or { 40, 40, 58, 255 },
                        borderWidth = 1,
                        borderColor = playerData.settings.autoSellEnabled and { 90, 220, 120, 255 } or PX.goldDim,
                        onClick = function(self)
                            playerData.settings.autoSellEnabled = not playerData.settings.autoSellEnabled
                            SaveCloudData(true)
                            GameEvents.Emit("scene:bag")
                        end,
                        children = { UI.Label { text = "自动出售: " .. (playerData.settings.autoSellEnabled and "开" or "关"), fontSize = 10, fontColor = PX.textWhite, textAlign = "center" } },
                    },
                },
            },
            UI.Label { text = "命中任一开启规则就会自动出售；锁定或已镶嵌宝石的装备不会自动出售", fontSize = 9, fontColor = PX.textGold, textAlign = "center" },
            UI.Label { text = playerData.settings.autoSellEnabled and "以下规则当前生效" or "自动出售关闭时，以下规则暂不生效", fontSize = 9, fontColor = playerData.settings.autoSellEnabled and { 120, 220, 140 } or PX.textGray, textAlign = "center" },
            UI.Label { text = "品质规则", fontSize = 10, fontColor = PX.textGold, textAlign = "center" },
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                gap = 6,
                children = {
                    UI.Panel {
                        flexGrow = 1,
                        height = 32,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = playerData.settings.autoSellColorRuleEnabled and { 35, 70, 45, 255 } or { 40, 40, 58, 255 },
                        borderWidth = 1,
                        borderColor = playerData.settings.autoSellColorRuleEnabled and { 90, 220, 120, 255 } or PX.goldDim,
                        onClick = function(self)
                            playerData.settings.autoSellColorRuleEnabled = not playerData.settings.autoSellColorRuleEnabled
                            SaveCloudData(true)
                            GameEvents.Emit("scene:bag")
                        end,
                        children = { UI.Label { text = "颜色规则: " .. (playerData.settings.autoSellColorRuleEnabled and "开" or "关"), fontSize = 10, fontColor = PX.textWhite, textAlign = "center" } },
                    },
                    UI.Panel {
                        flexGrow = 1,
                        height = 32,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = { 30, 30, 48, 255 },
                        borderWidth = 1,
                        borderColor = autoQualityDef.color,
                        onClick = function(self)
                            playerData.settings.autoSellThreshold = CycleQuality(playerData.settings.autoSellThreshold)
                            SaveCloudData(true)
                            GameEvents.Emit("scene:bag")
                        end,
                        children = { UI.Label { text = autoQualityDef.label .. "及以下", fontSize = 10, fontColor = autoQualityDef.color, textAlign = "center" } },
                    },
                },
            },
            UI.Label { text = "层数规则", fontSize = 10, fontColor = PX.textGold, textAlign = "center" },
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                gap = 6,
                children = {
                    UI.Panel {
                        flexGrow = 1,
                        height = 32,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = playerData.settings.autoSellFloorRuleEnabled and { 35, 70, 45, 255 } or { 40, 40, 58, 255 },
                        borderWidth = 1,
                        borderColor = playerData.settings.autoSellFloorRuleEnabled and { 90, 220, 120, 255 } or PX.goldDim,
                        onClick = function(self)
                            playerData.settings.autoSellFloorRuleEnabled = not playerData.settings.autoSellFloorRuleEnabled
                            SaveCloudData(true)
                            GameEvents.Emit("scene:bag")
                        end,
                        children = { UI.Label { text = "层数规则: " .. (playerData.settings.autoSellFloorRuleEnabled and "开" or "关"), fontSize = 10, fontColor = PX.textWhite, textAlign = "center" } },
                    },
                    UI.Panel {
                        width = 42,
                        height = 32,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = { 45, 35, 52, 255 },
                        borderWidth = 1,
                        borderColor = PX.goldDim,
                        onClick = function(self)
                            playerData.settings.autoSellMaxFloor =
                                AdjustAutoSellMaxFloor(
                                    playerData.settings.autoSellMaxFloor,
                                    -10
                                )
                            SaveCloudData(true)
                            GameEvents.Emit("scene:bag")
                        end,
                        children = {
                            UI.Label {
                                text = "-10",
                                fontSize = 10,
                                fontColor = PX.textWhite,
                                fontWeight = "bold",
                                textAlign = "center",
                            },
                        },
                    },
                    UI.Panel {
                        flexGrow = 1,
                        height = 32,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = { 30, 30, 48, 255 },
                        borderWidth = 1,
                        borderColor = PX.goldDim,
                        children = {
                            UI.Label {
                                text = autoFloorText,
                                fontSize = 10,
                                fontColor = PX.textGold,
                                textAlign = "center",
                            },
                        },
                    },
                    UI.Panel {
                        width = 42,
                        height = 32,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = { 45, 35, 52, 255 },
                        borderWidth = 1,
                        borderColor = PX.goldDim,
                        onClick = function(self)
                            playerData.settings.autoSellMaxFloor =
                                AdjustAutoSellMaxFloor(
                                    playerData.settings.autoSellMaxFloor,
                                    10
                                )
                            SaveCloudData(true)
                            GameEvents.Emit("scene:bag")
                        end,
                        children = {
                            UI.Label {
                                text = "+10",
                                fontSize = 10,
                                fontColor = PX.textWhite,
                                fontWeight = "bold",
                                textAlign = "center",
                            },
                        },
                    },
                },
            },
            UI.Label { text = "部件规则：勾选后该部件掉落即出售", fontSize = 10, fontColor = PX.textGold, textAlign = "center" },
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                flexWrap = "wrap",
                justifyContent = "center",
                gap = 6,
                children = autoSellSlotButtons,
            },
            UI.Label { text = "词条数量规则：按随机词条数，不含基础词条和彩色固定词条", fontSize = 10, fontColor = PX.textGold, textAlign = "center" },
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                flexWrap = "wrap",
                justifyContent = "center",
                gap = 6,
                children = autoSellAffixCountButtons,
            },
            UI.Label { text = "套装规则：勾选后该套装掉落即出售", fontSize = 10, fontColor = PX.textGold, textAlign = "center" },
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                flexWrap = "wrap",
                justifyContent = "center",
                gap = 6,
                children = autoSellSetButtons,
            },
            UI.Label { text = "自动出售只影响新掉落装备，背包已有装备请使用一键出售", fontSize = 9, fontColor = PX.textGray, textAlign = "center" },
        },
    }
    local equipmentCount = 0
    local materialRows = {}
    local equipmentData = {}
    local gemMaterialRows = {}
    for i, item in ipairs(playerData.inventory) do
        if item.type == "equipment" then
            equipmentCount = equipmentCount + 1
            table.insert(equipmentData, { index = i, item = item })
        elseif IsPinkRefineStoneItem(item) then
            table.insert(materialRows, UI.Panel {
                width = "100%",
                minHeight = 54,
                flexDirection = "row",
                padding = 8,
                gap = 10,
                alignItems = "center",
                backgroundColor = { 30, 20, 42, 240 },
                borderWidth = 1,
                borderColor = { 255, 120, 220, 210 },
                children = {
                    UI.Label { text = "材", fontSize = 12, fontColor = { 255, 145, 225, 255 }, width = 24, flexShrink = 0, textAlign = "center" },
                    MakePinkRefineStoneIcon(50),
                    UI.Panel {
                        flexGrow = 1,
                        flexShrink = 1,
                        gap = 2,
                        children = {
                            UI.Label { text = item.name or PINK_REFINE_STONE_NAME, fontSize = uiValueSize, fontColor = { 255, 145, 225, 255 }, fontWeight = "bold" },
                            UI.Label { text = "数量 x" .. tostring(item.count or 1), fontSize = 10, fontColor = PX.textWhite },
                            UI.Label { text = "仅用于彩色装备普通词条洗炼，消耗随装备层数提高", fontSize = 9, fontColor = PX.textGray },
                        },
                    },
                },
            })
        elseif IsRefineStoneItem(item) then
            table.insert(materialRows, UI.Panel {
                width = "100%",
                minHeight = 54,
                flexDirection = "row",
                padding = 8,
                gap = 10,
                alignItems = "center",
                backgroundColor = { 20, 20, 38, 240 },
                borderWidth = 1,
                borderColor = { 220, 180, 255, 190 },
                children = {
                    UI.Label { text = "材", fontSize = 12, fontColor = PX.textGold, width = 24, flexShrink = 0, textAlign = "center" },
                    MakeRefineStoneIcon(50),
                    UI.Panel {
                        flexGrow = 1,
                        flexShrink = 1,
                        gap = 2,
                        children = {
                            UI.Label { text = item.name or REFINE_STONE_NAME, fontSize = uiValueSize, fontColor = PX.textGold, fontWeight = "bold" },
                            UI.Label { text = "数量 x" .. tostring(item.count or 1), fontSize = 10, fontColor = PX.textWhite },
                            UI.Label { text = "用于普通品质装备洗炼，每100层增加1个消耗", fontSize = 9, fontColor = PX.textGray },
                        },
                    },
                },
            })
        elseif IsSocketPuncherItem(item) then
            table.insert(materialRows, UI.Panel {
                width = "100%",
                minHeight = 54,
                flexDirection = "row",
                padding = 8,
                gap = 10,
                alignItems = "center",
                backgroundColor = { 49, 34, 20, 240 },
                borderWidth = 1,
                borderColor = { 245, 190, 85, 220 },
                children = {
                    UI.Panel {
                        width = 50,
                        height = 50,
                        flexShrink = 0,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = { 85, 55, 28, 245 },
                        borderWidth = 2,
                        borderColor = { 245, 190, 85, 230 },
                        children = {
                            UI.Label {
                                text = "孔",
                                fontSize = 18,
                                fontColor = { 255, 220, 130, 255 },
                                fontWeight = "bold",
                                textAlign = "center",
                            },
                        },
                    },
                    UI.Panel {
                        flexGrow = 1,
                        flexShrink = 1,
                        gap = 2,
                        children = {
                            UI.Label { text = item.name or SOCKET_PUNCHER_NAME, fontSize = uiValueSize, fontColor = { 255, 220, 130, 255 }, fontWeight = "bold" },
                            UI.Label { text = "数量 x" .. tostring(item.count or 1), fontSize = 10, fontColor = PX.textWhite },
                            UI.Label { text = "在装备培养页使用；为未满孔装备增加一个空宝石孔，最多两孔", fontSize = 9, fontColor = PX.textGray },
                        },
                    },
                },
            })
        elseif IsGemItem(item) then
            local gemType = item.gemType
            local gemLevel = math.max(1, math.min(GEM_MAX_LEVEL, math.floor(item.gemLevel or 1)))
            local gemOrderIndex = 0
            for gi, gt in ipairs(GEM_ORDER or {}) do
                if gt == gemType then gemOrderIndex = gi break end
            end
            local def = GetGemDef(gemType)
            table.insert(gemMaterialRows, {
                level = gemLevel,
                orderIndex = gemOrderIndex,
                row = UI.Panel {
                    width = "100%",
                    minHeight = 54,
                    flexDirection = "row",
                    padding = 8,
                    gap = 10,
                    alignItems = "center",
                    backgroundColor = { 20, 20, 38, 240 },
                    borderWidth = 1,
                    borderColor = def and def.color or PX.goldDim,
                    onClick = function(self)
                        ShowGemSynthesisPage(gemType)
                    end,
                    children = {
                        MakeGemIcon(gemType, 50),
                        UI.Panel {
                            flexGrow = 1,
                            flexShrink = 1,
                            gap = 2,
                            children = {
                                UI.Label { text = GetGemDisplayName(gemType, gemLevel), fontSize = uiValueSize, fontColor = def and def.color or PX.textGold, fontWeight = "bold" },
                                UI.Label { text = "数量 x" .. tostring(item.count or 1), fontSize = 10, fontColor = PX.textWhite },
                                UI.Label { text = GetGemEffectText(gemType, gemLevel) .. "｜点击进入该类型合成页", fontSize = 9, fontColor = PX.textGray },
                            },
                        },
                        UI.Label { text = "合成 >", width = 48, fontSize = 10, fontColor = PX.textGold, textAlign = "center" },
                    },
                },
            })
        end
    end

    -- 宝石合成入口按等级升序排列（1级在最上），同等级按 GEM_ORDER 顺序，放在材料区顶部
    table.sort(gemMaterialRows, function(a, b)
        if a.level ~= b.level then return a.level < b.level end
        if a.orderIndex ~= b.orderIndex then return a.orderIndex < b.orderIndex end
        return false
    end)
    local sortedGemRows = {}
    for _, gemEntry in ipairs(gemMaterialRows) do
        table.insert(sortedGemRows, gemEntry.row)
    end
    local restMaterialRows = {}
    for _, row in ipairs(materialRows) do
        table.insert(restMaterialRows, row)
    end
    materialRows = {}
    for _, row in ipairs(sortedGemRows) do
        table.insert(materialRows, row)
    end
    for _, row in ipairs(restMaterialRows) do
        table.insert(materialRows, row)
    end

    local staticContent = {}
    table.insert(staticContent, sellSettingsPanel)
    if #materialRows > 0 then
        table.insert(staticContent, UI.Label { text = "材料", fontSize = 11, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" })
        for _, row in ipairs(materialRows) do
            table.insert(staticContent, row)
        end
        table.insert(staticContent, UI.Panel { width = "80%", height = 1, backgroundColor = PX.goldDim })
    end
    if equipmentCount == 0 then
        table.insert(staticContent, UI.Panel {
            width = "100%",
            height = 80,
            justifyContent = "center",
            alignItems = "center",
            backgroundColor = { 20, 20, 38, 240 },
            borderWidth = 1,
            borderColor = PX.goldDim,
            children = {
                UI.Label { text = "暂无装备", fontSize = 12, fontColor = PX.textGray, textAlign = "center" },
                UI.Label { text = "技能已拆分到技能页，击败怪物有几率掉落装备", fontSize = 10, fontColor = { 120, 120, 140, 200 }, textAlign = "center" },
            },
        })
    end

    local ITEM_HEIGHT = 78
    local equipmentList = nil
    if equipmentCount > 0 then
        equipmentList = UI.VirtualList {
            width = "100%",
            flexGrow = 1,
            flexBasis = 0,
            data = equipmentData,
            itemHeight = ITEM_HEIGHT,
            itemGap = 4,
            viewportHeight = 400,
            poolBuffer = 4,
            createItem = function()
                local qualityBadge = UI.Label {
                    text = "",
                    fontSize = 7,
                    fontWeight = "bold",
                    textAlign = "center",
                    position = "absolute",
                    left = 1,
                    bottom = 1,
                    paddingHorizontal = 2,
                    backgroundColor = { 8, 6, 16, 220 },
                    borderWidth = 1,
                }
                local lockBadge = UI.Label {
                    text = "",
                    fontSize = 7,
                    fontWeight = "bold",
                    textAlign = "center",
                    position = "absolute",
                    right = 1,
                    top = 1,
                    paddingHorizontal = 2,
                }
                local unreadBadge = UI.Label {
                    text = "",
                    fontSize = 12,
                    fontColor = { 245, 38, 52, 255 },
                    textAlign = "center",
                    position = "absolute",
                    right = 0,
                    top = -3,
                    textStroke = { width = 1, color = { 255, 190, 190, 255 } },
                }
                local resonanceBadge = MakeEquipmentResonanceBadge("", 8)
                local iconPanel = UI.Panel {
                    width = 50, height = 50, minWidth = 50, minHeight = 50, flexShrink = 0,
                    justifyContent = "center", alignItems = "center",
                    backgroundColor = { 12, 12, 24, 245 },
                    borderWidth = 2,
                    children = { resonanceBadge, qualityBadge, lockBadge, unreadBadge },
                }
                local nameLabel = UI.Label { text = "", fontSize = 12, fontWeight = "bold", maxLines = 1, textStroke = { width = 1, color = { 8, 6, 16, 210 } } }
                local detailLabel = UI.Label { text = "", fontSize = 9, fontColor = PX.textGray, maxLines = 1 }
                local affixLabel = UI.Label { text = "", fontSize = 9, fontColor = PX.textGray, maxLines = 1 }
                local compareLabel = UI.Label { text = "", fontSize = 9, fontColor = PX.textGold, maxLines = 1 }
                local indexLabel = UI.Label {
                    text = "",
                    fontSize = 9,
                    fontColor = PX.textGray,
                    width = 30,
                    flexShrink = 0,
                    textAlign = "center",
                    backgroundColor = { 12, 10, 22, 190 },
                    borderWidth = 1,
                    borderColor = PX.goldDim,
                    paddingVertical = 3,
                }
                local row = UI.Panel {
                    width = "100%",
                    height = ITEM_HEIGHT,
                    flexDirection = "row",
                    padding = 8,
                    gap = 9,
                    alignItems = "center",
                    backgroundColor = { 20, 20, 38, 240 },
                    borderWidth = { 1, 1, 2, 1 },
                    borderColor = PX.goldDim,
                    children = {
                        indexLabel,
                        iconPanel,
                        UI.Panel {
                            flexGrow = 1, flexShrink = 1, gap = 2,
                            children = { nameLabel, detailLabel, affixLabel, compareLabel },
                        },
                    },
                }
                row._indexLabel = indexLabel
                row._iconPanel = iconPanel
                row._resonanceBadge = resonanceBadge
                row._qualityBadge = qualityBadge
                row._lockBadge = lockBadge
                row._unreadBadge = unreadBadge
                row._nameLabel = nameLabel
                row._detailLabel = detailLabel
                row._affixLabel = affixLabel
                row._compareLabel = compareLabel
                return row
            end,
            bindItem = function(widget, data, idx)
                local item = data.item
                local invIndex = data.index
                local slotDef = EQUIPMENT_SLOT_BY_ID[item.slot]
                local qualityDef = GetEquipmentQualityDef(item.quality)
                local displayColor = GetEquipmentDisplayColor(item)
                local iconPath = GetEquipmentIconPath(item)
                widget._indexLabel:SetText("#" .. invIndex)
                widget._iconPanel:SetBackgroundImage(iconPath)
                widget._iconPanel:SetBackgroundFit("contain")
                widget._resonanceBadge:SetText(GetEquipmentResonanceBadgeText(item))
                widget._iconPanel.props.backgroundColor = GetEquipmentVisualBackground(item, qualityDef)
                widget._iconPanel.props.borderWidth = IsAncientEquipment(item) and 3 or 2
                widget._iconPanel.props.borderColor = displayColor
                widget._qualityBadge:SetText(GetEquipmentQualityBadgeText(item))
                widget._qualityBadge.props.fontColor = displayColor
                widget._qualityBadge.props.borderColor = displayColor
                widget._qualityBadge.props.backgroundColor = { 8, 6, 16, 220 }
                widget._lockBadge:SetText(item.locked and "上锁" or "")
                widget._lockBadge.props.fontColor = item.locked and { 50, 25, 8, 255 } or { 0, 0, 0, 0 }
                widget._lockBadge.props.backgroundColor = item.locked and { 255, 206, 86, 255 } or { 0, 0, 0, 0 }
                widget._lockBadge.props.borderWidth = item.locked and 1 or 0
                widget._lockBadge.props.borderColor = item.locked and { 105, 55, 12, 255 } or { 0, 0, 0, 0 }
                widget._unreadBadge:SetText(item.viewed == false and "●" or "")
                widget._nameLabel:SetText(GetEquipmentDisplayName(item))
                widget._nameLabel.props.fontColor = displayColor
                local socketText = "孔 " .. tostring(GetEquipmentSocketedGemCount(item))
                    .. "/" .. tostring(GetEquipmentSocketCount(item))
                widget._detailLabel:SetText((item.locked and "已上锁｜" or "")
                    .. GetEquipmentQualityLabel(item) .. "｜"
                    .. (slotDef and slotDef.label or "装备") .. "｜"
                    .. socketText .. "｜第" .. (item.floor or 1)
                    .. "层｜卖" .. GetEquipmentSellRewardText(item))
                widget._detailLabel.props.fontColor = item.locked and PX.textGold or PX.textGray
                widget._affixLabel:SetText(item.baseAffix and ("基础 " .. MakeAffixDisplay(item.baseAffix)) or "点击查看详情")
                widget._compareLabel:SetText(MakeEquipmentCompareText(item))
                widget.props.backgroundColor = GetEquipmentCardBackground(item)
                widget.props.borderWidth = IsAncientEquipment(item) and 3 or { 1, 1, 2, 1 }
                widget.props.borderColor = displayColor
            end,
            onItemClick = function(data, idx, widget)
                ShowInventoryEquipmentDetail(data.index)
            end,
        }
    end

    SetRootBagPage("背包", staticContent, equipmentList)
    print("[Page] 背包页面")
end

function SetRootBagPage(title, staticChildren, equipmentList)
    local sideW = math.max(16, math.floor(screenW * 0.045))
    local topAuraH = math.max(150, math.floor(screenH * 0.34))
    local bottomAuraH = math.max(110, math.floor(screenH * 0.22))
    local cornerSize = 34

    local contentAreaChildren = {}
    if equipmentList then
        table.insert(contentAreaChildren, UI.Panel {
            width = "100%",
            flexShrink = 0,
            gap = 10,
            alignItems = "center",
            children = staticChildren,
        })
        table.insert(contentAreaChildren, equipmentList)
    else
        table.insert(contentAreaChildren, UI.ScrollView {
            width = "100%",
            height = "100%",
            scrollX = false,
            scrollY = true,
            showScrollbar = true,
            children = {
                UI.Panel {
                    width = "100%",
                    gap = 10,
                    alignItems = "center",
                    children = staticChildren,
                },
            },
        })
    end

    local root = UI.Panel {
        width = "100%",
        height = "100%",
        justifyContent = "center",
        alignItems = "center",
        backgroundColor = { 8, 6, 14, 188 },
        children = {
            UI.Panel {
                position = "absolute", left = 0, right = 0, top = 0,
                height = topAuraH,
                backgroundColor = { 72, 24, 42, 138 },
            },
            UI.Panel {
                position = "absolute", left = 0, right = 0,
                top = math.floor(topAuraH * 0.34),
                height = math.max(42, math.floor(topAuraH * 0.38)),
                backgroundColor = { 118, 40, 42, 52 },
