function ShowClassSelectionPage(required)
    currentScreen = "class_select"
    UpdateScreenMetrics()

    local selectedClassId = GetCurrentRunClassId()
    local locked = selectedClassId ~= nil
    local cards = {}
    for _, classId in ipairs(CLASS_ORDER or {}) do
        local cardClassId = classId
        local def = CLASS_DEFS[cardClassId]
        local selected = cardClassId == selectedClassId
        table.insert(cards, UI.Panel {
            width = screenW < 420 and "48%" or "23%",
            minHeight = screenW < 420 and 174 or 188,
            padding = 8,
            gap = 5,
            alignItems = "center",
            backgroundColor = selected and { 70, 46, 30, 248 } or { 27, 21, 37, 244 },
            borderWidth = selected and 2 or 1,
            borderColor = selected and PX.gold or PX.goldDim,
            children = {
                UI.Label {
                    text = def.name,
                    fontSize = 15,
                    fontColor = selected and PX.textGold or PX.textWhite,
                    fontWeight = "bold",
                    textAlign = "center",
                },
                UI.Panel {
                    width = 76,
                    height = 76,
                    flexShrink = 0,
                    backgroundColor = { 12, 10, 20, 255 },
                    backgroundImage = CLASS_ICON_PATHS[cardClassId],
                    backgroundFit = "contain",
                    borderWidth = 1,
                    borderColor = selected and PX.gold or PX.goldDim,
                },
                UI.Label {
                    text = def.summary,
                    fontSize = 9,
                    fontColor = PX.textGray,
                    whiteSpace = "normal",
                    textAlign = "center",
                    minHeight = 34,
                },
                UI.Button {
                    width = "100%",
                    height = 34,
                    text = selected and "本局已选择" or (locked and "本局已锁定" or "选择职业"),
                    fontSize = 9,
                    variant = selected and "primary" or "secondary",
                    disabled = locked,
                    onClick = function(self)
                        if SelectCurrentRunClass(cardClassId) then
                            GameEvents.Emit("scene:main")
                        end
                    end,
                },
            },
        })
    end

    local content = UI.Panel {
        width = "100%",
        gap = 10,
        alignItems = "center",
        children = {
            UI.Label {
                text = locked and "本局职业已锁定" or "选择本局职业",
                fontSize = 18,
                fontColor = PX.textGold,
                fontWeight = "bold",
                textAlign = "center",
            },
            UI.Label {
                text = locked
                    and "基地死亡后可重新选择职业。"
