        { content },
        required and function() end or function() GameEvents.Emit("scene:main") end,
        required and "本局必须选择一个职业" or "本局职业",
        { hideBack = required == true, wideContent = true }
    ), true)
    print("[Page] 职业选择页面, required:", required == true)
end

