skillMergeMessage = skillMergeMessage or nil
selectedSkillUid = selectedSkillUid or nil

function ShowSkillPage()
    currentScreen = "subpage"
    currentSubPage = "skill"
    UpdateScreenMetrics()
    NormalizeEquipmentSettings()
    NormalizeSkills()
    NormalizeSkillLoadouts()
    local autoAttempts, autoSuccess, autoFail = 0, 0, 0
    if skipSkillPageAutoMergeOnce == true then
        skipSkillPageAutoMergeOnce = false
    else
        autoAttempts, autoSuccess, autoFail = TryAutoMergeSkills("skill_page")
    end
    if autoAttempts > 0 then
        skillMergeMessage = "自动合成" .. autoAttempts .. "次，成功" .. autoSuccess .. "次，失败" .. autoFail .. "次"
    end

    local function FormatSkillCost(cost)
        if cost >= 10000 and cost % 10000 == 0 then
            return tostring(math.floor(cost / 10000)) .. "万"
        end
        return tostring(cost)
    end

    local function SkillStarText(skill)
        return tostring(skill and skill.star or 1) .. "⭐"
    end

    local function GetSkillStarVisualColor(skill)
        local star = math.max(1, math.floor(skill and skill.star or 1))
        if star >= 9 then return { 255, 105, 230, 255 } end
        if star >= 7 then return { 255, 78, 78, 255 } end
        if star >= 5 then return { 255, 158, 52, 255 } end
        if star >= 3 then return { 185, 100, 255, 255 } end
        return { 90, 174, 255, 255 }
    end

    local function MakeSkillSectionTitle(text, accentColor, hint)
        accentColor = accentColor or PX.goldDim
        return UI.Panel {
            width = "100%",
            minHeight = hint and 36 or 28,
            paddingHorizontal = 9,
            paddingVertical = 5,
            gap = 2,
            justifyContent = "center",
            backgroundColor = { 29, 22, 38, 244 },
            borderWidth = { 1, 1, 2, 4 },
            borderColor = accentColor,
            children = {
                UI.Label {
                    text = text,
                    fontSize = 11,
                    fontColor = PX.textGold,
                    fontWeight = "bold",
                    textStroke = { width = 1, color = { 22, 8, 30, 225 } },
                },
                hint and UI.Label {
                    text = hint,
                    fontSize = 8,
                    fontColor = PX.textGray,
                } or nil,
            },
        }
    end

    local function SkillCardTitle(skill)
        if skill == nil then return "空" end
        local def = GetSkillDef(skill.id)
        return def and def.name or skill.name or "技能"
    end

    local function SkillOrderIndex(skillId)
        for index, id in ipairs(SKILL_ORDER or {}) do
            if id == skillId then return index end
        end
        return 9999
    end

    local function SkillUidNumber(skill)
        local uid = tostring(skill and skill.uid or "")
        return tonumber(string.match(uid, "skill_(%d+)")) or 0
    end

    local function CountUnequippedSkills()
        return CountUnequippedSkillCards()
    end

    local function CompareSkillForBagSort(a, b)
        local starA = GetSkillStar(a)
        local starB = GetSkillStar(b)
        if starA ~= starB then return starA > starB end

        local orderA = SkillOrderIndex(a and a.id or nil)
        local orderB = SkillOrderIndex(b and b.id or nil)
        if orderA ~= orderB then return orderA < orderB end

        local nameA = SkillCardTitle(a)
        local nameB = SkillCardTitle(b)
        if nameA ~= nameB then return nameA < nameB end

        local uidA = SkillUidNumber(a)
        local uidB = SkillUidNumber(b)
        if uidA ~= uidB then return uidA < uidB end
        return tostring(a and a.uid or "") < tostring(b and b.uid or "")
    end

    local function SortUnequippedSkills()
        NormalizeSkills()
        local unequipped = {}
        for _, skill in ipairs(playerData.skills or {}) do
            if not IsSkillUidEquipped(skill.uid) then
                table.insert(unequipped, skill)
            end
        end
        if #unequipped <= 1 then
            return #unequipped, false
        end

        table.sort(unequipped, CompareSkillForBagSort)

        local nextUnequipped = 1
        local sortedSkills = {}
        local changed = false
        for i, skill in ipairs(playerData.skills) do
            if IsSkillUidEquipped(skill.uid) then
                sortedSkills[i] = skill
            else
                local sortedSkill = unequipped[nextUnequipped]
                sortedSkills[i] = sortedSkill
                nextUnequipped = nextUnequipped + 1
                if skill.uid ~= sortedSkill.uid then
                    changed = true
                end
            end
        end

        if changed then
            playerData.skills = sortedSkills
            MarkSaveDirty()
            SaveCloudData(true)
        end
        return #unequipped, changed
    end

    local function MakeSkillIcon(def, size, fallbackText, active, accentColor)
        size = size or 34
        accentColor = accentColor or (active and { 120, 210, 255, 220 } or { 90, 82, 60, 150 })
        local iconImage = def and def.iconImage or nil
        local children = {}
        if iconImage then
            table.insert(children, UI.Panel {
                width = math.max(18, size - 6),
                height = math.max(18, size - 6),
                backgroundImage = iconImage,
                backgroundFit = "contain",
            })
        else
            table.insert(children, UI.Label {
                text = (def and def.icon) or fallbackText or "技",
                fontSize = math.max(10, math.floor(size * 0.42)),
                fontColor = active and PX.textWhite or PX.textGray,
                fontWeight = active and "bold" or "normal",
                textAlign = "center",
            })
        end
        return UI.Panel {
            width = size,
            height = size,
            minWidth = size,
            minHeight = size,
            flexShrink = 0,
            justifyContent = "center",
            alignItems = "center",
            backgroundColor = active and { 31, 26, 45, 255 } or { 27, 21, 37, 235 },
            borderWidth = 1,
            borderColor = accentColor,
            children = children,
        }
    end

    local ShowSkillDetailModal = function(uid) end

    local function SelectSkill(uid)
        if FindSkillCardByUid(uid) == nil then return end
        selectedSkillUid = uid
        skillMergeMessage = nil
        ShowSkillDetailModal(uid)
    end

    local function HasEmptySkillSlot()
        for i = 1, GetUnlockedSkillSlotCount() do
            if playerData.skillSlots[i] == nil then
                return true
            end
        end
        return false
    end

    local function CountEquippedSkillCopies(skillId)
        local count = 0
        for i = 1, GetUnlockedSkillSlotCount() do
            local equippedSkill = FindSkillCardByUid(playerData.skillSlots[i])
            if equippedSkill and equippedSkill.id == skillId then
                count = count + 1
            end
        end
        return count
    end

    local function ToggleSkillSlot(uid)
        local skill = FindSkillCardByUid(uid)
        if skill == nil then return end

        local equippedSlot = nil
        for i = 1, GetUnlockedSkillSlotCount() do
            if playerData.skillSlots[i] == uid then
                equippedSlot = i
                break
            end
        end

        if equippedSlot then
            local skillCap = CONFIG.MaxUnequippedSkillCards or 300
            local unequippedCount = CountUnequippedSkillCards()
            if unequippedCount >= skillCap then
                skillMergeMessage = "技能背包已满（" .. tostring(unequippedCount) .. "/"
                    .. tostring(skillCap) .. "），无法卸下"
                selectedSkillUid = uid
                GameEvents.Emit("scene:skill")
                return
            end
            playerData.skillSlots[equippedSlot] = nil
            skillMergeMessage = "已卸下：" .. SkillCardTitle(skill)
        else
            local target = nil
            for i = 1, GetUnlockedSkillSlotCount() do
                if playerData.skillSlots[i] == nil then
                    target = i
                    break
                end
            end
            local replacedSkill = nil
            if target == nil then
                target = 1
                replacedSkill = FindSkillCardByUid(playerData.skillSlots[target])
            end

            local duplicateLimit = math.max(1, CONFIG.SkillEquipDuplicateLimit or 3)
            local equippedCopies = CountEquippedSkillCopies(skill.id)
            if replacedSkill and replacedSkill.id == skill.id then
                equippedCopies = equippedCopies - 1
            end
            if equippedCopies >= duplicateLimit then
                skillMergeMessage = "同一技能最多装备" .. tostring(duplicateLimit) .. "个"
                selectedSkillUid = uid
                GameEvents.Emit("scene:skill")
                return
            end

            playerData.skillSlots[target] = uid
            if replacedSkill then
                skillMergeMessage = "技能栏已满，已替换：" .. SkillCardTitle(replacedSkill)
            else
                skillMergeMessage = "已装备：" .. SkillCardTitle(skill)
            end
        end
        selectedSkillUid = uid
        NormalizeSkills()
        InitSkillRuntime()
        SaveCloudData(true)
        GameEvents.Emit("scene:skill")
    end

    ShowSkillDetailModal = function(uid)
        local skill = FindSkillCardByUid(uid)
        if skill == nil then return end

        local def = GetSkillDef(skill.id)
        local equippedSlot = nil
        for i = 1, GetUnlockedSkillSlotCount() do
            if playerData.skillSlots[i] == uid then
                equippedSlot = i
                break
            end
        end

        local isEquipped = equippedSlot ~= nil
        local starColor = GetSkillStarVisualColor(skill)
        local detailText = GetSkillCurrentDescription(skill, equippedSlot)
        local actionText = isEquipped and "卸下技能" or (HasEmptySkillSlot() and "装备技能" or "装备并替换1号槽")
        -- ============================================================
        -- 技能详情增强：强化成长表 / 觉醒预览(8~10星)
        -- ============================================================
        local currentStar = GetSkillStar(skill)
        local maxStar = CONFIG.SkillMaxStar or 10
        local awakeningStar = CONFIG.SkillAwakeningStar or 8

        local function SplitDetailBlocks(fullText)
            local blocks = {}
            for block in (fullText .. "\n\n"):gmatch("(.-)\n\n") do
                table.insert(blocks, block)
            end
            return blocks
        end

        local function BlockBodyLines(block)
            local lines = {}
            local inBody = false
            for line in (block .. "\n"):gmatch("(.-)\n") do
                line = line:gsub("[\r\n]+$", "")
                line = line:gsub("^%s+", "")
                line = line:gsub("%s+$", "")
                if inBody then
                    if line ~= "" then
                        table.insert(lines, line)
                    end
                elseif line:find("【", 1, true) then
                    inBody = true
                end
            end
            return lines
        end

        local function FindDetailBlock(fullText, sectionPrefix)
            for _, block in ipairs(SplitDetailBlocks(fullText)) do
                local firstLine = block:match("^%s*[^\r\n]*")
                if firstLine and firstLine:find(sectionPrefix, 1, true) then
                    return block
                end
            end
            return nil
        end

        local function MockSkillOfStar(starValue)
            return {
                uid = skill.uid,
                id = skill.id,
                name = skill.name,
                star = starValue,
            }
        end

                -- 预扫描：每个星级的候选数值行，并识别"全部星级恒定"的静态说明行
        local rawLinesByStar = {}
        local staticLineSeenStars = {}
        for starIndex = 1, maxStar do
            local mockSkill = MockSkillOfStar(starIndex)
            local effectBlock = FindDetailBlock(GetSkillCurrentDescription(mockSkill, nil), "【当前效果】")
            local keptLines = {}
            if effectBlock then
                for _, line in ipairs(BlockBodyLines(effectBlock)) do
                    local isDamageLine = line:find("基础伤害", 1, true) ~= nil
                        or line:find("总伤害", 1, true) ~= nil
                    local hasNumber = line:find("%d") ~= nil
                    local hasColon = line:find("[:：]") ~= nil
                    if (not isDamageLine)
                        and line:find("尚未解锁", 1, true) == nil
                        and (hasNumber or hasColon) then
                        table.insert(keptLines, line)
                    end
                end
            end
            rawLinesByStar[starIndex] = keptLines
            local seen = {}
            for _, line in ipairs(keptLines) do
                if seen[line] == nil then
                    seen[line] = true
                    staticLineSeenStars[line] = (staticLineSeenStars[line] or 0) + 1
                end
            end
        end

        -- 抽取某星级的"随星级变化"数值行(恒定说明行与伤害行不再重复展示)
        local function StarChangeSummaryLines(starIndex)
            local damageFirst = {}
            local otherLines = {}
            for _, line in ipairs(rawLinesByStar[starIndex] or {}) do
                if (staticLineSeenStars[line] or 0) < maxStar then
                    if line:find("伤害", 1, true) ~= nil then
                        table.insert(damageFirst, line)
                    else
                        table.insert(otherLines, line)
                    end
                end
            end
            for _, line in ipairs(otherLines) do
                table.insert(damageFirst, line)
            end
            return damageFirst
        end

        -- ① 逐星强化表数据(★1 ~ ★10)
        local starRowPanels = {}
        for starIndex = 1, maxStar do
            local isCurrentRow = starIndex == currentStar
            local isAwakenedRow = starIndex >= awakeningStar
            local mockRowSkill = MockSkillOfStar(starIndex)
            local rowAccent = GetSkillStarVisualColor(mockRowSkill)
            local rowMultiplier = GetSkillDamageMultiplier(mockRowSkill)
            local rowMultiplierText = "伤害" .. string.format("×%.2f", rowMultiplier)
            local changeLines = StarChangeSummaryLines(starIndex)
            local changeText = table.concat(changeLines, "；")
            if changeText == "" then
                if isAwakenedRow then
                    changeText = "解锁专属觉醒效果，并继续提升通用伤害倍率。"
                elseif starIndex == 1 then
                    changeText = "基础形态：伤害倍率与暴击伤害将随星级提升。"
                else
                    changeText = "相比上一星级，本星级主要提升通用伤害倍率。"
                end
            end

            local leftChildren = {
                UI.Label {
                    text = "★" .. tostring(starIndex),
                    fontSize = 10,
                    fontColor = rowAccent,
                    fontWeight = "bold",
                    textAlign = "center",
                },
                UI.Label {
                    text = rowMultiplierText,
                    fontSize = 8,
                    fontColor = PX.textGold,
                    fontWeight = "bold",
                    textAlign = "center",
                },
            }
            if isAwakenedRow then
                table.insert(leftChildren, UI.Label {
                    text = "觉醒" .. tostring(starIndex - awakeningStar + 1) .. "阶",
                    fontSize = 7,
                    fontColor = rowAccent,
                    fontWeight = "bold",
                    textAlign = "center",
                })
            end

            table.insert(starRowPanels, UI.Panel {
                width = "100%",
                flexDirection = "row",
                alignItems = "flex-start",
                gap = 5,
                padding = 4,
                backgroundColor = isCurrentRow and { 47, 37, 30, 250 }
                    or (isAwakenedRow and { 32, 20, 44, 238 } or { 13, 12, 26, 180 }),
                borderWidth = isCurrentRow and 1 or 0,
                borderColor = starColor,
                children = {
                    UI.Panel {
                        width = 62,
                        minWidth = 62,
                        flexShrink = 0,
                        gap = 1,
                        children = leftChildren,
                    },
                    UI.Label {
                        flexShrink = 1,
                        text = changeText,
                        fontSize = 8,
                        fontColor = isCurrentRow and PX.textWhite or PX.textGray,
                        whiteSpace = "normal",
                        wordBreak = "break-word",
                        lineHeight = 1.45,
                    },
                },
            })
        end

        -- ② 觉醒预览(8★/9★/10★ 各阶实际数值)
        local awakeningPanels = {}
        if maxStar >= awakeningStar then
            for levelIndex = 1, maxStar - awakeningStar + 1 do
                local previewStar = awakeningStar + levelIndex - 1
                local reached = currentStar >= previewStar
                local mockAwakeSkill = MockSkillOfStar(previewStar)
                local awakeAccent = GetSkillStarVisualColor(mockAwakeSkill)
                local awakeBlock = FindDetailBlock(GetSkillCurrentDescription(mockAwakeSkill, nil), "【觉醒")
                local awakeLines = awakeBlock and BlockBodyLines(awakeBlock) or {}
                local awakeText = table.concat(awakeLines, "\n")
                if awakeText == "" then
                    awakeText = "达到" .. tostring(previewStar) .. "★后解锁该技能的专属觉醒效果。"
                end
                table.insert(awakeningPanels, UI.Panel {
                    width = "100%",
                    padding = 5,
                    gap = 2,
                    backgroundColor = reached and { 40, 26, 50, 246 } or { 15, 14, 30, 220 },
                    borderWidth = reached and 1 or 0,
                    borderColor = awakeAccent,
                    children = {
                        UI.Label {
                            text = "★" .. tostring(previewStar) .. " 觉醒" .. tostring(levelIndex) .. "阶"
                                .. (reached and " · 当前已达成" or ""),
                            fontSize = 9,
                            fontColor = awakeAccent,
                            fontWeight = "bold",
                        },
                        UI.Label {
                            text = awakeText,
                            fontSize = 8,
                            fontColor = PX.textWhite,
                            whiteSpace = "normal",
                            wordBreak = "break-word",
                            lineHeight = 1.45,
                        },
                    },
                })
            end
        end

        -- ③ 强化规则说明(合成/伤害/暴击/冷却通用规则)
        local skillRuleText = "合成强化：3张相同技能、相同星级的技能卡可合成为1张高1星技能卡；"
            .. "成功率随材料星级递减(1★100% → 6★及以上50%)；失败时随机保留其中1张原星级技能，其余2张材料消耗。\n"
            .. "通用成长：1~7★每升1★伤害倍率×1.12；8★起进入觉醒，每觉醒1阶伤害额外×1.20、冷却-4%；"
            .. "技能暴击率20%，暴击伤害随星级从+5%成长到+100%。"
        local modal
        modal = UI.Modal {
            title = "技能精确详情",
            size = "md",
            isOpen = false,
            closeOnOverlay = true,
            closeOnEscape = true,
            showCloseButton = true,
            contentPadding = 12,
            contentGap = 7,
            backgroundColor = { 20, 17, 35, 255 },
            borderWidth = 2,
            borderColor = starColor,
            children = {
                UI.Panel {
                    width = "100%",
                    flexDirection = "row",
                    alignItems = "center",
                    justifyContent = "center",
                    gap = 9,
                    children = {
                        MakeSkillIcon(def, 52, "技", true, starColor),
                        UI.Panel {
                            flexShrink = 1,
                            gap = 3,
                            children = {
                                UI.Label { text = SkillCardTitle(skill), fontSize = 15, fontColor = PX.textWhite, fontWeight = "bold", maxLines = 1, textStroke = { width = 1, color = { 8, 6, 16, 220 } } },
                                UI.Label { text = SkillStarText(skill), fontSize = 11, fontColor = starColor, fontWeight = "bold" },
                                UI.Label { text = isEquipped and ("已装备 · 第" .. tostring(equippedSlot) .. "号槽") or "当前未装备", fontSize = 9, fontColor = isEquipped and PX.textGold or PX.textGray, fontWeight = "bold" },
                            },
                        },
                    },
                },
                UI.Panel { width = "100%", height = 1, backgroundColor = starColor },
                UI.ScrollView {
                    width = "100%",
                    height = 360,
                    scrollX = false,
                    scrollY = true,
                    showScrollbar = true,
                    children = {
                        UI.Panel {
                            width = "100%",
                            padding = 10,
                            gap = 5,
                            backgroundColor = { 12, 11, 25, 220 },
                            borderWidth = { 1, 1, 2, 3 },
                            borderColor = starColor,
                            children = {
                                UI.Label { text = "当前星级精确数值", fontSize = 10, fontColor = starColor, fontWeight = "bold" },
                                UI.Label {
                                    text = detailText,
                                    fontSize = 9,
                                    fontColor = PX.textWhite,
                                    whiteSpace = "normal",
                                    wordBreak = "break-word",
                                    lineHeight = 1.4,
                                },
                            },
                        },
                        UI.Panel {
                            width = "100%",
                            padding = 8,
                            gap = 5,
                            backgroundColor = { 15, 20, 32, 235 },
                            borderWidth = { 1, 1, 2, 1 },
                            borderColor = { 120, 170, 220, 210 },
                            children = {
                                UI.Label { text = "技能简介", fontSize = 10, fontColor = { 120, 200, 255, 255 }, fontWeight = "bold" },
                                UI.Label {
                                    text = def.desc,
                                    fontSize = 9,
                                    fontColor = PX.textWhite,
                                    whiteSpace = "normal",
                                    wordBreak = "break-word",
                                    lineHeight = 1.45,
                                },
                            },
                        },
                        UI.Panel {
                            width = "100%",
                            padding = 8,
                            gap = 5,
                            backgroundColor = { 24, 20, 40, 242 },
                            borderWidth = { 1, 1, 2, 1 },
                            borderColor = { 170, 130, 200, 210 },
                            children = {
                                UI.Label { text = "强化 · 升星规则", fontSize = 10, fontColor = PX.textGold, fontWeight = "bold" },
                                UI.Label {
                                    text = skillRuleText,
                                    fontSize = 8,
                                    fontColor = PX.textGray,
                                    whiteSpace = "normal",
                                    wordBreak = "break-word",
                                    lineHeight = 1.45,
                                },
                            },
                        },
                        UI.Panel {
                            width = "100%",
                            padding = 8,
                            gap = 5,
                            backgroundColor = { 17, 15, 32, 240 },
                            borderWidth = { 1, 1, 2, 1 },
                            borderColor = PX.goldDim,
                            children = {
                                UI.Label { text = "逐星强化成长表", fontSize = 10, fontColor = PX.textGold, fontWeight = "bold" },
                                UI.Label {
                                    text = "每行展示该星级技能的伤害倍率与随星级变化的实际数值；伤害为技能卡自身最终数值(不计装备/宝石/局内增益)。金色边框=当前星级，紫色行=觉醒星级。",
                                    fontSize = 8,
                                    fontColor = PX.textGray,
                                    whiteSpace = "normal",
                                    wordBreak = "break-word",
                                    lineHeight = 1.4,
                                },
                                table.unpack(starRowPanels),
                            },
                        },
                        UI.Panel {
                            width = "100%",
                            padding = 8,
                            gap = 5,
                            backgroundColor = { 24, 17, 34, 242 },
                            borderWidth = { 1, 1, 2, 1 },
                            borderColor = { 200, 120, 230, 210 },
                            children = {
                                UI.Label { text = "觉醒预览（8★~10★）", fontSize = 10, fontColor = { 240, 130, 255, 255 }, fontWeight = "bold" },
                                UI.Label {
                                    text = "8★起每升1★视为1次觉醒(共3阶)，各阶效果与数值如下。",
                                    fontSize = 8,
                                    fontColor = PX.textGray,
                                    whiteSpace = "normal",
                                    wordBreak = "break-word",
                                },
                                table.unpack(awakeningPanels),
