    local function TryUnlockSlot(index)
        local unlocked = GetUnlockedSkillSlotCount()
        if index <= unlocked then return end
        if unlocked >= CONFIG.SkillSlotMaxCount then return end
        if index ~= unlocked + 1 then
            skillMergeMessage = "请先解锁前一个技能栏"
            GameEvents.Emit("scene:skill")
            return
        end

        local cost = CONFIG.SkillSlotUnlockCosts[index - CONFIG.SkillSlotBaseCount]
        if cost == nil then return end
        if playerData.gold < cost then
            skillMergeMessage = "金币不足，解锁需要" .. FormatSkillCost(cost)
            GameEvents.Emit("scene:skill")
            return
        end

        playerData.gold = playerData.gold - cost
        playerData.unlockedSkillSlots = index
        skillMergeMessage = "已解锁第" .. index .. "个技能栏"
        NormalizeSkills()
        InitSkillRuntime()
        SaveCloudData(true)
        GameEvents.Emit("scene:skill")
    end

    local slotMinWidth = 60
    local slotGap = 4
    local slotCellHeight = 68
    local slotIconSize = 28
    local slotNameSize = 8
    local slotMetaSize = 8

    local function MakeSlotCell(index)
        local unlocked = index <= GetUnlockedSkillSlotCount()
        local skill = unlocked and FindSkillCardByUid(playerData.skillSlots[index]) or nil
        local def = skill and GetSkillDef(skill.id) or nil
        local cost = CONFIG.SkillSlotUnlockCosts[index - CONFIG.SkillSlotBaseCount]
        local lockedText = cost and FormatSkillCost(cost) or "未解锁"
        local starColor = skill and GetSkillStarVisualColor(skill) or PX.goldDim
        return UI.Panel {
            height = slotCellHeight,
            minWidth = slotMinWidth,
            overflow = "hidden",
            justifyContent = "center",
            alignItems = "center",
            gap = 2,
            backgroundColor = not unlocked and { 16, 15, 26, 238 } or (skill and { 25, 23, 44, 246 } or { 19, 18, 34, 242 }),
            borderWidth = { 1, 1, 2, 1 },
            borderColor = not unlocked and { 78, 72, 58, 165 } or (skill and starColor or PX.goldDim),
            onClick = not unlocked and function(self) TryUnlockSlot(index) end or (skill and function(self) SelectSkill(skill.uid) end or nil),
            children = unlocked and {
                MakeSkillIcon(def, skill and slotIconSize or math.max(24, slotIconSize - 4), tostring(index), skill ~= nil, starColor),
                UI.Label {
                    width = "100%",
                    text = skill and SkillCardTitle(skill) or "空",
                    fontSize = slotNameSize,
                    fontColor = skill and PX.textWhite or PX.textGray,
                    fontWeight = skill and "bold" or "normal",
                    textAlign = "center",
                    maxLines = 1,
                    textStroke = skill and { width = 1, color = { 8, 6, 16, 210 } } or nil,
                },
                UI.Label {
                    width = "100%",
                    text = skill and SkillStarText(skill) or ("槽" .. index),
                    fontSize = slotMetaSize,
                    fontColor = skill and starColor or PX.textGray,
                    fontWeight = skill and "bold" or "normal",
                    textAlign = "center",
                },
                skill and UI.Label {
                    text = "装",
                    fontSize = 6,
                    fontColor = { 30, 12, 10, 255 },
                    fontWeight = "bold",
