                    position = "absolute",
                    right = 1,
                    top = 1,
                    backgroundColor = PX.textGold,
                    borderWidth = 1,
                    borderColor = { 105, 55, 12, 255 },
                    paddingHorizontal = 2,
                } or nil,
            } or {
                UI.Label {
                    text = "锁",
                    fontSize = slotMetaSize + 2,
                    fontColor = { 85, 74, 58, 255 },
                    fontWeight = "bold",
                    textAlign = "center",
                    backgroundColor = { 11, 10, 20, 205 },
                    borderWidth = 1,
                    borderColor = { 82, 72, 54, 180 },
                    paddingHorizontal = 4,
                    paddingVertical = 2,
                },
                UI.Label { width = "100%", text = lockedText, fontSize = slotNameSize, fontColor = PX.textGold, textAlign = "center" },
            },
        }
    end

    local content = {}

    local selectedLoadoutIndex = playerData.activeSkillLoadoutIndex or 1
    EnsureRunSkillSynergies(true)

    local function GetRunSynergySelectionText()
        local names = {}
        for _, synergyId in ipairs(GetRunSkillSynergyIds()) do
            local def = GetSkillSynergyDef(synergyId)
            table.insert(names, def and def.name or synergyId)
        end
        return #names > 0 and table.concat(names, "、") or "等待系统生成"
    end

    local function ShowSkillSynergyModal()
        local selected = {}
        for _, synergyId in ipairs(GetRunSkillSynergyIds()) do
            selected[synergyId] = true
        end
        local equipped = {}
        for _, skill in ipairs(GetEquippedSkills()) do
            equipped[skill.id] = true
        end
        local children = {
            UI.Label {
                text = "系统每局从全部联携中自动随机3组；基地死亡后重新生成。未佩戴完整组件时保留该联携，但不会触发。",
                fontSize = 9,
                fontColor = PX.textGray,
                whiteSpace = "normal",
            },
        }
        for _, synergyId in ipairs(SKILL_SYNERGY_ORDER or {}) do
            local def = GetSkillSynergyDef(synergyId)
            local isSelected = selected[synergyId] == true
            local complete = equipped[def.skills[1]] == true
                and equipped[def.skills[2]] == true
            local stateText = isSelected
                and (complete and "本局随机 · 已激活" or "本局随机 · 缺少组件")
                or "未随机到"
            table.insert(children, UI.Panel {
                width = "100%",
                padding = 6,
                gap = 3,
                backgroundColor = isSelected
                    and (complete and { 28, 54, 42, 245 } or { 58, 43, 28, 245 })
