        local modal = UI.Modal {
            title = "技能联携图鉴",
            size = "md",
            isOpen = false,
            closeOnOverlay = true,
            closeOnEscape = true,
            showCloseButton = true,
            contentPadding = 10,
            contentGap = 6,
            children = {
                UI.ScrollView {
                    width = "100%",
