    })

    table.insert(content, UI.Panel {
        width = "100%",
        minHeight = 38,
        paddingHorizontal = 7,
        paddingVertical = 5,
        flexDirection = "row",
        alignItems = "center",
        gap = 6,
        backgroundColor = { 27, 21, 37, 244 },
        borderWidth = { 1, 1, 2, 3 },
        borderColor = playerData.settings.autoSkillMergeEnabled and { 90, 220, 120, 220 } or PX.goldDim,
        children = {
            UI.Label { text = "自动合成", fontSize = 10, fontColor = PX.textGold, fontWeight = "bold", flexGrow = 1 },
            UI.Panel {
                width = 70,
                height = 28,
                justifyContent = "center",
                alignItems = "center",
                backgroundColor = playerData.settings.autoSkillMergeEnabled and { 35, 70, 45, 255 } or { 40, 40, 58, 255 },
                borderWidth = 1,
                borderColor = playerData.settings.autoSkillMergeEnabled and { 90, 220, 120, 255 } or PX.goldDim,
                onClick = function(self)
                    playerData.settings.autoSkillMergeEnabled = not playerData.settings.autoSkillMergeEnabled
                    SaveCloudData(true)
                    GameEvents.Emit("scene:skill")
                end,
                children = { UI.Label { text = playerData.settings.autoSkillMergeEnabled and "已开启" or "已关闭", fontSize = 9, fontColor = PX.textWhite, fontWeight = "bold", textAlign = "center" } },
            },
            UI.Panel {
                width = 78,
                height = 28,
                justifyContent = "center",
                alignItems = "center",
                backgroundColor = { 30, 30, 48, 255 },
                borderWidth = 1,
                borderColor = PX.goldDim,
                onClick = function(self)
                    local maxAutoSkillMergeStar = CONFIG.SkillMaxStar or 10
                    local target = (playerData.settings.autoSkillMergeTargetStar or 3) + 1
                    if target > maxAutoSkillMergeStar then target = 2 end
                    playerData.settings.autoSkillMergeTargetStar = target
                    SaveCloudData(true)
                    GameEvents.Emit("scene:skill")
                end,
                children = { UI.Label { text = "目标 " .. tostring(playerData.settings.autoSkillMergeTargetStar or 3) .. "星", fontSize = 9, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" } },
            },
        },
    })

    table.insert(content, UI.Panel {
        width = "100%",
        flexDirection = "row",
        gap = 6,
        children = {
            UI.Panel {
                flexGrow = 1,
                height = 32,
                justifyContent = "center",
                alignItems = "center",
                backgroundColor = PX.red,
                borderWidth = 2,
                borderColor = PX.redBright,
                onClick = function(self)
                    local attempts, successCount, failCount = OneKeyMergeSkills()
                    if attempts > 0 then
                        skillMergeMessage = "合成" .. attempts .. "次，成功" .. successCount .. "次，失败" .. failCount .. "次"
                    else
                        skillMergeMessage = "没有可合成的未装备技能卡"
                    end
                    GameEvents.Emit("scene:skill")
                end,
                children = { UI.Label { text = "一键合成", fontSize = 11, fontColor = PX.textWhite, fontWeight = "bold", textAlign = "center" } },
            },
            UI.Panel {
                flexGrow = 1,
                height = 32,
                justifyContent = "center",
                alignItems = "center",
                backgroundColor = { 76, 54, 32, 255 },
                borderWidth = 2,
                borderColor = PX.textGold,
                onClick = function(self)
                    ShowSkillResearchPage()
                end,
                children = { UI.Label { text = "技能分解", fontSize = 11, fontColor = PX.textWhite, fontWeight = "bold", textAlign = "center" } },
            },
        },
    })
    table.insert(content, UI.Label {
        width = "100%",
        text = "分解：未装备且未被方案引用的1～2星技能  |  碎片随机合成也可在此进入",
        fontSize = 8,
        fontColor = PX.textGray,
        textAlign = "center",
        whiteSpace = "normal",
    })

    if skillMergeMessage then
        table.insert(content, UI.Panel {
            width = "100%",
            minHeight = 30,
            paddingHorizontal = 8,
            paddingVertical = 5,
            justifyContent = "center",
            alignItems = "center",
            backgroundColor = { 54, 37, 25, 242 },
            borderWidth = { 1, 1, 2, 1 },
            borderColor = PX.textGold,
            children = {
                UI.Label { text = skillMergeMessage, fontSize = 10, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center", whiteSpace = "normal" },
            },
        })
    end

    local unequippedSkillCount, inventorySkillCount, pendingSkillCount = GetSkillCapacityUsage()
    local unequippedSkillCap = CONFIG.MaxUnequippedSkillCards or 300
    local skillUsageText = tostring(unequippedSkillCount) .. "/" .. tostring(unequippedSkillCap)
    if pendingSkillCount > 0 then
        skillUsageText = skillUsageText .. "（背包" .. tostring(inventorySkillCount)
            .. "+本局暂存" .. tostring(pendingSkillCount) .. "）"
    end
    table.insert(content, MakeSkillSectionTitle(
        "技能背包 · 未装备 " .. skillUsageText .. " 张",
        unequippedSkillCount >= unequippedSkillCap and PX.redBright or PX.gold,
        unequippedSkillCount >= unequippedSkillCap
            and (playerData.settings.autoSkillMergeEnabled == true
                and "已达当前容量：本局暂存技能将在结算时先自动合成"
                or "背包已满：新技能卡将无法获取，先合成或装备技能")
            or "点击技能卡打开详情"
    ))
    table.insert(content, UI.Panel {
        width = "100%",
        gap = 6,
        alignItems = "center",
        children = {
            UI.Panel {
                width = "100%",
                flexDirection = "row",
                justifyContent = "flex-end",
                alignItems = "center",
                gap = 8,
                children = {
                    UI.Panel {
                        height = 30,
                        paddingHorizontal = 14,
                        justifyContent = "center",
                        alignItems = "center",
                        backgroundColor = inventorySkillCount > 1 and { 38, 62, 82, 255 } or { 45, 45, 58, 210 },
                        borderWidth = 1,
                        borderColor = inventorySkillCount > 1 and { 120, 210, 255, 210 } or { 90, 90, 110, 170 },
                        onClick = function(self)
                            local count, changed = SortUnequippedSkills()
                            if count <= 1 then
                                skillMergeMessage = "未装备技能不足，无需排序"
                            elseif changed then
                                skillMergeMessage = "已按星级和技能类型整理" .. tostring(count) .. "张技能卡"
                            else
                                skillMergeMessage = "技能背包已是推荐顺序"
                            end
                            GameEvents.Emit("scene:skill")
                        end,
                        children = {
                            UI.Label { text = "一键排序", fontSize = 11, fontColor = inventorySkillCount > 1 and PX.textWhite or PX.textGray, fontWeight = "bold", textAlign = "center" },
                        },
                    },
                },
            },
        },
    })

    local skillData = {}
    local skillGroups = {}
    local skillGroupByKey = {}
    for _, skill in ipairs(playerData.skills) do
        if not IsSkillUidEquipped(skill.uid) then
            local star = math.max(1, math.floor(skill.star or 1))
            local key = tostring(skill.id) .. "@" .. tostring(star)
            local group = skillGroupByKey[key]
            if group == nil then
                group = {
                    skill = skill,
                    count = 0,
                }
                skillGroupByKey[key] = group
                table.insert(skillGroups, group)
            end
            group.count = group.count + 1
        end
    end
    for _, group in ipairs(skillGroups) do
        table.insert(skillData, group)
    end

    local skillGrid
    if #skillData > 0 then
        local SKILL_CARD_HEIGHT = 72
        local SKILL_MIN_CARD_WIDTH = 64
        local SKILL_ICON_SIZE = 38
        local SKILL_GAP = 6
        local skillCards = {}

        for _, group in ipairs(skillData) do
            local skill = group.skill
            local def = GetSkillDef(skill.id)
            local accentColor = GetSkillStarVisualColor(skill)
            table.insert(skillCards, UI.Panel {
                height = SKILL_CARD_HEIGHT,
                minWidth = SKILL_MIN_CARD_WIDTH,
                overflow = "hidden",
                justifyContent = "center",
                alignItems = "center",
                gap = 2,
                paddingHorizontal = 3,
                backgroundColor = { 31, 26, 45, 248 },
                borderWidth = { 1, 1, 2, 1 },
                borderColor = accentColor,
                onClick = (function(selectedUid)
                    return function(self) SelectSkill(selectedUid) end
                end)(skill.uid),
                children = {
                    MakeSkillIcon(def, SKILL_ICON_SIZE, "技", true, accentColor),
                    UI.Label {
                        text = SkillCardTitle(skill)
                            .. (group.count > 1 and (" ×" .. tostring(group.count)) or ""),
                        width = "100%",
                        fontSize = 8,
                        fontColor = accentColor,
                        fontWeight = "bold",
                        textAlign = "center",
                        maxLines = 1,
                    },
                    UI.Label {
                        text = SkillStarText(skill),
                        width = "100%",
                        fontSize = 8,
                        fontColor = accentColor,
                        fontWeight = "bold",
                        textAlign = "center",
                    },
                },
            })
        end

        skillGrid = UI.Panel {
            width = "100%",
            minWidth = 0,
            padding = 6,
            backgroundColor = { 27, 21, 37, 244 },
            borderWidth = 1,
            borderColor = PX.goldDim,
            children = {
                UI.SimpleGrid {
                    width = "100%",
                    minColumnWidth = SKILL_MIN_CARD_WIDTH,
                    gap = SKILL_GAP,
                    children = skillCards,
                },
            },
        }
    end

    if #skillData == 0 then
        table.insert(content, UI.Panel {
            width = "100%", height = 48,
            justifyContent = "center", alignItems = "center",
            children = {
                UI.Label {
                    text = #playerData.skills == 0
                        and "尚未获得技能"
                        or "未装备技能卡为空",
                    fontSize = 10,
                    fontColor = PX.textGray,
                    textAlign = "center",
                },
            },
        })
    else
        table.insert(content, skillGrid)
    end

    UI.SetRoot(BuildSubPage("技能", content, nil, nil, { wideContent = true }), true)
    print("[Page] 技能页面")
end

-- 重置完成提示：展示本次返还的转生石
function ShowRebirthResetResultModal(refunded)
    local modal
    modal = UI.Modal {
        title = "重置完成",
        size = "sm",
        isOpen = false,
        closeOnOverlay = true,
        closeOnEscape = true,
        showCloseButton = true,
        contentPadding = 14,
        contentGap = 10,
        onClose = function(self) self:Destroy() end,
        children = {
            UI.Label {
                text = "永久强化等级已清空，已返还 " .. tostring(math.max(0, math.floor(tonumber(refunded) or 0))) .. " 转生石。",
                fontSize = 13,
                fontColor = PX.textGold,
                fontWeight = "bold",
                textAlign = "center",
                whiteSpace = "normal",
            },
            UI.Label {
                text = "现在可以在强化卡片中重新分配加点。",
                fontSize = 11,
                fontColor = PX.textGray,
                textAlign = "center",
                whiteSpace = "normal",
            },
        },
    }
    modal:SetFooter(UI.Panel {
        width = "100%",
        flexDirection = "row",
        justifyContent = "center",
        children = {
            UI.Button {
                text = "知道了",
                variant = "primary",
                onClick = function() modal:Close() end,
            },
        },
    })
    modal:Open()
end

-- 重置加点确认弹窗：观看一次激励广告后清空全部永久强化并等额返还转生石
function ShowRebirthResetConfirmModal()
    if not HasRebirthUpgradesToReset() then
        print("[RebirthReset] 当前没有可重置的强化，跳过重置弹窗")
        return false
    end
    local refund = GetRebirthUpgradeResetRefund()
    local settled = false
    local uiAlive = true
    local modal
    -- 广告按钮下方提示（加载中/失败文案，固定高度避免布局跳动）
    local hintLabel = UI.Label {
        text = "",
        fontSize = 10,
        height = 14,
        fontColor = PX and PX.textGold or { 245, 200, 92, 255 },
        textAlign = "center",
        whiteSpace = "normal",
    }
    local function CloseModal()
        if modal ~= nil and modal:IsOpen() then modal:Close() end
    end
    modal = UI.Modal {
        title = "重置加点",
        size = "sm",
        isOpen = false,
        closeOnOverlay = true,
        closeOnEscape = true,
        showCloseButton = true,
        contentPadding = 14,
        contentGap = 10,
        onClose = function(self)
            -- 弹窗关闭后不再回写控件，避免操作已销毁的控件
            uiAlive = false
            self:Destroy()
        end,
        children = {
            UI.Label {
                text = "观看一次激励广告，即可清空以下全部永久强化等级，并按历史消耗等额返还转生石，返还后可重新加点。",
                fontSize = 12,
                fontColor = PX.textGray,
                textAlign = "center",
                whiteSpace = "normal",
            },
            UI.Label {
                text = "攻血强化 " .. tostring(refund.attackHpLevel) .. " 次，返还 " .. tostring(refund.attackHp)
                    .. "\n跳层强化 Lv." .. tostring(refund.skipLevel) .. "，返还 " .. tostring(refund.skip)
                    .. "\n技能伤害 Lv." .. tostring(refund.skillDamageLevel) .. "，返还 " .. tostring(refund.skillDamage)
                    .. "\n分身暴击 Lv." .. tostring(refund.cloneCritLevel) .. "，返还 " .. tostring(refund.cloneCrit),
                fontSize = 11,
                fontColor = PX.textWhite,
                textAlign = "center",
                whiteSpace = "normal",
            },
            UI.Label {
                text = "共返还 " .. tostring(refund.total) .. " 转生石",
                fontSize = 14,
                fontColor = PX.textGold,
                fontWeight = "bold",
                textAlign = "center",
            },
            hintLabel,
        },
    }
    modal:SetFooter(UI.Panel {
        width = "100%",
        flexDirection = "row",
        justifyContent = "center",
        gap = 8,
        children = {
            UI.Button {
                text = "取消",
                variant = "secondary",
                onClick = function() CloseModal() end,
            },
            UI.Button {
                text = "看广告重置",
                variant = "primary",
                onClick = function(self)
                    if settled then return end
                    if rewardAdInFlight then
                        -- 上次请求已超时未复位 → 先复位，随后直接重新发起
                        if rewardAdDeadline > 0 and os.clock() >= rewardAdDeadline then
                            rewardAdFlowEnded = true
                            FinishRewardAd({ success = false, msg = "广告响应超时" })
                        else
                            hintLabel:SetText("广告正在加载，请稍候…")
                            return
                        end
                    end
                    self:SetDisabled(true)
                    hintLabel:SetText("")
                    ShowRewardAd(function(success, msg)
                        if settled then return end
                        if success then
                            settled = true
                            local refunded = PerformRebirthUpgradeReset()
                            if uiAlive then CloseModal() end
                            GameEvents.Emit("scene:rebirth")
                            if refunded > 0 then
                                ShowRebirthResetResultModal(refunded)
                            end
                        elseif uiAlive then
                            -- 广告失败：恢复按钮并提示，保留弹窗供玩家重试或关闭
                            self:SetDisabled(false)
                            hintLabel:SetText(GetRewardAdFailureMessage(msg))
                        end
                    end)
                end,
            },
        },
    })
    modal:Open()
    print("[RebirthReset] 显示重置确认弹窗，可返还转生石:", refund.total)
    return true
end

function ShowRebirthPage()
    currentScreen = "subpage"
    currentSubPage = "rebirth"
    UpdateScreenMetrics()
    NormalizeRebirthStoneSystem()

    local rebirthCost = GetRebirthStoneUpgradeCost()
    local canRebirth = (playerData.rebirthStone or 0) >= rebirthCost
    local bestFloorForPreview = math.max(1, playerData.bestFloor or 1)
    local bestClaimFloor = playerData.rebirthStoneBestClaimFloor or 0
    local firstClearPending = CalculateRebirthStoneReward(bestFloorForPreview)
    local bestTierOffset = GetRebirthStoneTierOffset(bestFloorForPreview)
    local bestPerSeg = GetRepeatRebirthStoneSegmentReward(1, bestTierOffset)
    local nextRewardPreview = firstClearPending
    local nextUpgradeBonus = GetNextRebirthUpgradeBonus()
    local skipLevel = GetSkipLevelUpgradeLevel()
    local skipMaxLevel = CONFIG.SkipLevelMaxUpgradeLevel or 10
    local skipCost = GetSkipLevelUpgradeCost()
    local skipFull = skipLevel >= skipMaxLevel
    local skipEnabled = IsSkipLevelEnabled()
    local canSkipUpgrade = (not skipFull) and skipCost ~= nil and (playerData.rebirthStone or 0) >= skipCost
    local skipCurrentPercent = GetSkipLevelChancePercent(skipLevel)
    local skipNextPercent = skipFull and skipCurrentPercent or GetSkipLevelChancePercent(skipLevel + 1)
    local skipTwoCurrentPercent = GetSkipTwoLevelChancePercent(skipLevel)
    local skipTwoNextPercent = skipFull and skipTwoCurrentPercent or GetSkipTwoLevelChancePercent(skipLevel + 1)

    local skillDmgLevel = GetSkillDamageUpgradeLevel()
    local skillDmgMaxLevel = CONFIG.SkillDamageMaxUpgradeLevel or 10
    local skillDmgCost = GetSkillDamageUpgradeCost()
    local skillDmgFull = skillDmgLevel >= skillDmgMaxLevel
    local canSkillDmgUpgrade = (not skillDmgFull) and skillDmgCost ~= nil and (playerData.rebirthStone or 0) >= skillDmgCost
    local skillDmgCurrentPercent = GetSkillDamagePercent(skillDmgLevel)
    local skillDmgNextPercent = skillDmgFull and skillDmgCurrentPercent or GetSkillDamagePercent(skillDmgLevel + 1)

    local cloneCritLevel = GetCloneCritUpgradeLevel()
    local cloneCritMaxLevel = CONFIG.CloneCritMaxUpgradeLevel or 20
    local cloneCritCost = GetCloneCritUpgradeCost()
    local cloneCritFull = cloneCritLevel >= cloneCritMaxLevel
    local canCloneCritUpgrade = (not cloneCritFull) and cloneCritCost ~= nil and (playerData.rebirthStone or 0) >= cloneCritCost
    local cloneCritCurrentInherit = GetCloneCritInheritPercent(cloneCritLevel)
    local cloneCritNextInherit = cloneCritFull and cloneCritCurrentInherit or GetCloneCritInheritPercent(cloneCritLevel + 1)
    local heroStats = GetEquipmentStats()
    local heroEffCritRate = GetEffectiveCritRate(heroStats)
    local previewFloor = math.max(1, math.floor(playerData.currentFloor or playerData.bestFloor or 1))
    local heroEffCritDmg = GetEffectiveCritDamageAgainstMonster(heroStats, { floor = previewFloor })
    local cloneCurrentCritRate = heroEffCritRate * cloneCritCurrentInherit / 100
    local cloneCurrentCritDmg = heroEffCritDmg * cloneCritCurrentInherit / 100
    local cloneNextCritRate = cloneCritFull and cloneCurrentCritRate or (heroEffCritRate * cloneCritNextInherit / 100)
    local cloneNextCritDmg = cloneCritFull and cloneCurrentCritDmg or (heroEffCritDmg * cloneCritNextInherit / 100)

    local resetRefund = GetRebirthUpgradeResetRefund()
    local canResetUpgrades = HasRebirthUpgradesToReset()
