local function MakeAdventureSectionTitle(text, hint)
    return UI.Panel {
        width = "100%",
        minHeight = hint and 46 or 34,
        paddingHorizontal = 12,
        paddingVertical = 6,
        gap = 3,
        justifyContent = "center",
        backgroundColor = { 12, 20, 48, 252 },
        borderWidth = { 2, 2, 4, 6 },
        borderColor = PX.goldDim,
        children = {
            UI.Label { text = "◆  " .. text, fontSize = 14, fontColor = PX.textGold, fontWeight = "bold" },
            hint and UI.Label { text = hint, fontSize = 8, fontColor = PX.textGray, whiteSpace = "normal" } or nil,
        },
    }
end

local function MakeAdventureAction(text, enabled, onClick, active)
    return UI.Panel {
        minWidth = 82,
        height = 30,
        paddingHorizontal = 10,
        justifyContent = "center",
        alignItems = "center",
        backgroundColor = enabled and (active and { 82, 35, 58, 255 } or { 38, 70, 88, 255 }) or { 45, 45, 58, 210 },
        borderWidth = 1,
        borderColor = enabled and (active and PX.textGold or { 120, 210, 255, 220 }) or { 90, 90, 110, 170 },
