            UI.Panel { width = "100%", flexDirection = "row", flexWrap = "wrap", justifyContent = "center", gap = 6, children = styleButtons },
            MakeAdventureSectionTitle("中间特效", "五套铭牌内部背景，点击后立即预览"),
            UI.Panel { width = "100%", flexDirection = "row", flexWrap = "wrap", justifyContent = "center", gap = 6, children = innerBgButtons },
