local function MakeAdventureSkillIcon(def, size, starText, active, locked, onClick, onDoubleTap)
    size = size or 42
    local accentColor = locked
        and { 90, 82, 96, 180 }
        or (active and PX.textGold or { 120, 210, 255, 220 })
    local iconChildren = {}
    if def and def.iconImage then
        table.insert(iconChildren, UI.Panel {
            width = math.max(20, size - 6),
            height = math.max(20, size - 6),
            backgroundImage = def.iconImage,
            backgroundFit = "contain",
            opacity = locked and 0.3 or 1,
        })
    else
        table.insert(iconChildren, UI.Label {
            text = (def and def.icon) or "技",
            fontSize = math.max(12, math.floor(size * 0.42)),
            fontColor = locked and PX.textGray or PX.textWhite,
            fontWeight = "bold",
            textAlign = "center",
        })
    end
    if locked then
        table.insert(iconChildren, UI.Label {
            position = "absolute",
            left = 0,
            right = 0,
            top = 0,
            bottom = 0,
            text = "锁",
            fontSize = math.max(10, math.floor(size * 0.24)),
            fontColor = { 225, 225, 235, 220 },
            fontWeight = "bold",
            textAlign = "center",
            backgroundColor = { 8, 8, 16, 105 },
        })
    end
    local children = {
        UI.Panel {
            width = math.max(20, size - 6),
            height = math.max(20, size - 6),
            minWidth = math.max(20, size - 6),
            minHeight = math.max(20, size - 6),
            justifyContent = "center",
            alignItems = "center",
            children = iconChildren,
        },
    }
    if starText then
        table.insert(children, UI.Label {
            text = starText,
            fontSize = 8,
            fontColor = locked and PX.textGray or PX.textGold,
            fontWeight = "bold",
            textAlign = "center",
        })
    end
    return UI.Panel {
        width = size,
        height = size + (starText and 12 or 0),
        minWidth = size,
        minHeight = size + (starText and 12 or 0),
        flexShrink = 0,
        gap = 1,
        justifyContent = "center",
        alignItems = "center",
        backgroundColor = locked and { 22, 21, 31, 230 } or { 20, 17, 38, 240 },
        borderWidth = active and 2 or 1,
        borderColor = accentColor,
        onClick = onClick,
        onDoubleTap = onDoubleTap,
        children = children,
    }
end

local function MakeAdventureSkillChoice(def, starText, enabled, active, onClick, onDoubleTap)
    return MakeAdventureSkillIcon(
        def,
        42,
        starText,
        active,
        not enabled,
        enabled and onClick or nil,
        enabled and onDoubleTap or nil
    )
end

local function BuildSkillCollectionChips(defs, discovered)
    local chips = {}
    for _, def in ipairs(defs or {}) do
        local unlocked = discovered[def.id] == true
        table.insert(chips, MakeAdventureSkillIcon(
            def.def,
            48,
            unlocked and ("最高" .. tostring(def.highestStar or 1) .. "星") or nil,
            false,
            not unlocked
        ))
    end
    return chips
end

