local function IsLowerSkillUid(candidateUid, currentUid)
    local candidateText = tostring(candidateUid or "")
    local currentText = tostring(currentUid or "")
    local candidateNumber = tonumber(candidateText:match("(%d+)$"))
    local currentNumber = tonumber(currentText:match("(%d+)$"))
    if candidateNumber ~= nil and currentNumber ~= nil
        and candidateNumber ~= currentNumber then
        return candidateNumber < currentNumber
    end
    return candidateText < currentText
end

local function GetGroupedEligibleSkills(minStar, maxStar)
    local groupsByKey = {}
    for _, skill in ipairs(playerData.skills or {}) do
        local star = GetSkillStar(skill)
        local protected = IsSkillProtectedFromResearch(skill.uid)
        if not protected and star >= minStar and star <= maxStar then
            local key = tostring(skill.id) .. ":" .. tostring(star)
            local group = groupsByKey[key]
            if group == nil then
                group = {
                    id = skill.id,
                    star = star,
                    count = 0,
                    skill = skill,
                }
                groupsByKey[key] = group
            end
            group.count = group.count + 1
            if IsLowerSkillUid(skill.uid, group.skill.uid) then
                group.skill = skill
            end
        end
    end

    local result = {}
    for _, group in pairs(groupsByKey) do
        table.insert(result, group)
    end
    table.sort(result, function(a, b)
        if a.star ~= b.star then return a.star > b.star end
        if a.id ~= b.id then return tostring(a.id) < tostring(b.id) end
        return IsLowerSkillUid(a.skill.uid, b.skill.uid)
    end)
    return result
end

local function GetDismantleEligibleSkills()
    return GetGroupedEligibleSkills(1, math.max(1, CONFIG.SkillDismantleMaxStar or 2))
end

function ShowSkillResearchPage()
    currentScreen = "subpage"
    currentSubPage = "skill_research"
    UpdateScreenMetrics()
    NormalizeEquipmentSettings()
    NormalizeSkills()
    NormalizeSkillLoadouts()
    RebuildSkillProtectionCache()
    NormalizeSkillFragments()
    NormalizeAdventureData()

    local dismantleSource = FindSkillCardByUid(fragmentSelectedSourceUid)
    if dismantleSource ~= nil then
        local protected = IsSkillProtectedFromResearch(dismantleSource.uid)
        if protected then dismantleSource = nil; fragmentSelectedSourceUid = nil end
    end

    local dismantleGroups = GetDismantleEligibleSkills()
    local dismantleCount = 0
    for _, group in ipairs(dismantleGroups) do
        dismantleCount = dismantleCount + group.count
    end

    local function OpenDismantleConfirm(sourceUid, sourceDef, sourceStar)
        local canDismantle, reason, source, star = CanDismantleSkill(sourceUid)
        if not canDismantle then
            fragmentPageMessage = reason
            ShowSkillResearchPage()
            return
        end
        sourceDef = sourceDef or GetSkillDef(source.id)
        sourceStar = star or sourceStar
        local modal
        modal = UI.Modal {
            title = "确认技能分解",
            size = "sm",
            isOpen = false,
            closeOnOverlay = true,
            closeOnEscape = true,
            showCloseButton = true,
            children = {
                UI.Label {
                    text = "分解 " .. (sourceDef and sourceDef.name or "技能")
                        .. " " .. tostring(sourceStar) .. "星？",
                    fontSize = 12,
                    fontColor = PX.textGold,
                    fontWeight = "bold",
                    textAlign = "center",
                },
                UI.Label {
                    text = "将获得1个同星碎片，此操作不可撤销。",
                    fontSize = 9,
                    fontColor = PX.textGray,
                    textAlign = "center",
                },
            },
        }
        modal:SetFooter(UI.Panel {
            width = "100%",
            flexDirection = "row",
            justifyContent = "center",
            gap = 8,
            children = {
                MakeAdventureAction("取消", true, function() modal:Close() end),
                MakeAdventureAction("确定分解", true, function()
                    modal:Close()
                    local ok, message = DismantleSkill(sourceUid)
                    fragmentPageMessage = message
                    if ok then fragmentSelectedSourceUid = nil end
                    ShowSkillResearchPage()
                end, true),
            },
        })
        modal:Open()
    end

    local function OpenDismantleBatchConfirm(star)
        local preview = GetDismantleBatchPreview(star)
        if not preview.canExecute then
            fragmentPageMessage = preview.blockedReason
            ShowSkillResearchPage()
            return
        end

        local skipLines = {}
        for reason, count in pairs(preview.skipReasons) do
            table.insert(skipLines, tostring(count) .. "张：" .. tostring(reason))
        end
        table.sort(skipLines)
        local summaryLines = {
            "当前星级可分解数量：" .. tostring(preview.eligibleCount) .. "张",
            "跳过数量：" .. tostring(preview.skippedCount) .. "张",
            "预计获得碎片：" .. tostring(preview.star) .. "星碎片 ×" .. tostring(preview.expectedYield),
            "跳过原因：" .. (#skipLines > 0 and table.concat(skipLines, "；") or "无"),
        }

        local modal
        modal = UI.Modal {
            title = "确认一键分解",
            size = "sm",
            isOpen = false,
            closeOnOverlay = true,
            closeOnEscape = true,
            showCloseButton = true,
            children = {
                UI.Label { text = "分解全部" .. tostring(preview.star) .. "星技能？", fontSize = 12, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
                UI.Label { text = table.concat(summaryLines, "\n"), fontSize = 9, fontColor = PX.textWhite, textAlign = "center", whiteSpace = "normal" },
                UI.Label { text = "已装备技能和被技能方案引用的技能会跳过。此操作不可撤销。", fontSize = 8, fontColor = PX.textGray, textAlign = "center", whiteSpace = "normal" },
            },
        }
        modal:SetFooter(UI.Panel {
            width = "100%", flexDirection = "row", justifyContent = "center", gap = 8,
            children = {
                MakeAdventureAction("取消", true, function() modal:Close() end),
                MakeAdventureAction("确定分解", true, function()
                    modal:Close()
                    local ok, message, result = DismantleSkillsByStar(preview.star)
                    if ok then
                        local resultText = message
                        if result.skippedCount > 0 then
                            local resultLines = {}
                            for reason, count in pairs(result.skipReasons) do
                                table.insert(resultLines, tostring(count) .. "张" .. tostring(reason))
                            end
                            table.sort(resultLines)
                            resultText = resultText .. "\n跳过 " .. result.skippedCount .. " 张：" .. table.concat(resultLines, "，")
                        end
                        fragmentPageMessage = resultText
                    else
                        fragmentPageMessage = message
                    end
                    fragmentSelectedSourceUid = nil
                    ShowSkillResearchPage()
                end, true),
            },
        })
        modal:Open()
    end

    local content = {
        UI.Panel {
            width = "100%", padding = 9, gap = 4,
            backgroundColor = { 26, 20, 38, 246 }, borderWidth = 2, borderColor = PX.textGold,
            children = {
                UI.Label { text = "技能研究室", fontSize = 15, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
                UI.Label { text = "技能分解：未装备且未被方案引用的1～2星技能；同页可进行碎片随机合成。", fontSize = 9, fontColor = PX.textGray, textAlign = "center", whiteSpace = "normal" },
                UI.Label { text = "操作：点击或双击技能卡会立即弹出分解确认；装备栏和技能方案中的技能不会显示。", fontSize = 9, fontColor = { 255, 220, 120, 230 }, textAlign = "center", whiteSpace = "normal" },
                UI.Label { text = "可分解技能 " .. tostring(dismantleCount) .. "张", fontSize = 9, fontColor = { 120, 210, 255, 230 }, textAlign = "center" },
                fragmentPageMessage and UI.Label { text = fragmentPageMessage, fontSize = 9, fontColor = { 120, 210, 255, 230 }, textAlign = "center", whiteSpace = "normal" } or nil,
            },
        },
    }

    table.insert(content, MakeAdventureSectionTitle(
        "技能分解 · 可分解" .. tostring(dismantleCount) .. "张",
        "未装备且未被任一技能方案引用的1～2星技能可分解；每张获得1个同星碎片，3星及以上不可分解"
    ))

    -- 自动分解：开关 + 目标星级，每层结算后分解所有低于目标星级的可分解技能。
    local autoDismantlePreviewCount = GetAutoDismantleCount()
    table.insert(content, UI.Panel {
        width = "100%",
        minHeight = 38,
        paddingHorizontal = 7,
        paddingVertical = 5,
        flexDirection = "row",
        alignItems = "center",
        gap = 6,
        backgroundColor = { 27, 21, 37, 244 },
        borderWidth = { 1, 1, 2, 3 },
        borderColor = playerData.settings.autoDismantleEnabled and { 90, 220, 120, 220 } or PX.goldDim,
