                borderWidth = 1,
                borderColor = PX.goldDim,
                onClick = function(self)
                    local maxAutoDismantleStar = math.max(1, CONFIG.SkillDismantleMaxStar or 2)
                    local target = (playerData.settings.autoDismantleTargetStar or 3) + 1
                    if target > maxAutoDismantleStar then target = 1 end
                    playerData.settings.autoDismantleTargetStar = target
                    NormalizeEquipmentSettings()
                    SaveCloudData(true)
                    ShowSkillResearchPage()
                end,
                children = { UI.Label { text = "目标 " .. tostring(playerData.settings.autoDismantleTargetStar or 3) .. "星", fontSize = 9, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" } },
            },
        },
    })
    if playerData.settings.autoDismantleEnabled == true then
        table.insert(content, UI.Label {
            text = "每层结算后自动分解目标" .. tostring(playerData.settings.autoDismantleTargetStar or 3) .. "星及以下的未装备/未引用技能，获得同星碎片",
            fontSize = 8, fontColor = PX.textGray, textAlign = "center", whiteSpace = "normal",
        })
    end

    local dismantlePreview = GetDismantleBatchPreview(dismantleSelectedStar)
    local starOptions = {}
    for star = 1, math.max(1, CONFIG.SkillDismantleMaxStar or 2) do
        local starPreview = GetDismantleBatchPreview(star)
        table.insert(starOptions, {
            value = star,
            label = tostring(star) .. "星（可分解" .. tostring(starPreview.eligibleCount) .. "张）",
        })
    end
    local starSelector = UI.Dropdown {
        width = 250,
        options = starOptions,
        value = dismantleSelectedStar,
        onChange = function(self, value)
            dismantleSelectedStar = math.floor(tonumber(value) or 1)
            fragmentPageMessage = nil
            ShowSkillResearchPage()
        end,
    }
    local batchSkipLines = {}
    for reason, count in pairs(dismantlePreview.skipReasons or {}) do
        table.insert(batchSkipLines, tostring(count) .. "张" .. tostring(reason))
    end
    table.sort(batchSkipLines)
    local batchSummary = "当前星级可分解 " .. tostring(dismantlePreview.eligibleCount) .. "张"
        .. " | 跳过 " .. tostring(dismantlePreview.skippedCount) .. "张"
        .. " | 预计获得" .. tostring(dismantleSelectedStar) .. "星碎片 ×" .. tostring(dismantlePreview.expectedYield)
    local batchChildren = {
        UI.Label { text = "一键分解同星级技能", fontSize = 12, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" },
        UI.Label { text = "选择星级后，将处理所有符合条件的该星级技能，不区分技能名称和类型。", fontSize = 8, fontColor = PX.textGray, textAlign = "center", whiteSpace = "normal" },
        starSelector,
        UI.Label { text = batchSummary, fontSize = 9, fontColor = dismantlePreview.canExecute and PX.textWhite or PX.textGray, textAlign = "center", whiteSpace = "normal" },
        UI.Label { text = "跳过原因：" .. (#batchSkipLines > 0 and table.concat(batchSkipLines, "；") or "无"), fontSize = 8, fontColor = PX.textGray, textAlign = "center", whiteSpace = "normal" },
    }
    if dismantlePreview.blockedReason then
        table.insert(batchChildren, UI.Label {
            text = dismantlePreview.blockedReason,
            fontSize = 8,
            fontColor = PX.textGray,
            textAlign = "center",
            whiteSpace = "normal",
        })
    end
    table.insert(batchChildren, MakeAdventureAction("分解该星级全部技能", dismantlePreview.canExecute, function()
        OpenDismantleBatchConfirm(dismantleSelectedStar)
    end, true))

    table.insert(content, UI.Panel {
        width = "100%",
        padding = 9,
        gap = 5,
        alignItems = "center",
        backgroundColor = { 31, 24, 39, 244 },
        borderWidth = 2,
        borderColor = dismantlePreview.canExecute and PX.textGold or PX.goldDim,
        children = batchChildren,
    })

    local dismantleButtons = {}
    for _, group in ipairs(dismantleGroups) do
        local skillForClick = group.skill
        local skillStar = group.star
        local def = GetSkillDef(group.id)
        local function OpenSkillConfirm()
            fragmentSelectedSourceUid = skillForClick.uid
            fragmentPageMessage = nil
            OpenDismantleConfirm(skillForClick.uid, def, skillStar)
        end
        table.insert(dismantleButtons, MakeAdventureSkillChoice(
            def,
            tostring(skillStar) .. "星 ×" .. tostring(group.count),
            true,
            dismantleSource and dismantleSource.uid == skillForClick.uid,
            OpenSkillConfirm,
            OpenSkillConfirm
        ))
    end
    if #dismantleButtons == 0 then
        table.insert(content, UI.Label {
            text = "当前没有可分解技能：仅显示未装备、未被技能方案引用的1～2星技能。",
            fontSize = 10,
            fontColor = PX.textGray,
            textAlign = "center",
        })
    else
        table.insert(content, UI.Panel {
            width = "100%",
            flexDirection = "row",
            flexWrap = "wrap",
            justifyContent = "center",
            gap = 6,
            children = dismantleButtons,
        })
    end

    local canDismantle, dismantleReason, _, dismantleStar = CanDismantleSkill(fragmentSelectedSourceUid)
    local dismantleDef = dismantleSource and GetSkillDef(dismantleSource.id) or nil
    table.insert(content, UI.Panel {
        width = "100%",
        padding = 9,
        gap = 5,
        alignItems = "center",
        backgroundColor = { 31, 24, 39, 244 },
        borderWidth = 2,
        borderColor = canDismantle and PX.textGold or PX.goldDim,
        children = {
            UI.Label {
                text = dismantleSource and ((dismantleDef and dismantleDef.name or dismantleSource.id)
                    .. " " .. tostring(dismantleStar) .. "星 → " .. tostring(dismantleStar) .. "星碎片 ×1")
                    or "请选择要分解的技能卡",
                fontSize = 11,
                fontColor = canDismantle and PX.textGold or PX.textGray,
                fontWeight = "bold",
                textAlign = "center",
            },
            fragmentPageMessage and UI.Label {
                text = fragmentPageMessage,
                fontSize = 9,
                fontColor = PX.textGold,
                textAlign = "center",
                whiteSpace = "normal",
            } or nil,
            MakeAdventureAction("确认分解", canDismantle, function()
                OpenDismantleConfirm(fragmentSelectedSourceUid, dismantleDef, dismantleStar)
            end, true),
        },
    })

    table.insert(content, MakeAdventureSectionTitle(
        "碎片随机合成",
        "仅支持1～2星碎片合成：消耗5个N星碎片，等概率随机获得全部19种技能中的1张N+1星技能卡"
    ))
    local fragments = NormalizeSkillFragments()
    local fragmentRows = {}
    for star = 1, math.max(1, CONFIG.SkillFragmentSynthesisMaxStar or 2) do
        local targetStar = star
        local canSynthesize, synthReason = CanSynthesizeSkillFromFragments(targetStar)
        table.insert(fragmentRows, UI.Panel {
            width = 126,
            minHeight = 58,
            padding = 6,
            gap = 3,
            alignItems = "center",
            backgroundColor = { 23, 22, 42, 244 },
            borderWidth = 2,
            borderColor = canSynthesize and { 120, 210, 255, 220 } or PX.goldDim,
            children = {
                UI.Label {
                    text = tostring(targetStar) .. "星碎片  " .. tostring(fragments[targetStar] or 0)
                        .. "/5 → " .. tostring(targetStar + 1) .. "星",
                    fontSize = 10,
                    fontColor = canSynthesize and PX.textGold or PX.textGray,
                    fontWeight = "bold",
                    textAlign = "center",
                },
                MakeAdventureAction("随机合成", canSynthesize, function()
                    local modal
                    modal = UI.Modal {
                        title = "确认碎片合成",
                        size = "sm",
                        isOpen = false,
                        closeOnOverlay = true,
                        closeOnEscape = true,
                        showCloseButton = true,
                        children = {
                            UI.Label {
                                text = "消耗5个" .. targetStar .. "星碎片，随机获得1张"
                                    .. tostring(targetStar + 1) .. "星技能卡？",
                                fontSize = 10,
                                fontColor = PX.textGold,
                                fontWeight = "bold",
                                textAlign = "center",
                                whiteSpace = "normal",
                            },
                        },
                    }
                    modal:SetFooter(UI.Panel {
                        width = "100%",
                        flexDirection = "row",
                        justifyContent = "center",
                        gap = 8,
                        children = {
                            MakeAdventureAction("取消", true, function() modal:Close() end),
                            MakeAdventureAction("确定合成", true, function()
                                modal:Close()
                                local _, message = SynthesizeSkillFromFragments(targetStar)
                                fragmentPageMessage = message
                                ShowSkillResearchPage()
                            end, true),
                        },
                    })
                    modal:Open()
                end),
                MakeAdventureAction("批量合成", canSynthesize, function()
                    local maxCount, maxReason = GetSkillFragmentSynthesisMaxCount(targetStar)
                    if maxCount < 1 then
                        fragmentPageMessage = maxReason or "无法批量合成"
                        ShowSkillResearchPage()
                        return
                    end
                    local batchCount = 1
                    local fragmentCost = CONFIG.SkillFragmentSynthesisCost or 5
                    local function BuildBatchSummary(value)
                        return "共消耗" .. tostring(fragmentCost * value) .. "个" .. targetStar
                            .. "星碎片，获得" .. tostring(value) .. "张随机"
                            .. tostring(targetStar + 1) .. "星技能卡"
                    end
                    local countLabel = UI.Label { width = 40, text = tostring(batchCount), fontSize = 16, fontColor = PX.textGold, fontWeight = "bold", textAlign = "center" }
                    local summaryLabel = UI.Label {
                        text = BuildBatchSummary(batchCount),
                        fontSize = 9,
                        fontColor = PX.textWhite,
                        textAlign = "center",
                        whiteSpace = "normal",
                    }
                    local function RefreshBatchLabels()
                        countLabel:SetText(tostring(batchCount))
                        summaryLabel:SetText(BuildBatchSummary(batchCount))
                    end
                    local function StepButton(textValue, enabled, onTap)
                        return UI.Panel {
                            minWidth = 44,
                            height = 30,
                            justifyContent = "center",
                            alignItems = "center",
                            backgroundColor = enabled and { 38, 70, 88, 255 } or { 45, 45, 58, 210 },
                            borderWidth = 1,
                            borderColor = enabled and { 120, 210, 255, 220 } or { 90, 90, 110, 170 },
                            onClick = enabled and onTap or nil,
                            children = {
                                UI.Label { text = textValue, fontSize = 11, fontColor = enabled and PX.textWhite or PX.textGray, fontWeight = "bold", textAlign = "center" },
                            },
                        }
                    end
                    local modal
                    modal = UI.Modal {
                        title = "批量碎片合成",
                        size = "sm",
                        isOpen = false,
                        closeOnOverlay = true,
                        closeOnEscape = true,
                        showCloseButton = true,
                        contentGap = 7,
                        children = {
                            UI.Label {
                                text = "每次消耗5个" .. targetStar .. "星碎片，随机获得1张"
                                    .. tostring(targetStar + 1) .. "星技能卡",
                                fontSize = 9,
                                fontColor = PX.textGold,
                                textAlign = "center",
                                whiteSpace = "normal",
                            },
                            UI.Panel {
                                width = "100%",
                                flexDirection = "row",
                                justifyContent = "center",
                                alignItems = "center",
                                gap = 8,
                                children = {
                                    StepButton("−", batchCount > 1, function()
                                        batchCount = math.max(1, batchCount - 1)
                                        RefreshBatchLabels()
                                    end),
                                    countLabel,
                                    StepButton("＋", batchCount < maxCount, function()
                                        batchCount = math.min(maxCount, batchCount + 1)
                                        RefreshBatchLabels()
                                    end),
                                },
                            },
                            UI.Panel {
                                width = "100%",
                                flexDirection = "row",
                                flexWrap = "wrap",
                                justifyContent = "center",
                                gap = 6,
                                children = {
                                    StepButton("×2", maxCount >= 2, function()
                                        batchCount = math.min(maxCount, 2)
                                        RefreshBatchLabels()
                                    end),
                                    StepButton("×5", maxCount >= 5, function()
                                        batchCount = math.min(maxCount, 5)
                                        RefreshBatchLabels()
                                    end),
                                    StepButton("×10", maxCount >= 10, function()
                                        batchCount = math.min(maxCount, 10)
                                        RefreshBatchLabels()
                                    end),
                                    StepButton("最大" .. tostring(maxCount), true, function()
                                        batchCount = maxCount
                                        RefreshBatchLabels()
                                    end),
                                },
                            },
                            UI.Label {
                                text = "受碎片数量与技能背包容量限制，当前最多可合成" .. tostring(maxCount) .. "次",
                                fontSize = 8,
                                fontColor = PX.textGray,
                                textAlign = "center",
                                whiteSpace = "normal",
                            },
                            summaryLabel,
                        },
                    }
                    modal:SetFooter(UI.Panel {
                        width = "100%",
                        flexDirection = "row",
                        justifyContent = "center",
                        gap = 8,
                        children = {
                            MakeAdventureAction("取消", true, function() modal:Close() end),
                            MakeAdventureAction("确认合成", true, function()
                                modal:Close()
                                local ok, message = BatchSynthesizeSkillFromFragments(targetStar, batchCount)
                                fragmentPageMessage = message
                                ShowSkillResearchPage()
                            end, true),
                        },
                    })
                    modal:Open()
                end),
                not canSynthesize and UI.Label {
                    text = synthReason or "碎片不足",
                    fontSize = 7,
                    fontColor = PX.textGray,
                    textAlign = "center",
                    maxLines = 1,
                } or nil,
            },
        })
    end
    table.insert(content, UI.Panel {
        width = "100%",
        flexDirection = "row",
        flexWrap = "wrap",
        justifyContent = "center",
        gap = 6,
        children = fragmentRows,
    })

    UI.SetRoot(BuildSubPage("技能研究室", content, function()
        skipSkillPageAutoMergeOnce = true
        GameEvents.Emit("scene:skill")
    end, "← 返回技能", { wideContent = true }), true)
end

function HandleRender(eventType, eventData)
    if nvgContext == nil then return end
    local vg = nvgContext
    UpdateScreenMetrics()

    if IsBattleHighVisualLoad and IsBattleHighVisualLoad() then
        fastMultiRenderFrame = (fastMultiRenderFrame or 0) + 1
    else
        fastMultiRenderFrame = 0
    end

    nvgBeginFrame(vg, screenW, screenH, screenDpr)

    if currentScreen == "menu" then
    elseif currentScreen == "subpage" then
        DrawPixelBackground(vg)
    else
        DrawBackground(vg)
        DrawBase(vg)
        DrawMonsters(vg)
        DrawMonsterProjectiles(vg)
        DrawHero(vg)
        DrawClones(vg)
        DrawSkillEffects(vg)
        DrawParticlesFx(vg)
        if currentScreen == "training_result" then
            DrawTrainingResultPanel(vg)
        elseif currentScreen == "rift_decision" then
            DrawEquipmentRiftDecisionPanel(vg)
        elseif currentScreen == "rift_exit_confirm" then
            DrawHUD(vg)
            DrawEquipmentRiftExitConfirmPanel(vg)
        elseif currentScreen == "rift_result" then
            DrawEquipmentRiftResultPanel(vg)
        elseif currentScreen == "auto_continue" then
            DrawAutoContinuePanel(vg)
        else
            DrawHUD(vg)
            if currentScreen == "gameover" then
                DrawGameOverPanel(vg)
            end
        end
    end

    nvgEndFrame(vg)
end

function DrawPixelBackground(vg)
    local time = GetTime():GetElapsedTime()

    nvgBeginPath(vg)
    nvgRect(vg, 0, 0, screenW, screenH)
    local bg = nvgLinearGradient(vg, 0, 0, screenW, screenH,
        nvgRGBA(20, 14, 30, 255),
        nvgRGBA(44, 24, 36, 255))
    nvgFillPaint(vg, bg)
    nvgFill(vg)

    local pulse = 0.5 + 0.5 * math.sin(time * 1.6)
    local glowR = math.max(screenW, screenH) * 0.54
    nvgBeginPath(vg)
    nvgCircle(vg, screenW * 0.50, screenH * 0.30, glowR)
    local topGlow = nvgRadialGradient(vg, screenW * 0.50, screenH * 0.30, 18, glowR,
        nvgRGBA(210, 64, 56, 70 + pulse * 30),
        nvgRGBA(210, 64, 56, 0))
    nvgFillPaint(vg, topGlow)
    nvgFill(vg)

    nvgBeginPath(vg)
    nvgCircle(vg, screenW * 0.50, screenH * 0.72, glowR * 0.78)
    local goldGlow = nvgRadialGradient(vg, screenW * 0.50, screenH * 0.72, 12, glowR * 0.78,
        nvgRGBA(230, 178, 60, 44 + pulse * 24),
        nvgRGBA(230, 178, 60, 0))
    nvgFillPaint(vg, goldGlow)
    nvgFill(vg)

    nvgBeginPath(vg)
    nvgRect(vg, screenW * 0.08, screenH * 0.10, screenW * 0.84, 2)
    nvgRect(vg, screenW * 0.08, screenH * 0.90, screenW * 0.84, 2)
    nvgFillColor(vg, nvgRGBA(225, 180, 70, 72))
    nvgFill(vg)

    local gridSize = 10
    local offset = math.floor((time * 10) % gridSize)
    for gx = -1, math.floor(screenW / gridSize) + 1 do
        for gy = -1, math.floor(screenH / gridSize) + 1 do
            local hash = (gx * 7919 + gy * 104729) % 100
            if hash < 13 then
                local twinkle = 0.5 + 0.5 * math.sin(time * 2.1 + hash)
                local alpha = 22 + twinkle * 42
                nvgBeginPath(vg)
                nvgRect(vg, gx * gridSize, gy * gridSize + offset, 2, 2)
                nvgFillColor(vg, nvgRGBA(180 + hash, 130 + math.floor(hash * 0.5), 78 + hash, alpha))
                nvgFill(vg)
            end
        end
    end

    for i = 1, 7 do
        local x = screenW * (0.05 + i * 0.13)
        local h = screenH * (0.13 + (i % 3) * 0.035)
        local y = screenH - h * 0.45
        nvgBeginPath(vg)
        nvgMoveTo(vg, x, y - h * 0.55)
        nvgLineTo(vg, x - 12, y - h * 0.28)
        nvgLineTo(vg, x - 9, y + h * 0.36)
        nvgLineTo(vg, x + 9, y + h * 0.36)
        nvgLineTo(vg, x + 12, y - h * 0.28)
        nvgClosePath(vg)
        nvgFillColor(vg, nvgRGBA(225, 180, 70, 28))
        nvgFill(vg)

        nvgBeginPath(vg)
        nvgRect(vg, x - 1, y - h * 0.32, 2, h * 0.56)
        nvgFillColor(vg, nvgRGBA(240, 190, 86, 34))
        nvgFill(vg)
    end

    for i = 1, 4 do
        local w = screenW * (0.08 + i * 0.012)
        local h = screenH * (0.08 + i * 0.018)
        local x = (i % 2 == 0) and (screenW - w - 14) or 14
        local y = screenH * (0.14 + i * 0.15)
        nvgBeginPath(vg)
        nvgRect(vg, x, y, w, h)
        nvgFillColor(vg, nvgRGBA(110, 70, 46, 18))
        nvgFill(vg)
        nvgBeginPath(vg)
        nvgRect(vg, x, y, w, 2)
        nvgRect(vg, x, y + h - 2, w, 2)
        nvgFillColor(vg, nvgRGBA(225, 180, 70, 28))
        nvgFill(vg)
    end
end

function DrawBackground(vg)
    if currentBgIndex > 0 and bgImages[currentBgIndex] then
        local imgHandle = bgImages[currentBgIndex]
        local bgSourceW = BATTLE_BG_SOURCE_W or 1376
        local bgSourceH = BATTLE_BG_SOURCE_H or 768
        local scale = math.max(screenW / bgSourceW, screenH / bgSourceH)
        local drawW = bgSourceW * scale
        local drawH = bgSourceH * scale
        local drawX = (screenW - drawW) * 0.5
        local drawY = (screenH - drawH) * 0.5
        local pat = nvgImagePattern(vg, drawX, drawY, drawW, drawH, 0, imgHandle, 1.0)
        nvgBeginPath(vg)
        nvgRect(vg, 0, 0, screenW, screenH)
        nvgFillPaint(vg, pat)
        nvgFill(vg)
        nvgBeginPath(vg)
        nvgRect(vg, 0, 0, screenW, screenH)
        nvgFillColor(vg, nvgRGBA(0, 0, 0, 80))
        nvgFill(vg)
    else
        nvgBeginPath(vg)
        nvgRect(vg, 0, 0, screenW, screenH)
        local bg = nvgLinearGradient(vg, 0, 0, 0, screenH,
            nvgRGBA(10, 10, 22, 255),
            nvgRGBA(20, 12, 24, 255))
        nvgFillPaint(vg, bg)
        nvgFill(vg)
    end

    local time = GetTime():GetElapsedTime()
    local pulse = 0.5 + 0.5 * math.sin(time * 1.8)
    nvgBeginPath(vg)
    nvgCircle(vg, base.x, base.y - CONFIG.BaseHeight * 0.35, 180)
    local baseGlow = nvgRadialGradient(vg, base.x, base.y - CONFIG.BaseHeight * 0.35, 10, 180,
        nvgRGBA(210, 170, 50, 16 + pulse * 12),
        nvgRGBA(210, 170, 50, 0))
    nvgFillPaint(vg, baseGlow)
    nvgFill(vg)
end

function DrawBase(vg)
    local bx, by = base.x, base.y
    local bh, bw = CONFIG.BaseHeight, CONFIG.BaseWidth
    local flashAlpha = 0
    if base.flashTimer > 0 then
        flashAlpha = math.floor((base.flashTimer * 10) % 2) * 100
    end

    if baseImage and baseImage > 0 then
        local BASE_RENDER_SCALE = 2.0
        local drawW = bw * 1.6 * BASE_RENDER_SCALE
        local drawH = bh * BASE_RENDER_SCALE
        local drawX = bx - drawW * 0.5
        local drawY = by + bh * 0.5 - drawH  -- 底部锚定在原碰撞盒底边缘
        local pat = nvgImagePattern(vg, drawX, drawY, drawW, drawH, 0, baseImage, 1.0)
        nvgBeginPath(vg)
        nvgRect(vg, drawX, drawY, drawW, drawH)
        nvgFillPaint(vg, pat)
        nvgFill(vg)
        if flashAlpha > 0 then
            nvgBeginPath(vg)
            nvgRect(vg, drawX, drawY, drawW, drawH)
            nvgFillColor(vg, nvgRGBA(255, 50, 50, flashAlpha))
            nvgFill(vg)
        end
    else
        local bladeTop = by - bh / 2
        local bladeBot = by + bh / 2 - 20
        local bladeW = bw * 0.35
        nvgBeginPath(vg)
        nvgMoveTo(vg, bx, bladeTop - 20)
        nvgLineTo(vg, bx - bladeW, bladeTop + 10)
        nvgLineTo(vg, bx - bladeW, bladeBot)
        nvgLineTo(vg, bx + bladeW, bladeBot)
        nvgLineTo(vg, bx + bladeW, bladeTop + 10)
        nvgClosePath(vg)
        nvgFillColor(vg, nvgRGBA(180, 200, 255, 255))
        nvgFill(vg)
        nvgBeginPath(vg)
        nvgRect(vg, bx - 2, bladeTop - 10, 4, bladeBot - bladeTop + 10)
        nvgFillColor(vg, nvgRGBA(255, 255, 255, 80))
        nvgFill(vg)
        nvgBeginPath(vg)
        nvgRect(vg, bx - bw * 0.8, bladeBot, bw * 1.6, 8)
        nvgFillColor(vg, nvgRGBA(200, 170, 80, 255))
        nvgFill(vg)
        nvgBeginPath(vg)
        nvgRect(vg, bx - bw * 0.2, bladeBot + 8, bw * 0.4, 25)
        nvgFillColor(vg, nvgRGBA(100, 60, 30, 255))
        nvgFill(vg)
        if flashAlpha > 0 then
            nvgBeginPath(vg)
            nvgRect(vg, bx - bw, by - bh/2 - 25, bw*2, bh + 60)
            nvgFillColor(vg, nvgRGBA(255, 50, 50, flashAlpha))
            nvgFill(vg)
        end
    end

    if (base.shield or 0) > 0 then
        local shieldCenterY = by - bh * 0.35
        local layers = math.max(1, math.min(5, math.floor(base.shield or 0)))
        local shieldRadius = 62 + math.sin(GetTime():GetElapsedTime() * 4.0) * 3
        nvgBeginPath(vg)
        nvgCircle(vg, bx, shieldCenterY, shieldRadius)
        local shieldFill = nvgRadialGradient(vg, bx, shieldCenterY, shieldRadius * 0.45, shieldRadius,
            nvgRGBA(80, 190, 255, 16 + layers * 5),
            nvgRGBA(80, 145, 255, 2))
        nvgFillPaint(vg, shieldFill)
        nvgFill(vg)
        nvgStrokeWidth(vg, 2 + layers * 0.45)
        nvgStrokeColor(vg, nvgRGBA(150, 225, 255, 150 + layers * 20))
        nvgStroke(vg)
        for i = 1, layers do
            local angle = GetTime():GetElapsedTime() * 0.7 + (i - 1) * math.pi * 2 / layers
            local runeX = bx + math.cos(angle) * shieldRadius * 0.82
            local runeY = shieldCenterY + math.sin(angle) * shieldRadius * 0.82
            nvgSave(vg)
            nvgTranslate(vg, runeX, runeY)
            nvgRotate(vg, angle + math.pi * 0.25)
            nvgBeginPath(vg)
            nvgRect(vg, -4, -4, 8, 8)
            nvgFillColor(vg, nvgRGBA(220, 250, 255, 220))
            nvgFill(vg)
            nvgRestore(vg)
        end
    end

    local hpRatio = math.max(0, base.hp / base.maxHp)
    local barW, barH = 80, 12
    local barX, barY = bx - barW/2, by + bh/2 + 6
    nvgBeginPath(vg)
    nvgRect(vg, barX, barY, barW, barH)
    nvgFillColor(vg, nvgRGBA(40, 40, 40, 200))
    nvgFill(vg)
    local hpC = hpRatio > 0.5 and nvgRGBA(80,220,80,255) or (hpRatio > 0.25 and nvgRGBA(220,180,50,255) or nvgRGBA(220,50,50,255))
    nvgBeginPath(vg)
    nvgRect(vg, barX, barY, barW * hpRatio, barH)
    nvgFillColor(vg, hpC)
    nvgFill(vg)

    local hpText = math.floor(math.max(0, base.hp)) .. "/" .. math.floor(math.max(0, base.maxHp))
    nvgFontFace(vg, "sans")
    nvgFontSize(vg, 8)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 230))
    for _, offset in ipairs({ { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 } }) do
        nvgText(vg, bx + offset[1], barY + barH * 0.5 + offset[2], hpText, nil)
    end
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
    nvgText(vg, bx, barY + barH * 0.5, hpText, nil)
end

function DrawMonsters(vg)
    local time = GetTime():GetElapsedTime()
    local lightweightTwentyBattle =
        IsTwentyBattleTurboMode
        and IsTwentyBattleTurboMode()
    for _, m in ipairs(monsters) do
        local r = m.radius or CONFIG.MonsterRadius
        local isBoss = m.isBoss or m.type == "boss"
        local isDummy = m.isTrainingDummy == true
        local isElite = m.type == "elite"
        local isBlood = m.type == "blood"
        local isRanged = m.type == "ranged"
        local isTreasure = m.type == "treasure" or m.type == "skill_treasure"
        local isSkillTreasure = m.type == "skill_treasure"
        local highVisualLoad = IsBattleHighVisualLoad
            and IsBattleHighVisualLoad()
        local detailedVisual =
            not lightweightTwentyBattle
            and not highVisualLoad
            or isBoss
            or isTreasure
        local isFrozen = (m.freezeTimer or 0) > 0
        local isHit = (m.hitFlash or 0) > 0
        local bossBuff = m.bossBuff
        local bossBuffColor = bossBuff and bossBuff.color or nil
        local bossShieldActive = bossBuff ~= nil and IsBossShieldActive(m)
        local spawnDuration = math.max(0.001, m.spawnVisualDuration or 0.36)
        local spawnProgress = 1 - math.max(0, m.spawnVisualTimer or 0) / spawnDuration
        spawnProgress = math.max(0, math.min(1, spawnProgress))
        local spawnScale = 0.35 + spawnProgress * 0.65
        local visualScale = (isBoss and 1.18 or (isElite and 1.08 or (isTreasure and 1.06 or 1.0))) * spawnScale
        local drawR = r * visualScale
        local drawSize = drawR * 2
        local drawX = m.x - drawR
        local drawY = m.y - drawR
        local pulse = detailedVisual
            and (0.5 + 0.5 * math.sin(time * 5.0 + m.x * 0.03 + m.y * 0.02))
            or 0.5

        if isBoss then
            local auraColor = bossBuffColor or {170, 70, 255}
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y, drawR + 32 + pulse * 8)
            local aura = nvgRadialGradient(vg, m.x, m.y, drawR * 0.35, drawR + 42,
                nvgRGBA(auraColor[1], auraColor[2], auraColor[3], 76),
                nvgRGBA(math.floor(auraColor[1] * 0.56), math.floor(auraColor[2] * 0.38), math.floor(auraColor[3] * 0.56), 0))
            nvgFillPaint(vg, aura)
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y, drawR + 10 + pulse * 4)
            nvgStrokeColor(vg, nvgRGBA(auraColor[1], auraColor[2], auraColor[3], 120))
            nvgStrokeWidth(vg, 2)
            nvgStroke(vg)
            if bossShieldActive then
                nvgBeginPath(vg)
                nvgCircle(vg, m.x, m.y, drawR + 18 + pulse * 5)
                nvgStrokeColor(vg, nvgRGBA(150, 230, 255, 210))
                nvgStrokeWidth(vg, 4)
                nvgStroke(vg)
            end
        elseif detailedVisual and isBlood then
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y, drawR + 9 + pulse * 6)
            nvgStrokeColor(vg, nvgRGBA(255, 68, 74, 90 + math.floor(pulse * 70)))
            nvgStrokeWidth(vg, 2)
            nvgStroke(vg)
        elseif isTreasure then
            if not highVisualLoad then
                nvgBeginPath(vg)
                nvgCircle(vg, m.x, m.y, drawR + 14 + pulse * 8)
                local auraColor = isSkillTreasure and {100, 190, 255} or {255, 212, 82}
                local fadeColor = isSkillTreasure and {45, 90, 255} or {255, 150, 30}
                local treasureAura = nvgRadialGradient(vg, m.x, m.y, drawR * 0.25, drawR + 24,
                    nvgRGBA(auraColor[1], auraColor[2], auraColor[3], 92),
                    nvgRGBA(fadeColor[1], fadeColor[2], fadeColor[3], 0))
                nvgFillPaint(vg, treasureAura)
                nvgFill(vg)
                nvgBeginPath(vg)
                nvgCircle(vg, m.x, m.y, drawR + 7 + pulse * 3)
                nvgStrokeColor(vg, nvgRGBA(auraColor[1], auraColor[2], auraColor[3], 140 + math.floor(pulse * 70)))
                nvgStrokeWidth(vg, 2)
                nvgStroke(vg)
            end
        end

        if detailedVisual and isElite then
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y, drawR + 8)
            nvgStrokeColor(vg, nvgRGBA(255, 180, 60, 128 + math.floor(pulse * 70)))
            nvgStrokeWidth(vg, 2)
            nvgStroke(vg)

            if (m.chargeDuration or 0) > 0 then
                local dx = m.x - base.x
                local dy = m.y - base.y
                local len = math.sqrt(dx * dx + dy * dy)
                if len <= 0 then
                    dx, dy, len = 0, -1, 1
                end
                dx, dy = dx / len, dy / len
                for i = 1, 3 do
                    local trailR = drawR + 3 - i * 2
                    local alpha = 96 - i * 22
                    nvgBeginPath(vg)
                    nvgCircle(vg, m.x + dx * (i * 12), m.y + dy * (i * 12), math.max(3, trailR))
                    nvgFillColor(vg, nvgRGBA(255, 132, 34, alpha))
                    nvgFill(vg)
                end
            end
        end

        if detailedVisual and isRanged then
            local dx = base.x - m.x
            local dy = base.y - m.y
            local len = math.sqrt(dx * dx + dy * dy)
            local shootCooldown = math.max(
                0.001,
                CONFIG.RangedAttackCooldown
                    * (m.attackCooldownMultiplier or 1)
            )
            local charge = 1 - math.max(
                0,
                math.min(1, (m.shootTimer or shootCooldown) / shootCooldown)
            )
            if len > 0 then
                dx, dy = dx / len, dy / len
                nvgBeginPath(vg)
                nvgMoveTo(vg, m.x + dx * (drawR + 4), m.y + dy * (drawR + 4))
                nvgLineTo(vg, m.x + dx * (drawR + 24 + charge * 12), m.y + dy * (drawR + 24 + charge * 12))
                nvgStrokeColor(vg, nvgRGBA(120, 110, 255, 82 + math.floor(charge * 110)))
                nvgStrokeWidth(vg, 1 + charge * 2)
                nvgStroke(vg)
                if charge > 0.72 then
                    local targetPulse = (charge - 0.72) / 0.28
                    nvgBeginPath(vg)
                    nvgCircle(vg, base.x, base.y, 12 + targetPulse * 12)
                    nvgStrokeColor(vg, nvgRGBA(125, 185, 255, math.floor(80 + targetPulse * 110)))
                    nvgStrokeWidth(vg, 1 + targetPulse)
                    nvgStroke(vg)
                end
            end
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y, drawR + 5 + charge * 6)
            nvgStrokeColor(vg, nvgRGBA(120, 150, 255, 90 + math.floor(charge * 110)))
            nvgStrokeWidth(vg, 1 + charge)
            nvgStroke(vg)
        end

        if not isDummy
            and (m.imageHandle == nil or m.imageHandle <= 0)
            and assetLoadDone and m.imageCategory ~= nil then
            m.imageHandle = PickMonsterImage(m.imageCategory)
        end

        if isDummy then
            local wood = { 190, 132, 62 }
            local cloth = isBoss and { 116, 52, 146 } or { 145, 54, 44 }
            local postTop = m.y - drawR * 0.72
            local postBottom = m.y + drawR * 0.92
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y, drawR + 14 + pulse * 4)
            local dummyGlow = nvgRadialGradient(vg, m.x, m.y, drawR * 0.25, drawR + 20,
                nvgRGBA(isBoss and 190 or 232, isBoss and 88 or 172, isBoss and 240 or 78, 62),
                nvgRGBA(isBoss and 120 or 190, 60, isBoss and 170 or 40, 0))
            nvgFillPaint(vg, dummyGlow)
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgRect(vg, m.x - drawR * 0.12, postTop, drawR * 0.24, postBottom - postTop)
            nvgFillColor(vg, nvgRGBA(wood[1], wood[2], wood[3], 255))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgMoveTo(vg, m.x - drawR * 0.82, m.y - drawR * 0.20)
            nvgLineTo(vg, m.x + drawR * 0.82, m.y - drawR * 0.20)
            nvgStrokeColor(vg, nvgRGBA(wood[1], wood[2], wood[3], 255))
            nvgStrokeWidth(vg, math.max(5, drawR * 0.15))
            nvgStroke(vg)
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y - drawR * 0.52, drawR * 0.32)
            nvgFillColor(vg, nvgRGBA(218, 174, 92, 255))
            nvgFill(vg)
            nvgStrokeColor(vg, nvgRGBA(98, 62, 28, 240))
            nvgStrokeWidth(vg, 2)
            nvgStroke(vg)
            nvgBeginPath(vg)
            nvgCircle(vg, m.x - drawR * 0.10, m.y - drawR * 0.57, 2)
            nvgCircle(vg, m.x + drawR * 0.10, m.y - drawR * 0.57, 2)
            nvgFillColor(vg, nvgRGBA(38, 24, 20, 255))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgMoveTo(vg, m.x - drawR * 0.12, m.y - drawR * 0.43)
            nvgLineTo(vg, m.x, m.y - drawR * 0.38)
            nvgLineTo(vg, m.x + drawR * 0.12, m.y - drawR * 0.43)
            nvgStrokeColor(vg, nvgRGBA(84, 45, 28, 255))
            nvgStrokeWidth(vg, 1.5)
            nvgStroke(vg)
            nvgBeginPath(vg)
            nvgMoveTo(vg, m.x - drawR * 0.42, m.y - drawR * 0.20)
            nvgLineTo(vg, m.x - drawR * 0.28, m.y + drawR * 0.42)
            nvgLineTo(vg, m.x, m.y + drawR * 0.58)
            nvgLineTo(vg, m.x + drawR * 0.28, m.y + drawR * 0.42)
            nvgLineTo(vg, m.x + drawR * 0.42, m.y - drawR * 0.20)
            nvgClosePath(vg)
            nvgFillColor(vg, nvgRGBA(cloth[1], cloth[2], cloth[3], 245))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgMoveTo(vg, m.x - drawR * 0.34, postBottom)
            nvgLineTo(vg, m.x + drawR * 0.34, postBottom)
            nvgStrokeColor(vg, nvgRGBA(92, 56, 30, 255))
            nvgStrokeWidth(vg, math.max(5, drawR * 0.14))
            nvgStroke(vg)
            nvgFontFace(vg, "pixel")
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFontSize(vg, 12)
            nvgFillColor(vg, isBoss and nvgRGBA(226, 156, 255, 255) or nvgRGBA(255, 224, 126, 255))
            nvgText(vg, m.x, m.y - drawR - 18, isBoss and "无敌 · Boss木桩" or "无敌 · 普通木桩", nil)
        elseif isTreasure then
            local chestW = drawSize * 1.08
            local chestH = drawSize * 0.78
            local chestX = m.x - chestW * 0.5
            local chestY = m.y - chestH * 0.42
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, chestY + chestH + 3, chestW * 0.42)
            nvgFillColor(vg, nvgRGBA(0, 0, 0, 72))
            nvgFill(vg)
            local chestBodyColor = isSkillTreasure and {38, 78, 142} or {142, 76, 28}
            local chestLidColor = isSkillTreasure and {58, 132, 210} or {210, 122, 36}
            local chestTrimColor = isSkillTreasure and {135, 220, 255} or {255, 205, 72}
            nvgBeginPath(vg)
            nvgRoundedRect(vg, chestX, chestY + chestH * 0.28, chestW, chestH * 0.72, 4)
            nvgFillColor(vg, nvgRGBA(chestBodyColor[1], chestBodyColor[2], chestBodyColor[3], 255))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgRoundedRect(vg, chestX, chestY, chestW, chestH * 0.44, 5)
            nvgFillColor(vg, nvgRGBA(chestLidColor[1], chestLidColor[2], chestLidColor[3], 255))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgRect(vg, chestX, chestY + chestH * 0.42, chestW, 4)
            nvgRect(vg, chestX + chestW * 0.12, chestY + 2, 4, chestH - 4)
            nvgRect(vg, chestX + chestW * 0.80, chestY + 2, 4, chestH - 4)
            nvgFillColor(vg, nvgRGBA(chestTrimColor[1], chestTrimColor[2], chestTrimColor[3], 238))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgRoundedRect(vg, m.x - 6, chestY + chestH * 0.43, 12, 12, 3)
            nvgFillColor(vg, nvgRGBA(255, 224, 104, 255))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, chestY + chestH * 0.57, 2)
            nvgFillColor(vg, nvgRGBA(80, 48, 22, 245))
            nvgFill(vg)
            if not highVisualLoad then
                for coin = 1, 3 do
                    local a = time * 1.8 + coin * math.pi * 0.66 + m.x * 0.01
                    local cx = m.x + math.cos(a) * (drawR + 7)
                    local cy = m.y + math.sin(a) * (drawR * 0.52)
                    nvgBeginPath(vg)
                    nvgCircle(vg, cx, cy, 3)
                    nvgFillColor(vg, nvgRGBA(255, 218, 72, 190))
                    nvgFill(vg)
                end
            end

            local warningRemaining = math.max(0, m.treasureWarningTimer or 0)
            local escapeRemaining = math.max(0, m.treasureEscapeTimer
                or CONFIG.TreasureEscapeDuration or 10)
            local urgentColor = isSkillTreasure and {120, 210, 255} or {255, 218, 92}
            if escapeRemaining <= 2.5 then
                urgentColor = {255, 72, 52}
            elseif escapeRemaining <= 5 then
                urgentColor = {255, 144, 46}
            end
            local labelY = chestY - 19
            nvgFontFace(vg, "pixel")
            nvgFontSize(vg, 13)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(urgentColor[1], urgentColor[2], urgentColor[3], 255))
            local statusText = m.treasureDisplayText
                or (warningRemaining > 0
                    and (isSkillTreasure and "5本技能宝箱出现" or "5倍金币宝箱出现")
                    or (((m.treasureMiddlePauseTimer or 0) > 0)
                        and "停留 " .. string.format("%.1f", escapeRemaining) .. "秒"
                        or string.format("逃逸 %.1f秒", escapeRemaining)))
            nvgText(vg, m.x, labelY, statusText)

            local direction = m.treasureEscapeDirection or 1
            local arrowX = m.x + direction * (drawR + 22)
            local arrowY = m.y
            local arrowPulse = 4 + pulse * 4
            nvgBeginPath(vg)
            nvgMoveTo(vg, arrowX - direction * arrowPulse, arrowY - 8)
            nvgLineTo(vg, arrowX + direction * arrowPulse, arrowY)
            nvgLineTo(vg, arrowX - direction * arrowPulse, arrowY + 8)
            nvgStrokeColor(vg, nvgRGBA(urgentColor[1], urgentColor[2], urgentColor[3], 230))
            nvgStrokeWidth(vg, 3)
            nvgStroke(vg)
        elseif m.imageHandle and m.imageHandle > 0 then
            local imageSize = monsterImageSizes and monsterImageSizes[m.imageHandle] or nil
            local imageW = imageSize and imageSize.w or 1
            local imageH = imageSize and imageSize.h or 1
            local aspect = imageW > 0 and imageH > 0 and imageW / imageH or 1
            local imageDrawW = drawSize
            local imageDrawH = drawSize
            if aspect > 1 then
                imageDrawH = drawSize / aspect
            else
                imageDrawW = drawSize * aspect
            end
            local imageDrawX = m.x - imageDrawW * 0.5
            local imageDrawY = m.y - imageDrawH * 0.5
            local pat = nvgImagePattern(vg, imageDrawX, imageDrawY, imageDrawW, imageDrawH, 0, m.imageHandle, 1.0)
            nvgBeginPath(vg)
            nvgRect(vg, imageDrawX, imageDrawY, imageDrawW, imageDrawH)
            nvgFillPaint(vg, pat)
            nvgFill(vg)
        else
            local c = m.color
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y + drawR * 0.16, drawR * 0.86)
            nvgFillColor(vg, nvgRGBA(c[1], c[2], c[3], 230))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgCircle(vg, m.x - drawR * 0.28, m.y - drawR * 0.08, drawR * 0.12)
            nvgCircle(vg, m.x + drawR * 0.28, m.y - drawR * 0.08, drawR * 0.12)
            nvgFillColor(vg, nvgRGBA(20, 14, 18, 230))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y, drawR * 0.98)
            nvgStrokeColor(vg, nvgRGBA(math.min(255, c[1] + 36), math.min(255, c[2] + 36), math.min(255, c[3] + 36), 132))
            nvgStrokeWidth(vg, isElite and 2 or 1)
            nvgStroke(vg)
        end

        if detailedVisual and not isDummy and (isBoss or isElite or isBlood or isRanged) then
            local glowColor = isBoss and {210, 112, 255} or (isBlood and {255, 78, 72} or (isRanged and {118, 160, 255} or {255, 190, 78}))
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y, drawR + 5)
            local typeGlow = nvgRadialGradient(vg, m.x, m.y, drawR * 0.72, drawR + 8,
                nvgRGBA(glowColor[1], glowColor[2], glowColor[3], isBoss and 72 or 52),
                nvgRGBA(glowColor[1], glowColor[2], glowColor[3], 0))
            nvgFillPaint(vg, typeGlow)
            nvgFill(vg)
        end

        if isFrozen then
            local icePulse = 0.82 + 0.18 * math.sin(time * 7.0 + m.x * 0.02)
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y, drawR * 1.02)
            nvgFillColor(vg, nvgRGBA(90, 210, 255, 66 + math.floor(icePulse * 24)))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgMoveTo(vg, m.x - drawR * 0.58, m.y - drawR * 0.55)
            nvgLineTo(vg, m.x - drawR * 0.20, m.y - drawR * 0.10)
            nvgLineTo(vg, m.x - drawR * 0.42, m.y + drawR * 0.58)
            nvgMoveTo(vg, m.x + drawR * 0.56, m.y - drawR * 0.58)
            nvgLineTo(vg, m.x + drawR * 0.18, m.y - drawR * 0.02)
            nvgLineTo(vg, m.x + drawR * 0.56, m.y + drawR * 0.56)
            nvgStrokeColor(vg, nvgRGBA(170, 238, 255, 180))
            nvgStrokeWidth(vg, 1)
            nvgStroke(vg)
            for shardIndex = 1, 4 do
                local shardAngle = time * 0.35 + shardIndex * math.pi * 0.5
                local shardDistance = drawR * (0.82 + (shardIndex % 2) * 0.18)
                local shardX = m.x + math.cos(shardAngle) * shardDistance
                local shardY = m.y + math.sin(shardAngle) * shardDistance
                nvgSave(vg)
                nvgTranslate(vg, shardX, shardY)
                nvgRotate(vg, shardAngle)
                nvgBeginPath(vg)
                nvgMoveTo(vg, -2, 3)
                nvgLineTo(vg, 0, -5 - icePulse * 3)
                nvgLineTo(vg, 2, 3)
                nvgClosePath(vg)
                nvgFillColor(vg, nvgRGBA(195, 246, 255, 145 + math.floor(icePulse * 70)))
                nvgFill(vg)
                nvgRestore(vg)
            end
        end

        if detailedVisual and isHit then
            local hitAlpha = math.floor(math.min(1, (m.hitFlash or 0) / 0.15) * 170)
            nvgBeginPath(vg)
            nvgCircle(vg, m.x, m.y, drawR + 5)
            nvgStrokeColor(vg, nvgRGBA(255, 76, 54, hitAlpha))
            nvgStrokeWidth(vg, 2)
            nvgStroke(vg)
            nvgBeginPath(vg)
            nvgMoveTo(vg, m.x - drawR * 0.55, m.y - drawR * 0.35)
            nvgLineTo(vg, m.x - drawR * 0.10, m.y - drawR * 0.05)
            nvgLineTo(vg, m.x - drawR * 0.34, m.y + drawR * 0.38)
            nvgMoveTo(vg, m.x + drawR * 0.48, m.y - drawR * 0.42)
            nvgLineTo(vg, m.x + drawR * 0.04, m.y + drawR * 0.02)
            nvgLineTo(vg, m.x + drawR * 0.38, m.y + drawR * 0.50)
            nvgStrokeColor(vg, nvgRGBA(255, 56, 44, hitAlpha))
            nvgStrokeWidth(vg, 1)
            nvgStroke(vg)
        end

        if not isDummy
            and (not lightweightTwentyBattle or isBoss or isElite or isTreasure)
            and ((m.hp or 0) < (m.maxHp or 1) or isElite or isBoss) then
            local hpR = math.max(0, math.min(1, (m.hp or 0) / math.max(1, m.maxHp or 1)))
            local barW = isBoss and math.max(72, drawSize * 1.35) or drawSize
            local barH = isBoss and 7 or (isElite and 5 or 4)
            local barX = m.x - barW * 0.5
            local barY = drawY - (isBoss and 16 or 9)
            nvgBeginPath(vg)
            nvgRect(vg, barX - 1, barY - 1, barW + 2, barH + 2)
            nvgFillColor(vg, nvgRGBA(12, 8, 12, 210))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgRect(vg, barX, barY, barW, barH)
            nvgFillColor(vg, nvgRGBA(42, 24, 28, 230))
            nvgFill(vg)
            local hpColor = isBoss and nvgRGBA(210, 60, 130, 255) or (isElite and nvgRGBA(255, 115, 54, 255) or nvgRGBA(220, 50, 50, 255))
            nvgBeginPath(vg)
            nvgRect(vg, barX, barY, barW * hpR, barH)
            nvgFillColor(vg, hpColor)
            nvgFill(vg)
            if bossBuff ~= nil then
                local labelColor = bossBuffColor or {210, 112, 255}
                nvgFontFace(vg, "pixel")
                nvgFontSize(vg, 13)
                nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
                nvgFillColor(vg, nvgRGBA(labelColor[1], labelColor[2], labelColor[3], 245))
                nvgText(vg, m.x, barY - 10, bossShieldActive and "无敌" or (bossBuff.label or "强化"))
            end
        end
    end
end

function DrawMonsterProjectiles(vg)
    local lightweight = IsBattleHighVisualLoad
        and IsBattleHighVisualLoad()
    for index, p in ipairs(monsterProjectiles) do
        local radius = p.radius or 5
        local speed = math.sqrt((p.vx or 0) * (p.vx or 0) + (p.vy or 0) * (p.vy or 0))
        local tx, ty = 0, -1
        if speed > 0 then
            tx = -(p.vx or 0) / speed
            ty = -(p.vy or 0) / speed
        end
        local tailLen = math.max(18, radius * 5)

        if not lightweight or index % 2 == (fastMultiRenderFrame or 0) % 2 then
            nvgBeginPath(vg)
            nvgMoveTo(vg, p.x + tx * tailLen, p.y + ty * tailLen)
            nvgLineTo(vg, p.x, p.y)
            nvgStrokeColor(vg, nvgRGBA(80, 126, 255, 84))
            nvgStrokeWidth(vg, radius * 1.5)
            nvgStroke(vg)

            nvgBeginPath(vg)
            nvgMoveTo(vg, p.x + tx * tailLen * 0.72, p.y + ty * tailLen * 0.72)
            nvgLineTo(vg, p.x, p.y)
            nvgStrokeColor(vg, nvgRGBA(165, 238, 255, 168))
            nvgStrokeWidth(vg, math.max(2, radius * 0.55))
            nvgStroke(vg)
        end

        nvgBeginPath(vg)
        nvgCircle(vg, p.x, p.y, radius)
        nvgFillColor(vg, nvgRGBA(92, 210, 255, 245))
        nvgFill(vg)
        if not lightweight or index % 2 == (fastMultiRenderFrame or 0) % 2 then
            nvgBeginPath(vg)
            nvgCircle(vg, p.x, p.y, radius + 9)
            local aura = nvgRadialGradient(vg, p.x, p.y, 1, radius + 10,
                nvgRGBA(130, 230, 255, 146),
                nvgRGBA(80, 80, 255, 0))
            nvgFillPaint(vg, aura)
            nvgFill(vg)

            nvgBeginPath(vg)
            nvgCircle(vg, p.x - tx * radius * 0.28, p.y - ty * radius * 0.28, math.max(2, radius * 0.45))
            nvgFillColor(vg, nvgRGBA(240, 255, 255, 238))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgCircle(vg, p.x, p.y, radius + 4)
            nvgStrokeColor(vg, nvgRGBA(130, 230, 255, 160))
            nvgStrokeWidth(vg, 1)
            nvgStroke(vg)
        end
    end
end

local HERO_WING_SMALL_THRESHOLD = 10
local HERO_WING_UPGRADE_THRESHOLD = 15
local HERO_WING_VISUAL_SCALE = 1.5
local HERO_WING_FEATHERS = {
    { rootX = 0.18, rootY = -0.56, tipX = 2.30, tipY = -1.20, innerX = 0.98, innerY = -0.42 },
    { rootX = 0.18, rootY = -0.28, tipX = 2.42, tipY = -0.56, innerX = 1.12, innerY = -0.10 },
    { rootX = 0.20, rootY = 0.00, tipX = 2.22, tipY = 0.10, innerX = 1.04, innerY = 0.24 },
    { rootX = 0.18, rootY = 0.28, tipX = 1.82, tipY = 0.62, innerX = 0.82, innerY = 0.46 },
}

local function GetUpgradeWingScale()
    if GetActiveEquipment == nil then return 0 end
    local equipment = GetActiveEquipment()
    if equipment == nil then return 0 end
    local weapon = equipment.weapon
    local armor = equipment.armor
    local boots = equipment.boots
    local gloves = equipment.gloves
    local ring = equipment.ring
    if weapon == nil or armor == nil or boots == nil or gloves == nil or ring == nil then
        return 0
    end

    local weaponLevel = math.max(0, math.floor(weapon.weaponUpgradeLevel or 0))
    local armorLevel = math.max(0, math.floor(armor.armorUpgradeLevel or 0))
    local bootsLevel = math.max(0, math.floor(boots.bootsUpgradeLevel or 0))
    local glovesLevel = math.max(0, math.floor(gloves.glovesUpgradeLevel or 0))
    local ringLevel = math.max(0, math.floor(ring.ringUpgradeLevel or 0))
    if weaponLevel >= HERO_WING_UPGRADE_THRESHOLD
        and armorLevel >= HERO_WING_UPGRADE_THRESHOLD
        and bootsLevel >= HERO_WING_UPGRADE_THRESHOLD
        and glovesLevel >= HERO_WING_UPGRADE_THRESHOLD
        and ringLevel >= HERO_WING_UPGRADE_THRESHOLD then
        return 1.0
    end
    if weaponLevel >= HERO_WING_SMALL_THRESHOLD
        and armorLevel >= HERO_WING_SMALL_THRESHOLD
        and bootsLevel >= HERO_WING_SMALL_THRESHOLD
        and glovesLevel >= HERO_WING_SMALL_THRESHOLD
        and ringLevel >= HERO_WING_SMALL_THRESHOLD then
        return 0.5
    end
    return 0
end

local function DrawHeroWingFeather(vg, hx, hy, r, side, data, index, pulse)
    local lift = (pulse - 0.5) * r * 0.10
    local rootX = hx + side * data.rootX * r
    local rootY = hy + data.rootY * r - lift
    local tipX = hx + side * (data.tipX + pulse * 0.05) * r
    local tipY = hy + data.tipY * r - lift * (1.0 + index * 0.18)
    local innerX = hx + side * data.innerX * r
    local innerY = hy + data.innerY * r - lift * 0.45
    local lowerRootX = hx + side * (data.rootX - 0.08) * r
    local lowerRootY = hy + (data.rootY + 0.22) * r - lift * 0.35
    local alpha = math.floor(74 + pulse * 36 - index * 4)

    nvgBeginPath(vg)
    nvgMoveTo(vg, rootX, rootY)
    nvgLineTo(vg, tipX, tipY)
    nvgLineTo(vg, innerX, innerY)
    nvgLineTo(vg, lowerRootX, lowerRootY)
    nvgClosePath(vg)
    local fill = nvgLinearGradient(vg, rootX, rootY, tipX, tipY,
        nvgRGBA(255, 214, 86, alpha),
        nvgRGBA(152, 70, 255, math.floor(alpha * 0.72)))
    nvgFillPaint(vg, fill)
    nvgFill(vg)

    nvgBeginPath(vg)
    nvgMoveTo(vg, rootX, rootY)
    nvgLineTo(vg, tipX, tipY)
    nvgStrokeColor(vg, nvgRGBA(255, 232, 118, math.floor(alpha * 0.82)))
    nvgStrokeWidth(vg, math.max(1.2, r * 0.055))
    nvgStroke(vg)
end

local function DrawFallbackHeroWings(vg, hx, hy, r, pulse)
    nvgBeginPath(vg)
    nvgCircle(vg, hx, hy - r * 0.05, r * (2.55 + pulse * 0.12))
    local coreGlow = nvgRadialGradient(vg, hx, hy - r * 0.05, r * 0.35, r * 2.65,
        nvgRGBA(245, 196, 92, math.floor(32 + pulse * 18)),
        nvgRGBA(130, 42, 255, 0))
    nvgFillPaint(vg, coreGlow)
    nvgFill(vg)

    for side = -1, 1, 2 do
        local glowX = hx + side * r * 1.22
        local glowY = hy - r * 0.18
        nvgBeginPath(vg)
        nvgCircle(vg, glowX, glowY, r * (1.75 + pulse * 0.10))
        local wingGlow = nvgRadialGradient(vg, glowX, glowY, r * 0.18, r * 1.85,
            nvgRGBA(255, 205, 88, math.floor(42 + pulse * 18)),
            nvgRGBA(126, 48, 255, 0))
        nvgFillPaint(vg, wingGlow)
        nvgFill(vg)

        for index, feather in ipairs(HERO_WING_FEATHERS) do
            DrawHeroWingFeather(vg, hx, hy, r, side, feather, index, pulse)
        end

        nvgBeginPath(vg)
        nvgMoveTo(vg, hx + side * r * 0.18, hy - r * 0.58)
        nvgLineTo(vg, hx + side * r * (2.15 + pulse * 0.06), hy - r * 1.04)
        nvgLineTo(vg, hx + side * r * 1.60, hy + r * 0.54)
        nvgStrokeColor(vg, nvgRGBA(188, 104, 255, math.floor(84 + pulse * 48)))
        nvgStrokeWidth(vg, math.max(1.4, r * 0.06))
        nvgStroke(vg)
    end
end

local function DrawHeroWings(vg, hx, hy, r)
    local hasLeaderboardFirstWing = IsLeaderboardFirstWingEligible ~= nil
        and IsLeaderboardFirstWingEligible()
        and leaderboardFirstWingImage ~= nil
        and leaderboardFirstWingImage > 0
    local wingScale = hasLeaderboardFirstWing and 1.0 or GetUpgradeWingScale()
    if wingScale <= 0 then return end
    local elapsed = GetTime():GetElapsedTime()
    local pulse = 0.5 + 0.5 * math.sin(elapsed * 4.8)
    local wingRadius = r * wingScale * HERO_WING_VISUAL_SCALE

    local wingImage = hasLeaderboardFirstWing
        and leaderboardFirstWingImage
        or (wingScale >= 1.0 and heroWingImage or heroWingSmallImage)
    nvgSave(vg)
    if wingImage and wingImage > 0 then
        local wingSize = wingRadius * (5.36 + pulse * 0.04)
        local drawX = hx - wingSize * 0.5
        local drawY = hy - wingSize * 0.58
        local glowRadius = wingSize * (0.47 + pulse * 0.02)
        nvgBeginPath(vg)
        nvgCircle(vg, hx, hy - wingRadius * 0.35, glowRadius)
        local aura = nil
        if hasLeaderboardFirstWing then
            aura = nvgRadialGradient(vg, hx, hy - wingRadius * 0.35, wingRadius * 0.45, glowRadius,
                nvgRGBA(255, 238, 158, math.floor(54 + pulse * 22)),
                nvgRGBA(118, 190, 255, 0))
        else
            aura = nvgRadialGradient(vg, hx, hy - wingRadius * 0.35, wingRadius * 0.45, glowRadius,
                nvgRGBA(136, 52, 255, math.floor((42 + pulse * 20) * (0.72 + wingScale * 0.28))),
                nvgRGBA(65, 8, 92, 0))
        end
        nvgFillPaint(vg, aura)
        nvgFill(vg)

        local imageAlpha = hasLeaderboardFirstWing and 1.0 or (wingScale >= 1.0 and 0.96 or 0.90)
        local pat = nvgImagePattern(vg, drawX, drawY, wingSize, wingSize, 0, wingImage, imageAlpha)
        nvgBeginPath(vg)
        nvgRect(vg, drawX, drawY, wingSize, wingSize)
        nvgFillPaint(vg, pat)
        nvgFill(vg)
    else
        DrawFallbackHeroWings(vg, hx, hy, wingRadius, pulse)
    end
    nvgRestore(vg)
end

local function DrawEquippedTitle(vg, hx, titleBaseY)
    local codex = NormalizeAdventureData()
    local titleId = codex.selectedTitleId or ""
    if titleId == "" then return end
    local titleDef = ADVENTURE_TITLE_DEFS and ADVENTURE_TITLE_DEFS[titleId]
    local styleDef = ADVENTURE_TITLE_STYLE_DEFS and ADVENTURE_TITLE_STYLE_DEFS[codex.selectedTitleStyleId or "royal_gold"]
    if titleDef == nil or styleDef == nil then return end

    local time = GetTime():GetElapsedTime()
    local pulse = 0.5 + 0.5 * math.sin(time * 4.0)
    local accent = styleDef.color or { 255, 220, 120, 255 }
    local titleW = math.min(150, math.max(92, 36 + #titleDef.name * 7))
    local titleH = 23
    local titleX = hx - titleW * 0.5
    local titleY = titleBaseY - titleH - 5
    local iconHandle = titleEmblemImages and titleEmblemImages[titleId]
    local styleHandle = titleStyleImages and titleStyleImages[codex.selectedTitleStyleId]
    local innerBgHandle = titleInnerBgImages and titleInnerBgImages[codex.selectedTitleInnerBgId]
    local innerBgDef = ADVENTURE_TITLE_INNER_BG_DEFS and ADVENTURE_TITLE_INNER_BG_DEFS[codex.selectedTitleInnerBgId]

    nvgSave(vg)
    if styleHandle and styleHandle > 0 then
        local frameX = titleX - 25
        local frameY = titleY - 10
        local frameW = titleW + 50
        local frameH = titleH + 20
        local pat = nvgImagePattern(vg, frameX, frameY, frameW, frameH, 0, styleHandle, 0.98)
        nvgBeginPath(vg)
        nvgRect(vg, frameX, frameY, frameW, frameH)
        nvgFillPaint(vg, pat)
        nvgFill(vg)
    else
        nvgBeginPath(vg)
        nvgRect(vg, titleX, titleY, titleW, titleH)
        nvgFillColor(vg, nvgRGBA(12, 24, 42, 220))
        nvgFill(vg)
    end

    nvgBeginPath(vg)
    nvgRect(vg, titleX + 8, titleY + 5, titleW - 16, titleH - 10)
    if innerBgHandle and innerBgHandle > 0 then
        local innerPat = nvgImagePattern(vg, titleX + 8, titleY + 5, titleW - 16, titleH - 10, 0, innerBgHandle, 0.92)
        nvgFillPaint(vg, innerPat)
    else
        nvgFillColor(vg, nvgRGBA(accent[1], accent[2], accent[3], math.floor(28 + pulse * 18)))
    end
    nvgFill(vg)

    local innerAccent = innerBgDef and innerBgDef.color or accent
    nvgBeginPath(vg)
    nvgRect(vg, titleX + 8, titleY + 5, titleW - 16, titleH - 10)
    if innerBgHandle and innerBgHandle > 0 then
        local innerPat = nvgImagePattern(vg, titleX + 8, titleY + 5, titleW - 16, titleH - 10, 0, innerBgHandle, 0.96)
        nvgFillPaint(vg, innerPat)
    else
        nvgFillColor(vg, nvgRGBA(innerAccent[1], innerAccent[2], innerAccent[3], 115))
    end
    nvgFill(vg)
    nvgBeginPath(vg)
    nvgRect(vg, titleX + 11, titleY + 7, titleW - 22, titleH - 14)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, math.floor(10 + pulse * 18)))
    nvgFill(vg)

    nvgBeginPath(vg)
    nvgRect(vg, titleX + 5, titleY + 3, titleW - 10, titleH - 6)
    nvgFillColor(vg, nvgRGBA(12, 20, 35, 92))
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(accent[1], accent[2], accent[3], 215 + math.floor(pulse * 35)))
    nvgStrokeWidth(vg, 1.3)
    nvgStroke(vg)
    nvgBeginPath(vg)
    nvgCircle(vg, titleX - 10, titleY + titleH * 0.5, 2 + pulse * 1.5)
    nvgCircle(vg, titleX + titleW + 10, titleY + titleH * 0.5, 2 + pulse * 1.5)
    nvgFillColor(vg, nvgRGBA(accent[1], accent[2], accent[3], math.floor(90 + pulse * 100)))
    nvgFill(vg)

    nvgBeginPath(vg)
    nvgRect(vg, titleX + 7, titleY + titleH - 4, titleW - 14, 2)
    nvgFillColor(vg, nvgRGBA(accent[1], accent[2], accent[3], 220))
    nvgFill(vg)

    if iconHandle and iconHandle > 0 then
        local iconSize = 28
        local iconX = titleX + 3
        local iconY = titleY - 3
        local iconGlow = nvgRadialGradient(vg, iconX + iconSize * 0.5, iconY + iconSize * 0.5, 2, iconSize * 0.75,
            nvgRGBA(accent[1], accent[2], accent[3], math.floor(95 + pulse * 45)),
            nvgRGBA(accent[1], accent[2], accent[3], 0))
        nvgBeginPath(vg)
        nvgCircle(vg, iconX + iconSize * 0.5, iconY + iconSize * 0.5, iconSize * 0.72)
        nvgFillPaint(vg, iconGlow)
        nvgFill(vg)
        local iconPat = nvgImagePattern(vg, iconX, iconY, iconSize, iconSize, 0, iconHandle, 1.0)
        nvgBeginPath(vg)
        nvgRect(vg, iconX, iconY, iconSize, iconSize)
        nvgFillPaint(vg, iconPat)
        nvgFill(vg)
    end

    nvgFontFace(vg, "pixel")
    nvgFontSize(vg, 10)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(accent[1], accent[2], accent[3], math.floor(105 + pulse * 80)))
    nvgText(vg, hx + 8, titleY + titleH * 0.5, titleDef.name, nil)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 245))
    nvgText(vg, hx + 9, titleY + titleH * 0.5 + 1, titleDef.name, nil)
    nvgFillColor(vg, nvgRGBA(255, 244, 190, 255))
    nvgText(vg, hx + 8, titleY + titleH * 0.5, titleDef.name, nil)
    nvgFontSize(vg, 7)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, math.floor(80 + pulse * 90)))
    nvgText(vg, hx + 8 - titleW * 0.34, titleY + titleH - 5 + math.sin(time * 3.5) * 1.5, "✦", nil)
    nvgText(vg, hx + 8 + titleW * 0.34, titleY + 5 + math.sin(time * 3.5) * 1.5, "✦", nil)
    nvgRestore(vg)
end

function DrawHero(vg)
    local hx, hy = hero.x, hero.y
    local r = CONFIG.HeroRadius
    DrawHeroWings(vg, hx, hy, r)
    local drawW = 48
    local drawH = 64
    local drawX = hx - drawW * 0.5
    local drawY = hy + r - drawH
    if heroImage and heroImage > 0 then
        local pat = nvgImagePattern(vg, drawX, drawY, drawW, drawH, 0, heroImage, 1.0)
        nvgBeginPath(vg)
        nvgRect(vg, drawX, drawY, drawW, drawH)
        nvgFillPaint(vg, pat)
        nvgFill(vg)
    else
        nvgBeginPath(vg)
        nvgRect(vg, hx - r, hy - r, r*2, r*2)
        nvgFillColor(vg, nvgRGBA(60, 120, 220, 255))
        nvgFill(vg)
        nvgBeginPath(vg)
        nvgRect(vg, hx - r, hy - r, r*2, r*2)
        nvgStrokeColor(vg, nvgRGBA(100, 180, 255, 200))
        nvgStrokeWidth(vg, 2)
        nvgStroke(vg)
        nvgBeginPath(vg)
        nvgRect(vg, hx - 8, hy - 6, 4, 4)
        nvgRect(vg, hx + 4, hy - 6, 4, 4)
        nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
        nvgFill(vg)
    end
    DrawEquippedTitle(vg, hx, drawY)
    DrawSword(vg, hx, hy)
end

function DrawClones(vg)
    if #clones == 0 then return end
    local r = math.floor(CONFIG.HeroRadius * 0.5)
    local drawW = 24
    local drawH = 32
    for _, clone in ipairs(clones) do
        local cx, cy = clone.x, clone.y
        if heroImage and heroImage > 0 then
            local drawX = cx - drawW * 0.5
            local drawY = cy + r - drawH
            local pat = nvgImagePattern(vg, drawX, drawY, drawW, drawH, 0, heroImage, 0.65)
            nvgBeginPath(vg)
            nvgRect(vg, drawX, drawY, drawW, drawH)
            nvgFillPaint(vg, pat)
            nvgFill(vg)
        else
            nvgBeginPath(vg)
            nvgRect(vg, cx - r, cy - r, r*2, r*2)
            nvgFillColor(vg, nvgRGBA(60, 120, 220, 140))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgRect(vg, cx - r, cy - r, r*2, r*2)
            nvgStrokeColor(vg, nvgRGBA(100, 180, 255, 160))
            nvgStrokeWidth(vg, 1)
            nvgStroke(vg)
            nvgBeginPath(vg)
            nvgRect(vg, cx - 4, cy - 3, 3, 3)
            nvgRect(vg, cx + 2, cy - 3, 3, 3)
            nvgFillColor(vg, nvgRGBA(255, 255, 255, 200))
            nvgFill(vg)
        end
    end
end

local DEFAULT_WEAPON_POSE = { handleU = 0.80, handleV = 0.82, tipU = 0.18, tipV = 0.14 }
local WEAPON_VISUAL_POSES = {
    default = DEFAULT_WEAPON_POSE,
    blue = DEFAULT_WEAPON_POSE,
    purple = DEFAULT_WEAPON_POSE,
    orange = DEFAULT_WEAPON_POSE,
    red = DEFAULT_WEAPON_POSE,
    colorful = DEFAULT_WEAPON_POSE,
    long = DEFAULT_WEAPON_POSE,
    crystal = DEFAULT_WEAPON_POSE,
}

local DEFAULT_WEAPON_GLOW_PROFILE = { halfWidth = 0.16, edgeGap = 0.040, lineWidth = 0.050, imageHeight = 0.135, imageLength = 1.05 }
local WEAPON_GLOW_PROFILES = {
    default = DEFAULT_WEAPON_GLOW_PROFILE,
    blue = { halfWidth = 0.16, edgeGap = 0.040, lineWidth = 0.050, imageHeight = 0.135, imageLength = 1.05 },
    purple = { halfWidth = 0.14, edgeGap = 0.042, lineWidth = 0.047, imageHeight = 0.125, imageLength = 1.04 },
    orange = { halfWidth = 0.135, edgeGap = 0.045, lineWidth = 0.045, imageHeight = 0.120, imageLength = 1.04 },
    red = { halfWidth = 0.19, edgeGap = 0.038, lineWidth = 0.056, imageHeight = 0.150, imageLength = 1.06 },
    colorful = { halfWidth = 0.08, edgeGap = 0.055, lineWidth = 0.040, imageHeight = 0.105, imageLength = 1.03 },
    long = { halfWidth = 0.21, edgeGap = 0.035, lineWidth = 0.060, imageHeight = 0.160, imageLength = 1.07 },
    crystal = DEFAULT_WEAPON_GLOW_PROFILE,
}

local function GetWeaponGlowProfile(visualId)
    return WEAPON_GLOW_PROFILES[visualId or "default"] or DEFAULT_WEAPON_GLOW_PROFILE
end

local function GetWeaponGlowMetrics(visualId, length, pulse)
    local profile = GetWeaponGlowProfile(visualId)
    local sideOffset = math.max(6, length * ((profile.halfWidth or 0.16) + (profile.edgeGap or 0.04)) + (pulse or 0) * length * 0.008)
    local lineWidth = math.max(3, length * (profile.lineWidth or 0.05))
    local imageHeight = math.max(10, length * (profile.imageHeight or 0.135))
    local imageLength = length * (profile.imageLength or 1.05)
    return sideOffset, lineWidth, imageHeight, imageLength
end

local function GetWeaponVisualPose(visualId)
    local pose = WEAPON_VISUAL_POSES[visualId] or DEFAULT_WEAPON_POSE
    local localAngle = math.atan(pose.tipV - pose.handleV, pose.tipU - pose.handleU)
    return pose, localAngle
end
local function GetWeaponImageSizeForRange(attackRadius, weaponPose)
    local du = (weaponPose.tipU or 1) - (weaponPose.handleU or 0)
    local dv = (weaponPose.tipV or 0) - (weaponPose.handleV or 0)
    local poseLength = math.sqrt(du * du + dv * dv)
    if poseLength <= 0.001 then
        return attackRadius
    end
    return attackRadius / poseLength
end

local function WeaponEffectAlpha(value)
    return math.max(0, math.min(255, math.floor(value or 0)))
end

local function DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startAlong, endAlong, sideOffset, side, width, color, alpha, waveAmp, phase, offsetScale, segments)
    local c = color or {255, 220, 90}
    local count = segments or 8
    nvgStrokeWidth(vg, math.max(1, width or 1))
    nvgStrokeColor(vg, nvgRGBA(c[1], c[2], c[3], WeaponEffectAlpha(alpha)))
    nvgBeginPath(vg)
    for i = 0, count do
        local p = i / count
        local wave = math.sin((phase or 0) + p * math.pi * 2.0) * (waveAmp or 0)
        local along = startAlong + (endAlong - startAlong) * p
        local offset = side * (sideOffset * (offsetScale or 1.0) + wave)
        local x = ux * along + nx * offset
        local y = uy * along + ny * offset
        if i == 0 then
            nvgMoveTo(vg, x, y)
        else
            nvgLineTo(vg, x, y)
        end
    end
    nvgStroke(vg)
end

local function DrawWeaponFlameTongue(vg, ux, uy, nx, ny, along, sideOffset, side, flameLen, flameHeight, phase, outerColor, innerColor, alpha)
    local flicker = 0.90 + 0.14 * math.sin(phase or 0)
    local lean = math.sin((phase or 0) * 0.73) * flameLen * 0.10
    local rootHalf = flameLen * 0.16
    local tipAlong = along + flameLen * (0.40 + 0.08 * math.sin((phase or 0) * 1.21))
    local tipOut = sideOffset + flameHeight * flicker
    local midAlong = along + flameLen * 0.18 + lean
    local midOut = sideOffset + flameHeight * 0.34
    local rootOut = sideOffset * 0.90
    local oc = outerColor or {180, 80, 255}
    local ic = innerColor or {255, 230, 120}

    local function px(a, o)
        return ux * a + nx * side * o
    end
    local function py(a, o)
        return uy * a + ny * side * o
    end

    nvgBeginPath(vg)
    nvgMoveTo(vg, px(along - rootHalf, rootOut), py(along - rootHalf, rootOut))
    nvgLineTo(vg, px(midAlong, midOut), py(midAlong, midOut))
    nvgLineTo(vg, px(tipAlong, tipOut), py(tipAlong, tipOut))
    nvgLineTo(vg, px(along + rootHalf, rootOut), py(along + rootHalf, rootOut))
    nvgClosePath(vg)
    nvgFillColor(vg, nvgRGBA(oc[1], oc[2], oc[3], WeaponEffectAlpha(alpha)))
    nvgFill(vg)

    nvgBeginPath(vg)
    nvgMoveTo(vg, px(along - rootHalf * 0.38, rootOut), py(along - rootHalf * 0.38, rootOut))
    nvgLineTo(vg, px(midAlong, sideOffset + flameHeight * 0.20), py(midAlong, sideOffset + flameHeight * 0.20))
    nvgLineTo(vg, px(tipAlong - flameLen * 0.10, sideOffset + flameHeight * 0.48 * flicker), py(tipAlong - flameLen * 0.10, sideOffset + flameHeight * 0.48 * flicker))
    nvgLineTo(vg, px(along + rootHalf * 0.36, rootOut), py(along + rootHalf * 0.36, rootOut))
    nvgClosePath(vg)
    nvgFillColor(vg, nvgRGBA(ic[1], ic[2], ic[3], WeaponEffectAlpha(alpha * 0.72)))
    nvgFill(vg)
end

local function DrawWeaponFireSparks(vg, ux, uy, nx, ny, startAlong, endAlong, sideOffset, count, time, alpha, strong)
    local span = endAlong - startAlong
    local speed = strong and 0.10 or 0.045
    for i = 1, count do
        local p = (i * 0.137 + time * speed) % 1
        local side = (i % 2 == 0) and 1 or -1
        local along = startAlong + span * p + math.sin(time * 1.7 + i) * 2
        local out = sideOffset * (0.92 + (i % 3) * 0.08) + math.sin(time * 2.3 + i * 0.9) * sideOffset * 0.10
        local x = ux * along + nx * side * out
        local y = uy * along + ny * side * out
        local size = (strong and 2.0 or 1.3) + (i % 2) * 0.6
        local c = strong and ((i % 3 == 0) and {255, 188, 72} or {185, 28, 38}) or ((i % 4 == 0) and {178, 82, 255} or {255, 220, 90})
        nvgBeginPath(vg)
        nvgRect(vg, x - size * 0.5, y - size * 0.5, size, size)
        nvgFillColor(vg, nvgRGBA(c[1], c[2], c[3], WeaponEffectAlpha(alpha * (0.44 + (i % 3) * 0.11))))
        nvgFill(vg)
    end
end

local function DrawWeaponRotatingFireBlade(vg, ux, uy, nx, ny, startAlong, endAlong, sideOffset, side, phase, alpha, width)
    local span = endAlong - startAlong
    for layer = 1, 2 do
        local isCore = layer == 2
        nvgStrokeWidth(vg, isCore and math.max(2, width * 0.35) or math.max(3, width * 0.72))
        if isCore then
            nvgStrokeColor(vg, nvgRGBA(255, 170, 70, WeaponEffectAlpha(alpha * 0.82)))
        else
            nvgStrokeColor(vg, nvgRGBA(72, 0, 24, WeaponEffectAlpha(alpha * 0.58)))
        end
        nvgBeginPath(vg)
        for i = 0, 12 do
            local p = i / 12
            local swirl = math.sin(phase + p * math.pi * 2.0)
            local along = startAlong + span * p + math.cos(phase * 0.55 + p * math.pi) * 3
            local out = sideOffset * (1.02 + layer * 0.04) + swirl * sideOffset * 0.22
            local x = ux * along + nx * side * out
            local y = uy * along + ny * side * out
            if i == 0 then
                nvgMoveTo(vg, x, y)
            else
                nvgLineTo(vg, x, y)
            end
        end
        nvgStroke(vg)
    end
end

local function DrawWeaponUpgradeGlow(vg, weapon, visualId, weaponLocalAngle, length)
    if weapon == nil then return end
    local level = math.max(0, math.floor(weapon.weaponUpgradeLevel or 0))
    if level < 5 then return end

    local time = GetTime():GetElapsedTime()
    local ux = math.cos(weaponLocalAngle)
    local uy = math.sin(weaponLocalAngle)
    local nx = -uy
    local ny = ux
    local startOffset = math.max(4, length * 0.045)
    local pulse = 0.5 + 0.5 * math.sin(time * (level >= 20 and 8.0 or 5.6))
    local sideOffset, lineWidth = GetWeaponGlowMetrics(visualId, length, pulse)
    local endAlong = length * (1.0 + (level >= 20 and pulse * 0.012 or pulse * 0.006))
    local waveAmp = sideOffset * (level >= 20 and 0.08 or (level >= 15 and 0.065 or (level >= 10 and 0.045 or 0.02)))
    local midPurple = {170, 82, 255}
    local gold = {255, 210, 72}
    local whiteGold = {255, 248, 185}
    local blackRed = {42, 0, 20}
    local emberRed = {215, 34, 42}
    local hotOrange = {255, 172, 62}

    if level >= 20 then
        for side = -1, 1, 2 do
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 2.6, blackRed, 132 + pulse * 48, waveAmp * 0.90, time * 3.2 + side, 1.04, 10)
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 1.55, emberRed, 142 + pulse * 50, waveAmp * 0.70, time * 4.0 + side * 1.7, 0.98, 10)
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 0.68, hotOrange, 162 + pulse * 46, waveAmp * 0.48, time * 4.8 + side * 2.1, 0.90, 10)
        end
        for i = 1, 11 do
            local p = 0.08 + (i - 1) / 10 * 0.84
            local along = startOffset + (endAlong - startOffset) * p
            for side = -1, 1, 2 do
                DrawWeaponFlameTongue(vg, ux, uy, nx, ny, along, sideOffset * (0.94 + (i % 2) * 0.04), side, length * 0.105, sideOffset * 0.42 + lineWidth * 0.95, time * 5.5 + i * 1.37 + side, blackRed, hotOrange, 98 + pulse * 52)
            end
        end
    elseif level >= 15 then
        for side = -1, 1, 2 do
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 2.35, midPurple, 82 + pulse * 38, waveAmp, time * 2.5 + side, 1.05, 9)
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 1.25, gold, 112 + pulse * 42, waveAmp * 0.68, time * 3.2 + side, 0.96, 9)
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 0.52, whiteGold, 138 + pulse * 42, waveAmp * 0.38, time * 4.0 + side, 0.88, 9)
        end
        for i = 1, 8 do
            local p = 0.11 + (i - 1) / 7 * 0.80
            local along = startOffset + (endAlong - startOffset) * p
            for side = -1, 1, 2 do
                DrawWeaponFlameTongue(vg, ux, uy, nx, ny, along, sideOffset * 0.96, side, length * 0.082, sideOffset * 0.32 + lineWidth * 0.72, time * 4.7 + i * 1.21 + side, midPurple, gold, 74 + pulse * 42)
            end
        end
    elseif level >= 10 then
        for side = -1, 1, 2 do
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 1.65, midPurple, 70 + pulse * 26, waveAmp, time * 2.2 + side, 1.00, 8)
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 0.72, gold, 108 + pulse * 30, waveAmp * 0.52, time * 3.0 + side, 0.90, 8)
        end
        for i = 1, 6 do
            local p = 0.14 + (i - 1) / 5 * 0.72
            local along = startOffset + (endAlong - startOffset) * p
            for side = -1, 1, 2 do
                DrawWeaponFlameTongue(vg, ux, uy, nx, ny, along, sideOffset * 0.94, side, length * 0.058, sideOffset * 0.22 + lineWidth * 0.45, time * 3.8 + i * 1.41 + side, midPurple, whiteGold, 50 + pulse * 30)
            end
        end
    else
        for side = -1, 1, 2 do
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 1.05, midPurple, 48 + pulse * 18, waveAmp, time * 1.8 + side, 0.96, 6)
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 0.42, gold, 78 + pulse * 22, waveAmp * 0.38, time * 2.3 + side, 0.88, 6)
        end
        for i = 1, 4 do
            local p = 0.20 + (i - 1) / 3 * 0.60
            local along = startOffset + (endAlong - startOffset) * p
            local side = (i % 2 == 0) and 1 or -1
            DrawWeaponFlameTongue(vg, ux, uy, nx, ny, along, sideOffset * 0.92, side, length * 0.040, sideOffset * 0.15 + lineWidth * 0.28, time * 3.2 + i, midPurple, gold, 38 + pulse * 22)
        end
    end
end

local function DrawWeaponGlowImage(vg, weapon, visualId, weaponLocalAngle, length)
    if weapon == nil then return end
    local level = math.max(0, math.floor(weapon.weaponUpgradeLevel or 0))
    if level < 5 then return end

    local time = GetTime():GetElapsedTime()
    local pulse = 0.5 + 0.5 * math.sin(time * (level >= 20 and 8.0 or 5.6))
    local sideOffset, lineWidth = GetWeaponGlowMetrics(visualId, length, pulse)
    local startOffset = math.max(4, length * 0.045)
    local endAlong = length * (1.0 + (level >= 20 and pulse * 0.012 or pulse * 0.006))
    local sparkCount = level >= 20 and 14 or (level >= 15 and 10 or (level >= 10 and 7 or 4))

    nvgSave(vg)
    nvgRotate(vg, weaponLocalAngle)
    local ux, uy, nx, ny = 1, 0, 0, 1

    if level >= 20 then
        for blade = 1, 2 do
            local side = blade == 1 and 1 or -1
            DrawWeaponRotatingFireBlade(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, time * 4.6 + blade * 2.1, 124 + pulse * 48, lineWidth * 1.00)
        end
        for side = -1, 1, 2 do
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 0.92, {255, 170, 70}, 150 + pulse * 42, sideOffset * 0.05, time * 5.0 + side, 0.84, 10)
        end
    elseif level >= 15 then
        for side = -1, 1, 2 do
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 0.82, {255, 238, 132}, 124 + pulse * 36, sideOffset * 0.045, time * 3.8 + side, 0.84, 9)
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 0.40, {180, 92, 255}, 92 + pulse * 30, sideOffset * 0.065, time * 4.4 + side, 0.98, 9)
        end
    elseif level >= 10 then
        for side = -1, 1, 2 do
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 0.55, {255, 226, 110}, 108 + pulse * 26, sideOffset * 0.04, time * 3.2 + side, 0.84, 8)
        end
    else
        for side = -1, 1, 2 do
            DrawWeaponEdgeWave(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, side, lineWidth * 0.34, {255, 226, 110}, 80 + pulse * 20, sideOffset * 0.025, time * 2.4 + side, 0.84, 6)
        end
    end

    DrawWeaponFireSparks(vg, ux, uy, nx, ny, startOffset, endAlong, sideOffset, sparkCount, time, level >= 20 and 148 or 104, level >= 20)
    nvgRestore(vg)
end

local function DrawWeaponFlameOverlay(vg, weapon, length)
    if weapon == nil then return false end
    local level = math.max(0, math.floor(weapon.weaponUpgradeLevel or 0))
    local tier = GetWeaponFlameTier(level)
    if tier == nil then return false end
    if weaponFlameImages == nil then return false end
    local flameImg = weaponFlameImages[tier] or 0
    if flameImg == nil or flameImg <= 0 then return false end
    local flamePose = GetWeaponFlamePose(tier)
    if flamePose == nil then return false end
    local flameScale = tier >= 20 and 1.16
        or (tier >= 15 and 1.08
        or (tier >= 10 and 1.00 or 0.92))
    local flameAlpha = tier >= 20 and 1.00
        or (tier >= 15 and 0.95
        or (tier >= 10 and 0.88 or 0.78))
    local imgSize = GetWeaponImageSizeForRange(length, flamePose) * flameScale
    local imgX = -imgSize * flamePose.handleU
    local imgY = -imgSize * flamePose.handleV
    local pat = nvgImagePattern(vg, imgX, imgY, imgSize, imgSize, 0, flameImg, flameAlpha)
    nvgBeginPath(vg)
    nvgRect(vg, imgX, imgY, imgSize, imgSize)
    nvgFillPaint(vg, pat)
    nvgFill(vg)
    return true
end

local function DrawWeaponFlameOverlaySparks(vg, weapon, visualId, weaponLocalAngle, length)
    if weapon == nil then return end
    local tier = GetWeaponFlameTier(weapon.weaponUpgradeLevel or 0)
    if tier == nil or tier < 15 then return end

    local time = GetTime():GetElapsedTime()
    local pulse = 0.5 + 0.5 * math.sin(time * (tier >= 20 and 8.0 or 5.6))
    local sideOffset = GetWeaponGlowMetrics(visualId, length, pulse)
    local startAlong = math.max(4, length * 0.08)
    local endAlong = length * (tier >= 20 and 1.08 or 1.03)
    local sparkCount = tier >= 20 and 16 or 9

    nvgSave(vg)
    nvgRotate(vg, weaponLocalAngle)
    DrawWeaponFireSparks(
        vg,
        1,
        0,
        0,
        1,
        startAlong,
        endAlong,
        sideOffset * (tier >= 20 and 1.12 or 1.04),
        sparkCount,
        time,
        tier >= 20 and 164 or 116,
        tier >= 20
    )
    nvgRestore(vg)
end

local function GetVisualAttackRadius()
    local radius = CONFIG.AttackRadius
    if GetHeroAttackRadius then
        radius = GetHeroAttackRadius()
    end
    return radius
end

local function GetSwordTargetAngle(hx, hy, attackRadius)
    local swordAngle = -math.pi * 0.75
    local closestDist = 9999
    local searchRadius = attackRadius * 1.5
    for _, m in ipairs(monsters) do
        local dx = m.x - hx
        local dy = m.y - hy
        local dist = math.sqrt(dx*dx + dy*dy)
        if dist < closestDist and dist <= searchRadius then
            closestDist = dist
            swordAngle = math.atan(dy, dx)
        end
    end
    return swordAngle
end

local function GetSwordPose(hx, hy, attackRadius)
    local swordAngle = GetSwordTargetAngle(hx, hy, attackRadius)
    local handSide = math.cos(swordAngle) >= 0 and 1 or -1
    local r = CONFIG.HeroRadius
    local handX = hx + handSide * r * 0.62
    local handY = hy + r * 0.18
    local swingOffset = 0
    if hero.isSwinging then
        swingOffset = math.max(-0.80, math.min(0.80, hero.swingAngle * 0.50))
    end
    return swordAngle, handX, handY, swingOffset
end

function DrawSword(vg, hx, hy)
    local attackRadius = GetVisualAttackRadius()
    local swordAngle, handX, handY, swingOffset = GetSwordPose(hx, hy, attackRadius)
    local bladeAngle = swordAngle + swingOffset

    local weaponVisualId = "default"
    local equippedWeapon = GetActiveEquipment().weapon
    if equippedWeapon ~= nil then
        weaponVisualId = GetWeaponVisualId(equippedWeapon)
    end
    local weaponImg = weaponImages[weaponVisualId] or weaponImages["default"]
    local weaponPose, weaponLocalAngle = GetWeaponVisualPose(weaponVisualId)

    nvgSave(vg)
    nvgTranslate(vg, handX, handY)
    nvgRotate(vg, bladeAngle - weaponLocalAngle)

    local sLen = attackRadius
    local usedFlameOverlay = DrawWeaponFlameOverlay(vg, equippedWeapon, sLen)
    if not usedFlameOverlay then
        DrawWeaponUpgradeGlow(vg, equippedWeapon, weaponVisualId, weaponLocalAngle, sLen)
    end
    if weaponImg and weaponImg > 0 then
        local imgSize = GetWeaponImageSizeForRange(sLen, weaponPose)
        local imgX = -imgSize * weaponPose.handleU
        local imgY = -imgSize * weaponPose.handleV
        local pat = nvgImagePattern(vg, imgX, imgY, imgSize, imgSize, 0, weaponImg, 1.0)
        nvgBeginPath(vg)
        nvgRect(vg, imgX, imgY, imgSize, imgSize)
        nvgFillPaint(vg, pat)
        nvgFill(vg)
        if usedFlameOverlay then
            DrawWeaponFlameOverlaySparks(
                vg,
                equippedWeapon,
                weaponVisualId,
                weaponLocalAngle,
                sLen
            )
        else
            DrawWeaponGlowImage(vg, equippedWeapon, weaponVisualId, weaponLocalAngle, sLen)
        end
    else
        local ux = math.cos(weaponLocalAngle)
        local uy = math.sin(weaponLocalAngle)
        local nx = -uy
        local ny = ux
        local tipX = ux * sLen
        local tipY = uy * sLen
        local bladeBaseX = ux * sLen * 0.78
        local bladeBaseY = uy * sLen * 0.78

        nvgStrokeWidth(vg, math.max(6, sLen * 0.11))
        nvgStrokeColor(vg, nvgRGBA(200, 220, 255, 255))
        nvgBeginPath(vg)
        nvgMoveTo(vg, 0, 0)
        nvgLineTo(vg, bladeBaseX, bladeBaseY)
        nvgStroke(vg)

        nvgBeginPath(vg)
        nvgMoveTo(vg, tipX, tipY)
        nvgLineTo(vg, bladeBaseX + nx * 7, bladeBaseY + ny * 7)
        nvgLineTo(vg, bladeBaseX - nx * 7, bladeBaseY - ny * 7)
        nvgClosePath(vg)
        nvgFillColor(vg, nvgRGBA(230, 240, 255, 255))
        nvgFill(vg)

        nvgStrokeWidth(vg, 5)
        nvgStrokeColor(vg, nvgRGBA(200, 170, 60, 255))
        nvgBeginPath(vg)
        nvgMoveTo(vg, nx * 10, ny * 10)
        nvgLineTo(vg, -nx * 10, -ny * 10)
        nvgStroke(vg)
    end

    nvgRestore(vg)
end

function DrawAttackRange(vg)
    if not hero.isSwinging then return end

    local radius = GetVisualAttackRadius()
    local swordAngle, handX, handY, swingOffset = GetSwordPose(hero.x, hero.y, radius)
    local bladeAngle = swordAngle + swingOffset
    local inner = math.max(8, radius * 0.10)
    local outer = radius * 0.98

    nvgStrokeWidth(vg, 4)
    nvgStrokeColor(vg, nvgRGBA(255, 255, 255, 220))
    nvgBeginPath(vg)
    nvgMoveTo(vg, handX + math.cos(bladeAngle) * inner * 0.65, handY + math.sin(bladeAngle) * inner * 0.65)
    nvgLineTo(vg, handX + math.cos(bladeAngle) * outer * 1.05, handY + math.sin(bladeAngle) * outer * 1.05)
    nvgStroke(vg)
end

local function SkillEffectAlpha(value)
    return math.max(0, math.min(255, math.floor(value or 0)))
end

local function DrawSkillGlow(vg, x, y, radius, color, alpha)
    if x == nil or y == nil then return end
    local c = color or {180, 80, 255}
    nvgBeginPath(vg)
    nvgCircle(vg, x, y, radius)
    local glow = nvgRadialGradient(vg, x, y, 2, radius,
        nvgRGBA(c[1], c[2], c[3], SkillEffectAlpha(alpha)),
        nvgRGBA(c[1], c[2], c[3], 0))
    nvgFillPaint(vg, glow)
    nvgFill(vg)
end

local function DrawCultivationRing(vg, x, y, radius, color, alpha, spin)
    local c = color or {180, 80, 255}
    local a = SkillEffectAlpha(alpha)
    nvgBeginPath(vg)
    nvgCircle(vg, x, y, radius)
    nvgStrokeWidth(vg, 2)
    nvgStrokeColor(vg, nvgRGBA(c[1], c[2], c[3], a))
    nvgStroke(vg)

    nvgBeginPath(vg)
    nvgCircle(vg, x, y, radius * 0.62)
    nvgStrokeWidth(vg, 1)
    nvgStrokeColor(vg, nvgRGBA(255, 225, 130, SkillEffectAlpha(a * 0.62)))
    nvgStroke(vg)

    for i = 1, 8 do
        local angle = (spin or 0) + i * math.pi * 0.25
        local sx = x + math.cos(angle) * radius * 0.82
        local sy = y + math.sin(angle) * radius * 0.82
        nvgSave(vg)
        nvgTranslate(vg, sx, sy)
        nvgRotate(vg, angle + math.pi * 0.25)
        nvgBeginPath(vg)
        nvgRect(vg, -3, -3, 6, 6)
        nvgFillColor(vg, nvgRGBA(255, 225, 150, SkillEffectAlpha(a * 0.78)))
        nvgFill(vg)
        nvgRestore(vg)
    end
end

local function DrawJaggedLine(vg, x1, y1, x2, y2, segments, jitter, phase)
    local dx = x2 - x1
    local dy = y2 - y1
    local len = math.sqrt(dx * dx + dy * dy)
    if len <= 0 then return end
    local nx = -dy / len
    local ny = dx / len
    nvgBeginPath(vg)
    for i = 0, segments do
        local p = i / segments
        local offset = 0
        if i > 0 and i < segments then
            offset = math.sin(i * 12.989 + (phase or 0) * 7.3) * jitter
        end
        local x = x1 + dx * p + nx * offset
        local y = y1 + dy * p + ny * offset
        if i == 0 then
            nvgMoveTo(vg, x, y)
        else
            nvgLineTo(vg, x, y)
        end
    end
end

local function SkillSmoothStep(value)
    local v = math.max(0, math.min(1, value or 0))
    return v * v * (3 - 2 * v)
end

local function DrawSkillBurst(vg, x, y, radius, color, alpha, count, spin)
    local c = color or {255, 235, 170}
    local rays = math.max(3, math.min(8, count or 6))
    local a = SkillEffectAlpha(alpha)
    for i = 1, rays do
        local angle = (spin or 0) + (i - 1) * math.pi * 2 / rays
        local inner = radius * (0.18 + (i % 2) * 0.08)
        local outer = radius * (0.72 + (i % 3) * 0.12)
        nvgBeginPath(vg)
        nvgMoveTo(vg, x + math.cos(angle) * inner, y + math.sin(angle) * inner)
        nvgLineTo(vg, x + math.cos(angle) * outer, y + math.sin(angle) * outer)
        nvgStrokeWidth(vg, i % 2 == 0 and 2 or 1)
        nvgStrokeColor(vg, nvgRGBA(c[1], c[2], c[3], a))
        nvgStroke(vg)
    end
end

local function DrawSkillCracks(vg, x, y, radius, color, alpha, count, phase)
    local c = color or {255, 205, 125}
    local branches = math.max(4, math.min(10, count or 8))
    for i = 1, branches do
        local angle = (phase or 0) + (i - 1) * math.pi * 2 / branches
        local bend = math.sin(i * 7.17) * 0.16
        local midRadius = radius * (0.42 + (i % 3) * 0.07)
        nvgBeginPath(vg)
        nvgMoveTo(vg, x + math.cos(angle) * radius * 0.12, y + math.sin(angle) * radius * 0.12)
        nvgLineTo(vg, x + math.cos(angle + bend) * midRadius, y + math.sin(angle + bend) * midRadius)
        nvgLineTo(vg, x + math.cos(angle - bend * 0.55) * radius, y + math.sin(angle - bend * 0.55) * radius)
        nvgStrokeWidth(vg, i % 3 == 0 and 2 or 1)
        nvgStrokeColor(vg, nvgRGBA(c[1], c[2], c[3], SkillEffectAlpha(alpha)))
        nvgStroke(vg)
    end
end

function ShouldDrawFastMultiVisual(index)
    if IsTwentyBattleTurboMode
        and IsTwentyBattleTurboMode() then
        return index % 4
            == (fastMultiRenderFrame or 0) % 4
    end
    if not (IsBattleHighVisualLoad and IsBattleHighVisualLoad()) then
        return true
    end
    return index % 2 == (fastMultiRenderFrame or 0) % 2
end

function ShouldAlwaysDrawSkillEffect(effect)
    if effect == nil then return false end
    local effectType = effect.type
    return effectType == "meteor_warning"
        or effectType == "gold_drop"
        or effectType == "drop"
        or effectType == "boss_death"
        or effectType == "shield_break"
        or effectType == "heal"
        or effectType == "shield"
end

function DrawSkillEffects(vg)
    local time = GetTime():GetElapsedTime()
    for index, e in ipairs(skillEffects) do
        if not e.suppressVisual and (
            ShouldAlwaysDrawSkillEffect(e)
            or ShouldDrawFastMultiVisual(index)
        ) then
        local maxLife = e.maxLife or 1
        local elapsed = math.max(0, maxLife - e.life)
        local visualDelay = e.visualDelay or 0
        local visualDuration = math.max(0.001, e.visualDuration or (maxLife - visualDelay))
        local visualElapsed = elapsed - visualDelay
        local age = math.max(0, math.min(1, visualElapsed / visualDuration))
        local t = 1 - age
        local alpha = visualElapsed >= 0 and SkillEffectAlpha(230 * t) or 0

        if e.type == "area_pulse" then
            local c = e.color or {120, 220, 255}
            local wave = SkillSmoothStep(age)
            local radius = (e.radius or 90) * (0.18 + wave * 0.82)
            local pulseAlpha = alpha * (1 - age * 0.34)
            DrawSkillGlow(vg, e.x, e.y, radius * 1.10, c, pulseAlpha * 0.16)
            for ring = 1, 2 do
                local rr = radius * (ring == 1 and 1 or 0.68)
                nvgBeginPath(vg)
                nvgCircle(vg, e.x, e.y, rr)
                nvgStrokeWidth(vg, ring == 1 and (3 - age) or 1)
                nvgStrokeColor(vg, nvgRGBA(c[1], c[2], c[3],
                    SkillEffectAlpha(pulseAlpha * (ring == 1 and 0.72 or 0.36))))
                nvgStroke(vg)
            end
            DrawSkillBurst(vg, e.x, e.y, radius * 0.92, c, pulseAlpha * 0.32, 4, age * 0.35)

        elseif e.type == "meteor_warning" then
            local radius = e.radius or 90
            local countdown = SkillSmoothStep(age)
            local pulse = 0.96 + math.sin(time * 18) * 0.04
            local warningAlpha = 115 + countdown * 120
            DrawSkillGlow(vg, e.x, e.y, radius * 1.10, {255, 95, 30}, 38 + countdown * 28)
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius * pulse)
            nvgStrokeWidth(vg, 2 + countdown * 2)
            nvgStrokeColor(vg, nvgRGBA(255, 95, 35, SkillEffectAlpha(warningAlpha)))
            nvgStroke(vg)
            for ring = 1, 2 do
                local rr = radius * (0.18 + countdown * (ring == 1 and 0.36 or 0.68))
                nvgBeginPath(vg)
                nvgCircle(vg, e.x, e.y, rr)
                nvgStrokeWidth(vg, ring == 1 and 2 or 1)
                nvgStrokeColor(vg, nvgRGBA(255, ring == 1 and 210 or 135, 55,
                    SkillEffectAlpha((80 + countdown * 90) * (ring == 1 and 1 or 0.72))))
                nvgStroke(vg)
            end
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius * (0.16 + countdown * 0.40))
            nvgFillColor(vg, nvgRGBA(255, 120, 35, SkillEffectAlpha(22 + countdown * 65)))
            nvgFill(vg)
            for i = 1, 8 do
                local angle = i * math.pi * 0.25 + time * 0.18
                local outer = radius
                local inner = radius * (0.78 - countdown * 0.20)
                nvgBeginPath(vg)
                nvgMoveTo(vg, e.x + math.cos(angle) * inner, e.y + math.sin(angle) * inner)
                nvgLineTo(vg, e.x + math.cos(angle) * outer, e.y + math.sin(angle) * outer)
                nvgStrokeWidth(vg, i % 2 == 0 and 2 or 1)
                nvgStrokeColor(vg, nvgRGBA(255, 180, 75, SkillEffectAlpha(100 + countdown * 90)))
                nvgStroke(vg)
            end
            local cross = radius * (0.20 + countdown * 0.16)
            nvgStrokeWidth(vg, 2)
            nvgStrokeColor(vg, nvgRGBA(255, 235, 160, SkillEffectAlpha(110 + countdown * 110)))
            nvgBeginPath(vg)
            nvgMoveTo(vg, e.x - cross, e.y)
            nvgLineTo(vg, e.x + cross, e.y)
            nvgMoveTo(vg, e.x, e.y - cross)
            nvgLineTo(vg, e.x, e.y + cross)
            nvgStroke(vg)

        elseif e.type == "skill_hit" then
            local c = e.color or {255, 220, 90}
            local r = (e.radius or 18) * (1.0 + age * 0.55)
            DrawSkillGlow(vg, e.x, e.y, r * 1.05, c, alpha * 0.36)
            for i = 1, 3 do
                local a = time * 1.7 + i * math.pi * 0.67
                nvgBeginPath(vg)
                nvgMoveTo(vg, e.x + math.cos(a) * r * 0.12, e.y + math.sin(a) * r * 0.12)
                nvgLineTo(vg, e.x + math.cos(a) * r * 0.58, e.y + math.sin(a) * r * 0.58)
                nvgStrokeWidth(vg, 1)
                nvgStrokeColor(vg, nvgRGBA(255, 245, 210, SkillEffectAlpha(alpha * 0.48)))
                nvgStroke(vg)
            end

        elseif e.type == "thunder" or e.type == "chain" then
            local isThunder = e.type == "thunder"
            local c = isThunder and {135, 80, 255} or {255, 210, 70}
            local core = isThunder and {165, 235, 255} or {255, 250, 180}
            local jitter = isThunder and 18 or 12
            local reveal = SkillSmoothStep(math.min(1, age / (isThunder and 0.10 or 0.18)))
            local tx = e.x1 + (e.x2 - e.x1) * reveal
            local ty = e.y1 + (e.y2 - e.y1) * reveal
            local strikeFade = math.max(0, 1 - math.max(0, age - 0.58) / 0.42)
            local strikeAlpha = SkillEffectAlpha(255 * strikeFade)
            DrawSkillGlow(vg, tx, ty, isThunder and 58 or 42, c, strikeAlpha * 0.35)
            nvgStrokeWidth(vg, isThunder and 7 or 5)
            nvgStrokeColor(vg, nvgRGBA(c[1], c[2], c[3], SkillEffectAlpha(strikeAlpha * 0.34)))
            DrawJaggedLine(vg, e.x1, e.y1, tx, ty, isThunder and 9 or 7, jitter, time + age)
            nvgStroke(vg)
            nvgStrokeWidth(vg, 2)
            nvgStrokeColor(vg, nvgRGBA(core[1], core[2], core[3], strikeAlpha))
            DrawJaggedLine(vg, e.x1, e.y1, tx, ty, isThunder and 10 or 8, jitter * 0.55, time * 1.8 + age)
            nvgStroke(vg)
            if reveal >= 0.98 then
                local burstAge = math.max(0, (age - (isThunder and 0.08 or 0.16)) / 0.84)
                local burstRadius = (isThunder and 28 or 22) + burstAge * (isThunder and 26 or 18)
                DrawSkillGlow(vg, e.x2, e.y2, burstRadius, isThunder and {145, 70, 255} or {255, 210, 70}, strikeAlpha * 0.26)
                DrawSkillBurst(vg, e.x2, e.y2, burstRadius, core, strikeAlpha * 0.62, isThunder and 6 or 4, time * 0.45)
                nvgBeginPath(vg)
                nvgCircle(vg, e.x2, e.y2, burstRadius * (0.48 + burstAge * 0.38))
                nvgStrokeWidth(vg, 2)
                nvgStrokeColor(vg, nvgRGBA(core[1], core[2], core[3], SkillEffectAlpha(strikeAlpha * 0.45)))
                nvgStroke(vg)
            end
            if isThunder and reveal > 0.45 then
                local dx = tx - e.x1
                local dy = ty - e.y1
                local branchCount = 3
                for i = 1, branchCount do
                    local p = 0.42 + i * 0.14
                    if p < reveal then
                        local bx = e.x1 + dx * p
                        local by = e.y1 + dy * p
                        local side = i % 2 == 0 and 1 or -1
                        nvgBeginPath(vg)
                        nvgMoveTo(vg, bx, by)
                        nvgLineTo(vg, bx + side * (18 + i * 4), by + 15 + i * 5)
                        nvgStrokeWidth(vg, 1)
                        nvgStrokeColor(vg, nvgRGBA(180, 125, 255, SkillEffectAlpha(strikeAlpha * 0.55)))
                        nvgStroke(vg)
                    end
                end
            elseif not isThunder and reveal > 0.65 then
                local dx = tx - e.x1
                local dy = ty - e.y1
                local len = math.sqrt(dx * dx + dy * dy)
                if len > 0 then
                    local nx = -dy / len
                    local ny = dx / len
                    for i = 1, 3 do
                        local p = i * 0.25
                        local bx = e.x1 + dx * p
                        local by = e.y1 + dy * p
                        nvgBeginPath(vg)
                        nvgMoveTo(vg, bx - nx * 9, by - ny * 9)
                        nvgLineTo(vg, bx + nx * 9, by + ny * 9)
                        nvgStrokeWidth(vg, 1)
                        nvgStrokeColor(vg, nvgRGBA(255, 235, 120, SkillEffectAlpha(strikeAlpha * 0.58)))
                        nvgStroke(vg)
                    end
                end
            end

        elseif e.type == "fireball" then
            local tx = e.x2 or e.x
            local ty = e.y2 or e.y
            local sx = e.x1 or hero.x
            local sy = e.y1 or hero.y
            local dx = tx - sx
            local dy = ty - sy
            local len = math.sqrt(dx * dx + dy * dy)
            local nx = len > 0 and -dy / len or 0
            local ny = len > 0 and dx / len or 0
            local side = (e.volleyIndex or 1) % 2 == 0 and -1 or 1
            local travel = SkillSmoothStep(math.min(1, age / 0.62))
            local arc = math.sin(travel * math.pi) * 22 * side
            local px = sx + dx * travel + nx * arc
            local py = sy + dy * travel + ny * arc
            local radius = e.radius or 64
            local fireColor = {255, 70, 24}
            local demonColor = {140, 35, 255}
            local flightAlpha = SkillEffectAlpha(255 * math.max(0, 1 - math.max(0, age - 0.72) / 0.28))

            if visualElapsed >= 0 then
                for i = 1, 5 do
                    local trailTravel = math.max(0, travel - i * 0.055)
                    local trailArc = math.sin(trailTravel * math.pi) * 22 * side
                    local x = sx + dx * trailTravel + nx * trailArc
                    local y = sy + dy * trailTravel + ny * trailArc
                    local trailRadius = math.max(7, 23 - i * 3)
                    DrawSkillGlow(vg, x, y, trailRadius, i % 2 == 0 and demonColor or fireColor,
                        flightAlpha * math.max(0.05, 0.28 - i * 0.035))
                end
                DrawSkillGlow(vg, px, py, 40, fireColor, flightAlpha * 0.55)
                DrawSkillGlow(vg, px, py, 25, demonColor, flightAlpha * 0.38)
                nvgBeginPath(vg)
                nvgCircle(vg, px, py, 9 + math.sin(time * 16 + (e.volleyIndex or 1)) * 2)
                local coreFill = nvgRadialGradient(vg, px, py, 1, 13,
                    nvgRGBA(255, 250, 185, flightAlpha),
                    nvgRGBA(255, 65, 20, SkillEffectAlpha(flightAlpha * 0.18)))
                nvgFillPaint(vg, coreFill)
                nvgFill(vg)
            end

            if age > 0.52 then
                local impactAge = math.min(1, (age - 0.52) / 0.48)
                local impactFade = 1 - impactAge
                local blast = radius * (0.28 + SkillSmoothStep(impactAge) * 0.95)
                DrawSkillGlow(vg, tx, ty, blast * 1.08, fireColor, 95 * impactFade)
                nvgBeginPath(vg)
                nvgCircle(vg, tx, ty, blast)
                nvgStrokeWidth(vg, 4 - impactAge * 2)
                nvgStrokeColor(vg, nvgRGBA(255, 125, 45, SkillEffectAlpha(220 * impactFade)))
                nvgStroke(vg)
                nvgBeginPath(vg)
                nvgCircle(vg, tx, ty, blast * 0.56)
                nvgStrokeWidth(vg, 2)
                nvgStrokeColor(vg, nvgRGBA(165, 65, 255, SkillEffectAlpha(185 * impactFade)))
                nvgStroke(vg)
                DrawSkillBurst(vg, tx, ty, blast * 1.12, {255, 205, 95}, 170 * impactFade, 6,
                    time * 0.32 + (e.volleyIndex or 1))
            end

        elseif e.type == "flying_sword" then
            local dx = e.x2 - e.x1
            local dy = e.y2 - e.y1
            local angle = math.atan(dy, dx)
            local travel = SkillSmoothStep(math.min(1, age / 0.72))
            local px = e.x1 + dx * travel
            local py = e.y1 + dy * travel
            local flightFade = math.max(0, 1 - math.max(0, age - 0.78) / 0.22)
            local swordAlpha = SkillEffectAlpha(245 * flightFade)
            for i = 1, 4 do
                local trail = math.max(0, travel - i * 0.075)
                local tx = e.x1 + dx * trail
                local ty = e.y1 + dy * trail
                local trailAlpha = SkillEffectAlpha(swordAlpha * math.max(0.05, 0.30 - i * 0.05))
                nvgStrokeWidth(vg, math.max(1, 6 - i))
                nvgStrokeColor(vg, nvgRGBA(i % 2 == 0 and 170 or 90, 110, 255, trailAlpha))
                nvgBeginPath(vg)
                nvgMoveTo(vg, tx - math.cos(angle) * (22 - i * 2), ty - math.sin(angle) * (22 - i * 2))
                nvgLineTo(vg, tx, ty)
                nvgStroke(vg)
            end
            DrawSkillGlow(vg, px, py, 24, {125, 95, 255}, swordAlpha * 0.30)
            nvgSave(vg)
            nvgTranslate(vg, px, py)
            nvgRotate(vg, angle)
            nvgBeginPath(vg)
            nvgMoveTo(vg, 20, 0)
            nvgLineTo(vg, -9, -6)
            nvgLineTo(vg, -4, 0)
            nvgLineTo(vg, -9, 6)
            nvgClosePath(vg)
            local swordFill = nvgLinearGradient(vg, -9, 0, 20, 0,
                nvgRGBA(135, 75, 255, SkillEffectAlpha(swordAlpha * 0.72)),
                nvgRGBA(250, 255, 255, swordAlpha))
            nvgFillPaint(vg, swordFill)
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgRect(vg, -17, -2, 13, 4)
            nvgFillColor(vg, nvgRGBA(185, 90, 255, SkillEffectAlpha(swordAlpha * 0.84)))
            nvgFill(vg)
            nvgRestore(vg)
            if age > 0.68 then
                local impactAge = math.min(1, (age - 0.68) / 0.32)
                DrawSkillBurst(vg, e.x2, e.y2, 24 + impactAge * 18, {210, 235, 255},
                    150 * (1 - impactAge), 4, angle)
            end
            DrawSkillGlow(vg, e.x1, e.y1, 18 + age * 7, {120, 75, 255}, alpha * 0.13)

        elseif e.type == "dart" then
            local dx = e.x2 - e.x1
            local dy = e.y2 - e.y1
            local angle = math.atan(dy, dx)
            local len = math.sqrt(dx * dx + dy * dy)
            local nx = len > 0 and -dy / len or 0
            local ny = len > 0 and dx / len or 0
            local side = (e.volleyIndex or 1) % 2 == 0 and -1 or 1
            local travel = SkillSmoothStep(math.min(1, age / 0.70))
            local arc = math.sin(travel * math.pi) * 13 * side
            local px = e.x1 + dx * travel + nx * arc
            local py = e.y1 + dy * travel + ny * arc
            local dartFade = math.max(0, 1 - math.max(0, age - 0.78) / 0.22)
            local dartAlpha = SkillEffectAlpha(245 * dartFade)
            for i = 1, 4 do
                local trail = math.max(0, travel - i * 0.075)
                local trailArc = math.sin(trail * math.pi) * 13 * side
                local x = e.x1 + dx * trail + nx * trailArc
                local y = e.y1 + dy * trail + ny * trailArc
                nvgBeginPath(vg)
                nvgCircle(vg, x, y, math.max(1, 5 - i))
                nvgFillColor(vg, nvgRGBA(65, 245, 115, SkillEffectAlpha(dartAlpha * (0.30 - i * 0.045))))
                nvgFill(vg)
            end
            DrawSkillGlow(vg, px, py, 23, {45, 210, 85}, dartAlpha * 0.30)
            nvgSave(vg)
            nvgTranslate(vg, px, py)
            nvgRotate(vg, angle + time * 11 * side)
            for blade = 1, 4 do
                local bladeAngle = (blade - 1) * math.pi * 0.5
                nvgSave(vg)
                nvgRotate(vg, bladeAngle)
                nvgBeginPath(vg)
                nvgMoveTo(vg, 2, 0)
                nvgLineTo(vg, 15, -3)
                nvgLineTo(vg, 9, 3)
                nvgClosePath(vg)
                nvgFillColor(vg, nvgRGBA(190, 255, 205, dartAlpha))
                nvgFill(vg)
                nvgRestore(vg)
            end
            nvgBeginPath(vg)
            nvgCircle(vg, 0, 0, 3)
            nvgFillColor(vg, nvgRGBA(40, 120, 60, dartAlpha))
            nvgFill(vg)
            nvgRestore(vg)
            if age > 0.64 then
                local impactAge = math.min(1, (age - 0.64) / 0.36)
                local impactAlpha = 1 - impactAge
                DrawSkillGlow(vg, e.x2, e.y2, 30 + impactAge * 22, {45, 190, 80}, 85 * impactAlpha)
                DrawSkillBurst(vg, e.x2, e.y2, 34 + impactAge * 20, {100, 255, 145},
                    150 * impactAlpha, 5, time * 0.4 + side)
                for i = 1, 4 do
                    local a = i * math.pi * 0.5 + time * 0.35
                    local rr = 12 + impactAge * (14 + i * 2)
                    nvgBeginPath(vg)
                    nvgCircle(vg, e.x2 + math.cos(a) * rr, e.y2 + math.sin(a) * rr - impactAge * 8,
                        2 + (i % 2))
                    nvgFillColor(vg, nvgRGBA(70, 230, 110, SkillEffectAlpha(150 * impactAlpha)))
                    nvgFill(vg)
                end
            end

        elseif e.type == "shield" or e.type == "shield_break" then
            local broken = e.type == "shield_break"
            local baseRadius = e.radius or 58
            local form = broken and 1 or SkillSmoothStep(math.min(1, age / 0.22))
            local radius = baseRadius * (broken and (0.92 + age * 0.30) or (0.24 + form * 0.76))
            local shieldColor = broken and {255, 65, 105} or {120, 190, 255}
            local runeColor = broken and {180, 55, 255} or {255, 220, 110}
            local pulse = 1.0 + math.sin(time * 8.0) * 0.04
            DrawSkillGlow(vg, e.x, e.y, radius * 1.28, shieldColor, alpha * (broken and 0.26 or 0.20))
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius * pulse)
            local shieldFill = nvgRadialGradient(vg, e.x, e.y, radius * 0.28, radius * pulse,
                nvgRGBA(shieldColor[1], shieldColor[2], shieldColor[3], SkillEffectAlpha(alpha * 0.17)),
                nvgRGBA(shieldColor[1], shieldColor[2], shieldColor[3], 0))
            nvgFillPaint(vg, shieldFill)
            nvgFill(vg)
            local layerCount = broken and 1 or math.max(1, math.min(5, e.layers or 1))
            for layer = 1, layerCount do
                local layerRadius = radius * (0.48 + layer * 0.12)
                local direction = layer % 2 == 0 and -1 or 1
                nvgBeginPath(vg)
                nvgCircle(vg, e.x, e.y, layerRadius * pulse)
                nvgStrokeWidth(vg, layer == layerCount and 2 or 1)
                nvgStrokeColor(vg, nvgRGBA(runeColor[1], runeColor[2], runeColor[3],
                    SkillEffectAlpha(alpha * (0.28 + layer * 0.08))))
                nvgStroke(vg)
                for rune = 1, 4 do
                    local a = time * (1.15 + layer * 0.16) * direction + rune * math.pi * 0.5 + layer * 0.4
                    local rx = e.x + math.cos(a) * layerRadius
                    local ry = e.y + math.sin(a) * layerRadius
                    nvgSave(vg)
                    nvgTranslate(vg, rx, ry)
                    nvgRotate(vg, a)
                    nvgBeginPath(vg)
                    nvgRect(vg, -2.5, -2.5, 5, 5)
                    nvgFillColor(vg, nvgRGBA(runeColor[1], runeColor[2], runeColor[3],
                        SkillEffectAlpha(alpha * 0.62)))
                    nvgFill(vg)
                    nvgRestore(vg)
                end
            end
            if broken then
                for i = 1, 8 do
                    local a = i * math.pi * 2 / 8 + time * 0.35
                    local inner = radius * 0.20
                    local outer = radius * (0.78 + age * 0.72)
                    nvgBeginPath(vg)
                    nvgMoveTo(vg, e.x + math.cos(a) * inner, e.y + math.sin(a) * inner)
                    nvgLineTo(vg, e.x + math.cos(a + 0.12) * outer, e.y + math.sin(a + 0.12) * outer)
                    nvgStrokeWidth(vg, i % 2 == 0 and 2 or 1)
                    nvgStrokeColor(vg, nvgRGBA(255, 90, 135, SkillEffectAlpha(alpha * 0.82)))
                    nvgStroke(vg)
                    nvgBeginPath(vg)
                    nvgMoveTo(vg, e.x + math.cos(a) * outer, e.y + math.sin(a) * outer)
                    nvgLineTo(vg, e.x + math.cos(a + 0.18) * outer * 1.12,
                        e.y + math.sin(a + 0.18) * outer * 1.12)
                    nvgLineTo(vg, e.x + math.cos(a - 0.14) * outer * 1.22,
                        e.y + math.sin(a - 0.14) * outer * 1.22)
                    nvgStrokeWidth(vg, 1)
                    nvgStrokeColor(vg, nvgRGBA(205, 115, 255, SkillEffectAlpha(alpha * 0.58)))
                    nvgStroke(vg)
                end
            else
                local sweepAngle = time * 2.6
                nvgBeginPath(vg)
                nvgMoveTo(vg, e.x + math.cos(sweepAngle) * radius * 0.20, e.y + math.sin(sweepAngle) * radius * 0.20)
                nvgLineTo(vg, e.x + math.cos(sweepAngle) * radius * 0.92, e.y + math.sin(sweepAngle) * radius * 0.92)
                nvgStrokeWidth(vg, 3)
                nvgStrokeColor(vg, nvgRGBA(220, 250, 255, SkillEffectAlpha(alpha * 0.45)))
                nvgStroke(vg)
            end

        elseif e.type == "blade_orbit" then
            local baseRadius = e.radius or 118
            local summon = math.min(1, age / 0.12)
            local dismiss = age > 0.86 and math.max(0, (1 - age) / 0.14) or 1
            local orbitScale = SkillSmoothStep(math.min(summon, dismiss))
            local radius = baseRadius * (0.42 + orbitScale * 0.58)
            local spin = time * 6.5
            DrawSkillGlow(vg, hero.x, hero.y, radius * 1.10, {75, 195, 255}, alpha * 0.14)
            for ring = 1, 2 do
                local rr = radius * (ring == 1 and 1 or 0.63)
                nvgBeginPath(vg)
                nvgCircle(vg, hero.x, hero.y, rr)
                nvgStrokeWidth(vg, ring == 1 and 2 or 1)
                nvgStrokeColor(vg, nvgRGBA(ring == 1 and 105 or 185, ring == 1 and 225 or 155, 255,
                    SkillEffectAlpha(alpha * (ring == 1 and 0.46 or 0.34))))
                nvgStroke(vg)
            end
            for i = 1, 8 do
                local outer = i % 2 == 1
                local bladeRadius = outer and radius or radius * 0.63
                local direction = outer and 1 or -1
                local angle = spin * direction + (i - 1) * math.pi * 0.25
                local x = hero.x + math.cos(angle) * bladeRadius
                local y = hero.y + math.sin(angle) * bladeRadius
                for trail = 3, 1, -1 do
                    local trailAngle = angle - direction * trail * 0.10
                    local tx = hero.x + math.cos(trailAngle) * bladeRadius
                    local ty = hero.y + math.sin(trailAngle) * bladeRadius
                    nvgBeginPath(vg)
                    nvgCircle(vg, tx, ty, 2 + (3 - trail))
                    nvgFillColor(vg, nvgRGBA(95, 205, 255, SkillEffectAlpha(alpha * (0.08 + trail * 0.035))))
                    nvgFill(vg)
                end
                nvgSave(vg)
                nvgTranslate(vg, x, y)
                nvgRotate(vg, angle + direction * math.pi * 0.5)
                nvgBeginPath(vg)
                nvgMoveTo(vg, -12, 0)
                nvgLineTo(vg, 8, -5)
                nvgLineTo(vg, 15, 0)
                nvgLineTo(vg, 8, 5)
                nvgClosePath(vg)
                nvgFillColor(vg, nvgRGBA(215, 250, 255, SkillEffectAlpha(alpha * 0.90)))
                nvgFill(vg)
                nvgStrokeWidth(vg, 1)
                nvgStrokeColor(vg, nvgRGBA(75, 160, 255, alpha))
                nvgStroke(vg)
                nvgRestore(vg)
            end

        elseif e.type == "piercing_lance" then
            local x1, y1 = e.x1 or hero.x, e.y1 or hero.y
            local x2, y2 = e.x2 or x1, e.y2 or y1
            local dx, dy = x2 - x1, y2 - y1
            local len = math.sqrt(dx * dx + dy * dy)
            if len > 0 then
                local ux, uy = dx / len, dy / len
                local nx, ny = -uy, ux
                local width = e.width or 36
                local chargeAge = math.min(1, age / 0.20)
                local launchAge = SkillSmoothStep(math.max(0, math.min(1, (age - 0.12) / 0.58)))
                local fade = math.max(0, 1 - math.max(0, age - 0.78) / 0.22)
                local lanceAlpha = SkillEffectAlpha(245 * fade)
                local tipX = x1 + dx * launchAge
                local tipY = y1 + dy * launchAge
                local tailProgress = math.max(0, launchAge - 0.34)
                local tailX = x1 + dx * tailProgress
                local tailY = y1 + dy * tailProgress
                if age < 0.28 then
                    local chargeRadius = 12 + chargeAge * 24
                    DrawSkillGlow(vg, x1, y1, chargeRadius * 1.3, {85, 210, 255}, 95 * (1 - age / 0.28))
                    for line = -2, 2 do
                        nvgBeginPath(vg)
                        nvgMoveTo(vg, x1 - ux * 42 + nx * line * 7, y1 - uy * 42 + ny * line * 7)
                        nvgLineTo(vg, x1 - ux * 8 + nx * line * 3, y1 - uy * 8 + ny * line * 3)
                        nvgStrokeWidth(vg, line == 0 and 3 or 1)
                        nvgStrokeColor(vg, nvgRGBA(170, 235, 255, SkillEffectAlpha(150 * (1 - age / 0.28))))
                        nvgStroke(vg)
                    end
                end
                if launchAge > 0 then
                    for trail = 1, 3 do
                        local offset = trail * width * 0.24
                        local side = trail % 2 == 0 and -1 or 1
                        nvgBeginPath(vg)
                        nvgMoveTo(vg, tailX + nx * offset * side, tailY + ny * offset * side)
                        nvgLineTo(vg, tipX - ux * (22 + trail * 8) + nx * offset * 0.35 * side,
                            tipY - uy * (22 + trail * 8) + ny * offset * 0.35 * side)
                        nvgStrokeWidth(vg, trail == 1 and 3 or 1)
                        nvgStrokeColor(vg, nvgRGBA(120, 225, 255, SkillEffectAlpha(lanceAlpha * (0.34 - trail * 0.06))))
                        nvgStroke(vg)
                    end
                    DrawSkillGlow(vg, tipX, tipY, width * 1.85, {80, 210, 255}, lanceAlpha * 0.27)
                    nvgBeginPath(vg)
                    nvgMoveTo(vg, tailX + nx * width * 0.28, tailY + ny * width * 0.28)
                    nvgLineTo(vg, tipX + nx * width * 0.12, tipY + ny * width * 0.12)
                    nvgLineTo(vg, tipX + ux * 27, tipY + uy * 27)
                    nvgLineTo(vg, tipX - nx * width * 0.12, tipY - ny * width * 0.12)
                    nvgLineTo(vg, tailX - nx * width * 0.28, tailY - ny * width * 0.28)
                    nvgClosePath(vg)
                    local lanceFill = nvgLinearGradient(vg, tailX, tailY, tipX, tipY,
                        nvgRGBA(55, 145, 255, SkillEffectAlpha(lanceAlpha * 0.28)),
                        nvgRGBA(235, 255, 255, lanceAlpha))
                    nvgFillPaint(vg, lanceFill)
                    nvgFill(vg)
                    nvgStrokeWidth(vg, 2)
                    nvgStrokeColor(vg, nvgRGBA(225, 250, 255, lanceAlpha))
                    nvgStroke(vg)
                end
                if age > 0.66 then
                    local impactAge = math.min(1, (age - 0.66) / 0.34)
                    DrawSkillBurst(vg, x2, y2, 30 + impactAge * 28, {200, 245, 255},
                        155 * (1 - impactAge), 4, math.atan(dy, dx))
                end
            end

        elseif e.type == "flame_zone" then
            local baseRadius = e.radius or 92
            local form = SkillSmoothStep(math.min(1, age / 0.10))
            local vanish = age > 0.88 and math.max(0, (1 - age) / 0.12) or 1
            local radius = baseRadius * (0.45 + 0.55 * form)
            local zoneAlpha = alpha * vanish
            local pulse = 0.96 + math.sin(time * 5) * 0.04
            DrawSkillGlow(vg, e.x, e.y, radius * 1.18, {255, 75, 25}, zoneAlpha * 0.25)
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius * pulse)
            local flameFill = nvgRadialGradient(vg, e.x, e.y, radius * 0.10, radius * pulse,
                nvgRGBA(255, 195, 55, SkillEffectAlpha(zoneAlpha * 0.36)),
                nvgRGBA(165, 25, 10, SkillEffectAlpha(zoneAlpha * 0.06)))
            nvgFillPaint(vg, flameFill)
            nvgFill(vg)
            DrawSkillCracks(vg, e.x, e.y, radius * 0.88, {255, 125, 35}, zoneAlpha * 0.55, 8, time * 0.05)
            for i = 1, 8 do
                local angle = i * 2.399 + time * (i % 2 == 0 and 0.24 or -0.18)
                local rr = radius * (0.18 + (i % 4) * 0.17)
                local x = e.x + math.cos(angle) * rr
                local baseY = e.y + math.sin(angle) * rr * 0.65
                local flamePhase = (time * (5.5 + i * 0.18) + i * 1.7) % (math.pi * 2)
                local flameH = 14 + (i % 3) * 7 + math.sin(flamePhase) * 5
                nvgBeginPath(vg)
                nvgMoveTo(vg, x - 6, baseY + 4)
                nvgLineTo(vg, x + math.sin(flamePhase) * 4, baseY - flameH)
                nvgLineTo(vg, x + 6, baseY + 4)
                nvgClosePath(vg)
                local tongueFill = nvgLinearGradient(vg, x, baseY + 4, x, baseY - flameH,
                    nvgRGBA(255, 80, 18, SkillEffectAlpha(zoneAlpha * 0.66)),
                    nvgRGBA(255, 240, 120, SkillEffectAlpha(zoneAlpha * 0.88)))
                nvgFillPaint(vg, tongueFill)
                nvgFill(vg)
            end
            for i = 1, 5 do
                local sparkPhase = (time * (0.62 + i * 0.04) + i * 0.17) % 1
                local a = i * 1.71 + time * 0.22
                local rr = radius * (0.22 + (i % 3) * 0.20)
                local sx = e.x + math.cos(a) * rr
                local sy = e.y + math.sin(a) * rr * 0.62 - sparkPhase * 30
                nvgBeginPath(vg)
                nvgCircle(vg, sx, sy, 1.5 + (i % 2))
                nvgFillColor(vg, nvgRGBA(255, 215, 90, SkillEffectAlpha(zoneAlpha * (1 - sparkPhase) * 0.75)))
                nvgFill(vg)
            end

        elseif e.type == "returning_axe" then
            local x1, y1 = e.x1 or hero.x, e.y1 or hero.y
            local x2, y2 = e.x2 or x1, e.y2 or y1
            local dx, dy = x2 - x1, y2 - y1
            local len = math.sqrt(dx * dx + dy * dy)
            local nx = len > 0 and -dy / len or 0
            local ny = len > 0 and dx / len or 0
            local progress = math.max(0, math.min(1, age))
            local outbound = progress <= 0.5
            local leg = outbound and progress * 2 or (progress - 0.5) * 2
            local travel = outbound and SkillSmoothStep(leg) or (1 - SkillSmoothStep(leg))
            local side = outbound and 1 or -1
            local arc = math.sin(travel * math.pi) * 34 * side
            local x = x1 + dx * travel + nx * arc
            local y = y1 + dy * travel + ny * arc
            DrawSkillGlow(vg, x, y, 30, {255, 160, 45}, alpha * 0.36)
            for trail = 1, 4 do
                local past = math.max(0, math.min(1, travel - side * trail * 0.045))
                local trailArc = math.sin(past * math.pi) * 34 * side
                local tx = x1 + dx * past + nx * trailArc
                local ty = y1 + dy * past + ny * trailArc
                nvgBeginPath(vg)
                nvgCircle(vg, tx, ty, math.max(2, 7 - trail))
                nvgFillColor(vg, nvgRGBA(255, 150, 45, SkillEffectAlpha(alpha * (0.25 - trail * 0.04))))
                nvgFill(vg)
            end
            nvgSave(vg)
            nvgTranslate(vg, x, y)
            nvgRotate(vg, time * 18 * side)
            nvgBeginPath(vg)
            nvgMoveTo(vg, -13, 0)
            nvgLineTo(vg, -3, -12)
            nvgLineTo(vg, 15, -7)
            nvgLineTo(vg, 10, 0)
            nvgLineTo(vg, 15, 7)
            nvgLineTo(vg, -3, 12)
            nvgClosePath(vg)
            local axeFill = nvgLinearGradient(vg, -13, -10, 15, 8,
                nvgRGBA(145, 70, 25, alpha),
                nvgRGBA(255, 235, 160, alpha))
            nvgFillPaint(vg, axeFill)
            nvgFill(vg)
            nvgStrokeWidth(vg, 2)
            nvgStrokeColor(vg, nvgRGBA(255, 238, 180, alpha))
            nvgStroke(vg)
            nvgRestore(vg)
            if math.abs(progress - 0.5) < 0.12 then
                local turnAge = math.abs(progress - 0.5) / 0.12
                DrawSkillBurst(vg, x2, y2, 34 + (1 - turnAge) * 16, {255, 205, 105},
                    170 * (1 - turnAge), 5, time * 0.7)
            elseif progress > 0.82 then
                local catchAge = (progress - 0.82) / 0.18
                DrawSkillGlow(vg, x1, y1, 24 + catchAge * 18, {255, 190, 80}, 80 * (1 - catchAge))
            end

        elseif e.type == "ground_slam" then
            local radius = e.radius or 112
            local charge = math.min(1, age / 0.16)
            local impactAge = SkillSmoothStep(math.max(0, math.min(1, (age - 0.10) / 0.90)))
            local ring = radius * (0.12 + impactAge * 0.88)
            if age < 0.20 then
                local chargeFade = 1 - age / 0.20
                DrawSkillGlow(vg, e.x, e.y, 24 + charge * 30, {255, 200, 115}, 100 * chargeFade)
                DrawSkillBurst(vg, e.x, e.y, 30 + charge * 22, {255, 225, 155}, 170 * chargeFade, 6,
                    time * 0.28)
            end
            DrawSkillGlow(vg, e.x, e.y, ring * 1.10, {205, 130, 75}, alpha * 0.24)
            for i = 1, 3 do
                local ringDelay = math.max(0, impactAge - (i - 1) * 0.10)
                local rr = radius * math.min(1, 0.12 + ringDelay * (0.92 + i * 0.06))
                nvgBeginPath(vg)
                nvgCircle(vg, e.x, e.y, rr)
                nvgStrokeWidth(vg, 5 - i)
                nvgStrokeColor(vg, nvgRGBA(235, 170, 100,
                    SkillEffectAlpha(alpha * (0.58 - i * 0.10))))
                nvgStroke(vg)
            end
            DrawSkillCracks(vg, e.x, e.y, ring, {255, 205, 125}, alpha * 0.62, 9, time * 0.04)
            for i = 1, 6 do
                local rockProgress = math.min(1, math.max(0, (age - 0.14 - i * 0.012) / 0.62))
                local a = i * 2.399
                local rr = radius * (0.20 + (i % 3) * 0.18) * impactAge
                local rockX = e.x + math.cos(a) * rr
                local groundY = e.y + math.sin(a) * rr * 0.55
                local rockY = groundY - math.sin(rockProgress * math.pi) * (18 + (i % 3) * 7)
                local rockSize = 3 + (i % 3) * 2
                nvgSave(vg)
                nvgTranslate(vg, rockX, rockY)
                nvgRotate(vg, time * (i % 2 == 0 and -1.8 or 1.6) + i)
                nvgBeginPath(vg)
                nvgRect(vg, -rockSize, -rockSize, rockSize * 2, rockSize * 2)
                nvgFillColor(vg, nvgRGBA(170, 115, 70, SkillEffectAlpha(alpha * 0.78)))
                nvgFill(vg)
                nvgRestore(vg)
            end

        elseif e.type == "sword_wave" then
            local x1 = e.x1 or hero.x
            local y1 = e.y1 or hero.y
            local x2 = e.x2 or x1
            local y2 = e.y2 or y1
            local dx = x2 - x1
            local dy = y2 - y1
            local len = math.sqrt(dx * dx + dy * dy)
            if len > 0 then
                local ux = dx / len
                local uy = dy / len
                local nx = -uy
                local ny = ux
                local travel = SkillSmoothStep(math.min(1, age / 0.72))
                local headDistance = len * travel
                local waveLength = math.min(len * 0.46, 145)
                local tailDistance = math.max(0, headDistance - waveLength)
                local headX = x1 + ux * headDistance
                local headY = y1 + uy * headDistance
                local tailX = x1 + ux * tailDistance
                local tailY = y1 + uy * tailDistance
                local baseW = (e.width or 38) * (0.78 + math.sin(travel * math.pi) * 0.34)
                local tipW = baseW * 0.20
                local waveFade = math.max(0, 1 - math.max(0, age - 0.80) / 0.20)
                local waveAlpha = SkillEffectAlpha(240 * waveFade)
                DrawSkillGlow(vg, headX, headY, baseW * 1.45, {115, 225, 255}, waveAlpha * 0.18)
                for echo = 2, 1, -1 do
                    local echoDistance = math.max(0, headDistance - echo * 28)
                    local ex = x1 + ux * echoDistance
                    local ey = y1 + uy * echoDistance
                    local echoW = baseW * (0.78 - echo * 0.12)
                    nvgBeginPath(vg)
                    nvgMoveTo(vg, ex + nx * echoW * 0.42, ey + ny * echoW * 0.42)
                    nvgLineTo(vg, ex + ux * 38, ey + uy * 38)
                    nvgLineTo(vg, ex - nx * echoW * 0.42, ey - ny * echoW * 0.42)
                    nvgStrokeWidth(vg, 2)
                    nvgStrokeColor(vg, nvgRGBA(130, 195, 255, SkillEffectAlpha(waveAlpha * (0.20 + echo * 0.06))))
                    nvgStroke(vg)
                end
                nvgBeginPath(vg)
                nvgMoveTo(vg, tailX + nx * baseW * 0.50, tailY + ny * baseW * 0.50)
                nvgLineTo(vg, headX + nx * tipW, headY + ny * tipW)
                nvgLineTo(vg, headX + ux * 28, headY + uy * 28)
                nvgLineTo(vg, headX - nx * tipW, headY - ny * tipW)
                nvgLineTo(vg, tailX - nx * baseW * 0.50, tailY - ny * baseW * 0.50)
                nvgClosePath(vg)
                local bladeFill = nvgLinearGradient(vg, tailX, tailY, headX, headY,
                    nvgRGBA(70, 150, 255, SkillEffectAlpha(waveAlpha * 0.12)),
                    nvgRGBA(235, 250, 255, SkillEffectAlpha(waveAlpha * 0.76)))
                nvgFillPaint(vg, bladeFill)
                nvgFill(vg)
                nvgStrokeWidth(vg, math.max(2, baseW * 0.09))
                nvgStrokeColor(vg, nvgRGBA(235, 252, 255, SkillEffectAlpha(waveAlpha * 0.86)))
                nvgBeginPath(vg)
                nvgMoveTo(vg, tailX, tailY)
                nvgLineTo(vg, headX + ux * 20, headY + uy * 20)
                nvgStroke(vg)
                for i = 1, 3 do
                    local p = math.max(0, travel - i * 0.09)
                    local bx = x1 + dx * p
                    local by = y1 + dy * p
                    local side = i % 2 == 0 and 1 or -1
                    nvgBeginPath(vg)
                    nvgMoveTo(vg, bx - ux * 10 - nx * baseW * 0.28 * side,
                        by - uy * 10 - ny * baseW * 0.28 * side)
                    nvgLineTo(vg, bx + ux * 22 + nx * baseW * 0.16 * side,
                        by + uy * 22 + ny * baseW * 0.16 * side)
                    nvgStrokeWidth(vg, 1)
                    nvgStrokeColor(vg, nvgRGBA(195, 240, 255, SkillEffectAlpha(waveAlpha * 0.46)))
                    nvgStroke(vg)
                end
            end

        elseif e.type == "poison_mist" then
            local baseRadius = e.radius or 95
            local form = SkillSmoothStep(math.min(1, age / 0.10))
            local evaporate = age > 0.84 and math.max(0, (1 - age) / 0.16) or 1
            local radius = baseRadius * (0.52 + form * 0.48)
            local mistAlpha = alpha * evaporate
            local pulse = 0.96 + math.sin(time * 2.2 + age * 3.0) * 0.04
            DrawSkillGlow(vg, e.x, e.y, radius * 1.12, {45, 210, 90}, mistAlpha * 0.21)
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius * pulse)
            local mistFill = nvgRadialGradient(vg, e.x, e.y, radius * 0.16, radius * pulse,
                nvgRGBA(95, 255, 125, SkillEffectAlpha(mistAlpha * 0.22)),
                nvgRGBA(15, 80, 35, SkillEffectAlpha(mistAlpha * 0.04)))
            nvgFillPaint(vg, mistFill)
            nvgFill(vg)
            for ring = 1, 2 do
                nvgBeginPath(vg)
                nvgCircle(vg, e.x, e.y, radius * (0.48 + ring * 0.22) * pulse)
                nvgStrokeWidth(vg, ring == 1 and 2 or 1)
                nvgStrokeColor(vg, nvgRGBA(120, 255, 135, SkillEffectAlpha(mistAlpha * (0.32 - ring * 0.06))))
                nvgStroke(vg)
            end
            for i = 1, 10 do
                local cloudPhase = (time * (0.26 + i * 0.011) + i * 0.19) % 1
                local a = i * 2.399 + time * (0.22 + i * 0.008)
                local rr = radius * (0.14 + (i % 5) * 0.16)
                local x = e.x + math.cos(a) * rr
                local y = e.y + math.sin(a) * rr * 0.68 - cloudPhase * (age > 0.84 and 34 or 12)
                local s = 7 + (i % 4) * 3 + math.sin(time * 1.5 + i) * 2
                nvgBeginPath(vg)
                nvgCircle(vg, x, y, s)
                nvgFillColor(vg, nvgRGBA(110, 245, 135, SkillEffectAlpha(mistAlpha * (0.14 + (i % 3) * 0.05))))
                nvgFill(vg)
            end
            for i = 1, 4 do
                local bubblePhase = (time * (0.45 + i * 0.05) + i * 0.23) % 1
                local a = i * 1.57 + time * 0.18
                local rr = radius * (0.25 + (i % 2) * 0.30)
                local bx = e.x + math.cos(a) * rr
                local by = e.y + math.sin(a) * rr * 0.65 - bubblePhase * 24
                local br = 2 + bubblePhase * 5
                nvgBeginPath(vg)
                nvgCircle(vg, bx, by, br)
                nvgStrokeWidth(vg, 1)
                nvgStrokeColor(vg, nvgRGBA(180, 255, 185, SkillEffectAlpha(mistAlpha * (1 - bubblePhase) * 0.55)))
                nvgStroke(vg)
            end

        elseif e.type == "storm_push" then
            local radius = e.radius or 150
            local gather = math.min(1, age / 0.18)
            local burstAge = SkillSmoothStep(math.max(0, math.min(1, (age - 0.10) / 0.90)))
            local ring = radius * (0.10 + burstAge * 0.98)
            local inner = math.max(8, ring * 0.38)
            if age < 0.24 then
                local gatherAlpha = 1 - age / 0.24
                for i = 1, 6 do
                    local a = time * 2.8 + i * math.pi / 3
                    local outer = radius * (0.50 + (i % 2) * 0.24)
                    local innerR = radius * (0.18 + gather * 0.12)
                    nvgBeginPath(vg)
                    nvgMoveTo(vg, e.x + math.cos(a) * outer, e.y + math.sin(a) * outer)
                    nvgLineTo(vg, e.x + math.cos(a + 0.32) * innerR, e.y + math.sin(a + 0.32) * innerR)
                    nvgStrokeWidth(vg, i % 2 == 0 and 2 or 1)
                    nvgStrokeColor(vg, nvgRGBA(170, 240, 255, SkillEffectAlpha(150 * gatherAlpha)))
                    nvgStroke(vg)
                end
            end
            DrawSkillGlow(vg, e.x, e.y, ring, {90, 220, 255}, alpha * 0.14)
            for k = 1, 3 do
                local delayed = math.max(0, burstAge - (k - 1) * 0.09)
                local rr = math.min(radius * 1.05, radius * (0.10 + delayed * (0.88 + k * 0.08)))
                nvgBeginPath(vg)
                nvgCircle(vg, e.x, e.y, rr)
                nvgStrokeWidth(vg, 5 - k)
                nvgStrokeColor(vg, nvgRGBA(120, 230, 255,
                    SkillEffectAlpha(alpha * (0.62 - k * 0.12))))
                nvgStroke(vg)
            end
            for i = 1, 10 do
                local a = time * 2.4 + i * math.pi * 2 / 10
                local bend = math.sin(time * 4.0 + i) * 0.30
                local x1 = e.x + math.cos(a + bend) * inner
                local y1 = e.y + math.sin(a + bend) * inner
                local x2 = e.x + math.cos(a + bend * 0.30) * math.min(radius * 1.08, ring + 30)
                local y2 = e.y + math.sin(a + bend * 0.30) * math.min(radius * 1.08, ring + 30)
                nvgBeginPath(vg)
                nvgMoveTo(vg, x1, y1)
                nvgLineTo(vg, x2, y2)
                nvgStrokeWidth(vg, 1 + (i % 3))
                nvgStrokeColor(vg, nvgRGBA(180, 245, 255, SkillEffectAlpha(alpha * 0.44)))
                nvgStroke(vg)
            end
            for i = 1, 5 do
                local a = i * 1.41 + time * 0.65
                local rr = ring * (0.35 + (i % 3) * 0.22)
                nvgBeginPath(vg)
                nvgMoveTo(vg, e.x + math.cos(a) * rr, e.y + math.sin(a) * rr)
                nvgLineTo(vg, e.x + math.cos(a) * (rr + 26), e.y + math.sin(a) * (rr + 26))
                nvgStrokeWidth(vg, 1)
                nvgStrokeColor(vg, nvgRGBA(225, 250, 255, SkillEffectAlpha(alpha * 0.50)))
                nvgStroke(vg)
            end

        elseif e.type == "holy_judgement" then
            local x2 = e.x2 or e.x or hero.x
            local y2 = e.y2 or e.y or hero.y
            local x1 = e.x1 or x2
            local y1 = e.y1 or -24
            local radius = e.radius or 24
            local lockAge = math.min(1, age / 0.26)
            local beamAge = SkillSmoothStep(math.max(0, math.min(1, (age - 0.16) / 0.34)))
            local impactAge = math.max(0, math.min(1, (age - 0.34) / 0.66))
            local beamFade = 1 - math.max(0, age - 0.82) / 0.18
            local beamAlpha = SkillEffectAlpha(245 * math.max(0, beamFade))
            local lockRadius = radius * (2.15 - lockAge * 0.70)
            DrawCultivationRing(vg, x2, y2, lockRadius, {255, 220, 95},
                SkillEffectAlpha(190 * (1 - impactAge * 0.55)), time * 1.2)
            DrawSkillGlow(vg, x2, y2, radius * (2.2 + impactAge * 2.0), {255, 220, 105}, beamAlpha * 0.32)
            if beamAge > 0 then
                local beamWidth = 6 + beamAge * 18
                nvgStrokeWidth(vg, beamWidth + 14)
                nvgStrokeColor(vg, nvgRGBA(255, 210, 90, SkillEffectAlpha(beamAlpha * 0.18)))
                nvgBeginPath(vg)
                nvgMoveTo(vg, x1, y1)
                nvgLineTo(vg, x2, y2)
                nvgStroke(vg)
                nvgStrokeWidth(vg, beamWidth)
                nvgStrokeColor(vg, nvgRGBA(255, 235, 125, SkillEffectAlpha(beamAlpha * 0.78)))
                nvgBeginPath(vg)
                nvgMoveTo(vg, x1, y1)
                nvgLineTo(vg, x2, y2)
                nvgStroke(vg)
                nvgStrokeWidth(vg, math.max(2, beamWidth * 0.22))
                nvgStrokeColor(vg, nvgRGBA(255, 255, 245, beamAlpha))
                nvgBeginPath(vg)
                nvgMoveTo(vg, x1, y1)
                nvgLineTo(vg, x2, y2)
                nvgStroke(vg)
            end
            if impactAge > 0 then
                local impactFade = 1 - impactAge
                local ringR = radius * (1.10 + SkillSmoothStep(impactAge) * 2.20)
                for ring = 1, 2 do
                    nvgBeginPath(vg)
                    nvgCircle(vg, x2, y2, ringR * (ring == 1 and 1 or 0.62))
                    nvgStrokeWidth(vg, ring == 1 and 4 or 2)
                    nvgStrokeColor(vg, nvgRGBA(ring == 1 and 255 or 185, ring == 1 and 220 or 95,
                        ring == 1 and 90 or 255, SkillEffectAlpha(210 * impactFade)))
                    nvgStroke(vg)
                end
                DrawSkillBurst(vg, x2, y2, ringR * 1.16, {255, 245, 170}, 185 * impactFade, 8,
                    time * 0.55)
                local cross = ringR * 0.90
                nvgStrokeWidth(vg, 3)
                nvgStrokeColor(vg, nvgRGBA(255, 255, 225, SkillEffectAlpha(180 * impactFade)))
                nvgBeginPath(vg)
                nvgMoveTo(vg, x2 - cross, y2)
                nvgLineTo(vg, x2 + cross, y2)
                nvgMoveTo(vg, x2, y2 - cross)
                nvgLineTo(vg, x2, y2 + cross)
                nvgStroke(vg)
            end

        elseif e.type == "monster_spawn" then
            local c = e.color or {105, 90, 180}
            local radius = (e.radius or 20) * (0.52 + SkillSmoothStep(age) * (e.boss and 2.15 or 1.35))
            local fade = 1 - age
            local highLoad = IsBattleHighVisualLoad and IsBattleHighVisualLoad()
            local mediumLoad = not highLoad
                and IsBattleMediumVisualLoad
                and IsBattleMediumVisualLoad()
            if not highLoad then
                DrawSkillGlow(
                    vg,
                    e.x,
                    e.y,
                    radius * (mediumLoad and 1.05 or 1.25),
                    c,
                    (mediumLoad and 42 or 78) * fade
                )
            end
            local ringCount = highLoad and 1
                or (mediumLoad and (e.boss and 2 or 1) or (e.boss and 3 or 2))
            for ring = 1, ringCount do
                local ringRadius = radius * (0.45 + ring * 0.24)
                nvgBeginPath(vg)
                nvgCircle(vg, e.x, e.y, ringRadius)
                nvgStrokeColor(vg, nvgRGBA(c[1], c[2], c[3], SkillEffectAlpha((175 - ring * 28) * fade)))
                nvgStrokeWidth(vg, e.boss and 3 or 2)
                nvgStroke(vg)
            end
            if not highLoad then
                DrawSkillBurst(
                    vg,
                    e.x,
                    e.y,
                    radius,
                    c,
                    (mediumLoad and 82 or 118) * fade,
                    mediumLoad and (e.boss and 5 or 3) or (e.boss and 8 or 5),
                    time * 0.28
                )
            end

        elseif e.type == "monster_death" then
            local c = e.color or {180, 90, 130}
            local radius = (e.radius or 28) * (0.32 + SkillSmoothStep(age) * 0.98)
            local fade = 1 - age
            DrawSkillGlow(vg, e.x, e.y, radius * 1.16, c, 82 * fade)
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius)
            nvgStrokeColor(vg, nvgRGBA(c[1], c[2], c[3], SkillEffectAlpha(190 * fade)))
            nvgStrokeWidth(vg, math.max(1, 4 - age * 3))
            nvgStroke(vg)
            DrawSkillBurst(vg, e.x, e.y, radius * 1.15, c, 175 * fade, 6, time * 0.24)

        elseif e.type == "split_burst" then
            local radius = (e.radius or 40) * (0.42 + SkillSmoothStep(age) * 0.92)
            local fade = 1 - age
            DrawSkillGlow(vg, e.x, e.y, radius * 1.16, {92, 130, 255}, 68 * fade)
            for i = 1, 3 do
                local a = (i - 1) * math.pi * 2 / 3 + 0.3
                local inner = radius * 0.18
                local outer = radius * (0.72 + age * 0.36)
                nvgBeginPath(vg)
                nvgMoveTo(vg, e.x + math.cos(a) * inner, e.y + math.sin(a) * inner)
                nvgLineTo(vg, e.x + math.cos(a) * outer, e.y + math.sin(a) * outer)
                nvgStrokeColor(vg, nvgRGBA(155, 205, 255, SkillEffectAlpha(210 * fade)))
                nvgStrokeWidth(vg, 3 - age * 2)
                nvgStroke(vg)
                nvgBeginPath(vg)
                nvgCircle(vg, e.x + math.cos(a) * outer, e.y + math.sin(a) * outer, 4 + 3 * fade)
                nvgFillColor(vg, nvgRGBA(100, 95, 235, SkillEffectAlpha(180 * fade)))
                nvgFill(vg)
            end
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius * 0.64)
            nvgStrokeColor(vg, nvgRGBA(115, 170, 255, SkillEffectAlpha(150 * fade)))
            nvgStrokeWidth(vg, 2)
            nvgStroke(vg)

        elseif e.type == "blood_pool" then
            local radius = (e.radius or 24) * (0.45 + SkillSmoothStep(age) * 0.55)
            local fade = e.trail and (1 - age) * 0.62 or (1 - age * 0.55)
            nvgSave(vg)
            nvgTranslate(vg, e.x, e.y)
            nvgScale(vg, 1, 0.42)
            nvgBeginPath(vg)
            nvgCircle(vg, 0, 0, radius)
            local pool = nvgRadialGradient(vg, 0, 0, radius * 0.18, radius,
                nvgRGBA(125, 6, 20, SkillEffectAlpha(165 * fade)),
                nvgRGBA(40, 0, 12, 0))
            nvgFillPaint(vg, pool)
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgCircle(vg, 0, 0, radius * 0.72)
            nvgStrokeColor(vg, nvgRGBA(225, 34, 52, SkillEffectAlpha(105 * fade)))
            nvgStrokeWidth(vg, 2)
            nvgStroke(vg)
            nvgRestore(vg)

        elseif e.type == "boss_death" then
            local c = e.color or {205, 92, 255}
            local fade = 1 - age
            local radius = (e.radius or 78) * (0.22 + SkillSmoothStep(age) * 1.12)
            DrawSkillGlow(vg, e.x, e.y, radius * 1.34, c, 125 * fade)
            for ring = 1, 3 do
                nvgBeginPath(vg)
                nvgCircle(vg, e.x, e.y, radius * (0.38 + ring * 0.21))
                nvgStrokeColor(vg, nvgRGBA(
                    ring == 2 and 255 or c[1],
                    ring == 2 and 82 or c[2],
                    ring == 2 and 118 or c[3],
                    SkillEffectAlpha((225 - ring * 35) * fade)))
                nvgStrokeWidth(vg, ring == 1 and 5 or 2)
                nvgStroke(vg)
            end
            DrawSkillBurst(vg, e.x, e.y, radius * 1.22, {245, 165, 255}, 225 * fade, 12, time * 0.36)
            DrawSkillCracks(vg, e.x, e.y, radius * 0.82, {255, 85, 145}, 170 * fade, 9, time * 0.02)

        elseif e.type == "monster_shot" then
            local c = {105, 210, 255}
            local reveal = SkillSmoothStep(age)
            local x2 = e.x1 + (e.x2 - e.x1) * reveal
            local y2 = e.y1 + (e.y2 - e.y1) * reveal
            nvgBeginPath(vg)
            nvgMoveTo(vg, e.x1, e.y1)
            nvgLineTo(vg, x2, y2)
            nvgStrokeColor(vg, nvgRGBA(c[1], c[2], c[3], SkillEffectAlpha(220 * t)))
            nvgStrokeWidth(vg, 5 - age * 3)
            nvgStroke(vg)
            DrawSkillGlow(vg, x2, y2, 16 + age * 8, c, 92 * t)

        elseif e.type == "elite_charge" then
            local radius = (e.radius or 34) * (0.58 + SkillSmoothStep(age) * 0.76)
            local fade = 1 - age
            DrawSkillGlow(vg, e.x, e.y, radius * 1.22, {255, 115, 30}, 92 * fade)
            for ring = 1, 2 do
                nvgBeginPath(vg)
                nvgCircle(vg, e.x, e.y, radius * (ring == 1 and 1 or 0.62))
                nvgStrokeColor(vg, nvgRGBA(255, ring == 1 and 105 or 205, 40, SkillEffectAlpha(210 * fade)))
                nvgStrokeWidth(vg, ring == 1 and 3 or 1)
                nvgStroke(vg)
            end
            DrawSkillBurst(vg, e.x, e.y, radius, {255, 205, 90}, 165 * fade, 6, time * 0.4)

        elseif e.type == "heal" then
            local lift = SkillSmoothStep(age) * 38
            local form = SkillSmoothStep(math.min(1, age / 0.24))
            local ringRadius = 18 + form * 42
            DrawSkillGlow(vg, e.x, e.y, 68, {60, 255, 155}, alpha * 0.24)
            for ring = 1, 2 do
                nvgBeginPath(vg)
                nvgCircle(vg, e.x, e.y, ringRadius * (ring == 1 and 1 or 0.62))
                nvgStrokeWidth(vg, ring == 1 and 2 or 1)
                nvgStrokeColor(vg, nvgRGBA(95, 255, 165, SkillEffectAlpha(alpha * (ring == 1 and 0.52 or 0.32))))
                nvgStroke(vg)
            end
            local crossSize = 9 + math.sin(time * 5.5) * 1.5
            nvgBeginPath(vg)
            nvgRect(vg, e.x - 2.5, e.y - crossSize, 5, crossSize * 2)
            nvgRect(vg, e.x - crossSize, e.y - 2.5, crossSize * 2, 5)
            nvgFillColor(vg, nvgRGBA(215, 255, 225, SkillEffectAlpha(alpha * 0.72)))
            nvgFill(vg)
            for i = 1, 7 do
                local particleAge = (age + i * 0.12) % 1
                local a = i * 2.399 + particleAge * math.pi * 1.3
                local rr = 14 + particleAge * 30
                local x = e.x + math.cos(a) * rr
                local y = e.y + math.sin(a) * rr * 0.42 - particleAge * 38
                nvgBeginPath(vg)
                nvgCircle(vg, x, y, 2 + (i % 3))
                nvgFillColor(vg, nvgRGBA(i % 2 == 0 and 245 or 80, 255,
                    i % 2 == 0 and 190 or 135, SkillEffectAlpha(alpha * (1 - particleAge) * 0.72)))
                nvgFill(vg)
            end
            nvgFontFace(vg, "pixel")
            nvgFontSize(vg, 18)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(110, 255, 160, alpha))
            nvgText(vg, e.x, e.y - 30 - lift, e.text or "+", nil)

        elseif e.type == "freeze" then
            local baseRadius = e.radius or 80
            local form = SkillSmoothStep(math.min(1, age / 0.18))
            local burstFade = math.max(0, 1 - age)
            local radius = baseRadius * (0.24 + form * 0.86)
            local freezeAlpha = SkillEffectAlpha(210 * burstFade)
            DrawSkillGlow(vg, e.x, e.y, radius * 1.08, {40, 145, 255}, 72 * burstFade)
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius)
            local iceFill = nvgRadialGradient(vg, e.x, e.y, radius * 0.08, radius,
                nvgRGBA(185, 245, 255, SkillEffectAlpha(82 * burstFade)),
                nvgRGBA(20, 80, 155, SkillEffectAlpha(18 * burstFade)))
            nvgFillPaint(vg, iceFill)
            nvgFill(vg)
            for ring = 1, 3 do
                local ringProgress = math.max(0, math.min(1, age * 1.35 - (ring - 1) * 0.10))
                local ringRadius = baseRadius * (0.18 + SkillSmoothStep(ringProgress) * (0.66 + ring * 0.10))
                nvgBeginPath(vg)
                nvgCircle(vg, e.x, e.y, ringRadius)
                nvgStrokeWidth(vg, math.max(1, 4 - ring))
                nvgStrokeColor(vg, nvgRGBA(140, 230, 255,
                    SkillEffectAlpha(freezeAlpha * (0.82 - ring * 0.14))))
                nvgStroke(vg)
            end
            DrawSkillCracks(vg, e.x, e.y, radius * 0.82, {205, 250, 255}, freezeAlpha * 0.78, 10,
                age * 0.18)
            for i = 1, 10 do
                local a = i * math.pi * 2 / 10 + age * 0.28
                local shardDistance = radius * (0.32 + (i % 3) * 0.24)
                local x = e.x + math.cos(a) * shardDistance
                local y = e.y + math.sin(a) * shardDistance
                nvgSave(vg)
                nvgTranslate(vg, x, y)
                nvgRotate(vg, a)
                nvgBeginPath(vg)
                nvgMoveTo(vg, -3, 5)
                nvgLineTo(vg, 0, -10 - (i % 2) * 6)
                nvgLineTo(vg, 4, 5)
                nvgClosePath(vg)
                nvgFillColor(vg, nvgRGBA(205, 250, 255,
                    SkillEffectAlpha(freezeAlpha * (0.72 + (i % 2) * 0.18))))
                nvgFill(vg)
                nvgRestore(vg)
            end

        elseif e.type == "meteor" then
            local radius = e.radius or 90
            local fallAge = SkillSmoothStep(math.min(1, age / 0.48))
            local impactAge = math.max(0, math.min(1, (age - 0.36) / 0.64))
            local startX = e.x - 118
            local startY = e.y - 185
            local meteorX = startX + (e.x - startX) * fallAge
            local meteorY = startY + (e.y - startY) * fallAge
            local trailAlpha = SkillEffectAlpha(230 * math.max(0, 1 - impactAge))
            if fallAge < 1 then
                for i = 1, 5 do
                    local back = i * 0.075
                    local p = math.max(0, fallAge - back)
                    local tx = startX + (e.x - startX) * p
                    local ty = startY + (e.y - startY) * p
                    DrawSkillGlow(vg, tx, ty, math.max(8, 31 - i * 4),
                        i % 2 == 0 and {145, 45, 255} or {255, 85, 25},
                        trailAlpha * math.max(0.05, 0.30 - i * 0.045))
                end
                nvgStrokeWidth(vg, 14)
                nvgStrokeColor(vg, nvgRGBA(120, 35, 255, SkillEffectAlpha(trailAlpha * 0.22)))
                nvgBeginPath(vg)
                nvgMoveTo(vg, startX, startY)
                nvgLineTo(vg, meteorX, meteorY)
                nvgStroke(vg)
                nvgStrokeWidth(vg, 5)
                nvgStrokeColor(vg, nvgRGBA(255, 95, 28, SkillEffectAlpha(trailAlpha * 0.90)))
                DrawJaggedLine(vg, startX, startY, meteorX, meteorY, 6, 9, time)
                nvgStroke(vg)
                DrawSkillGlow(vg, meteorX, meteorY, 34 + math.sin(time * 12) * 3, {255, 95, 25}, trailAlpha * 0.52)
                nvgBeginPath(vg)
                nvgCircle(vg, meteorX, meteorY, 11)
                local meteorFill = nvgRadialGradient(vg, meteorX, meteorY, 1, 13,
                    nvgRGBA(255, 245, 175, trailAlpha),
                    nvgRGBA(125, 35, 20, SkillEffectAlpha(trailAlpha * 0.55)))
                nvgFillPaint(vg, meteorFill)
                nvgFill(vg)
            end
            if impactAge > 0 then
                local impactFade = 1 - impactAge
                local blast = radius * (0.28 + SkillSmoothStep(impactAge) * 1.04)
                DrawSkillGlow(vg, e.x, e.y, blast * 1.12, {255, 75, 25}, 110 * impactFade)
                DrawSkillGlow(vg, e.x, e.y, blast * 0.66, {155, 45, 255}, 85 * impactFade)
                for ring = 1, 2 do
                    nvgBeginPath(vg)
                    nvgCircle(vg, e.x, e.y, blast * (ring == 1 and 1 or 0.64))
                    nvgStrokeWidth(vg, ring == 1 and 5 or 2)
                    nvgStrokeColor(vg, nvgRGBA(ring == 1 and 255 or 175, ring == 1 and 115 or 65,
                        ring == 1 and 40 or 255, SkillEffectAlpha(210 * impactFade)))
                    nvgStroke(vg)
                end
                DrawSkillCracks(vg, e.x, e.y, math.min(radius, blast * 0.92), {255, 165, 75},
                    175 * impactFade, 7, time * 0.03)
                DrawSkillBurst(vg, e.x, e.y, blast * 1.08, {255, 195, 105}, 185 * impactFade, 7,
                    time * 0.28)
                for i = 1, 5 do
                    local a = i * 2.399
                    local debrisProgress = math.min(1, impactAge * (1.05 + i * 0.03))
                    local rr = blast * (0.35 + (i % 3) * 0.18)
                    local rockX = e.x + math.cos(a) * rr
                    local rockY = e.y + math.sin(a) * rr * 0.58 - math.sin(debrisProgress * math.pi) * (16 + i * 2)
                    nvgBeginPath(vg)
                    nvgRect(vg, rockX - 2, rockY - 2, 4 + (i % 2) * 2, 4 + (i % 2) * 2)
                    nvgFillColor(vg, nvgRGBA(155, 75, 45, SkillEffectAlpha(180 * impactFade)))
                    nvgFill(vg)
                end
            end

        elseif e.type == "blackhole" then
            local baseRadius = e.radius or 110
            local form = SkillSmoothStep(math.min(1, age / 0.12))
            local collapse = age > 0.86 and math.max(0, (1 - age) / 0.14) or 1
            local radius = baseRadius * (0.20 + form * collapse * 0.80)
            local holeAlpha = SkillEffectAlpha(230 * math.min(form, collapse))
            local spin = time * 5.6 + age * 4.0
            DrawSkillGlow(vg, e.x, e.y, radius * 1.18, {120, 35, 255}, holeAlpha * 0.34)
            DrawSkillGlow(vg, e.x, e.y, radius * 0.72, {20, 5, 35}, holeAlpha * 0.62)
            for ring = 1, 3 do
                local rr = radius * (0.28 + ring * 0.19) * (0.96 + math.sin(time * 2 + ring) * 0.04)
                local startA = spin * (ring % 2 == 0 and -0.55 or 0.72) + ring
                nvgBeginPath(vg)
                for segment = 0, 10 do
                    local p = segment / 10
                    local a = startA + p * math.pi * (1.20 + ring * 0.18)
                    local spiralR = rr * (0.72 + p * 0.28)
                    local x = e.x + math.cos(a) * spiralR
                    local y = e.y + math.sin(a) * spiralR * 0.72
                    if segment == 0 then nvgMoveTo(vg, x, y) else nvgLineTo(vg, x, y) end
                end
                nvgStrokeWidth(vg, ring == 1 and 3 or 2)
                nvgStrokeColor(vg, nvgRGBA(145 + ring * 25, 45 + ring * 8, 255,
                    SkillEffectAlpha(holeAlpha * (0.30 - ring * 0.045))))
                nvgStroke(vg)
            end
            for i = 1, 8 do
                local phase = (time * (0.36 + i * 0.015) + i * 0.12) % 1
                local inward = 1 - phase
                local a = spin * 0.26 + i * 2.399 + phase * 1.8
                local rr = radius * (0.20 + inward * 0.78)
                local x = e.x + math.cos(a) * rr
                local y = e.y + math.sin(a) * rr * 0.72
                nvgBeginPath(vg)
                nvgCircle(vg, x, y, 1.5 + inward * 2.2)
                nvgFillColor(vg, nvgRGBA(210, 135, 255, SkillEffectAlpha(holeAlpha * phase * 0.48)))
                nvgFill(vg)
            end
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius * 0.20)
            local coreFill = nvgRadialGradient(vg, e.x, e.y, 1, radius * 0.20,
                nvgRGBA(225, 190, 255, SkillEffectAlpha(holeAlpha * 0.38)),
                nvgRGBA(2, 0, 9, SkillEffectAlpha(holeAlpha)))
            nvgFillPaint(vg, coreFill)
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius * 0.075)
            nvgFillColor(vg, nvgRGBA(3, 0, 10, SkillEffectAlpha(holeAlpha)))
            nvgFill(vg)

        elseif e.type == "awakening" then
            local pulse = 1.0 + 0.08 * math.sin(time * 10)
            local radius = e.radius * 1.15 * pulse
            DrawSkillGlow(vg, e.x, e.y, radius * 1.18, {255, 200, 60}, 28 * t)
            DrawSkillGlow(vg, e.x, e.y, radius * 0.78, {180, 70, 255}, 20 * t)
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius)
            nvgFillColor(vg, nvgRGBA(255, 225, 90, math.floor(34 * t)))
            nvgFill(vg)
            nvgBeginPath(vg)
            nvgCircle(vg, e.x, e.y, radius * 0.82)
            nvgStrokeWidth(vg, 2)
            nvgStrokeColor(vg, nvgRGBA(255, 210, 80, math.floor(120 * t)))
            nvgStroke(vg)
            for i = 1, 6 do
                local a = time * 1.2 + i * math.pi / 3
                nvgBeginPath(vg)
                nvgMoveTo(vg, e.x + math.cos(a) * radius * 0.24, e.y + math.sin(a) * radius * 0.24)
                nvgLineTo(vg, e.x + math.cos(a) * radius * 0.76, e.y + math.sin(a) * radius * 0.76)
                nvgStrokeWidth(vg, 1)
                nvgStrokeColor(vg, nvgRGBA(255, 245, 170, math.floor(88 * t)))
                nvgStroke(vg)
            end

        elseif e.type == "gold_drop" then
            nvgFontFace(vg, "pixel")
            nvgFontSize(vg, 15)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            local y = e.y - (1 - t) * 48
            DrawSkillGlow(vg, e.x, y, 34 + (1 - t) * 18, {255, 210, 70}, alpha * 0.28)
            for i = 1, 5 do
                local a = time * 2.2 + i * math.pi * 0.4
                local rr = 10 + i * 2 + (1 - t) * 12
                nvgBeginPath(vg)
                nvgCircle(vg, e.x + math.cos(a) * rr, y + math.sin(a) * rr * 0.45, 2.5)
                nvgFillColor(vg, nvgRGBA(255, 220, 80, math.floor(alpha * 0.75)))
                nvgFill(vg)
            end
            nvgFillColor(vg, nvgRGBA(95, 54, 12, alpha))
            nvgText(vg, e.x + 1, y + 2, e.text, nil)
            nvgFillColor(vg, nvgRGBA(255, 224, 92, alpha))
            nvgText(vg, e.x, y, e.text, nil)
        elseif e.type == "drop" then
            nvgFontFace(vg, "pixel")
            nvgFontSize(vg, 13)
            nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(120, 220, 255, alpha))
            nvgText(vg, e.x, e.y - (1 - t) * 42, e.text, nil)
        end
        end
    end
end

function DrawParticlesFx(vg)
    for index, p in ipairs(particles) do
        if ShouldDrawFastMultiVisual(index) then
            local alpha = (p.life / p.maxLife) * 255
            local s = p.size * (p.life / p.maxLife)
            nvgBeginPath(vg)
            nvgRect(vg, p.x - s/2, p.y - s/2, s, s)
            nvgFillColor(vg, nvgRGBA(p.color[1], p.color[2], p.color[3], alpha))
            nvgFill(vg)
        end
    end
end

function FormatDamageValue(value)
    value = math.max(0, math.floor(value or 0))
    if value >= 1000000 then
        return string.format("%.1fM", value / 1000000)
    elseif value >= 10000 then
        return string.format("%.1fW", value / 10000)
    end
    return tostring(value)
end

function BuildDamageRankRows()
    local now = GetTime():GetElapsedTime()
    if damageRankRowsCacheTime ~= nil
        and now - damageRankRowsCacheTime < 0.25
        and damageRankRowsCache ~= nil
        and #damageRankRowsCache > 0 then
        return damageRankRowsCache
    end
    local rows = {
        { label = "主角", value = damageStats and damageStats.hero or 0, color = {255, 230, 120, 255} },
        { label = "分身", value = damageStats and damageStats.clone or 0, color = {150, 200, 255, 255} },
    }
    local skills = damageStats and damageStats.skills or {}
    local added = {}
    for _, skill in ipairs(GetEquippedSkills and GetEquippedSkills() or {}) do
        local skillId = skill.id
        if skillId ~= nil and not added[skillId] then
            added[skillId] = true
            table.insert(rows, {
                label = skill.name or (SKILL_DEFS[skillId] and SKILL_DEFS[skillId].name) or skillId,
                value = skills[skillId] or 0,
                color = {180, 220, 255, 245},
            })
        end
    end
    for _, skillId in ipairs(SKILL_ORDER or {}) do
        local value = skills[skillId] or 0
        if value > 0 and not added[skillId] then
            local def = SKILL_DEFS[skillId]
            table.insert(rows, {
                label = def and def.name or skillId,
                value = value,
                color = {180, 220, 255, 245},
            })
        end
    end
    table.sort(rows, function(a, b) return (a.value or 0) > (b.value or 0) end)
    damageRankRowsCache = rows
    damageRankRowsCacheTime = now
    return rows
end

function BuildCompactSynergyRows()
    local selectedIds = battleSynergyRuntime
        and battleSynergyRuntime.selectedIds
        or {}
    local rows = {}
    local enabledCount = 0
    for _, synergyId in ipairs(selectedIds) do
        local def = GetSkillSynergyDef(synergyId)
        local runtime = battleSynergyRuntime.byId
            and battleSynergyRuntime.byId[synergyId]
            or nil
        local stateText = "缺技能"
        local color = { 145, 145, 165, 235 }
        if runtime and runtime.enabled then
            enabledCount = enabledCount + 1
            if (runtime.cooldownRemaining or 0) > 0 then
                stateText = string.format("%.0f秒", runtime.cooldownRemaining)
                color = { 255, 170, 85, 245 }
            elseif (runtime.windowRemaining or 0) > 0 then
                stateText = "等待连携"
                color = { 255, 225, 100, 245 }
            else
                stateText = "就绪"
                color = { 120, 235, 145, 245 }
            end
        end
        table.insert(rows, {
            label = def and def.name or synergyId,
            stateText = stateText,
            color = color,
        })
    end
    return rows, enabledCount, #selectedIds
end

function GetDamageRankHUDHeight()
    if not damageRankExpanded then return 14 end
    local rows = BuildDamageRankRows()
    local synergyRows = BuildCompactSynergyRows()
    return 24 + 14 + #synergyRows * 14 + 3 + math.min(#rows, 7) * 15 + 6
end

function DrawDamageRankHUD(vg, x, y)
    local rows = damageRankExpanded and BuildDamageRankRows() or damageRankRowsCache or {}
    local synergyRows, enabledCount, synergyTotal = BuildCompactSynergyRows()
    local collapsedH = 14
    local collapsedW = 154
    local panelW = damageRankExpanded and 184 or collapsedW
    local synergyRowH = 14
    local damageRowH = 15
    local maxRows = math.min(#rows, 7)
    local panelH = damageRankExpanded
        and (24 + 14 + #synergyRows * synergyRowH + 3 + maxRows * damageRowH + 6)
        or collapsedH

    nvgFontFace(vg, "pixel")
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 9)
    nvgFillColor(vg, nvgRGBA(255, 230, 120, 230))
    local total = damageStats and damageStats.total or 0
    local title = damageRankExpanded
        and "伤害排行 ▲"
        or ("伤害 " .. FormatDamageValue(total) .. " ▼  联携 "
            .. tostring(enabledCount) .. "/" .. tostring(synergyTotal))

    if damageRankExpanded then
        nvgBeginPath(vg)
        nvgRect(vg, x, y, panelW, panelH)
        nvgFillColor(vg, nvgRGBA(10, 10, 20, 220))
        nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(210, 170, 50, 180))
        nvgStrokeWidth(vg, 1)
        nvgStroke(vg)

        nvgFontSize(vg, 10)
        nvgFillColor(vg, nvgRGBA(255, 230, 120, 235))
        nvgText(vg, x + 6, y + 12, title, nil)

        local synergyHeaderY = y + 30
        nvgFontSize(vg, 8)
        nvgFillColor(vg, nvgRGBA(145, 210, 255, 245))
        nvgText(vg, x + 7, synergyHeaderY, "联携 " .. enabledCount .. "/" .. synergyTotal, nil)

        local cursorY = y + 38
        for _, row in ipairs(synergyRows) do
            local rowY = cursorY + synergyRowH * 0.5
            nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(215, 220, 235, 240))
            nvgText(vg, x + 8, rowY, row.label, nil)
            nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
            local c = row.color
            nvgFillColor(vg, nvgRGBA(c[1], c[2], c[3], c[4]))
            nvgText(vg, x + panelW - 8, rowY, row.stateText, nil)
            cursorY = cursorY + synergyRowH
        end

        nvgBeginPath(vg)
        nvgMoveTo(vg, x + 6, cursorY + 1)
        nvgLineTo(vg, x + panelW - 6, cursorY + 1)
        nvgStrokeColor(vg, nvgRGBA(100, 130, 170, 100))
        nvgStrokeWidth(vg, 1)
        nvgStroke(vg)
        cursorY = cursorY + 3

        for i = 1, maxRows do
            local row = rows[i]
            local rowY = cursorY + (i - 1) * damageRowH + damageRowH * 0.5
            local c = row.color or {220, 220, 235, 255}
            nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(c[1], c[2], c[3], c[4] or 255))
            nvgText(vg, x + 8, rowY, tostring(i) .. ". " .. row.label, nil)
            nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
            nvgFillColor(vg, nvgRGBA(245, 245, 245, 245))
            nvgText(vg, x + panelW - 8, rowY, FormatDamageValue(row.value), nil)
        end
        damageRankRect = { x = x - 6, y = y - 6, w = panelW + 12, h = 30 }
    else
        nvgText(vg, x, y + collapsedH * 0.5, title, nil)
        damageRankRect = { x = x - 6, y = y - 6, w = collapsedW + 12, h = collapsedH + 12 }
    end
end

function DrawRunSkillSynergyHUD(vg, x, y)
    local selectedIds = battleSynergyRuntime
        and battleSynergyRuntime.selectedIds
        or {}
    if #selectedIds <= 0 then return end

    local panelW = 158
    local rowH = 16
    local panelH = 20 + #selectedIds * rowH
    nvgBeginPath(vg)
    nvgRect(vg, x, y, panelW, panelH)
    nvgFillColor(vg, nvgRGBA(10, 10, 20, 190))
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(120, 190, 235, 130))
    nvgStrokeWidth(vg, 1)
    nvgStroke(vg)

    nvgFontFace(vg, "pixel")
    nvgFontSize(vg, 9)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(150, 215, 255, 245))
    nvgText(vg, x + 6, y + 10, "本局联携", nil)

    for index, synergyId in ipairs(selectedIds) do
        local def = GetSkillSynergyDef(synergyId)
        local runtime = battleSynergyRuntime.byId
            and battleSynergyRuntime.byId[synergyId]
            or nil
        local stateText = "未激活"
        local color = { 150, 150, 170, 230 }
        if runtime and runtime.enabled then
            if (runtime.cooldownRemaining or 0) > 0 then
                stateText = string.format("冷却%.1f", runtime.cooldownRemaining)
                color = { 255, 175, 90, 240 }
            elseif (runtime.windowRemaining or 0) > 0 then
                stateText = string.format("窗口%.1f", runtime.windowRemaining)
                color = { 255, 225, 100, 245 }
            else
                stateText = "就绪"
                color = { 125, 235, 145, 245 }
            end
        end
        local rowY = y + 20 + (index - 1) * rowH + rowH * 0.5
        nvgFontSize(vg, 8)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(220, 220, 235, 240))
        nvgText(vg, x + 6, rowY, def and def.name or synergyId, nil)
        nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(color[1], color[2], color[3], color[4]))
        nvgText(vg, x + panelW - 6, rowY, stateText, nil)
    end
end

function DrawHUD(vg)
    local si = safeInset or { left = 0, top = 0, right = 0, bottom = 0 }
    local pad = 8

    nvgFontFace(vg, "pixel")

    local leftX = si.left + pad
    local leftY = si.top + pad
    nvgFontSize(vg, 11)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)

    local rowH = 22
    local rowY = leftY + rowH * 0.5
    local cx = leftX

    nvgFillColor(vg, nvgRGBA(170, 170, 195, 220))
    local floorText = IsTrainingDummyMode and IsTrainingDummyMode()
        and (IsTrainingDummyBossTarget() and "Boss木桩" or "普通木桩")
        or (equipmentRiftActive
            and ("秘境·难度" .. tostring(equipmentRiftDifficulty))
            or (trainingModeActive
                and ("训练场·层" .. tostring(trainingFloor))
                or (endlessTrialActive
                    and ("无尽·层" .. tostring(runFloor))
                    or (fiveBattleActive and (tostring(fiveBattleFloorCount or 5) .. "连" .. tostring(fiveBattleStartFloor) .. "-" .. tostring(fiveBattleEndFloor)) or ("层" .. runFloor)))))
    nvgText(vg, cx, rowY, floorText)
    cx = cx + #floorText * 6 + 10

    nvgFillColor(vg, nvgRGBA(170, 170, 195, 220))
    local progressText = nil
    if IsTrainingDummyMode and IsTrainingDummyMode() then
        progressText = string.format("%.1fs", trainingElapsedTime or 0)
    elseif fiveBattleActive and floorSpawnIndex > #floorSpawnPlan then
        progressText = "Boss " .. tostring(floorBossDefeatedCount) .. "/" .. tostring(floorBossCount)
    else
        progressText = floorKillCount .. "/" .. floorKillTarget
    end
    nvgText(vg, cx, rowY, progressText)
    cx = cx + #progressText * 6 + 10
    local leftPanelW = cx - leftX + 10

    nvgBeginPath(vg)
    nvgRect(vg, leftX, leftY, leftPanelW, rowH)
    nvgFillColor(vg, nvgRGBA(10, 10, 20, 180))
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(210, 170, 50, 100))
    nvgStrokeWidth(vg, 1)
    nvgStroke(vg)

    cx = leftX
    rowY = leftY + rowH * 0.5
    nvgFillColor(vg, nvgRGBA(170, 170, 195, 220))
    nvgText(vg, cx, rowY, floorText)
    cx = cx + #floorText * 6 + 10
    nvgFillColor(vg, nvgRGBA(170, 170, 195, 220))
    nvgText(vg, cx, rowY, progressText)
    cx = cx + #progressText * 6 + 10

    local awBarW = 60
    local awBarH = 6
    local awBarX = leftX + 2
    local awBarY = leftY + rowH + 5
    local awRatio = awakeningActive and math.max(0, awakeningTimer / GetAwakeningDuration()) or (awakeningEnergy / AWAKENING_MAX_ENERGY)
    nvgBeginPath(vg)
    nvgRect(vg, awBarX, awBarY, awBarW, awBarH)
    nvgFillColor(vg, nvgRGBA(40, 32, 20, 210))
    nvgFill(vg)
    nvgBeginPath(vg)
    nvgRect(vg, awBarX, awBarY, awBarW * math.max(0, math.min(1, awRatio)), awBarH)
    nvgFillColor(vg, awakeningActive and nvgRGBA(255, 210, 70, 255) or nvgRGBA(180, 90, 255, 230))
    nvgFill(vg)
    nvgFontSize(vg, 10)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(255, 230, 120, 230))
    local awText = awakeningActive and "觉醒" or ("能量" .. math.floor(awakeningEnergy))
    nvgText(vg, awBarX + awBarW + 6, awBarY + awBarH * 0.5, awText, nil)

    local rankY = awBarY + awBarH + 5
    DrawDamageRankHUD(vg, awBarX, rankY)

    if IsTrainingDummyMode and IsTrainingDummyMode() then
        local dpsPanelX = awBarX
        local dpsPanelY = rankY + GetDamageRankHUDHeight() + 8
        local dpsPanelW = 178
        local dpsPanelH = 46
        nvgBeginPath(vg)
        nvgRect(vg, dpsPanelX, dpsPanelY, dpsPanelW, dpsPanelH)
        nvgFillColor(vg, nvgRGBA(10, 10, 20, 205))
        nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(210, 170, 50, 150))
        nvgStrokeWidth(vg, 1)
        nvgStroke(vg)
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgFontSize(vg, 10)
        nvgFillColor(vg, nvgRGBA(255, 225, 120, 255))
        nvgText(vg, dpsPanelX + 7, dpsPanelY + 13,
            "平均 DPS  " .. FormatDamageValue(GetTrainingAverageDps()), nil)
        nvgFillColor(vg, nvgRGBA(150, 220, 255, 255))
        nvgText(vg, dpsPanelX + 7, dpsPanelY + 32,
            "近5秒 DPS " .. FormatDamageValue(GetTrainingRecentDps()), nil)

        local endW, endH = 86, 28
        local endX = screenW * 0.5 - endW * 0.5
        local endY = si.top + pad
        trainingEndButtonRect = { x = endX - 6, y = endY - 6, w = endW + 12, h = endH + 12 }
        nvgBeginPath(vg)
        nvgRoundedRect(vg, endX, endY, endW, endH, 3)
        nvgFillColor(vg, nvgRGBA(150, 38, 52, 245))
        nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(255, 105, 92, 245))
        nvgStrokeWidth(vg, 2)
        nvgStroke(vg)
        nvgFontSize(vg, 12)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
        nvgText(vg, endX + endW * 0.5, endY + endH * 0.5, "结束测试", nil)
    else
        trainingEndButtonRect = nil
    end
    DrawEquipmentRiftHud(vg)

    local hpRatio = math.max(0, math.min(1, base.hp / base.maxHp))
    local hpC = hpRatio > 0.5 and nvgRGBA(80, 220, 80, 255) or
                (hpRatio > 0.25 and nvgRGBA(220, 180, 50, 255) or nvgRGBA(220, 50, 50, 255))

    nvgFontSize(vg, 11)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)

    local hpStr = math.floor(hpRatio * 100) .. "%"
    local hpBarW = 60
    local hpBarH = 6
    local rightRowH = 22
    local rightX = screenW - si.right - pad
    local rightY = si.top + pad
    nvgFontSize(vg, 11)
    local hpStrW = #hpStr * 6
    local rightPanelW = 30 + hpBarW + hpStrW + 16
    local rightPanelX = rightX - rightPanelW
    nvgBeginPath(vg)
    nvgRect(vg, rightPanelX, rightY, rightPanelW, rightRowH)
    nvgFillColor(vg, nvgRGBA(10, 10, 20, 180))
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(210, 170, 50, 100))
    nvgStrokeWidth(vg, 1)
    nvgStroke(vg)
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, nvgRGBA(220, 180, 50, 220))
    nvgText(vg, rightPanelX + 6, rightY + rightRowH * 0.5, "基地", nil)
    local hpBarX = rightPanelX + 30
    local hpBarY = rightY + rightRowH * 0.5 - hpBarH * 0.5
    nvgBeginPath(vg)
    nvgRect(vg, hpBarX, hpBarY, hpBarW, hpBarH)
    nvgFillColor(vg, nvgRGBA(40, 40, 50, 200))
    nvgFill(vg)
    nvgBeginPath(vg)
    nvgRect(vg, hpBarX, hpBarY, hpBarW * hpRatio, hpBarH)
    nvgFillColor(vg, hpC)
    nvgFill(vg)
    nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, hpC)
    nvgText(vg, rightPanelX + rightPanelW - 6, rightY + rightRowH * 0.5, hpStr, nil)

    local speedBtnW = 28
    local speedBtnH = 16
    local speedBtnX = rightX - speedBtnW
    local speedBtnY = rightY + rightRowH + 4
    speedBtnRect = { x = speedBtnX - 4, y = speedBtnY - 4, w = speedBtnW + 8, h = speedBtnH + 8 }

    local isFast = (gameSpeed > 1)
    nvgBeginPath(vg)
    nvgRect(vg, speedBtnX, speedBtnY, speedBtnW, speedBtnH)
    nvgFillColor(vg, isFast and nvgRGBA(200, 40, 40, 220) or nvgRGBA(30, 30, 50, 200))
    nvgFill(vg)
    nvgStrokeColor(vg, isFast and nvgRGBA(255, 80, 80, 255) or nvgRGBA(160, 50, 50, 180))
    nvgStrokeWidth(vg, 1)
    nvgStroke(vg)

    nvgFontSize(vg, 10)
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFillColor(vg, isFast and nvgRGBA(255, 220, 80, 255) or nvgRGBA(200, 200, 220, 220))
    nvgText(vg, speedBtnX + speedBtnW * 0.5, speedBtnY + speedBtnH * 0.5, "x" .. tostring(gameSpeed), nil)

    if playerData.settings and (playerData.settings.tenSpeedUnlocked or playerData.settings.fakeTenSpeedUnlocked) then
        local tenBtnW = 28
        local tenBtnH = speedBtnH
        local tenBtnX = speedBtnX - tenBtnW - 6
        local tenBtnY = speedBtnY
        tenSpeedBtnRect = { x = tenBtnX - 4, y = tenBtnY - 4, w = tenBtnW + 8, h = tenBtnH + 8 }
        local hasReal = playerData.settings.tenSpeedUnlocked
        local isTen = hasReal and gameSpeed == 10
        local fakeFlash = (not hasReal) and os.clock() < (fakeTenBtnFlashUntil or 0)
        local highlight = isTen or fakeFlash

        nvgBeginPath(vg)
        nvgRect(vg, tenBtnX, tenBtnY, tenBtnW, tenBtnH)
        nvgFillColor(vg, highlight and nvgRGBA(200, 40, 40, 230) or nvgRGBA(35, 32, 58, 215))
        nvgFill(vg)
        nvgStrokeColor(vg, highlight and nvgRGBA(255, 90, 90, 255) or nvgRGBA(210, 170, 50, 210))
        nvgStrokeWidth(vg, 1)
        nvgStroke(vg)

        nvgFontSize(vg, 10)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, highlight and nvgRGBA(255, 230, 90, 255) or nvgRGBA(235, 205, 110, 235))
        nvgText(vg, tenBtnX + tenBtnW * 0.5, tenBtnY + tenBtnH * 0.5, "x10", nil)
    else
        tenSpeedBtnRect = { x = 0, y = 0, w = 0, h = 0 }
    end

    -- 无尽模式：顶部中央返回菜单，避免被倍速按钮挤掉
    if endlessTrialActive then
        local pauseBtnW, pauseBtnH = 86, 28
        local pauseBtnX = screenW * 0.5 - pauseBtnW * 0.5
        local pauseBtnY = si.top + pad
        endlessPauseBtnRect = {
            x = pauseBtnX - 6,
            y = pauseBtnY - 6,
            w = pauseBtnW + 12,
            h = pauseBtnH + 12,
        }
        nvgBeginPath(vg)
        nvgRoundedRect(vg, pauseBtnX, pauseBtnY, pauseBtnW, pauseBtnH, 3)
        nvgFillColor(vg, nvgRGBA(126, 32, 48, 245))
        nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(255, 105, 92, 245))
        nvgStrokeWidth(vg, 2)
        nvgStroke(vg)
        nvgFontSize(vg, 11)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
        nvgText(vg, pauseBtnX + pauseBtnW * 0.5, pauseBtnY + pauseBtnH * 0.5, "返回菜单", nil)
    else
        endlessPauseBtnRect = { x = 0, y = 0, w = 0, h = 0 }
    end

    if os.clock() < (speedQuotaNoticeUntil or 0) and speedQuotaNoticeText ~= "" then
        local noticeW = math.min(screenW - si.left - si.right - 24, 340)
        local noticeH = 34
        local noticeX = (screenW - noticeW) * 0.5
        local noticeY = si.top + 54
        nvgBeginPath(vg)
        nvgRoundedRect(vg, noticeX, noticeY, noticeW, noticeH, 4)
        nvgFillColor(vg, nvgRGBA(16, 14, 28, 235))
        nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(245, 200, 92, 220))
        nvgStrokeWidth(vg, 1)
        nvgStroke(vg)
        nvgFontSize(vg, 11)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 232, 150, 255))
        nvgText(vg, screenW * 0.5, noticeY + noticeH * 0.5, speedQuotaNoticeText, nil)
    end
end

function DrawTrainingResultPanel(vg)
    local result = trainingResult or {}
    nvgBeginPath(vg)
    nvgRect(vg, 0, 0, screenW, screenH)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 190))
    nvgFill(vg)

    local panelW = math.min(420, screenW - 36)
    local rows = result.rows or {}
    local maxRows = math.min(6, #rows)
    local panelH = math.min(screenH - 34, 250 + maxRows * 24)
    local panelX = (screenW - panelW) * 0.5
    local panelY = (screenH - panelH) * 0.5
    nvgBeginPath(vg)
    nvgRect(vg, panelX, panelY, panelW, panelH)
    local fill = nvgLinearGradient(vg, panelX, panelY, panelX, panelY + panelH,
        nvgRGBA(30, 20, 48, 252), nvgRGBA(12, 12, 24, 252))
    nvgFillPaint(vg, fill)
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(235, 185, 76, 245))
    nvgStrokeWidth(vg, 2)
    nvgStroke(vg)

    local isDummyResult = result.mode == "dummy"
    nvgFontFace(vg, "pixel")
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 24)
    nvgFillColor(vg, result.cleared and nvgRGBA(255, 220, 100, 255) or nvgRGBA(255, 105, 92, 255))
    nvgText(vg, screenW * 0.5, panelY + 34,
        isDummyResult and "木桩测试完成" or (result.cleared and "训练完成" or "训练失败"), nil)
    nvgFontSize(vg, 12)
    nvgFillColor(vg, nvgRGBA(180, 180, 205, 240))
    local resultSubtitle = isDummyResult
        and ((result.dummyTargetKind == "boss" and "Boss木桩" or "普通木桩") .. " · 不影响正式进度")
        or ("第" .. tostring(result.floor or 1) .. "层 · 不影响正式进度")
    nvgText(vg, screenW * 0.5, panelY + 58, resultSubtitle, nil)

    local statY = panelY + 80
    local statW = (panelW - 48) / 3
    local stats = {
        { "总伤害", FormatDamageValue(result.totalDamage or 0) },
        { "平均DPS", FormatDamageValue(result.dps or 0) },
        isDummyResult
            and { "测试时长", string.format("%.1fs", result.elapsed or 0) }
            or { "用时/击杀", string.format("%.1fs / %d", result.elapsed or 0, result.kills or 0) },
    }
    for i, item in ipairs(stats) do
        local x = panelX + 12 + (i - 1) * (statW + 6)
        nvgBeginPath(vg)
        nvgRect(vg, x, statY, statW, 54)
        nvgFillColor(vg, nvgRGBA(18, 18, 34, 235))
        nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(180, 135, 55, 150))
        nvgStrokeWidth(vg, 1)
        nvgStroke(vg)
        nvgFontSize(vg, 9)
        nvgFillColor(vg, nvgRGBA(155, 155, 182, 245))
        nvgText(vg, x + statW * 0.5, statY + 15, item[1], nil)
        nvgFontSize(vg, 13)
        nvgFillColor(vg, nvgRGBA(255, 225, 120, 255))
        nvgText(vg, x + statW * 0.5, statY + 38, item[2], nil)
    end

    local rankY = statY + 68
    nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 11)
    nvgFillColor(vg, nvgRGBA(255, 220, 110, 250))
    nvgText(vg, panelX + 18, rankY, "伤害构成", nil)
    local total = math.max(1, result.totalDamage or 0)
    for i = 1, maxRows do
        local row = rows[i]
        local y = rankY + i * 23
        local percent = (row.value or 0) * 100 / total
        nvgFontSize(vg, 10)
        nvgFillColor(vg, nvgRGBA(220, 220, 235, 245))
        nvgTextAlign(vg, NVG_ALIGN_LEFT + NVG_ALIGN_MIDDLE)
        nvgText(vg, panelX + 22, y, tostring(i) .. ". " .. tostring(row.label), nil)
        nvgTextAlign(vg, NVG_ALIGN_RIGHT + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 225, 120, 255))
        nvgText(vg, panelX + panelW - 22, y,
            FormatDamageValue(row.value) .. string.format("  %.1f%%", percent), nil)
    end

    local buttonY = panelY + panelH - 40
    local buttonGap = 8
    local buttonW = (panelW - 40 - buttonGap * 2) / 3
    trainingResultButtonRects = {}
    local buttons = { "再测一次", isDummyResult and "更换模式" or "更换层数", "返回主界面" }
    for i, label in ipairs(buttons) do
        local x = panelX + 12 + (i - 1) * (buttonW + buttonGap)
        trainingResultButtonRects[i] = { x = x, y = buttonY, w = buttonW, h = 28 }
        nvgBeginPath(vg)
        nvgRect(vg, x, buttonY, buttonW, 28)
        nvgFillColor(vg, i == 1 and nvgRGBA(140, 38, 52, 245) or nvgRGBA(52, 36, 72, 245))
        nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(220, 170, 70, 220))
        nvgStrokeWidth(vg, 1)
        nvgStroke(vg)
        nvgFontSize(vg, 9)
        nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
        nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
        nvgText(vg, x + buttonW * 0.5, buttonY + 14, label, nil)
    end
end

function DrawGameOverPanel(vg)
    nvgBeginPath(vg)
    nvgRect(vg, 0, 0, screenW, screenH)
    nvgFillColor(vg, nvgRGBA(0, 0, 0, 178))
    nvgFill(vg)

    local panelW = math.min(340, screenW - 42)
    local panelH = 276
    local panelX = (screenW - panelW) / 2
    local panelY = (screenH - panelH) / 2

    nvgBeginPath(vg)
    nvgRoundedRect(vg, panelX - 8, panelY - 8, panelW + 16, panelH + 16, 4)
    local glow = nvgBoxGradient(vg, panelX, panelY, panelW, panelH, 3, 28,
        nvgRGBA(220, 50, 50, 110),
        nvgRGBA(220, 50, 50, 0))
    nvgFillPaint(vg, glow)
    nvgFill(vg)

    nvgBeginPath(vg)
    nvgRect(vg, panelX, panelY, panelW, panelH)
    local panelFill = nvgLinearGradient(vg, panelX, panelY, panelX, panelY + panelH,
        nvgRGBA(24, 20, 34, 248),
        nvgRGBA(12, 12, 22, 248))
    nvgFillPaint(vg, panelFill)
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(210, 170, 50, 230))
    nvgStrokeWidth(vg, 2)
    nvgStroke(vg)

    nvgBeginPath(vg)
    nvgRect(vg, panelX + 10, panelY + 10, panelW - 20, 1)
    nvgRect(vg, panelX + 10, panelY + panelH - 11, panelW - 20, 1)
    nvgFillColor(vg, nvgRGBA(210, 170, 50, 120))
    nvgFill(vg)

    nvgFontFace(vg, "pixel")
    nvgTextAlign(vg, NVG_ALIGN_CENTER + NVG_ALIGN_MIDDLE)
    nvgFontSize(vg, 31)
    nvgFillColor(vg, nvgRGBA(255, 72, 72, 255))
    nvgText(vg, screenW/2, panelY + 48,
        endlessResultFloor > 0 and "无尽挑战结束" or "基地沦陷", nil)

    nvgFontSize(vg, 15)
    nvgFillColor(vg, nvgRGBA(170, 170, 195, 220))
    local resultSubtitle = "大剑仍在，下一次守住它"
    local endlessResetNotice = nil
    if endlessResultFloor >= (CONFIG.EndlessStartFloor or 600) then
        resultSubtitle = "无尽第" .. tostring(endlessResultFloor) .. "层"
        endlessResetNotice = "本轮肉鸽属性已清空，需从第1层重新爬塔积攒"
    elseif endlessResultFloor > 0 then
        resultSubtitle = "普通第" .. tostring(CONFIG.NormalFloorCap or 600) .. "层"
    end
    nvgText(vg, screenW/2, panelY + 80, resultSubtitle, nil)
    if endlessResetNotice ~= nil then
        nvgFontSize(vg, 10)
        nvgFillColor(vg, nvgRGBA(255, 125, 125, 235))
        nvgText(vg, screenW/2, panelY + 97, endlessResetNotice, nil)
    end

    local statY = panelY + 112
    local statW = (panelW - 44) / 3
    local labels = {
        { "分数", tostring(score), {240, 240, 240, 255} },
        { "最高", tostring(playerData.highScore), PX.textGold },
        { "击杀", tostring(killCount), {240, 240, 240, 255} },
    }
    for i, item in ipairs(labels) do
        local x = panelX + 14 + (i - 1) * (statW + 8)
        nvgBeginPath(vg)
        nvgRect(vg, x, statY, statW, 58)
        nvgFillColor(vg, nvgRGBA(12, 12, 22, 210))
        nvgFill(vg)
        nvgStrokeColor(vg, nvgRGBA(210, 170, 50, 120))
        nvgStrokeWidth(vg, 1)
        nvgStroke(vg)
        nvgFontSize(vg, 11)
        nvgFillColor(vg, nvgRGBA(150, 150, 172, 230))
        nvgText(vg, x + statW/2, statY + 16, item[1], nil)
        nvgFontSize(vg, 20)
        local c = item[3]
        nvgFillColor(vg, nvgRGBA(c[1], c[2], c[3], c[4] or 255))
        nvgText(vg, x + statW/2, statY + 40, item[2], nil)
    end

    nvgFontSize(vg, 12)
    nvgFillColor(vg, nvgRGBA(255, 205, 95, 245))
    nvgText(vg, screenW/2, panelY + panelH - 88, "金币损失 " .. tostring(lastDeathGoldLoss or 0) .. "  获得 " .. tostring(lastDeathGoldReward or 0), nil)
    nvgFontSize(vg, 11)
    nvgFillColor(vg, nvgRGBA(255, 205, 95, 245))
    nvgText(vg, screenW/2, panelY + panelH - 68, "转生石 +" .. tostring(lastDeathRebirthStoneReward or 0), nil)
    nvgFontSize(vg, 10)
    nvgFillColor(vg, nvgRGBA(255, 125, 125, 235))
    nvgText(vg, screenW/2, panelY + panelH - 52, tostring(lastDeathSkillLossText or ""), nil)

    nvgBeginPath(vg)
    nvgRect(vg, panelX + 48, panelY + panelH - 34, panelW - 96, 26)
    nvgFillColor(vg, nvgRGBA(200, 40, 40, 235))
    nvgFill(vg)
    nvgStrokeColor(vg, nvgRGBA(255, 95, 95, 230))
    nvgStrokeWidth(vg, 1)
    nvgStroke(vg)
    nvgFontSize(vg, 14)
    nvgFillColor(vg, nvgRGBA(255, 255, 255, 255))
    nvgText(vg, screenW/2, panelY + panelH - 21, "点击返回主界面", nil)
end

function AppStart()
    startupSaveWaitActive = true
    startupSaveWaitTimer = 0
    startupSaveFallbackEnter = nil
    startupSaveTimeout = 5.0
    math.randomseed(os.time())
    math.random()
    math.random()
    math.random()

    GameEvents.On("scene:loading", ShowLoadingPage)
    GameEvents.On("scene:main", ShowMainMenu)
    GameEvents.On("scene:equip", ShowEquipmentPage)
    GameEvents.On("scene:attr", ShowAttributePage)
    GameEvents.On("scene:bag", ShowInventoryPage)
    GameEvents.On("scene:skill", ShowSkillPage)
    GameEvents.On("scene:rebirth", ShowRebirthPage)
    GameEvents.On("battle:start", StartGame)

    nvgContext = nvgCreate(1)
    if nvgContext == nil then
        print("ERROR: Failed to create NanoVG context")
        return
    end

    local pixelFontId = nvgCreateFont(nvgContext, "pixel", "Fonts/FusionPixel-12px-Prop-zh_hans.ttf")
    local uiFontId = nvgCreateFont(nvgContext, "misans", "Fonts/MiSans-Regular.ttf")
    if pixelFontId == -1 then
        print("ERROR: Could not load pixel font, fallback to MiSans")
        nvgCreateFont(nvgContext, "pixel", "Fonts/MiSans-Regular.ttf")
    elseif uiFontId ~= -1 then
        nvgAddFallbackFont(nvgContext, "pixel", "misans")
    end

    UpdateScreenMetrics()

    local PixelTheme = UI.Theme.ExtendTheme(UI.Theme.defaultTheme, {
        fonts = {
            { family = "sans", weights = {
                normal = "Fonts/MiSans-Regular.ttf",
                bold = "Fonts/MiSans-Regular.ttf",
            }},
            { family = "pixel", weights = {
                normal = "Fonts/FusionPixel-12px-Prop-zh_hans.ttf",
                bold = "Fonts/FusionPixel-12px-Prop-zh_hans.ttf",
            }},
            { family = "mono", weights = {
                normal = "Fonts/MiSans-Regular.ttf",
            }},
        },
        colors = {
            primary = PX.red,
            primaryHover = PX.redBright,
            primaryPressed = { 160, 30, 30, 255 },
            background = PX.bg,
            surface = PX.panelBg,
            text = PX.textWhite,
            textSecondary = PX.textGray,
            border = PX.goldDim,
        },
        componentDefaults = {
            borderRadius = 0,  -- 全局直角
        },
        components = {
            Button = { borderWidth = 1 },
            Slider = {
                borderWidth = 1,
                trackBgColor = PX.sliderTrack,
                trackFillColor = PX.sliderFill,
                thumbColor = PX.sliderThumb,
                thumbBorderWidth = 1,
                thumbBorderColor = PX.gold,
            },
        },
    })

    UI.Init({
        theme = PixelTheme,
        scale = UI.Scale.DEFAULT,
    })

    NormalizeEquipment()
    NormalizeEquipmentSettings()
    LoadLocalSnapshot()
    ShowLoadingPage("正在校验并同步存档...")

    local startupEntered = false
    local function EnterGameAfterSaveReady()
        if startupEntered then return end
        startupEntered = true
        startupSaveWaitActive = false
        startupSaveFallbackEnter = nil
        ApplyRebirthBonuses()
        StartBackgroundMusic()
        EnsureRunSkillSynergies(false)
        if ReportDailyActiveOnEnter ~= nil then
            ReportDailyActiveOnEnter()
        end
        GameEvents.Emit("scene:main")
    end

    startupSaveFallbackEnter = nil
    if KeepCloudWriteReadyIfLocalProgress("startup_local_snapshot") then
        print("[StartupSave] 已读取本地快照，先进入游戏并保持云写入开启")
    else
        print("[StartupSave] 未发现本地快照，先进入游戏；云档确认前禁止云写")
    end
    EnterGameAfterSaveReady()
    ScheduleCloudRetry("startup", true)
    SubscribeToEvent("BeginFrame", function()
        UnsubscribeFromEvent("BeginFrame")
        BeginCloudRecovery("startup_first_frame")
    end)

    SubscribeToEvent(nvgContext, "NanoVGRender", "HandleRender")
    SubscribeToEvent("Update", "HandleUpdate")
    SubscribeToEvent("MouseMove", "HandleMouseMove")
    SubscribeToEvent("MouseButtonDown", "HandleMouseDown")
    SubscribeToEvent("MouseButtonUp", "HandleMouseUp")
    SubscribeToEvent("TouchBegin", "HandleTouchBegin")
    SubscribeToEvent("TouchMove", "HandleTouchMove")
    SubscribeToEvent("TouchEnd", "HandleTouchEnd")
    SubscribeToEvent("KeyDown", "HandleKeyDown")
    SubscribeToEvent("AppWillEnterBackground", "HandleEnterBackground")
    SubscribeToEvent("AppDidEnterBackground", "HandleEnterBackground")
    SubscribeToEvent("AppWillEnterForeground", "HandleEnterForeground")
    SubscribeToEvent("AppDidEnterForeground", "HandleEnterForeground")

    StartAssetLoading()

    print("=== 暗黑割草大剑守卫 启动（像素风）===")
end

function AppStop()
    if rewardAdInFlight then
        rewardAdOnComplete = nil
        rewardAdCompleted = true
        rewardAdInFlight = false
        rewardAdDeadline = 0
        rewardAdFlowEnded = false
        rewardAdBattlePaused = false
        pendingRewardAdDeliver = nil
    end
    StartOfflineClimbIfEligible("app_stop")
    -- 退出前先结束结算期延迟保存并落盘，避免结算窗口内退出丢进度。
    if EndDeferredCloudSave ~= nil then
        EndDeferredCloudSave()
    end
    AutoSaveIfNeeded(true)
    StopBackgroundMusic()
    UI.Shutdown()
    if nvgContext ~= nil then
        nvgDelete(nvgContext)
        nvgContext = nil
    end
end

function Start()
    AppStart()
end

function Stop()
    AppStop()
end

